@php
    $timetableUser = request()->user() ?? auth()->guard('teacher')->user() ?? auth()->guard('web')->user();
    $timetableDepartmentName = trim((string) ($timetableUser->department ?? ''));
    $timetableRoles = $timetableUser->getRoleNames()->toArray();
    $timetableActiveRole = session('active_role', $timetableRoles[0] ?? '');
    if (!in_array($timetableActiveRole, $timetableRoles, true) && $timetableRoles) {
        $timetableActiveRole = $timetableRoles[0];
    }
    // Jadval administratorlari (JADVAL_ADMIN: admin, superadmin, registrator ofisi, kichik admin, o'quv bo'limi) — shu modulda teng huquqli.
    $timetableJadvalAdmin = in_array($timetableActiveRole, \App\Http\Controllers\Admin\TimetableController::TIMETABLE_FULL_EDIT_ROLES, true);
    // O'quv bo'limi endi jadval administratori — "faqat auditoriya biriktirish" rejimi hech kimga qo'llanmaydi (o'zgaruvchi qoldirilgan).
    $timetableAuditoriumAssignmentOnly = in_array($timetableActiveRole, ['oquv_bolimi', 'oquv_bolimi_boshligi'], true) && !$timetableJadvalAdmin;
    $timetableDepartmentHead = $timetableActiveRole === 'kafedra_mudiri';
    // O'qituvchi: jadvalni bevosita tahrirlamaydi, o'z darsiga vaqt taklifini yuboradi.
    $timetableReadOnly = in_array($timetableActiveRole, ['oqituvchi', 'fan_masuli'], true);
    // O'qituvchi identifikatori controllerda ikkala guard uchun bir xil aniqlanadi.
    // Fan mas'uli: "Mas'ul fanlarim" ko'rinishi (o'zi mas'ul bo'lgan fanlar)
    $timetableHasSubjects = $timetableActiveRole === 'fan_masuli';
    try {
        $timetableHasSubjects = $timetableHasSubjects || ($timetableTeacherId && \Illuminate\Support\Facades\Schema::hasTable('teacher_responsible_subjects')
            && \Illuminate\Support\Facades\DB::table('teacher_responsible_subjects')->where('teacher_id', $timetableTeacherId)->exists());
    } catch (\Throwable $e) { /* Biriktirishsiz fan mas'uli uchun ham bo'sh filtr saqlanadi. */ }
    $timetableAssignmentOnly = $timetableAuditoriumAssignmentOnly || $timetableDepartmentHead || $timetableReadOnly;
    // Joylashtirish (kafedra mudiri — ichki qatlamda o'z kafedrasi kartalari: joyi, o'qituvchisi, xonasi).
    $timetableCanPlace = $timetableActiveRole === 'kafedra_mudiri';
    // Bo'shatish va sikl kalendari ("+ qo'shish") — kartalar ro'yxati/doska sozlamasini o'zgartiradi: kafedra mudiriga yopiq.
    $timetableCanUnplace = $timetableAuditoriumAssignmentOnly;
    // Fanlar menejeri subjects/subject-setting.save ni chaqiradi — o'qituvchi, fan mas'uli va kafedra mudiriga yopiq.
    $timetableCanUseManager = $timetableAuditoriumAssignmentOnly;
    // Karta yaratish / kartalar ro'yxatini va doska sozlamasini o'zgartirish tugmalari (kartochkalar, fan nomlari, yangi doska, versiyalar,
    // KTR haftalari, bo'shatish, sikl bayramlari "+ qo'shish" va h.k.) — faqat adminlar. Cheklangan rollarda (o'qituvchi, fan mas'uli,
    // kafedra mudiri; o'quv bo'limi — bo'shatish va fanlar menejeridan tashqari) sahifaga yashirin va o'chiq chiqadi: tt-forbidden —
    // display:none !important (JS 'hidden' ni olib tashlasa ham ko'rinmaydi). Server ham 403 qaytaradi (TimetableAssignmentAccess).
    $timetableForbiddenIds = $timetableAssignmentOnly ? array_values(array_filter([
        'newBoardBtn', 'genBtn', 'refreshNamesBtn', 'mergeBolakBtn', 'delBoardBtn', 'snapshotsBtn', 'ktrWeeksBtn',
        'settingsBtn', 'managerBtn', 'excelViewBtn', 'checkBtn', 'rulesBtn',
        'unplaceBtn', 'gsSave', 'cycleHolAddBtn', 'cycleRefresh', 'cmSave', 'cmUnplace', 'cmResetWeek',
    ], fn ($id) => !($timetableCanUnplace && in_array($id, ['unplaceBtn', 'cycleHolAddBtn'], true))
        && !($timetableCanPlace && $id === 'cycleRefresh') && !($timetableCanUseManager && $id === 'managerBtn'))) : [];
    $ttForbid = fn (string $id) => in_array($id, $timetableForbiddenIds, true) ? ' tt-forbidden' : '';
    // Qamrov rejimi (Butun doska / Kafedraniki / Mas'ul fanlarim / Faqat meniki) — har foydalanuvchi va rol uchun alohida saqlanadi
    // (superadmin bir foydalanuvchidan boshqasiga o'tganda oldingi rejim qolib ketmasin): guard + id.
    $timetableUserKey = ($timetableUser instanceof \App\Models\Teacher ? 't' : 'u') . (int) ($timetableUser?->getAuthIdentifier() ?? 0);
    // O'qituvchi, fan mas'uli, kafedra mudiri, registrator ofisi, kichik admin, o'quv bo'limi: doska tanlovi bo'sh turmasin — oxirgi
    // ochilgan doska (brauzerda, JS), bo'lmasa yagona doska, bo'lmasa eng yangi (joriy) Real doska (kartalari bor). URLda berilgan — o'sha.
    $timetableAutoBoardRoles = ['oqituvchi', 'fan_masuli', 'kafedra_mudiri', 'registrator_ofisi', 'kichik_admin', 'oquv_bolimi', 'oquv_bolimi_boshligi'];
    $timetableAutoBoardId = null;
    if (in_array($timetableActiveRole, $timetableAutoBoardRoles, true) && isset($boards) && $boards->count()) {
        $withCards = fn ($b) => (int) ($b->cards_count ?? 0) > 0;
        $timetableAutoBoardId = ($boards->count() === 1 ? $boards->first() : null
            ?? $boards->first(fn ($b) => ($b->kind ?? '') === 'real' && $withCards($b)) ?? $boards->first($withCards) ?? $boards->first())->id;
    }
    // Jadval o'zgarishlarini tasdiqlovchi (registrator ofisi), so'rov yuboruvchi (kafedra mudiri)
    // va o'zgarishlar tarixini ko'ruvchilar (o'quv bo'limi, kichik admin)
    $timetableCanApprove = in_array($timetableActiveRole, \App\Services\Timetable\TimetableChangeApproval::APPROVER_ROLES, true);
    // Butun doska bo'yicha joylanmagan kartalar hisoboti (Excel) — serverdagi ruxsat bilan bir xil rollar.
    $timetableCanBoardReport = $timetableJadvalAdmin;
    $timetableUsesChangeRequests = $timetableCanApprove
        || in_array($timetableActiveRole, ['oqituvchi', 'fan_masuli', 'kafedra_mudiri', 'kichik_admin', 'oquv_bolimi', 'oquv_bolimi_boshligi'], true);
@endphp

