            .asc-nav-btn {
            position: relative;
            z-index: 50;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 0;
            width: 70px;
            min-height: 70px;
            padding: 8px;
            border: 0;
            border-radius: 10px;
            color: #475569;
            background: #fff;
            font-size: 0.78rem;
            font-weight: 600;
            text-align: left;
            transition: transform 0.22s cubic-bezier(.2,.8,.2,1), background-color 0.22s ease, color 0.22s ease, box-shadow 0.22s ease;
            outline: none;
        }
        .asc-nav-btn > span:not(.asc-nav-icon) { display: none; }
        .asc-nav-btn .asc-nav-icon { width: 54px; height: 54px; flex: 0 0 54px; }
        .asc-nav-btn { background: transparent; box-shadow: none; }
        .asc-nav-btn:focus,
        .asc-nav-btn:focus-visible { outline: none; border: 0; }
        .asc-nav-btn.active:focus,
        .asc-nav-btn.active:focus-visible { border: 2px solid #2563eb; }
        .asc-nav-btn:hover::after {
            content: attr(data-tooltip);
            position: absolute;
            left: calc(100% + 8px);
            top: 50%;
            z-index: 9999;
            transform: translateY(-50%);
            padding: 7px 10px;
            border-radius: 6px;
            background: #0f172a;
            color: #fff;
            font-size: 12px;
            font-weight: 700;
            white-space: nowrap;
            box-shadow: 0 8px 20px rgba(15,23,42,.22);
            pointer-events: none;
        }
        .asc-nav-btn:hover {
            z-index: 60;
            transform: scale(1.08);
            background: transparent;
            color: #1d4ed8;
            border-color: #bfdbfe;
        }
        .asc-nav-btn.active {
            background: linear-gradient(135deg, #2563eb, #1d4ed8);
            color: #fff;
            border: 2px solid #2563eb;
            border-color: #2563eb;
            outline: none;
            box-shadow: 0 2px 7px rgba(37, 99, 235, 0.25);
        }
        .dark .asc-nav-btn {
            color: #cbd5e1;
            background: #1e293b;
        }
        .dark .asc-nav-btn:hover {
            background: #1e3a8a;
            color: #dbeafe;
            border-color: #3b82f6;
        }
        .dark .asc-nav-btn.active {
            background: linear-gradient(135deg, #2563eb, #1d4ed8);
            color: #fff;
        }

