        .check-section-icon {
            width: 25px;
            height: 25px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            flex: 0 0 25px;
            font-size: 16px;
            border-radius: 8px;
            background: rgba(255,255,255,.75);
        }
        .check-section-title { letter-spacing: .01em; }
        .check-section-count {
            margin-left: auto;
            font-size: 11px;
            font-weight: 800;
            white-space: nowrap;
        }
        .check-section-body {
            display: grid;
            gap: 5px;
            padding: 11px 14px 12px 46px;
            color: #475569;
            font-size: 12px;
            line-height: 1.45;
        }
        .check-section-body > div {
            padding: 5px 8px;
            border-radius: 6px;
            background: #f8fafc;
        }
        .check-section-empty {
            padding: 10px 14px 11px 46px;
            color: #64748b;
            font-size: 12px;
        }


        /* ── Ixcham boshqaruv paneli: jadval uchun ko'proq joy ── */
        .tt-top-toolbar { padding: 6px 8px; gap: 8px; flex-wrap: nowrap; align-items: center; }
        .tt-board-select { flex: 0 1 300px; min-width: 200px; }
        .tt-board-select select { height: 32px; font-size: 11.5px; padding-left: 34px; }
        .tt-board-icon { width: 20px; height: 20px; left: 9px; }
        .tt-toolbar-actions { flex: 1 1 auto; flex-wrap: nowrap; gap: 4px; justify-content: flex-end; min-width: 0; }
        .tt-toolbar-actions .asc-tool, .tt-grid-field .asc-tool { min-height: 32px; padding: 0 7px; font-size: 11.5px; white-space: nowrap; }
        .tt-toolbar-actions .asc-tool:hover { transform: none; }
        /* Tor ekranda tugmalar faqat belgi (nomi — sichqoncha yo'rig'ida) */
        @media (max-width: 1900px) {
            .tt-toolbar-actions .asc-tool.toolbar-action { font-size: 0; gap: 0; padding: 0 6px; }
            .tt-toolbar-actions .asc-tool.toolbar-action .toolbar-icon { margin: 0; }
            .tt-toolbar-actions .asc-tool.toolbar-action #checkBadge,
            .tt-toolbar-actions .asc-tool.toolbar-action #rulesBadge { font-size: 10px; }
        }
        .tt-work-panel { display: flex; align-items: center; flex-wrap: wrap; }
        .tt-work-panel.mb-3 { margin-bottom: 4px; }
        .tt-top-panel.mb-1 { margin-bottom: 4px; }
        .tt-filters-row { padding: 6px 8px; gap: 6px; flex: 0 1 auto; align-items: center; }
        .tt-work-panel .tt-bottom-row { flex: 1 1 auto; }
        .tt-field > select { padding-top: 0; padding-bottom: 0; line-height: 30px; }
        .tt-field > label { display: none; }
        .tt-field .tt-dd-btn, .tt-field > select { height: 32px; min-width: 120px; font-size: 11.5px; }
        .tt-bottom-row { min-height: 0; padding: 6px 8px; border-top: 0; flex-wrap: nowrap; gap: 6px; background: transparent; }
        .tt-toggle-chip { min-height: 32px; padding: 0 9px; }
        /* Tor ekranda yuqoridagi nowrap avvalgi moslashuvchan joylashuvni bosib ketmasin:
           aks holda flex-end + nowrap tugmalarni chap chetdan ekran tashqarisiga chiqarardi. */
        @media (max-width: 1450px) {
            .tt-top-toolbar, .tt-bottom-row { flex-wrap: wrap; }
            .tt-toolbar-actions { flex-wrap: wrap; justify-content: flex-start; }
        }
        @media (max-width: 900px) {
            .tt-board-select, .tt-toolbar-actions { flex: 1 1 100%; max-width: none; }
            /* Tugmalar faqat belgi — eski 145px'lik keng tugma qoidasi ularni ko'p qatorga yoyardi */
            .tt-toolbar-actions .asc-tool { flex: 0 0 auto; }
        }
        /* Sikl paneli: kichik oraliqlar */
        #cycleArea > div:first-child { gap: 8px; padding-top: 4px; padding-bottom: 4px; }
        #cycleHolBar { padding-top: 2px; padding-bottom: 2px; }
        /* Guruh filtri ("Guruh" sarlavhasi) */
        #cycleGrid th.cyc-gfilter-th { padding: 2px 4px; }
        .cyc-gfilter-btn { max-width: calc(100% - 18px); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; border: 1px solid #cbd5e1;
            border-radius: 6px; background: #fff; padding: 2px 6px; font-size: 11px; font-weight: 700; color: #1e293b; cursor: pointer; }
        .cyc-gfilter-btn.is-on { background: #dbeafe; border-color: #60a5fa; color: #1d4ed8; }
        .cyc-gfilter-x { margin-left: 2px; border: 0; background: transparent; font-size: 15px; line-height: 1; color: #64748b; cursor: pointer; }
        #cycRowPop { position: fixed; z-index: 60; width: 230px; max-height: 360px; display: flex; flex-direction: column; background: #fff;
            border: 1px solid #cbd5e1; border-radius: 10px; box-shadow: 0 10px 30px rgba(15,23,42,.18); padding: 6px; }
        #cycRowPop .cyc-rp-q { width: 100%; height: 30px; border: 1px solid #cbd5e1; border-radius: 6px; padding: 0 8px; font-size: 12px; margin-bottom: 4px; }
        #cycRowPop .cyc-rp-list { overflow-y: auto; display: flex; flex-direction: column; }
        #cycRowPop .cyc-rp-tools { display: flex; gap: 6px; margin-bottom: 4px; }
        #cycRowPop .cyc-rp-tools button { flex: 1; border: 1px solid #cbd5e1; border-radius: 6px; background: #f8fafc; padding: 2px 6px; font-size: 11px; cursor: pointer; }
        #cycRowPop .cyc-rp-item { display: flex; align-items: center; gap: 6px; padding: 4px 8px; border-radius: 6px; font-size: 12px; cursor: pointer; }
        #cycRowPop .cyc-rp-item:hover { background: #f1f5f9; }
        #cycRowPop .cyc-rp-item.is-on { background: #dbeafe; color: #1d4ed8; font-weight: 700; }
        #cycRowPop .cyc-rp-empty { padding: 6px 8px; color: #94a3b8; font-size: 12px; }
        /* Menyu / panjara / joylashmagan kartalar orasidagi suriladigan chegaralar */
        .tt-resizer { flex: 0 0 auto; height: 7px; margin: 1px 0; cursor: row-resize; border-radius: 4px;
            background: linear-gradient(#e2e8f0, #e2e8f0) center / 48px 3px no-repeat; touch-action: none; }
        .tt-resizer:hover, .tt-resizer.dragging { background: linear-gradient(#64748b, #64748b) center / 64px 3px no-repeat, #e0e7ff; }
        body.tt-resizing, body.tt-resizing * { cursor: row-resize !important; user-select: none !important; }
        /* Saqlangan yoki surilgan balandlik oynaga sig'masa ham panel konteynerdan chiqib ketmaydi (pastki kartalari
           ko'rinmay qolmaydi): panjaraga kamida 60px qoladi, kartalar panel ichida skroll bo'ladi. */
        #ttBottomPanel { display: flex; flex-direction: column; max-height: calc(100% - 60px); }
        #ttBottomPanel > #cardPanel { min-height: 0; }
        .tt-card-sync-track { position: relative; height: 6px; overflow: hidden; border-radius: 9999px; background: #dbeafe; }
        .tt-card-sync-track span { position: absolute; inset-block: 0; width: 34%; border-radius: inherit; background: #2563eb;
            animation: tt-card-sync-slide 1.15s ease-in-out infinite; }
        @keyframes tt-card-sync-slide { from { left: -34%; } to { left: 100%; } }
        /* "Butun doska (Excel)" hisoboti oynasidagi progress — o'z klassi (Tailwind build'iga bog'liq emas); xatoda qizil */
        .tt-report-track { height: 10px; overflow: hidden; border-radius: 9999px; background: #e5e7eb; }
        .tt-report-bar { height: 100%; width: 0; background: #10b981; transition: width .3s; }
        .tt-report-bar.is-error { background: #ef4444; }
</style>

    <style>
        .tt-info-only { opacity: .68; background-image: repeating-linear-gradient(135deg, transparent, transparent 7px, rgba(100,116,139,.12) 7px, rgba(100,116,139,.12) 9px) !important; }
        .tt-info-only-overlap { color: #854d0e; background: #fef9c3; font-size: 10px; padding: 2px 4px; }
        .tt-info-only-badge { display: inline-block; font-size: 9px; line-height: 1.25; color: #475569; background: #f1f5f9; border-radius: 3px; padding: 1px 3px; margin: 1px 2px; }
        #ttAgendaModal .ag-e.tt-info-only { background-color: #f1f5f9; color: #64748b; }
    </style>
    <script>
        (function () {
            const BOARDS_STORE = @json(route('admin.timetable.boards.store'));
            const BASE = @json(url('admin/dars-jadvali-tuzish'));
            const TEACHERS_URL = @json(route('admin.timetable.teachers'));
            const TEACHER_DEPARTMENTS_URL = @json(route('admin.timetable.teachers.departments'));
            const AUDS_URL = @json(route('admin.timetable.auditoriums'));
            const CSRF = @json(csrf_token());
            // HEMIS'ga yozish xatcho'pi (bookmarklet) yuklaydigan skript.
            const HS_WRITER_URL = @json(asset('js/hemis-writer.js'));
            const TIMETABLE_ASSIGNMENT_ONLY = @json($timetableAssignmentOnly);
            const TIMETABLE_AUDITORIUM_ASSIGNMENT_ONLY = @json($timetableAuditoriumAssignmentOnly);
            const TIMETABLE_CAN_PLACE = @json($timetableCanPlace);
            const TIMETABLE_CAN_UNPLACE = @json($timetableCanUnplace);
            const TIMETABLE_FORBIDDEN_IDS = @json($timetableForbiddenIds);
            const TIMETABLE_AUTO_BOARD_ID = @json($timetableAutoBoardId);
            const TIMETABLE_READ_ONLY = @json($timetableReadOnly);
            const TIMETABLE_CAN_APPROVE = @json($timetableCanApprove);
            const TIMETABLE_ROLE = @json($timetableActiveRole);
            // Haftalik jadval qatlami (sikl kabi): tashqi — o'quv bo'limi, ichki — kafedra mudiri; ikkalasi — to'liq tahrirlovchilar (server bilan
            // bitta ro'yxat: TIMETABLE_FULL_EDIT_ROLES). Sikl ko'rinishida tahrir — server bergan can_edit bo'yicha.
            const WEEKLY_ADMIN = @json(\App\Http\Controllers\Admin\TimetableController::TIMETABLE_FULL_EDIT_ROLES).includes(TIMETABLE_ROLE);
            // "Takliflar" oynasi: qaysi rollarga ochiq (qamrov va "Qo'llash" huquqini server beradi).
            const SUGGEST_ROLES = ['admin', 'superadmin', 'registrator_ofisi', 'kichik_admin', 'oquv_bolimi', 'oquv_bolimi_boshligi', 'kafedra_mudiri', 'fan_masuli', 'oqituvchi'];
            const WEEKLY_OQUV = ['oquv_bolimi', 'oquv_bolimi_boshligi'].includes(TIMETABLE_ROLE);
            let weeklyLayer = WEEKLY_OQUV ? 'external' : 'internal';
            try { const v = localStorage.getItem('lms:timetable-weekly-layer'); if (v === 'external' || v === 'internal') weeklyLayer = v; } catch (e) { }
            const weeklyCanEdit = () => !TIMETABLE_READ_ONLY && (WEEKLY_ADMIN || (weeklyLayer === 'external' ? WEEKLY_OQUV : TIMETABLE_ROLE === 'kafedra_mudiri'));
            // Kurs va fan bo'yicha ma'lumot rejimi (serverdagi InfoOnlyCourses sozlamasi).
            function isHemisExcluded(card) {
                if (!card) return false;
                const configured = board && board.settings && board.settings.info_only_courses;
                return (Array.isArray(configured) ? configured : [6]).map(Number).includes(+card.course);
            }
            function normalizeInfoSubject(name) {
                return String(name || '').replace(/[’‘ʻʼ`´‛＇]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase();
            }
            function infoSubjectMatch(card) {
                const configured = board && board.settings && board.settings.info_only_subjects;
                const name = normalizeInfoSubject(card && (card.subject_name || card.subject));
                return (Array.isArray(configured) ? configured : ["O'quv amaliyoti"])
                    .find(label => normalizeInfoSubject(label) && name.includes(normalizeInfoSubject(label))) || '';
            }
            function isNonBlocking(card) { return !!card && (isHemisExcluded(card) || !!infoSubjectMatch(card)); }
            function infoOnlyText(card) {
                if (isHemisExcluded(card)) return (+card.course) + '-kurs · ma’lumot (onlayn)';
                const subject = infoSubjectMatch(card);
                return subject ? subject + ' · nazorat' : '';
            }
            function infoOnlyBadgeHtml(card) {
                const text = infoOnlyText(card);
                return text ? '<span class="tt-info-only-badge">' + esc(text) + '</span>' : '';
            }
            function infoOnlyClass(card) { return isNonBlocking(card) ? ' tt-info-only' : ''; }
            function cycleInfoCard(row, block) { return { course: row.course, subject_name: block.subject }; }
            function infoOnlyGroupOverlapHtml(list) {
                const online = list.filter(isNonBlocking);
                const overlaps = online.some((a, i) => online.some((b, j) => j > i && a.id !== b.id
                    && !bolakSiblings(a, b) && (curWeek || weeksIntersect(a, b))));
                return overlaps ? '<div class="tt-info-only-overlap">Ma’lumot: guruhning ma’lumot darslari ustma-ust</div>' : '';
            }
            function cycleInfoOverlapHtml(row, block) {
                const card = cycleInfoCard(row, block);
                if (!isNonBlocking(card)) return '';
                return '<div class="tt-info-only-overlap">Ma’lumot: guruhning ma’lumot darslari ustma-ust — '
                    + '<button type="button" data-cycle-gear="' + esc(block.key) + '">' + esc(block.subject) + '</button> '
                    + infoOnlyBadgeHtml(card) + '</div>';
            }
            function hemisInfoNoticeHtml(rep) {
                return (rep.info_only_notice ? '<div class="text-xs text-gray-500 my-2">' + hsEsc(rep.info_only_notice) + '</div>' : '')
                    + (rep.warnings || []).map(w => '<div class="text-xs text-amber-700 my-2">' + hsEsc(w) + '</div>').join('');
            }
            // Kartani tanlangan qatlamga moslaydi: tashqida joylashuv ext_day/ext_pair, o'qituvchi va xona yashiriladi.
            function applyWeeklyLayer(list) {
                list.forEach(c => {
                    if (!c._int) c._int = { day: c.day, pair: c.pair, teacher_id: c.teacher_id, teacher_name: c.teacher_name,
                        auditorium_code: c.auditorium_code, auditorium_name: c.auditorium_name, auditorium_volume: c.auditorium_volume };
                    if (weeklyLayer === 'external') {
                        Object.assign(c, { day: c.ext_day || null, pair: c.ext_pair || null, teacher_id: null, teacher_name: null,
                            auditorium_code: null, auditorium_name: null, auditorium_volume: null });
                    } else {
                        Object.assign(c, c._int);
                    }
                });
            }
            const TIMETABLE_TEACHER_ID = @json($timetableTeacherId);
            const TIMETABLE_DEPARTMENT_HEAD = @json($timetableDepartmentHead);
            const TIMETABLE_HAS_SUBJECTS = @json((bool) $timetableHasSubjects);
            let mySubjectCardIds = new Set();   // "Mas'ul fanlarim": serverdan (data.my_subject_card_ids)
            // Fan mas'uli "Joylash uchun tanlash": { card (birlikning birinchi bo'lagi), week, data (responsible-move/grid javobi), error }.
            let fmPick = null;
            const fmGridCache = new Map();   // "karta|hafta" => grid javobi (doska qayta yuklanganda va joylangandan keyin tozalanadi)
            let fmDragCard = null;           // paneldan sudralayotgan mas'ul fan kartasi (tashlansa — tasdiq oynasi, darhol yozilmaydi)
            let fmOwnOnly = true;            // "Faqat shu guruh": rejimda faqat kartaning fakulteti / yo'nalishi / kursi ustunlari (sukut — yoqiq)
            // "Faqat meniki": faqat o'qituvchiga biriktirilgan kartalar/sikl bloklari ko'rinadi.
            // Ko'rinish qamrovi: 'all' — butun doska, 'kafedra' — kafedra mudirining o'z kafedrasi
            // fanlari, 'mine' — faqat o'ziga biriktirilganlar. mineOnly = qamrov toraytirilgan.
            // O'qituvchi / fan mas'uli: sukut — o'qituvchi kesimi, "Faqat meniki" (fan mas'uli — "Mas'ul fanlarim"), joriy hafta,
            // o'z darslari bor barcha fakultet, yo'nalish va kurslar.
            const TEACHER_DEFAULTS = ['oqituvchi', 'fan_masuli'].includes(TIMETABLE_ROLE) && Boolean(TIMETABLE_TEACHER_ID);
            const DEFAULT_VIEW = TEACHER_DEFAULTS ? 'teacher' : 'group';
            // Qamrov rejimi: kalit — foydalanuvchi (guard + id) va rol (lms:timetable-scope:{user}:{rol}); saqlangan qiymat bo'lmasa —
            // rol sukuti: o'qituvchi — "Faqat meniki", fan mas'uli — "Mas'ul fanlarim", kafedra mudiri — "Kafedraniki", adminlar — "Butun doska".
            const TIMETABLE_USER_KEY = @json($timetableUserKey);
            const SCOPE_KEY = 'lms:timetable-scope:' + TIMETABLE_USER_KEY + ':' + TIMETABLE_ROLE;
            // Oxirgi ochilgan doska (shu foydalanuvchi va rol) — sahifa URLsiz ochilganda shu doska tanlanadi.
            const LAST_BOARD_KEY = 'lms:timetable-last-board:' + TIMETABLE_USER_KEY + ':' + TIMETABLE_ROLE;
            // O'qituvchi, fan mas'uli va kafedra mudiri: /data server tomonda rol doirasida (butun doska emas) — rejim almashsa qayta yuklanadi.
            const TIMETABLE_SCOPED_DATA = ['oqituvchi', 'fan_masuli', 'kafedra_mudiri'].includes(TIMETABLE_ROLE);
            const scopeAllowed = m => m === 'all' || (m === 'mine' && +TIMETABLE_TEACHER_ID > 0) || (m === 'kafedra' && !!TIMETABLE_DEPARTMENT_HEAD)
                || (m === 'subjects' && !!TIMETABLE_HAS_SUBJECTS);
            const ROLE_DEFAULT_SCOPE = { oqituvchi: 'mine', fan_masuli: 'subjects', kafedra_mudiri: 'kafedra' }[TIMETABLE_ROLE] || 'all';
            let scopeMode = scopeAllowed(ROLE_DEFAULT_SCOPE) ? ROLE_DEFAULT_SCOPE : (TIMETABLE_SCOPED_DATA && scopeAllowed('mine') ? 'mine' : 'all');
            try {
                const saved = localStorage.getItem(SCOPE_KEY);
                if (['all', 'mine', 'subjects', 'kafedra'].includes(saved) && scopeAllowed(saved)) scopeMode = saved;
            } catch (e) { }
            let mineOnly = scopeMode !== 'all';
            let myKafedras = [];
            const kafedraNorm = v => String(v || '').toLowerCase().trim().replace(/\s*kafedra(si)?\s*$/u, '').replace(/[^\p{L}\p{N}]+/gu, '');
            function scopeModeLabel() {
                return { all: 'Butun doska', kafedra: 'Kafedraniki', subjects: "Mas'ul fanlarim", mine: 'Faqat meniki' }[scopeMode] || '';
            }
            function scopeCards(list) {
                if (scopeMode === 'mine') return list.filter(c => +c.teacher_id === +TIMETABLE_TEACHER_ID);
                if (scopeMode === 'subjects') return list.filter(c => mySubjectCardIds.has(+c.id));
                if (scopeMode === 'kafedra') {
                    const keys = new Set(myKafedras.map(kafedraNorm).filter(Boolean));
                    return list.filter(c => keys.has(kafedraNorm(c.kafedra_name)));
                }
                return list;
            }
            let allCards = [];
            let groupStudents = {};   // "fakultet|guruh" => faol talabalar soni (sikl jadvalidagi kabi)
            const TIMETABLE_CAN_USE_MANAGER = @json($timetableCanUseManager);
            const DAY_NAMES = ['Dushanba', 'Seshanba', 'Chorshanba', 'Payshanba', 'Juma', 'Shanba', 'Yakshanba'];

            let board = null;      // {id, days, pairs_per_day, ...}
            let cards = [];        // barcha kartochkalar
            let grids = {};        // "faculty|specialty|course" => {days, pairs_per_day, weeks}
            let specList = [];     // [{key, specialty_name, course}]
            let curSpec = null;    // tanlangan {specialty_name, course} (asosiy/primary)
            // Ko'p tanlovli qamrov (dropdown checkboxlari) — bir nechta fakultet/yo'nalish/kurs
            let selectedFaculties = new Set();
            let selectedDirs = new Set();
            let selectedCourses = new Set();
            let groupRows = [];    // [{oqim_label, lang, group}]
            let flowStudents = {}; // fakultet|yo'nalish|kurs|oqim => talabalar soni
            let selected = null;   // tanlangan karta (obyekt)
            let audCache = null;
            let modalCard = null;
            let overrides = {};    // "cardId|week" => {day, pair, cancelled, auditorium_*}
            let missingGroups = []; // rejada fani bor, lekin guruh proyeksiyasi yo'q yo'nalish+kurslar
            let subjectSettings = {};  // "spec|course|subject" => {mode, season, rotation_group, occurrences, cycle_days}
            let autoCycleBackup = null;
            let autoCycleApplied = false;
            let cycleGroupFilter = '';
            let cycleCfFilter = '';   // sikl paneli: faqat shu turdagi to'qnashuvli kartalar ('teacher' | 'room' | '')
            const SUBJ_MODE_LABELS = { normal: 'Har hafta', alternate: 'Hafta almashinuvi', cycle: 'Sikl (blok)' };
            const SUBJ_SEASON_LABELS = { kuzgi: 'Kuzgi', bahorgi: 'Bahorgi' };
            // Fan-rejim kaliti — katta-kichik harf/bo'shliqqa befarq (reja nomi
            // "Davolash ishi", karta nomi "davolash ishi" bo'lishi mumkin).
            const gridKey = (faculty, spec, course, curriculum = 0) =>
                String(faculty || '').trim() + '|' + String(spec || '').trim() + '|' + course + '|' + (+curriculum || 0);
            const gridForCard = c => grids[gridKey(c.faculty_name || c.faculty || '', c.specialty_name || c.specialty, c.course, c.curriculum_hemis_id)]
                || grids[gridKey(c.faculty_name || c.faculty || '', c.specialty_name || c.specialty, c.course)]
                || grids[gridKey('', c.specialty_name || c.specialty, c.course)]
                || { days: board.days, pairs_per_day: board.pairs_per_day, weeks: board.weeks };
            const subjModeKey = (spec, course, subject) =>
                String(spec || '').trim().toLowerCase() + '|' + course + '|' + String(subject || '').trim().toLowerCase();
            let curWeek = 0;       // 0 = barcha haftalar (shablon); 1..N = alohida hafta
            // Doska va ko'rinish tanlovlari (fakultet/yo'nalish/kurs, dars turi, hafta, kesim)
            // URLda saqlanadi — F5 bosilganda yoki havola ochilganda aynan shu doska va
            // shu ko'rinishga qaytamiz (doskadan chiqib ketmaymiz).
            let pendingView = parseViewFromUrl();

            const $ = id => document.getElementById(id);
            const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
            const subjectSettingOf = row => subjectSettings[subjModeKey(row.specialty_name, row.course, row.subject_name)] || {};
            const subjectSeasonOf = row => subjectSettingOf(row).season || row.season || (board && board.semester_parity) || 'kuzgi';
            const subjectSeasonLabel = season => SUBJ_SEASON_LABELS[season] || season || 'Kuzgi';
            const subjectSemesterLabel = row => row.semester_label || (row.semester ? (row.semester + '-semestr') : 'вЂ”');
            const subjectSeasonOptionLabel = (row, season) => subjectSemesterLabel(row) + ' (' + subjectSeasonLabel(season) + ')';
            const subjectSeasonOptionsHtml = (row, season) => Object.keys(SUBJ_SEASON_LABELS).map(value =>
                '<option value="' + value + '"' + (season === value ? ' selected' : '') + '>' + esc(subjectSeasonOptionLabel(row, value)) + '</option>').join('');
            const subjectSeasonBadgeText = (row, season = subjectSeasonOf(row)) => {
                const semester = row.semester_label || (row.semester ? (row.semester + '-semestr') : '—');
                return semester + ' (' + subjectSeasonLabel(season) + ')';
            };
            const repaintSubjectSeason = (tr, row, season) => {
                const select = tr.querySelector('.asc-subj-season');
                if (select) {
                    syncSubjectSeasonSelect(tr, row, season);
                    select.value = season || '';
                }
            };
            function subjectSeasonSemesterLabel(row, season = subjectSeasonOf(row)) {
                const base = Number.parseInt(row.semester, 10);
                if (!Number.isFinite(base) || base <= 0) return row.semester_label || '-';
                const boardSeason = (board && board.semester_parity) || 'kuzgi';
                if (season === boardSeason) return base + '-semestr';
                return (boardSeason === 'kuzgi' ? (base + 1) : Math.max(1, base - 1)) + '-semestr';
            }
            function syncSubjectSeasonSelect(tr, row, season = subjectSeasonOf(row)) {
                const select = tr.querySelector('.asc-subj-season');
                if (!select) return;
                select.innerHTML = Object.keys(SUBJ_SEASON_LABELS).map(value =>
                    '<option value="' + value + '"' + (season === value ? ' selected' : '') + '>'
                    + esc(subjectSeasonSemesterLabel(row, value) + ' (' + subjectSeasonLabel(value) + ')')
                    + '</option>').join('');
            }

            function applyTimetableAccess() {
                if (!TIMETABLE_ASSIGNMENT_ONLY) return;

                // Karta yaratish / kartalar ro'yxatini o'zgartirish (kartochkalar, fan nomlari, yangi doska, versiyalar, KTR haftalari,
                // bo'shatish, sikl bayramlari) — faqat adminlar; ro'yxat serverda ($timetableForbiddenIds), sahifaga ham yashirin chiqadi.
                // tt-forbidden — display:none !important: boshqa kod 'hidden' ni olib tashlasa ham ko'rinmaydi. Server ham 403 qaytaradi.
                TIMETABLE_FORBIDDEN_IDS.forEach(id => {
                    const el = $(id);
                    if (!el) return;
                    el.disabled = true;
                    el.classList.add('hidden');
                    el.classList.add('tt-forbidden');
                    el.title = 'Bu amal faqat jadval administratoriga ochiq';
                });

                if (TIMETABLE_READ_ONLY) {
                    ['assignBtn', 'unplacedExportBtn', 'subjectColorsBtn', 'cycleAllowOverlap', 'cycleIgnoreGap'].forEach(id => {
                        const el = $(id);
                        if (!el) return;
                        el.disabled = true;
                        (el.closest('label') || el).classList.add('hidden');
                    });
                    return;
                }
                const assignButton = $('assignBtn');
                if (assignButton) {
                    assignButton.disabled = false;
                    assignButton.title = TIMETABLE_AUDITORIUM_ASSIGNMENT_ONLY
                        ? 'Auditoriyalarni biriktirish'
                        : 'Fanlarni o\'qituvchilarga biriktirish';
                }
            }
            function applyAscRoleAccess() {
                if (!TIMETABLE_CAN_USE_MANAGER) return;
                document.querySelectorAll('.asc-nav-btn').forEach(btn => {
                    const allowed = btn.dataset.ascType === 'subjects';
                    btn.classList.toggle('hidden', !allowed);
                    btn.disabled = !allowed;
                    btn.tabIndex = allowed ? 0 : -1;
                });
            }

            applyTimetableAccess();
            applyAscRoleAccess();
            // Ixcham panelda tugma nomi yashiriladi — u sichqoncha yo'rig'ida ko'rinsin.
            document.querySelectorAll('.tt-toolbar-actions .toolbar-action').forEach(btn => {
                const label = btn.textContent.replace(/\s+/g, ' ').trim();
                if (!label) return;
                if (!btn.title) btn.title = label;
                else if (!btn.title.startsWith(label)) btn.title = label + ' — ' + btn.title;
                btn.setAttribute('aria-label', label);
            });

            // Jadvallarni sichqoncha bilan ushlab chap-o'ngga siljitish.
            document.querySelectorAll('[data-drag-scroll]').forEach(el => {
                let startX = 0;
                let startScroll = 0;
                let moved = false;

                el.addEventListener('pointerdown', e => {
                    if (e.button !== 0 || ascType === 'auditoriums') return;
                    if (e.target.closest?.('#asgTable tbody tr, #asgAudTable tbody tr, #asgTable thead, #asgAudTable thead, button, input, select, textarea, a, label')) return;
                    startX = e.clientX;
                    startScroll = el.scrollLeft;
                    moved = false;
                    el.classList.add('is-dragging');
                    el.setPointerCapture?.(e.pointerId);
                });
                el.addEventListener('pointermove', e => {
                    if (!el.classList.contains('is-dragging')) return;
                    const dx = e.clientX - startX;
                    if (Math.abs(dx) > 4) moved = true;
                    el.scrollLeft = startScroll - dx;
                    if (moved) e.preventDefault();
                });
                const stopDrag = () => {
                    el.classList.remove('is-dragging');
                    if (moved) {
                        el.dataset.dragged = '1';
                        setTimeout(() => { el.dataset.dragged = '0'; }, 0);
                    }
                };
                el.addEventListener('pointerup', stopDrag);
                el.addEventListener('pointercancel', stopDrag);
                el.addEventListener('click', e => {
                    if (el.dataset.dragged === '1') {
                        e.preventDefault();
                        e.stopPropagation();
                        el.dataset.dragged = '0';
                    }
                }, true);
            });

            // ===== Fan rangi (aSc Timetables uslubida) =====
            // FAQAT amaliy (praktik) darslar fan bo'yicha o'ziga xos rangda
            // bo'yaladi; ma'ruza ([M]) o'zining sariq rangida qoladi. Ranglar
            // doskaning barcha fanlari alfavit tartibida oltin burchak (137.5°)
            // bo'yicha teng taqsimlanadi — qo'shni fanlar bir-biridan ajraladi
            // va bir fan hamma joyda (panel, panjara, Excel) bir xil rangda.
            // HSL emas, HEX ishlatiladi — Excel (.xls) HTML importi hsl() ni
            // tushunmaydi, hex esa brauzerda ham, Excelda ham bir xil chiqadi.
            let subjectColors = {};
            function hslToHex(h, s, l) {
                s /= 100; l /= 100;
                const k = n => (n + h / 30) % 12;
                const a = s * Math.min(l, 1 - l);
                const f = n => {
                    const c = l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
                    return Math.round(255 * c).toString(16).padStart(2, '0');
                };
                return '#' + f(0) + f(8) + f(4);
            }
            // Rang fanning asosiy nomiga beriladi ("Fan (a)/(b)/(c)" — bitta rang) va avvalo
            // EKRANDAGI qamrov fanlari orasida taqsimlanadi: butun doskada yuzlab fan bo'lgani uchun
            // ranglar bir-biriga yaqinlashib qolardi (masalan Patologik anatomiya va Umumiy xirurgiya).
            // Qamrovdagi 10–20 fanga oltin burchak bilan tarqatilgan rang + navbatlanuvchi yorqinlik.
            function buildSubjectColors(scopeCards) {
                const bolakM = n => /^(.*?)\s*\((\p{L})\)\s*$/u.exec(String(n).trim());
                const baseOf = n => { const m = bolakM(n); return (m ? m[1] : String(n)).trim().toLowerCase(); };
                const allNames = [...new Set(cards.map(c => c.subject_name).filter(Boolean))];
                const scopeNames = [...new Set((scopeCards || cards).map(c => c.subject_name).filter(Boolean))];
                const order = [];
                const pushBases = names => [...new Set(names.map(baseOf))].sort((a, b) => a.localeCompare(b, 'uz'))
                    .forEach(b => { if (!order.includes(b)) order.push(b); });
                pushBases(scopeNames);
                pushBases(allNames);
                // Birinchi 11 fan — bir-biridan aniq farq qiladigan tayyor ranglar (qo'shnilari
                // ataylab uzoq: qizil, havorang, yashil, binafsha...). Sariq yo'q — u ma'ruzaniki.
                const PALETTE = [
                    ['#fecaca', '#dc2626'], ['#a5f3fc', '#0891b2'], ['#d9f99d', '#65a30d'], ['#ddd6fe', '#7c3aed'],
                    ['#fed7aa', '#ea580c'], ['#bfdbfe', '#2563eb'], ['#fbcfe8', '#db2777'], ['#a7f3d0', '#059669'],
                    ['#e7e5e4', '#57534e'], ['#c7d2fe', '#4338ca'], ['#99f6e4', '#0d9488'],
                ];
                const GOLDEN = 137.508;
                subjectColors = {};
                const colorOf = {};
                order.forEach((b, i) => {
                    colorOf[b] = i < PALETTE.length
                        ? { bg: PALETTE[i][0], border: PALETTE[i][1] }
                        : (h => ({ bg: hslToHex(h, [74, 60, 82][i % 3], [85, 90, 81][i % 3]), border: hslToHex(h, 64, 40) }))(Math.round((i * GOLDEN + 18) % 360));
                });
                [...new Set([...allNames, ...scopeNames])].forEach(n => { subjectColors[n] = { ...colorOf[baseOf(n)] }; });
            }
            // Rang qamrovi — ekranda ko'rinib turganlar: sikl ko'rinishida sikl bloklari (specCards ularni
            // chiqarib tashlaydi), aks holda tanlangan yo'nalish/kurs kartalari.
            function colorScopeCards() {
                if (viewMode === 'cycle' && cyclePlanData && Array.isArray(cyclePlanData.cycle_cards)) {
                    return cyclePlanData.cycle_cards.map(c => ({ subject_name: c.subject }));
                }
                return specCards();
            }
            // Foydalanuvchi tanlagan ranglar doska sozlamalarida saqlanadi va
            // avtomatik (golden-angle) rangdan ustun turadi.
            let subjectColorOverrides = {};
            function loadSubjectColorOverrides() {
                const stored = (board && board.settings && board.settings.subject_colors) || {};
                subjectColorOverrides = (stored && typeof stored === 'object') ? { ...stored } : {};
            }
            async function saveSubjectColorOverrides() {
                if (!board) return;
                const settings = { ...(board.settings || {}), subject_colors: subjectColorOverrides };
                await api(BASE + '/boards/' + board.id + '/subject-colors', 'POST', {
                    subject_colors: JSON.stringify(subjectColorOverrides),
                });
                board.settings = settings;
            }
            // Fon rangidan mos chegara rangi: bir xil tusda, to'yingan va qoraroq.
            function borderFromBg(hex) {
                const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || ''));
                if (!m) return '#94a3b8';
                const n = parseInt(m[1], 16);
                const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map(v => v / 255);
                const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min;
                let h = 0;
                if (d) {
                    if (max === r) h = ((g - b) / d + (g < b ? 6 : 0));
                    else if (max === g) h = (b - r) / d + 2;
                    else h = (r - g) / d + 4;
                    h *= 60;
                }
                return hslToHex(Math.round(h), 62, 45);
            }
            const subjColor = name => {
                const custom = subjectColorOverrides[name];
                if (custom) return { bg: custom, border: borderFromBg(custom) };
                const color = subjectColors[name] || { bg: '#f1f5f9', border: '#94a3b8' };
                return { ...color };
            };
            // Ma'ruza — bir xil sariq (class'dagi tt-lec/.lec fonida qoladi,
            // inline rang bermaymiz). Amaliy — har fan o'z rangida.
            const subjStyle = c => {
                if (c.training_type === 'lecture') return '';
                const s = subjColor(c.subject_name);
                return 'background-color:' + s.bg + ';border-left-color:' + s.border + ';';
            };

            // So'rov tanasi PHP uslubida: oddiy massiv — key[]=..., obyektlar massivi — key[0][op]=... (Takliflar actions va b.),
            // obyekt — key[field]=...; aks holda obyekt "[object Object]" satri bo'lib ketadi (actions.0.op 422).
            function appendFormValue(fd, key, v) {
                if (v === undefined || v === null) return;
                if (Array.isArray(v)) {
                    v.forEach((x, i) => {
                        if (x !== null && typeof x === 'object' && !(typeof Blob !== 'undefined' && x instanceof Blob)) appendFormValue(fd, key + '[' + i + ']', x);
                        else if (x !== undefined && x !== null) fd.append(key + '[]', x);
                    });
                    return;
                }
                if (typeof v === 'object' && !(typeof Blob !== 'undefined' && v instanceof Blob)) {
                    Object.entries(v).forEach(([k2, v2]) => appendFormValue(fd, key + '[' + k2 + ']', v2));
                    return;
                }
                fd.append(key, v);
            }
            // opts.timeout (ms) — shu vaqtda javob kelmasa so'rov to'xtatiladi: xato status 'timeout' bilan (gateway 504 ni kutmasdan).
            async function api(url, method = 'GET', body = null, opts = {}) {
                // Doska ma'lumoti tez o'zgaradi — brauzer eski GET javobini keshdan bermasin.
                const opt = { method, cache: 'no-store', headers: { 'Accept': 'application/json' } };
                if (body) {
                    const fd = new FormData();
                    fd.append('_token', CSRF);
                    Object.entries(body).forEach(([k, v]) => appendFormValue(fd, k, v));
                    opt.body = fd;
                }
                let timer = null, timedOut = false;
                // opts.signal — chaqiruvchi to'xtatadi (masalan o'qituvchi jadvalidagi oldindan yuklash: yangisi eskisini to'xtatadi).
                if ((opts.timeout || opts.signal) && typeof AbortController === 'function') {
                    const ac = new AbortController();
                    opt.signal = ac.signal;
                    if (opts.timeout) timer = setTimeout(() => { timedOut = true; ac.abort(); }, opts.timeout);
                    if (opts.signal) {
                        if (opts.signal.aborted) ac.abort(); else opts.signal.addEventListener('abort', () => ac.abort(), { once: true });
                    }
                }
                let r;
                try {
                    r = await fetch(url, opt);
                } catch (e) {
                    if (e && e.name === 'AbortError') {
                        const byCaller = !timedOut && opts.signal && opts.signal.aborted;
                        const err = new Error(byCaller ? 'So‘rov to‘xtatildi.' : 'Server javob bermadi (vaqt tugadi).');
                        err.status = byCaller ? 'aborted' : 'timeout';
                        throw err;
                    }
                    throw e;
                } finally {
                    clearTimeout(timer);
                }
                const j = await r.json().catch(() => ({}));
                if (!r.ok) {
                    // Javob tanasi ham xatoda: masalan 409 needs_confirm — "Baribir biriktirish" so'rovi.
                    const err = new Error(j.error || (j.errors ? Object.values(j.errors).flat().join(' · ') : j.message) || ('HTTP ' + r.status));
                    err.status = r.status;
                    err.data = j;
                    throw err;
                }
                if (j && j.pending_approval) onPendingApproval(j);
                // Server ogohlantirishi (masalan o'qituvchi/xona shu sanada sikl darsida band) — joylash bajarildi.
                if (j && Array.isArray(j.warnings) && j.warnings.length) {
                    ttToast('<b>&#9888; Ogohlantirish</b>' + j.warnings.map(w => '<div>' + esc(w) + '</div>').join(''), 'warn');
                }
                return j;
            }

            // ===== Jadval o'zgarishlari: tarix va registrator ofisi tasdig'i =====
            // Kafedra mudiri o'zgartirganda server o'zgarishni qo'llamaydi, so'rov qilib saqlaydi
            // (pending_approval). Ekrandagi "oldindan" ko'chirilgan holat serverdan qayta yuklanadi.
            // Tasdiqsiz qo'llangan o'zgarishlar ham serverda yoziladi — "Tarix" bo'limi o'chmaydi.
            let changeReqs = { requests: [], approval_required: false, can_approve: false };
            let changeHistory = { rows: [], more: false, loading: false };
            let changeReqFilter = 'pending';
            let pendingReloadTimer = null;
            const CR_STATUS = { pending: ['Kutilmoqda', '#b45309', '#fef3c7'], approved: ['Tasdiqlandi', '#047857', '#d1fae5'],
                rejected: ['Rad etildi', '#b91c1c', '#fee2e2'], failed: ['Qo\'llanmadi', '#b91c1c', '#fee2e2'], cancelled: ['Bekor qilindi', '#475569', '#e2e8f0'],
                applied: ['Kiritildi', '#1d4ed8', '#dbeafe'], expired: ['Muddati o\'tgan', '#92400e', '#fde68a'] };
            function ttToast(html, tone) {
                let box = document.getElementById('ttToastBox');
                if (!box) { box = document.createElement('div'); box.id = 'ttToastBox'; document.body.appendChild(box); }
                const t = document.createElement('div');
                t.className = 'tt-toast ' + (tone || '');
                t.innerHTML = html;
                box.appendChild(t);
                setTimeout(() => { t.classList.add('out'); setTimeout(() => t.remove(), 400); }, 6500);
            }
            // Umumiy qoida (barcha tugmalar): pending_approval — server xabari ("So'rov … yuborildi") va so'rov raqami (№…), so'rovlar ro'yxati
            // qayta yuklanadi; tugma egasi qatorda "tasdiq kutilmoqda" ko'rsatadi (masalan unitFixPending).
            function pendingApprovalText(j) {
                return (j && j.message ? j.message : "So'rov tasdiqqa yuborildi.") + (j && j.change_request_id ? ' (№' + j.change_request_id + ')' : '');
            }
            function onPendingApproval(j) {
                ttToast('<b>&#9203; Tasdiqqa yuborildi</b><div>' + esc(j.summary || '') + '</div><div class="tt-toast-sub" data-pending-msg>' + esc(pendingApprovalText(j)) + '</div>', 'warn');
                clearTimeout(pendingReloadTimer);
                pendingReloadTimer = setTimeout(async () => {
                    if (!board) return;
                    await loadChangeRequests();
                    try {
                        if (viewMode === 'cycle') await loadCyclePlan();
                        else await loadBoard(board.id);
                    } catch (e) { }
                }, 300);
            }
            function pendingReqs() { return (changeReqs.requests || []).filter(r => r.status === 'pending'); }
            // Kutilayotgan so'rov bosqichi: o'qituvchi / fan mas'uli so'rovi avval kafedra mudirida, keyin (va kafedra mudiri so'rovi) — registratorda.
            function crStageText(r) { return r && r.approval_stage === 'department' ? 'Kafedra mudiri tasdig‘ida' : 'Registrator ofisi tasdig‘ida'; }
            // Sikl kun oynasi: shu guruhcha va sanadagi amaliy darsga kutilayotgan vaqt so'rovi (cycle-practice-starts).
            // Ko'p kunli so'rov (payload.dates) — aynan shu sanalar; ma'ruza so'rovi (training_type = lecture) — oqimdagi barcha guruhchalar.
            function pendingPracticeAsk(card, iso) {
                if (!card || !iso) return null;
                return pendingReqs().find(r => r.route === 'admin.timetable.cycle-practice-starts' && r.payload
                    && r.payload.subject_name === card.subject
                    && (r.payload.group_name === card.group || (r.payload.units || []).includes(card.group))
                    && ((r.payload.dates || []).length ? r.payload.dates.includes(iso)
                        : (r.payload.date === iso || (r.payload.scope === 'rest' && iso > r.payload.date)))) || null;
            }
            // "Vaqtini o'zgartirishni so'rash": o'qituvchi yoki fan mas'uli, server ruxsat bergan (o'z darsi / mas'ul fani), ertadan.
            // kind: practice — amaliy (shu guruhcha), lecture — ma'ruza (butun oqim).
            function cycCanAsk(card, dp, date, today, kind = 'practice') {
                const lec = kind === 'lecture';
                return ['oqituvchi', 'fan_masuli'].includes(TIMETABLE_ROLE) && Boolean(card && (lec ? card.ask_lec : card.ask && card.type === 'practice'))
                    && +(dp && (lec ? dp.lec : dp.prc)) > 0 && Boolean(date && date.iso > today);
            }
            const CR_DOW = ['yakshanba', 'dushanba', 'seshanba', 'chorshanba', 'payshanba', 'juma', 'shanba'];
            const crDow = iso => CR_DOW[new Date(iso + 'T00:00:00Z').getUTCDay()] || '';
            async function loadChangeRequests() {
                if (!board || !$('changeReqBtn')) return;
                try { changeReqs = await api(BASE + '/boards/' + board.id + '/change-requests?status=pending&_=' + Date.now()); }
                catch (e) { return; }
                const n = pendingReqs().length;
                const badge = $('changeReqBadge');
                badge.textContent = n; badge.classList.toggle('hidden', !n);
                markPendingChanges();
                renderCyclePendingBar();
                // Qatordagi "tasdiq kutilmoqda" — faqat hali kutilayotgan so'rovlar (bekor / rad / tasdiqlangan — tugma qayta ochiladi).
                if (typeof unitFixPendingSync === 'function' && unitFixPendingSync() && viewMode !== 'cycle') renderPanel();
                if (document.getElementById('crModal') && document.getElementById('crModal').classList.contains('open')) renderChangeReqModal();
            }
            // Tarix sahifalab yuklanadi (eng yangisidan): reset — boshidan.
            async function loadChangeHistory(reset) {
                if (!board || changeHistory.loading) return;
                const last = reset ? null : changeHistory.rows[changeHistory.rows.length - 1];
                changeHistory.loading = true;
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/change-requests?status=history' + (last ? '&before_id=' + last.id : '') + '&_=' + Date.now());
                    changeHistory.rows = (reset ? [] : changeHistory.rows).concat(j.requests || []);
                    changeHistory.more = Boolean(j.has_more);
                } catch (e) { }
                changeHistory.loading = false;
                renderChangeReqModal();
            }
            function markPendingChanges() {
                const ids = new Map();
                pendingReqs().forEach(r => { if (/\.cards\.|week-suggestions/.test(r.route)) (r.card_ids || []).forEach(id => ids.set(+id, crStageText(r))); });
                document.querySelectorAll('[data-chip], .pn-card[data-id]').forEach(el => {
                    const stage = ids.get(+(el.dataset.chip || el.dataset.id));
                    el.classList.toggle('tt-pending-chg', Boolean(stage));
                    if (stage) el.dataset.crStage = stage; else delete el.dataset.crStage;
                    el.title = (stage ? '⏳ ' + stage + ' · ' : '') + String(el.title || '').replace(/^⏳ [^·]*· /, '');
                });
            }
            function renderCyclePendingBar() {
                const bar = $('cyclePendingBar');
                if (!bar) return;
                const list = pendingReqs().filter(r => !/\.cards\./.test(r.route));
                bar.classList.toggle('hidden', !list.length);
                if (!list.length) { bar.innerHTML = ''; return; }
                bar.innerHTML = '<b>&#9203; Tasdiq kutilmoqda (' + list.length + '):</b> ' +
                    list.slice(0, 3).map(r => '<span>' + esc(r.summary) + ' · <b>' + crStageText(r) + '</b></span>').join('') +
                    (list.length > 3 ? '<span>… yana ' + (list.length - 3) + ' ta</span>' : '') +
                    ' <button type="button" data-cr-open>Ko\'rish</button>';
                bar.querySelector('[data-cr-open]').onclick = openChangeReqModal;
            }
            // Sikl kun oynasi: shu kun bo'yicha kutilayotgan soat so'rovi (bo'lsa); mode berilsa — faqat shu surish rejimidagisi.
            function pendingDaySlot(card, dayIndex, mode) {
                if (!card) return null;
                return pendingReqs().find(r => r.route === 'admin.timetable.cycle-lecture-slots' && r.payload
                    && r.payload.subject_name === card.subject && r.payload.group_name === card.group
                    // Bitta kun: day_index yoki (↑ ↓ — cycDaysApply) bitta elementli day_indexes + start_hour.
                    && (String(r.payload.day_index) === String(dayIndex) || (Array.isArray(r.payload.day_indexes) && r.payload.day_indexes.length === 1
                        && String(r.payload.day_indexes[0]) === String(dayIndex))) && r.payload.start_hour
                    && (!mode || (r.payload.mode || 'both') === mode)) || null;
            }
            function openChangeReqModal() {
                let m = document.getElementById('crModal');
                if (!m) {
                    m = document.createElement('div');
                    m.id = 'crModal';
                    m.innerHTML = '<div class="cr-box"><div class="cr-head"><b>Jadval o\'zgarishlari</b><button type="button" class="cr-x" aria-label="Yopish">&times;</button></div><div class="cr-body"></div></div>';
                    document.body.appendChild(m);
                    m.querySelector('.cr-x').onclick = () => m.classList.remove('open');
                    m.addEventListener('click', ev => { if (ev.target === m) m.classList.remove('open'); });
                }
                m.classList.add('open');
                renderChangeReqModal();
                loadChangeRequests();
                if (changeReqFilter === 'history') loadChangeHistory(true);
            }
            // O'qituvchi so'rovi: eski → yangi vaqt va har bosqich (kim, qachon, izoh).
            function crNoticeHtml(r) {
                const n = r.notice;
                const steps = (r.steps || []).map(st => '<li>' + esc(st.at || '') + ' · ' + esc(st.by || '—') + ': ' + esc(st.action || '') +
                    (st.note ? ' <i>(' + esc(st.note) + ')</i>' : '') + '</li>').join('');
                // Ko'p kunli so'rov: har kun (sana, hozirgi → yangi vaqt) — ochiladigan ro'yxat.
                const days = n && (n.days || []).length ? '<details class="cr-sub"><summary>Kunlar (' + n.days.length + ')</summary><ul class="cr-day-list">'
                    + n.days.map(d => '<li>' + esc(d.date) + (d.k ? ' (' + d.k + '-kun)' : '') + ': ' + esc(d.old) + ' → <b>' + esc(d.new) + '</b></li>').join('') + '</ul></details>' : '';
                return (n ? '<div class="cr-sub">' + esc(n.old || '') + ' → <b>' + esc(n.new || '') + '</b>' + (n.room ? ' · xona ' + esc(n.room) : '') + '</div>' : '') + days +
                    (steps ? '<ul class="cr-steps">' + steps + '</ul>' : '');
            }
            function renderChangeReqModal() {
                const m = document.getElementById('crModal');
                if (!m) return;
                const body = m.querySelector('.cr-body');
                const pending = pendingReqs();
                const history = changeReqFilter === 'history';
                const list = history ? changeHistory.rows : pending;
                const approver = Boolean(changeReqs.can_approve);
                const modeHtml = approver
                    ? '<label class="cr-mode"><input type="checkbox" id="crModeChk"' + (changeReqs.approval_required ? ' checked' : '') + '> ' +
                      'Kafedra mudirlari o\'zgarishlari registrator ofisi / o\'quv bo\'limi tasdig\'idan o\'tsin</label>'
                    : '<div class="cr-mode-info">' + (TIMETABLE_ROLE === 'oqituvchi' || TIMETABLE_ROLE === 'fan_masuli'
                        ? 'Taklifingiz avval kafedra mudiri, keyin registrator ofisi yoki o\'quv bo\'limi tasdiqlagach jadvalga tushadi.'
                        : TIMETABLE_DEPARTMENT_HEAD
                        ? (changeReqs.approval_required
                            ? 'Bu doskada o\'zgarishlaringiz registrator ofisi yoki o\'quv bo\'limi tasdiqlagandan keyin jadvalga tushadi. Bo\'sh darsga birinchi marta o\'qituvchi yoki xona biriktirish — darhol.'
                            : 'Hozir bu doskada o\'zgarishlar tasdiqsiz, darhol qo\'llanadi.')
                        : (changeReqs.approval_required
                            ? 'Bu doskada kafedra mudirlari o\'zgarishlari registrator ofisi yoki o\'quv bo\'limi tasdig\'idan o\'tadi (bo\'sh darsga birinchi marta o\'qituvchi yoki xona biriktirish bundan mustasno).'
                            : 'Bu doskada o\'zgarishlar tasdiqsiz, darhol qo\'llanadi.')) + '</div>';
                const tabs = '<div class="cr-tabs">' + [['pending', 'Kutilayotgan (' + pending.length + ')'], ['history', 'Tarix']]
                    .map(([k, l]) => '<button type="button" data-cr-tab="' + k + '" class="' + (changeReqFilter === k ? 'on' : '') + '">' + l + '</button>').join('') + '</div>';
                const rows = list.length ? list.map(r => {
                    const st = r.status === 'pending'
                        ? [crStageText(r), '#b45309', '#fef3c7']
                        : CR_STATUS[r.status] || [r.status, '#334155', '#e2e8f0'];
                    const acts = r.status !== 'pending' ? '' : r.can_review
                        ? '<button type="button" class="cr-ok" data-cr-approve="' + r.id + '">Tasdiqlash</button><button type="button" class="cr-no" data-cr-reject="' + r.id + '">Rad etish</button>'
                        : r.mine ? '<button type="button" class="cr-no" data-cr-cancel="' + r.id + '">Bekor qilish</button>' : '';
                    const note = r.error ? '<div class="cr-err">' + esc(r.error) + '</div>' : (r.review_note && r.status !== 'pending' ? '<div class="cr-note">' + esc(r.review_note) + '</div>' : '');
                    return '<tr><td class="cr-when">' + esc(r.created_at || '') + '</td>' +
                        '<td><div class="cr-who">' + esc(r.kafedra_name || r.requester_role || '') + '</div><div class="cr-sub">' + esc(r.requester_name || '') +
                        (r.requester_role && r.kafedra_name ? ' · ' + esc(r.requester_role) : '') + '</div></td>' +
                        '<td>' + esc(r.summary) + crNoticeHtml(r) + (r.head_reviewer_name ? '<div class="cr-sub">Kafedra mudiri tasdiqladi: ' + esc(r.head_reviewer_name) + '</div>' : '') + (r.groups && r.groups.length ? '<div class="cr-sub">Guruhlar: ' + esc(r.groups.slice(0, 8).join(', ')) + (r.groups.length > 8 ? '…' : '') + '</div>' : '') + note + '</td>' +
                        '<td><span class="cr-st" style="color:' + st[1] + ';background:' + st[2] + '">' + st[0] + '</span>' +
                        (r.reviewer_name && r.status !== 'pending' ? '<div class="cr-sub">' + esc(r.reviewer_name) + (r.reviewed_at ? ' · ' + esc(r.reviewed_at) : '') + '</div>' : '') + '</td>' +
                        '<td class="cr-acts">' + acts + '</td></tr>';
                }).join('') : '<tr><td colspan="5" class="cr-empty">' + (history
                    ? (changeHistory.loading ? 'Yuklanmoqda...' : 'O\'zgarishlar tarixi bo\'sh.')
                    : 'Kutilayotgan so\'rovlar yo\'q.') + '</td></tr>';
                const more = history && changeHistory.more
                    ? '<div class="cr-more"><button type="button" data-cr-more' + (changeHistory.loading ? ' disabled' : '') + '>Yana yuklash</button></div>' : '';
                body.innerHTML = modeHtml + tabs + '<div class="cr-table-wrap"><table class="cr-table"><thead><tr><th>Sana</th><th>Kim</th><th>O\'zgarish</th><th>Holat</th><th></th></tr></thead><tbody>' + rows + '</tbody></table></div>' + more;
                body.querySelectorAll('[data-cr-tab]').forEach(b => b.onclick = () => {
                    changeReqFilter = b.dataset.crTab;
                    renderChangeReqModal();
                    if (changeReqFilter === 'history') loadChangeHistory(true);
                });
                const moreBtn = body.querySelector('[data-cr-more]');
                if (moreBtn) moreBtn.onclick = () => loadChangeHistory(false);
                const chk = body.querySelector('#crModeChk');
                if (chk) chk.onchange = async () => {
                    try {
                        await api(BASE + '/boards/' + board.id + '/change-requests/mode', 'POST', { approval_required: chk.checked ? 1 : 0 });
                        ttToast(chk.checked ? 'Tasdiq rejimi yoqildi: kafedra o\'zgarishlari endi so\'rov bo\'lib keladi.' : 'Tasdiq rejimi o\'chirildi.', 'ok');
                        await loadChangeRequests();
                    } catch (e) { chk.checked = !chk.checked; alert('Xatolik: ' + e.message); }
                };
                const act = async (btn, url, body, okMsg) => {
                    btn.disabled = true;
                    try {
                        const result = await api(url, 'POST', body);
                        ttToast(result.message || okMsg, 'ok');
                        await loadChangeRequests();
                        if (changeReqFilter === 'history') await loadChangeHistory(true);
                        if (viewMode === 'cycle') await loadCyclePlan(); else await loadBoard(board.id);
                    } catch (e) { alert('Xatolik: ' + e.message); btn.disabled = false; await loadChangeRequests(); }
                };
                body.querySelectorAll('[data-cr-approve]').forEach(b => b.onclick = () =>
                    act(b, BASE + '/change-requests/' + b.dataset.crApprove + '/approve', {}, 'Tasdiqlandi — jadvalga qo\'llandi, tegishlilarga xabar yuborilmoqda.'));
                // Rad etish — sabab sahifa ichidagi oynada (majburiy): bo'sh yoki "Bekor" — rad etilmaydi. So'rov id'si oyna ochilishidan
                // oldin olinadi (oyna ochiq turganda ro'yxat qayta chizilsa ham).
                body.querySelectorAll('[data-cr-reject]').forEach(b => b.onclick = async () => {
                    const id = b.dataset.crReject;
                    const note = await askRejectReason();
                    if (note === null) { ttToast('Rad etilmadi: sabab kiritilmadi.', 'warn'); return; }
                    act(b, BASE + '/change-requests/' + id + '/reject', { note }, 'Rad etildi.');
                });
                body.querySelectorAll('[data-cr-cancel]').forEach(b => b.onclick = () => {
                    if (!confirm('So\'rov bekor qilinsinmi?')) return;
                    act(b, BASE + '/change-requests/' + b.dataset.crCancel + '/cancel', {}, 'So\'rov bekor qilindi.');
                });
            }
            if ($('changeReqBtn')) $('changeReqBtn').onclick = openChangeReqModal;

            // ===== Doska =====
            $('newBoardBtn').onclick = () => $('newBoardForm').classList.toggle('hidden');
            $('createBoardBtn').onclick = async function () {
                this.disabled = true;
                try {
                    const j = await api(BOARDS_STORE, 'POST', {
                        academic_year: $('nbYear').value, semester_parity: $('nbParity').value,
                        kind: $('nbKind').value, faculty_id: $('nbFaculty').value || '',
                        days: $('nbDays').value, pairs_per_day: $('nbPairs').value, weeks: $('nbWeeks').value,
                        subject_source: $('nbSource') ? $('nbSource').value : 'ishchi',
                        admin_only: $('nbAdminOnly') && $('nbAdminOnly').checked ? 1 : 0,
                    });
                    location.href = location.pathname + '?board=' + j.board_id;
                } catch (e) { alert('Xatolik: ' + e.message); this.disabled = false; }
            };

            $('boardSel').onchange = function () {
                if (this.value) loadBoard(this.value); else hideBoard();
            };
            $('delBoardBtn').onclick = async () => {
                if (!board || !confirm('Doska va barcha kartochkalari o\'chirilsinmi?')) return;
                await fetch(BASE + '/boards/' + board.id, { method: 'POST', headers: {'Accept':'application/json'},
                    body: (() => { const f = new FormData(); f.append('_token', CSRF); f.append('_method', 'DELETE'); return f; })() });
                location.href = location.pathname;
            };
            // Kartochkalar: odatda SINXRONLASH (joylashuvlar saqlanadi, faqat noaktual kartalar
            // o'chadi, yangilari taqsimlanmagan holda qo'shiladi). Shift+bosish — to'liq qayta yaratish.
            let cardSyncTimer = null;
            let cardSyncElapsed = 0;
            function startCardSyncProgress(full) {
                const box = $('cardSyncProgress');
                cardSyncElapsed = 0;
                $('cardSyncProgressText').textContent = full
                    ? 'Barcha kartochkalar qayta yaratilmoqda…'
                    : 'Tasdiqlangan oqim va o‘quv reja fanlari sinxronlanmoqda…';
                $('cardSyncProgressElapsed').textContent = '0 soniya';
                box.classList.remove('hidden');
                if (cardSyncTimer) clearInterval(cardSyncTimer);
                cardSyncTimer = setInterval(() => {
                    cardSyncElapsed++;
                    $('cardSyncProgressElapsed').textContent = cardSyncElapsed + ' soniya';
                }, 1000);
            }
            function setCardSyncProgressText(text) {
                $('cardSyncProgressText').textContent = text;
            }
            function stopCardSyncProgress() {
                if (cardSyncTimer) clearInterval(cardSyncTimer);
                cardSyncTimer = null;
                $('cardSyncProgress').classList.add('hidden');
            }
            $('genBtn').title = 'Tasdiqlangan oqim bilan sinxronlash. Shift+bosish — hammasini qayta yaratish';
            $('genBtn').onclick = async function (ev) {
                if (!board) return;
                const full = !!(ev && ev.shiftKey) && cards.length > 0;
                if (full) {
                    if (!confirm('TO\'LIQ QAYTA YARATISH: mavjud kartochkalar (joylashuvlari bilan) o\'chirilib qayta yaratiladi. O\'qituvchi va xona biriktirishlari saqlanib qoladi. Davom etamizmi?')) return;
                } else if (cards.length && !confirm('Kartochkalar tasdiqlangan oqim bilan sinxronlanadi:\n'
                    + '• mavjud kartochkalar va ularning joylashuvi saqlanadi;\n'
                    + '• rejada endi yo\'q kartochkalar o\'chiriladi;\n'
                    + '• yangilari pastda (taqsimlanmagan) qo\'shiladi.\nDavom etamizmi?')) return;
                this.disabled = true;
                $('boardMsg').textContent = full ? 'Qayta yaratilmoqda...' : 'Sinxronlanmoqda...';
                startCardSyncProgress(full);
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/generate', 'POST', { mode: full ? 'full' : 'sync' });
                    const parts = [];
                    if (j.mode === 'sync') {
                        parts.push((j.kept || 0) + ' ta saqlandi', (j.created || 0) + ' ta yangi qo\'shildi',
                            (j.removed || 0) + ' ta o\'chirildi' + (j.removed_placed ? ' (' + j.removed_placed + ' tasi joylangan edi)' : ''));
                        if (j.updated) parts.push(j.updated + ' ta yangilandi');
                        if (j.renamed) parts.push(j.renamed + ' ta fan nomi yangilandi');
                        if (j.kept_placement) parts.push(j.kept_placement + ' ta qayta yaratilgan karta eski joyini oldi');
                        if (j.kept_placement_conflicts) parts.push(j.kept_placement_conflicts + ' ta eski joy band — karta joylanmagan qoldi');
                    } else parts.push((j.created || 0) + ' ta kartochka yaratildi');
                    if (j.restored_units) parts.push(j.restored_units + ' ta dars birligining o\'qituvchi/xona biriktirishi tiklandi');
                    if (j.lost_units) parts.push(j.lost_units + ' ta birlik endi rejada yo\'q');
                    // Birlashib yaratilgan kartalar (bo'lak qismlari, "Guruhchalar birga o'tadi"): guruhchalarda o'qituvchilar har xil edi.
                    if ((j.joint_warnings || []).length) {
                        parts.push((j.joint_warnings.length) + ' ta birlashgan kartada o\'qituvchilar har xil edi');
                        alert('Birlashib yaratilgan kartalar — tekshiring:\n\n' + j.joint_warnings.slice(0, 30).join('\n'));
                    }
                    // Semestri topilmagan guruhlar (o'quv reja sanalari shu davrga kesishmaydi — HEMIS'da tekshirish kerak).
                    if ((j.semester_warnings || []).length) {
                        parts.push(j.semester_warnings.length + ' ta guruhda shu davrda semestr yo\'q');
                        alert('Semestri topilmagan guruhlar — HEMIS\'da semestr sanalarini tekshiring:\n\n' + j.semester_warnings.slice(0, 40).join('\n'));
                    }
                    const summary = parts.join(' · ');
                    setCardSyncProgressText('Doska yangi kartochkalar bilan qayta yuklanmoqda…');
                    await loadBoard(board.id);
                    $('boardMsg').textContent = summary;
                } catch (e) {
                    $('boardMsg').textContent = 'Sinxronlash xatosi: ' + e.message;
                    alert('Xatolik: ' + e.message);
                } finally {
                    stopCardSyncProgress();
                    this.disabled = false;
                }
            };
            // ===== Doska versiyalari (nusxalar): ro'yxat, qo'lda nusxa, joylashuvni tiklash (avval sinov) =====
            if ($('snapshotsBtn')) $('snapshotsBtn').onclick = async function () {
                if (!board) return;
                let box = $('snapBox');
                if (!box) {
                    box = document.createElement('div');
                    box.id = 'snapBox';
                    box.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(15,23,42,.45);display:flex;align-items:flex-start;justify-content:center;padding:40px 16px;overflow:auto';
                    document.body.appendChild(box);
                }
                const reasonName = { daily: 'Kunlik', manual: 'Qo\'lda', before_generate: '«Kartochkalar» oldidan', before_unplace: '«Bo\'shatish» oldidan',
                    before_layer_copy: 'Qatlamga ko\'chirish oldidan', before_restore: 'Tiklash oldidan', imported_backup: 'Zaxira bazadan',
                    before_add_groups: 'Yangi guruhlar oldidan', before_separate_practice: 'Alohida amaliy oldidan', before_split_practice: 'Amaliyni bo\'lish oldidan',
                    before_split_variant: 'Bo\'lakni bo\'lish oldidan', before_merge_lectures: 'Ma\'ruzalarni birlashtirish oldidan' };
                const render = async (msg) => {
                    let list = [];
                    try { list = (await api(BASE + '/boards/' + board.id + '/snapshots')).snapshots || []; } catch (e) { msg = 'Xatolik: ' + e.message; }
                    box.innerHTML = '<div style="background:#fff;border-radius:12px;max-width:820px;width:100%;padding:16px;font-size:13px">'
                        + '<div style="display:flex;gap:8px;align-items:center;margin-bottom:8px"><b style="flex:1;font-size:15px">Doska versiyalari</b>'
                        + '<button type="button" id="snapTake" class="tt-ktr-weeks-btn">Hozir nusxa olish</button>'
                        + '<button type="button" id="snapClose" class="tt-ktr-weeks-btn">Yopish</button></div>'
                        + '<div style="color:#64748b;margin-bottom:8px">Har kecha va «Kartochkalar», «Bo\'shatish» kabi amallardan oldin avtomatik nusxa olinadi (30 kun saqlanadi). '
                        + '«Tiklash» — nusxadagi joylashuvni hozir <b>joylanmagan</b> kartalarga qaytaradi (karta qayta yaratilgan bo\'lsa ham, fan + guruh bo\'yicha); joylashganlariga tegilmaydi. Avval «Sinov».</div>'
                        + (msg ? '<pre style="white-space:pre-wrap;background:#f1f5f9;padding:8px;border-radius:8px;margin-bottom:8px">' + esc(msg) + '</pre>' : '')
                        + '<table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f8fafc"><th style="text-align:left;padding:4px">Sana</th><th style="text-align:left">Turi</th><th>Kartalar</th><th>Joylashgan</th><th></th></tr></thead><tbody>'
                        + (list.length ? list.map(x => '<tr style="border-top:1px solid #e2e8f0"><td style="padding:4px">' + esc(x.created_at) + '</td><td>' + esc(reasonName[x.reason] || x.reason)
                            + (x.created_by_name ? ' <span style="color:#94a3b8">· ' + esc(x.created_by_name) + '</span>' : '') + '</td><td style="text-align:center">' + x.cards_count
                            + '</td><td style="text-align:center">' + x.placed_count + '</td><td style="text-align:right;white-space:nowrap">'
                            + '<button type="button" class="tt-ktr-weeks-btn" data-snap-dry="' + x.id + '">Sinov</button> '
                            + '<button type="button" class="tt-ktr-weeks-btn" data-snap-apply="' + x.id + '">Tiklash</button></td></tr>').join('')
                            : '<tr><td colspan="5" style="padding:8px;color:#94a3b8">Hali nusxa yo\'q</td></tr>')
                        + '</tbody></table></div>';
                    $('snapClose').onclick = () => box.remove();
                    $('snapTake').onclick = async () => { try { await api(BASE + '/boards/' + board.id + '/snapshots', 'POST', {}); render('Nusxa olindi.'); } catch (e) { render('Xatolik: ' + e.message); } };
                    const run = async (id, dry) => {
                        if (!dry && !confirm('Nusxadagi joylashuv hozir joylanmagan kartalarga yoziladi (oldin hozirgi holatdan nusxa olinadi). Davom etamizmi?')) return;
                        render('Hisoblanmoqda...');
                        try {
                            const r = await api(BASE + '/boards/' + board.id + '/snapshots/' + id + '/restore', 'POST', { dry_run: dry ? 1 : 0 });
                            const txt = (r.dry_run ? 'SINOV (yozilmadi): ' : 'YOZILDI: ') + r.cards + ' karta (' + r.units + ' dars birligi) — ichki ' + r.internal + ', tashqi ' + r.external
                                + ', haftalik ko\'chirish ' + r.week_moves + ', o\'qituvchi/xona ' + r.teacher_room + '\nNusxada topilmadi: ' + r.no_source + ' · nusxada ham joylanmagan: ' + r.source_unplaced
                                + (r.conflicts ? ' · joyi band (to\'qnashuv) — yozilmadi: ' + r.conflicts : '')
                                + (r.examples && r.examples.length ? '\n\n' + r.examples.join('\n') : '')
                                + (r.conflict_examples && r.conflict_examples.length ? '\n\nTo\'qnashuvlar:\n' + r.conflict_examples.join('\n') : '');
                            await render(txt);
                            if (!r.dry_run) await loadBoard(board.id);
                        } catch (e) { render('Xatolik: ' + e.message); }
                    };
                    box.querySelectorAll('[data-snap-dry]').forEach(b => b.onclick = () => run(b.dataset.snapDry, true));
                    box.querySelectorAll('[data-snap-apply]').forEach(b => b.onclick = () => run(b.dataset.snapApply, false));
                };
                render('');
            };
            // Fan nomlarini ishchi rejadagi joriy nomga yangilash (qayta yaratmasdan)
            // Birlashgan bo'lak kartasi ("Fan (a)", guruhchalar 02a + 02c): qisqa yorliq "02a + 02c"; boshqa kartalar — ''.
            function bolakPartsLabel(c) {
                if (!c || c.training_type === 'lecture' || !/\(\s*[a-zа-яё]\s*\)\s*$/i.test(String(c.subject_name || '')) || (c.group_names || []).length < 2) return '';
                return c.group_names.map(g => { const m = /(\d+[^\d\s(]*)\s*(\(.*\))?\s*$/.exec(String(g)); return m ? m[1] : g; }).join(' + ');
            }
            // "Bo'laklar": joriy qamrovda bo'lak qismlarini birlashtirish — avval sinov (dry_run) natijasi, "Tasdiqlash" — bajarish.
            if ($('mergeBolakBtn')) $('mergeBolakBtn').onclick = async function () {
                if (!board) return;
                const url = BASE + '/boards/' + board.id + '/merge-bolak-parts';
                let dry;
                this.disabled = true;
                try { dry = await api(url, 'POST', Object.assign(scopeBody(), { dry_run: 1 })); }
                catch (e) { alert('Xatolik: ' + e.message); this.disabled = false; return; }
                this.disabled = false;
                const prior = document.getElementById('bolakMergeModal');
                if (prior) prior.remove();
                const days = (board.day_names && board.day_names.length) ? board.day_names : ['Dushanba', 'Seshanba', 'Chorshanba', 'Payshanba', 'Juma', 'Shanba', 'Yakshanba'];
                const placed = p => p ? ((days[p.day - 1] || p.day + '-kun') + ', ' + p.pair + '-para') : 'panelda';
                const rows = dry.list || [];
                const m = document.createElement('div');
                m.id = 'bolakMergeModal';
                m.className = 'cr-proposal-overlay';
                m.innerHTML = '<div class="cr-proposal-form" style="width:min(900px,96vw);max-height:86vh;overflow:auto">'
                    + '<h3 class="font-bold text-lg">Bo‘lak qismlarini birlashtirish — sinov natijasi</h3>'
                    + '<p class="text-sm">' + esc(scopeLabelText()) + '. Bitta bo‘lakning guruhchalardagi qismlari (masalan 02a + 02c) bitta mashg‘ulot: bir vaqtda, bitta xona va o‘qituvchi.</p>'
                    + (rows.length ? '<table class="w-full text-xs border-collapse tt-rules-table" style="margin-top:6px"><thead><tr><th>Fan</th><th>Guruhchalar</th><th>Natija</th><th>Ogohlantirish</th></tr></thead><tbody>'
                        + rows.map(r => '<tr><td>' + esc(r.subject) + '</td><td>' + esc(r.groups) + '</td><td>'
                            + (r.card_to && r.card_to.length ? r.cards_from.length + ' karta → ' + r.card_to.length + ' (' + r.placed_at.map(placed).join('; ') + ')' : '—') + '</td>'
                            + '<td class="' + (r.warning ? 'text-amber-700' : '') + '">' + esc(r.warning || '') + '</td></tr>').join('') + '</tbody></table>'
                        : '<p class="text-sm text-gray-500" style="margin-top:6px">Birlashtiriladigan bo‘lak qismlari yo‘q.</p>')
                    + '<p role="alert" class="text-red-600"></p><div class="flex justify-end gap-3" style="margin-top:8px"><button type="button" data-close>Bekor</button>'
                    + (dry.merged ? '<button type="button" data-ok class="px-3 py-2 bg-blue-600 text-white rounded">Tasdiqlash</button>' : '') + '</div></div>';
                document.body.appendChild(m);
                m.querySelector('[data-close]').onclick = () => m.remove();
                const ok = m.querySelector('[data-ok]');
                if (ok) ok.onclick = async () => {
                    ok.disabled = true;
                    try {
                        const r = await api(url, 'POST', scopeBody());
                        m.remove();
                        await loadBoard(board.id);
                        $('boardMsg').textContent = 'Bo‘lak qismlari birlashtirildi: ' + (r.merged || 0) + ' ta, o‘chirilgan kartalar: ' + (r.removed || 0);
                    } catch (e) { ok.disabled = false; m.querySelector('[role="alert"]').textContent = e.message; }
                };
            };
            $('refreshNamesBtn').onclick = async function () {
                if (!board) return;
                this.disabled = true; $('boardMsg').textContent = 'Fan nomlari yangilanmoqda...';
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/refresh-names', 'POST', {});
                    $('boardMsg').textContent = (j.updated || 0) + ' ta kartochka nomi yangilandi'
                        + ' · ' + (j.kafedra_updated || 0) + ' ta kartochka kafedrasi yangilandi';
                    await loadBoard(board.id);
                } catch (e) { $('boardMsg').textContent = ''; alert('Xatolik: ' + e.message); }
                this.disabled = false;
            };
            // Doskani sahifadan chiqmasdan qayta yuklash (F5 o'rniga): tanlovlar
            // (fakultet/yo'nalish/kurs, dars turi, hafta, kesim) va skroll saqlanadi.
            async function reloadBoard() {
                if (!board) return;
                const btn = $('reloadBoardBtn'), wrap = $('gridWrap');
                const scroll = { top: wrap.scrollTop, left: wrap.scrollLeft };
                btn.disabled = true; btn.classList.add('is-loading');
                $('boardMsg').textContent = 'Yangilanmoqda...';
                try {
                    await loadBoard(board.id);
                    wrap.scrollTop = scroll.top; wrap.scrollLeft = scroll.left;
                    if (cards.length) {
                        $('boardMsg').textContent = 'Yangilandi ' +
                            new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                    }
                } catch (e) { $('boardMsg').textContent = ''; alert('Xatolik: ' + e.message); }
                btn.disabled = false; btn.classList.remove('is-loading');
            }
            $('reloadBoardBtn').onclick = reloadBoard;

            // aSc uslubidagi boshqaruv tugmalari (doska tanlash qatorida) — bitta guruh sifatida ko'rsatish/yashirish

            function toggleAscToolbar(show) {
                document.querySelectorAll('[data-asc-toolbar]').forEach(el => {
                    const allowedForRole = !TIMETABLE_ASSIGNMENT_ONLY
                        || el.id === 'assignBtn'
                        || (TIMETABLE_CAN_USE_MANAGER && el.id === 'managerBtn');
                    el.classList.toggle('hidden', !show || !allowedForRole);
                });
                applyTimetableAccess();
            }

            // ===== Holatni URLda saqlash (F5 / havola) =====
            // ?board=ID&fac=..&dir=..&crs=..&type=..&week=..&view=..  (fac/dir/crs takrorlanishi mumkin)
            function parseViewFromUrl() {
                const p = new URLSearchParams(location.search);
                const id = p.get('board');
                if (!id) return null;
                // Hafta — faqat musbat butun son (week=-1, 1.5, abc → shablon); yuqori
                // chegara (panjaraning hafta soni) fillWeekSel'da tekshiriladi.
                const week = Number(p.get('week'));
                return {
                    board: id,
                    fac: p.getAll('fac'),
                    dir: p.getAll('dir'),
                    crs: p.getAll('crs').map(Number).filter(Number.isInteger),
                    type: p.get('type') || 'all',
                    week: Number.isInteger(week) && week > 0 ? week : 0,
                    // syncUrl sukut kesimini (DEFAULT_VIEW — o'qituvchiga 'teacher') yozmaydi — yo'q bo'lsa o'sha.
                    view: p.get('view') || DEFAULT_VIEW,
                };
            }
            // Joriy holatni URLga yozamiz (tarixga yangi yozuv qo'shmasdan). Faqat
            // o'zgargan bo'lsa yoziladi — renderAll'dan tez-tez chaqirilsa ham arzon.
            function syncUrl() {
                const p = new URLSearchParams();
                if (board) {
                    p.set('board', board.id);
                    if (cards.length) {
                        selectedFaculties.forEach(f => p.append('fac', f));
                        selectedDirs.forEach(d => p.append('dir', d));
                        selectedCourses.forEach(c => p.append('crs', c));
                        if (typeFilter !== 'all') p.set('type', typeFilter);
                        if (curWeek) p.set('week', curWeek);
                        if (viewMode !== DEFAULT_VIEW) p.set('view', viewMode);
                    }
                }
                const qs = p.toString();
                const next = location.pathname + (qs ? '?' + qs : '') + location.hash;
                if (next !== location.pathname + location.search + location.hash) {
                    history.replaceState(history.state, '', next);
                }
            }
            // URLdan o'qilgan tanlovlarni doska yuklanganda qo'llaymiz (faqat o'sha doskaga).
            function applyPendingView() {
                const v = pendingView;
                pendingView = null;
                if (!v || !board || String(v.board) !== String(board.id)) return;
                selectedFaculties = new Set(v.fac);
                selectedDirs = new Set(v.dir);
                selectedCourses = new Set(v.crs);
                if (['all', 'lecture', 'practice'].includes(v.type)) setTypeFilter(v.type);
                curWeek = v.week;
                if ([...$('viewMode').options].some(o => o.value === v.view)) {
                    viewMode = v.view;
                    $('viewMode').value = v.view;
                }
            }
            function setTypeFilter(t) {
                typeFilter = t;
                document.querySelectorAll('.tt-type').forEach(x => x.classList.toggle('active', x.dataset.type === t));
            }

            // So'nggi doska yuklash so'rovi tartib raqami: qamrov/doska tez almashtirilsa kechikkan eski javob
            // (mas. scope=mine) yangisining ustiga yozilmaydi — faqat oxirgi so'rov qo'llanadi.
            let boardLoadSeq = 0;
            function hideBoard() {
                boardLoadSeq++;   // yo'lda qolgan yuklash doskani qayta ochmasin
                ttFocusDiscard();
                board = null;
                $('genBtn').classList.add('hidden'); $('delBoardBtn').classList.add('hidden');
                $('refreshNamesBtn').classList.add('hidden'); $('reloadBoardBtn').classList.add('hidden');
                if ($('mergeBolakBtn')) $('mergeBolakBtn').classList.add('hidden');
                if ($('snapshotsBtn')) $('snapshotsBtn').classList.add('hidden');
                toggleAscToolbar(false);
                $('specBar').classList.add('hidden'); $('mainArea').classList.add('hidden');
                syncUrl();
            }

            async function loadBoard(id) {
                // Boshqa doskaga o'tayotgan bo'lsak — eski doskaga oid holatni tozalaymiz
                const switching = !board || String(board.id) !== String(id);
                // Boshqa doska: oldingi doskaning qamrov tanlovi so'rovga qo'shilmasin ("Butun doska" — tanlangan qamrov bo'yicha so'raladi).
                if (switching) { ttFocusDiscard(); curSpec = null; selectedFaculties.clear(); selectedDirs.clear(); selectedCourses.clear(); }
                // URLga noyob parametr — har qanday kesh (brauzer/proxy) eski kartalarni
                // qaytarmasin (yangi kurs/kartalar darrov ko'rinsin).
                // O'qituvchi / fan mas'uli: "Faqat meniki" / "Mas'ul fanlarim" — server faqat shu kartalarni beradi (butun doska emas).
                const dataScope = serverScopeParam();
                const seq = ++boardLoadSeq;
                const j = await api(BASE + '/boards/' + id + '/data?_=' + Date.now() + dataScope);
                if (seq !== boardLoadSeq) return;   // eskirgan javob — undan keyin yangi so'rov yuborilgan
                try { localStorage.setItem(LAST_BOARD_KEY, String(id)); } catch (e) { }
                lastLoadSig = dataScope;   // shu parametrlar bilan yuklangan — xuddi shu so'rov takrorlanmaydi (scopeNeedsReload)
                board = j.board; allCards = j.cards || [];
                teacherFullNames = Object.assign({}, j.teacher_full_names || {});
                invalidateWeeklyConflicts();
                invalidateCycleWeek();
                teacherPhones = Object.assign({}, j.teacher_phones || {});   // {id: {text, tel}} — faqat ko'rishga huquq bo'lsa
                inactiveRooms = Object.assign({}, j.inactive_rooms || {});
                specIndex = Array.isArray(j.spec_index) ? j.spec_index : [];
                loadedSpecs = j.filter && Array.isArray(j.filter.loaded_specs) ? new Set(j.filter.loaded_specs.map(r => specTriple(r[0], r[1], r[2]))) : null;
                loadedWeeks = j.filter && Array.isArray(j.filter.weeks) ? new Set(j.filter.weeks.map(Number)) : null;
                applyWeeklyLayer(allCards);
                groupStudents = j.group_students || {};
                myKafedras = Array.isArray(j.my_kafedras) ? j.my_kafedras : [];
                mySubjectCardIds = new Set((j.my_subject_card_ids || []).map(Number));
                cards = scopeCards(allCards);
                // Joylash rejimi: kesh eskirdi; karta hamon bo'lsa — rejim qoladi (grid qayta so'raladi), aks holda — tugaydi.
                fmGridCache.clear();
                if (fmPick) {
                    const nc = cards.find(x => +x.id === +fmPick.card.id);
                    if (nc) Object.assign(fmPick, { card: nc, data: null, error: null, week: 0 }); else fmPick = null;
                }
                missingGroups = j.missing_groups || [];
                buildSubjectColors();
                loadSubjectColorOverrides();
                grids = {};
                (j.grids || []).forEach(g => { grids[gridKey(g.faculty_name, g.specialty_name, g.course, g.curriculum_hemis_id)] = g; });
                // Hafta bo'yicha istisnolar: ixcham massiv (ov: [karta, hafta, kun, para, bekor, xona kodi, xona nomi]) yoki eski obyektlar.
                overrides = {};
                const roomVol = j.room_volumes || {};
                (j.ov || []).forEach(o => {
                    overrides[o[0] + '|' + o[1]] = { day: o[2], pair: o[3], cancelled: !!o[4], auditorium_code: o[5] || null, auditorium_name: o[6] || null,
                        auditorium_volume: o[5] ? (roomVol[o[5]] ?? null) : null, ...(o[7] ? { mudir_placeholder: o[7] } : {}), ...(o[8] ? { unplaced: true } : {}) };
                });
                (j.overrides || []).forEach(o => {
                    overrides[o.card_id + '|' + o.week] = {
                        day: o.day,
                        pair: o.pair,
                        cancelled: o.cancelled,
                        auditorium_code: o.auditorium_code || null,
                        auditorium_name: o.auditorium_name || null,
                        auditorium_volume: o.auditorium_volume || null,
                    };
                });
                // Fan rejimi (hafta almashinuvi / sikl): "spec|course|subject" => {mode, rotation_group, occurrences, cycle_days}
                subjectSettings = {};
                (j.subject_settings || []).forEach(s => { subjectSettings[subjModeKey(s.specialty_name, s.course, s.subject_name)] = s; });
                // Eski kartaga ishora qiluvchi tanlovlarni bekor qilamiz (eski doskaga yozib
                // yubormaslik uchun); doska almashsa yo'nalish tanlovini ham qayta tanlaymiz
                selected = null; modalCard = null;
                $('cardModal').classList.add('hidden');
                if (switching) {
                    curSpec = null; selectedFaculties.clear(); selectedDirs.clear(); selectedCourses.clear();
                    // Sikl sanasi/bayramlari doskaga xos — almashganda tozalaymiz (boshqa
                    // doska qiymatini uning ustiga yozib yubormaslik uchun).
                    if ($('cycleStart')) $('cycleStart').value = '';
                    cyclePlanData = null; cycleHolidays = []; cyclePairsShown = null;
                    if ($('cycleHolBar')) $('cycleHolBar').classList.add('hidden');
                }
                applyPendingView();
                $('boardSel').value = String(board.id);
                $('genBtn').classList.remove('hidden');
                if ($('changeReqBtn')) { $('changeReqBtn').classList.remove('hidden'); loadChangeRequests(); }
                $('refreshNamesBtn').classList.remove('hidden');
                if ($('mergeBolakBtn')) $('mergeBolakBtn').classList.remove('hidden');
                $('reloadBoardBtn').classList.remove('hidden');
                if ($('snapshotsBtn')) $('snapshotsBtn').classList.remove('hidden');
                $('delBoardBtn').classList.remove('hidden');
                toggleAscToolbar(true);
                if (!showLoadedCards()) return;
                // Qoidalar sonini (badge) fonda yangilaymiz — doska yuklanishini kutdirmaydi
                loadRules().catch(() => {});
            }

            // O'qituvchi / fan mas'uli / kafedra mudiri: /data rol doirasida — rejim (scope) har doim; "Butun doska" — tanlangan qamrov
            // (fakultet, yo'nalish, kurs; tanlov bo'sh — server rol doirasidagi yo'nalish+kurslarni beradi). O'qituvchi va fan mas'uli
            // (faqat ko'radi): hafta tanlangan bo'lsa — ko'chirishlar faqat shu hafta uchun (bekor qilinganlari — hammasi).
            function serverScopeParam() {
                if (!TIMETABLE_SCOPED_DATA) return '';
                let q = '&scope=' + encodeURIComponent(scopeMode);
                if (scopeMode === 'all' && (selectedFaculties.size || selectedDirs.size || selectedCourses.size)) {
                    const b = scopeBody();
                    b.faculty_names.forEach(v => { q += '&faculty_names[]=' + encodeURIComponent(v); });
                    b.specialty_names.forEach(v => { q += '&specialty_names[]=' + encodeURIComponent(v); });
                    b.courses.forEach(v => { q += '&courses[]=' + encodeURIComponent(v); });
                }
                if (TIMETABLE_READ_ONLY && +curWeek > 0) q += '&weeks[]=' + (+curWeek);
                return q;
            }
            // "Butun doska" (cheklangan rol): to'liq yuklangan yo'nalish+kurslar (null — hammasi yuklangan) va doskadagi barcha
            // yo'nalish+kurslar ro'yxati (qamrov tanlovi uchun); yuklangan haftalar (null — hammasi).
            // lastLoadSig — oxirgi yuklangan so'rov parametrlari; scopeInflightSig — yo'ldagi avtomatik so'rov (takrorlanmasin).
            let loadedSpecs = null, specIndex = [], loadedWeeks = null, lastLoadSig = null, scopeInflightSig = '';
            const specTriple = (fac, spec, course) => String(fac || '').trim().toLowerCase() + '|' + String(spec || '').trim().toLowerCase() + '|' + (+course);
            // Tanlangan qamrovning yuklanmagan yo'nalish+kursi bormi — bo'lsa doska shu qamrov bilan qayta so'raladi. Xuddi shu
            // parametrlar bilan oxirgi yuklangan (server bergani shu) yoki yo'ldagi so'rov — takrorlanmaydi (sikl yo'q).
            function scopeNeedsReload() {
                if (!TIMETABLE_SCOPED_DATA || scopeMode !== 'all' || !loadedSpecs) return false;
                const missing = specIndex.some(r => selectedFaculties.has(r[0]) && selectedDirs.has(r[1]) && selectedCourses.has(+r[2])
                    && !loadedSpecs.has(specTriple(r[0], r[1], r[2])));
                const sig = serverScopeParam();
                return missing && sig !== lastLoadSig && sig !== scopeInflightSig;
            }
            // Ko'chirishlar faqat yuklangan haftalar uchun (o'qituvchi / fan mas'uli): ko'rsatilayotgan hafta ular orasida bo'lmasa (hafta
            // tanlandi yoki panjara almashib hafta moslashtirildi) — shu hafta bilan qayta so'raladi; xuddi shu so'rov takrorlanmaydi.
            function weekNeedsReload() {
                return !!(board && loadedWeeks && !(+curWeek > 0 && loadedWeeks.has(+curWeek)) && serverScopeParam() !== lastLoadSig);
            }
            function ensureScopeLoaded() {
                if (!board || !scopeNeedsReload()) return false;
                const sig = scopeInflightSig = serverScopeParam();
                loadBoard(board.id).catch(e => alert('Xatolik: ' + e.message))
                    .finally(() => { if (scopeInflightSig === sig) scopeInflightSig = ''; });
                return true;
            }
            // Yuklangan kartalarni (qamrov qo'llangan — cards) ko'rsatadi; bo'sh bo'lsa false.
            // Qamrov bo'yicha bo'sh (doskada kartalar bor yoki server qamrov bilan bergan) — qamrov tugmalari
            // (specBar ichida) ko'rinib qoladi, "Butun doska"ga qaytish mumkin; doska haqiqatan bo'sh — "Kartochkalarni yaratish".
            function showLoadedCards() {
                buildSpecList();
                if (!cards.length) {
                    const scopeEmpty = allCards.length > 0 || serverScopeParam() !== '';
                    $('specBar').classList.toggle('hidden', !scopeEmpty); $('mainArea').classList.add('hidden');
                    $('boardMsg').textContent = scopeEmpty
                        ? 'Tanlangan qamrovda darslar yo\'q — "Butun doska"ni tanlang.'
                        : 'Kartochkalar hali yaratilmagan — "Kartochkalarni yaratish"ni bosing.';
                    if (scopeEmpty) {
                        renderMineUi();
                        // "Butun doska": tanlov ro'yxati (spec_index) bo'sh javobda ham ko'rinsin; tanlangan qamrov yuklanmagan bo'lsa — so'raladi.
                        if (specList.length) { fillSpecControls(); ensureScopeLoaded(); }
                    }
                    syncUrl();
                    return false;
                }
                $('boardMsg').textContent = '';
                $('specBar').classList.remove('hidden'); $('mainArea').classList.remove('hidden');
                if ((!curSpec || !specList.find(s => s.key === curSpec.key)) && specList.length) curSpec = specList.find(s => !s.idx) || specList[0];
                fillSpecControls();
                fillGridInputs();   // hafta yangi panjaraga moslashtiriladi (fillWeekSel)
                if (weekNeedsReload()) {
                    loadBoard(board.id).catch(e => alert('Xatolik: ' + e.message));
                    return true;
                }
                renderAll();
                ensureScopeLoaded();
                return true;
            }

            function buildSpecList() {
                const seen = {};
                specList = [];
                cards.forEach(c => {
                    // Kalitga fakultetni ham qo'shamiz — bir yo'nalish (mas.
                    // "davolash ishi") bir nechta fakultetда bo'lса ham
                    // ular alohida qolsin (aks holda biri ikkinchisini yutadi).
                    const fac = c.faculty_name || '';
                    const k = fac + '|' + c.specialty_name + '|' + c.course;
                    if (!seen[k]) { seen[k] = 1; specList.push({ key: k, specialty_name: c.specialty_name, course: c.course, faculty: fac }); }
                });
                // "Butun doska" (cheklangan rol): tanlov uchun doskadagi boshqa yo'nalish+kurslar ham (idx — hali yuklanmagan).
                if (TIMETABLE_SCOPED_DATA && scopeMode === 'all') specIndex.forEach(r => {
                    const k = (r[0] || '') + '|' + r[1] + '|' + (+r[2]);
                    if (!seen[k]) { seen[k] = 1; specList.push({ key: k, specialty_name: r[1], course: +r[2], faculty: r[0] || '', idx: true }); }
                });
                specList.sort((a, b) =>
                    (a.faculty + '|' + a.specialty_name + a.course).localeCompare(b.faculty + '|' + b.specialty_name + b.course, 'uz'));
            }

            // ===== Ko'p tanlovli tanlov: Fakultet → Yo'nalish → Kurs (dropdown) =====
            // Uch o'lcham ham checkbox dropdown'idan tanlanadi (bir nechtasini
            // birga ko'rsatish mumkin). selectedFaculties/selectedDirs/selectedCourses
            // to'plamlari ko'rinishni (specCards) va bo'shatish qamrovini boshqaradi.
            const facLabel = f => f || '— (fakultetsiz)';
            const facultiesList = () => [...new Set(specList.map(s => s.faculty))].sort((a, b) => a.localeCompare(b, 'uz'));
            // Tanlangan fakultet(lar)ga tegishli yo'nalishlar; fakultet(lar)+yo'nalish(lar)ga tegishli kurslar.
            const availDirs = () => [...new Set(specList.filter(s => selectedFaculties.has(s.faculty)).map(s => s.specialty_name))]
                .sort((a, b) => a.localeCompare(b, 'uz'));
            const availCourses = () => [...new Set(specList
                .filter(s => selectedFaculties.has(s.faculty) && selectedDirs.has(s.specialty_name)).map(s => s.course))]
                .sort((a, b) => a - b);

            // Asosiy (primary) curSpec — panjara sozlamalari paneli va sozlama saqlash uchun.
            function setPrimarySpec() {
                const fac = [...selectedFaculties].sort((a, b) => a.localeCompare(b, 'uz'))[0];
                const dir = [...selectedDirs].sort((a, b) => a.localeCompare(b, 'uz'))[0];
                const crs = [...selectedCourses].sort((a, b) => a - b)[0];
                curSpec = specList.find(s => s.faculty === fac && s.specialty_name === dir && s.course === crs)
                    || specList.find(s => s.faculty === fac && s.specialty_name === dir)
                    || specList.find(s => s.faculty === fac)
                    || specList[0] || null;
            }
            // Tanlovlarni mavjud variantlarga moslaymiz (kamida bittasi tanlangan bo'ladi).
            // seed=true bo'lsa — curSpec (yoki birinchi variant)dan boshlab to'ldiramiz.
            function reconcileSelection(seed) {
                const facs = facultiesList();
                if (seed && TEACHER_DEFAULTS) {
                    // O'qituvchi: o'z darslari bor (yuklangan) hamma fakultet, yo'nalish va kurslar (tanlov bo'sh — birinchi ochilish);
                    // "Butun doska"da ro'yxatdagi yuklanmagan yo'nalishlar tanlanmaydi (butun doska so'ralmasin).
                    const own = specList.filter(x => !x.idx);
                    selectedFaculties = new Set(own.map(x => x.faculty));
                    selectedDirs = new Set(own.map(x => x.specialty_name));
                    selectedCourses = new Set(own.map(x => x.course));
                }
                if (seed && !TEACHER_DEFAULTS) selectedFaculties = new Set(curSpec && facs.includes(curSpec.faculty) ? [curSpec.faculty] : (facs.length ? [facs[0]] : []));
                selectedFaculties = new Set([...selectedFaculties].filter(f => facs.includes(f)));
                if (!selectedFaculties.size && facs.length) selectedFaculties.add(facs[0]);

                const dirs = availDirs();
                if (seed && !TEACHER_DEFAULTS) selectedDirs = new Set(curSpec && dirs.includes(curSpec.specialty_name) ? [curSpec.specialty_name] : (dirs.length ? [dirs[0]] : []));
                selectedDirs = new Set([...selectedDirs].filter(d => dirs.includes(d)));
                if (!selectedDirs.size && dirs.length) selectedDirs.add(dirs[0]);

                const courses = availCourses();
                if (seed && !TEACHER_DEFAULTS) selectedCourses = new Set(curSpec && courses.includes(curSpec.course) ? [curSpec.course] : (courses.length ? [courses[0]] : []));
                selectedCourses = new Set([...selectedCourses].filter(c => courses.includes(c)));
                if (!selectedCourses.size && courses.length) selectedCourses.add(courses[0]);

                setPrimarySpec();
            }

            // Bitta dropdown'ni chizadi: menyu ichiga checkboxlar + tugma yozuvi (xulosa).
            function renderDD(id, title, items) {
                const menu = $(id + 'Menu');
                const chosen = items.filter(it => it.checked);
                const tools = items.length > 1
                    ? '<div class="tt-dd-tools"><button type="button" data-dd-all="' + id + '">Barchasi</button>' +
                      '<button type="button" data-dd-one="' + id + '">Faqat asosiy</button></div>' : '';
                menu.innerHTML = tools + (items.map(it =>
                    '<label class="tt-dd-item"><input type="checkbox" value="' + esc(it.v) + '"' + (it.checked ? ' checked' : '') + '>' +
                    esc(it.label) + '</label>').join('') || '<div class="tt-dd-empty">—</div>');
                let sum;
                if (!items.length) sum = '—';
                else if (chosen.length === items.length && items.length > 1) sum = 'Barchasi (' + items.length + ')';
                else if (chosen.length <= 1) sum = chosen.length ? chosen[0].label : '—';
                else sum = chosen.length + ' ta tanlandi';
                $(id + 'Btn').innerHTML = '<span class="tt-dd-ttl">' + title + ':</span> ' +
                    '<span class="tt-dd-sum">' + esc(sum) + '</span> <span class="tt-dd-caret">▾</span>';
            }
            // Uchala dropdown'ni joriy tanlov holatiga qarab qayta chizadi.
            function fillSelectors() {
                renderDD('fac', 'Fakultet', facultiesList().map(f => ({ v: f, label: facLabel(f), checked: selectedFaculties.has(f) })));
                renderDD('dir', 'Yo\'nalish', availDirs().map(d => ({ v: d, label: d, checked: selectedDirs.has(d) })));
                renderDD('crs', 'Kurs', availCourses().map(c => ({ v: c, label: c + '-kurs', checked: selectedCourses.has(c) })));
            }
            // Boshlang'ich to'ldirish (loadBoard'dan). Tanlov bo'sh bo'lsa (yangi doska)
            // curSpec'dan urug'lantiramiz; aks holda mavjud tanlovni saqlab, mavjud
            // variantlarga moslaymiz (bo'shatishdan keyingi qayta yuklashda
            // ko'p tanlov yo'qolib qolmasin).
            function fillSpecControls() {
                const empty = !selectedFaculties.size && !selectedDirs.size && !selectedCourses.size;
                reconcileSelection(empty);
                fillSelectors();
            }

            // Checkbox o'zgarganda: tegishli to'plamni yangilaymiz, tanlovni moslaymiz, qayta chizamiz.
            function onDDChange(which, target) {
                const set = which === 'fac' ? selectedFaculties : which === 'dir' ? selectedDirs : selectedCourses;
                const val = which === 'crs' ? +target.value : target.value;
                if (target.checked) set.add(val); else set.delete(val);
                if (!set.size) { set.add(val); target.checked = true; }   // kamida bitta
                reconcileSelection(false);
                fillSelectors();
                selected = null; fillGridInputs(); renderAll();
                ensureScopeLoaded();
            }
            [['fac', 'facMenu'], ['dir', 'dirMenu'], ['crs', 'crsMenu']].forEach(([which, menuId]) => {
                $(menuId).addEventListener('change', ev => {
                    if (ev.target && ev.target.matches('input[type=checkbox]')) onDDChange(which, ev.target);
                });
                // "Barchasi" / "Faqat asosiy" tugmalari
                $(menuId).addEventListener('click', ev => {
                    const set = which === 'fac' ? selectedFaculties : which === 'dir' ? selectedDirs : selectedCourses;
                    const items = which === 'fac' ? facultiesList() : which === 'dir' ? availDirs() : availCourses();
                    if (ev.target.dataset.ddAll !== undefined && ev.target.dataset.ddAll) {
                        items.forEach(v => set.add(v));
                    } else if (ev.target.dataset.ddOne !== undefined && ev.target.dataset.ddOne) {
                        const keep = [...set].sort((a, b) => which === 'crs' ? a - b : String(a).localeCompare(String(b), 'uz'))[0];
                        set.clear(); if (keep != null) set.add(keep);
                    } else { return; }
                    reconcileSelection(false);
                    fillSelectors();
                    selected = null; fillGridInputs(); renderAll();
                    ensureScopeLoaded();
                });
            });
            // Tugmani bosish — menyuni ochish/yopish; tashqariga bosilsa yopiladi.
            document.addEventListener('click', ev => {
                const btn = ev.target.closest('.tt-dd-btn');
                const insideMenu = ev.target.closest('.tt-dd-menu');
                document.querySelectorAll('.tt-dd').forEach(dd => {
                    const menu = dd.querySelector('.tt-dd-menu');
                    if (btn && dd.contains(btn)) menu.classList.toggle('open');
                    else if (menu !== insideMenu) menu.classList.remove('open');
                });
            });

            // ===== Panjara sozlamasi (yo'nalish+kurs bo'yicha) =====
            function curGrid() {
                const visible = cards.filter(c => selectedFaculties.has(c.faculty_name || '') && selectedDirs.has(c.specialty_name) && selectedCourses.has(c.course));
                const calendars = visible.map(gridForCard);
                const base = calendars[0] || { days: board.days, pairs_per_day: board.pairs_per_day, weeks: board.weeks };
                return Object.assign({}, base, { weeks: Math.max(+base.weeks || 1, ...calendars.map(g => +g.weeks || 1)) });
            }
            function fillGridInputs() {
                // Panjara qiymatlari endi Sozlamalar modalidan boshqariladi.
                fillWeekSel();
            }

            // ===== Hafta tanlash (individual haftalar) =====
            // Semestr boshlanishi (doska sozlamasi / sikl jadvalidagi sana) — hafta sanalari uchun.
            function semesterStartDate() {
                const v = (board && board.settings && board.settings.semester_start) || ($('cycleStart') && $('cycleStart').value) || '';
                const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(v);
                if (!m) return null;
                const d = new Date(+m[1], +m[2] - 1, +m[3]);
                d.setDate(d.getDate() - ((d.getDay() + 6) % 7));   // o'sha haftaning dushanbasi
                return d;
            }
            // Yo'nalish+kurs kalendari: panjaraning o'z boshlanishi (bo'lmasa doska semestr boshi),
            // ta'til oralig'iga (settings.weekly_breaks) tushgan haftalar o'quv haftasi hisoblanmaydi.
            function gridStartDate(g) {
                const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String((g && g.start_date) || ''));
                if (!m) return semesterStartDate();
                const d = new Date(+m[1], +m[2] - 1, +m[3]);
                d.setDate(d.getDate() - ((d.getDay() + 6) % 7));
                return d;
            }
            function weekBreaks(g) {
                const toD = v => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(v || '')); return m ? new Date(+m[1], +m[2] - 1, +m[3]) : null; };
                return ((g && g.weekly_breaks) ?? ((board && board.settings && board.settings.weekly_breaks) || []))
                    .map(b => [toD(b && b.from), toD(b && b.to)]).filter(b => b[0] && b[1]);
            }
            // n-o'quv haftasining dushanbasi (tanlangan yo'nalish+kurs kalendari bo'yicha)
            function weekMonday(n, g) {
                const st = gridStartDate(g || curGrid());
                if (!st) return null;
                const br = weekBreaks(g || curGrid());
                const d = new Date(st);
                for (let k = 0, guard = 0; guard < 200; guard++, d.setDate(d.getDate() + 7)) {
                    if (br.some(([f, t]) => d >= f && d <= t)) continue;
                    if (++k >= n) return d;
                }
                return d;
            }
            function weekDates(n) {
                const a = weekMonday(n);
                if (!a) return '';
                const b = new Date(a); b.setDate(b.getDate() + Math.max(0, (board.days || 6) - 1));
                const f = d => String(d.getDate()).padStart(2, '0') + '.' + String(d.getMonth() + 1).padStart(2, '0');
                return f(a) + '–' + f(b);
            }
            // Bugun semestrning nechanchi haftasi (chegaradan chiqsa — 1 yoki oxirgi hafta).
            function currentWeekNo(w) {
                if (!gridStartDate(curGrid())) return 1;
                const today = new Date(); today.setHours(0, 0, 0, 0);
                for (let i = w; i >= 1; i--) { const m = weekMonday(i); if (m && m <= today) return i; }
                return 1;
            }
            // Ichki (haqiqiy) jadval faqat haftama-hafta ko'riladi — "shablon" yo'q.
            const weeklyOnly = () => typeof weeklyLayer !== 'undefined' && weeklyLayer === 'internal' && viewMode !== 'cycle';
            function fillWeekSel() {
                const w = +curGrid().weeks || +board.weeks || 15;
                // curWeek faqat 0 (shablon) yoki 1..w oralig'idagi butun son bo'lishi mumkin —
                // aks holda (URLdan kelgan noto'g'ri qiymat, qisqargan panjara) shablonga qaytamiz,
                // yo'qsa select'da mos variant bo'lmaydi va hafta istisnosi 422 bilan qaytadi.
                if (!Number.isInteger(curWeek) || curWeek < 0 || curWeek > w) curWeek = 0;
                const only = weeklyOnly();
                const now = currentWeekNo(w);
                if (only && !curWeek) curWeek = now;   // ichki jadval — joriy hafta bilan ochiladi
                let opts = only ? '' : '<option value="0">Barcha haftalar (shablon)</option>';
                for (let i = 1; i <= w; i++) {
                    const dates = weekDates(i);
                    opts += '<option value="' + i + '">' + i + '-hafta' + (dates ? ' (' + dates + ')' : '') + (i === now && semesterStartDate() ? ' • joriy' : '') + '</option>';
                }
                $('weekSel').innerHTML = opts;
                $('weekSel').value = String(curWeek);
                if ($('weekPrev')) $('weekPrev').disabled = curWeek <= (only ? 1 : 0);
                if ($('weekNext')) $('weekNext').disabled = curWeek >= w;
            }
            function stepWeek(delta) {
                const w = +curGrid().weeks || +board.weeks || 15;
                const next = Math.min(w, Math.max(weeklyOnly() ? 1 : 0, (curWeek || 0) + delta));
                if (next === curWeek) return;
                $('weekSel').value = String(next);
                $('weekSel').onchange.call($('weekSel'));
            }
            if ($('weekPrev')) $('weekPrev').onclick = () => stepWeek(-1);
            if ($('weekNext')) $('weekNext').onclick = () => stepWeek(1);
            // Haftalik fanlar: har hafta qaysi kartochka o'tilishi — KTR'dan (ma'ruza haftalari, amaliy soati).
            if ($('ktrWeeksBtn')) $('ktrWeeksBtn').onclick = async function () {
                if (!board) return;
                const body = scopeBody();
                this.disabled = true;
                try {
                    const dry = await api(BASE + '/boards/' + board.id + '/ktr-weeks', 'POST', Object.assign({ dry_run: 1 }, body));
                    const msg = 'Qamrov: ' + scopeLabelText() + '\n\n' +
                        dry.cards + ' ta kartochka KTR bo\'yicha haftalarga taqsimlanadi\n' +
                        '(' + dry.weeks_on + ' ta hafta yoqiladi, ' + dry.weeks_off + ' ta o\'chiriladi).' +
                        (dry.no_ktr.length ? '\n\nKTR topilmagan fanlar (o\'zgarmaydi): ' + dry.no_ktr.slice(0, 8).join('; ') + (dry.no_ktr.length > 8 ? '…' : '') : '') +
                        (dry.mismatch_count ? '\n\nDiqqat: ' + dry.mismatch_count + ' ta haftada KTR soatiga kartochkalar yetmaydi (masalan: ' + dry.mismatch[0] + ').' : '') +
                        '\n\nDavom etamizmi?';
                    if (!confirm(msg)) return;
                    const res = await api(BASE + '/boards/' + board.id + '/ktr-weeks', 'POST', body);
                    $('boardMsg').textContent = 'KTR bo\'yicha: ' + res.cards + ' ta kartochka haftalari yangilandi';
                    await loadBoard(board.id);
                } catch (e) { alert('Xatolik: ' + e.message); }
                finally { this.disabled = false; }
            };
            // ===== Registrator: HEMIS bilan solishtirish (faqat o'qiydi, taklif beradi) =====
            let hemisSyncLast = null;
            let hemisSyncUntil = null;
            let hemisSyncPeriod = null;  // {from, to} — hisob davri (haftalar); null — 1-hafta…joriy hafta
            let hemisSyncFilter = { missingRoomOnly: false, onlyDiff: true, periodMatch: true, finished: false, ops: { create: true, update: true, delete: true, blocked: true }, blk: { room: true, teacher: true, other: true }, subjects: null, groups: null };   // subjects / groups: null — barcha fanlar / guruhlar   // null — joriy hafta oxirigacha (sukut), 0 — semestr oxirigacha
            function hemisSyncModal(html) {
                let m = $('hemisSyncModal');
                if (!m) {
                    m = document.createElement('div');
                    m.id = 'hemisSyncModal';
                    m.className = 'fixed inset-0 z-[9999] bg-black/40 flex items-start justify-center p-4 overflow-auto';
                    m.onclick = e => { if (e.target === m) m.remove(); };
                    document.body.appendChild(m);
                }
                m.innerHTML = '<div class="bg-white rounded-xl shadow-xl w-full max-w-6xl p-4 text-[12px]">' + html + '</div>';
                return m;
            }
            // Ochiladigan ro'yxatlar (Fanlar / Guruhlar): tashqariga bosilsa yoki Esc bosilsa — yopiladi.
            // Ro'yxat ichidagi tugma oynani qayta chizsa (bosilgan element DOM'dan chiqadi) — yopilmaydi: apply() uni qayta ochadi.
            document.addEventListener('click', e => {
                if (!e.target.isConnected) return;
                document.querySelectorAll('#hemisSyncModal details.hs-pick[open]').forEach(d => { if (!d.contains(e.target)) d.open = false; });
            });
            document.addEventListener('keydown', e => {
                if (e.key === 'Escape') document.querySelectorAll('#hemisSyncModal details.hs-pick[open]').forEach(d => { d.open = false; });
            });
            const hsEsc = v => String(v == null ? '' : v).replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
            const hsSigned = n => (n > 0 ? '+' : '') + n;
            function hsUnitMatches(u) {
                if ((u.actions || []).length || u.actions_later || (u.notes || []).length) return false;
                for (const k of ['hours_diff', 'count_diff']) if (Object.values(u.before[k] || {}).some(v => +v)) return false;
                const p = u.period;
                if (p) {
                    if (Object.keys(u.code_names).some(c => (+p.ktr_hours[c] || 0) !== (+p.hemis_hours[c] || 0))) return false;
                    if (['L', 'A'].some(x => Object.values(u.codes).includes(x) && (+p.ktr_count[x] || 0) !== (+p.hemis_count[x] || 0))) return false;
                }
                return true;
            }
            // Qismlar: ma'ruza va "amaliy qism" (ma'ruzadan boshqa hamma tur) — har biri jurnalda kunma-kun ustun.
            const HS_PART = { L: 'Ma\'ruza', A: 'Amaliy qism' };
            const HS_A_TITLE = ' title="Amaliy qism — ma\'ruzadan boshqa barcha turlar: amaliy, seminar, laboratoriya, klinik mashg\'ulot. Bir kunda qaysi biri bo\'lsa ham — jurnalda bitta ustun."';
            // Fan filtri: null — hammasi; aks holda tanlangan fan nomlari.
            const hsSubjOk = u => !hemisSyncFilter.subjects || hemisSyncFilter.subjects.includes(u.subject_name);
            // Guruh filtri: null — hammasi; aks holda tanlangan guruhlar (rep.groups[].group). Fan filtri bilan birga (ikkalasi ham).
            const hsGroupOk = g => !hemisSyncFilter.groups || hemisSyncFilter.groups.includes(g.group);
            const hsGroupNames = rep => [...new Set(rep.groups.map(g => g.group))].sort((a, b) => a.localeCompare(b));
            // Filtr panelidagi ochiladigan ro'yxat: checkbox'lar, tepada "Hammasi / Hech biri".
            const hsPickBox = (key, label, all, picked) => {
                const sel = picked ? picked.filter(x => all.includes(x)) : all;
                return '<details id="hs' + key + 'Box" class="hs-pick relative"><summary class="cursor-pointer border rounded px-2 py-0.5 bg-white">' + label + ': ' +
                    (sel.length === all.length ? 'hammasi' : sel.length + ' / ' + all.length) + '</summary>' +
                    '<div class="absolute z-10 mt-1 bg-white border rounded shadow p-2 max-h-72 overflow-auto w-96">' +
                    '<div class="mb-1"><button type="button" id="hs' + key + 'All" class="underline mr-2">Hammasi</button><button type="button" id="hs' + key + 'None" class="underline">Hech biri</button></div>' +
                    all.map((n, i) => '<label class="flex items-center gap-1"><input type="checkbox" class="hs-pick-' + key + '" data-i="' + i + '"' + (sel.includes(n) ? ' checked' : '') + '> ' + hsEsc(n) + '</label>').join('') +
                    '</div></details>';
            };
            // Fan filtri ro'yxati: solishtirilgan va o'tkazilgan (skipped) fanlar — o'tkazilganning sababini ham tanlab ko'rish mumkin.
            const hsSubjectNames = rep => [...new Set(rep.groups.flatMap(g => [...g.units, ...(g.skipped || [])].map(x => x.subject_name)))]
                .sort((a, b) => a.localeCompare(b));
            // Joylanmagan kartalar (HEMIS'ga yozilmaydi): guruh filtri bo'yicha; bitta karta bir nechta guruhda bo'lsa — bir marta.
            const hsUnplaced = rep => {
                const u = rep.unplaced || {};
                const weekly = ((u.weekly && u.weekly.items) || []).filter(hsGroupOk);
                const cycle = ((u.cycle && u.cycle.items) || []).filter(hsGroupOk);
                const cycleCards = new Set(cycle.map(i => i.key)).size;
                // Ichki jadvaldagi to'qnashuvlar (o'qituvchi/xona band): darslar (karta-hafta yoki sikl bloki) bo'yicha.
                const conflicts = ((u.conflicts && u.conflicts.items) || []).filter(hsGroupOk);
                return { weekly, cycle, cycleCards, cardWeeks: new Set(weekly.flatMap(i => i.weeks.map(w => i.card_id + '|' + w))).size,
                    cards: new Set(weekly.map(i => i.card_id)).size + cycleCards,
                    conflicts, conflictLessons: new Set(conflicts.map(i => i.lesson)).size };
            };
            // To'qnashuvlar jadvali: guruh, fan, sana (sikl — oraliq), vaqt, kim yoki qaysi xona band va kim bilan.
            function hsConflictListHtml(un) {
                return '<table class="w-full text-[11px]"><thead><tr class="text-left"><th>Guruh</th><th>Fan</th><th>Sana</th><th>Vaqt</th><th>Kim / qaysi xona band, kim bilan</th></tr></thead><tbody>' +
                    un.conflicts.map(i => '<tr><td>' + hsEsc(i.group) + '</td><td>' + hsEsc(i.subject) + '</td><td>' + hsEsc(i.dates || String(i.date).split('-').reverse().join('.')) +
                        '</td><td>' + hsEsc(i.time || '') + '</td><td>' + hsEsc(i.text) + '</td></tr>').join('') + '</tbody></table>';
            }
            let hsUnplacedOpen = false;   // "Ro'yxat" ochiqmi (qayta chizishda saqlanadi)
            const hsWeekRanges = ws => ws.reduce((acc, w) => {
                const last = acc[acc.length - 1];
                if (last && w === last[1] + 1) last[1] = w; else acc.push([w, w]);
                return acc;
            }, []).map(([a, b]) => a === b ? String(a) : a + '–' + b).join(', ');
            // Guruh bo'yicha ro'yxat (natija oynasidagi banner va oldindan ogohlantirish oynasi uchun bir xil).
            function hsUnplacedListHtml(un) {
                const TYPE = { lecture: 'ma\'ruza', practice: 'amaliy' };
                const byGroup = {};
                un.weekly.forEach(i => (byGroup[i.group] = byGroup[i.group] || []).push([i.subject, hsEsc(i.subject) + ' (' + TYPE[i.type] + '): ' + hsWeekRanges(i.weeks) + '-hafta']));
                un.cycle.forEach(i => (byGroup[i.group] = byGroup[i.group] || []).push([i.subject, hsEsc(i.subject) + ' (' + TYPE[i.type] + ', sikl): ' + i.days + ' kun']));
                return Object.keys(byGroup).sort((a, b) => a.localeCompare(b)).map(g => '<div><b>' + hsEsc(g) + '</b>: ' +
                    byGroup[g].sort((a, b) => a[0].localeCompare(b[0])).map(x => x[1]).join('; ') + '</div>').join('');
            }
            // Ogohlantirish bilan o'chiriladigan HEMIS darslari — JSON meta va ogohlantirish uchun: LMS'da joylanmagani uchun (lms_unplaced) va
            // guruh o'qimaydigan bo'lak darslari (not_studied); by_reason — sababi bo'yicha soni.
            const HS_DEL_REASONS = { lms_unplaced: 'LMSda joylanmagan', not_studied: 'guruh bu bo\'lakni o\'qimaydi' };
            function hsUnplacedDeletes(groups) {
                const by = {};
                const byReason = { lms_unplaced: 0, not_studied: 0 };
                let count = 0;
                (groups || []).forEach(g => (g.units || []).forEach(u => (u.actions || []).forEach(a => {
                    if (a.op !== 'delete' || !(a.reason_code in byReason)) return;
                    const part = ((u.codes || {})[a.code] === 'L') ? 'Ma\'ruza' : 'Amaliy qism';
                    const k = a.reason_code + '|' + g.group + '|' + u.subject_name + '|' + part;
                    by[k] = by[k] || { group: g.group, subject: u.subject_name, part, reason_code: a.reason_code, weeks: [], count: 0 };
                    by[k].count++;
                    byReason[a.reason_code]++;
                    count++;
                    if (a.week) by[k].weeks.push(+a.week);
                })));
                return { count, by_reason: byReason,
                    by_unit: Object.values(by).map(x => Object.assign(x, { weeks: hsWeekRanges([...new Set(x.weeks)].sort((a, b) => a - b)) })) };
            }
            // "LMSda joylanmagan — x ta, guruh bu bo'lakni o'qimaydi — y ta" (soni bor sabablar).
            const hsDelReasonsText = br => Object.keys(HS_DEL_REASONS).filter(k => br[k]).map(k => HS_DEL_REASONS[k] + ' — ' + br[k] + ' ta').join(', ');
            // JSON (HEMIS'ga yozish uchun) — faqat filtrda tanlangan guruh, fan va amallar; meta: unplaced_deletes (xatcho'p boshlashda so'raydi).
            function hsJsonOut(rep) {
                const out = JSON.parse(JSON.stringify(rep));
                out.groups = out.groups.filter(hsGroupOk);
                out.groups.forEach(g => g.units.forEach(u => { u.actions = hsSubjOk(u) ? u.actions.filter(hsOpOk) : []; }));
                out.unplaced_deletes = hsUnplacedDeletes(out.groups);
                return out;
            }
            // Sariq blok: joylanmagan haftalari bor birliklar (balanslanmadi) va ular sababli o'chiriladigan darslar (JSON'dagidek).
            function hsUnplacedWeeksBanner(rep) {
                const units = (rep.unplaced_units || []).filter(x => hsGroupOk({ group: x.group }) && hsSubjOk({ subject_name: x.subject }));
                const ud = hsJsonOut(rep).unplaced_deletes;
                if (!units.length && !ud.count) return '';
                return '<div class="mb-2 p-2 rounded border border-amber-300 bg-amber-50 text-amber-900" data-hs-unplaced-weeks>'
                    + (ud.count ? '<div class="font-semibold text-red-700" data-hs-unplaced-deletes>⚠ Diqqat: ' + ud.count + ' ta dars HEMIS\'dan o\'chiriladi ('
                        + hsEsc(hsDelReasonsText(ud.by_reason)) + ')</div>'
                        + '<ul class="ml-4 list-disc">' + ud.by_unit.map(x => '<li>' + hsEsc(x.group + ' · ' + x.subject + ' · ' + x.part + (x.weeks ? ': ' + x.weeks + '-hafta' : '')
                            + ' — ' + x.count + ' ta' + (x.reason_code === 'not_studied' ? ' (guruh bu bo\'lakni o\'qimaydi)' : '')) + '</li>').join('') + '</ul>' : '')
                    + (units.length ? '<div class="mt-1"><b>LMSda joylanmagan haftalar</b> — balanslanmadi (joylanishi kutilmoqda):</div><ul class="ml-4 list-disc">'
                        + units.map(x => '<li>' + hsEsc(x.group + ' · ' + x.subject + ' · ' + x.part + ': ' + x.weeks + '-hafta')
                            + (x.deletes ? ' <span class="text-red-700">(HEMIS\'dan o\'chiriladi: ' + x.deletes + ' ta)</span>' : '') + '</li>').join('') + '</ul>' : '')
                    + '</div>';
            }
            function hsUnplacedBanner(rep) {
                const un = hsUnplaced(rep);
                if (!un.cardWeeks && !un.cycleCards) return '';
                const list = hsUnplacedListHtml(un);
                return '<div id="hsUnplacedBanner" class="mb-2 p-2 rounded border border-red-400 bg-red-50 text-red-800">⚠ Hali joylanmagan kartalar bor: ' +
                    [un.cardWeeks ? 'haftalik — ' + un.cardWeeks + ' ta karta-hafta' : '', un.cycleCards ? 'sikl — ' + un.cycleCards + ' ta karta' : ''].filter(Boolean).join(', ') +
                    '. Ular HEMIS\'ga yozilmaydi. <button type="button" id="hsUnplacedToggle" class="underline ml-1">Ro\'yxat</button>' +
                    '<div id="hsUnplacedList" class="mt-1' + (hsUnplacedOpen ? '' : ' hidden') + '">' + list + '</div></div>';
            }
            // "Bu davrda mos": tanlangan davrgacha amali yo'q, keyingi haftalarda bor ("Bu davrda moslar" belgisi olinsa yashiriladi).
            const hsPeriodMatch = u => !u.actions.length && (u.actions_later || 0) > 0;
            // Amal qatori: qisqa xulosa (HEMIS → LMS), to'siq belgilari (xona / o'qituvchi band — alohida rangda),
            // pastda batafsil: kim, qachon, qaysi guruh va fan band qilgan; so'ng sabab.
            const HS_BLOCK = {
                room: { label: 'Xona band', cls: 'bg-orange-100 text-orange-800 border-orange-300' },
                teacher: { label: 'O\'qituvchi band', cls: 'bg-purple-100 text-purple-800 border-purple-300' },
            };
            const hsChangeShort = c => {
                const m = /^([^:]+):\s*(.*?)\s*→\s*(.*)$/.exec(String(c));
                if (!m) return hsEsc(c);
                const what = m[1].charAt(0).toUpperCase() + m[1].slice(1);
                return '<b>' + hsEsc(what) + ':</b> HEMIS\'da <span class="line-through">' + hsEsc(m[2] || '—') + '</span> → LMS\'da <b>' + hsEsc(m[3]) + '</b>';
            };
            function hsActionHtml(a, u) {
                const opName = { create: 'Qo\'shish', update: 'O\'zgartirish', delete: 'O\'chirish' };
                const opCls = { create: 'text-emerald-700', update: 'text-amber-700', delete: 'text-red-700' };
                const blocks = a.blocks || [];
                // Tuzilgan tafsiloti yo'q to'siqlar (para vaqti yo'q, o'qituvchi/xona topilmadi) — alohida, matni bilan.
                const covered = new Set(blocks.map(b => b.text));
                const other = (a.blocked || []).filter(m => !covered.has(m));
                const types = [...new Set(blocks.map(b => b.type))];
                const chips = types.map(t => '<span class="ml-1 px-1.5 rounded border text-[10px] font-semibold ' + HS_BLOCK[t].cls + '">⛔ ' + HS_BLOCK[t].label + '</span>').join('')
                    + (other.length ? '<span class="ml-1 px-1.5 rounded border text-[10px] font-semibold bg-red-100 text-red-700 border-red-300">⛔ To\'siq</span>' : '')
                    // Bartaraf etilgan to'siq: band o'qituvchi/xona o'rniga kafedra mudiri / mudir xonasi qo'yilgan.
                    + (a.resolved || []).map(b => '<span class="ml-1 px-1.5 rounded border text-[10px] font-semibold bg-emerald-50 text-emerald-700 border-emerald-300" title="' + hsEsc((b.source || '') + ' · ' + (b.group || '') + ' · «' + (b.subject || '') + '» ' + (b.time || '')) + '">✔ ' + (b.type === 'room' ? 'Xona band → mudir xonasi' : 'O\'qituvchi band → kafedra mudiri') + '</span>').join('');
                // Balanslash darsi (jurnal ustuni KTR bilan teng bo'lishi uchun; bandliksiz) — alohida belgi; muddatdan keyingisi — hozir yozilmaydi.
                const bal = a.balance ? '<span class="ml-1 px-1.5 rounded border text-[10px] font-semibold bg-sky-50 text-sky-800 border-sky-300" data-hs-balance'
                    + ' title="Dars soni KTR\'dan kam: guruh keladigan eng yaqin kunga, bandlik tekshirilmaydi">Balanslash'
                    + (a.balance_week ? ' — ' + (+a.balance_week) + '-hafta darsi o‘rniga' : '') + '</span>' : '';
                const later = a.later ? ' <i class="text-gray-400">(hozir yozilmaydi)</i>' : '';
                const head = '<div' + (a.later ? ' class="text-gray-400"' : '') + '><span class="' + (a.later ? '' : opCls[a.op]) + ' font-semibold">' + opName[a.op] + '</span> · '
                    + hsEsc(a.date) + ' ' + hsEsc(a.start) + '–' + hsEsc(a.end)
                    + ' · ' + hsEsc((u && u.code_names[a.code]) || a.code) + ' · ' + hsEsc(a.employee_name || '—') + ' · ' + hsEsc(a.auditorium_name || '—') + bal + chips + later + '</div>';
                const summary = (a.changes && a.changes.length) ? '<div class="ml-3 text-gray-700">' + a.changes.map(hsChangeShort).join(' · ') + '</div>' : '';
                const details = blocks.map(b => '<div class="ml-3 mt-0.5 px-1.5 py-0.5 rounded border ' + HS_BLOCK[b.type].cls + '">' +
                    (b.type === 'room'
                        ? '<b>' + hsEsc(b.room || '') + '</b>-xona ' + hsEsc(b.time) + ' da band'
                        : '<b>' + hsEsc(b.teacher || 'O\'qituvchi') + '</b> ' + hsEsc(b.time) + ' da boshqa darsda')
                    + ': ' + hsEsc(b.source || '') + ' · ' + hsEsc(b.group || '') + ' · «' + hsEsc(b.subject || '') + '»'
                    + (b.type === 'room' && b.teacher ? ' · o\'qituvchi: ' + hsEsc(b.teacher) : '')
                    + (b.type === 'teacher' && b.room ? ' · xona: ' + hsEsc(b.room) : '')
                    + (b.other_groups ? ' · yana ' + (+b.other_groups) + ' ta guruh' : '') + '</div>').join('')
                    + (other.length ? '<div class="ml-3 mt-0.5 text-red-700">' + hsEsc(other.join('; ')) + '</div>' : '');
                const flags = (a.flags && a.flags.length) ? ' <span class="text-indigo-600 text-[10px]">[' + hsEsc(a.flags.join(', ')) + ']</span>' : '';
                const reason = a.reason ? '<div class="ml-3 text-gray-500 italic text-[10px]">Sabab: ' + hsEsc(a.reason) + flags + '</div>' : (flags ? '<div class="ml-3">' + flags + '</div>' : '');
                return '<div class="mb-1.5 pb-1 border-b border-dashed border-gray-200">' + head + summary + details + reason + '</div>';
            }
            // To'siq turi: xona band / o'qituvchi band / boshqa (o'qituvchi yoki xona topilmadi, para yo'q...).
            const hsBlockKinds = a => {
                const k = new Set((a.blocks || []).map(b => b.type));
                if (!k.size || (a.blocked || []).length > (a.blocks || []).length) k.add('other');
                return [...k];
            };
            const hsOpOk = a => (!hemisSyncFilter.missingRoomOnly || a.missing_room) && ((a.blocked && a.blocked.length)
                ? hemisSyncFilter.ops.blocked && hsBlockKinds(a).some(k => hemisSyncFilter.blk[k])
                : !!hemisSyncFilter.ops[a.op]);
            function hemisSyncRender(rep) {
                const F = hemisSyncFilter;
                let tot = { create: 0, update: 0, delete: 0, blocked: 0, later: 0, hidden: 0, opHidden: 0, periodHidden: 0, finishedHidden: 0 };
                // Amal turi yoki to'siq turi bo'yicha filtr tanlangan bo'lsa — shu filtrga tushadigan amali yo'q fanlar ko'rsatilmaydi.
                const opsNarrowed = !(F.ops.create && F.ops.update && F.ops.delete && F.ops.blocked && F.blk.room && F.blk.teacher && F.blk.other);
                let body = '';
                const pf = rep.period_from, pt = rep.period_to;
                const missingRoomCount = rep.groups.filter(hsGroupOk).reduce((n, g) => n + g.units.filter(hsSubjOk).reduce((m, u) => m + (u.missing_room_lessons || []).length, 0), 0);
                for (const g of rep.groups) {
                    if (!hsGroupOk(g)) continue;
                    // Fan filtrida tanlanmaganlar "mos" emas — yashirilgan mos fanlar soniga qo'shilmaydi.
                    const picked = g.units.filter(hsSubjOk).filter(u => !F.missingRoomOnly || (u.missing_room_lessons || []).length || (u.actions || []).some(a => a.missing_room));
                    const shown = picked.filter(u => !(F.onlyDiff && hsUnitMatches(u)));
                    tot.hidden += picked.length - shown.length;
                    // Faqat ko'rinish: bu fanlarning tanlangan davrda amali yo'q — Excel / JSON / to'siq xabarlari o'zgarmaydi.
                    const inPeriod = F.periodMatch ? shown : shown.filter(u => !hsPeriodMatch(u));
                    tot.periodHidden += shown.length - inPeriod.length;
                    const units = opsNarrowed ? inPeriod.filter(u => u.actions.some(hsOpOk)) : inPeriod;
                    tot.opHidden += inPeriod.length - units.length;
                    shown.filter(u => !units.includes(u)).forEach(u => { tot.later += u.actions_later || 0; });
                    // Mos fanlar yashirilsa ham guruhning ogohlantirishlari (o'tkazilgan fanlar, HEMIS rejasida topilmagan kartochkalar) qoladi.
                    // Amal/to'siq turi filtri tanlanganda — faqat shu turdagi amali bor fanlar; o'tkazilgan fanlar va
                    // HEMIS rejasida topilmagan kartochkalar (amal emas, ma'lumot) ko'rsatilmaydi.
                    const skippedPicked = opsNarrowed ? [] : g.skipped.filter(x => !hemisSyncFilter.subjects || hemisSyncFilter.subjects.includes(x.subject_name));
                    // Darslari tugagan fanlar (bugun va o'tgan kunlar HEMIS'da tahrirlanmaydi — qiladigan ish yo'q) sukutda yashirin;
                    // "joylanmagan" va "kartochka yo'q" — haqiqiy muammo, doim ko'rinadi.
                    const skippedShown = F.missingRoomOnly ? [] : (F.finished ? skippedPicked : skippedPicked.filter(x => x.kind !== 'finished'));
                    tot.finishedHidden += skippedPicked.length - skippedShown.length;
                    const noSubjCards = opsNarrowed || F.missingRoomOnly ? [] : (g.cards_without_subject || []);
                    if (!units.length && !skippedShown.length && !noSubjCards.length) continue;
                    body += '<h4 class="mt-4 mb-1 font-semibold text-[13px]">' + hsEsc(g.group) +
                        ' <span class="text-gray-400 font-normal">· HEMIS import: ' + hsEsc(g.imported_at || '—') + '</span></h4>';
                    body += '<table class="w-full border text-[11px]"><thead class="bg-gray-50"><tr>' +
                        '<th class="border px-1 text-left">Fan</th>' +
                        '<th class="border px-1" title="Tanlangan hisob davridagi haftalar: KTR bo\'yicha kerak, HEMIS\'da qo\'yilgan va LMS ichki jadvalida bor">Davr ' + (g.period_from || pf) + '–' + (g.period_to || pt) + '-hafta<br><span class="font-normal text-gray-500">soat va dars kunlari</span></th>' +
                        '<th class="border px-1" title="Balans davri (haftalik fan — 1-haftadan «HEMIS\'ga yozish» muddatigacha, sikl — blok): (HEMIS bugungacha + LMS ertadan muddatgacha) − KTR. Musbat — ortiqcha, manfiy — kam; o\'qdan keyin — takliflar qo\'llangandan keyin">Balans: soat farqi<br><span class="font-normal text-gray-500">(hozir → takliflardan keyin)</span></th>' +
                        '<th class="border px-1" title="Balans davri bo\'yicha dars kunlari (jurnal ustunlari) farqi">Balans: dars kunlari farqi</th><th class="border px-1 text-left">Tuzatish takliflari</th>' +
                        '<th class="border px-1">HEMIS amallari</th></tr></thead><tbody>';
                    for (const u of units) {
                        const p = u.period;
                        const per = p ? Object.keys(u.code_names).map(c => {
                            const k = +p.ktr_hours[c] || 0, h = +p.hemis_hours[c] || 0;
                            return '<div class="' + (k !== h ? 'text-red-600' : 'text-gray-500') + '"><b>' + hsEsc(u.code_names[c]) + '</b> soati — KTR ' + k + ' · HEMIS ' + h + '</div>';
                        }).join('') + ['L', 'A'].filter(x => Object.values(u.codes).includes(x)).map(x => {
                            const k = +p.ktr_count[x] || 0, h = +p.hemis_count[x] || 0, l = +p.lms_count[x] || 0;
                            return '<div class="' + (k !== h ? 'text-red-600' : 'text-gray-500') + '"' + (x === 'A' ? HS_A_TITLE : '') + '><b>' + HS_PART[x] + '</b> kunlari — KTR ' + k + ' · HEMIS ' + h + ' · LMS ' + l + '</div>';
                        }).join('') : '';
                        // Guruh o'qimaydigan bo'lak (not_studied): KTR / balans yo'q — faqat HEMIS'dagi ertangi darslarini o'chirish.
                        const ns = !!u.not_studied;
                        const hd = ns ? '' : Object.keys(u.code_names).map(c => {
                            const b = u.before.hours_diff[c] || 0, a = u.after.hours_diff[c] || 0;
                            return '<div class="' + (a ? 'text-red-600' : (b ? 'text-amber-700' : 'text-gray-400')) + '">' + hsEsc(u.code_names[c]) + ' soati: ' +
                                (b || a ? hsSigned(-b) + ' → ' + hsSigned(-a) : '0') + '</div>';
                        }).join('');
                        const cd = ns ? '' : ['L', 'A'].filter(x => Object.values(u.codes).includes(x)).map(x => {
                            const b = u.before.count_diff[x] || 0, a = u.after.count_diff[x] || 0;
                            return '<div class="' + (a ? 'text-red-600' : (b ? 'text-amber-700' : 'text-gray-400')) + '"' + (x === 'A' ? HS_A_TITLE : '') + '>' + HS_PART[x] + ' kunlari: ' +
                                (b || a ? hsSigned(-b) + ' → ' + hsSigned(-a) : '0') + '</div>';
                        }).join('');
                        // "HEMIS'ga yozish" chegarasidan keyingi takliflar — kulrang, hozir yozilmaydi.
                        const fx = u.fixes.map(f => {
                            const later = g.until && f.date && f.date > g.until;
                            const wk = later ? (rep.weeks || []).find(w => f.date >= w.from && f.date <= w.to) : null;
                            return later
                                ? '<div class="text-gray-400">• ' + hsEsc(f.text) + ' <i>(' + (wk ? wk.week + '-hafta' : 'keyingi hafta') + ' — hozir yozilmaydi)</i></div>'
                                : '<div>• ' + hsEsc(f.text) + '</div>';
                        }).join('') +
                            // Sikl fani: blokka sig'magan kamomad — qizil belgi, qisqartirib bo'lmagan ortiqcha — sariq.
                            u.notes.map(n => /^Sikl bloki oxirigacha sig'madi/.test(n)
                                ? '<div class="text-red-700"><span class="inline-block px-1 mr-1 rounded bg-red-600 text-white text-[10px] font-bold">SIKL</span>⚠ ' + hsEsc(n) + '</div>'
                                : /^Sikl blokida ortiqcha/.test(n)
                                    ? '<div class="text-amber-700"><span class="inline-block px-1 mr-1 rounded bg-amber-400 text-amber-950 text-[10px] font-bold">SIKL</span>⚠ ' + hsEsc(n) + '</div>'
                                    : '<div class="text-red-600">⚠ ' + hsEsc(n) + '</div>').join('');
                        const acts = u.actions.filter(hsOpOk);
                        const cnt = { create: 0, update: 0, delete: 0 };
                        tot.later += u.actions_later || 0;
                        acts.forEach(a => { if (a.blocked && a.blocked.length) tot.blocked++; else { cnt[a.op]++; tot[a.op]++; } });
                        const list = acts.map(a => hsActionHtml(a, u)).join('');
                        const missingList = F.missingRoomOnly && (u.missing_room_lessons || []).length
                            ? '<details class="text-violet-700"><summary>Xonasi bo‘sh: ' + u.missing_room_lessons.length + ' ta dars</summary>'
                                + u.missing_room_lessons.map(l => '<div>' + hsEsc(l.date + ' ' + l.start + '–' + l.end + ' · ' + (l.employee_name || '—') + ' · ' + (l.auditorium_name || 'xona bog‘lanmagan')) + '</div>').join('') + '</details>' : '';
                        const nBlk = acts.filter(a => a.blocked && a.blocked.length).length;
                        // Fan rejimi va balans davri: shu davr bo'yicha KTR / HEMIS (bugungacha) / LMS (ertadan muddatgacha) — dars / soat.
                        const bs = u.balance_stats;
                        const balLine = u.mode_label && !ns ? '<div class="text-gray-500" data-hs-mode>' + hsEsc(u.mode_label)
                            + (u.balance_period ? ' · balans ' + hsEsc(u.balance_period) : '')
                            + (bs && u.balance_period ? ': KTR ' + bs.ktr.count + ' / ' + bs.ktr.hours + ' · HEMIS ' + bs.hemis.count + ' / ' + bs.hemis.hours
                                + ' · LMS ' + bs.lms.count + ' / ' + bs.lms.hours + ' <span class="text-gray-400">(dars / soat)</span>' : '') + '</div>' : '';
                        const laterBal = (u.later_balance || []).map(a => hsActionHtml(a, u)).join('');
                        // H < muddat: LMS'da joylanmagan haftalar — sariq belgi (balanslanmadi, joylanishi kutilmoqda).
                        const unplacedBadge = u.unplaced_label ? '<div class="mt-0.5 px-1 rounded bg-amber-100 text-amber-800 border border-amber-300" data-hs-unplaced>'
                            + hsEsc(u.unplaced_label) + '</div>' : '';
                        // Bo'lakli fan: umumiy ma'ruza boshqa bo'lakda hisoblanadi; o'qimaydigan bo'lak — tekshirilgan dalillar bilan.
                        const lectureNote = u.lecture_note ? '<div class="text-gray-500" data-hs-lecture-note>' + hsEsc(u.lecture_note) + '</div>' : '';
                        const nsBadge = ns ? '<div class="mt-0.5 px-1 rounded bg-gray-100 text-gray-600 border border-gray-300" data-hs-not-studied>guruh bu bo\'lakni o\'qimaydi'
                            + ((u.not_studied_checks || []).length ? ' (' + hsEsc(u.not_studied_checks.join(' · ')) + ')' : '')
                            + ' — faqat HEMIS\'dagi ertangi darslari o\'chiriladi</div>' : '';
                        const dash = '<span class="text-gray-400">—</span>';
                        body += '<tr class="align-top' + (ns ? ' bg-gray-50 text-gray-600' : '') + '"><td class="border px-1">' + hsEsc(u.subject_name)
                            + (u.cycle ? ' <span class="px-1 rounded bg-sky-100 text-sky-700 text-[10px]" title="Sikl fani: HEMIS LMS ichki sikl jadvaliga aynan moslashtiriladi (KTR balansi — faqat ma\'lumot)">sikl</span>' : '') + '<div class="text-gray-400">' + hsEsc(u.kafedra || '') + '</div>' + balLine + lectureNote + unplacedBadge + nsBadge + '</td>' +
                            '<td class="border px-1 whitespace-nowrap">' + (ns ? dash : per) + '</td>' +
                            '<td class="border px-1 whitespace-nowrap">' + (ns ? dash : hd) + '</td><td class="border px-1 whitespace-nowrap">' + (ns ? dash : cd) + '</td>' +
                            '<td class="border px-1">' + (fx || '<span class="text-gray-400">—</span>') + '</td>' +
                            '<td class="border px-1">' + (acts.length
                                ? '<details><summary class="cursor-pointer">+' + cnt.create + ' · ~' + cnt.update + ' · −' + cnt.delete + (nBlk ? ' · ⛔' + nBlk : '') + '</summary>' + list + '</details>'
                                : (u.actions.length ? '<span class="text-gray-400">filtrda yashirin</span>'
                                    // Tanlangan haftagacha amal yo'q, lekin keyingi haftalarda bor — "mos" emas (filtrda ham yashirilmaydi).
                                    : u.actions_later ? '<span class="text-emerald-600">bu davrda mos</span><div class="text-amber-700">keyingi haftalarda ' + u.actions_later + ' ta amal</div>'
                                    : '<span class="text-emerald-600">mos</span>')) + laterBal + missingList + '</td></tr>';
                    }
                    // Fan filtri tanlangan bo'lsa — o'tkazilgan fanlar ham faqat tanlanganlari.
                    for (const sk of skippedShown) {
                        body += '<tr class="text-gray-500"><td class="border px-1">' + hsEsc(sk.subject_name) + '</td><td class="border px-1" colspan="5" data-hs-skip="' + hsEsc(sk.kind || '') + '">' + hsEsc(sk.reason) + '</td></tr>';
                    }
                    body += '</tbody></table>';
                    if (noSubjCards.length) {
                        body += '<div class="text-amber-700 mt-1">HEMIS o\'quv rejasida topilmagan kartochkalar: ' + hsEsc(noSubjCards.join('; ')) + '</div>';
                    }
                }
                const wkOpt = (sel, label) => (rep.weeks || []).map(w => '<option value="' + w.week + '"' + (w.week === sel ? ' selected' : '') + '>' + label(w) + (w.week === rep.current_week ? ' • joriy' : '') + '</option>').join('');
                const chk = (id, on, text) => '<label class="inline-flex items-center gap-1 mr-2"><input type="checkbox" id="' + id + '"' + (on ? ' checked' : '') + '> ' + text + '</label>';
                const head = '<div class="flex flex-wrap items-center gap-2 mb-2"><h3 class="font-semibold text-[14px] flex-1">HEMIS solishtirish · ' + hsEsc(scopeLabelText()) +
                    ' · bugun ' + hsEsc(rep.today) + '</h3>' +
                    '<button type="button" id="hsExcel" class="tt-weekly-excel">Excel</button>' +
                    '<button type="button" id="hsJson" class="tt-ktr-weeks-btn">JSON (HEMIS\'ga yozish uchun)</button>' +
                    '<button type="button" id="hsTickets" class="tt-ktr-weeks-btn" title="Filtrdagi to\'siqlar bo\'yicha o\'qituvchi va kafedra mudiriga Telegram orqali so\'rov">📨 To\'siqlar bo\'yicha xabar</button>' +
                    '<button type="button" id="hsTicketList" class="tt-ktr-weeks-btn">So\'rovlar</button>' +
                    // Xatcho'p: HEMIS sahifasida bosilganda mark'dagi yozish oynasini ochadi (JSON fayl tanlanadi).
                    '<a href="' + hsEsc("javascript:(function(){var s=document.createElement('script');s.charset='utf-8';s.src='" + HS_WRITER_URL + "?v='+Date.now();document.body.appendChild(s);})();") + '"' +
                    ' onclick="alert(\'Bu xatcho\\\'p: uni sichqoncha bilan brauzerning xatcho\\\'plar paneliga torting. Keyin HEMIS sahifasida (kirib turgan holda) shu xatcho\\\'pni bosing va yuklab olingan JSON faylni tanlang.\'); return false;"' +
                    ' title="Sichqoncha bilan xatcho\'plar paneliga torting, so\'ng HEMIS sahifasida bosing" class="px-2 py-1 rounded border border-indigo-400 bg-indigo-50 text-indigo-700 cursor-move">⭐ HEMIS\'ga yozish (xatcho\'p)</a>' +
                    '<button type="button" id="hsClose" class="px-2 py-1 border rounded">Yopish</button></div>' +
                    '<div class="text-violet-700 mb-1">Xonasi bo‘sh: ' + missingRoomCount + ' ta dars (mudir xonasi qo‘yiladi)</div>' +
                    hsUnplacedBanner(rep) + hsUnplacedWeeksBanner(rep) +
                    '<div class="flex flex-wrap items-center gap-3 mb-2 p-2 bg-gray-50 rounded border">' +
                    '<label class="text-gray-700">Hisob davri: <select id="hsPFrom" class="border rounded px-1 py-0.5 text-[12px]">' + wkOpt(pf, w => w.week + '-hafta (' + hsEsc(w.from) + ')') + '</select>' +
                    ' – <select id="hsPTo" class="border rounded px-1 py-0.5 text-[12px]">' + wkOpt(pt, w => w.week + '-hafta oxiri (' + hsEsc(w.to) + ')') + '</select></label>' +
                    '<label class="text-gray-700">HEMIS\'ga yozish: <select id="hsUntil" class="border rounded px-1 py-0.5 text-[12px]">' +
                    wkOpt(rep.until_week, w => w.week + '-hafta oxirigacha (' + hsEsc(w.to) + ')') +
                    '<option value="0"' + (!rep.until_week ? ' selected' : '') + '>Semestr oxirigacha</option></select></label>' +
                    '<span class="text-gray-700">' + chk('hsMissingRooms', F.missingRoomOnly, 'Faqat xonasi bo‘sh') + chk('hsOnlyDiff', F.onlyDiff, 'Faqat farqi borlar') +
                    chk('hsPeriodMatch', F.periodMatch, '<span title="Tanlangan davrgacha amali yo\'q, keyingi haftalarda amali bor fanlar">Bu davrda moslar</span>') +
                    chk('hsFinished', F.finished, '<span title="LMS ichki jadvalida ertadan keyin darsi yo\'q fanlar — bugun va o\'tgan kunlar HEMIS\'da tahrirlanmaydi">Tugagan fanlar</span>') +
                    chk('hsOpC', F.ops.create, 'Qo\'shish') + chk('hsOpU', F.ops.update, 'O\'zgartirish') + chk('hsOpD', F.ops.delete, 'O\'chirish') + chk('hsOpB', F.ops.blocked, 'To\'siqli') +
                    '<span class="ml-1 pl-2 border-l border-gray-300' + (F.ops.blocked ? '' : ' opacity-40') + '">To\'siq turi: ' +
                    chk('hsBlkRoom', F.blk.room, '<span class="px-1 rounded bg-orange-100 text-orange-800">Xona band</span>') +
                    chk('hsBlkTeacher', F.blk.teacher, '<span class="px-1 rounded bg-purple-100 text-purple-800">O\'qituvchi band</span>') +
                    chk('hsBlkOther', F.blk.other, '<span class="px-1 rounded bg-red-100 text-red-700">Boshqa</span>') +
                    '<button type="button" id="hsOnlyBlocked" class="ml-1 underline text-[11px]">faqat to\'siqlilar</button></span>' + '</span>' +
                    hsPickBox('Subj', 'Fanlar', hsSubjectNames(rep), F.subjects) +
                    hsPickBox('Group', 'Guruhlar', hsGroupNames(rep), F.groups) + '</div>' +
                    '<div class="text-gray-600 mb-1">Haftalik fan balansi «HEMIS\'ga yozish» muddatigacha: KTR (1-haftadan muddat haftasigacha) = HEMIS (bugungacha o\'tilgan) + LMS ichki jadvali (ertadan muddatgacha); muddatdan keyingi haftalar bu safar hisoblanmaydi. ' +
                    '«Har hafta» fanda har hafta darslar soni va soati KTR qatoridan oshmaydi. Dars soni yetmasa — <b>balanslash darsi</b>: guruh keladigan eng yaqin kunga (shu qism yo\'q kun), bandlik tekshirilmaydi. Sikl fani — blok bo\'yicha. ' +
                    '«Hisob davri» faqat shu haftalardagi KTR / HEMIS / LMS yig\'indilarini ko\'rsatadi, «HEMIS\'ga yozish» esa qaysi haftagacha amal chiqishini belgilaydi. Bugun va undan oldingi kunlarga tegilmaydi.</div>' +
                    '<div class="text-gray-500 mb-1 text-[11px]"><b>Soati</b> — akademik soat (1 para = 2 soat). <b>Kunlari</b> — necha kunda o\'tilgani (jurnaldagi ustunlar soni). ' +
                    '<b>Amaliy qism</b> — ma\'ruzadan boshqa barcha turlar (amaliy, seminar, laboratoriya, klinik): bir kunda qaysi biri bo\'lsa ham bitta ustun. ' +
                    '<b>KTR</b> — reja bo\'yicha kerak, <b>HEMIS</b> — HEMIS\'da qo\'yilgan, <b>LMS</b> — mark ichki jadvalida. Teng bo\'lmasa — qizil.</div>' +
                    '<div class="text-gray-600 mb-1">Ko\'rsatilgan amallar: <b class="text-emerald-700">+' + tot.create + '</b> qo\'shish, <b class="text-amber-700">~' + tot.update + '</b> o\'zgartirish, ' +
                    '<b class="text-red-700">−' + tot.delete + '</b> o\'chirish' + (tot.blocked ? ', <b class="text-red-600">' + tot.blocked + ' ta to\'siqli</b>' : '') +
                    (tot.later ? ' · tanlangan haftadan keyin yana ' + tot.later + ' ta amal (hozir yozilmaydi)' : '') +
                    (tot.hidden ? ' · ' + tot.hidden + ' ta mos fan yashirildi' : '') +
                    (tot.opHidden ? ' · ' + tot.opHidden + ' ta fanda tanlangan turdagi amal yo\'q (yashirildi)' : '') +
                    (tot.periodHidden ? ' · ' + tot.periodHidden + ' ta fan bu davrda mos (yashirildi)' : '') +
                    (tot.finishedHidden ? ' · ' + tot.finishedHidden + ' ta tugagan fan (yashirildi)' : '') + '.' +
                    (rep.fallback_room ? '' : ' <b class="text-red-600">"Kafedra mudiri xonasi" auditoriyasi topilmadi — HEMIS\'da ochib, auditoriyalarni import qiling.</b>') +
                    (rep.groups_not_in_hemis.length ? '<div class="text-red-600">HEMIS\'da topilmagan guruhlar: ' + hsEsc(rep.groups_not_in_hemis.join(', ')) + '</div>' : '') + '</div>';
                hemisSyncModal(head + hemisInfoNoticeHtml(rep) + body);
                $('hsClose').onclick = () => $('hemisSyncModal').remove();
                if ($('hsUnplacedToggle')) $('hsUnplacedToggle').onclick = () => {
                    hsUnplacedOpen = !hsUnplacedOpen;
                    $('hsUnplacedList').classList.toggle('hidden', !hsUnplacedOpen);
                };
                $('hsTickets').onclick = () => hsTicketsSend(rep);
                $('hsTicketList').onclick = () => hsTicketsList();
                $('hsUntil').onchange = function () { hemisSyncUntil = +this.value; hemisSyncRun(); };
                const perChange = () => {
                    let a = +$('hsPFrom').value, b = +$('hsPTo').value;
                    if (b < a) [a, b] = [b, a];
                    hemisSyncPeriod = { from: a, to: b };
                    hemisSyncRun();
                };
                $('hsPFrom').onchange = perChange;
                $('hsPTo').onchange = perChange;
                const reFilter = () => {
                    F.onlyDiff = $('hsOnlyDiff').checked;
                    const missingRoomOnly = $('hsMissingRooms').checked;
                    if (missingRoomOnly && !F.missingRoomOnly) F.onlyDiff = false;
                    F.missingRoomOnly = missingRoomOnly;
                    F.periodMatch = $('hsPeriodMatch').checked;
                    F.finished = $('hsFinished').checked;
                    F.ops = { create: $('hsOpC').checked, update: $('hsOpU').checked, delete: $('hsOpD').checked, blocked: $('hsOpB').checked };
                    F.blk = { room: $('hsBlkRoom').checked, teacher: $('hsBlkTeacher').checked, other: $('hsBlkOther').checked };
                    hemisSyncRender(rep);
                };
                ['hsMissingRooms', 'hsOnlyDiff', 'hsPeriodMatch', 'hsFinished', 'hsOpC', 'hsOpU', 'hsOpD', 'hsOpB', 'hsBlkRoom', 'hsBlkTeacher', 'hsBlkOther'].forEach(id => { $(id).onchange = reFilter; });
                $('hsOnlyBlocked').onclick = () => {
                    F.ops = { create: false, update: false, delete: false, blocked: true };
                    hemisSyncRender(rep);
                };
                // Ochiladigan ro'yxat: belgilash — filtr (hammasi belgilansa null), qayta chizilgandan keyin ro'yxat ochiq qoladi.
                for (const [key, all, field] of [['Subj', hsSubjectNames(rep), 'subjects'], ['Group', hsGroupNames(rep), 'groups']]) {
                    const boxes = () => document.querySelectorAll('#hemisSyncModal .hs-pick-' + key);
                    const apply = () => {
                        const picked = [...boxes()].filter(c => c.checked).map(c => all[+c.dataset.i]);
                        F[field] = picked.length === all.length ? null : picked;
                        hemisSyncRender(rep);
                        if ($('hs' + key + 'Box')) $('hs' + key + 'Box').open = true;
                    };
                    boxes().forEach(c => { c.onchange = apply; });
                    $('hs' + key + 'All').onclick = () => { boxes().forEach(c => { c.checked = true; }); apply(); };
                    $('hs' + key + 'None').onclick = () => { boxes().forEach(c => { c.checked = false; }); apply(); };
                }
                $('hsJson').onclick = () => {
                    const un = hsUnplaced(rep);
                    if (un.cards && !confirm(un.cards + ' ta joylanmagan karta bor — ular HEMIS\'ga yozilmaydi. Baribir davom etamizmi?')) return;
                    // Yozish uchun JSON — faqat filtrda tanlangan guruh, fan va amallar (to'siqlilar baribir yozilmaydi); meta: unplaced_deletes.
                    const out = hsJsonOut(rep);
                    const blob = new Blob([JSON.stringify(out, null, 1)], { type: 'application/json' });
                    const a = document.createElement('a');
                    a.href = URL.createObjectURL(blob); a.download = 'hemis_amallar_' + rep.today + '.json';
                    document.body.appendChild(a); a.click(); a.remove();
                };
                $('hsExcel').onclick = async function () {
                    const fd = new FormData();
                    const add = (k, v) => fd.append(k, v);
                    add('_token', CSRF);
                    const sb = scopeBody();
                    Object.keys(sb).forEach(k => sb[k].forEach(v => add(k + '[]', v)));
                    // Faqat foydalanuvchi tanlagani yuboriladi: sukutda server har guruh uchun o'z joriy haftasini
                    // oladi (kalendari boshqacha guruhlar) — Excel oynadagi bilan bir xil bo'ladi.
                    if (hemisSyncUntil !== null) add('until_week', hemisSyncUntil);
                    if (hemisSyncPeriod) { add('period_from', hemisSyncPeriod.from); add('period_to', hemisSyncPeriod.to); }
                    add('only_diff', F.onlyDiff ? 1 : 0);
                    add('missing_room_only', F.missingRoomOnly ? 1 : 0);
                    add('ops_filter', 1);   // hech biri tanlanmasa ham — Excel'da amal bo'lmaydi
                    Object.keys(F.ops).filter(k => F.ops[k]).forEach(k => add('ops[]', k));
                    Object.keys(F.blk).filter(k => F.blk[k]).forEach(k => add('blk[]', k));
                    add('blk_filter', 1);
                    if (F.subjects) { add('subjects_filter', 1); F.subjects.forEach(n => add('subjects[]', n)); }
                    // Guruh filtri hisobotni toraytirmaydi ("groups[]" — qamrov, guruhlararo to'siqlar o'zgarardi), faqat chiqishni.
                    if (F.groups) { add('groups_filter', 1); F.groups.forEach(n => add('filter_groups[]', n)); }
                    // Forma yuborish o'rniga fetch: xato bo'lsa sahifa "ERR_INVALID_RESPONSE" bo'lib qolmaydi — sababi ko'rsatiladi.
                    const btn = this, html = btn.innerHTML;
                    btn.disabled = true; btn.textContent = 'Tayyorlanmoqda…';
                    try {
                        const r = await fetch(BASE + '/boards/' + board.id + '/hemis-sync/export', { method: 'POST', body: fd, headers: { Accept: 'application/json' } });
                        const blob = await r.blob();
                        const head = new Uint8Array(await blob.slice(0, 2).arrayBuffer());
                        if (!r.ok || head[0] !== 0x50 || head[1] !== 0x4B) {   // xlsx — "PK" (zip) bilan boshlanadi
                            let msg = 'HTTP ' + r.status;
                            try { const j = JSON.parse(await blob.text()); msg = j.error || j.message || msg; } catch (_) { }
                            throw new Error(msg);
                        }
                        const a = document.createElement('a');
                        a.href = URL.createObjectURL(new Blob([blob], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }));
                        a.download = 'hemis_solishtirish_' + rep.today + '.xlsx';
                        document.body.appendChild(a); a.click(); a.remove();
                        setTimeout(() => URL.revokeObjectURL(a.href), 5000);
                    } catch (e) {
                        alert('Excel faylini yaratib bo\'lmadi: ' + e.message);
                    } finally { btn.disabled = false; btn.innerHTML = html; }
                };
            }
            // "HEMIS solishtirish" bosilganda eng birinchi (HEMIS'siz, faqat LMS): qamrovda ichki jadvalda joylanmagan kartalar bo'lsa —
            // qizil oyna; "Baribir davom etish" — odatdagi hemisSyncAsk(). Joylanmagan bo'lmasa yoki xulosa olinmasa — darhol hemisSyncAsk().
            async function hemisUnplacedGate() {
                hemisSyncModal('<div class="p-6 text-center text-gray-500">Joylanmagan kartalar tekshirilmoqda… (' + hsEsc(scopeLabelText()) + ')</div>');
                let u;
                try {
                    u = await api(BASE + '/boards/' + board.id + '/unplaced-summary', 'POST', scopeBody());
                } catch (e) {
                    console.warn('Joylanmagan kartalar xulosasi olinmadi — ogohlantirishsiz davom etiladi:', e);
                    return hemisSyncAsk();
                }
                const un = hsUnplaced({ unplaced: u });
                const hasUnplaced = un.cardWeeks || un.cycleCards;
                if (!hasUnplaced && !un.conflictLessons) return hemisSyncAsk();
                const m = hemisSyncModal('<div id="hsUnpBox" class="p-3 rounded border border-red-400 bg-red-50 text-red-800">' +
                    '<h3 class="font-semibold text-[14px] mb-2">⛔ ' + (hasUnplaced ? 'Hali joylanmagan kartalar bor' : 'Ichki jadvalda to\'qnashuvlar bor') + '</h3>' +
                    (hasUnplaced
                        ? '<div id="hsUnpText" class="mb-2">Haftalik — ' + un.cardWeeks + ' ta karta-hafta, sikl — ' + un.cycleCards + ' ta karta. Ular HEMIS\'ga yozilmaydi, HEMIS\'da dars kam qoladi.</div>' +
                            '<details open class="mb-3"><summary class="cursor-pointer">Guruh bo\'yicha ro\'yxat</summary>' +
                            '<div id="hsUnpList" class="mt-1 max-h-72 overflow-auto">' + hsUnplacedListHtml(un) + '</div></details>'
                        : '') +
                    // O'qituvchi yoki xona shu vaqtda band — kafedra mudiriga almashtirilmaydi, HEMIS'ga yozilmaydi (to'siq).
                    (un.conflictLessons
                        ? '<details open id="hsUnpConflicts" class="mb-3"><summary class="cursor-pointer font-semibold">To\'qnashuvlar: ' + un.conflictLessons + ' ta dars</summary>' +
                            '<div class="text-[11px] my-1">O\'qituvchi yoki xona shu vaqtda boshqa darsda band — bunday darslar HEMIS\'ga yozilmaydi. O\'qituvchi yoki xonani almashtiring.</div>' +
                            '<div class="max-h-72 overflow-auto">' + hsConflictListHtml(un) + '</div></details>'
                        : '') +
                    '<div class="flex gap-2"><button type="button" id="hsUnpGo" class="px-3 py-1 rounded bg-red-600 text-white">Baribir davom etish</button>' +
                    // Diagnostika (unplaced-export) faqat haftalik kartalar bo'yicha — sikl kartalari unda yo'q; faqat sikl bo'lsa bo'sh fayl bo'lardi.
                    (un.cardWeeks ? '<button type="button" id="hsUnpExcel" class="tt-weekly-excel" title="Haftalik joylanmagan kartalar va sabablari (sikl kartalari bu faylga kirmaydi)">Excel (sabablar)</button>' : '') +
                    '<button type="button" id="hsUnpClose" class="px-3 py-1 rounded border bg-white">Yopish</button></div></div>');
                $('hsUnpGo').onclick = () => hemisSyncAsk();
                $('hsUnpClose').onclick = () => m.remove();
                if ($('hsUnpExcel')) $('hsUnpExcel').onclick = async function () {
                    // Mavjud "Joylanmagan kartalar" diagnostikasi — ichki jadval, shu qamrov bo'yicha.
                    const params = new URLSearchParams();
                    const sb = scopeBody();
                    Object.keys(sb).forEach(k => sb[k].forEach(v => params.append(k + '[]', v)));
                    params.set('layer', 'internal');
                    this.disabled = true;
                    try { await downloadUnplacedXlsx(params); }
                    catch (e) { alert('Diagnostika Excelini yuklab bo\'lmadi: ' + e.message); }
                    finally { this.disabled = false; }
                };
            }
            async function hemisSyncRun() {
                hemisSyncModal('<div class="p-6 text-center text-gray-500">HEMIS bilan solishtirilmoqda… (' + hsEsc(scopeLabelText()) + ')</div>');
                try {
                    // Sukut (until_week yuborilmasa) — server joriy hafta oxirigacha oladi.
                    const body = hemisSyncUntil === null ? scopeBody() : Object.assign({ until_week: hemisSyncUntil }, scopeBody());
                    if (hemisSyncPeriod) Object.assign(body, { period_from: hemisSyncPeriod.from, period_to: hemisSyncPeriod.to });
                    hemisSyncLast = await api(BASE + '/boards/' + board.id + '/hemis-sync', 'POST', body);
                    hemisSyncRender(hemisSyncLast);
                } catch (e) {
                    hemisSyncModal('<div class="p-4 text-red-600">' + hsEsc(hsErrText(e)) + '</div>' + HS_CLOSE);
                }
            }
            const HS_CLOSE = '<button type="button" class="px-2 py-1 border rounded" onclick="this.closest(\'#hemisSyncModal\').remove()">Yopish</button>';
            // "Failed to fetch" — brauzer mark serveriga yeta olmadi (internet/server), HEMIS emas.
            const hsErrText = e => /failed to fetch|networkerror|load failed/i.test(String(e && e.message))
                ? 'Mark serveri bilan aloqa yo\'q (internet yoki server javob bermayapti). Birozdan keyin qayta urinib ko\'ring.'
                : 'Xatolik: ' + (e && e.message);
            const hsAgo = ts => {
                if (!ts) return 'hali import qilinmagan';
                const m = Math.round((Date.now() - new Date(String(ts).replace(' ', 'T')).getTime()) / 60000);
                return hsEsc(ts) + ' (' + (m < 60 ? m + ' daqiqa' : m < 2880 ? Math.round(m / 60) + ' soat' : Math.round(m / 1440) + ' kun') + ' oldin)';
            };
            // 1-qadam: oxirgi import vaqtini ko'rsatib, shu ma'lumot bilan solishtirish yoki avval HEMIS'dan yangilashni so'raydi.
            async function hemisSyncAsk(note) {
                hemisSyncModal('<div class="p-6 text-center text-gray-500">Oxirgi HEMIS importi tekshirilmoqda…</div>');
                let st;
                try { st = await api(BASE + '/boards/' + board.id + '/hemis-sync/import-status'); }
                catch (e) { hemisSyncModal('<div class="p-4 text-red-600">' + hsEsc(hsErrText(e)) + '</div>' + HS_CLOSE); return; }
                if (st.running) return hemisSyncWaitImport();
                const job = st.job || {};
                hemisSyncModal('<h3 class="font-semibold text-[14px] mb-2">HEMIS solishtirish · ' + hsEsc(scopeLabelText()) + '</h3>' +
                    (note ? '<div class="text-red-600 mb-2">' + note + '</div>' : '') +
                    '<div class="text-gray-700 mb-1">Solishtirish HEMIS dars jadvalining mark\'dagi nusxasi bilan qilinadi.</div>' +
                    '<div class="mb-1">Oxirgi import: <b>' + hsAgo(st.last_import_at) + '</b>' +
                    (st.last_import_approx ? ' <span class="text-gray-500">(taxminan — to\'liq import hali qayd etilmagan, bu yozuvlarning oxirgi yangilanishi)</span>' : '') +
                    '. Har kecha 00:30 da avtomatik yangilanadi.</div>' +
                    (job.status === 'error' ? '<div class="text-amber-700 mb-1">Oxirgi qo\'lda yangilash xato bilan tugagan: ' + hsEsc(job.message || '') + '</div>' : '') +
                    '<div class="mb-3 text-gray-600">Shu ma\'lumot bilan solishtiraymi yoki avval HEMIS\'dan yangilab olaymi?</div>' +
                    '<div class="flex gap-2"><button type="button" id="hsUseLast" class="px-3 py-1 rounded bg-emerald-600 text-white">Shu ma\'lumot bilan solishtirish</button>' +
                    '<button type="button" id="hsReimport" class="px-3 py-1 rounded border border-emerald-600 text-emerald-700">HEMIS\'dan yangilab, keyin solishtirish</button>' + HS_CLOSE + '</div>');
                $('hsUseLast').onclick = () => hemisSyncRun();
                $('hsReimport').onclick = async () => {
                    try { await api(BASE + '/boards/' + board.id + '/hemis-sync/import', 'POST', {}); }
                    catch (e) { return hemisSyncAsk(hsEsc(hsErrText(e))); }
                    hemisSyncWaitImport();
                };
            }
            // Import tugashini kutadi (job holati keshda); tugasa — solishtiradi, xato bo'lsa — oxirgi ma'lumotni taklif qiladi.
            // Oyna yopilsa kutish to'xtaydi (import serverda davom etadi) — oyna qayta ochilib turmaydi.
            async function hemisSyncWaitImport() {
                let skip = false;   // "Kutmasdan…" — holat so'ralayotgan paytda bosilsa ham yo'qolmaydi
                for (let i = 0; i < 400; i++) {
                    let st;
                    try { st = await api(BASE + '/boards/' + board.id + '/hemis-sync/import-status'); }
                    catch (e) { st = null; }
                    if (!$('hemisSyncModal')) return;
                    if (skip) return hemisSyncRun();
                    const j = (st && st.job) || {};
                    if (st && !st.running && j.status === 'done') return hemisSyncRun();
                    if (st && !st.running && j.status !== 'queued') {
                        return hemisSyncAsk('HEMIS\'dan yangilab bo\'lmadi' + (j.message ? ': ' + hsEsc(j.message) : '') +
                            '. HEMIS hozir ishlamayotgan bo\'lishi mumkin — oxirgi import bilan solishtirish mumkin.');
                    }
                    const m = hemisSyncModal('<div class="p-6 text-center text-gray-600">HEMIS\'dan dars jadvali yangilanmoqda… ' +
                        (j.pages ? j.page + '/' + j.pages + ' sahifa' : '') + '<div class="text-[11px] text-gray-400 mt-1">' + hsEsc(j.message || '') + '</div>' +
                        '<div class="mt-3"><button type="button" id="hsStopWait" class="px-2 py-1 border rounded">Kutmasdan oxirgi import bilan solishtirish</button></div></div>');
                    $('hsStopWait').onclick = () => { skip = true; };
                    for (let k = 0; k < 6 && !skip && m.isConnected; k++) await new Promise(r => setTimeout(r, 500));
                    if (!m.isConnected) return;
                    if (skip) return hemisSyncRun();
                }
                hemisSyncAsk('Import juda uzoq davom etmoqda.');
            }
            if ($('hemisSyncBtn')) $('hemisSyncBtn').onclick = async function () {
                if (!board) return;
                this.disabled = true;
                hemisSyncUntil = null;
                hemisSyncPeriod = null;
                hemisSyncFilter.subjects = null;   // fan va guruh filtri qamrovga bog'liq — yangi solishtirishda hammasi
                hemisSyncFilter.groups = null;
                // Eng birinchi — joylanmagan kartalar (bo'lsa qizil oyna), so'ng odatdagi hemisSyncAsk().
                try { await hemisUnplacedGate(); } finally { this.disabled = false; }
            };
            // ===== "Bugungi darslar (HEMIS)": faqat bugun — o'zgartirish (o'qituvchi, xona, para vaqti), qo'shish va o'chirish =====
            // Bugun qo'shish/o'chirish faqat belgilanmagan (davomat/baho yo'q) darslar uchun; davomat olingan / baho qo'yilgan darsga
            // tegilmaydi (kulrang), belgilangan ortiqcha dars o'chirilmaydi (ma'lumot).
            const HT_STATUS = {
                update: ['O\'zgartiriladi', 'text-amber-700'], create: ['Qo\'shiladi', 'text-teal-700'], delete: ['O\'chiriladi', 'text-rose-700'], locked: ['Tegilmaydi', 'text-gray-500'], blocked: ['To\'siqli', 'text-red-700'],
                info: ['Ma\'lumot', 'text-sky-700'], ok: ['Mos', 'text-emerald-700'],
            };
            let hemisTodayLast = null;
            let hemisTodayGroup = '';   // oynadagi guruh filtri ('' — hammasi): ko'rinish, JSON va Excel
            let hemisTodaySubject = '';   // oynadagi fan filtri ('' — hammasi): ko'rinish, JSON va Excel
            let hemisTodayMissingRooms = false;
            const htRows = (rep, group, subject) => (rep.rows || []).filter(r => (!group || r.group === group) && (!subject || r.subject === subject)
                && (!hemisTodayMissingRooms || r.missing_room));
            const htSort = list => [...new Set(list)].filter(v => v != null && v !== '').sort((a, b) => String(a).localeCompare(String(b), undefined, { numeric: true }));
            // Bog'liq ro'yxatlar: guruhlar — tanlangan fan qatorlaridan, fanlar — tanlangan guruh qatorlaridan.
            const htGroups = (rep, subject) => htSort((rep.rows || []).filter(r => !subject || r.subject === subject).map(r => r.group));
            const htSubjects = (rep, group) => htSort((rep.rows || []).filter(r => !group || r.group === group).map(r => r.subject));
            const htDate = d => String(d || '').split('-').reverse().join('.');
            function hemisTodayHtml(rep, group, subject) {
                const rows = htRows(rep, group, subject);
                const n = s => rows.filter(r => r.status === s).length;
                const groups = htGroups(rep, subject);
                const subjects = htSubjects(rep, group);
                const head = '<div class="flex flex-wrap items-center gap-2 mb-2"><h3 class="font-semibold text-[14px] flex-1">Bugun (' + hsEsc(htDate(rep.today)) + '): ' +
                    rows.length + ' ta dars · ' + n('update') + ' ta o\'zgartiriladi · ' + n('create') + ' ta qo\'shiladi · ' + n('delete') + ' ta o\'chiriladi · ' + n('locked') + ' ta davomat/baho bor — tegilmaydi · ' + n('blocked') + ' ta to\'siqli</h3>' +
                    '<span class="text-violet-700">Xonasi bo‘sh: ' + (rep.rows || []).filter(r => (!group || r.group === group) && (!subject || r.subject === subject) && r.missing_room).length
                        + ' ta dars (mudir xonasi qo‘yiladi)</span>' +
                    '<label><input id="htMissingRooms" type="checkbox"' + (hemisTodayMissingRooms ? ' checked' : '') + '> Faqat xonasi bo‘sh</label>' +
                    '<select id="htGroup" class="border rounded px-1 py-0.5"><option value="">Barcha guruhlar</option>' +
                    groups.map(g => '<option value="' + hsEsc(g) + '"' + (g === group ? ' selected' : '') + '>' + hsEsc(g) + '</option>').join('') + '</select>' +
                    '<select id="htSubject" class="border rounded px-1 py-0.5"><option value="">Barcha fanlar</option>' +
                    subjects.map(x => '<option value="' + hsEsc(x) + '"' + (x === subject ? ' selected' : '') + '>' + hsEsc(x) + '</option>').join('') + '</select>' +
                    '<button type="button" id="htJson" class="tt-ktr-weeks-btn"' + (n('update') + n('create') + n('delete') ? '' : ' disabled') + '>JSON (HEMIS\'ga yozish uchun)</button>' +
                    // Xatcho'p: HEMIS sahifasida bosiladi, yuklangan JSON'dagi faqat bugungi to'siqsiz amallarni yozadi (o'zgartirish va
                    // o'chirishdan oldin davomat/baho jonli tekshiriladi, boshida "N ta dars o'zgartiriladi, M ta qo'shiladi..." tasdig'i,
                    // natija har dars bo'yicha).
                    '<a id="htWriter" href="' + hsEsc("javascript:(function(){var s=document.createElement('script');s.charset='utf-8';s.src='" + HS_WRITER_URL + "?v='+Date.now();document.body.appendChild(s);})();") + '"' +
                    ' onclick="alert(\'Bu xatcho\\\'p: uni sichqoncha bilan brauzerning xatcho\\\'plar paneliga torting. Avval «JSON» tugmasi bilan faylni yuklab oling, keyin HEMIS sahifasida (kirib turgan holda) xatcho\\\'pni bosing va shu faylni tanlang.\'); return false;"' +
                    ' title="Sichqoncha bilan xatcho\'plar paneliga torting, so\'ng HEMIS sahifasida bosing" class="px-2 py-1 rounded border border-indigo-400 bg-indigo-50 text-indigo-700 cursor-move">⭐ Bugungi o\'zgarishlarni yozish (xatcho\'p)</a>' +
                    '<button type="button" id="htExcel" class="tt-weekly-excel">Excel</button>' +
                    '<button type="button" id="htClose" class="px-2 py-1 border rounded">Yopish</button></div>' +
                    '<div class="text-gray-500 text-[11px] mb-2">O\'zgartirish (o\'qituvchi, xona, para vaqti), qo\'shish va o\'chirish: bugun qo\'shish/o\'chirish faqat belgilanmagan (davomat/baho yo\'q) darslar uchun. ' +
                    'Davomat olingan yoki baho qo\'yilgan darsga tegilmaydi — xatcho\'p yozishdan oldin HEMIS\'dan yana tekshiradi.' +
                    (rep.timing ? ' <span title="HEMIS\'ni kutish / jami">· ' + rep.timing.groups + ' guruh, HEMIS ' + (rep.timing.hemis_ms / 1000).toFixed(1) +
                        ' s / jami ' + (rep.timing.total_ms / 1000).toFixed(1) + ' s</span>' : '') + '</div>' +
                    (rep.missing_groups && rep.missing_groups.length ? '<div class="text-amber-700 mb-1">HEMIS\'da topilmagan guruhlar: ' + hsEsc(rep.missing_groups.join(', ')) + '</div>' : '') +
                    (rep.import_failed ? '<div class="text-red-700 mb-1">' + rep.import_failed + ' ta guruh jadvali HEMIS\'dan yangilanmadi (javob bermadi) — ularning o\'zgartirishlari to\'siqli.</div>' : '');
                const who = (a, b) => hsEsc(a || '—') + (b && b !== a ? ' → <b>' + hsEsc(b) + '</b>' : '');
                // LMS'da biriktirilmagan — kafedra mudiri / "Kafedra mudiri xonasi" qo'yiladi (HEMIS solishtirish bilan bir xil): belgi.
                const fbTag = text => ' <span class="ht-fb" style="font-size:10px;font-weight:600;border-radius:4px;padding:0 4px;background:#ede9fe;color:#5b21b6">' + text + '</span>';
                const body = rows.map(r => {
                    const st = HT_STATUS[r.status] || [r.status, ''];
                    const grey = r.status === 'locked' ? ' bg-gray-100 text-gray-400' : '';
                    const fb = r.fallback_teacher || r.fallback_room || r.placeholder;
                    const time = hsEsc(r.start + '–' + r.end) + (r.new_start && (r.new_start !== r.start || r.new_end !== r.end) ? ' → <b>' + hsEsc(r.new_start + '–' + r.new_end) + '</b>' : '');
                    const why = r.status === 'blocked' ? (r.blocked || []).join('; ') : (r.reason || (r.status === 'ok' ? 'mos' : ''));
                    return '<tr class="align-top' + grey + (fb && !grey ? ' bg-violet-50' : '') + '" data-status="' + r.status + '"' + (fb ? ' data-fallback="1"' : '') + '><td class="border px-1">' + hsEsc(r.group) + '</td>' +
                        '<td class="border px-1">' + hsEsc(r.subject) + (r.balance ? ' <span class="ht-balance" style="font-size:10px;font-weight:600;border-radius:4px;padding:0 4px;background:#e0f2fe;color:#075985"'
                            + ' title="HEMIS solishtirish qo\'ygan balanslash darsi (jurnal ustuni KTR bilan teng bo\'lishi uchun) — to\'qnashuv / bandlik emas">balanslash</span>' : '')
                            + '<div class="text-gray-400">' + hsEsc(r.type) + (r.hemis_id ? ' · #' + r.hemis_id : '') + '</div></td>' +
                        '<td class="border px-1 whitespace-nowrap">' + time + '</td>' +
                        '<td class="border px-1">' + who(r.employee_name, r.new_employee_name) + (r.fallback_teacher ? fbTag('kafedra mudiri') : '') +
                            (r.placeholder ? fbTag('vaqtincha: kafedra mudiri') : '') + '</td>' +
                        '<td class="border px-1">' + who(r.auditorium_name, r.new_auditorium_name) + (r.fallback_room ? fbTag('mudir xonasi') : '') + '</td>' +
                        '<td class="border px-1"><span class="font-semibold ' + (grey ? '' : st[1]) + '">' + st[0] + '</span>' + (why ? '<div>' + hsEsc(why) + '</div>' : '') +
                        (r.fallback_reason && r.fallback_reason !== why ? '<div class="text-violet-700">' + hsEsc(r.fallback_reason) + '</div>' : '') +
                        (r.note ? '<div class="text-amber-700">' + hsEsc(r.note) + '</div>' : '') + '</td></tr>';
                }).join('');
                return head + hemisInfoNoticeHtml(rep) + (body ? '<div class="max-h-[70vh] overflow-auto"><table class="w-full border text-[11px]"><thead class="bg-gray-50 sticky top-0"><tr>' +
                    ['Guruh', 'Fan', 'Vaqt', 'O\'qituvchi', 'Xona', 'Holat'].map(h => '<th class="border px-1">' + h + '</th>').join('') + '</tr></thead><tbody>' + body + '</tbody></table></div>'
                    : '<div class="text-gray-500">Bugun qamrovda dars yo\'q.</div>');
            }
            // Xatcho'p uchun JSON: faqat to'siqsiz amallar — o'zgartirish, qo'shish, o'chirish (server tayyorlagan, today: true), tanlangan
            // guruh va fan bo'yicha. Filtr (fan yoki "faqat xonasi bo'sh") bo'lsa — aynan jadvalda ko'ringan qatorlar (o'zgartirish/o'chirish —
            // hemis_id, qo'shish — key); amali qolmagan birlik va guruh tushib qoladi.
            function hemisTodayJson(rep, group, subject) {
                const out = JSON.parse(JSON.stringify(rep.json || {}));
                const HT_OPS = ['update', 'create', 'delete'];
                const keyOf = (op, x) => op === 'create' ? 'c:' + x.key : 'h:' + (+x.hemis_id);
                const ids = new Set(htRows(rep, group, subject).filter(r => HT_OPS.includes(r.status)).map(r => keyOf(r.status, r)));
                const byRows = Boolean(subject) || hemisTodayMissingRooms;
                out.groups = (out.groups || []).filter(g => !group || g.group === group)
                    .map(g => Object.assign(g, { units: (g.units || []).map(u => Object.assign(u, { actions: (u.actions || []).filter(a => HT_OPS.includes(a.op) && a.today === true
                        && (!byRows || ids.has(keyOf(a.op, a)))) })).filter(u => u.actions.length) }))
                    .filter(g => g.units.length);
                return out;
            }
            function hemisTodayExcel(rep, group, subject) {
                const cell = (t, o) => Object.assign({ t: String(t == null ? '' : t) }, o || {});
                const rows = [['Guruh', 'Fan', 'Dars turi', 'HEMIS id', 'Vaqt (HEMIS)', 'Yangi vaqt', 'O\'qituvchi (HEMIS)', 'Yangi o\'qituvchi', 'Xona (HEMIS)', 'Yangi xona', 'Holat', 'Sabab / o\'zgarish', 'Fallback sababi']
                    .map(h => cell(h, { b: 1, bg: '#f3f4f6' }))];
                htRows(rep, group, subject).forEach(r => {
                    const grey = r.status === 'locked' ? { fc: '#9ca3af' } : null;
                    rows.push([r.group, r.subject, r.type, r.hemis_id || '', r.start + '–' + r.end, r.new_start ? r.new_start + '–' + r.new_end : '',
                        r.employee_name, r.new_employee_name || '', r.auditorium_name, r.new_auditorium_name || '', (HT_STATUS[r.status] || [r.status])[0],
                        [r.status === 'blocked' ? (r.blocked || []).join('; ') : r.reason, (r.changes || []).join('; '), r.note].filter(Boolean).join(' · '),
                        r.fallback_reason || ''].map(v => cell(v, grey || (r.fallback_teacher || r.fallback_room || r.placeholder ? { bg: '#f5f3ff' } : null))));
                });
                return { rows, sheet_title: 'Bugungi darslar', freeze_rows: 1 };
            }
            function hemisTodayRender(rep) {
                // Tanlangan guruh / fan bog'liq ro'yxatdan chiqib qolsa — "hammasi" ga tushadi (chizishdan oldin: jadval, son, JSON, Excel bir xil).
                if (hemisTodaySubject && !htSubjects(rep, hemisTodayGroup).includes(hemisTodaySubject)) hemisTodaySubject = '';
                if (hemisTodayGroup && !htGroups(rep, hemisTodaySubject).includes(hemisTodayGroup)) hemisTodayGroup = '';
                const m = hemisSyncModal(hemisTodayHtml(rep, hemisTodayGroup, hemisTodaySubject));
                $('htMissingRooms').onchange = e => { hemisTodayMissingRooms = e.target.checked; hemisTodayRender(rep); };
                $('htGroup').onchange = e => { hemisTodayGroup = e.target.value; hemisTodayRender(rep); };
                $('htSubject').onchange = e => { hemisTodaySubject = e.target.value; hemisTodayRender(rep); };
                $('htClose').onclick = () => m.remove();
                $('htJson').onclick = () => {
                    const blob = new Blob([JSON.stringify(hemisTodayJson(rep, hemisTodayGroup, hemisTodaySubject), null, 1)], { type: 'application/json' });
                    const a = document.createElement('a');
                    const safe = v => String(v).replace(/[^\w\-]+/g, '_');
                    a.href = URL.createObjectURL(blob); a.download = 'hemis_bugun_' + rep.today + (hemisTodayGroup ? '_' + safe(hemisTodayGroup) : '')
                        + (hemisTodaySubject ? '_' + safe(hemisTodaySubject) : '') + '.json';
                    document.body.appendChild(a); a.click(); a.remove();
                };
                $('htExcel').onclick = function () {
                    return sendExcelExport(hemisTodayExcel(rep, hemisTodayGroup, hemisTodaySubject), 'Bugungi darslar (HEMIS) · ' + htDate(rep.today) + ' · ' + scopeLabelText(),
                        'hemis_bugun_' + rep.today, this);
                };
            }
            async function hemisTodayRun() {
                hemisSyncModal('<div class="p-6 text-center text-gray-500">Bugungi darslar HEMIS bilan solishtirilmoqda… (' + hsEsc(scopeLabelText()) +
                    ')<div class="text-[11px] text-gray-400 mt-1">HEMIS\'dan bugungi jadval, davomat va baholar olinmoqda</div></div>');
                try {
                    hemisTodayLast = await api(BASE + '/boards/' + board.id + '/hemis-today', 'POST', scopeBody());
                    hemisTodayGroup = '';
                    hemisTodaySubject = '';
                    hemisTodayMissingRooms = false;
                    hemisTodayRender(hemisTodayLast);
                } catch (e) {
                    hemisSyncModal('<div class="p-4 text-red-600">' + hsEsc(hsErrText(e)) + '</div>' + HS_CLOSE);
                }
            }
            if ($('hemisTodayBtn')) $('hemisTodayBtn').onclick = async function () {
                if (!board) return;
                this.disabled = true;
                try { await hemisTodayRun(); } finally { this.disabled = false; }
            };
            // ===== HEMIS to'siqlari bo'yicha so'rovlar (Telegram: o'qituvchi / kafedra mudiri) =====
            const TICKET_FROM_URL = new URLSearchParams(location.search).get('ticket');
            const HS_TICKET_STATUS = { open: 'Ochiq', resolved: 'Hal qilindi', pending_registrar: 'Registrator tasdig\'ida', cancelled: 'Bekor qilingan' };
            const HS_DAY = ['', 'Dushanba', 'Seshanba', 'Chorshanba', 'Payshanba', 'Juma', 'Shanba', 'Yakshanba'];
            const HS_ROLE = { teacher: 'Dars o\'qituvchisi', head: 'Kafedra mudiri', blocker: 'Xonani band qilgan dars o\'qituvchisi' };
            // Oynadagi (filtrlangan) to'siqli amallar → so'rovlar: har to'siq turi alohida.
            function hsTicketItems(rep) {
                const items = [];
                for (const g of rep.groups) {
                    if (!hsGroupOk(g)) continue;
                    for (const u of g.units) {
                        if (!hsSubjOk(u)) continue;
                        for (const a of u.actions) {
                            if (!(a.blocked && a.blocked.length) || !a.card_id || !a.week || !hsOpOk(a)) continue;
                            for (const kind of hsBlockKinds(a)) {
                                if (!hemisSyncFilter.blk[kind]) continue;
                                const b = (a.blocks || []).find(x => x.type === kind) || null;
                                items.push({ card_id: a.card_id, week: a.week, date: a.date, start: a.start, end: a.end, type: kind, group: g.group,
                                    text: kind === 'other' ? a.blocked.filter(t => !(a.blocks || []).some(x => x.text === t)).join('; ') : (b && b.text) || a.blocked.join('; '),
                                    blocker: b ? { source: b.source, group: b.group, subject: b.subject, teacher: b.teacher, room: b.room, time: b.time } : null });
                            }
                        }
                    }
                }
                return items;
            }
            async function hsTicketsSend(rep) {
                const items = hsTicketItems(rep);
                if (!items.length) { alert('Filtrda yuboriladigan to\'siq yo\'q (bugungacha va tanlangan haftadan keyingilar hisobga olinmaydi).'); return; }
                if (!confirm(items.length + ' ta to\'siq bo\'yicha so\'rov yaratiladi va dars o\'qituvchisi, kafedra mudiri (xona band bo\'lsa — xonani band qilgan dars o\'qituvchisi ham) Telegram orqali xabar oladi. Yuboramizmi?')) return;
                // api() massivni "key[]" qilib yuboradi — obyektlar "[object Object]" bo'lib qolardi (422). Shuning uchun
                // Laravel tushunadigan items[i][maydon] (blocker uchun items[i][blocker][maydon]) kalitlari.
                const body = {};
                items.forEach((it, i) => Object.entries(it).forEach(([k, v]) => {
                    if (v && typeof v === 'object') Object.entries(v).forEach(([bk, bv]) => { body['items[' + i + '][' + k + '][' + bk + ']'] = bv; });
                    else body['items[' + i + '][' + k + ']'] = v;
                }));
                try {
                    const r = await api(BASE + '/boards/' + board.id + '/block-tickets', 'POST', body);
                    alert('Yaratildi: ' + r.created + ' ta so\'rov (o\'tkazildi: ' + r.skipped + ' — allaqachon ochiq yoki o\'tgan kun).\nTelegram xabarlari: ' + r.telegram_sent + ' ta.' +
                        (r.without_telegram.length ? '\n\nTelegram ulanmagan / topilmagan: ' + r.without_telegram.join(', ') : ''));
                } catch (e) { alert(hsErrText(e)); }
            }
            async function hsTicketsList() {
                if (!board) return;
                hemisSyncModal('<div class="p-6 text-center text-gray-500">To\'siq so\'rovlari yuklanmoqda…</div>');
                let j;
                try { j = await api(BASE + '/boards/' + board.id + '/block-tickets'); }
                catch (e) { hemisSyncModal('<div class="p-4 text-red-600">' + hsEsc(hsErrText(e)) + '</div>' + HS_CLOSE); return; }
                const rows = (j.tickets || []).map(t => '<tr class="align-top hover:bg-gray-50 cursor-pointer" data-ticket="' + t.id + '">' +
                    '<td class="border px-1">№' + t.id + '</td><td class="border px-1">' + hsEsc(t.lesson_date) + ' ' + hsEsc(t.start_time) + '–' + hsEsc(t.end_time) + '</td>' +
                    '<td class="border px-1">' + hsEsc(t.group_name) + '<div class="text-gray-500">' + hsEsc(t.subject_name) + '</div></td>' +
                    '<td class="border px-1">' + (HS_BLOCK[t.block_type] ? '<span class="px-1 rounded border ' + HS_BLOCK[t.block_type].cls + '">' + HS_BLOCK[t.block_type].label + '</span>' : 'Boshqa') + '</td>' +
                    '<td class="border px-1">' + (t.recipients || []).map(r => hsEsc(r.name) + ': ' + (r.response === 'accepted' ? '✅' : r.response === 'declined' ? '❌' : (r.chat_id ? '…' : '📵'))).join('<br>') + '</td>' +
                    '<td class="border px-1">' + hsEsc(HS_TICKET_STATUS[t.status] || t.status) + (t.can_resolve ? ' <b class="text-emerald-700">— hal qiling</b>' : '') + '</td></tr>').join('');
                hemisSyncModal('<div class="flex items-center mb-2"><h3 class="font-semibold text-[14px] flex-1">To\'siq so\'rovlari</h3>' + HS_CLOSE + '</div>' +
                    '<div class="text-gray-500 text-[11px] mb-2">✅ qabul qildi · ❌ rad etdi · … javob kutilmoqda · 📵 Telegram ulanmagan. Qatorni bosing — batafsil va hal qilish.</div>' +
                    (rows ? '<table class="w-full border text-[11px]"><thead class="bg-gray-50"><tr><th class="border px-1">№</th><th class="border px-1">Sana, vaqt</th><th class="border px-1">Guruh, fan</th><th class="border px-1">To\'siq</th><th class="border px-1">Javoblar</th><th class="border px-1">Holat</th></tr></thead><tbody>' + rows + '</tbody></table>'
                        : '<div class="text-gray-500">So\'rov yo\'q.</div>'));
                document.querySelectorAll('#hemisSyncModal [data-ticket]').forEach(tr => { tr.onclick = () => hsTicketOpen(tr.dataset.ticket); });
            }
            async function hsTicketOpen(id, day) {
                hemisSyncModal('<div class="p-6 text-center text-gray-500">So\'rov №' + hsEsc(id) + ' yuklanmoqda…</div>');
                let t;
                try { t = (await api(BASE + '/block-tickets/' + id + (day ? '?day=' + day : ''))).ticket; }
                catch (e) { hemisSyncModal('<div class="p-4 text-red-600">' + hsEsc(hsErrText(e)) + '</div>' + HS_CLOSE); return; }
                const b = t.blocker || {};
                const blockLine = t.block_type === 'room'
                    ? '<b>' + hsEsc(b.room || '') + '</b>-xona ' + hsEsc(b.time || '') + ' da band: ' + hsEsc([b.source, b.group, b.subject && '«' + b.subject + '»', b.teacher && 'o\'qituvchi: ' + b.teacher].filter(Boolean).join(' · '))
                    : t.block_type === 'teacher'
                        ? '<b>' + hsEsc(b.teacher || '') + '</b> ' + hsEsc(b.time || '') + ' da boshqa darsda: ' + hsEsc([b.source, b.group, b.subject && '«' + b.subject + '»', b.room && 'xona: ' + b.room].filter(Boolean).join(' · '))
                        : hsEsc(t.block_text || '');
                const cls = HS_BLOCK[t.block_type] ? HS_BLOCK[t.block_type].cls : 'bg-red-100 text-red-700 border-red-300';
                let html = '<div class="flex items-center mb-2"><h3 class="font-semibold text-[14px] flex-1">To\'siq №' + t.id + ' · ' + hsEsc(HS_TICKET_STATUS[t.status] || t.status) + '</h3>' +
                    (board ? '<button type="button" id="tkBack" class="px-2 py-1 border rounded mr-1">← Ro\'yxat</button>' : '') + HS_CLOSE + '</div>' +
                    '<div class="mb-1"><b>' + hsEsc(t.group_name) + '</b> · ' + hsEsc(t.subject_name) + ' · ' + hsEsc(t.kafedra_name || '') + '</div>' +
                    '<div class="mb-1">' + hsEsc(t.lesson_date) + ' (' + t.week + '-hafta) ' + hsEsc(t.start_time) + '–' + hsEsc(t.end_time) +
                    (t.card ? ' · o\'qituvchi: ' + hsEsc(t.card.teacher_name || '—') + ' · xona: ' + hsEsc(t.card.auditorium_name || '—') : '') + '</div>' +
                    '<div class="mb-2 px-2 py-1 rounded border ' + cls + '">' + blockLine + '</div>' +
                    '<div class="mb-2"><b>Javoblar:</b> ' + (t.recipients || []).map(r => hsEsc(HS_ROLE[r.role] || r.role) + ' — ' + hsEsc(r.name) + ': ' +
                        (r.response === 'accepted' ? '✅ qabul qildi' : r.response === 'declined' ? '❌ rad etdi' : (r.chat_id ? 'javob kutilmoqda' : '📵 Telegram ulanmagan')) +
                        (r.note ? ' («' + hsEsc(r.note) + '»)' : '')).join('<br>') + '</div>';
                if (t.resolution) {
                    const rs = t.resolution;
                    html += '<div class="mb-2 text-emerald-800"><b>Yechim:</b> ' + (rs.kind === 'room' ? 'xona — ' + hsEsc(rs.auditorium) : rs.kind === 'time' ? 'vaqt — ' + hsEsc(rs.time) :
                        rs.kind === 'day' ? 'kun — ' + hsEsc(HS_DAY[rs.day] || rs.day) + ' (registrator tasdig\'i bilan)' : '') + (rs.by ? ' · ' + hsEsc(rs.by) : '') +
                        (rs.registrar ? ' · <span class="text-red-600">registrator: ' + hsEsc(rs.registrar) + (rs.registrar_note ? ' — ' + hsEsc(rs.registrar_note) : '') + '</span>' : '') + '</div>';
                }
                if (t.can_respond) {
                    html += '<div class="mb-2"><button type="button" id="tkAcc" class="px-2 py-1 rounded bg-emerald-600 text-white">✅ Qabul qildim</button> ' +
                        '<button type="button" id="tkDec" class="px-2 py-1 rounded border border-red-400 text-red-700">❌ Rad etaman</button></div>';
                }
                if (t.can_resolve) {
                    const d = t.free_pairs_day || (t.place && t.place.day);
                    html += '<div class="p-2 border rounded bg-gray-50"><b>Hal qilish</b> <span class="text-gray-500">(faqat shu so\'rov doirasida, shu dars uchun)</span>' +
                        '<div class="mt-1"><label class="mr-3"><input type="radio" name="tkKind" value="room" checked> Xonani almashtirish</label>' +
                        '<label class="mr-3"><input type="radio" name="tkKind" value="time"> Vaqtini almashtirish (shu kun)</label>' +
                        '<label><input type="radio" name="tkKind" value="day"> Kunini almashtirish (registrator tasdig\'i)</label></div>' +
                        '<div id="tkRoomBox" class="mt-1">Bo\'sh xona: <select id="tkRoom" class="border rounded px-1 max-w-full">' +
                        (t.free_rooms || []).map(r => '<option value="' + hsEsc(r.code) + '">' + hsEsc(r.name) + (r.volume ? ' (' + r.volume + ')' : '') + (r.building ? ' — ' + hsEsc(r.building) : '') + '</option>').join('') + '</select></div>' +
                        '<div id="tkTimeBox" class="mt-1 hidden">' +
                        '<span id="tkDayWrap" class="hidden">Kun: <select id="tkDay" class="border rounded px-1">' + [1, 2, 3, 4, 5, 6].map(x => '<option value="' + x + '"' + (x === d ? ' selected' : '') + '>' + HS_DAY[x] + '</option>').join('') + '</select> </span>' +
                        'Bo\'sh vaqt: <select id="tkPair" class="border rounded px-1">' + (t.free_pairs || []).map(p => '<option value="' + p.pair + '">' + hsEsc(p.time) + '</option>').join('') + '</select>' +
                        (!(t.free_pairs || []).length ? ' <span class="text-red-600">bo\'sh vaqt yo\'q</span>' : '') + '</div>' +
                        '<div class="mt-1">Izoh: <input id="tkNote" class="border rounded px-1 w-2/3" maxlength="500"></div>' +
                        '<div class="mt-2"><button type="button" id="tkResolve" class="px-3 py-1 rounded bg-emerald-600 text-white">Saqlash</button></div></div>';
                }
                hemisSyncModal(html);
                if ($('tkBack')) $('tkBack').onclick = () => hsTicketsList();
                const respond = async resp => {
                    try { await api(BASE + '/block-tickets/' + t.id + '/respond', 'POST', { response: resp }); hsTicketOpen(t.id); }
                    catch (e) { alert(hsErrText(e)); }
                };
                if ($('tkAcc')) { $('tkAcc').onclick = () => respond('accepted'); $('tkDec').onclick = () => respond('declined'); }
                if (t.can_resolve) {
                    const kindNow = () => (document.querySelector('#hemisSyncModal input[name="tkKind"]:checked') || {}).value;
                    const showKind = () => {
                        const k = kindNow();
                        $('tkRoomBox').classList.toggle('hidden', k !== 'room');
                        $('tkTimeBox').classList.toggle('hidden', k === 'room');
                        $('tkDayWrap').classList.toggle('hidden', k !== 'day');
                    };
                    document.querySelectorAll('#hemisSyncModal input[name="tkKind"]').forEach(r => { r.onchange = showKind; });
                    if (day) { document.querySelector('#hemisSyncModal input[value="day"]').checked = true; }
                    showKind();
                    $('tkDay').onchange = function () { hsTicketOpen(t.id, +this.value); };
                    $('tkResolve').onclick = async () => {
                        const k = kindNow();
                        const body = { kind: k, note: $('tkNote').value };
                        if (k === 'room') { if (!$('tkRoom').value) return alert('Xona tanlang.'); body.auditorium_code = $('tkRoom').value; }
                        else { if (!$('tkPair').value) return alert('Vaqt tanlang.'); body.pair = +$('tkPair').value; if (k === 'day') body.day = +$('tkDay').value; }
                        try {
                            const r = await api(BASE + '/block-tickets/' + t.id + '/resolve', 'POST', body);
                            alert(r.status === 'pending_registrar' ? 'Kunni o\'zgartirish so\'rovi registrator ofisi va o\'quv bo\'limiga yuborildi.' : 'Saqlandi: o\'zgarish LMS ichki jadvalida qo\'llandi.');
                            hsTicketOpen(t.id);
                        } catch (e) { alert(hsErrText(e)); }
                    };
                }
            }
            if ($('blockTicketsBtn')) $('blockTicketsBtn').onclick = () => hsTicketsList();
            if (TICKET_FROM_URL) setTimeout(() => hsTicketOpen(TICKET_FROM_URL), 300);
            // ===== Ichki jadval: haftani zichlash =====
            // Tashqi jadval (ext_day/ext_pair) andoza: guruhning shu kunidagi shablonda band, lekin
            // shu haftada bo'sh qolgan yarim-slotlariga keyingi darslar yuqoriga suriladi; so'ng
            // joylashmagan kartalar andozadagi joyiga yoki shu kunning pastroq bo'sh joyiga qo'yiladi.
            // Har bir ko'chirish oddiy week-override (server konflikt tekshiradi).
            // Kartaning o'z panjarasidagi haftalar soni (yo'nalish+kurs, bo'lmasa doska).
            const cardTermWeeks = c => {
                const g = gridForCard(c);
                return +(g && g.weeks) || +board.weeks || 15;
            };
            async function compactInternalWeek(W, scopeCards) {
                // Kartaning semestri tugagan haftaga ko'chirish yozilmasin.
                scopeCards = scopeCards.filter(c => W <= cardTermWeeks(c));
                const all = cards.filter(c => !isCycleCardAny(c));
                const key = c => c.id + '|' + W;
                const off = c => { const o = overrides[key(c)]; return !!(o && o.cancelled); };
                const place = c => {
                    const o = overrides[key(c)];
                    if (o) return o.cancelled ? null : { d: +o.day, p: +o.pair };
                    return c.day ? { d: +c.day, p: +c.pair } : null;
                };
                const slots = (c, g, d) => gkey(c, g) + '|' + d;
                const tmpl = {};
                all.forEach(c => {
                    if (!c.ext_day || !c.ext_pair) return;
                    cardGroups(c).forEach(g => {
                        const k = slots(c, g, c.ext_day), set = tmpl[k] || (tmpl[k] = new Set());
                        for (let i = 0; i < cardLen(c); i++) set.add(+c.ext_pair + i);
                    });
                });
                // Ma'ruza vaqti qat'iy: shu haftada o'tiladigan, hali joylanmagan ma'ruzaning tashqi joyi unga band
                // hisoblanadi — amaliy darslar u yerga surilib (yoki qo'yilib), ma'ruzani joysiz qoldirmasin.
                const lecWait = scopeCards.filter(c => c.training_type === 'lecture' && !off(c) && !place(c) && c.ext_day && c.ext_pair);
                const occ = () => {
                    const u = {};
                    all.forEach(c => {
                        if (off(c)) return;
                        const pl = place(c);
                        if (!pl) return;
                        cardGroups(c).forEach(g => {
                            const m = u[slots(c, g, pl.d)] || (u[slots(c, g, pl.d)] = new Map());
                            for (let i = 0; i < cardLen(c); i++) m.set(pl.p + i, c.id);
                        });
                    });
                    lecWait.forEach(c => {
                        if (place(c)) return;
                        cardGroups(c).forEach(g => {
                            const m = u[slots(c, g, +c.ext_day)] || (u[slots(c, g, +c.ext_day)] = new Map());
                            for (let i = 0; i < cardLen(c); i++) if (!m.has(+c.ext_pair + i)) m.set(+c.ext_pair + i, c.id);
                        });
                    });
                    return u;
                };
                const maxPair = Math.max(1, boardSchedule().filter(it => it.type === 'pair').length) || 12;
                const free = (u, c, d, p) => p >= 1 && p + cardLen(c) - 1 <= maxPair && cardGroups(c).every(g => {
                    const m = u[slots(c, g, d)];
                    for (let i = 0; i < cardLen(c); i++) { const x = m && m.get(p + i); if (x && x !== c.id) return false; }
                    return true;
                });
                const move = async (c, d, p) => {
                    try {
                        await api(BASE + '/cards/' + c.id + '/week-override', 'POST', { week: W, action: 'move', day: d, pair: p, layer: 'internal' });
                        overrides[key(c)] = Object.assign({}, overrides[key(c)] || {}, { card_id: c.id, week: W, day: d, pair: p, cancelled: false });
                        return true;
                    } catch (e) { return false; }
                };
                const res = { up: 0, placed: 0, left: 0 };
                // Birlik (dars yaxlit): bir guruh, bir fan, bir tur, bir o'qituvchining shu haftadagi bo'laklari. Har surish va joylash —
                // birlik bilan (unit-place): bo'laklar ketma-ket, sig'masa hech biri; server bandlikni tekshiradi.
                const index = buildUnitIndex(all);
                const unitList = c => (c.training_type === 'lecture' ? [c] : (index.get(unitKey(c)) || [c]))
                    .filter(x => !off(x) && W <= cardTermWeeks(x));
                const ids = list => new Set(list.map(x => x.id));
                // Birlik d kuni s dan: guruhlari bo'sh (o'z bo'laklari hisobga olinmaydi).
                const unitFree = (u, list, d, s) => {
                    const mine = ids(list);
                    let p = s;
                    for (const c of list) {
                        if (p < 1 || p + cardLen(c) - 1 > maxPair) return false;
                        for (const g of cardGroups(c)) {
                            const m = u[slots(c, g, d)];
                            for (let i = 0; i < cardLen(c); i++) { const x = m && m.get(p + i); if (x && !mine.has(x)) return false; }
                        }
                        p += cardLen(c);
                    }
                    return true;
                };
                const placeUnit = async (list, d, s) => {
                    try {
                        const body = { week: W, layer: 'internal' };
                        if (d) { body.day = d; body.pair = s; }
                        const j = await api(BASE + '/cards/' + list[0].id + '/unit-place', 'POST', body);
                        applyUnitPayload(j && j.unit, W);
                        return true;
                    } catch (e) { return false; }
                };
                // 1) Yuqoriga surish: shu haftada bo'shab qolgan (shablonda band) joyga — butun birlik birga.
                // Ma'ruza vaqti qat'iy — tashqi jadvaldagi kun/vaqtda turadi (ma'ruza xonalari umumiy), surilmaydi.
                const doneUp = new Set();
                const act = scopeCards.filter(c => !off(c) && place(c) && c.training_type !== 'lecture')
                    .sort((a, b) => place(a).d - place(b).d || place(a).p - place(b).p);
                for (const c0 of act) {
                    if (doneUp.has(unitKey(c0))) continue;
                    doneUp.add(unitKey(c0));
                    const list = unitList(c0);
                    // Qisman joylangan yoki bo'lingan birlik — 2-bosqichda yaxlit qilinadi.
                    if (list.some(x => !place(x)) || new Set(list.map(x => place(x).d)).size > 1) continue;
                    list.sort((a, b) => place(a).p - place(b).p);
                    const d = place(list[0]).d, start = place(list[0]).p;
                    const u = occ();
                    let st = start;
                    while (st > 1 && list.every(c => cardGroups(c).every(g => tmpl[slots(c, g, d)] && tmpl[slots(c, g, d)].has(st - 1))) && unitFree(u, list, d, st - 1)) st--;
                    // Para chegarasi faqat butun para (2+ yarim-slot) darslar uchun saqlanadi.
                    const step = list.some(c => cardLen(c) > 1) ? 2 : 1;
                    if (step === 2 && (start - st) % 2) st++;
                    for (; st < start; st += step) { if (await placeUnit(list, d, st)) { res.up++; break; } }
                }
                // 2) Joylanmagan bo'lagi bor birliklar (qisman joylanganlar ham) yaxlit joylanadi: kun — joylangan qismi kuni, bo'lmasa
                // tashqi jadvaldagi kuni (boshqa kunga o'tkazilmaydi). Vaqt tanlovi: avval joyida (qisman — joylangan qismi boshidan),
                // keyin bo'shliq qo'shmaydigan yoki kamaytiradigan, so'ng guruhning mavjud darsiga yopishgan, keyin tashqi joyiga
                // yaqin. Sig'masa — birlik butunlay joydan olinadi: qisman joylangan birlik qolmaydi.
                // Tartib: ma'ruzalar (qat'iy vaqt), keyin tashqi joyi bor yangi birliklar (boshqa darsning tashqi joyini qisman
                // joylangan birlik egallab qo'ymasin), so'ng qisman joylanganlar va tashqi joyi yo'qlar.
                const doneUnits = new Set(), todoUnits = [];
                for (const c0 of scopeCards) {
                    if (off(c0) || W > cardTermWeeks(c0) || doneUnits.has(unitKey(c0))) continue;
                    doneUnits.add(unitKey(c0));
                    const list = unitList(c0);
                    if (list.length && list.some(x => !place(x))) todoUnits.push(list);
                }
                const tier = list => (list[0].training_type === 'lecture' ? 0 : !list.some(x => place(x)) && list.some(x => x.ext_day && x.ext_pair) ? 1 : 2);
                todoUnits.sort((a, b) => tier(a) - tier(b));
                for (const list of todoUnits) {
                    const placedNow = list.filter(x => place(x));
                    const withExt = list.filter(x => x.ext_day && x.ext_pair).sort((a, b) => +a.ext_pair - +b.ext_pair);
                    const d = placedNow.length ? place(placedNow[0]).d : (withExt[0] ? +withExt[0].ext_day : 0);
                    // Na joylangan qismi, na tashqi joyi bor — qayerga qo'yishni bilmaymiz (qo'lda joylanadi).
                    if (!d) continue;
                    const order = [...placedNow.sort((a, b) => place(a).p - place(b).p), ...list.filter(x => !place(x)).sort((a, b) => a.id - b.id)];
                    const len = unitLen(order);
                    const lo = placedNow.length ? Math.min(...placedNow.map(x => place(x).p)) : null;
                    const p0 = lo || (withExt[0] ? +withExt[0].ext_pair : 1);
                    let starts;
                    if (order[0].training_type === 'lecture') {
                        // Ma'ruza — faqat tashqi jadvaldagi vaqtiga; band bo'lsa joylanmagan qoladi.
                        starts = [p0];
                    } else {
                        const step = order.some(c => cardLen(c) > 1) ? 2 : 1;
                        const rows = groupDayRows(W, ids(order));
                        starts = [];
                        for (let s = 1; s + len - 1 <= maxPair; s++) if ((s - p0) % step === 0 || s === lo) starts.push(s);
                        const eff = {};
                        starts.forEach(s => { eff[s] = unitGapEffect(order, d, s, rows); });
                        const rank = s => (s === lo ? 0 : 1);
                        starts.sort((x, y) => rank(x) - rank(y) || (eff[x].delta > 0) - (eff[y].delta > 0) || (!eff[x].touch) - (!eff[y].touch)
                            || eff[x].delta - eff[y].delta || Math.abs(x - p0) - Math.abs(y - p0) || x - y);
                    }
                    let ok = false;
                    for (const s of starts) {
                        if (!unitFree(occ(), order, d, s)) continue;
                        if (await placeUnit(order, d, s)) { ok = true; break; }
                    }
                    if (ok) { res.placed += order.length - placedNow.length; continue; }
                    // Sig'madi — qisman qoldirilmaydi: joylangan qismi ham olinadi.
                    if (placedNow.length) await placeUnit(order, null, null);
                    res.left += order.length;
                }
                return res;
            }

            // ===== Takliflar: joylanmagan kartalarni sig'dirish yo'llari (server hisoblaydi, foydalanuvchi tanlaydi) =====
            // Tartib (server): ikkalasini ketma-ket, shu kun boshqa vaqt, boshqa xona, darsni (to'siqni) shu kunda surish, boshqa kun, …,
            // to'siqni boshqa kunga. "Darsni surish" — faqat kun o'zgarmaydigan siljish.
            const SUG_LABEL = { parallel: 'Yonma-yon (parallel)', pair: 'Ikkalasini ketma-ket', slot: 'Shu kun, boshqa vaqt', room: 'Boshqa xona', blocker: 'Darsni surish', day: 'Boshqa kun',
                week: 'Boshqa hafta', lecture: 'Ma\'ruzani surish', teacher: 'Boshqa o\'qituvchi', blocker_day: 'To\'siqni boshqa kunga' };
            const SUG_COLOR = { parallel: '#4f46e5', pair: '#0f766e', slot: '#059669', room: '#0284c7', blocker: '#7c3aed', day: '#d97706', week: '#b45309', lecture: '#a16207',
                teacher: '#dc2626', blocker_day: '#9a3412' };
            // Bo'shliq belgisi (yumshoq mezon, taklif yashirilmaydi): "bo'shliqsiz" — yashil, "+½ para bo'shliq" / "+1 para bo'shliq" — sariq.
            function sugGapBadge(gap) {
                if (gap === undefined || gap === null) return '';
                const n = +gap;
                const txt = n <= 0 ? 'bo\'shliqsiz' : '+' + (n === 1 ? '½' : (n % 2 ? (Math.floor(n / 2) + '½') : String(n / 2))) + ' para bo\'shliq';
                return ' <span class="sug-gap" style="font-size:10px;font-weight:600;border-radius:4px;padding:0 5px;' +
                    (n <= 0 ? 'background:#dcfce7;color:#166534' : 'background:#fef9c3;color:#854d0e') + '">' + txt + '</span>';
            }
            // Takliflar oynasi ichidagi xabar (alert sahifani to'sib qo'yadi): kind — 'err' | 'ok'.
            function sugNote(body, html, kind) {
                if (!body) return;
                let n = body.querySelector('#ttSugNote');
                if (!n) { n = document.createElement('div'); n.id = 'ttSugNote'; body.prepend(n); }
                n.setAttribute('role', kind === 'err' ? 'alert' : 'status');
                n.style.cssText = 'border-radius:6px;padding:6px 10px;margin-bottom:8px;' + (kind === 'err'
                    ? 'background:#fef2f2;border:1px solid #fca5a5;color:#991b1b' : 'background:#ecfdf5;border:1px solid #6ee7b7;color:#065f46');
                n.innerHTML = html;
                if (n.scrollIntoView) n.scrollIntoView({ block: 'nearest' });
            }
            async function openWeekSuggestions(notice) {
                if (!board || !curWeek || weeklyLayer !== 'internal') return;
                let box = document.getElementById('ttSugModal');
                if (!box) {
                    box = document.createElement('div');
                    box.id = 'ttSugModal';
                    box.style.cssText = 'position:fixed;inset:0;z-index:70;background:rgba(15,23,42,.45);display:flex;align-items:center;justify-content:center;padding:16px';
                    box.innerHTML = '<div style="background:#fff;border-radius:12px;width:min(1100px,100%);max-height:92vh;display:flex;flex-direction:column;box-shadow:0 20px 60px #0005">' +
                        '<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 16px;border-bottom:1px solid #e2e8f0">' +
                        '<b id="ttSugTitle">Takliflar</b><button type="button" id="ttSugClose" style="font-size:20px;line-height:1">&times;</button></div>' +
                        '<div id="ttSugBody" style="overflow:auto;padding:12px 16px;font-size:12px"></div></div>';
                    document.body.appendChild(box);
                    box.addEventListener('click', ev => { if (ev.target === box || ev.target.id === 'ttSugClose') box.remove(); });
                }
                const body = box.querySelector('#ttSugBody');
                box.querySelector('#ttSugTitle').textContent = 'Takliflar — ' + curWeek + '-hafta';
                body.innerHTML = '<div style="color:#64748b">Hisoblanmoqda…</div>';
                const params = new URLSearchParams();
                [...selectedFaculties].forEach(v => params.append('faculty_names[]', v));
                [...selectedDirs].forEach(v => params.append('specialty_names[]', v));
                [...selectedCourses].forEach(v => params.append('courses[]', v));
                params.set('type', typeFilter);
                params.set('week', curWeek);
                let res;
                try { res = await api(BASE + '/boards/' + board.id + '/week-suggestions?' + params.toString()); }
                catch (e) { body.innerHTML = '<div style="color:#dc2626">' + esc(e.message) + '</div>'; return; }
                // Joylanmagan va (joyi bor, lekin) to'qnashuvli kartalar alohida sanaladi; ikkalasi ham bo'lmasa — "yo'q".
                box.querySelector('#ttSugTitle').textContent = 'Takliflar — ' + res.week + '-hafta · Joylanmagan: ' + (res.unplaced_total ?? res.total) +
                    ' · To\'qnashuvli: ' + (res.conflict_total || 0) + (res.shown < res.total ? ' (birinchi ' + res.shown + ' tasi)' : '');
                if (!res.total || !res.cards.length) { body.innerHTML = '<div style="color:#059669">Bu haftada joylanmagan yoki to\'qnashuvli karta yo\'q.</div>'; return; }
                window.__ttSug = res.cards;
                renderSugCards(body, res, params);
                // Oldingi qo'llashda bajarilmaganlar — qayta hisoblangan ro'yxat ustida.
                if (notice && notice.html) sugNote(body, notice.html, notice.kind);
            }
            // Takliflar ro'yxati. Vaqt byudjeti tugagan bo'lsa (partial) — sariq yozuv; qisqartirilgan kartada "To'liq takliflar"
            // tugmasi faqat shu karta uchun (card_id) to'liq hisoblab, kartani almashtiradi.
            function renderSugCards(body, res, params) {
                const partialCards = window.__ttSug.filter(c => c.partial).length;
                body.innerHTML = (partialCards
                    ? '<div id="ttSugPartial" style="background:#fef9c3;border:1px solid #facc15;color:#854d0e;border-radius:6px;padding:6px 10px;margin-bottom:8px">⚠ ' +
                        esc(partialCards + ' ta karta uchun to\'liq takliflar hisoblanmadi') + ' — kartadagi «To\'liq takliflar» tugmasini bosing.</div>'
                    : '') + window.__ttSug.map((c, ci) =>
                    '<div style="border:1px solid ' + (c.partial ? '#facc15' : '#e2e8f0') + ';border-radius:8px;padding:8px 10px;margin-bottom:8px">' +
                    '<div><b>' + esc(c.subject) + '</b> <span style="color:#64748b">[' + (c.type === 'lecture' ? 'M' : 'A') + '] ' +
                    esc((c.groups || []).join(', ')) + ' · ' + esc(c.teacher || 'o\'qituvchi yo\'q') + (c.room ? ' · ' + esc(c.room) : '') + '</span>' +
                    (c.conflict ? ' <span class="sug-conflict" style="font-size:10px;font-weight:700;color:#fff;background:#dc2626;border-radius:4px;padding:1px 6px">⚠ To\'qnashuv</span>' : '') +
                    (c.partial ? ' <button type="button" data-full="' + ci + '" style="font-size:11px;border:1px solid #facc15;border-radius:6px;padding:1px 8px;background:#fefce8;color:#854d0e">To\'liq takliflar</button>' : '') +
                    '</div>' +
                    (c.reason ? '<div style="color:#b91c1c;margin:2px 0 4px">' + esc(c.reason) + focusLinksHtml(c.clashes) +
                        agendaLinksHtml(c.clashes, 'w|' + c.id + '|' + res.week) + '</div>' : '') +
                    // Xona sig'imi (1.4) — haftalik karta va biriktirish oynasidagi bilan bir xil server matni.
                    (c.cap_warn ? '<div class="sug-cap-warn" style="color:#a16207;margin:2px 0 4px">⚠ ' + esc(c.cap_warn) + '</div>' : '') +
                    (c.suggestions.length ? c.suggestions.map((s, si) => sugRowHtml(s, ci, si, res.apply_mode)).join('')
                        : '<div style="color:#64748b">Taklif topilmadi — qo\'lda joylash kerak.</div>') +
                    '</div>').join('') + sugFooterHtml(res.apply_mode);
                body.querySelectorAll('[data-full]').forEach(btn => btn.onclick = async () => {
                    const ci = +btn.dataset.full;
                    btn.disabled = true; btn.textContent = 'Hisoblanmoqda…';
                    const p = new URLSearchParams(params);
                    p.set('card_id', window.__ttSug[ci].id);
                    try {
                        const one = await api(BASE + '/boards/' + board.id + '/week-suggestions?' + p.toString());
                        if (one.cards && one.cards[0]) window.__ttSug[ci] = one.cards[0];
                        renderSugCards(body, res, params);
                    } catch (e) {
                        btn.disabled = false; btn.textContent = 'To\'liq takliflar';
                        sugNote(body, 'Takliflarni olib bo\'lmadi: ' + esc(e.message), 'err');
                    }
                });
                // Bir kartaning takliflari muqobil — bittasi tanlanadi.
                const pick = () => [...body.querySelectorAll('[data-sug-pick]:checked')].map(x => x.dataset.sugPick.split(':').map(Number));
                const sync = () => {
                    const b = body.querySelector('[data-sug-apply-all]');
                    if (b) { const n = pick().length; b.disabled = !n; b.textContent = 'Tanlanganlarni qo\'llash' + (n ? ' (' + n + ')' : ''); }
                };
                body.querySelectorAll('[data-sug-pick]').forEach(chk => chk.onchange = () => {
                    if (chk.checked) body.querySelectorAll('[data-sug-pick^="' + chk.dataset.sugPick.split(':')[0] + ':"]').forEach(o => { if (o !== chk) o.checked = false; });
                    sync();
                });
                // Tanlangan karta va taklif — bosilgan paytdagi nusxa ({ c, sug }): sabab oynasi ochiq turganda "To'liq takliflar"
                // javobi window.__ttSug[ci] ni almashtirsa ham, foydalanuvchi tasdiqlagan taklif yuboriladi (indeks bo'yicha qayta olinmaydi).
                const sugAt = (ci, si) => { const c = window.__ttSug[ci]; return { c, sug: c.suggestions[si] }; };
                const applyOne = async ({ c, sug }, reason) => {
                    const r = await api(BASE + '/boards/' + board.id + '/week-suggestions/' + (sug.mode === 'direct' ? 'apply' : 'propose'), 'POST',
                        Object.assign({ week: res.week, card_id: c.id, type: sug.type, title: sug.title, actions: sug.actions }, sug.mode === 'direct' ? {} : { reason }));
                    return r;
                };
                const confirmSug = sug => !((sug.type === 'teacher' && !confirm('O\'qituvchi butun semestr uchun almashadi. Davom etamizmi?'))
                    || (sug.type === 'lecture' && !confirm('Ma\'ruza vaqti tashqi jadvaldan farq qiladi. Davom etamizmi?'))
                    || (sug.type === 'week' && !confirm('KTR taqsimoti o\'zgaradi (' + sug.note + '). Davom etamizmi?')));
                const finish = async (msgs, errs = []) => {
                    if (msgs.length) ttToast(msgs.map(esc).join('<br>'), 'ok');
                    await loadChangeRequests();
                    await loadBoard(board.id);
                    openWeekSuggestions(errs.length ? { kind: 'err', html: '<b>Bajarilmaganlar (jadval o\'zgarmadi):</b>' + errs.map(x => '<div>' + esc(x) + '</div>').join('') } : null);
                };
                body.querySelectorAll('[data-sug]').forEach(btn => btn.onclick = async () => {
                    const pickd = sugAt(...btn.dataset.sug.split(':').map(Number)), sug = pickd.sug;
                    if (!sug.can_apply || !confirmSug(sug)) return;
                    // So'rov (kafedra mudiri / registrator tasdig'i) — sabab majburiy.
                    const reason = sug.mode === 'direct' ? '' : await askSugReason();
                    if (reason === null) { sugNote(body, "So'rov yuborilmadi: sabab kiritilmadi.", 'err'); return; }
                    btn.disabled = true; btn.textContent = '…';
                    // Yaxlit: server barcha amallarni bitta tranzaksiyada bajaradi (yoki bitta so'rov yaratadi) — qisman bajarilmaydi.
                    try { const r = await applyOne(pickd, reason); await finish([r.message || 'Qo\'llandi.']); }
                    catch (e) { sugNote(body, 'Bajarilmadi (jadval o\'zgarmadi): ' + esc(e.message), 'err'); btn.disabled = false; btn.textContent = sugApplyLabel(sug.mode); }
                });
                const all = body.querySelector('[data-sug-apply-all]');
                if (all) all.onclick = async () => {
                    const list = pick().map(([ci, si]) => sugAt(ci, si));
                    if (!list.length || list.some(x => !confirmSug(x.sug))) return;
                    // So'rovlar bo'lsa — sabab bir marta so'raladi (hammasiga).
                    const reason = list.some(x => x.sug.mode !== 'direct') ? await askSugReason() : '';
                    if (reason === null) { sugNote(body, "So'rov yuborilmadi: sabab kiritilmadi.", 'err'); return; }
                    all.disabled = true;
                    const msgs = [], errs = [];
                    for (const x of list) {
                        try { const r = await applyOne(x, reason); msgs.push(x.c.subject + ': ' + (r.message || 'qo\'llandi')); }
                        catch (e) { errs.push(x.c.subject + ': ' + e.message); }
                    }
                    // Har tanlangan taklif — alohida so'rov; bajarilmaganlari oyna ichida (qayta hisoblangan ro'yxat ustida).
                    await finish(msgs, errs);
                };
                sync();
            }
            // Taklif qatori: katakcha (qo'llash mumkin bo'lsa), turi, matni, "Qo'llash" (yoki o'chiq — sababi bilan).
            function sugApplyLabel(mode) { return mode === 'direct' ? 'Qo\'llash' : 'So\'rov yuborish'; }
            // Sabab oynasi (sahifa ichida, native prompt() o'rniga): sarlavha, izoh, matn maydoni (1000 belgi), "Bekor" va tasdiq tugmasi.
            // Takliflar (z-index 70) va "Jadval o'zgarishlari" (#crModal, 10040) oynalari ustida, xabarlar (#ttToastBox, 10050) ostida.
            // Esc — bekor (ostidagi oynaga o'tmaydi), Ctrl/Cmd+Enter — tasdiq, oddiy Enter — yangi qator. Orqa fonga bosish yopmaydi (tugmani
            // ikki marta bosganda ikkinchisi oynani bekor qilib yubormasin). Natija — Promise: kiritilgan (tozalangan) matn; bekor yoki bo'sh — null.
            function askReasonDialog({ title, hint, placeholder, okLabel, okColor }) {
                return new Promise(resolve => {
                    const prev = document.getElementById('ttReasonModal');
                    if (prev) prev.__close ? prev.__close(null) : prev.remove();   // avvalgisi — bekor (kutayotgani osilib qolmasin)
                    const m = document.createElement('div');
                    m.id = 'ttReasonModal';
                    m.setAttribute('role', 'dialog');
                    m.setAttribute('aria-modal', 'true');
                    m.setAttribute('aria-labelledby', 'ttReasonTitle');
                    m.style.cssText = 'position:fixed;inset:0;z-index:10045;background:rgba(15,23,42,.35);display:flex;align-items:center;justify-content:center;padding:16px';
                    m.innerHTML = '<div style="background:#fff;border-radius:10px;width:min(460px,100%);padding:14px 16px;box-shadow:0 20px 60px #0005;font-size:12px">' +
                        '<b id="ttReasonTitle" style="display:block;font-size:13px;margin-bottom:2px">' + esc(title) + '</b>' +
                        (hint ? '<div style="color:#64748b;margin-bottom:8px">' + esc(hint) + '</div>' : '') +
                        '<textarea id="ttReasonText" rows="4" maxlength="1000" placeholder="' + esc(placeholder || '') + '" ' +
                        'style="width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:6px;padding:6px 8px;font-size:12px;font-family:inherit;resize:vertical"></textarea>' +
                        '<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:10px">' +
                        '<button type="button" data-reason="cancel" style="font-size:12px;border:1px solid #cbd5e1;border-radius:6px;padding:4px 12px;background:#f8fafc">Bekor</button>' +
                        '<button type="button" data-reason="ok" style="font-size:12px;border-radius:6px;padding:4px 12px;background:' + (okColor || '#2563eb') + ';color:#fff">' + esc(okLabel) + '</button>' +
                        '</div></div>';
                    let done = false;
                    const close = v => {
                        if (done) return;
                        done = true;
                        document.removeEventListener('keydown', onKey, true);
                        m.remove();
                        resolve(v);
                    };
                    const submit = () => close(String(m.querySelector('#ttReasonText').value || '').trim() || null);
                    const onKey = e => {
                        if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); close(null); }
                        else if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); submit(); }
                    };
                    m.__close = close;
                    m.addEventListener('click', e => {
                        const b = e.target.closest ? e.target.closest('[data-reason]') : null;
                        if (b) b.dataset.reason === 'ok' ? submit() : close(null);
                    });
                    document.addEventListener('keydown', onKey, true);
                    document.body.appendChild(m);
                    const ta = m.querySelector('#ttReasonText');
                    if (ta && ta.focus) ta.focus();
                });
            }
            // Takliflar "So'rov yuborish" sababi (kafedra mudiri va registrator ofisi ko'radi).
            function askSugReason() {
                return askReasonDialog({ title: "So'rov sababi", hint: "Kafedra mudiri va registrator ofisi ko'radi.",
                    placeholder: 'Masalan: ertalab amaliyot bor', okLabel: 'Yuborish' });
            }
            // "Jadval o'zgarishlari": so'rovni rad etish sababi (taklif yuboruvchiga boradi).
            function askRejectReason() {
                return askReasonDialog({ title: 'Rad etish sababi', hint: 'Taklif yuboruvchiga boradi.',
                    placeholder: 'Masalan: xona shu vaqtda band', okLabel: 'Rad etish', okColor: '#dc2626' });
            }
            function sugRowHtml(s, ci, si, applyMode) {
                const can = Boolean(s.can_apply);
                return '<div style="display:flex;gap:8px;align-items:flex-start;padding:3px 0;border-top:1px dashed #f1f5f9">' +
                    (applyMode && can ? '<input type="checkbox" data-sug-pick="' + ci + ':' + si + '" style="margin-top:2px">' : '') +
                    '<span style="flex:0 0 auto;font-size:10px;font-weight:700;color:#fff;border-radius:4px;padding:1px 6px;background:' + (SUG_COLOR[s.type] || '#475569') + '">' + (SUG_LABEL[s.type] || s.type) + '</span>' +
                    '<span style="flex:1 1 auto">' + esc(s.title) + sugGapBadge(s.gap) + (s.note ? ' <i style="color:#64748b">(' + esc(s.note) + ')</i>' : '') +
                    (!can && s.why && applyMode ? '<div class="sug-why" style="color:#b45309;font-size:11px">' + esc(s.why) + '</div>' : '') + '</span>' +
                    (applyMode ? '<button type="button" data-sug="' + ci + ':' + si + '"' + (can ? '' : ' disabled title="' + esc(s.why || '') + '"') +
                        ' style="flex:0 0 auto;font-size:11px;border:1px solid #cbd5e1;border-radius:6px;padding:1px 8px;background:#f8fafc' + (can ? '' : ';opacity:.5;cursor:not-allowed') + '">' + sugApplyLabel(s.mode) + '</button>' : '') +
                    '</div>';
            }
            function sugFooterHtml(applyMode) {
                if (!applyMode) return '<div style="color:#64748b;margin-top:6px">Faqat ko\'rish: takliflarni qo\'llash huquqingiz yo\'q.</div>';
                return '<div style="position:sticky;bottom:-12px;background:#fff;border-top:1px solid #e2e8f0;padding:8px 0;display:flex;gap:10px;align-items:center">' +
                    '<button type="button" data-sug-apply-all disabled style="font-size:12px;border-radius:6px;padding:4px 12px;background:#2563eb;color:#fff">Tanlanganlarni qo\'llash</button>' +
                    '<span style="color:#64748b">' + (applyMode === 'direct' ? 'Har taklif yaxlit qo\'llanadi: yo hamma amali, yo hech biri.'
                        : 'Har taklif bitta so\'rov bo\'lib tasdiqqa boradi; jadval yakuniy tasdiqdan keyin o\'zgaradi.') + '</span></div>';
            }
            if ($('suggestWeekBtn')) $('suggestWeekBtn').onclick = openWeekSuggestions;
            if ($('compactWeekBtn')) $('compactWeekBtn').onclick = async function () {
                if (!board || !curWeek || weeklyLayer !== 'internal') return;
                const scope = visibleSpecCards().filter(c => !isCycleCardAny(c));
                // Faqat tanlangan qamrovdagi panjaralar semestri (boshqa, uzunroq panjara emas).
                const total = Math.max(curWeek, ...scope.map(cardTermWeeks));
                if (!confirm('Qamrov: ' + scopeLabelText() + '\n\nIchki jadvalda bo\'sh qolgan dars joylariga keyingi darslar suriladi, ' +
                    'joylashmagan kartalar o\'sha kunning ichida bo\'sh joyga ketma-ket (bo\'linmasdan) qo\'yiladi.\n\nDavom etamizmi?')) return;
                const allWeeks = total > 1 && confirm('Barcha haftalarga (1–' + total + ') qo\'llansinmi?\n\nOK — barcha haftalar, Bekor — faqat ' + curWeek + '-hafta');
                const weeks = allWeeks ? Array.from({ length: total }, (_, i) => i + 1) : [curWeek];
                this.disabled = true;
                const sum = { up: 0, placed: 0, left: 0 };
                try {
                    for (const W of weeks) {
                        $('boardMsg').textContent = 'Zichlanmoqda: ' + W + '-hafta…';
                        const r = await compactInternalWeek(W, scope);
                        sum.up += r.up; sum.placed += r.placed; sum.left += r.left;
                    }
                    $('boardMsg').textContent = 'Zichlash: ' + sum.up + ' ta dars yuqoriga surildi, ' + sum.placed + ' ta karta joylandi' +
                        (sum.left ? ', ' + sum.left + ' tasiga bo\'sh joy topilmadi' : '');
                    await loadBoard(board.id);
                } catch (e) { alert('Xatolik: ' + e.message); }
                finally { this.disabled = false; }
            };
            $('weekSel').onchange = function () {
                curWeek = +this.value || 0;
                selected = null;
                showSkipped = false;
                fillWeekSel();
                // Ko'chirishlar faqat yuklangan haftalar uchun kelgan (o'qituvchi / fan mas'uli) — boshqa hafta: shu hafta bilan qayta so'raladi.
                if (weekNeedsReload()) {
                    loadBoard(board.id).catch(e => alert('Xatolik: ' + e.message));
                    return;
                }
                renderAll();
            };
            // "Bu haftada o'tilmaydi" kartalarini panelda ko'rsatish/yashirish
            $('skipToggle').onclick = function () {
                showSkipped = !showSkipped;
                renderPanel();
            };
            // Joylashmagan kartalar paneli filtrlari: fan, oqim, guruh, dars turi
            // mine — fan mas'uli: "Mas'ul fanlarim" (sukut — yoqilgan; filtr tozalashda saqlanadi).
            const pnFilter = { subject: '', oqim: '', groups: new Set(), type: '', mine: TIMETABLE_ROLE === 'fan_masuli' };
            const pnMatch = c =>
                (!pnFilter.mine || mySubjectCardIds.has(+c.id)) &&
                (!pnFilter.subject || c.subject_name === pnFilter.subject) &&
                (!pnFilter.oqim || (c.oqim_label || '') === pnFilter.oqim) &&
                (!pnFilter.groups.size || cardGroups(c).some(g => pnFilter.groups.has(g))) &&
                (!pnFilter.type || c.training_type === pnFilter.type);
            $('pnSubject').onchange = function () { pnFilter.subject = this.value; renderPanel(); };
            $('pnType').onchange = function () { pnFilter.type = this.value; renderPanel(); };
            if ($('pnMine')) $('pnMine').onchange = function () { pnFilter.mine = this.checked; renderPanel(); };
            $('pnOqim').onchange = function () { pnFilter.oqim = this.value; renderPanel(); };
            // Guruhlar — bir nechtasini belgilash mumkin
            $('pnGroupMenu').addEventListener('change', ev => {
                if (!ev.target.matches('input[type=checkbox]')) return;
                if (ev.target.checked) pnFilter.groups.add(ev.target.value);
                else pnFilter.groups.delete(ev.target.value);
                renderPanel();
            });
            $('pnGroupMenu').addEventListener('click', ev => {
                if (ev.target.dataset.pnGroupsClear === undefined) return;
                pnFilter.groups.clear();
                renderPanel();
            });
            $('pnReset').onclick = function () {
                pnFilter.subject = pnFilter.type = pnFilter.oqim = '';
                pnFilter.groups.clear();
                renderPanel();
            };
            // Guruh ro'yxatini chizadi; paneldan yo'qolgan guruhlar tanlovdan chiqadi.
            function fillPnGroups(values) {
                [...pnFilter.groups].forEach(g => { if (!values.includes(g)) pnFilter.groups.delete(g); });
                const n = pnFilter.groups.size;
                $('pnGroupMenu').innerHTML =
                    (n ? '<div class="tt-dd-tools"><button type="button" data-pn-groups-clear="1">Tanlovni tozalash</button></div>' : '') +
                    (values.map(g =>
                        '<label class="tt-dd-item"><input type="checkbox" value="' + esc(g) + '"' + (pnFilter.groups.has(g) ? ' checked' : '') + '>' +
                        esc(g) + '</label>').join('') || '<div class="tt-dd-empty">—</div>');
                const sum = !n ? 'Barcha guruhlar' : n === 1 ? [...pnFilter.groups][0] : n + ' ta guruh';
                $('pnGroupBtn').innerHTML = '<span class="tt-dd-sum">' + esc(sum) + '</span> <span class="tt-dd-caret">▾</span>';
            }
            // Tanlov ro'yxatini paneldagi kartalardan to'ldiradi; tanlangan qiymat
            // endi yo'q bo'lsa (masalan, joylashtirilib bo'lindi) filtr tozalanadi.
            function fillPnSelect(id, allLabel, values, key) {
                if (pnFilter[key] && !values.includes(pnFilter[key])) pnFilter[key] = '';
                $(id).innerHTML = '<option value="">' + allLabel + '</option>' +
                    values.map(v => '<option value="' + esc(v) + '">' + esc(v) + '</option>').join('');
                $(id).value = pnFilter[key];
            }
            $('viewMode').onchange = function () {
                viewMode = this.value;
                selected = null;
                try { buildSubjectColors(colorScopeCards()); } catch (e) { }
                if (typeof renderWeeklyLayerUi === 'function') renderWeeklyLayerUi();
                if (board) fillWeekSel();
                renderGrid();
                syncUrl();
            };
            // Kartaning tanlangan haftadagi (yoki shablon) effektiv joylashuvi: {day,pair} yoki null
            // Karta QAYSI haftalarda o'tiladi (hafta istisnolaridan: bekor qilinmaganlari).
            // Ma'ruza haftalari semestr bo'ylab tarqatilgan — kartada "6 hafta: 1,3,6..."
            // ko'rinishida chiqadi. Ro'yxat uzun bo'lsa qisqartiriladi.
            function activeWeeksOf(c, totalWeeks) {
                const total = Math.max(1, Math.min(+totalWeeks || 1, +c.term_weeks || +totalWeeks || 1));
                const out = [];
                for (let w = 1; w <= total; w++) {
                    const ov = overrides[c.id + '|' + w];
                    if (!(ov && ov.cancelled)) out.push(w);
                }
                // Hamma haftada o'tilsa — raqamlarni ko'rsatish shart emas
                if (out.length >= total) return [];
                return out.length > 10 ? out.slice(0, 10).concat(['…']) : out;
            }

            function effPlace(c) {
                if (curWeek && c.term_weeks && curWeek > +c.term_weeks) return null;
                if (!curWeek) return c.day ? { day: c.day, pair: c.pair } : null;
                const ov = overrides[c.id + '|' + curWeek];
                // Tashqi qatlamda haftaga xos ko'chirishlar (ichki jadvalniki) hisobga olinmaydi, faqat o'tilmaydigan haftalar.
                if (weeklyLayer === 'external') {
                    if ((ov && ov.cancelled) || !c.day) return null;
                    // Shu haftada o'tilmaydigan dars (masalan ma'ruza) bo'shatgan joyga
                    // keyingi darslar yuqoriga suriladi — kun o'rtasida bo'sh para qolmaydi.
                    const sh = externalCompactMap()[c.id];
                    return { day: c.day, pair: sh || c.pair };
                }
                if (ov) return ov.cancelled ? null : { day: ov.day, pair: ov.pair };
                return c.day ? { day: c.day, pair: c.pair } : null;
            }
            // Tashqi qatlam, alohida hafta: shablonda band bo'lgan, lekin shu haftada
            // bo'shab qolgan (o'tilmaydigan karta egallagan yoki yuqoriga surilgan karta
            // tashlab ketgan) yarim-slotlarga keyingi darslar ketma-ket suriladi.
            // Shablondagi ataylab bo'sh joylar (masalan kun IV paradan boshlansa) to'ldirilmaydi.
            // Natija: { cardId: yangi pair } — faqat surilgan kartalar uchun.
            let compactCache = null;
            function externalCompactMap() {
                const sig = curWeek + '|' + weeklyLayer + '|' + cards.length;
                if (compactCache && compactCache.sig === sig) return compactCache.map;
                const map = {};
                if (curWeek && weeklyLayer === 'external') {
                    const tmpl = {};   // gkey|day -> Set(shablonda band yarim-slotlar)
                    const act = [];
                    cards.forEach(c => {
                        if (!c.day || !c.pair || isCycleCardAny(c)) return;
                        const len = cardLen(c);
                        cardGroups(c).forEach(g => {
                            const k = gkey(c, g) + '|' + c.day;
                            const set = tmpl[k] || (tmpl[k] = new Set());
                            for (let i = 0; i < len; i++) set.add(c.pair + i);
                        });
                        if (!weekCancelled(c)) act.push(c);
                    });
                    act.sort((a, b) => (a.day - b.day) || (a.pair - b.pair) || (cardLen(b) - cardLen(a)));
                    const used = {};   // gkey|day -> Set(shu haftada haqiqatan band slotlar)
                    act.forEach(c => {
                        const len = cardLen(c);
                        const keys = cardGroups(c).map(g => gkey(c, g) + '|' + c.day);
                        let start = c.pair;
                        // Har bir guruh uchun yuqoridagi slot bo'sh va shablonda band bo'lsa — bir qadam yuqoriga
                        while (start > 1 && keys.length && keys.every(k =>
                            tmpl[k].has(start - 1) && !(used[k] && used[k].has(start - 1)))) start--;
                        // Juft yarim-slot chegarasini saqlash (para o'rtasidan boshlanmasin)
                        if (len > 1 && (c.pair - start) % 2) start++;   // yarim para dars yarim-slot bo'shliqqa ham suriladi
                        if (start !== c.pair) map[c.id] = start;
                        keys.forEach(k => {
                            const set = used[k] || (used[k] = new Set());
                            for (let i = 0; i < len; i++) set.add(start + i);
                        });
                    });
                }
                compactCache = { sig, map };
                return map;
            }
            const resetCompactCache = () => { compactCache = null; };
            // Tanlangan haftada vaqt bilan birga auditoriya ham individual
            // override'dan olinadi; shablon ko'rinishida bazaviy xona qoladi.
            function effectiveCard(c) {
                if (!curWeek || weeklyLayer === 'external') return c;
                const ov = overrides[c.id + '|' + curWeek];
                if (!ov || ov.cancelled || !ov.auditorium_code) return c;
                return {
                    ...c,
                    auditorium_code: ov.auditorium_code,
                    auditorium_name: ov.auditorium_name || ov.auditorium_code,
                    auditorium_volume: ov.auditorium_volume || null,
                };
            }
            // Karta shu haftada shablondan farq qiladimi (individual)?
            const hasWeekOverride = c => curWeek && !!overrides[c.id + '|' + curWeek];
            // Karta shu haftada umuman o'tilmaydimi (bekor qilingan / almashinuvchi
            // fanning "bo'sh" haftasi)? Bunday karta joylashmagan hisoblanmaydi —
            // u shu haftaga tegishli emas, shuning uchun panel va statistikadan
            // butunlay chiqarib tashlanadi.
            const weekCancelled = (c) => {
                if (!curWeek) return false;
                if (c.term_weeks && curWeek > +c.term_weeks) return true;
                const ov = overrides[c.id + '|' + curWeek];
                // "Joylanmagan, o'tiladi" (unplaced) — bekor emas: "Joylashmagan kartalar"da.
                return !!(ov && ov.cancelled && !ov.unplaced);
            };
            // Tanlangan haftada haqiqatan o'tiladigan kartalar (shablon ko'rinishida — hammasi)
            const weekActiveCards = () => visibleSpecCards().filter(c => !weekCancelled(c));
            // Panelda "bu haftada o'tilmaydi" kartalari ham ko'rsatilsinmi (odatda — yo'q)
            let showSkipped = false;
            // Panjara saqlash endi Sozlamalar modalidagi har bir kurs katagida bajariladi.

            // Ko'rinayotgan tanlov qamrovi — backendga yuboriladigan massivlar
            // (tanlangan fakultet/yo'nalish/kurs). "Butun doska" da qamrov yuborilmaydi.
            function scopeBody() {
                return {
                    faculty_names: [...selectedFaculties],
                    specialty_names: [...selectedDirs],
                    courses: [...selectedCourses].sort((a, b) => a - b),
                };
            }
            function scopeLabelText() {
                const fl = selectedFaculties.size > 1 ? (selectedFaculties.size + ' fakultet') : facLabel([...selectedFaculties][0]);
                const dl = selectedDirs.size > 1 ? (selectedDirs.size + ' yo\'nalish') : ([...selectedDirs][0] || '—');
                const cl = [...selectedCourses].sort((a, b) => a - b).join(',') + '-kurs';
                return fl + ' · ' + dl + ' · ' + cl;
            }

            // Ko'rinayotgan qamrovdagi barcha joylashuvlarni bo'shatish (panelga qaytarish)
            $('unplaceBtn').onclick = async function () {
                if (!board || !curSpec) return;
                // "Faqat meniki" ko'rinishi to'liq emas, bo'shatish esa butun qamrovga
                // (boshqalarning darslariga ham) ta'sir qiladi — bu rejimda o'chirilgan.
                if (mineOnly) {
                    alert('"' + scopeModeLabel() + '" rejimida bo‘shatish o‘chirilgan. Avval "Butun doska" ga qayting.');
                    return;
                }
                if (viewMode === 'cycle') {
                    // Bu qatlam faqat ko'rish uchun — server ham rad etadi (403)
                    if (cyclePlanData && cyclePlanData.can_edit === false) {
                        alert('Bu qatlamdagi sikl bloklarini bo‘shatish huquqingiz yo‘q.');
                        return;
                    }
                    if (!confirm('Tanlangan guruhlarning sikl bloklari panelga qaytarilsinmi?')) return;
                    this.disabled = true;
                    $('autoMsg').textContent = 'Sikl bloklari bo‘shatilmoqda...';
                    try {
                        await loadCyclePlan({ clear: true });
                        $('autoMsg').textContent = 'Sikl bloklari panelga qaytarildi.';
                    } catch (e) {
                        $('autoMsg').textContent = '';
                        alert('Sikl bloklarini bo‘shatib bo‘lmadi: ' + e.message);
                    }
                    this.disabled = false;
                    return;
                }
                const whole = $('autoScope').checked;
                const scopeLabel = whole ? 'Butun doska' : scopeLabelText();
                if (!confirm(scopeLabel + ' bo\'yicha barcha joylashuvlar bo\'shatilib, kartochkalar panelga qaytariladi. Davom etamizmi?')) return;
                this.disabled = true; $('autoMsg').textContent = 'Bo\'shatilmoqda...';
                try {
                    const body = { layer: weeklyLayer };
                    if (!whole) Object.assign(body, scopeBody());
                    if (typeFilter !== 'all') body.training_type = typeFilter;
                    const j = await api(BASE + '/boards/' + board.id + '/unplace', 'POST', body);
                    await loadBoard(board.id);
                    $('autoMsg').textContent = (j.unplaced || 0) + ' ta joylashuv bo\'shatildi';
                } catch (e) { $('autoMsg').textContent = ''; alert('Xatolik: ' + e.message); }
                this.disabled = false;
            };

            // ===== Yordamchilar =====
            let viewMode = DEFAULT_VIEW;   // group | teacher | room | subject (jadval kesimi)
            if ($('viewMode')) $('viewMode').value = viewMode;
            // Ko'rinadigan kartalar — tanlangan fakultet(lar) × yo'nalish(lar) × kurs(lar) kesishmasi.
            const multiSpec = () => selectedDirs.size > 1;
            // Sikl rejimidagi fan — haftalik panjaraga tushmaydi (faqat sikl kalendarida).
            const isCycleCard = c => (subjectSettings[subjModeKey(c.specialty_name, c.course, c.subject_name)] || {}).mode === 'cycle';
            // Bo'lakli fan ("Fan (a)") sozlamasi asosiy nom bilan saqlangan bo'lishi mumkin.
            const isCycleCardAny = c => isCycleCard(c)
                || isCycleCard(Object.assign({}, c, { subject_name: String(c.subject_name || '').replace(/\s*\(\p{L}\)\s*$/u, '') }));
            const specCards = () => cards.filter(c =>
                selectedFaculties.has(c.faculty_name || '') &&
                selectedDirs.has(c.specialty_name) &&
                selectedCourses.has(c.course) &&
                !isCycleCardAny(c));
            const cardGroups = c => (c.group_names && c.group_names.length) ? c.group_names : (c.group_name ? [c.group_name] : []);
            // Xona qidiruvi uchun normallashtirish: kichik harf, tutuq belgilari (ʼ ʻ ' ‘ ’ `) bitta "'", o'zbek kirill → lotin
            // (ш→sh, ч→ch, ў→o', қ→q, ғ→g', ҳ→h, ё→yo, ю→yu, я→ya …) — kirill so'rov lotin nomni, lotin so'rov kirill nomni topadi.
            const UZ_CYR_LAT = { 'а': 'a', 'б': 'b', 'в': 'v', 'г': 'g', 'д': 'd', 'е': 'e', 'ё': 'yo', 'ж': 'j', 'з': 'z', 'и': 'i', 'й': 'y',
                'к': 'k', 'л': 'l', 'м': 'm', 'н': 'n', 'о': 'o', 'п': 'p', 'р': 'r', 'с': 's', 'т': 't', 'у': 'u', 'ф': 'f', 'х': 'x', 'ц': 'ts',
                'ч': 'ch', 'ш': 'sh', 'щ': 'sh', 'ъ': "'", 'ы': 'i', 'ь': '', 'э': 'e', 'ю': 'yu', 'я': 'ya', 'ў': "o'", 'қ': 'q', 'ғ': "g'", 'ҳ': 'h' };
            function searchNorm(v) {
                return String(v == null ? '' : v).toLowerCase().replace(/[ʼʻ‘’`´]/g, "'").replace(/[а-яёўқғҳ]/g, ch => UZ_CYR_LAT[ch] ?? ch);
            }
            // Xona so'z bo'yicha: so'rov so'zlarga bo'linadi, har so'z kod, nom, bino yoki xona turidan birida bo'lishi kerak (tartib muhim emas).
            // nameOnly — xona nomi va bino nomi bo'yicha, kod emas (server ro'yxati — "Boshqa xona tanlash", fan mas'uli oynasi: "510" kodi 510
            // bo'lgan boshqa xonani topmasin); boshqa oynalar — hammasi.
            function roomMatches(room, q, nameOnly = false) {
                const words = searchNorm(q).split(/\s+/).filter(Boolean);
                if (!words.length) return true;
                const fields = (nameOnly ? [room.name, room.building, room.building_name] : [room.code, room.name, room.building_name, room.auditorium_type_name]).map(searchNorm);
                return words.every(w => fields.some(f => f.includes(w)));
            }
            // Server xonalar ro'yxati (room-options / responsible-move check) — umumiy ko'rinish: sarlavha ("Seshanba, 24.11 15:00–16:20 uchun:
            // 120 bo'sh, 35 band · 8 sig'maydi · 12 biriktirilgan"), bino guruhlari sarlavhalari (server tartibi: hozirgi → shu bino → boshqa
            // binolar nomi bo'yicha → "Bino ko'rsatilmagan"; guruh ichida bo'sh tepada) va qatordagi bino yorlig'i.
            function roomListHeadText(when, rooms) {
                const n = k => rooms.filter(r => !r.current && (k === 'free' ? r.free : r.kind === k)).length;
                const extra = [n('capacity') ? n('capacity') + " sig'maydi" : '', n('assigned') ? n('assigned') + ' biriktirilgan' : ''].filter(Boolean);
                return (when ? when + ' uchun: ' : '') + n('free') + " bo'sh, " + n('busy') + ' band' + (extra.length ? ' · ' + extra.join(' · ') : '');
            }
            // Qatorlar orasiga guruh sarlavhasi (r.group o'zgarganda; hozirgi xona — guruhsiz, tepada). rowHtml(r) — qator.
            function roomListGrouped(rooms, rowHtml, headHtml) {
                let last = null;
                return rooms.map(r => {
                    const g = r.current ? null : (r.group || null);
                    const head = g && g !== last ? headHtml(g) : '';
                    if (!r.current) last = g;
                    return head + rowHtml(r);
                }).join('');
            }
            const roomBuildingTag = r => r && r.building ? r.building : '';
            // Ma'ruza yorlig'i: "Ma'ruza · 1-oqim (02a, 02b, 03a …)" — guruhchalar umumiy prefiksisiz ("p/st24-"), 8 tadan ko'p
            // bo'lsa "… +N"; to'liq ro'yxat — title (sichqoncha ustida).
            function lectureLabel(oqim, groups) {
                const list = [...new Set((groups || []).map(g => String(g || '').trim()).filter(Boolean))]
                    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));
                const head = "Ma'ruza · " + (oqim || 'oqim');
                if (!list.length) return { text: head, title: '' };
                let pre = list[0];
                list.forEach(g => { while (pre && !g.startsWith(pre)) pre = pre.slice(0, -1); });
                // Prefiks ajratgichgacha (-, /, bo'shliq) qisqartiriladi: "p/st24-0" → "p/st24-".
                const cut = Math.max(pre.lastIndexOf('-'), pre.lastIndexOf('/'), pre.lastIndexOf(' '));
                pre = cut >= 0 ? pre.slice(0, cut + 1) : '';
                const short = list.map(g => g.slice(pre.length) || g);
                const shown = short.length > 8 ? short.slice(0, 8).join(', ') + ' … +' + (short.length - 8) : short.join(', ');
                return { text: head + ' (' + shown + ')', title: list.join(', ') };
            }
            // Guruh identifikatori. Guruh NOMI fakultetlar bo'ylab takrorlanishi mumkin
            // (mas. 1-kurs "1K-01a (o'z)" ham 1-son, ham 2-son davolashda bor), shuning
            // uchun panjara/konflikt kaliti nom emas — fakultet+yo'nalish+kurs+nom.
            const gkey = (c, g) => (c.faculty_name || '') + '¦' + (c.specialty_name || '') + '¦' + c.course + '¦' + g;
            const cardGKeys = c => cardGroups(c).map(g => gkey(c, g));

            // ===== Birlik: dars yaxlit joylanadi =====
            // Bir kunda guruhning bitta fandan amaliy soatlari bo'linmaydi: birlik — bir guruh, bir fan, bir tur va bir o'qituvchining
            // barcha bo'laklari (masalan 2 soat + 1 soat kartalari), tanlangan haftada o'tiladiganlari. Serverdagi weeklyUnitKey bilan
            // bir xil. Ma'ruza — o'zi birlik.
            const unitKey = c => c.training_type === 'lecture' ? 'L#' + c.id
                : [String(c.faculty_name || '').trim().toLowerCase(), String(c.specialty_name || '').trim().toLowerCase(), +c.course,
                    String(c.group_name || '').trim().toLowerCase(), String(c.subject_name || '').trim().toLowerCase(), c.training_type, +c.teacher_id || 0].join('|');
            // Ichki jadvaldagi W-haftadagi joy (W = 0 — shablon).
            function placeInWeek(c, W) {
                if (W && c.term_weeks && W > +c.term_weeks) return null;
                const ov = W ? overrides[c.id + '|' + W] : null;
                if (ov) return ov.cancelled || !ov.day || !ov.pair ? null : { day: +ov.day, pair: +ov.pair };
                return c.day && c.pair ? { day: +c.day, pair: +c.pair } : null;
            }
            // Shu hafta "vaqtincha kafedra mudirida" (haftalik yozuvdagi belgi): {teacher_name (mudir), mudir_name, orig_teacher_name, …} | null.
            const phOf = (c, W = curWeek) => (c && W && overrides[c.id + '|' + W] && overrides[c.id + '|' + W].mudir_placeholder) || null;
            const activeInWeek = (c, W) => !(W && c.term_weeks && W > +c.term_weeks)
                && !(W && overrides[c.id + '|' + W] && overrides[c.id + '|' + W].cancelled && !overrides[c.id + '|' + W].unplaced);
            // Birlik indeksi (kalit → kartalar) — panel/zichlash kabi ko'p chaqiriladigan joylar uchun bir marta quriladi.
            function buildUnitIndex(list = cards) {
                const m = new Map();
                list.forEach(c => { const k = unitKey(c); if (!m.has(k)) m.set(k, []); m.get(k).push(c); });
                return m;
            }
            // Kartaning birligi (shu haftada o'tiladigan bo'laklar): joylanganlar joyi bo'yicha, keyin joylanmaganlar.
            function unitOf(c, W = curWeek, index = null) {
                if (c.training_type === 'lecture') return [c];
                const all = index ? (index.get(unitKey(c)) || [c]) : cards.filter(x => unitKey(x) === unitKey(c));
                const list = all.filter(x => x === c || activeInWeek(x, W));
                return list.sort((a, b) => {
                    const pa = placeInWeek(a, W), pb = placeInWeek(b, W);
                    return (!pa) - (!pb) || (pa && pb ? pa.pair - pb.pair : 0) || a.id - b.id;
                });
            }
            const unitLen = list => list.reduce((s, c) => s + cardLen(c), 0);
            // Qisman joylangan: bir qismi joylangan, qolgani joylanmagan. Bo'lingan (split): hamma bo'lak joylangan, lekin turli kunlarda
            // yoki bir kunda oraliq bilan (serverdagi unitSplitInfo).
            function unitState(c, W = curWeek, index = null) {
                const list = unitOf(c, W, index), placed = list.filter(x => placeInWeek(x, W));
                return { list, placed, len: unitLen(list), partial: placed.length > 0 && placed.length < list.length,
                    split: placed.length > 1 && placed.length === list.length && unitIsSplit(list, W) };
            }
            function unitIsSplit(list, W = curWeek) {
                const pl = list.map(x => [x, placeInWeek(x, W)]).filter(([, at]) => at);
                if (pl.length < 2) return false;
                if (new Set(pl.map(([, at]) => at.day)).size > 1) return true;
                pl.sort((a, b) => a[1].pair - b[1].pair || a[0].id - b[0].id);
                return pl.some(([, at], i) => i > 0 && at.pair !== pl[i - 1][1].pair + cardLen(pl[i - 1][0]));
            }
            // Joylangan bo'laklar kunlar bo'yicha: "Seshanba 08:30–09:50; Chorshanba 10:00–13:20" (kun ichida ketma-ketlari — bitta oraliq).
            function unitDaysText(list, W = curWeek) {
                const byDay = {};
                list.forEach(x => { const at = placeInWeek(x, W); if (at) (byDay[at.day] = byDay[at.day] || []).push([at.pair, at.pair + cardLen(x)]); });
                return Object.keys(byDay).map(Number).sort((a, b) => a - b).map(d => {
                    const segs = [];
                    byDay[d].sort((a, b) => a[0] - b[0]).forEach(r => { const l = segs[segs.length - 1]; if (l && l[1] === r[0]) l[1] = r[1]; else segs.push(r.slice()); });
                    return (boardDayNames()[d - 1] || d + '-kun') + ' ' + segs.map(r => slotRangeText(r[0], r[1] - r[0])).join(', ');
                }).join('; ');
            }
            // Ko'p bo'lakli amaliy dars shu haftada: bo'lak (d, p) ga tushadigan qilib butun birlik — [[bo'lak, para], ...] (birinchi bo'lak
            // boshidan, o'z tartibida ketma-ket); ma'ruza / bitta bo'lakli dars — null.
            function unitMovePlan(c, p, W = curWeek) {
                if (!c || c.training_type === 'lecture' || !W || !activeInWeek(c, W)) return null;
                const list = unitOf(c, W);
                if (list.length < 2) return null;
                let at = p - unitLen(list.slice(0, list.indexOf(c)));
                return list.map(x => { const r = [x, at]; at += cardLen(x); return r; });
            }
            // Yarim-slot (qator) vaqti: boshlanishi / tugashi.
            const slotStart = p => { const it = boardSchedule().filter(x => x.type === 'pair')[p - 1]; return it ? (it.start || '') : ''; };
            const slotEnd = p => { const it = boardSchedule().filter(x => x.type === 'pair')[p - 1]; return it ? (it.end || '') : ''; };
            // "12:40–15:00": p dan boshlanadigan len yarim-slotli dars.
            const slotRangeText = (p, len) => (slotStart(p) && slotEnd(p + len - 1) ? slotStart(p) + '–' + slotEnd(p + len - 1) : '');
            // Server javobidagi birlik holati (unit-place → unit) — mahalliy joylashuvga.
            function applyUnitPayload(unit, W) {
                (unit || []).forEach(u => {
                    const c = cards.find(x => x.id === +u.id);
                    if (!c) return;
                    if (!W) {
                        // Ko'rinadigan joy (day/pair) — ikkala qatlamda ham (tashqida applyWeeklyLayer ext_* ni day/pair ga ko'chiradi);
                        // saqlangan qatlam maydoni — rememberLayerPlace (tashqi: ext_*, ichki: _int).
                        if (weeklyLayer === 'external') { c.ext_day = u.day; c.ext_pair = u.pair; }
                        c.day = u.day; c.pair = u.pair;
                        rememberLayerPlace(c, u.day, u.pair);
                        return;
                    }
                    const k = c.id + '|' + W;
                    if (u.active && u.day) overrides[k] = Object.assign({}, overrides[k] || {}, { day: u.day, pair: u.pair, cancelled: false });
                    else if (!u.active) overrides[k] = Object.assign({}, overrides[k] || {}, { day: null, pair: null, cancelled: true, auditorium_code: null, auditorium_name: null });
                    else delete overrides[k];
                });
            }
            // Birlikni yaxlit joylash / surish (d, p — birinchi bo'lak boshlanishi) yoki olib tashlash (d = p = null). Sig'masa — xato
            // (server sababi: "4 soat sig'maydi: 13:30 dan keyin 3 soat bo'sh — …"), hech narsa o'zgarmaydi. Boshlanish jadvaldan tashqarida
            // (masalan 2-bo'lak 2-qatorga — birinchi bo'lak 0-qatorga tushadi) — xato: so'rov "olib tashlash" bo'lib ketmasin.
            async function placeUnitAt(c, d, p, W = curWeek) {
                weeklyEditGuard();
                const remove = d == null && p == null;
                if (!remove && !(+d >= 1 && +p >= 1)) throw new Error('Tanlangan vaqt jadval chegarasidan tashqarida.');
                const week = weeklyLayer === 'external' ? 0 : (W || 0);
                const body = { layer: weeklyLayer };
                if (week) body.week = week;
                if (!remove) { body.day = d; body.pair = p; }
                const j = await api(BASE + '/cards/' + c.id + '/unit-place', 'POST', body);
                applyUnitPayload(j && j.unit, week);
                return j;
            }
            // Guruh kunidagi bo'shliq ("oyna"): birinchi va oxirgi dars orasidagi bo'sh yarim-slotlar (katta tanaffus qator emas —
            // hisoblanmaydi). rows — band qatorlar to'plami.
            function gapsOf(rows) {
                if (!rows.size) return 0;
                const xs = [...rows];
                const lo = Math.min(...xs), hi = Math.max(...xs);
                return hi - lo + 1 - rows.size;
            }
            // Guruhlar kunidagi band qatorlar: "gkey|kun" → Set. skip — hisobga olinmaydigan karta id lari (surilayotgan birlik).
            function groupDayRows(W, skip = new Set()) {
                const out = {};
                cards.forEach(c => {
                    if (skip.has(c.id) || isCycleCardAny(c)) return;
                    const pl = placeInWeek(c, W);
                    if (!pl) return;
                    cardGKeys(c).forEach(k => {
                        const s = out[k + '|' + pl.day] || (out[k + '|' + pl.day] = new Set());
                        for (let i = 0; i < cardLen(c); i++) s.add(pl.pair + i);
                    });
                });
                return out;
            }
            // Birlikni d kuni p dan qo'yish guruhlar bo'shlig'ini qanchaga o'zgartiradi (manfiy — kamaytiradi) va guruhning mavjud
            // darsiga yopishadimi (oldidan yoki ketidan, oraliqsiz). rows — groupDayRows(W, birlik id lari).
            function unitGapEffect(list, d, p, rows) {
                const len = unitLen(list);
                let delta = 0, touch = false;
                [...new Set(list.flatMap(cardGKeys))].forEach(k => {
                    const cur = rows[k + '|' + d] || new Set();
                    const next = new Set(cur);
                    for (let i = 0; i < len; i++) next.add(p + i);
                    delta += gapsOf(next) - gapsOf(cur);
                    if (cur.has(p - 1) || cur.has(p + len)) touch = true;
                });
                return { delta, touch };
            }
            // Dars turi filtri (Hammasi / Ma'ruza / Amaliy) — panel, panjara va statistikaga ta'sir qiladi
            let typeFilter = 'all';
            const typeVisible = c => typeFilter === 'all' || c.training_type === typeFilter;
            const visibleSpecCards = () => specCards().filter(typeVisible);

            // Fan rejimi Darslar jadvalidagi har bir qator ichida boshqariladi.
            function subjectModeParamsHtml(setting) {
                const mode = setting.mode || 'normal';
                if (mode === 'alternate') {
                    return '<span class="asc-subj-param">Guruh <input class="asc-subj-group" maxlength="40" value="' + esc(setting.rotation_group || '') + '" placeholder="A"></span>' +
                        '<span class="asc-subj-param">Hafta <input type="number" class="asc-subj-occ" min="1" max="60" value="' + (setting.occurrences ?? '') + '" placeholder="—"></span>';
                }
                if (mode === 'cycle') {
                    // Fakultet / o'quv reja bo'yicha alohida kunlar soni (openSubjScopeDlg): saqlanganlar soni bilan.
                    const n = (setting.scoped || []).length;
                    // "Ma'ruza alohida" (umumiy daraja): kunlik ma'ruza soatlari (SOATDA); sikl kunlari — jami (ma'ruza + amaliy).
                    const lec = setting.lecture && setting.lecture.on ? setting.lecture : null;
                    return '<span class="asc-subj-param">Sikl <input type="number" class="asc-subj-cycle" min="1" max="120" value="' + (setting.cycle_days ?? '') + '" placeholder="kun"></span>'
                        + '<label class="asc-subj-param asc-subj-lec" title="Ma\'ruza amaliy blokidan alohida blok bo\'lib joylanadi (kunlik soatlar ro\'yxati, soatda)">'
                        + '<input type="checkbox" class="asc-subj-lecon"' + (lec ? ' checked' : '') + '> Ma\'ruza alohida</label>'
                        + '<input class="asc-subj-lechours" value="' + esc(lec ? (lec.hours || []).join(',') : '') + '" placeholder="8,8,6,6,6"' + (lec ? '' : ' hidden')
                        + ' title="Kunlik ma\'ruza soatlari (soatda, vergul bilan)">'
                        + '<button type="button" class="asc-subj-scope" title="Shu fan uchun fakultet yoki o\'quv reja bo\'yicha alohida sikl kunlari soni va ma\'ruza">'
                        + 'Fakultet / o\'quv reja bo\'yicha alohida' + (n ? ' (' + n + ')' : '') + '</button>';
                }
                return '<span class="text-slate-400">—</span>';
            }

            // Fan sozlamasini saqlash: sikl kunlari soni o'zgarsa — avval oldindan ko'rish (dry_run); joylangan bloklar uzunligi o'zgarsa —
            // tasdiq oynasi ("N ta joylangan blok uzunligi o'zgaradi" + ro'yxat). Bekor — null.
            async function subjSettingSave(body) {
                const url = BASE + '/boards/' + board.id + '/subject-setting';
                if (body.mode === 'cycle') {
                    const dry = await api(url, 'POST', Object.assign({}, body, { dry_run: 1 }));
                    if ((dry.affected || []).length && !(await subjAffectedConfirm(dry.affected))) return null;
                }
                return api(url, 'POST', body);
            }
            function subjAffectedConfirm(list) {
                return new Promise(resolve => {
                    const prior = document.getElementById('subjAffectDlg');
                    if (prior) prior.remove();
                    const m = document.createElement('div');
                    m.id = 'subjAffectDlg';
                    m.className = 'cr-proposal-overlay';
                    m.innerHTML = '<div class="cr-proposal-form"><h3 class="font-bold text-lg">' + list.length + ' ta joylangan blok uzunligi o\'zgaradi</h3>'
                        + '<ul class="saf-list">' + list.map(a => '<li><b>' + esc(a.faculty || '—') + '</b> · ' + esc(a.row) + (a.type === 'lecture' ? ' (ma\'ruza)' : '')
                            + ': ' + esc(a.from == null ? '—' : String(a.from)) + ' → ' + esc(a.to == null ? '—' : String(a.to)) + ' kun</li>').join('') + '</ul>'
                        + '<div class="flex justify-end gap-2"><button type="button" data-saf="cancel">Bekor</button>'
                        + '<button type="button" data-saf="ok" class="px-3 py-2 rounded bg-blue-600 text-white">Saqlash</button></div></div>';
                    document.body.appendChild(m);
                    const done = v => { m.remove(); resolve(v); };
                    m.onclick = ev => { if (ev.target === m) done(false); };
                    m.querySelector('[data-saf="cancel"]').onclick = () => done(false);
                    m.querySelector('[data-saf="ok"]').onclick = () => done(true);
                });
            }
            // "Fakultet / o'quv reja bo'yicha alohida": shu yo'nalish va kursdagi fakultetlar, har fakultet ichida o'quv rejalar (nomi,
            // semestri, guruh prefiksi, guruhlar soni). Bo'sh — yuqori daraja: avval fakultet, keyin umumiy. O'zgarishi bilan saqlanadi
            // (joylangan bloklar o'zgarsa — tasdiq oynasi).
            // Ma'ruza sozlamasi matni: {on, hours} → "alohida 8+8+6+6+6" / "amaliy ichida"; null — meros.
            const subjLecText = lec => !lec ? null : (lec.on && (lec.hours || []).length ? 'alohida ' + lec.hours.join('+') : 'amaliy ichida');
            async function openSubjScopeDlg(row, onSaved) {
                const prior = document.getElementById('subjScopeDlg');
                if (prior) prior.remove();
                const m = document.createElement('div');
                m.id = 'subjScopeDlg';
                m.className = 'cr-proposal-overlay';
                m.innerHTML = '<div class="cr-proposal-form"><div class="text-slate-500">Yuklanmoqda…</div></div>';
                document.body.appendChild(m);
                m.onclick = ev => { if (ev.target === m) m.remove(); };
                const qs = new URLSearchParams({ specialty_name: row.specialty_name, course: row.course, subject_name: row.subject_name });
                const render = async () => {
                    let j;
                    try { j = await api(BASE + '/boards/' + board.id + '/subject-setting/scopes?' + qs); }
                    catch (e) { m.querySelector('.cr-proposal-form').innerHTML = '<p class="text-red-600">' + esc(e.message) + '</p>'; return; }
                    const general = j.days != null ? j.days : 1;
                    const shortFac = n => String(n || '—').replace(/\s+fakulteti$/i, '');
                    const genLec = subjLecText(j.lecture && j.lecture.on ? j.lecture : null) || 'amaliy ichida';
                    // "Ma'ruza alohida" (kunlik soatlar, SOATDA): meros — yuqori daraja; amaliy ichida — hozirgidek; alohida — ro'yxat.
                    const lecCtl = (key, lec, inherited) => '<span class="ssc-lec"><select data-ssl="' + key + '" title="Ma\'ruza: alohida blok (kunlik soatlar) yoki amaliy blok ichida">'
                        + '<option value="inherit"' + (!lec ? ' selected' : '') + '>ma\'ruza: meros (' + esc(inherited) + ')</option>'
                        + '<option value="off"' + (lec && !lec.on ? ' selected' : '') + '>ma\'ruza amaliy ichida</option>'
                        + '<option value="on"' + (lec && lec.on ? ' selected' : '') + '>ma\'ruza alohida</option></select>'
                        + '<input data-sslh="' + key + '" value="' + esc(lec && lec.on ? (lec.hours || []).join(',') : '') + '" placeholder="8,8,6,6,6" title="Kunlik ma\'ruza soatlari (soatda, vergul bilan; har kun 1–' + (j.day_hours || 12) + ')"'
                        + (lec && lec.on ? '' : ' hidden') + '> soat</span>';
                    m.querySelector('.cr-proposal-form').innerHTML = '<h3 class="font-bold text-lg">Fakultet / o\'quv reja bo\'yicha alohida</h3>'
                        + '<p class="text-sm">' + esc(row.subject_name + ' · ' + row.specialty_name + ' · ' + row.course + '-kurs') + ' — umumiy: <b>' + general
                        + ' kun</b>, ma\'ruza: <b>' + esc(genLec) + '</b>' + (j.plan_lecture_hours != null ? ' (rejada ' + j.plan_lecture_hours + ' soat)' : '')
                        + '. Bo\'sh — yuqori daraja (avval fakultet, keyin umumiy). Ma\'ruza alohida bo\'lsa, sikl kunlari — jami (masalan 21 = 5 ma\'ruza + 16 amaliy).</p><div class="ssc-list">'
                        + (j.faculties || []).map((f, fi) => {
                            const facLec = subjLecText(f.lecture) || genLec;
                            return '<div class="ssc-fac"><div class="ssc-row"><label><b>' + esc(f.name || '—') + '</b> '
                            + '<input type="number" min="1" max="120" data-ssc="' + fi + '" value="' + (f.days ?? '') + '" placeholder="umumiy: ' + general + '"> kun</label>'
                            + lecCtl(String(fi), f.lecture, genLec) + '</div>'
                            + (f.curricula || []).map((c, ci) => '<div class="ssc-row ssc-cur"><label><span>' + esc(shortFac(f.name) + ' · ' + (c.prefix || '—') + ' · '
                                + (c.semester || 'semestr —') + ' (' + c.groups + ' guruh)') + '<small>' + esc(c.name) + '</small></span>'
                                + '<input type="number" min="1" max="120" data-ssc="' + fi + '|' + ci + '" value="' + (c.days ?? '') + '"'
                                + ' placeholder="' + (f.days != null ? 'fakultet: ' + f.days : 'umumiy: ' + general) + '"' + (c.id > 0 ? '' : ' disabled title="Guruhlarning o\'quv rejasi aniqlanmagan"') + '> kun</label>'
                                + (c.id > 0 ? lecCtl(fi + '|' + ci, c.lecture, facLec) : '') + '</div>').join('')
                            + '</div>';
                        }).join('')
                        + '</div><p role="alert" class="text-sm"></p><div class="flex justify-end"><button type="button" data-ssc-close>Yopish</button></div>';
                    m.querySelector('[data-ssc-close]').onclick = () => m.remove();
                    const target = key => {
                        const [fi, ci] = key.split('|');
                        const f = j.faculties[+fi];
                        return [f, ci != null ? f.curricula[+ci] : null];
                    };
                    const save = async (key, extra) => {
                        const [f, c] = target(key);
                        const msg = m.querySelector('[role="alert"]');
                        msg.className = 'text-sm text-slate-500';
                        msg.textContent = 'Saqlanmoqda…';
                        const daysInp = m.querySelector('input[data-ssc="' + key + '"]');
                        try {
                            const saved = await subjSettingSave(Object.assign({ specialty_name: row.specialty_name, course: +row.course, subject_name: row.subject_name, mode: 'cycle',
                                faculty_name: f.name, curriculum_hemis_id: c ? c.id : 0, cycle_days: daysInp && daysInp.value ? +daysInp.value : null }, extra));
                            if (!saved) { msg.textContent = 'Bekor qilindi.'; await render(); return; }
                            if (onSaved) await onSaved();
                            await render();
                            const out = m.querySelector('[role="alert"]');
                            const warns = saved.warnings || [];
                            out.className = 'text-sm ' + (warns.length ? 'text-amber-700' : 'text-emerald-700');
                            out.textContent = 'Saqlandi' + ((saved.affected || []).length ? ': ' + saved.affected.length + ' ta blok uzunligi o\'zgardi.' : '.')
                                + (warns.length ? ' ⚠ ' + warns.join(' ') : '');
                        } catch (e) { msg.className = 'text-sm text-red-600'; msg.textContent = e.message; }
                    };
                    m.querySelectorAll('input[data-ssc]').forEach(inp => inp.onchange = () => save(inp.dataset.ssc, {}));
                    // Ma'ruza: "alohida" tanlansa — soatlar kiritilgach saqlanadi; meros / amaliy ichida — darhol.
                    const lecSave = key => {
                        const sel = m.querySelector('select[data-ssl="' + key + '"]'), hrs = m.querySelector('input[data-sslh="' + key + '"]');
                        hrs.hidden = sel.value !== 'on';
                        if (sel.value === 'on' && !hrs.value.trim()) {
                            hrs.focus();
                            const msg = m.querySelector('[role="alert"]');
                            msg.className = 'text-sm text-slate-600';
                            msg.textContent = 'Kunlik ma\'ruza soatlarini kiriting (soatda, vergul bilan, masalan 8,8,6,6,6).';
                            return;
                        }
                        save(key, { lecture: sel.value, lecture_hours: sel.value === 'on' ? hrs.value.trim() : undefined });
                    };
                    m.querySelectorAll('select[data-ssl]').forEach(sel => sel.onchange = () => lecSave(sel.dataset.ssl));
                    m.querySelectorAll('input[data-sslh]').forEach(inp => inp.onchange = () => lecSave(inp.dataset.sslh));
                };
                await render();
            }

            async function saveSubjectModeRow(tr, row) {
                const mode = tr.querySelector('.asc-subj-mode').value;
                const seasonSelect = tr.querySelector('.asc-subj-season');
                const body = {
                    specialty_name: row.specialty_name,
                    course: +row.course,
                    subject_name: row.subject_name,
                    mode,
                    season: seasonSelect ? seasonSelect.value : subjectSeasonOf(row),
                };
                if (mode === 'alternate') {
                    const group = tr.querySelector('.asc-subj-group');
                    const occurrences = tr.querySelector('.asc-subj-occ');
                    if (group && group.value.trim()) body.rotation_group = group.value.trim();
                    if (occurrences && occurrences.value) body.occurrences = +occurrences.value;
                } else if (mode === 'cycle') {
                    const cycle = tr.querySelector('.asc-subj-cycle');
                    if (cycle && cycle.value) body.cycle_days = +cycle.value;
                    // "Ma'ruza alohida": belgi va kunlik soatlar (belgisiz — amaliy ichida, hozirgidek).
                    const lecOn = tr.querySelector('.asc-subj-lecon'), lecHours = tr.querySelector('.asc-subj-lechours');
                    if (lecOn) {
                        body.lecture = lecOn.checked ? 'on' : 'off';
                        if (lecOn.checked) body.lecture_hours = (lecHours && lecHours.value.trim()) || '';
                    }
                }
                const status = tr.querySelector('.asc-subj-status');
                status.textContent = '…';
                status.className = 'asc-subj-status text-slate-400';
                try {
                    const saved = await subjSettingSave(body);
                    const key = subjModeKey(row.specialty_name, row.course, row.subject_name);
                    if (!saved) {
                        // Tasdiq oynasida "Bekor" — avvalgi rejim va qiymat qaytadi.
                        const prev = subjectSettingOf(row);
                        tr.querySelector('.asc-subj-mode').value = prev.mode || 'normal';
                        tr.querySelector('.asc-subj-params').innerHTML = subjectModeParamsHtml({ ...prev, mode: prev.mode || 'normal' });
                        status.textContent = '—';
                        status.className = 'asc-subj-status text-slate-400';
                        return;
                    }
                    const effectiveSeason = (saved && saved.season) || body.season || ((board && board.semester_parity) || 'kuzgi');
                    row.season = effectiveSeason;
                    // Mijozdagi ma'ruza sozlamasi — server ko'rinishida ({on, hours}).
                    const lecState = body.lecture === 'on'
                        ? { on: true, hours: String(body.lecture_hours || '').split(/[\s,;]+/).filter(Boolean).map(Number) }
                        : (body.lecture === 'off' ? { on: false, hours: [] } : subjectSettingOf(row).lecture || null);
                    const { lecture: _l, lecture_hours: _lh, ...plain } = body;
                    if (mode === 'normal' && effectiveSeason === ((board && board.semester_parity) || 'kuzgi')) delete subjectSettings[key];
                    else subjectSettings[key] = { ...subjectSettingOf(row), ...plain, lecture: mode === 'cycle' ? lecState : null, season: effectiveSeason };
                    repaintSubjectSeason(tr, row, effectiveSeason);
                    const warns = (saved && saved.warnings) || [];
                    status.textContent = warns.length ? '⚠' : '✓';
                    status.className = 'asc-subj-status ' + (warns.length ? 'text-amber-600' : 'text-emerald-600');
                    status.title = warns.join('\n');
                    // (Ogohlantirish toast'i — api() ichida.)
                } catch (e) {
                    status.textContent = '✕';
                    status.className = 'asc-subj-status text-red-600';
                    repaintSubjectSeason(tr, row, subjectSeasonOf(row));
                    alert('Xatolik: ' + e.message);
                }
            }

            function autoCycleStorageKey() {
                return board ? 'lms:auto-cycle-backup:' + board.id : '';
            }

            function loadAutoCycleState() {
                if (!board || autoCycleBackup !== null) return;
                try {
                    const raw = localStorage.getItem(autoCycleStorageKey());
                    if (!raw) return;
                    const saved = JSON.parse(raw);
                    if (Array.isArray(saved.backup) && saved.backup.length) {
                        autoCycleBackup = saved.backup;
                        autoCycleApplied = !!saved.applied;
                    }
                } catch (e) {
                    localStorage.removeItem(autoCycleStorageKey());
                }
            }

            function persistAutoCycleState() {
                if (!board) return;
                try {
                    if (autoCycleApplied && autoCycleBackup && autoCycleBackup.length) {
                        localStorage.setItem(autoCycleStorageKey(), JSON.stringify({
                            applied: true,
                            backup: autoCycleBackup,
                        }));
                    } else {
                        localStorage.removeItem(autoCycleStorageKey());
                    }
                } catch (e) { }
            }

            function syncAutoCycleState() {
                loadAutoCycleState();
                const candidates = autoCycleCandidates();
                if (!candidates.length) return;
                const hasCycle = candidates.some(item =>
                    (subjectSettingOf(item.row).mode || 'normal') === 'cycle');
                if (hasCycle) {
                    autoCycleApplied = true;
                } else if (autoCycleBackup) {
                    autoCycleApplied = false;
                    autoCycleBackup = null;
                    persistAutoCycleState();
                }
            }

            function autoCycleCandidates() {
                return ascData.filter(row => [4, 5, 6].includes(+row.course))
                    .map(row => {
                        const total = (+row.lecture || 0) + (+row.practice || 0)
                            + (+row.laboratory || 0) + (+row.seminar || 0);
                        return { row, total, days: Math.max(1, Math.ceil(total / 6)) };
                    })
                    .filter(item => item.total > 0);
            }

            async function autoCycleSubjects() {
                if (!board || ascType !== 'subjects') return;
                const candidates = autoCycleCandidates();
                autoCycleBackup = candidates.map(item => ({
                    row: item.row,
                    previous: { ...subjectSettingOf(item.row) },
                }));
                if (!candidates.length) {
                    $('ascFootMsg').textContent = '4-6 kurslar uchun soatli fan topilmadi.';
                    return;
                }
                if (!confirm('4-6 kursdagi ' + candidates.length + ' ta fan Sikl rejimiga o‘tkaziladi. Kunlar jami soat / 6 bo‘yicha yuqoriga yaxlitlanadi. Davom etamizmi?')) {
                    return;
                }
                const button = $('aBtnAutoCycle');
                if (button) button.disabled = true;
                let savedCount = 0;
                const failed = [];
                try {
                    for (const item of candidates) {
                        const row = item.row;
                        const body = {
                            specialty_name: row.specialty_name,
                            course: +row.course,
                            subject_name: row.subject_name,
                            mode: 'cycle',
                            cycle_days: item.days,
                            season: subjectSeasonOf(row),
                        };
                        try {
                            const saved = await api(BASE + '/boards/' + board.id + '/subject-setting', 'POST', body);
                            const key = subjModeKey(row.specialty_name, row.course, row.subject_name);
                            const season = (saved && saved.season) || body.season;
                            subjectSettings[key] = { ...subjectSettingOf(row), ...body, season };
                            savedCount++;
                        } catch (e) {
                            failed.push(row.subject_name + ' (' + row.course + '-kurs): ' + e.message);
                        }
                        $('ascFootMsg').textContent = 'Sikl sozlanmoqda: ' + savedCount + '/' + candidates.length;
                    }
                    renderAscTable();
                    autoCycleApplied = savedCount > 0;
                    persistAutoCycleState();
                    renderAscButtons();
                    $('ascFootMsg').textContent = 'Avtomatik sikl sozlandi: ' + savedCount + ' ta fan' +
                        (failed.length ? '; xato: ' + failed.length : '') + '. 6 soat = 1 kun.';
                    if (failed.length) {
                        alert('Ba’zi fanlar saqlanmadi:\\n' + failed.slice(0, 5).join('\\n'));
                    }
                } finally {
                    if (button) button.disabled = false;
                }
            }

            // ===== Sikl (4-6 kurs) kalendar ko‘rinishi =====
            async function toggleAutoCycleSubjects() {
                if (autoCycleApplied) {
                    await restoreAutoCycleSubjects();
                    return;
                }
                await autoCycleSubjects();
            }

            async function restoreAutoCycleSubjects() {
                const restoreItems = (autoCycleBackup && autoCycleBackup.length)
                    ? autoCycleBackup
                    : autoCycleCandidates()
                        .filter(item => (subjectSettingOf(item.row).mode || 'normal') === 'cycle')
                        .map(item => ({
                            row: item.row,
                            previous: { mode: 'normal', season: ((board && board.semester_parity) || 'kuzgi') },
                        }));
                if (!restoreItems.length) return;
                if (!confirm('4-6 kurs fanlarining avtomatik Sikldan oldingi rejimi va kunlari tiklansinmi?')) return;
                const button = $('aBtnAutoCycle');
                if (button) button.disabled = true;
                let restoredCount = 0;
                const failed = [];
                try {
                    for (const item of restoreItems) {
                        const row = item.row;
                        const previous = item.previous || {};
                        const mode = previous.mode || 'normal';
                        const body = {
                            specialty_name: row.specialty_name,
                            course: +row.course,
                            subject_name: row.subject_name,
                            mode,
                            season: previous.season || ((board && board.semester_parity) || 'kuzgi'),
                        };
                        if (mode === 'alternate') {
                            if (previous.rotation_group) body.rotation_group = previous.rotation_group;
                            if (previous.occurrences) body.occurrences = previous.occurrences;
                        } else if (mode === 'cycle' && previous.cycle_days) {
                            body.cycle_days = previous.cycle_days;
                        }
                        try {
                            await api(BASE + '/boards/' + board.id + '/subject-setting', 'POST', body);
                            const key = subjModeKey(row.specialty_name, row.course, row.subject_name);
                            if (mode === 'normal' && body.season === ((board && board.semester_parity) || 'kuzgi')) {
                                delete subjectSettings[key];
                            } else {
                                subjectSettings[key] = { ...previous, ...body };
                            }
                            restoredCount++;
                        } catch (e) {
                            failed.push(row.subject_name + ' (' + row.course + '-kurs): ' + e.message);
                        }
                        $('ascFootMsg').textContent = 'Avvalgi holat tiklanmoqda: ' + restoredCount + '/' + restoreItems.length;
                    }
                    if (!failed.length) {
                        autoCycleApplied = false;
                        autoCycleBackup = null;
                    }
                    persistAutoCycleState();
                    renderAscTable();
                    renderAscButtons();
                    $('ascFootMsg').textContent = 'Avtomatik Sikldan oldingi holatga ' + restoredCount + ' ta fan qaytarildi.' +
                        (failed.length ? ' Xato: ' + failed.length : '');
                    if (failed.length) {
                        alert('Ba’zi fanlar qaytarilmadi:\\n' + failed.slice(0, 5).join('\\n'));
                    }
                } finally {
                    if (button) button.disabled = false;
                }
            }

            let cyclePlanData = null;
            let cycleViewMode = 'flow';
            // Sikl jadvalida guruh/oqim bo'yicha filtr ("Guruh" sarlavhasi orqali) — bir nechtasi (checkbox). Qiymat — qatorlarning
            // noyob row_key'lari: qamrovda bir xil nomli guruh boshqa yo'nalish/kursda ham bo'lishi mumkin. Bo'sh — hammasi.
            // Tanlov sahifa yangilanganda ham saqlanadi (localStorage: doska + fakultet/yo'nalish/kurs kaliti).
            let cycleRowFilters = [];
            let cycleRowStoreKey = null;   // tanlov qaysi kalitdan o'qilgan (qamrov o'zgarsa — o'sha qamrovniki o'qiladi)
            // "Ko'rsatish" fokus rejimi: {show, groups, keys, prev, scrolled} — null bo'lsa oddiy ko'rinish (pastda, to'qnashuvlar bo'limida).
            let ttFocus = null;
            function cycleRowStorageKey() {
                const sorted = set => [...set].map(String).sort().join(',');
                return 'tt:cycRows:' + (board ? board.id : 0) + ':' + sorted(selectedFaculties) + '|' + sorted(selectedDirs) + '|' + sorted(selectedCourses);
            }
            function cycleRowFiltersLoad() {
                const key = cycleRowStorageKey();
                if (key === cycleRowStoreKey) return;
                cycleRowStoreKey = key;
                let v = [];
                try { v = JSON.parse(localStorage.getItem(key) || '[]'); } catch (e) { v = []; }
                cycleRowFilters = Array.isArray(v) ? v.map(String) : [];
            }
            function cycleRowFiltersSave() {
                cycleRowStoreKey = cycleRowStorageKey();
                try {
                    if (cycleRowFilters.length) localStorage.setItem(cycleRowStoreKey, JSON.stringify(cycleRowFilters));
                    else localStorage.removeItem(cycleRowStoreKey);
                } catch (e) { /* xususiy oyna / bloklangan saqlash — tanlov faqat shu sahifada */ }
            }
            // Tugma yozuvi: bitta — nomi ("d1/d22-05a"), bir nechta — "3 ta guruh", bo'sh — "Guruh (24)".
            function cycleRowFilterText(allRows, rowWord) {
                const n = cycleRowFilters.length;
                return !n ? rowWord + ' (' + allRows.length + ')'
                    : n === 1 ? (cycleRowLabels(allRows)[cycleRowFilters[0]] || '') : n + ' ta ' + rowWord.toLowerCase();
            }
            function cycleRowFiltersApply() {
                // Fokus paytida qo'lda tanlansa — fokus tugaydi (lenta yopiladi), tanlov oddiygidek saqlanadi.
                if (ttFocus && ttFocus.show.view === 'cycle') ttFocusForget();
                cycleRowFiltersSave();
                if (cyclePlanData) { renderCyclePlan(cyclePlanData); renderCycleCards(cyclePlanData); }
            }
            // Qator yorlig'i — guruh nomi; bir xil nomli qatorlarga yo'nalish va kurs qo'shiladi.
            function cycleRowLabels(rows) {
                const count = {};
                rows.forEach(r => { count[r.group] = (count[r.group] || 0) + 1; });
                const labels = {};
                rows.forEach(r => { labels[r.row_key] = count[r.group] > 1 ? r.group + ' · ' + r.specialty + ', ' + r.course + '-kurs' : r.group; });
                return labels;
            }
            function closeCycRowPop() { const p = document.getElementById('cycRowPop'); if (p) p.remove(); }
            function openCycRowPop(anchor) {
                closeCycRowPop();
                const planRows = (cyclePlanData && cyclePlanData.rows) || [];
                const labels = cycleRowLabels(planRows);
                const names = planRows.map(r => ({ key: r.row_key, label: labels[r.row_key] }));
                const pop = document.createElement('div');
                pop.id = 'cycRowPop';
                pop.innerHTML = '<input type="text" class="cyc-rp-q" placeholder="Qidirish: masalan 01a" autocomplete="off">'
                    + '<div class="cyc-rp-tools"><button type="button" data-rp-all>Hammasi</button><button type="button" data-rp-clear>Tozalash</button></div>'
                    + '<div class="cyc-rp-list"></div>';
                document.body.appendChild(pop);
                const r = anchor.getBoundingClientRect();
                pop.style.left = Math.max(8, r.left) + 'px';
                pop.style.top = (r.bottom + 4) + 'px';
                const list = pop.querySelector('.cyc-rp-list');
                const q = pop.querySelector('.cyc-rp-q');
                // Belgilash darhol qo'llanadi (oyna ochiq qoladi); tanlov qidiruvdan keyin ham saqlanadi (yashirin qatorlar ham).
                const hitsNow = () => { const t = q.value.trim().toLowerCase(); return names.filter(n => !t || n.label.toLowerCase().includes(t)); };
                const draw = () => {
                    const hits = hitsNow(), on = new Set(cycleRowFilters);
                    list.innerHTML = hits.map(n => '<label class="cyc-rp-item' + (on.has(n.key) ? ' is-on' : '') + '"><input type="checkbox" data-rp="' + esc(n.key) + '"'
                        + (on.has(n.key) ? ' checked' : '') + '> ' + esc(n.label) + '</label>').join('')
                        + (hits.length ? '' : '<div class="cyc-rp-empty">Topilmadi</div>');
                };
                const set = keys => { cycleRowFilters = keys; cycleRowFiltersApply(); draw(); };
                draw();
                q.addEventListener('input', draw);
                q.addEventListener('keydown', ev => {
                    if (ev.key === 'Enter') {   // birinchi topilganini belgilash / olib tashlash
                        const first = hitsNow()[0];
                        if (first) set(cycleRowFilters.includes(first.key) ? cycleRowFilters.filter(k => k !== first.key) : cycleRowFilters.concat([first.key]));
                    }
                    if (ev.key === 'Escape') closeCycRowPop();
                });
                list.addEventListener('change', ev => {
                    const b = ev.target.closest ? ev.target.closest('input[data-rp]') : null;
                    if (!b) return;
                    const k = b.dataset.rp;
                    set(b.checked ? [...new Set(cycleRowFilters.concat([k]))] : cycleRowFilters.filter(x => x !== k));
                });
                // "Hammasi" — topilganlarning hammasi (qidiruv bo'sh bo'lsa — barcha qatorlar), "Tozalash" — tanlov yo'q (hammasi ko'rinadi).
                pop.querySelector('[data-rp-all]').addEventListener('click', () => set([...new Set(cycleRowFilters.concat(hitsNow().map(n => n.key)))]));
                pop.querySelector('[data-rp-clear]').addEventListener('click', () => set([]));
                setTimeout(() => q.focus(), 0);
            }
            document.addEventListener('click', ev => {
                const btn = ev.target.closest && ev.target.closest('#cycRowFilterBtn');
                if (btn) { ev.preventDefault(); if (document.getElementById('cycRowPop')) closeCycRowPop(); else openCycRowPop(btn); return; }
                const clr = ev.target.closest && ev.target.closest('#cycRowFilterClear');
                if (clr) {
                    ev.preventDefault(); cycleRowFilters = []; closeCycRowPop();
                    cycleRowFiltersApply();
                    return;
                }
                if (!(ev.target.closest && ev.target.closest('#cycRowPop'))) closeCycRowPop();
            });
            // Server ichki jadvalni guruhcha qatorlarida qaytaradi (view: group) — API so'rovlari shu bilan.
            function cycleEffView() { return (cyclePlanData && cyclePlanData.view) || cycleViewMode; }   // 'flow' — oqim bo'yicha, 'group' — har subguruh alohida qator
            // Sikl jadvali qatlami: null — rol bo'yicha server tanlaydi
            // (o'quv bo'limi — tashqi, kafedra/o'qituvchi — ichki), keyin tugma bilan almashtiriladi.
            let cycleLayer = null;
            function cycleLayerParams() { return cycleLayer ? { layer: cycleLayer } : {}; }
            function renderCycleLayerUi(j) {
                if (j && j.layer) cycleLayer = j.layer;
                [['cycLayerExternal', 'external'], ['cycLayerInternal', 'internal']].forEach(([id, l]) => {
                    const b = $(id);
                    if (!b) return;
                    const on = cycleLayer === l;
                    b.className = 'px-2 py-1 ' + (on ? 'bg-blue-600 font-semibold text-white' : 'bg-white text-gray-500');
                });
                if ($('cycLayerRo')) $('cycLayerRo').classList.toggle('hidden', !(j && j.can_edit === false));
                if ($('cycleAutoShiftBtn')) $('cycleAutoShiftBtn').classList.toggle('hidden', !(j && j.layer === 'internal' && j.can_edit));
                // Ichki jadval doim guruhcha bo'yicha — Oqim/Guruh almashtirgichi kerak emas.
                const viewSwitch = $('cycViewFlow') ? $('cycViewFlow').parentElement : null;
                if (viewSwitch && j) viewSwitch.classList.toggle('hidden', Boolean(j.sub_rows));
            }
            let cyclePairsShown = null;   // ko'rinadigan para qatorlari (sukut: sikl kuni = 6 soat)
            let cycleBandsResize = null;  // kun chiziqlarini qayta chizuvchi resize ishlovchisi
            let cycleDayGeometry = [];    // kun ustunlari o'lchovi: [{left, width}]
            // Dam olish (yakshanba/bayram) ustunlarini yashirish — faqat ko'rinish.
            // Ichki (kafedra) jadvalda ham ishlaydi: blok ichidagi kun to'ri yashirilgan kunlarni o'tkazib yuboradi.
            let cycleHideOff = false;
            try { cycleHideOff = localStorage.getItem('lms:cycle-hide-off') === '1'; } catch (e) { }
            function cycleHidingOff() {
                return cycleHideOff;
            }
            function cycleColHidden(index) {
                const d = cyclePlanData && cyclePlanData.dates ? cyclePlanData.dates[index] : null;
                return cycleHidingOff() && Boolean(d && d.off);
            }
            // [from, from+span) oralig'idagi ko'rinadigan kalendar indekslari.
            function cycleVisibleIdx(from, span) {
                const out = [];
                for (let i = from; i < from + span; i++) if (!cycleColHidden(i)) out.push(i);
                if (!out.length) for (let i = from; i < from + span; i++) out.push(i);
                return out;
            }
            let cycleDragKey = null;
            let cycleHolidays = [];   // bayram kunlari (Y-m-d)
            // Bayram chiplarini chizadi (× bilan olib tashlash mumkin)
            function renderHolChips() {
                $('cycleHolBar').classList.toggle('hidden', !cycleHolidays.length);
                $('cycleHolList').innerHTML = cycleHolidays.map(d =>
                    '<span class="inline-flex items-center gap-1 bg-white border border-amber-300 rounded px-1.5 py-0.5 text-[10px] text-amber-800">' +
                    esc(d.split('-').reverse().join('.')) +
                    '<button type="button" class="cyc-hol-x text-amber-500 hover:text-red-600 font-bold" data-d="' + esc(d) + '">×</button></span>').join('');
            }
            async function loadCyclePlan(options = {}) {
                if (!board) return;
                loadCycleOverlapUi();
                const body = scopeBody();
               if ($('cycleStart').value) body.start_date = $('cycleStart').value;
                body.holidays = cycleHolidays;
                if (options.clear) body.clear = 1;
                body.view = cycleViewMode;
                Object.assign(body, cycleLayerParams());
                if (scopeMode === 'mine') { body.mine = 1; delete body.clear; }
                else if (scopeMode === 'kafedra') { body.kafedra = 1; delete body.clear; }
                else if (scopeMode === 'subjects') { body.subjects = 1; delete body.clear; }
                $('cycleMsg').classList.remove('text-red-700', 'text-emerald-700', 'text-amber-700', 'font-semibold');
                $('cycleMsg').classList.add('text-gray-500');
                $('cycleMsg').removeAttribute('title');
                $('cycleMsg').textContent = 'Yuklanmoqda...';
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/cycle-plan', 'POST', body);
                    // Qayta chizishda jadval joyidan siljimasin (o'zgartirilgan joy ko'z oldida qolsin).
                    const gw = $('cycleGridWrap');
                    const keep = gw ? { top: gw.scrollTop, left: gw.scrollLeft, page: window.scrollY } : null;
                    // "Ko'rsatish": shu chizishda to'qnashuvga birinchi scroll qilinsa — eski joy tiklanmaydi (scroll bekor bo'lmasin).
                    const focusScroll = !!(ttFocus && !ttFocus.scrolled);
                    const wkScrolledBefore = cycleWkScrolled;
                    cyclePlanData = j;
                    invalidateCycleWeek();   // sikl joylashuvi / o'qituvchi / xona o'zgargan bo'lishi mumkin — kesimlar qayta so'raydi
                    try { buildSubjectColors(colorScopeCards()); } catch (e) { }
                    renderCycleLayerUi(j);
                    if (j.start_date && !$('cycleStart').value) $('cycleStart').value = j.start_date;
                    cycleHolidays = j.holidays || [];   // server — yagona manba (saqlangandan keyin)
                    renderHolChips();
                    renderCyclePlan(j);
                    renderCycleCards(j);
                    if (typeof cycMultiPaint === 'function') cycMultiPaint();   // kunlar tanlovi qayta chizilgan jadvalda ham
                    if (typeof renderStats === 'function') renderStats();
                    if (keep && !options.resetScroll && !(focusScroll && ttFocus && ttFocus.scrolled)) {
                        // Shu chizishda tanlangan haftaga scroll qilingan bo'lsa (birinchi yuklash / boshqa hafta) — gorizontal joy tiklanmaydi.
                        const wkMoved = cycleWkScrolled !== wkScrolledBefore && !!cycleWkScrolled;
                        const restore = () => { gw.scrollTop = keep.top; if (!wkMoved) gw.scrollLeft = keep.left; window.scrollTo(window.scrollX, keep.page); };
                        restore(); requestAnimationFrame(restore);
                    }
                    $('cycleMsg').textContent = (j.rows ? j.rows.length : 0) + ((j.view || cycleViewMode) === 'group' ? ' guruh · ' : ' oqim · ') + (j.subjects ? j.subjects.length : 0) + ' sikl fani' +
                        (j.total_days ? (' · ' + j.total_days + ' o\'quv kuni') : '') +

                        (cycleHolidays.length ? (' · ' + cycleHolidays.length + ' bayram') : '');
                } catch (e) {
                    $('cycleMsg').textContent = '';
                    $('cycleGrid').innerHTML = '<tbody><tr><td class="p-3 text-sm text-red-600">Xatolik: ' + esc(e.message) + '</td></tr></tbody>';
                    throw e;
                }
            }
            function cycleMemberParts(name) {
                const clean = String(name || '')
                    .replace(/\s*\((?:rus|ru|рус|russ|ing|eng|engl|ang|angl|англ|o['’‘]?z|oz|uz|ўз|узб)[^)]*\)\s*$/iu, '')
                    .trim();
                const match = clean.match(/^(.*?\d)\s*([a-eа-е])$/iu);
                if (!match) return {base: clean, letter: ''};
                const cyrillic = {а: 'a', б: 'b', в: 'c', г: 'd', д: 'e'};
                const letter = match[2].toLowerCase();
                return {base: match[1].trim(), letter: cyrillic[letter] || letter};
            }

            // Oqim to'liq nomi "Fakultet / 1-oqim / ru" ko'rinishida saqlanadi.
            // Tor ustunlarda faqat oqim (va til) bo'lagi ko'rsatiladi.
            // Bo'lakli fan qatori yorlig'i: "(a) bo'lak" belgisi + oqim, fan nomi va
            // bo'lak qaysi guruhchalardan yig'ilgani (pastda, alohida yorliqlar).
            // Guruhcha qatnashadigan bo'lak qatorlari: a'zolari orasida shu guruhcha bor.
            function cycleVariantRowsOf(allRows, row) {
                if (row.variant) return [];
                const key = v => String(v || '').trim().toLowerCase();
                // Bir xil nomli guruhcha boshqa fakultet/yo'nalish/kursda ham bo'lishi mumkin (row_key kabi).
                const sameCurriculum = v => key(v.specialty) === key(row.specialty) && +v.course === +row.course
                    && key(v.faculty) === key(row.faculty);
                return allRows.filter(v => v.variant && sameCurriculum(v) && (v.subgroups || []).some(m => key(m) === key(row.group)));
            }
            // Filtr qo'llangan qatorlar — ekran ham, Excel ham shundan oladi.
            function cycleVisibleRows(allRows) {
                if (!cycleRowFilters.length) return allRows;
                const on = new Set(cycleRowFilters), seen = new Set();
                // Tanlangan qatorlar (jadval tartibida) va ularning bo'lak qatorlari — har biri bir marta.
                return allRows.filter(r => on.has(r.row_key)).flatMap(r => [r, ...cycleVariantRowsOf(allRows, r)])
                    .filter(r => !seen.has(r.row_key) && seen.add(r.row_key));
            }
            function cycleVariantLabelHtml(row) {
                const letter = (/\((\p{L})\)\s*$/u.exec(row.variant || '') || [])[1] || '?';
                const subject = String(row.variant || '').replace(/\s*\(\p{L}\)\s*$/u, '');
                const members = (row.subgroups || []).map(s => String(s).replace(/\s*\(.*\)$/, ''));
                return '<div class="cyc-vrow" title="' + esc(row.variant + '\n' + (row.flow || '') + '\nGuruhchalar: ' + members.join(', ')) + '">'
                    + '<div class="cyc-vrow-head"><span class="cyc-vrow-tag">' + esc(letter) + '</span>'
                    + '<span class="cyc-vrow-kind">bo\'lak</span><span class="cyc-vrow-flow">' + esc(cycleFlowShort(row.flow || '')) + '</span></div>'
                    + '<div class="cyc-vrow-subj">' + esc(subject) + '</div>'
                    + '<div class="cyc-vrow-members">' + members.map(m => '<span>' + esc(m) + '</span>').join('') + '</div>'
                    + cycleVariantStudentsHtml(row, members)
                    + '</div>';
            }
            // Bo'lakka HEMIS'da biriktirilgan talabalar: guruh bo'yicha soni va ro'yxat.
            function cycleVariantStudentsHtml(row, members) {
                const list = Array.isArray(row.students) ? row.students : null;
                if (!list) return '';
                if (!list.length) return '<div class="cyc-vrow-stu is-empty">HEMIS\'da talaba biriktirilmagan</div>';
                const tail = g => (/(\d+\p{L}*)\s*$/u.exec(String(g)) || [])[1] || String(g);
                // Tor ustunga sig'ishi uchun: "FAMILIYA I. O." (to'liq ism — tooltipda).
                const short = n => { const p = String(n || '').trim().split(/\s+/u);
                    return p.length < 2 ? p.join(' ') : p[0] + ' ' + p.slice(1, 3).map(x => x.charAt(0) + '.').join(' '); };
                const per = {};
                list.forEach(s => { per[s.group] = (per[s.group] || 0) + 1; });
                const multi = Object.keys(per).length > 1;
                return '<details class="cyc-vrow-stu" open><summary>' + list.length + ' talaba'
                    + (multi ? ' <i>(' + Object.entries(per).map(([g, n]) => esc(tail(g)) + ': ' + n).join(', ') + ')</i>' : '')
                    + '</summary><ol>' + list.map(s => '<li title="' + esc(s.name + ' — ' + s.group) + '">' + esc(short(s.name))
                        + (multi ? ' <b>' + esc(tail(s.group)) + '</b>' : '') + '</li>').join('') + '</ol></details>';
            }
            function cycleFlowShort(flow) {
                const name = String(flow || '').trim();
                const parts = name.split(' / ');
                const tail = parts.slice(-2).filter(part => /-oqim$/i.test(part) || part.length <= 3);
                return tail.join(' / ') || name;
            }

            // Chap ustun: bitta qator = bitta OQIM. Sarlavhada oqim nomi, ostida
            // shu oqim tarkibidagi guruhlar (guruhcha harflari bilan).
            // Faol talabalar soni nishoni (FISH emas — faqat son).
            function cycleStuCountHtml(n, title) {
                return '<em class="cyc-stu-count" title="' + esc(title || (n + ' ta faol talaba')) + '">' + n + '</em>';
            }
            function cycleMembersHtml(flow, members, counts) {
                const grouped = new Map(), perBase = new Map();
                (members || []).flatMap(name => String(name).split(/\s+\+\s+/u)).forEach(name => {
                    const part = cycleMemberParts(name);
                    const base = part.base || flow;
                    if (!grouped.has(base)) grouped.set(base, new Set());
                    if (part.letter) grouped.get(base).add(part.letter);
                    if (counts && counts[name] != null) perBase.set(base, (perBase.get(base) || 0) + (+counts[name] || 0));
                });
                const total = Array.from(perBase.values()).reduce((a, b) => a + b, 0);

                // Oqim nomi guruh nomining o'zi bo'lsa (label'siz eski kartalar),
                // sarlavha takrorlanmasin — faqat guruh qatorlari ko'rsatiladi.
                //
                // Ustunga faqat oqim bo'lagi sig'adi, to'liq nomi tooltipda.
                const flowName = String(flow || '').trim();
                const isFlowLabel = flowName !== '' && !grouped.has(flowName);
                const shortName = cycleFlowShort(flowName);
                const head = isFlowLabel
                    ? '<div class="cyc-flow-head" title="' + esc(flowName) + '">' +
                      '<span>' + esc(shortName) + '</span>' +
                      '<i>' + grouped.size + ' guruh' + (counts ? ' · ' + total + ' talaba' : '') + '</i></div>'
                    : '';

                if (!grouped.size) grouped.set(flowName, new Set());

                return '<div class="cyc-members">' + head +
                    Array.from(grouped.entries()).map(([base, letters]) => {
                        const suffixes = Array.from(letters).sort().join(',');
                        return '<div class="cyc-member-row"><span>' + esc(base)
                            + (perBase.has(base) ? ' ' + cycleStuCountHtml(perBase.get(base)) : '') + '</span>' +
                            '<b>' + esc(suffixes || '—') + '</b></div>';
                    }).join('') + '</div>';
            }
            function renderCyclePlanLegacy(j) {
                const dates = j.dates || [], rows = j.rows || [];
                if (!rows.length) {
                    $('cycleGrid').innerHTML = '<tbody><tr><td class="p-4 text-sm text-gray-400">Sikl rejimidagi fan yoki oqim topilmadi. Fan sozlamasida 4-6 kurs fanlarini <b>Sikl</b> qilib, sikl uzunligini (kun) kiriting, so\'ng shu yerni Yangilang.</td></tr></tbody>';
                    return;
                }
                let h = '<thead><tr><th class="cyc-gcol">Oqim</th>';
                dates.forEach(d => h += '<th class="cyc-dcol' + ((d.sunday || d.holiday) ? ' cyc-off' : '') + '" title="' + (d.sunday ? 'Yakshanba' : (d.holiday ? 'Bayram kuni' : '')) + '">' + esc(d.d) + '</th>');
                h += '</tr></thead><tbody>';
                rows.forEach(r => {
                    h += '<tr><td class="cyc-gcol">' + cycleMembersHtml(r.group, r.subgroups) + '</td>';
                    let col = 0;
                    (r.blocks || []).forEach(b => {
                        while (col < b.from) { h += '<td class="cyc-cell' + (dates[col] && (dates[col].sunday || dates[col].holiday) ? ' cyc-off' : '') + '"></td>'; col++; }
                        const c = subjColor(b.subject);
                        h += '<td class="cyc-cell cyc-block" colspan="' + (b.to - b.from + 1) + '" style="background:' + c.bg + ';border-color:' + c.border + ';" title="' + esc(b.subject) + ' — ' + b.days + ' kun">' +
                            '<span class="cyc-lbl"><b class="cyc-subj">' + esc(b.subject) + '</b> <span class="cyc-days">(' + b.days + ')</span></span></td>';
                        col = b.to + 1;
                    });
                    while (col < dates.length) { h += '<td class="cyc-cell' + (dates[col] && (dates[col].sunday || dates[col].holiday) ? ' cyc-off' : '') + '"></td>'; col++; }
                    h += '</tr>';
                });
                h += '</tbody>';
                $('cycleGrid').innerHTML = h;
                paintCycleDayBands(dates);
                // Oyna o'lchami o'zgarsa ustun eni ham o'zgaradi — qayta chizamiz.
                if (cycleBandsResize) window.removeEventListener('resize', cycleBandsResize);
                cycleBandsResize = () => paintCycleDayBands(dates);
                window.addEventListener('resize', cycleBandsResize);
                // Skrollda ham qayta o'lchanadi — overlay jadval bilan birga yuradi.
                const wrapEl = $('cycleGridWrap');
                if (wrapEl && !wrapEl.dataset.bandScroll) {
                    wrapEl.dataset.bandScroll = '1';
                    wrapEl.addEventListener('scroll', () => {
                        if (cyclePlanData) paintCycleDayBands(cyclePlanData.dates || []);
                    }, { passive: true });
                }
            }
            // Sikl panjarasi interaktiv ko'rinishda chiziladi: bo'sh katakka fan
            // kartasini sudrash uning start indeksini saqlaydi.
            function showCyclePlacementResult(card, index, message, type = 'error') {
                const msg = $('cycleMsg');
                const dateRow = cyclePlanData && cyclePlanData.dates && cyclePlanData.dates[index];
                const date = dateRow ? (dateRow.iso || dateRow.d || '') : '';
                const subject = card && card.subject ? card.subject : 'Fan kartasi';
                const prefix = type === 'success' ? 'Joylandi'
                    : (type === 'pending' ? 'Tasdiqlashga yuborildi' : 'Joylanmadi');
                const details = [subject, date].filter(Boolean).join(' · ');
                const text = prefix + (details ? ': ' + details : '') + (message ? ' — ' + message : '');

                msg.textContent = text;
                msg.classList.remove('text-gray-500', 'text-red-700', 'text-emerald-700', 'text-amber-700', 'font-semibold');
                msg.classList.add(type === 'success' ? 'text-emerald-700'
                    : (type === 'pending' ? 'text-amber-700' : 'text-red-700'), 'font-semibold');
                msg.setAttribute('title', text);

                if (type === 'error' && typeof ttToast === 'function') {
                    ttToast('<b>Sikl kartasi joylanmadi</b><div>' + esc(text) + '</div>', 'error');
                }
            }
            // Karta shu qatorga tushadimi: o'z qatori; alohida ma'ruza kartasi — oqimning istalgan guruhcha qatori (row_keys).
            function cycCardRowOk(card, rowKey) {
                return Boolean(card) && (card.row_keys || [card.row_key]).includes(rowKey);
            }
            async function placeCycleCardAt(card, index, pair) {
                if (!card) {
                    showCyclePlacementResult(null, index, 'Karta ma\u2019lumoti topilmadi. Sahifani yangilab qayta urinib ko\u2018ring.');
                    return;
                }
                try {
                    const result = await api(BASE + '/boards/' + board.id + '/cycle-place', 'POST', {
                        ...cycleOverlapParams(), ...cycleLayerParams(),
                        action: 'place', specialty_name: card.specialty, course: card.course,
                        group_name: card.group, subject_name: card.subject, start_index: index,
                        training_type: card.type || 'practice', pair: pair || 1, view: card.view || cycleEffView(), placement_group: (card && card.placement_group) || undefined,
                        start_date: $('cycleStart').value, holidays: cycleHolidays,
                    });
                    await loadCyclePlan();
                    // Ogohlantirish (xato emas): alohida ma'ruza kunlariga boshqa fan amaliyoti tushdi — api() uni toast qiladi; holat qatorida ham.
                    const warns = (result && result.warnings) || [];
                    const reloaded = ((cyclePlanData && cyclePlanData.cycle_cards) || [])
                        .find(item => item.key === card.key);
                    if (result && result.pending_approval) {
                        showCyclePlacementResult(card, index, '', 'pending');
                    } else if (!reloaded || !reloaded.placed) {
                        showCyclePlacementResult(card, index,
                            'Server yozuvni qabul qildi, lekin qayta yuklanganda blok topilmadi. Fan/oqim nomlari mosligini tekshiring.');
                    } else {
                        showCyclePlacementResult(card, index, warns.length ? '⚠ ' + warns.join('; ') : '', 'success');
                    }
                } catch (e) {
                    console.error('Sikl joylash xatosi: ' + (e && e.message ? e.message : 'Noma\u2019lum xato'), {karta: card, index: index});
                    showCyclePlacementResult(card, index, e && e.message ? e.message : 'Noma\u2019lum xato.');
                }
            }
            // Tanlangan karta qaysi oqim qatoriga tushishi mumkinligini ko'rsatadi:
            // o'sha qatorning bo'sh kataklari ajratiladi, qolganlari so'niq bo'ladi.
            function highlightCycleRow(cardKey) {
                const card = cardKey
                    ? ((cyclePlanData && cyclePlanData.cycle_cards) || []).find(item => item.key === cardKey)
                    : null;
                $('cycleGrid').querySelectorAll('[data-cycle-row]').forEach(cell => {
                    cell.classList.remove('cycle-row-target', 'cycle-row-muted', 'cyc-pick-row');
                    if (!card) return;
                    const ok = cycCardRowOk(card, cell.dataset.cycleRow);
                    cell.classList.add(ok ? 'cycle-row-target' : 'cycle-row-muted');
                    // "Joylash uchun tanlash" (tanlangan karta) — guruh qatori qalin ikki chiziq bilan, tanlov bekor bo'lguncha.
                    if (ok && cycleDragKey === cardKey) cell.classList.add('cyc-pick-row');
                });
            }
            // Kun chiziqlari va dam olish ustunlari jadval fonida chiziladi:
            // sarlavha kataklaridan haqiqiy o'lchov olinadi, shuning uchun
            // ustun eni o'zgarsa ham chiziq joyida qoladi.
            function paintCycleDayBands(dates) {
                const grid = $('cycleGrid');
                const wrap = $('cycleGridWrap');
                const overlay = $('cycleOverlay');
                const body = grid.querySelector('tbody');
                if (!overlay || !body) return;

                overlay.innerHTML = '';
                cycleDayGeometry = [];

                const heads = grid.querySelectorAll('thead .cyc-dcol');
                if (!heads.length) return;

                // Overlay jadval bilan bir tekislikda: offsetTop/offsetLeft
                // wrap ichidagi haqiqiy joyni beradi va skrollga bog'liq emas,
                // shuning uchun qo'shimcha tuzatish talab qilmaydi.
                const wrapRect = wrap.getBoundingClientRect();
                const bodyRect = body.getBoundingClientRect();
                const offsetX = wrap.scrollLeft - wrapRect.left;

                overlay.style.top = (body.offsetTop) + 'px';
                overlay.style.left = '0px';
                overlay.style.width = grid.offsetWidth + 'px';
                overlay.style.height = bodyRect.height + 'px';

                const frag = document.createDocumentFragment();

                heads.forEach((head, index) => {
                    const rect = head.getBoundingClientRect();
                    const left = Math.round(rect.left + offsetX);
                    const width = Math.round(rect.right + offsetX) - left;
                    cycleDayGeometry[index] = { left: left, width: width };
                });

                // Dam olish kunlari — uzluksiz bo'laklar bo'lib chiziladi.
                let start = null;
                const flush = (endIndex) => {
                    if (start === null) return;
                    const from = cycleDayGeometry[start.index];
                    const to = cycleDayGeometry[endIndex];
                    if (from && to) {
                        const band = document.createElement('div');
                        band.className = 'cyc-off-band ' + (start.holiday ? 'is-holiday' : 'is-sunday');
                        band.style.left = from.left + 'px';
                        band.style.width = (to.left + to.width - from.left) + 'px';
                        frag.appendChild(band);
                    }
                    start = null;
                };

                dates.forEach((d, index) => {
                    const holiday = Boolean(d.holiday);
                    const off = holiday || Boolean(d.sunday);
                    if (!off) { flush(index - 1); return; }
                    if (start && start.holiday !== holiday) flush(index - 1);
                    if (!start) start = { index: index, holiday: holiday };
                });
                flush(dates.length - 1);

                overlay.appendChild(frag);
            }

            // Sudrash paytida aniq bitta kun ustunini belgilaydi; joylab
            // bo'lmaydigan kun qizil bo'ladi. Nishon katak ichiga qo'yiladi,
            // shuning uchun skroll va jadval siljishi ta'sir qilmaydi.
            function markCycleDrop(cell, dayIndex, allowed) {
                clearCycleDropMark();
                if (!cell) return;

                const from = +cell.dataset.cycleFrom || 0;
                const span = Math.max(1, +cell.dataset.cycleSpan || 1);
                const visible = cycleVisibleIdx(from, span);
                let offset = visible.indexOf(dayIndex);
                if (offset < 0) offset = Math.max(0, visible.findIndex(i => i > dayIndex));
                const colWidth = cell.offsetWidth / visible.length;

                const mark = document.createElement('div');
                mark.className = 'cyc-drop-mark' + (allowed ? '' : ' is-bad');
                mark.style.left = (offset * colWidth) + 'px';
                mark.style.width = colWidth + 'px';
                cell.appendChild(mark);
            }

            function clearCycleDropMark() {
                const grid = $('cycleGrid');
                if (grid) grid.querySelectorAll('.cyc-drop-mark').forEach(el => el.remove());
            }

            function cycleDateClass(date) {
                if (!date) return '';
                if (date.holiday) return ' cyc-off cyc-holiday';
                return date.sunday ? ' cyc-off cyc-weekend' : '';
            }
            // ── Sikl blokiga o'qituvchi / vaqt / xona biriktirish ──
            let cycAssignCard = null;
            let cycAssignBusy = { text: {}, items: {} };   // band o'qituvchilar: id => matn va "Ko'rsatish" ma'lumoti
            // Band o'qituvchi tanlansa — kim bilan, qachon va "Ko'rsatish" (saqlashdagi "Baribir biriktirish" ogohlantirishi alohida).
            function cycAssignBusyNote() {
                const id = $('cycAssignTeacher').value, busy = id ? cycAssignBusy.text[id] : null, el = $('cycAssignWarn');
                if (!busy) { el.classList.add('hidden'); el.innerHTML = ''; return; }
                el.innerHTML = '<div style="color:#b45309">⚠ Band: ' + esc(busy) + focusLinksHtml(cycAssignBusy.items[id]) + agendaLinksHtml(cycAssignBusy.items[id], null) + '</div>';
                el.classList.remove('hidden');
            }
            $('cycAssignTeacher').onchange = cycAssignBusyNote;

            async function openCycleAssign(key) {
                const card = (cyclePlanData.cycle_cards || []).find(item => item.key === key);
                if (!card || !card.placed) return;
                cycAssignCard = card;

                $('cycAssignTitle').textContent = card.subject
                    + ((cyclePlanData && cyclePlanData.simple) ? '' : (card.type === 'lecture' ? " — Ma'ruza" : ' — Amaliy'));
                $('cycAssignMeta').textContent = card.group + ' · ' + card.days + ' kun';
                $('cycAssignKafedra').textContent = "O'qituvchi";
                $('cycAssignTeacher').innerHTML = '<option value="">Yuklanmoqda...</option>';
                $('cycAssignRoom').innerHTML = '<option value="">Yuklanmoqda...</option>';
                $('cycAssignWarn').classList.add('hidden');
                cycAssignBusy = { text: {}, items: {} };
                $('cycAssignModal').classList.add('open');

                try {
                    const j = await api(BASE + '/boards/' + board.id + '/cycle-assign-options', 'POST', {
                        specialty_name: card.specialty, course: card.course,
                        group_name: card.group, subject_name: card.subject,
                        training_type: card.type || 'practice', view: cycleEffView(), placement_group: (card && card.placement_group) || undefined,
                        start_date: $('cycleStart').value, holidays: cycleHolidays, ...cycleLayerParams(),
                    });

                    $('cycAssignKafedra').textContent = "O'qituvchi" + (j.kafedra ? ' (' + j.kafedra + ')' : '');
                    // Blok sanalarida boshqa guruhcha bilan band o'qituvchilar — kulrang, sababi title'da.
                    const busyT = j.busy_teachers || {};
                    cycAssignBusy = { text: busyT, items: (j.busy_items && j.busy_items.teachers) || {} };
                    $('cycAssignTeacher').innerHTML = '<option value="">— Tanlanmagan —</option>' +
                        (j.teachers || []).map(t => '<option value="' + t.id + '"' + (busyT[t.id] ? ' style="color:#9ca3af" title="Band: ' + esc(busyT[t.id]) + '"' : '') + '>' +
                            esc(t.name) + (busyT[t.id] ? ' — band' : '') + '</option>').join('');
                    $('cycAssignRoom').innerHTML = '<option value="">— Tanlanmagan —</option>' +
                        (j.rooms || []).map(r => '<option value="' + esc(r.code) + '">' + esc(r.name) + (r.volume ? ' (' + r.volume + ' o\u2018rin)' : ' (sig\u2018imi kiritilmagan)')
                            + (r.why ? ' — ' + esc(r.why) : '') + '</option>').join('');   // server tartibi: yaqinlik bo'yicha

                    // "A + B" kabi umumiy karta: o'qituvchi/xona boshqa guruhchalarga ham tegadi.
                    if (j.shared_with && j.shared_with.length) {
                        $('cycAssignMeta').textContent = card.group + ' · ' + card.days + ' kun · umumiy karta: '
                            + j.shared_with.join(', ') + ' bilan birga (o‘zgarish ularga ham tegadi)';
                    }
                    const current = j.current || {};
                    if (current.teacher_id) $('cycAssignTeacher').value = String(current.teacher_id);
                    // Hozirgi xona nofaol — "(nofaol)" belgisi bilan ko'rinadi, tanlab (saqlab) bo'lmaydi; ogohlantirish.
                    if (current.auditorium_code && current.auditorium_active === false) {
                        $('cycAssignRoom').insertAdjacentHTML('afterbegin', '<option value="' + esc(current.auditorium_code) + '" disabled data-room-off="1" style="color:#b91c1c">'
                            + esc(current.auditorium_name || current.auditorium_code) + ' (nofaol)</option>');
                        $('cycAssignWarn').innerHTML = '<span style="color:#b91c1c">⚠ ' + esc(ROOM_OFF_TEXT) + ' («' + esc(current.auditorium_name || current.auditorium_code) + '»)</span>';
                        $('cycAssignWarn').classList.remove('hidden');
                    }
                    if (current.auditorium_code) $('cycAssignRoom').value = current.auditorium_code;
                    // Guruhcha smenasi (ichki jadval): butun blok shu paradan — masalan, IV para (13:30).
                    const shiftOpts = j.shift_options || [];
                    $('cycAssignShiftBox').classList.toggle('hidden', !shiftOpts.length);
                    $('cycAssignShift').innerHTML = '<option value="0">Oqimdagidek</option>' +
                        shiftOpts.map(o => '<option value="' + (+o.start) + '">' + esc(o.label) + '</option>').join('');
                    $('cycAssignShift').value = String(+j.shift_start || 0);
                    if ($('cycAssignShift').value !== String(+j.shift_start || 0)) $('cycAssignShift').value = '0';
                } catch (e) {
                    $('cycAssignModal').classList.remove('open');
                    alert('Ma\u2019lumotlarni yuklab bo\u2018lmadi: ' + e.message);
                }
            }

            function closeCycleAssign() {
                $('cycAssignModal').classList.remove('open');
                cycAssignCard = null;
            }

            // Tozalash: o'qituvchi va xona olib tashlanadi.
            $('cycAssignReset').addEventListener('click', async () => {
                if (!cycAssignCard) return;
                if (!confirm("Biriktirilgan o'qituvchi va xona olib tashlansinmi?")) return;
                const button = $('cycAssignReset');
                button.disabled = true;
                try {
                    await api(BASE + '/boards/' + board.id + '/cycle-assign', 'POST', {
                        specialty_name: cycAssignCard.specialty, course: cycAssignCard.course,
                        group_name: cycAssignCard.group, subject_name: cycAssignCard.subject,
                        training_type: cycAssignCard.type || 'practice', view: cycleEffView(), placement_group: (cycAssignCard && cycAssignCard.placement_group) || undefined,
                        teacher_id: null, lesson_time: null, auditorium_code: null,
                        start_date: $('cycleStart').value, holidays: cycleHolidays,
                    });
                    closeCycleAssign();
                    await loadCyclePlan();
                } catch (e) {
                    alert('Tozalab bo\u2018lmadi: ' + e.message);
                } finally {
                    button.disabled = false;
                }
            });

            $('cycAssignClose').addEventListener('click', closeCycleAssign);
            $('cycAssignModal').addEventListener('click', ev => {
                if (ev.target === $('cycAssignModal')) closeCycleAssign();
            });

            async function saveCycleAssign(force) {
                if (!cycAssignCard) return;
                const roomOpt = $('cycAssignRoom').selectedOptions && $('cycAssignRoom').selectedOptions[0];
                if (roomOpt && roomOpt.dataset && roomOpt.dataset.roomOff) {
                    $('cycAssignWarn').innerHTML = '<span style="color:#b91c1c">⚠ Xona nofaol — boshqa xona tanlang</span>';
                    $('cycAssignWarn').classList.remove('hidden');
                    return;
                }
                const button = $('cycAssignSave');
                button.disabled = true;
                try {
                    const saved = await api(BASE + '/boards/' + board.id + '/cycle-assign', 'POST', {
                        specialty_name: cycAssignCard.specialty, course: cycAssignCard.course,
                        group_name: cycAssignCard.group, subject_name: cycAssignCard.subject,
                        training_type: cycAssignCard.type || 'practice', view: cycleEffView(), placement_group: (cycAssignCard && cycAssignCard.placement_group) || undefined,
                        teacher_id: $('cycAssignTeacher').value ? +$('cycAssignTeacher').value : null,
                        auditorium_code: $('cycAssignRoom').value || null,
                        shift_start: $('cycAssignShiftBox').classList.contains('hidden') ? undefined : +$('cycAssignShift').value,
                        start_date: $('cycleStart').value, holidays: cycleHolidays, force: force ? 1 : undefined, ...cycleLayerParams(),
                    });
                    // O'qituvchi/xona shu vaqtda band edi — guruhcha boshqa smenaga o'tkazildi (to'qnashuv yo'q).
                    if (saved && saved.auto_shift) ttToast('<b>&#8634; Smena o\'zgartirildi</b><div>' + esc(saved.auto_shift.message) + '</div>', 'warn');
                    closeCycleAssign();
                    await loadCyclePlan();
                } catch (e) {
                    // O'qituvchi/xona blok sanalarida band — kim bilan, qachon; "Baribir biriktirish" bilan saqlanadi.
                    if (e.data && e.data.needs_confirm) showBusyConfirm($('cycAssignWarn'), e.message, () => saveCycleAssign(true), e.data.conflict_items);
                    else alert('Saqlab bo\u2018lmadi: ' + e.message);
                } finally {
                    button.disabled = false;
                }
            }
            $('cycAssignSave').addEventListener('click', () => saveCycleAssign(false));

            // "Smenalarni avtomatik ajratish" (ichki jadval): qamrovdagi sikl to'qnashuvlari guruhcha smenasini 8:30 ⇄ 13:30
            // almashtirib hal qilinadi; nima o'zgargani va hal bo'lmaganlari ro'yxat bilan.
            function cycleAutoShiftHtml(j) {
                const li = (x, extra) => '<li><b>' + esc(x.group) + '</b> · ' + esc(x.subject) + (extra ? ' — ' + esc(extra) : '') + '</li>';
                return '<div style="font-weight:600;margin-bottom:6px">' + esc(j.message || '') + '</div>' +
                    ((j.changed || []).length ? '<div style="color:#059669;font-weight:600">O\'zgartirildi:</div><ul id="cycAutoChanged" style="margin:2px 0 6px 16px;list-style:disc">' +
                        j.changed.map(x => li(x, x.message.split(': ').slice(1).join(': ') + ' (' + x.reason + ')')).join('') + '</ul>' : '') +
                    ((j.unresolved || []).length ? '<div style="color:#b91c1c;font-weight:600">Hal bo\'lmadi:</div><ul id="cycAutoUnresolved" style="margin:2px 0 0 16px;list-style:disc">' +
                        j.unresolved.map(x => li(x, x.why + ': ' + x.reason)).join('') + '</ul>' : '');
            }
            async function cycleAutoShift() {
                if (!board || !confirm('Qamrovdagi sikl to\'qnashuvlari guruhcha smenasini (8:30 ⇄ 13:30) almashtirib hal qilinsinmi?')) return;
                const btn = $('cycleAutoShiftBtn');
                btn.disabled = true;
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/cycle-auto-shift', 'POST', Object.assign(scopeBody(), cycleLayerParams()));
                    if (j && !j.pending_approval) {
                        let box = document.getElementById('cycAutoShiftModal');
                        if (!box) {
                            box = document.createElement('div');
                            box.id = 'cycAutoShiftModal';
                            box.style.cssText = 'position:fixed;inset:0;z-index:70;background:rgba(15,23,42,.45);display:flex;align-items:center;justify-content:center;padding:16px';
                            box.addEventListener('click', ev => { if (ev.target === box || ev.target.id === 'cycAutoShiftClose') box.remove(); });
                            document.body.appendChild(box);
                        }
                        box.innerHTML = '<div style="background:#fff;border-radius:12px;width:min(760px,100%);max-height:85vh;overflow:auto;padding:14px 18px;font-size:12px">' +
                            '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><b>Smenalarni avtomatik ajratish</b>' +
                            '<button type="button" id="cycAutoShiftClose" style="font-size:20px;line-height:1">&times;</button></div>' + cycleAutoShiftHtml(j) + '</div>';
                    }
                    await loadCyclePlan();
                } catch (e) {
                    alert('Bajarilmadi: ' + e.message);
                } finally {
                    btn.disabled = false;
                }
            }
            if ($('cycleAutoShiftBtn')) $('cycleAutoShiftBtn').addEventListener('click', cycleAutoShift);

            // ── Fan nomining blok ichidagi joyi ──
            // Sukut: M/A darslar egallagan soatlar oralig'ining o'rtasi (gorizontal — blok
            // o'rtasi). Foydalanuvchi siljitgan joy shu brauzerda (doska + blok bo'yicha) saqlanadi.
            function cycTitleStoreKey() { return board ? 'lms:cyc-title-pos:' + board.id : ''; }
            function cycTitleStore() {
                try { return JSON.parse(localStorage.getItem(cycTitleStoreKey()) || '{}') || {}; } catch (e) { return {}; }
            }
            function cycTitleSave(key, pos) {
                try {
                    const all = cycTitleStore();
                    if (pos) all[key] = pos; else delete all[key];
                    localStorage.setItem(cycTitleStoreKey(), JSON.stringify(all));
                } catch (e) { }
            }
            function cycTitlePosStyle(block, plan, dayHours) {
                const saved = cycTitleStore()[block.key];
                if (saved && isFinite(saved[0]) && isFinite(saved[1])) {
                    return '--mk-x:' + (+saved[0]).toFixed(2) + '%;--mk-y:' + (+saved[1]).toFixed(2) + '%';
                }
                let lo = Infinity, hi = -Infinity;
                Object.values(plan || {}).forEach(dp => {
                    const n = (+dp.lec || 0) + (+dp.prc || 0);
                    if (n < 1) return;
                    const st = +dp.start || 1;
                    lo = Math.min(lo, st); hi = Math.max(hi, st + n - 1);
                });
                if (!isFinite(lo)) return '';
                const y = ((lo - 1) + hi) / 2 / Math.max(1, dayHours) * 100;
                return '--mk-y:' + y.toFixed(2) + '%';
            }
            // Yorliq markazini (blokka nisbatan, px) blok ichida ushlab, foizda qaytaradi:
            // yorliqning yarim kengligi/balandligi chegaradan chiqmasin.
            function cycTitleClampPct(cx, cy, or, ar) {
                const hw = or.width / 2 + 2, hh = or.height / 2 + 2;
                const x = Math.min(Math.max(cx, hw), Math.max(hw, ar.width - hw));
                const y = Math.min(Math.max(cy, hh), Math.max(hh, ar.height - hh));
                return [x / ar.width * 100, y / ar.height * 100];
            }
            // Avtomatik (chetki soat) yoki saqlangan joyda ikki qatorli uzun nom blokdan
            // chiqib, qo'shni qatorni yopmasin (.is-mark — overflow: visible). Avval hamma
            // o'lchov olinadi, keyin yoziladi — bitta layout.
            function clampCycTitles() {
                const items = [...document.querySelectorAll('#cycleGrid .cyc-mk-over')]
                    .map(over => ({ over, or: over.getBoundingClientRect(), ar: over.parentElement.getBoundingClientRect() }));
                items.forEach(({ over, or, ar }) => {
                    if (!ar.width || !ar.height) return;
                    const cx = or.left + or.width / 2 - ar.left, cy = or.top + or.height / 2 - ar.top;
                    const pos = cycTitleClampPct(cx, cy, or, ar);
                    if (Math.abs(pos[0] - cx / ar.width * 100) < 0.05 && Math.abs(pos[1] - cy / ar.height * 100) < 0.05) return;
                    over.style.setProperty('--mk-x', pos[0].toFixed(2) + '%');
                    over.style.setProperty('--mk-y', pos[1].toFixed(2) + '%');
                });
            }
            // Ushlab siljitish: sichqoncha 4px dan ko'p yursa — siljitish, aks holda oddiy bosish.
            let cycTitleDragged = false;
            function setupCycTitleDrag() {
                const grid = $('cycleGrid');
                if (!grid || grid.dataset.mkDragReady) return;
                grid.dataset.mkDragReady = '1';
                grid.addEventListener('pointerdown', ev => {
                    if (ev.button !== 0) return;
                    const title = ev.target.closest ? ev.target.closest('.cyc-mk-title[data-mk-subj]') : null;
                    if (!title) return;
                    const over = title.closest('.cyc-mk-over'), area = over && over.parentElement;
                    if (!area) return;
                    const sx = ev.clientX, sy = ev.clientY;
                    const ar = area.getBoundingClientRect(), or = over.getBoundingClientRect();
                    const cx0 = or.left + or.width / 2 - ar.left, cy0 = or.top + or.height / 2 - ar.top;
                    let moving = false, pos = null;
                    cycTitleDragged = false;
                    const move = e => {
                        const dx = e.clientX - sx, dy = e.clientY - sy;
                        if (!moving && Math.abs(dx) + Math.abs(dy) < 4) return;
                        if (!moving) { moving = true; over.classList.add('is-dragging'); try { title.setPointerCapture(ev.pointerId); } catch (_) { } }
                        e.preventDefault();
                        pos = cycTitleClampPct(cx0 + dx, cy0 + dy, or, ar);
                        over.style.setProperty('--mk-x', pos[0].toFixed(2) + '%');
                        over.style.setProperty('--mk-y', pos[1].toFixed(2) + '%');
                    };
                    const up = () => {
                        document.removeEventListener('pointermove', move);
                        document.removeEventListener('pointerup', up);
                        document.removeEventListener('pointercancel', up);
                        over.classList.remove('is-dragging');
                        if (moving) {
                            cycTitleDragged = true;   // keyingi "click" popoverni ochmasin
                            if (pos) cycTitleSave(title.dataset.mkSubj, [+pos[0].toFixed(2), +pos[1].toFixed(2)]);
                        }
                    };
                    document.addEventListener('pointermove', move);
                    document.addEventListener('pointerup', up);
                    document.addEventListener('pointercancel', up);
                });
                // Ikki marta bosish — avtomatik (darslar markazi) joyga qaytarish.
                grid.addEventListener('dblclick', ev => {
                    const title = ev.target.closest ? ev.target.closest('.cyc-mk-title[data-mk-subj]') : null;
                    if (!title) return;
                    ev.preventDefault();
                    cycTitleSave(title.dataset.mkSubj, null);
                    closeCycDayPop();
                    if (cyclePlanData) renderCyclePlan(cyclePlanData);
                });
            }

            let cfOwners = {}, cfBlocks = {};   // ma'ruza to'qnashuvi egasi bloki; blok kaliti => {key, subject, group, conflicts}
            function renderCyclePlan(j) {
                if (typeof closeCycDayPop === 'function') closeCycDayPop();
                const dates = j.dates || [], allRows = j.rows || [];
                cfOwners = cfLectureOwners(allRows);
                cfMergeLectureItems(allRows, cfOwners);
                cfBlocks = {};
                allRows.forEach(r => (r.blocks || []).forEach(b => { cfBlocks[b.key] = { key: b.key, subject: b.subject, group: r.group, conflicts: b.conflicts || [] }; }));
                // "Guruh" ustuni sarlavhasidan tanlangan guruhlar/oqimlar (bo'lmasa hammasi): shu qamrov tanlovi o'qiladi, jadvalda
                // yo'q qatorlar tanlovdan chiqadi.
                cycleRowFiltersLoad();
                if (ttFocus && ttFocus.show.view === 'cycle') {
                    // "Ko'rsatish": vaqtincha — to'qnashuvdagi guruhlar qatorlari (saqlanmaydi; Yopish oldingisini tiklaydi).
                    cycleRowFilters = focusCycleRowKeys(allRows);
                } else {
                    const keep = cycleRowFilters.filter(k => allRows.some(r => r.row_key === k));
                    if (keep.length !== cycleRowFilters.length) { cycleRowFilters = keep; cycleRowFiltersSave(); }
                }
                // Guruhcha tanlanganda u qatnashadigan bo'lak qatorlari (Fan (a)/(b)/(c)) ham ko'rinadi.
                const rows = cycleVisibleRows(allRows);
                if (!rows.length) {
                    // "Faqat meniki": jadvalda sikl bor, lekin shu o'qituvchiga biriktirilgani yo'q —
                    // sozlama haqidagi xabar chalg'itadi.
                    const emptyMsg = scopeMode === 'kafedra'
                        ? 'Tanlangan qamrovda kafedrangizga tegishli sikl fani yo\'q. Barcha darslarni ko\'rish uchun <b>Butun doska</b> ni tanlang.'
                        : scopeMode === 'subjects'
                        ? 'Tanlangan qamrovda siz mas\'ul bo\'lgan sikl fani yo\'q. Barcha darslarni ko\'rish uchun <b>Butun doska</b> ni tanlang.'
                        : mineOnly
                        ? 'Tanlangan qamrovda sizga biriktirilgan sikl darsi yo\'q. Barcha darslarni ko\'rish uchun <b>Butun doska</b> ni tanlang.'
                        : 'Sikl rejimidagi fan yoki oqim topilmadi. Avval fan sozlamasida <b>Sikl</b> rejimi va kun sonini kiriting.';
                    $('cycleGrid').innerHTML = '<tbody><tr><td class="p-4 text-sm text-gray-400">' + emptyMsg + '</td></tr></tbody>';
                    renderCycleCards(j);
                    return;
                }
                // Juftlik qatorlar qo'ng'iroq jadvalidan: nomi (0.5-para, 1-para...) va vaqti bilan.
                const bellPairs = boardSchedule().filter(it => it.type === 'pair');
                const totalPairs = bellPairs.length || Math.max(1, +j.pairs || 1);
                // Sukutda sikl kuniga yetarli qatorlar ko'rinadi (6 soat):
                // yarim-para jadvalida 6 qator, to'liq parada 3 qator. Qolganini
                // "+" tugmasi ochadi; band qatorlar hech qachon yashirilmaydi.
                const parseT = t => { const m = /^(\d{1,2}):(\d{2})$/.exec(t || ''); return m ? (+m[1]) * 60 + (+m[2]) : null; };
                const durs = bellPairs.map(it => { const a = parseT(it.start), b = parseT(it.end); return a != null && b != null && b > a ? b - a : null; }).filter(v => v != null);
                const rowMins = durs.length ? durs.reduce((x, y) => x + y, 0) / durs.length : 80;
                const basePairs = Math.ceil(6 / (rowMins >= 60 ? 2 : 1));
                let maxLaneUsed = 1;
                rows.forEach(row => (row.blocks || []).forEach(block => {
                    const bp = Math.max(1, +block.pair || 1);
                    const laneTo = Math.max(bp + Math.max(+block.span_head || 1, 1) - 1,
                        (+block.span_tail || 0) > 0 ? bp + (+block.tail_offset || 0) + (+block.span_tail) - 1 : bp);
                    if (laneTo > maxLaneUsed) maxLaneUsed = laneTo;
                }));
                // O'quv bo'limi ko'rinishi: ma'ruza/amaliy ajratilmaydi, para
                // qatorlari yo'q — bitta qator, faqat kunlar va qoidalar.
                const simple = Boolean(j.simple);
                const markMode = Boolean(j.mark_mode);
                const dayHours = Math.max(1, +j.day_hours || 6);
                if (cyclePairsShown == null) cyclePairsShown = basePairs;
                const pairs = simple ? 1 : Math.max(1, Math.min(totalPairs, Math.max(cyclePairsShown, maxLaneUsed)));
                if (!simple) cyclePairsShown = pairs;
                const showAddPair = !simple && pairs < totalPairs;
                let h = '<colgroup><col class="cyc-group-col">'
                    + (markMode ? '<col style="width:84px">' : '')
                    + (simple ? '' : '<col style="width:52px">');
                dates.forEach((d, i) => h += '<col class="cyc-date-col' + (cycleColHidden(i) ? ' cyc-col-hidden' : '') + '">');
                const rowWord = (j.view || cycleViewMode) === 'group' ? 'Guruh' : 'Oqim';
                h += '</colgroup><thead><tr><th class="cyc-gcol cyc-gfilter-th">'
                    + '<button type="button" id="cycRowFilterBtn" class="cyc-gfilter-btn' + (cycleRowFilters.length ? ' is-on' : '') + '" title="' + rowWord + 'larni tanlash yoki qidirish">'
                    + esc(cycleRowFilterText(allRows, rowWord)) + ' &#9662;</button>'
                    + (cycleRowFilters.length ? '<button type="button" id="cycRowFilterClear" class="cyc-gfilter-x" title="Hammasini ko\'rsatish">&times;</button>' : '')
                    + '</th>'
                    + (markMode ? '<th class="cyc-mk-side">Para</th>' : '')
                    + (simple ? '' : '<th class="cyc-pcol" title="Juftlik">Para</th>');
                dates.forEach((d, i) => h += '<th class="cyc-dcol' + cycleDateClass(d) + (cycleColHidden(i) ? ' cyc-col-hidden' : '') + '" title="' + (d.sunday ? 'Yakshanba' : (d.holiday ? 'Bayram kuni' : '')) + '">' + esc(d.d) + '</th>');
                h += '</tr></thead><tbody>';
                rows.forEach(row => {
                    // Guruhcha qatorida u qatnashadigan bo'lak bloklari "ishora" sifatida chiziladi:
                    // sikl bor, lekin dars bo'lak qatorida — bosilsa o'sha qator ochiladi.
                    const ghostBlocks = j.mark_mode ? cycleVariantRowsOf(allRows, row).flatMap(v => (v.blocks || [])
                        .filter(b => b.from != null && b.to != null)
                        .map(b => ({ ...b, ghost: true, ghost_row: v.row_key,
                            ghost_letter: (/\((\p{L})\)\s*$/u.exec(v.variant || '') || [])[1] || '' }))) : [];
                    // Bloklar yaxlit to'rtburchak katak bo'lib chiziladi (rowspan)
                    // — ichki chiziqlar yo'q: ma'ruza 1 para, amaliy butun sikl
                    // davomida kuniga 4 soat (2 para). Bo'sh kataklar colspan bilan
                    // birlashtiriladi: DOM kichik, drag & drop qotmaydi; aniq kun
                    // sichqoncha o'rnidan topiladi.
                    const cols = dates.length;
                    const cellAt = {};   // lane -> {boshCol: {html, next}}
                    const covered = {};  // lane -> rowspan/colspan qamrovi
                    for (let l = 1; l <= pairs; l++) { cellAt[l] = {}; covered[l] = new Uint8Array(cols); }
                    const mark = (lane0, lanes, from, to) => {
                        for (let l = lane0; l < lane0 + lanes && l <= pairs; l++)
                            for (let c = from; c <= to && c < cols; c++) covered[l][c] = 1;
                    };
                    const free = (lane0, lanes, from, to) => {
                        for (let l = lane0; l < lane0 + lanes && l <= pairs; l++)
                            for (let c = from; c <= to && c < cols; c++) if (covered[l][c]) return false;
                        return true;
                    };
                    [...(row.blocks || []), ...ghostBlocks].forEach(block => {
                        if (block.ghost) {
                            const gTo = Math.min(block.to, cols - 1);
                            if (block.from >= cols || gTo < block.from || !free(1, pairs, block.from, gTo)) return;
                            const gc = subjColor(String(block.subject).replace(/\s*\(\p{L}\)\s*$/u, ''));
                            const gSubj = String(block.subject).replace(/\s*\(\p{L}\)\s*$/u, '');
                            cellAt[1][block.from] = {
                                html: '<td class="cyc-cell cyc-ghost" rowspan="' + pairs + '" colspan="' + (gTo - block.from + 1) + '"'
                                    + ' style="--gc:' + gc.bg + ';--gb:' + gc.border + '"'
                                    + ' title="' + esc(block.subject) + ' — bu guruhcha \'' + esc(block.ghost_letter) + '\' bo\'lagida o\'qiydi. Bosing: bo\'lak qatorini ochish">'
                                    + '<button type="button" class="cyc-ghost-btn" data-ghost-row="' + esc(block.ghost_row) + '">'
                                    + '<span class="cyc-vrow-tag">' + esc(block.ghost_letter) + '</span>'
                                    + '<span class="cyc-ghost-txt"><b>' + esc(gSubj) + '</b><i>(' + esc(block.ghost_letter) + ') bo\'lakda · ' + block.days + ' kun &rarr;</i></span>'
                                    + '</button></td>',
                                next: gTo + 1,
                            };
                            mark(1, pairs, block.from, gTo);
                            return;
                        }
                        const p = Math.max(1, +block.pair || 1);
                        if (p > pairs || block.from >= cols) return;
                        const spanHead = Math.max(1, +block.span_head || 1);
                        const spanTail = +block.span_tail || 0;
                        const headDays = +block.head_days || 0;
                        const headTo = block.head_to != null ? +block.head_to : block.to;
                        const tailFrom = block.tail_from != null ? +block.tail_from : null;
                        // Amaliy dum bo'lagi ma'ruza bo'shatgan paradan boshlanadi (tail_offset < 0).
                        const tailOffset = +block.tail_offset || 0;
                        const rects = [];
                        if (block.type === 'practice' && spanTail > 0 && tailFrom != null && headDays > 0) {
                            // Bosh bo'lak ichki yakshanba/bayram ustunlarini ham qamrab,
                            // dum bo'lagigacha uzluksiz davom etadi.
                            rects.push({ lanes: spanHead, from: block.from, to: Math.min(tailFrom - 1, block.to), main: true });
                            rects.push({ lanes: spanTail, from: tailFrom, to: block.to, main: false, lane0: p + tailOffset });
                        } else if (block.type === 'practice' && spanTail > 0 && headDays < 1) {
                            rects.push({ lanes: spanTail, from: block.from, to: block.to, main: true, lane0: p + tailOffset });
                        } else {
                            rects.push({ lanes: spanHead, from: block.from, to: block.to, main: true });
                        }
                        const color = subjColor(block.subject);
                        const reqParts = [block.teacher_name, block.auditorium_name || block.auditorium_code]
                            .filter(Boolean);
                        const req = reqParts.join(' · ');
                        const reqHtml = reqParts.map(part => '<span class="cyc-req">' + esc(part) + '</span>').join('');
                        // Alohida ma'ruza bloki sodda ko'rinishda ham "M" belgisi bilan (amaliy blokidan ajralib tursin).
                        const sepLecBlock = block.type === 'lecture' && block.lecture_separate;
                        const typeChip = simple && !sepLecBlock
                            ? ''
                            : '<span class="cyc-type ' + block.type + '" title="' + (block.type === 'lecture' ? "Ma'ruza" + (sepLecBlock ? ' (alohida: ' + (block.lecture_list || []).join('+') + ' soat)' : '') : 'Amaliy') + '">' + (block.type === 'lecture' ? 'M' : 'A') + '</span>';
                        // Alohida ma'ruza: kesishuv (xato), boshqa fan amaliyoti ma'ruza kunlarida (ogohlantirish), soatlar yig'indisi rejadan farqli.
                        const sepNotes = [block.lecture_clash, ...(block.lecture_warn || []), block.lecture_note].filter(Boolean);
                        const sepNoteHtml = sepNotes.length
                            ? ' <span class="cyc-scope-note' + (block.lecture_clash ? ' is-clash' : '') + '" title="' + esc(sepNotes.join('\n')) + '">⚠</span>' : '';
                        const twoRects = rects.length > 1;
                        rects.forEach(rect => {
                            // Dum bo'lagi (ma'ruza tugagach) yuqoriroq paradan boshlanishi mumkin.
                            const lp = Math.max(1, rect.lane0 || p);
                            const lanes = Math.min(rect.lanes, pairs - lp + 1);
                            const to = Math.min(rect.to, cols - 1);
                            if (lanes < 1 || to < rect.from || rect.from < 0) return;
                            if (!free(lp, lanes, rect.from, to)) {
                                // Online blocks remain visible together in the occupied cell, with an informational notice.
                                if (rect.main && isNonBlocking(cycleInfoCard(row, block))) {
                                    for (let lane = 1; lane < lp + lanes; lane++) {
                                        const owner = Object.entries(cellAt[lane] || {}).find(([from, cell]) => lane + (cell.lanes || 1) > lp && +from <= to && cell.next > rect.from);
                                        if (owner) {
                                            owner[1].html = owner[1].html.replace('</td>', cycleInfoOverlapHtml(row, block) + '</td>');
                                            break;
                                        }
                                    }
                                }
                                return;
                            }
                            const spanCols = to - rect.from + 1;
                            const joinStyle = twoRects ? (rect.main ? 'border-right:0;' : 'border-left:0;') : '';
                            let cellHtml;
                            if (rect.main && markMode) {
                                // Kafedra mudiri: blok ichida kun × soat to'ri.
                                // Ustunlar — blokning kalendar kunlari, qatorlar
                                // — kunlik soatlar; ma'ruza kataklari bo'yaladi.
                                // Ichki jadval: har kun KTR bo'yicha — ma'ruza (M), amaliy (A),
                                // bo'sh soat; blok ichidagi dam olish/bayram ustuni chiziqli.
                                const plan = block.day_plan || {};
                                let sumLec = 0, sumPrc = 0;
                                Object.values(plan).forEach(dp => { sumLec += +dp.lec || 0; sumPrc += +dp.prc || 0; });
                                const lecTotal = block.lecture_hours, prcTotal = block.practice_hours;
                                // Alohida ma'ruzali fan: ma'ruza blokida — faqat M (kunlik soatlar), amaliy blokida — faqat A.
                                const sumLabel = block.lecture_separate
                                    ? (block.type === 'lecture'
                                        ? 'M ' + sumLec + ' s (' + (block.lecture_list || []).join('+') + ')' + (lecTotal != null ? ' · reja ' + lecTotal + ' s' : '')
                                        : 'A ' + sumPrc + (prcTotal != null ? '/' + prcTotal : '') + ' s')
                                    : 'M ' + sumLec + (lecTotal != null ? '/' + lecTotal : '') + ' · A ' + sumPrc + (prcTotal != null ? '/' + prcTotal : '') + ' s';
                                // Tor blokda yorliq sig'maydi: o'qituvchi/xona faqat sichqoncha ustiga borganda.
                                // Blok ichida ko'rinadigan kunlar (yashirilgan dam olish/bayram ustunlarisiz).
                                const visDays = [];
                                for (let d = 0; d < spanCols; d++) if (!cycleColHidden(rect.from + d)) visDays.push(d);
                                if (!visDays.length) for (let d = 0; d < spanCols; d++) visDays.push(d);
                                const compact = visDays.length <= 6;
                                // Blokni kataklar to'liq qoplaydi va ularning o'z title'i bor — td title'i
                                // hech qachon chiqmaydi. Shuning uchun tor blokda ma'lumot katak title'iga qo'shiladi.
                                const blockTip = compact ? ' — ' + block.subject + (req ? ' · ' + req : '') + ' · ' + sumLabel : '';
                                let inner = '';
                                for (let hour = 1; hour <= dayHours; hour++) {
                                    for (const d of visDays) {
                                        const dayIndex = rect.from + d;
                                        const date = dates[dayIndex];
                                        const off = date && (date.sunday || date.holiday || date.off);
                                        const offset = dayIndex - block.from;
                                        const dp = plan[offset];
                                        let kind = '';
                                        if (!off && dp) {
                                            const st = +dp.start || 1;
                                            // Amaliy boshlanishi (ps): guruhcha smenasi bo'lsa — ma'ruzadan keyin emas, smena soatidan.
                                            const ps = dp.ps != null ? +dp.ps : st + (+dp.lec || 0);
                                            if (hour >= st && hour < st + (+dp.lec || 0)) kind = ' is-lecture';
                                            else if (hour >= ps && hour < ps + (+dp.prc || 0)) kind = ' is-practice';
                                            // Oqim ma'ruzasi shu sanada vaqtincha kafedra mudirida (mudir_ph_lec).
                                            const lph = block.mudir_ph_lec;
                                            if (kind === ' is-lecture' && lph && date && (!(lph.dates || []).length || lph.dates.includes(date.iso))) kind += ' is-ph-lec';
                                        }
                                        const offLabel = off && hour === Math.ceil(dayHours / 2) ? (date.holiday ? 'bayram' : 'dam') : '';
                                        inner += '<button type="button" class="cyc-mk-cell'
                                            + (off ? ' is-off' + (date.holiday ? ' is-holiday' : '') : '')
                                            + kind
                                            + (hour % 2 === 0 ? ' is-pair-end' : '')
                                            + (hour === 1 ? ' is-first' : '') + (hour === dayHours ? ' is-last' : '')
                                            + '" data-mk-key="' + esc(block.key) + '"'
                                            + ' data-mk-day="' + offset + '" data-mk-hour="' + hour + '"'
                                            + (offLabel ? ' data-off-label="' + offLabel + '"' : '')
                                            + (off ? ' disabled' : '')
                                            + ' title="' + (date ? esc(date.d) : '') + (off ? (date.holiday ? ' · bayram' : ' · dam olish kuni') : (dp ? ' · ' + dp.k + '-kun · ' + hour + '-soat' : ' · ' + hour + '-soat')) + esc(blockTip)
                                            + (kind.includes('is-ph-lec') ? ' · ma‘ruza vaqtincha kafedra mudirida: ' + esc(block.mudir_ph_lec.mudir_name || block.mudir_ph_lec.teacher_name || '') : '') + '"></button>';
                                    }
                                }
                                cellHtml = '<td class="cyc-cell cyc-block is-mark' + cfBlockClass(block.key, block.conflicts, cfOwners) + '" rowspan="' + lanes + '" colspan="' + spanCols + '" data-cycle-row="' + esc(row.row_key) + '" data-cycle-pair="' + lp + '" data-cycle-from="' + rect.from + '" data-cycle-span="' + spanCols + '" data-cycle-key="' + esc(block.key) + '" style="background:' + color.bg + ';border-color:' + color.border + ';' + joinStyle + '" title="' + esc(block.subject) + ' — ' + block.days + ' kun' + (block.scope_note ? ' · ⚠ ' + esc(block.scope_note) : '') + (sepNotes.length ? ' · ⚠ ' + esc(sepNotes.join('; ')) : '') + ' · ' + esc(sumLabel) + (req ? ' · ' + esc(req) : '') + '">' +
                                    '<div class="cyc-mk">' +
                                    '<div class="cyc-mk-grid" style="grid-template-columns:repeat(' + visDays.length + ',1fr);grid-template-rows:repeat(' + dayHours + ',1fr)">' +
                                    inner +
                                    '<div class="cyc-mk-over' + (compact ? ' is-compact' : '') + '" style="' + cycTitlePosStyle(block, plan, dayHours) + '">' +
                                    // O'qituvchi biriktirilmagan fan: kulrang fon, qizil uzuq hoshiya va belgi.
                                    (block.teacher_name
                                        ? '<span class="cyc-mk-title" role="button" tabindex="0" data-mk-subj="' + esc(block.key) + '" title="Bosing — fan haqida (soatlar, o\'qituvchi, xona). Ushlab blok ichida siljiting; ikki marta bosing — markazga qaytadi." style="background:color-mix(in srgb, ' + color.bg + ' 62%, transparent);border:1px solid ' + color.border + '">'
                                        : '<span class="cyc-mk-title is-noteacher" role="button" tabindex="0" data-mk-subj="' + esc(block.key) + '" title="O\'qituvchi biriktirilmagan — ⚙ orqali biriktiring. Bosing — fan haqida; ushlab siljiting; ikki marta bosing — markazga qaytadi.">'
                                            + '<i class="bi bi-person-fill-exclamation" aria-label="O\'qituvchi biriktirilmagan"></i> ') +
                                    // To'qnashuv: qisqa belgi (qizil — o'qituvchi/guruh, sariq — xona, kulrang — o'tgan); tafsilot — bosilganda.
                                    cfBadgeHtml(block.key, block.conflicts, cfOwners) +
                                    // Oqimda o'quv rejalar / fakultetlar har xil — aniqlovchili sozlama o'rniga yuqori daraja olindi (⚠).
                                    (sepLecBlock ? '<span class="cyc-type lecture">M</span> ' : '') + esc(block.subject) + ' <span class="cyc-days">(' + block.days + ')</span>' + (block.scope_note ? ' <span class="cyc-scope-note" title="' + esc(block.scope_note) + '">⚠</span>' : '') + sepNoteHtml + '</span>' +
                                    // O'qituvchi/xona doskada yozilmaydi — fan nomi bosilganda oynada chiqadi.
                                    '</div>' +
                                    '<button type="button" class="cyc-gear cyc-mk-gear" data-cycle-gear="' + esc(block.key) + '" title="O\'qituvchi / xona biriktirish">&#9881;</button>' +
                                    '</div></div></td>';
                            } else if (rect.main) {
                                cellHtml = '<td class="cyc-cell cyc-block" draggable="true" rowspan="' + lanes + '" colspan="' + spanCols + '" data-cycle-row="' + esc(row.row_key) + '" data-cycle-pair="' + lp + '" data-cycle-from="' + rect.from + '" data-cycle-span="' + spanCols + '" data-cycle-key="' + esc(block.key) + '" style="background:' + color.bg + ';border-color:' + color.border + ';' + joinStyle + '" title="' + esc(block.subject) + ' — ' + block.days + ' kun' + (block.scope_note ? ' · ⚠ ' + esc(block.scope_note) : '') + (sepNotes.length ? ' · ⚠ ' + esc(sepNotes.join('; ')) : '') + (block.hours ? ' · ' + block.hours + ' soat' : '') + (req ? ' · ' + esc(req) : '') + '">' +
                                    '<span class="cyc-shift-actions">' +
                                    '<button type="button" class="cyc-shift-btn" data-cycle-shift="-1" aria-label="Bir o\'quv kuni orqaga">&#8592;</button>' +
                                    '<button type="button" class="cyc-gear" draggable="false" data-cycle-gear="' + esc(block.key) + '" title="O\'qituvchi / vaqt / xona biriktirish">&#9881;</button>' +
                                    '<button type="button" class="cyc-shift-btn" data-cycle-shift="1" aria-label="Bir o\'quv kuni oldinga">&#8594;</button>' +
                                    '</span><span class="cyc-lbl">' + typeChip + '<b class="cyc-subj">' + esc(block.subject) + '</b> <span class="cyc-days">(' + block.days + ')</span>' + (block.scope_note ? ' <span class="cyc-scope-note" title="' + esc(block.scope_note) + '">⚠</span>' : '') + sepNoteHtml + (block.hours ? '<i class="cyc-hrs">' + block.hours + ' s</i>' : '') + '</span>' +
                                    reqHtml +
                                    '</td>';
                            } else {
                                cellHtml = '<td class="cyc-cell cyc-block cyc-cont" rowspan="' + lanes + '" colspan="' + spanCols + '" data-cycle-row="' + esc(row.row_key) + '" data-cycle-pair="' + lp + '" data-cycle-from="' + rect.from + '" data-cycle-span="' + spanCols + '" style="background:' + color.bg + ';border-color:' + color.border + ';' + joinStyle + '" title="' + esc(block.subject) + '"></td>';
                            }
                            if (isNonBlocking(cycleInfoCard(row, block))) {
                                cellHtml = cellHtml.replace('cyc-block', 'cyc-block tt-info-only').replace('</td>', infoOnlyBadgeHtml(cycleInfoCard(row, block)) + '</td>');
                            }
                            cellAt[lp][rect.from] = { html: cellHtml, next: to + 1, lanes };
                            mark(lp, lanes, rect.from, to);
                        });
                    });
                    for (let pair = 1; pair <= pairs; pair++) {
                        h += markMode ? '<tr class="cyc-markrow" style="--mk-rows:' + dayHours + '">' : '<tr>';
                        if (pair === 1) {
                            // Guruh rejimida qator — bitta guruh: nomi to'g'ridan-to'g'ri.
                            // Bo'lakli fan qatori ("Fan (c)"): bo'lak nomi + oqim + qaysi guruhchalardan.
                            const groupLabel = row.variant
                                ? cycleVariantLabelHtml(row)
                                : (j.view || cycleViewMode) === 'group'
                                ? '<div class="cyc-members"><div class="cyc-member-row cyc-member-single"><span title="' + esc(row.group) + '">' + esc(row.group) + '</span></div>'
                                    + (row.member_students ? '<div class="cyc-stu-line">' + cycleStuCountHtml(
                                        Object.values(row.member_students).reduce((a, b) => a + (+b || 0), 0)) + ' talaba</div>' : '')
                                    + '</div>'
                                : cycleMembersHtml(row.group, row.subgroups, row.member_students);
                            h += '<td class="cyc-gcol" rowspan="' + (pairs + (showAddPair ? 1 : 0)) + '">' + groupLabel + '</td>';
                            if (markMode) {
                                // Karta ichidagi soat qatorlari bilan bir tekis
                                // turadigan yonbosh yorliqlar (qo'ng'iroq jadvalidan).
                                let sideRows = '';
                                // Qator — akademik soat. To'liq paralik jadvalda bitta para
                                // 2 soat: 1–2-soat — I-para, 3–4 — II-para, 5–6 — III-para.
                                const hpp = rowMins >= 60 ? 2 : 1;
                                // Har qator — yarim para (40 daqiqa): vaqti para boshidan/oxiridan hisoblanadi.
                                const toMin = t => { const m = /^(\d{1,2}):(\d{2})$/.exec(t || ''); return m ? (+m[1]) * 60 + (+m[2]) : null; };
                                const toHm = v => String(Math.floor(v / 60)).padStart(2, '0') + ':' + String(v % 60).padStart(2, '0');
                                for (let hour = 1; hour <= dayHours; hour++) {
                                    const pt = bellPairs[Math.ceil(hour / hpp) - 1];
                                    const part = (hour - 1) % hpp;           // para ichidagi yarim (0 yoki 1)
                                    const a = pt ? toMin(pt.start) : null, b = pt ? toMin(pt.end) : null;
                                    let span = '';
                                    if (a != null && b != null) {
                                        const step = (b - a) / hpp;
                                        span = toHm(Math.round(a + step * part)) + '–' + toHm(Math.round(a + step * (part + 1)));
                                    }
                                    const pairNo = Math.ceil(hour / hpp);
                                    // Qo'ng'iroq jadvali yarim paralarga bo'lingan bo'lsa (hpp=1), ketma-ket bir xil
                                    // qisqartmali qatorlar ("I", "I") bitta para katagiga birlashadi.
                                    const abbrAt = hh => { const t = bellPairs[Math.ceil(hh / hpp) - 1]; const a = t ? String(t.abbr || '').trim() : ''; return a && a !== '—' ? a : null; };
                                    const sameAsPrev = hpp === 1 && hour > 1 && abbrAt(hour) && abbrAt(hour) === abbrAt(hour - 1);
                                    let groupLen = 1;
                                    while (hpp === 1 && abbrAt(hour) && hour + groupLen <= dayHours && abbrAt(hour + groupLen) === abbrAt(hour)) groupLen++;
                                    if (part === 0 && !sameAsPrev) {
                                        // Para nomi — shu paraning barcha yarim qatorlarini qamraydi.
                                        const rowsInPair = hpp === 1 ? groupLen : Math.min(hpp, dayHours - hour + 1);
                                        const abbr = pt ? (pt.abbr && pt.abbr !== '—' ? pt.abbr : (pt.name || pairNo)) : pairNo;
                                        sideRows += '<div class="cyc-mk-side-para" style="grid-column:1;grid-row:' + hour + ' / span ' + rowsInPair + '"'
                                            + ' title="' + esc(pt ? (pt.name || '') + ' ' + (pt.start || '') + '–' + (pt.end || '') : '') + '">'
                                            + '<b>' + esc(abbr) + '</b><i>para</i></div>';
                                    }
                                    const pairEnd = hpp === 1 ? !(abbrAt(hour) && hour < dayHours && abbrAt(hour + 1) === abbrAt(hour)) : hour % hpp === 0;
                                    sideRows += '<div class="cyc-mk-side-row' + (pairEnd ? ' is-pair-end' : '') + '" style="grid-column:2;grid-row:' + hour + '">' +
                                        (span ? '<span>' + span + '</span>' : '') +
                                        '</div>';
                                }
                                h += '<td class="cyc-mk-side"><div class="cyc-mk-side-box">' +
                                    '<div class="cyc-mk-side-gap"></div>' +
                                    '<div class="cyc-mk-side-rows" style="grid-template-rows:repeat(' + dayHours + ',1fr)">' +
                                    sideRows + '</div></div></td>';
                            }
                        }
                        if (!simple) {
                            const pt = bellPairs[pair - 1];
                            h += '<td class="cyc-pcol"><div class="cyc-pname">' + esc(pt ? (pt.name || pt.abbr || pair) : (pair + '-para')) + '</div>' +
                                (pt && (pt.start || pt.end) ? '<div class="cyc-ptime">' + esc(pt.start || '') + '<br>' + esc(pt.end || '') + '</div>' : '') + '</td>';
                        }
                        let col = 0;
                        while (col < cols) {
                            const cellObj = cellAt[pair][col];
                            if (cellObj) { h += cellObj.html; col = cellObj.next; continue; }
                            if (covered[pair][col]) { col++; continue; }
                            let endCol = col;
                            while (endCol + 1 < cols && !covered[pair][endCol + 1] && !cellAt[pair][endCol + 1]) endCol++;
                            h += '<td class="cyc-cell" colspan="' + (endCol - col + 1) + '" data-cycle-row="' + esc(row.row_key) + '" data-cycle-pair="' + pair + '" data-cycle-from="' + col + '" data-cycle-span="' + (endCol - col + 1) + '"></td>';
                            col = endCol + 1;
                        }
                        h += '</tr>';
                    }
                    if (showAddPair) {
                        h += '<tr class="cyc-addrow"><td class="cyc-pcol"><button type="button" class="cyc-addpair" title="Yana bir para qo\'shish">+</button></td>' +
                            '<td class="cyc-addcell" colspan="' + dates.length + '"></td></tr>';
                    }
                });
                h += '</tbody>';
                $('cycleGrid').innerHTML = h;
                setupCycleGridEvents();
                setupCycleMarking();
                setupCycTitleDrag();
                clampCycTitles();
                renderCycleCards(j);
                focusHighlight();
            }

            // ── Sikl jadvali hodisalari (delegatsiya) ──
            // Har renderda minglab katakka to'rttadan listener ulash drag
            // paytida interfeysni qotirardi; endi butun jadvalga bir marta
            // ulanadi va render faqat innerHTML almashtiradi.
            let cycleDropCell = null;
            let cycleGridEventsReady = false;
            // ── Ma'ruza kataklarini belgilash (kafedra mudiri) ──
            // Bosib yoki sudrab belgilanadi; sichqoncha qo'yib yuborilganda
            // butun blok belgilari bitta so'rovda saqlanadi.
            let mkDrag = null;   // {key, turnOn} — sudrash paytidagi holat

            // Hisoblagich yozuvi: belgilangan soat / rejadagi ma'ruza soati.
            function markCountLabel(marked, total) {
                if (total == null || total === '') return 'M: ' + marked + ' soat';
                const left = total - marked;
                if (left > 0) return 'M: ' + marked + '/' + total + ' soat · qoldi ' + left;
                if (left < 0) return 'M: ' + marked + '/' + total + ' soat · ortiqcha ' + (-left);
                return 'M: ' + marked + '/' + total + ' soat';
            }

            function refreshMarkCount(key) {
                const badge = document.querySelector('.cyc-mk-count[data-mk-count="' + CSS.escape(key) + '"]');
                if (!badge) return;
                const marked = document.querySelectorAll(
                    '.cyc-mk-cell.is-lecture:not(.is-off)[data-mk-key="' + CSS.escape(key) + '"]'
                ).length;
                const raw = badge.dataset.mkTotal;
                const total = raw === '' ? null : Number(raw);
                badge.textContent = markCountLabel(marked, total);
                badge.classList.toggle('is-done', total != null && marked === total);
                badge.classList.toggle('is-over', total != null && marked > total);
            }

            function mkSlotsOf(key) {
                const slots = {};
                document.querySelectorAll('.cyc-mk-cell.is-lecture[data-mk-key="' + CSS.escape(key) + '"]')
                    .forEach(cell => {
                        const day = cell.dataset.mkDay;
                        (slots[day] = slots[day] || []).push(+cell.dataset.mkHour);
                    });
                return slots;
            }

            async function saveLectureSlots(key) {
                const card = (cyclePlanData && cyclePlanData.cycle_cards || []).find(item => item.key === key);
                if (!card) return;
                try {
                    await api(BASE + '/boards/' + board.id + '/cycle-lecture-slots', 'POST', {
                        specialty_name: card.specialty, course: card.course,
                        group_name: card.group, subject_name: card.subject,
                        training_type: card.type || 'practice', view: cycleEffView(), placement_group: (card && card.placement_group) || undefined,
                        slots_json: JSON.stringify(mkSlotsOf(key)),
                    });
                    // Keyingi renderda belgilar joyida qolsin.
                    const block = (cyclePlanData.rows || [])
                        .flatMap(row => row.blocks || [])
                        .find(item => item.key === key);
                    if (block) block.lecture_slots = mkSlotsOf(key);
                    $('cycleMsg').textContent = 'Ma\'ruza soatlari saqlandi.';
                } catch (e) {
                    alert('Ma\'ruza soatlarini saqlab bo\'lmadi: ' + e.message);
                    loadCyclePlan();
                }
            }

            // ===== O'qituvchi kun/hafta jadvali (teacher-agenda) =====
            // Oyna: sarlavha ("MUXAMMADIYEV S. B. — 19.11.2026 (payshanba)"), Kun / Hafta, ◀ ▶. Kun — paralar ustuni (darslar yoki
            // "bo'sh"), hafta — kunlar × paralar. To'qnashuvdagi dars — qizil, ko'chirilayotgani — ko'k ramka. Har bo'sh parada
            // "Shu vaqtga ko'chirish" — server tekshiruvi (guruh, xona, sig'im) bilan: o'chiq — sababi bilan; xona muammosida — bo'sh xona
            // taklifi. Ko'chirish: haftalik — Takliflar bajaruvchisi (admin — darhol, boshqalar — so'rov), sikl — kun boshlanishi yoki
            // blokning kelgusi kunlari (cycle-practice-starts / cycle-time-proposal). Keyin oyna va jadval yangilanadi.
            // Bugungi darsni ko'chirgandan keyin — HEMIS dagi jadval va davomatni solishtirish eslatmasi (server ham hemis_hint beradi).
            const TT_HEMIS_HINT = 'Bugungi dars — ko\u2018chirgandan keyin HEMIS dagi jadval va davomatni \u00abBugungi darslar (HEMIS)\u00bb orqali solishtiring.';
            let ttAgenda = null;   // { teacher_id, teacher_name, date, range, move, data, pick, msg, busy }
            let agendaSeq = 0;     // so'rov tartibi: kun/hafta tez almashsa — eski (kechikkan) javob yangisining ustiga yozilmaydi
            // Ko'chirish variantlari (teacher-agenda?move=) keshi: kalit — dars + sana + kun/hafta + qatlam + o'qituvchi; qiymat — { mv, p (kutilayotgan
            // so'rov), ctrl, demand (sudrash / tanlash uchun — oldindan yuklash uni to'xtatmaydi) }. Ko'chirishdan keyin, sana yoki kun/hafta
            // almashganda, oyna yopilganda — tozalanadi. Oldindan yuklash (sichqoncha dars ustiga kelsa, 150 ms; oyna ochilganda — to'qnashuvdagi
            // ikkinchi dars) — bir vaqtda bittasi: yangisi eskisini to'xtatadi.
            const agMoveCache = new Map();
            let agPrefetchCk = null;
            let agHoverTimer = null;
            // Javob kelmasdan tashlangan katak (bittasi): { d (sudrash), st, key, date, pair } — javob kelgach agendaDropState bo'yicha davom etadi.
            let agPending = null;
            const agLayer = () => ((viewMode === 'cycle' ? cycleLayer : weeklyLayer) === 'external' ? 'external' : 'internal');
            const agCk = (st, key) => [key, st.date, st.range, agLayer(), st.teacher_id].join('|');
            function agendaCacheClear() {
                agMoveCache.forEach(it => { if (it.p && it.ctrl) it.ctrl.abort(); });
                agMoveCache.clear();
                agPrefetchCk = null;
            }
            // Dars variantlari: keshdan yoki so'rov bilan (Promise<move>). demand = false — oldindan yuklash (oxirgisi ustun, eskisi to'xtatiladi).
            function agendaMoveGet(st, key, demand) {
                const ck = agCk(st, key);
                let it = agMoveCache.get(ck);
                if (it) {
                    if (demand) it.demand = true;
                    return it.mv ? Promise.resolve(it.mv) : it.p;
                }
                if (!demand && agPrefetchCk && agPrefetchCk !== ck) {
                    const old = agMoveCache.get(agPrefetchCk);
                    if (old && old.p && !old.demand) { if (old.ctrl) old.ctrl.abort(); agMoveCache.delete(agPrefetchCk); }
                }
                const ctrl = typeof AbortController === 'function' ? new AbortController() : null;
                const q = new URLSearchParams({ teacher_id: st.teacher_id, date: st.date, range: st.range, layer: agLayer(), move: key });
                it = { mv: null, p: null, ctrl, demand: !!demand };
                it.p = api(BASE + '/boards/' + board.id + '/teacher-agenda?' + q, 'GET', null, { timeout: 65000, signal: ctrl ? ctrl.signal : undefined })
                    .then(j => { it.mv = j.move; it.p = null; return j.move; },
                        e => { if (agMoveCache.get(ck) === it) agMoveCache.delete(ck); throw e; });
                agMoveCache.set(ck, it);
                if (!demand) agPrefetchCk = ck;
                return it.p;
            }
            // Oldindan yuklash (natija keshda; xato — jim).
            function agendaPrefetch(st, key) {
                const cur = st.data && st.data.move;
                if (!key || st.room_code || (st.move === key && cur && cur.key === key && !cur.loading)) return;
                agendaMoveGet(st, key, false).catch(() => {});
            }
            // Oyna ochilganda: ko'chiriladigan dars bilan to'qnashuvdagi ikkinchi (ko'chirsa bo'ladigan) dars — oldindan.
            function agendaPrefetchPartner(st) {
                const j = st.data, mv = j && j.move;
                if (!mv || !st.move || mv.loading) return;
                const me = (j.entries || []).find(e => e.key === st.move) || mv;
                const other = (j.entries || []).find(e => e.movable && e.key && e.key !== st.move && e.conflict && e.date === me.date
                    && e.from < me.to && me.from < e.to);
                if (other) agendaPrefetch(st, other.key);
            }
            document.addEventListener('click', ev => {
                const a = ev.target && ev.target.closest ? ev.target.closest('[data-agenda]') : null;
                if (!a) return;
                ev.preventDefault();
                ev.stopPropagation();
                let info = null;
                try { info = JSON.parse(a.dataset.agenda); } catch (e) { return; }
                ttAgendaOpen(info);
            }, true);
            const agShift = (date, days) => { const d = new Date(date + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + days); return d.toISOString().slice(0, 10); };
            // ◀ ▶: kun — bir kun (yakshanba o'tkaziladi), hafta — yetti kun.
            function agendaStep(date, range, dir) {
                let d = agShift(date, range === 'week' ? 7 * dir : dir);
                if (range !== 'week' && new Date(d + 'T00:00:00Z').getUTCDay() === 0) d = agShift(d, dir);
                return d;
            }
            async function ttAgendaOpen(info) {
                const keep = ttAgenda && !info.range && ttAgenda.teacher_id === (+info.teacher_id || 0) && (ttAgenda.room_code || null) === (info.room_code || null)
                    ? { range: ttAgenda.range } : {};
                // Xona bandligi: teacher_id o'rniga room_code — xonaning kun/hafta darslari va bo'sh paralari (ko'chirishsiz).
                ttAgenda = Object.assign({ range: 'day', move: null, room_code: null }, keep, info,
                    { teacher_id: +info.teacher_id || 0, data: null, pick: null, msg: null, busy: false });
                agendaCacheClear();
                agPending = null;
                await ttAgendaLoad();
                if (ttAgenda && ttAgenda.data) agendaPrefetchPartner(ttAgenda);
            }
            async function ttAgendaLoad() {
                const st = ttAgenda;
                if (!st || !board) return;
                agendaRender(true);
                // Qatlam — oyna ochilgan ko'rinishniki: sikl jadvalida — sikl qatlami, haftalikda — haftalik qatlam (ular alohida).
                const layer = viewMode === 'cycle' ? cycleLayer : weeklyLayer;
                const q = new URLSearchParams(Object.assign(st.room_code ? { room_code: st.room_code } : { teacher_id: st.teacher_id },
                    { date: st.date, range: st.range, layer: layer === 'external' ? 'external' : 'internal' }));
                if (st.move && !st.room_code) q.set('move', st.move);
                if (st.restFor) q.set('rest_for', st.restFor);   // "shu va keyingi haftalar" — tanlangan para tekshiruvi
                if (st.selFor) q.set('sel', st.selFor);   // "bir nechta hafta / kun" — tanlanganlar tekshiruvi
                const seq = ++agendaSeq;
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/teacher-agenda?' + q);
                    if (ttAgenda !== st || seq !== agendaSeq) return;
                    st.data = j;
                    // Shu darsning variantlari — keshga (keyin bosish / sudrash so'rovsiz).
                    if (st.move && j.move && j.move.key === st.move && !st.room_code) agMoveCache.set(agCk(st, st.move), { mv: j.move, p: null, ctrl: null, demand: true });
                } catch (e) {
                    if (ttAgenda !== st || seq !== agendaSeq) return;
                    st.msg = { kind: 'err', text: e.message };
                }
                agendaRender(false);
            }
            function ttAgendaClose() {
                ttAgenda = null;
                agPending = null;
                if (agHoverTimer) clearTimeout(agHoverTimer);
                agendaCacheClear();
                document.removeEventListener('keydown', agendaKey, true);
                const m = document.getElementById('ttAgendaModal');
                if (m) m.remove();
            }
            function agendaKey(e) {
                if (e.key === 'Escape' && agDrag) { e.preventDefault(); e.stopPropagation(); agendaDragEnd(null); return; }   // sudrash bekor
                if (e.key === 'Escape' && agPending) { e.preventDefault(); e.stopPropagation(); agendaPendingCancel(); return; }   // kutilayotgan tashlash bekor
                if (e.key === 'Escape' && !document.getElementById('ttReasonModal')) { e.preventDefault(); e.stopPropagation(); ttAgendaClose(); }
            }
            function agendaRender(loading) {
                let m = document.getElementById('ttAgendaModal');
                if (!ttAgenda) { if (m) m.remove(); return; }
                if (!m) {
                    m = document.createElement('div');
                    m.id = 'ttAgendaModal';
                    m.setAttribute('role', 'dialog');
                    m.setAttribute('aria-modal', 'true');
                    m.addEventListener('click', agendaClick);
                    m.addEventListener('pointerdown', agendaPointerDown);
                    m.addEventListener('pointerover', agendaHover);
                    m.addEventListener('pointerout', agendaHoverOut);
                    document.body.appendChild(m);
                    document.addEventListener('keydown', agendaKey, true);
                }
                m.innerHTML = agendaHtml(ttAgenda, loading);
            }
            // Tanlangan bo'sh para uchun natija: haftalik — options; sikl — "butun blok" bo'lsa block, aks holda options.
            // "weeks" / "days" (bir nechta hafta / kun): joy — "shu hafta/kun" varianti, natija — server tekshiruvi (mv.sel) tanlanganlar bo'yicha.
            function agendaOpt(mv, date, pair, choice, items) {
                if (choice === 'weeks' || choice === 'days') {
                    const one = agendaOpt(mv, date, pair, 'one');
                    if (!one) return null;
                    const sel = mv.sel, want = (items || []).map(String).join(',');
                    const same = sel && sel.date === date && +sel.pair === +pair && (sel.items || []).map(String).join(',') === want;
                    if (!want) return Object.assign({}, one, { ok: false, why: 'kamida bittasini tanlang' });
                    return Object.assign({}, one, same ? { ok: !!sel.ok, why: sel.why || null, bad: sel.bad || [] } : { ok: false, why: 'tekshirilmoqda…' });
                }
                const src = mv && mv.kind === 'cycle' && choice === 'block' ? mv.block : mv && mv.options;
                return src && src[date] ? src[date][pair] || null : null;
            }
            // Tanlanganlarni server tekshiruviga yuboradi (sel) — oyna qayta yuklanadi.
            function agendaSelCheck(st) {
                const pk = st.pick;
                st.selFor = pk && (pk.choice === 'weeks' || pk.choice === 'days') && (pk.items || []).length
                    ? pk.date + '|' + pk.pair + '|' + pk.items.join(',') : null;
                if (st.selFor) ttAgendaLoad(); else agendaRender(false);
            }
            function agendaHtml(st, loading) {
                const j = st.data, mv = j && j.move;
                const title = j ? j.title : (st.room_code ? (st.room_name || 'Xona') : (st.teacher_name || "O'qituvchi")) + ' — ' + cfDate(st.date);
                // To'liq F.I.Sh. yonida telefon (tel: havola) — server huquq bo'yicha beradi; bo'lmasa ko'rsatilmaydi.
                const tel = j && j.teacher && j.teacher.phone
                    ? ' <a class="ag-phone" href="tel:' + esc(j.teacher.phone_tel || j.teacher.phone) + '" title="Qo\'ng\'iroq qilish">· ' + esc(j.teacher.phone) + '</a>' : '';
                return '<div class="ag-box"><div class="ag-head"><b>' + esc(title) + '</b>' + tel +
                    '<span class="ag-tabs"><button type="button" data-ag="day"' + (st.range === 'week' ? '' : ' class="on"') + '>Kun</button>' +
                    '<button type="button" data-ag="week"' + (st.range === 'week' ? ' class="on"' : '') + '>Hafta</button></span>' +
                    '<button type="button" data-ag="prev" aria-label="Oldingi">◀</button><button type="button" data-ag="next" aria-label="Keyingi">▶</button>' +
                    '<button type="button" data-ag="close" aria-label="Yopish">&times;</button></div>' +
                    (st.msg ? '<div class="ag-msg ag-' + esc(st.msg.kind) + '">' + esc(st.msg.text) + '</div>' : '') +
                    (mv && mv.why ? '<div class="ag-msg ag-err">Ko‘chirib bo‘lmaydi: ' + esc(mv.why) + '</div>' : '') +
                    (mv && !mv.why && mv.label ? '<div class="ag-msg" data-ag-head>Ko‘chiriladigan dars: <b>' + esc(mv.label) + '</b>' + (mv.date ? ', ' + esc(cfDate(mv.date)) : '') +
                        (mv.loading ? ' — <span class="ag-spin"></span>tekshirilmoqda…'
                            : ' — bo‘sh paralardan birini tanlang' + (mv.kind === 'cycle' ? ' (kun o‘zgarmaydi)' : ' (shu hafta ichida)') + '.') +
                        (agendaOtherMovable(j, st.move) ? ' Boshqa darsni tanlash uchun uni bosing yoki sudrang.' : '') + '</div>'
                        : j && !mv && !st.room_code && agendaOtherMovable(j, null) ? '<div class="ag-msg" data-ag-head>Ko‘chirish uchun darsni bosing yoki sudrang.</div>' : '') +
                    agendaPickHtml(st) +
                    (loading && !j ? '<div class="ag-load">Yuklanmoqda…</div>' : j ? (st.range === 'week' ? agendaWeekHtml(j, st) : agendaDayHtml(j, st)) : '') +
                    '</div>';
            }
            // Oynada (ko'chiriladigandan boshqa) ko'chirsa bo'ladigan dars bormi — sarlavhadagi "boshqa darsni tanlash" ko'rsatmasi uchun.
            const agendaOtherMovable = (j, moveKey) => ((j && j.entries) || []).some(e => e.key && e.movable && e.key !== moveKey);
            // Dars: vaqt, fan (M/A), guruhlar, xona; qamrovdan tashqari — faqat "band: boshqa fakultet"; davomi (keyingi para) — "↳".
            // Katak tooltipi (to'liq): vaqt, fan (M/A), barcha guruhlar, o'qituvchi to'liq F.I.Sh., xona, to'qnashuv sababi.
            function agendaEntryTip(e) {
                if (e.hidden) return [(e.start || '') + '–' + (e.end || ''), e.label].filter(Boolean).join('\n');
                return [(e.start || '') + '–' + (e.end || '') + ' ' + e.subject + ' (' + (e.type === 'M' ? "M — ma'ruza" : 'A — amaliy') + ')',
                    'Guruh: ' + (e.groups || []).join(', '), e.teacher_full || e.teacher ? "O'qituvchi: " + (e.teacher_full || e.teacher) : '',
                    e.room ? 'Xona: ' + e.room : '', e.conflict ? "To'qnashuv: " + (e.conflict_with || 'bir vaqtda boshqa dars') : '',
                    e.out_of_scope ? "Qamrovdan tashqari dars — faqat ko'rish" : ''].filter(Boolean).join('\n');
            }
            function agendaEntryHtml(e, moveKey, cont, compact) {
                const moving = !!(e.key && e.key === moveKey);
                const cls = 'ag-e' + (e.info_only ? ' tt-info-only' : '') + (e.conflict ? ' ag-conf' : '') + (moving ? ' ag-moving' : '') + (e.hidden ? ' ag-hidden' : '') + (cont ? ' ag-cont' : '');
                // Sudrash: ko'chirsa bo'ladigan dars (server — movable); bo'lmasa — sababi. Tooltip — to'liq ma'lumot va (bo'lsa) ko'chirish izohi.
                const hint = e.key && e.movable ? 'Bosing yoki sudrab bo\u2018sh paraga ko\u2018chiring' : (e.key && e.movable_why ? e.movable_why : '');
                const tip = ' data-ag-tip title="' + esc(agendaEntryTip(e) + (hint && hint !== "Qamrovdan tashqari dars — faqat ko'rish." ? '\n' + hint : '')) + '"';
                const drag = (e.key && e.movable ? ' data-ag-drag="' + esc(e.key) + '"' : '') + tip;
                if (cont) return '<div class="' + cls + '"' + drag + '>↳ ' + esc(e.hidden ? e.label : e.subject + ' (' + e.type + ')') + '</div>';
                // To'qnashuvdagi katakda ko'chirsa bo'ladigan dars — "↕" (ko'chirib bo'lmaydiganida yo'q; sababi — title).
                const icon = e.conflict && e.key && e.movable ? '<span class="ag-mvicon" aria-hidden="true">↕</span>' : '';
                // Xona jadvalida — o'qituvchi, o'qituvchi jadvalida — xona nomi (katak tor bo'lsa — "…", to'liqi tooltipda).
                const who = ttAgenda && ttAgenda.room_code ? (e.teacher || '') : (e.room || '');
                const text = e.hidden ? e.label : e.subject + ' (' + e.type + ') — ' + (compact ? cfGroups(e.groups) : (e.groups || []).join(', ')) +
                    (who ? ' · ' + who : '') + (e.info_only && infoOnlyText(e) ? ' · ' + infoOnlyText(e) : '');
                return '<div class="' + cls + '"' + drag + '>' + icon + '<span class="ag-time">' + esc((e.start || '') + '–' + (e.end || '')) + '</span> ' + esc(text) +
                    (e.conflict ? ' <span class="ag-tag">to‘qnashuv</span>' : '') + (moving ? ' <span class="ag-tag ag-tag-mv">ko‘chiriladi</span>' : '') + '</div>';
            }
            // Bo'sh para: "bo'sh" va (ko'chiriladigan dars bo'lsa) "Shu vaqtga ko'chirish" — o'chiq bo'lsa sababi bilan; xona taklifi.
            function agendaFreeHtml(j, date, no, compact, infoLabels = []) {
                const opt = agendaOpt(j.move, date, no, 'one');
                let btn = '';
                if (opt) {
                    const label = compact ? '→ ko‘chirish' : 'Shu vaqtga ko‘chirish' + (opt.room ? ' (' + opt.room.name + ')' : '');
                    const room = opt.room ? ' → bo‘sh xona: ' + opt.room.name + (opt.room.volume ? ' (' + opt.room.volume + ' o‘rin)' : '') : '';
                    btn = opt.ok
                        ? ' <button type="button" class="ag-mv" data-ag-pick="' + esc(date + '|' + no) + '"' + (opt.why ? ' title="' + esc(opt.why + room) + '"' : '') + '>' +
                            esc(label) + '</button>' + (!compact && opt.why ? '<div class="ag-why ag-warn">' + esc(opt.why + room) + '</div>' : '')
                        : ' <button type="button" class="ag-mv" disabled title="' + esc(opt.why || '') + '">' + esc(label) + '</button>' +
                            (!compact ? '<div class="ag-why">' + esc(opt.why || '') + '</div>' : '');
                }
                // Javob kelmasdan tashlangan katak — "tekshirilmoqda…" (javob kelgach davom etadi).
                const pend = agPending && agPending.st === ttAgenda && agPending.date === date && +agPending.pair === +no;
                return '<div class="ag-free' + (pend ? ' is-pending' : '') + '" data-ag-free="' + esc(date + '|' + no) + '">bo‘sh' + (infoLabels.length ? ' · ' + infoLabels.map(esc).join(', ') : '') + btn +
                    (pend ? '<span class="ag-pend"><span class="ag-spin"></span>tekshirilmoqda…</span>' : '') + '</div>';
            }
            function agendaCellHtml(j, st, date, p, compact) {
                const here = (j.entries || []).filter(e => e.date === date && e.from < p.to && p.from < e.to);
                const shown = here.map(e => agendaEntryHtml(e, st.move, e.from < p.from, compact)).join('');
                const infoLabels = [...new Set(here.filter(e => e.info_only).map(e => isHemisExcluded(e) ? e.course + '-kurs onlayn' : infoSubjectMatch(e) || 'ma’lumot'))];
                return shown + (!here.some(e => !e.info_only) ? agendaFreeHtml(j, date, p.no, compact, infoLabels) : '');
            }
            function agendaDayHtml(j, st) {
                const d = ((j.dates || [])[0] || {}).date;
                return '<table class="ag-day">' + (j.pairs || []).map(p => '<tr><th>' + esc(p.label) + '<div class="ag-time">' + esc(p.start + '–' + p.end) +
                    '</div></th><td>' + agendaCellHtml(j, st, d, p, false) + '</td></tr>').join('') + '</table>';
            }
            function agendaWeekHtml(j, st) {
                return '<table class="ag-week"><tr><th></th>' + (j.dates || []).map(d => '<th>' + esc(d.label) + '</th>').join('') + '</tr>' +
                    (j.pairs || []).map(p => '<tr><th>' + esc(p.label) + '<div class="ag-time">' + esc(p.start + '–' + p.end) + '</div></th>' +
                        (j.dates || []).map(d => '<td>' + agendaCellHtml(j, st, d.date, p, true) + '</td>').join('') + '</tr>').join('') + '</table>';
            }
            // Tanlangan para: ko'chirish turi (haftalik — shu hafta / shu va keyingi haftalar; sikl — shu kun / butun blok) va tasdiq.
            function agendaPickHtml(st) {
                const j = st.data, mv = j && j.move, pk = st.pick;
                if (!mv || !pk) return '';
                const pair = (j.pairs || []).find(p => p.no === +pk.pair) || {};
                const one = agendaOpt(mv, pk.date, pk.pair, 'one');
                const rest = (mv.rest_weeks || []).length;
                // Keyingi haftalar — server tekshiruvi (rest_for): shu para va xona har haftada; kelguncha — o'chiq.
                const restOk = mv.rest && mv.rest.date === pk.date && +mv.rest.pair === +pk.pair ? mv.rest : { ok: false, why: 'keyingi haftalar tekshirilmoqda…' };
                const multi = mv.kind === 'weekly' ? 'weeks' : 'days';
                const multiItems = mv.kind === 'weekly' ? (mv.rest_weeks || []) : (mv.block_days || []).map(x => x.date);
                const multiOpt = agendaOpt(mv, pk.date, pk.pair, multi, pk.choice === multi ? pk.items : [mv.kind === 'weekly' ? mv.week : pk.date]);
                const choices = (mv.kind === 'weekly'
                    ? [['one', 'faqat shu hafta', one], ['rest', 'shu va keyingi haftalar (' + rest + ' ta)', rest > 1 ? restOk : { ok: false, why: 'keyingi haftalarda dars shu joyda emas' }]]
                    : [['one', 'faqat shu kun', one], ['block', 'butun blok (' + (mv.block_date ? cfDate(mv.block_date) + ' dan, kelgusi kunlar' : '—') + ')',
                        agendaOpt(mv, pk.date, pk.pair, 'block')]])
                    .concat(multiItems.length > 1 && one ? [[multi, mv.kind === 'weekly' ? 'bir nechta haftani tanlash' : 'bir nechta kunni tanlash',
                        one.ok ? Object.assign({}, multiOpt || {}, { ok: true, why: null }) : one]] : []);
                const cur = agendaOpt(mv, pk.date, pk.pair, pk.choice, pk.items);
                // Tanlash ro'yxati: haftalik — dars shu joyda turgan haftalar; sikl — blokning kelgusi amaliy kunlari (sana, kun, hozirgi vaqt).
                const bad = new Set(((cur && cur.bad) || []).map(String));
                const listHtml = pk.choice === multi ? '<div class="ag-weeks">' + (mv.kind === 'weekly'
                    ? multiItems.map(w => '<label' + (bad.has(String(w)) ? ' class="ag-bad"' : '') + '><input type="checkbox" data-ag-item="' + w + '"' + ((pk.items || []).map(Number).includes(+w) ? ' checked' : '') + '> ' + w + '-hafta</label>')
                    : (mv.block_days || []).map(x => '<label><input type="checkbox" data-ag-item="' + esc(x.date) + '"' + ((pk.items || []).includes(x.date) ? ' checked' : '') + '> '
                        + esc(cfDate(x.date) + ' · ' + crDow(x.date) + (x.k ? ' · ' + x.k + '-kun' : '') + ' · hozir ' + x.time) + '</label>')).join('')
                    + '</div>' + (cur && !cur.ok && cur.why ? '<div class="ag-why" style="white-space:pre-line">' + esc(cur.why)
                        + (bad.size || /\d{2}\.\d{2}:/.test(cur.why) ? '\nMuammoli hafta/kunni olib tashlab, qayta tekshiring.' : '') + '</div>' : '') : '';
                // To'qnashuvdagi dars toza joyga (faqat shu hafta / kun) — so'rovsiz; bugungi dars (xodim) — HEMIS eslatmasi.
                const fixNow = agendaDirectFix(mv, cur, pk);
                const today = j.today && (pk.date === j.today || mv.date === j.today) && mv.via === 'apply';
                return '<div class="ag-pick"><div><b>' + esc(mv.label || '') + '</b> → ' + esc(cfDate(pk.date) + ', ' + (pair.label || '') +
                    ' (' + (pair.start || '') + '–' + (pair.end || '') + ')') + (one && one.room ? ', xona: ' + esc(one.room.name) : '') + '</div>' +
                    // Ko'p bo'lakli amaliy dars — barcha bo'laklari birga: "6 soat (2+2+2) birga ko'chiriladi".
                    (mv.unit_note ? '<div class="ag-unit-note" data-ag-unit style="font-size:11px;color:#1d4ed8">' + esc(mv.unit_note) + '</div>' : '') +
                    (fixNow ? '<div class="ag-fix-note" data-ag-fix>To‘qnashuvdagi dars — so‘rovsiz joylanadi</div>' : '') +
                    (today ? '<div class="ag-hemis" data-ag-hemis>' + esc(j.hemis_hint || TT_HEMIS_HINT) + '</div>' : '') +
                    choices.map(([v, label, o]) => '<label class="ag-ch"><input type="radio" name="agChoice" value="' + v + '"' + (pk.choice === v ? ' checked' : '') +
                        (o && o.ok ? '' : ' disabled') + '> ' + esc(label) + (o && !o.ok && o.why ? ' <span class="ag-why">— ' + esc(o.why) + '</span>' : '') + '</label>').join('') +
                    listHtml +
                    '<div class="ag-pick-btns"><button type="button" data-ag="submit"' + (cur && cur.ok && !st.busy ? '' : ' disabled') + '>' +
                    (mv.via === 'apply' ? 'Qo‘llash' : fixNow ? 'Joylash (darhol)' : 'So‘rov yuborish') + '</button> <button type="button" data-ag="unpick">Bekor</button></div></div>';
            }
            // O'qituvchi: to'qnashuvdagi dars (via = apply_fix) tanlangan toza joyga, faqat shu hafta / shu kun — so'rovsiz (server qayta tekshiradi).
            const agendaDirectFix = (mv, opt, pk) => Boolean(mv && mv.via === 'apply_fix' && opt && opt.ok && opt.fix && pk && pk.choice === 'one');
            // So'rov: haftalik — Takliflar "move" amallari (har hafta), sikl — kun boshlanishi (scope day | rest).
            function agendaApplyRequest(mv, opt, pick, reason) {
                // Darhol: admin (apply) yoki o'qituvchining to'qnashuvdagi darsi toza joyga (apply_fix — haftalik: week-suggestions/apply,
                // sikl: cycle-time-proposal — server har kunni o'zi ajratadi, sababsiz). Qolgani — so'rov (sabab bilan).
                const direct = mv.via === 'apply' || agendaDirectFix(mv, opt, pick);
                const withReason = b => (!direct ? Object.assign(b, { reason }) : b);
                if (mv.kind === 'weekly') {
                    const weeks = pick.choice === 'weeks' && (pick.items || []).length ? pick.items.map(Number)
                        : pick.choice === 'rest' && (mv.rest_weeks || []).length ? mv.rest_weeks : [mv.week];
                    const room = opt.room ? { auditorium_code: opt.room.code } : {};
                    // Dars yaxlit: ko'p bo'lakli amaliy dars (birlik) — barcha bo'laklari shu vaqtdan ketma-ket (har hafta).
                    const c0 = (typeof cards !== 'undefined' ? cards : []).find(x => x.id === +mv.card_id);
                    const pieces = w => {
                        if (!c0 || c0.training_type === 'lecture') return [[c0 ? c0.id : mv.card_id, 0]];
                        const list = unitOf(c0, w);
                        const at = list.indexOf(c0);
                        let off = -unitLen(list.slice(0, Math.max(0, at)));
                        return list.map(x => { const r = [x.id, off]; off += cardLen(x); return r; });
                    };
                    return { path: '/week-suggestions/' + (direct ? 'apply' : 'propose'), body: withReason({ week: mv.week, card_id: mv.card_id,
                        type: 'agenda', title: "O'qituvchi jadvalidan ko'chirish",
                        actions: weeks.flatMap(w => pieces(w).map(([id, off]) =>
                            Object.assign({ op: 'move', card_id: id, week: w, day: opt.day, pair: opt.pair + off }, room))) }) };
                }
                const u = mv.unit || {}, scope = pick.choice === 'block' ? 'rest' : 'day';
                const body = { specialty_name: u.specialty_name, course: u.course, subject_name: u.subject_name, group_name: u.group_name,
                    date: scope === 'rest' ? mv.block_date : pick.date, scope, start_hour: opt.start_hour };
                // Bir nechta kun: bitta yangi soat barcha tanlangan kunlarga (bitta so'rov; tasdiqda hammasi birga).
                if (pick.choice === 'days' && (pick.items || []).length) Object.assign(body, { dates: pick.items.slice().sort(), date: pick.items.slice().sort()[0], scope: 'day' });
                return mv.via === 'apply' ? { path: '/cycle-practice-starts', body: Object.assign(body, { units: [u.unit] }) }
                    : { path: '/cycle-time-proposal', body: withReason(body) };
            }
            async function agendaSubmit() {
                const st = ttAgenda, mv = st && st.data && st.data.move, pk = st && st.pick;
                const opt = mv && pk ? agendaOpt(mv, pk.date, pk.pair, pk.choice, pk.items) : null;
                // "Shu va keyingi haftalar" — faqat server keyingi haftalarni ham tasdiqlagan bo'lsa.
                const restBad = mv && pk && mv.kind === 'weekly' && pk.choice === 'rest'
                    && !(mv.rest && mv.rest.ok && mv.rest.date === pk.date && +mv.rest.pair === +pk.pair);
                if (!opt || !opt.ok || restBad || st.busy) return;
                let reason = '';
                if (mv.via !== 'apply' && !agendaDirectFix(mv, opt, pk)) {
                    reason = await askSugReason();
                    if (reason === null) { st.msg = { kind: 'err', text: "So'rov yuborilmadi: sabab kiritilmadi." }; agendaRender(false); return; }
                }
                const req = agendaApplyRequest(mv, opt, pk, reason);
                st.busy = true;
                agendaRender(false);
                try {
                    const r = await api(BASE + '/boards/' + board.id + req.path, 'POST', req.body);
                    // Jadval (yoki so'rovlar) o'zgardi — oldingi variantlar eskirdi.
                    agendaCacheClear();
                    const text = (r && r.message) || (mv.via === 'apply' ? 'Ko‘chirildi.' : 'So‘rov yuborildi.');
                    ttToast(esc(text) + (r && r.today_moved ? '<div class="tt-toast-sub" data-hemis-hint>' + esc(r.hemis_hint || TT_HEMIS_HINT) + '</div>' : ''), 'ok');
                    st.pick = null;
                    st.restFor = null;
                    st.selFor = null;
                    st.msg = { kind: 'ok', text };
                    try { await loadChangeRequests(); } catch (e) { /* so'rovlar ro'yxati — ixtiyoriy */ }
                    if (viewMode === 'cycle') await loadCyclePlan(); else await loadBoard(board.id);
                } catch (e) {
                    st.msg = { kind: 'err', text: 'Bajarilmadi (jadval o‘zgarmadi): ' + e.message };
                }
                st.busy = false;
                if (ttAgenda === st) await ttAgendaLoad();
            }
            // ===== Oynada sudrab ko'chirish (pointer; HTML5 DnD emas — oyna innerHTML bilan qayta chiziladi) =====
            // Ko'chirsa bo'ladigan dars (data-ag-drag) 5px dan ortiq siljisa — sudrash: shu dars uchun variantlar (teacher-agenda?move=)
            // oynani qayta chizmasdan olinadi; bo'sh paralar: yashil — ko'chiriladi, sariq — ogohlantirish / boshqa xona, qizil — yo'q.
            // Bo'sh paraga tashlansa — "Shu vaqtga ko'chirish" bosilgandek (tasdiq paneli); qizil / band katak — toast; Esc — bekor.
            let agDrag = null;   // { key, st, x, y, on, mv, wait, over }
            let agDragSuppress = false;
            function agendaPointerDown(ev) {
                const el = ev.button === 0 && ev.target.closest ? ev.target.closest('[data-ag-drag]') : null;
                if (!el || !ttAgenda || ttAgenda.busy) return;
                clearTimeout(agHoverTimer);
                // Yangi sudrash kutilayotgan tashlashning o'rnini egallaydi.
                agendaPendingCancel(true);
                agDrag = { key: el.dataset.agDrag, st: ttAgenda, x: ev.clientX, y: ev.clientY, on: false, mv: null, wait: false, over: null };
                document.addEventListener('pointermove', agendaPointerMove, true);
                document.addEventListener('pointerup', agendaPointerUp, true);
            }
            function agendaDragTip(text, tone, ev, spin) {
                let tip = document.getElementById('agDragTip');
                if (!tip) { tip = document.createElement('div'); tip.id = 'agDragTip'; document.body.appendChild(tip); }
                tip.className = tone || '';
                // Kutish — aylanuvchi belgi bilan.
                if (spin) tip.innerHTML = '<span class="ag-spin"></span>' + esc(text); else tip.textContent = text;
                tip.style.left = Math.min(window.innerWidth - tip.offsetWidth - 8, ev.clientX + 14) + 'px';
                tip.style.top = (ev.clientY + 16) + 'px';
            }
            // Bo'sh para varianti: holati (ok | warn | bad) va sababi.
            function agendaDropState(mv, date, pair) {
                const opt = mv ? agendaOpt(mv, date, pair, 'one') : null;
                if (!opt) return { tone: 'bad', why: mv && mv.why ? mv.why : (mv && mv.kind === 'cycle' ? 'sikl darsi — kun o‘zgarmaydi' : 'bu kunga ko‘chirib bo‘lmaydi'), opt: null };
                if (!opt.ok) return { tone: 'bad', why: opt.why || 'ko‘chirib bo‘lmaydi', opt };
                const room = opt.room ? 'bo‘sh xona: ' + opt.room.name : '';
                return { tone: opt.why || opt.room ? 'warn' : 'ok', why: [opt.why, room].filter(Boolean).join(' · '), opt };
            }
            // Sudrash (yoki kutilayotgan tashlash) uchun variantlar: oyna qayta chizilmaydi — faqat ko'chirish variantlari (keyingi chizishda
            // "ko'chiriladi" belgisi bilan). Keshda bo'lsa (oldindan yuklangan) — darhol.
            const agendaDragAdopt = (st, key, mv) => { st.move = key; st.pick = null; st.restFor = null; st.selFor = null; if (st.data) st.data.move = mv; };
            async function agendaDragFetch(d) {
                const st = d.st;
                const cur = st.data && st.data.move;
                if (st.move === d.key && cur && cur.key === d.key && !cur.loading) { d.mv = cur; return; }
                const hit = agMoveCache.get(agCk(st, d.key));
                if (hit && hit.mv) { agendaDragAdopt(st, d.key, hit.mv); d.mv = hit.mv; return; }
                d.wait = true;
                let mv;
                try {
                    mv = await agendaMoveGet(st, d.key, true);
                } catch (e) {
                    mv = { why: e.message, options: {}, block: {}, failed: true };
                }
                d.wait = false;
                if (ttAgenda !== st) return;
                const pending = agPending && agPending.d === d;
                if (!mv.failed && (agDrag === d || pending)) agendaDragAdopt(st, d.key, mv);
                d.mv = mv;
                if (agDrag === d && d.lastEv) agendaDragPaint(d.lastEv);
                if (pending) agendaPendingDone(mv);
            }
            // Tashlash natijasi (javob bor): qizil — sababi bilan toast; aks holda "Shu vaqtga ko'chirish" bosilgandek — tanlov paneli (haftalik —
            // shu / keyingi haftalar, sikl — shu kun / butun blok).
            function agendaDropApply(st, key, mv, date, pair) {
                const r = agendaDropState(mv, date, +pair);
                if (r.tone === 'bad') { ttToast('Ko‘chirib bo‘lmaydi: ' + esc(r.why), 'warn'); agendaRender(false); return; }
                st.move = key;
                if (st.data) st.data.move = mv;
                st.pick = { date, pair: +pair, choice: 'one' };
                st.selFor = null;
                if (mv.kind === 'weekly' && (mv.rest_weeks || []).length > 1) { st.restFor = date + '|' + pair; ttAgendaLoad(); }
                else { st.restFor = null; agendaRender(false); }
            }
            // Kutilayotgan tashlash: javob keldi — davom etadi; xato yoki vaqt tugasa — sababi bilan toast, katakdagi belgi o'chadi.
            function agendaPendingDone(mv) {
                const p = agPending;
                agPending = null;
                if (!p || ttAgenda !== p.st) return;
                if (mv.failed) { ttToast('Tekshirib bo‘lmadi: ' + esc(mv.why || 'server javob bermadi'), 'warn'); agendaRender(false); return; }
                agendaDropApply(p.st, p.key, mv, p.date, p.pair);
            }
            // Kutilayotgan tashlashni bekor qilish (Esc, yangi sudrash yoki tanlash, sana almashishi). dom = true — oynani qayta chizmasdan belgini olib tashlash
            // (pointerdown paytida — sudralayotgan element o'z joyida qolsin).
            function agendaPendingCancel(dom) {
                if (!agPending) return false;
                agPending = null;
                const m = document.getElementById('ttAgendaModal');
                if (dom && m) {
                    m.querySelectorAll('.ag-free.is-pending').forEach(c => c.classList.remove('is-pending'));
                    m.querySelectorAll('.ag-pend').forEach(x => x.remove());
                } else if (ttAgenda) agendaRender(false);
                return true;
            }
            // Sichqoncha ko'chirsa bo'ladigan dars ustiga kelsa (150 ms) — shu dars variantlari oldindan (sudrash paytida — yo'q).
            function agendaHover(ev) {
                const el = ev.target && ev.target.closest ? ev.target.closest('[data-ag-drag]') : null;
                if (!el || (ev.relatedTarget && el.contains(ev.relatedTarget))) return;
                clearTimeout(agHoverTimer);
                const st = ttAgenda, key = el.dataset.agDrag;
                if (!st || agDrag || st.busy) return;
                agHoverTimer = setTimeout(() => { if (ttAgenda === st && !agDrag) agendaPrefetch(st, key); }, 150);
            }
            function agendaHoverOut(ev) {
                const el = ev.target && ev.target.closest ? ev.target.closest('[data-ag-drag]') : null;
                if (el && !(ev.relatedTarget && el.contains(ev.relatedTarget))) clearTimeout(agHoverTimer);
            }
            // Darsni bosish — uni "ko'chiriladigan dars" qilib tanlaydi: keshda bo'lsa — darhol, bo'lmasa — "tekshirilmoqda…" (javob kelguncha).
            function agendaSelect(st, key) {
                agendaPendingCancel(true);
                const cur = st.data && st.data.move;
                if (st.move === key && cur && cur.key === key && !cur.loading) return;
                st.move = key; st.pick = null; st.restFor = null; st.selFor = null; st.msg = null;
                const hit = agMoveCache.get(agCk(st, key));
                if (hit && hit.mv) { if (st.data) st.data.move = hit.mv; agendaRender(false); return; }
                const e = ((st.data && st.data.entries) || []).find(x => x.key === key);
                if (st.data) st.data.move = { key, loading: true, label: e ? (e.label || e.subject + ' (' + e.type + ') — ' + (e.groups || []).join(', ')) : '',
                    date: e ? e.date : null, options: {}, block: {} };
                agendaRender(false);
                agendaMoveGet(st, key, true).then(mv => {
                    if (ttAgenda !== st || st.move !== key || !st.data) return;
                    st.data.move = mv;
                    agendaRender(false);
                }, err => {
                    if (ttAgenda !== st || st.move !== key || !st.data) return;
                    st.data.move = { key, why: err.message, options: {}, block: {} };
                    agendaRender(false);
                });
            }
            function agendaDragPaint(ev) {
                const d = agDrag, m = document.getElementById('ttAgendaModal');
                if (!d || !m) return;
                d.lastEv = { clientX: ev.clientX, clientY: ev.clientY };
                m.classList.add('is-ag-dragging');
                const cell = (document.elementFromPoint(ev.clientX, ev.clientY) || m).closest('[data-ag-free]');
                d.over = cell ? cell.dataset.agFree : null;
                m.querySelectorAll('[data-ag-free]').forEach(c => {
                    c.classList.remove('is-ok', 'is-warn', 'is-bad', 'is-over');
                    if (d.wait || !d.mv) return;
                    const [date, pair] = c.dataset.agFree.split('|');
                    c.classList.add('is-' + agendaDropState(d.mv, date, +pair).tone);
                    if (c === cell) c.classList.add('is-over');
                });
                const label = (d.mv && d.mv.label ? d.mv.label.split(' — ')[0] : 'Dars');
                if (d.wait || !d.mv) { agendaDragTip(label + ': tekshirilmoqda…', 'is-wait', ev, true); return; }
                if (!cell) { agendaDragTip(label + ' → bo‘sh paraga tashlang', d.mv.why ? 'is-bad' : 'is-wait', ev); return; }
                const [date, pair] = cell.dataset.agFree.split('|');
                const p = ((ttAgenda.data && ttAgenda.data.pairs) || []).find(x => x.no === +pair) || {};
                const r = agendaDropState(d.mv, date, +pair);
                const how = r.tone === 'bad' ? r.why : (agendaDirectFix(d.mv, r.opt, { choice: 'one' }) ? 'so‘rovsiz joylanadi'
                    : d.mv.via === 'apply' ? 'ko‘chiriladi' : 'so‘rov yuboriladi') + (r.why ? ' (' + r.why + ')' : '');
                agendaDragTip(label + ' → ' + cfDate(date) + ' ' + (p.label || '') + ': ' + how, r.tone === 'ok' ? '' : 'is-' + r.tone, ev);
            }
            function agendaPointerMove(ev) {
                const d = agDrag;
                if (!d) return;
                if (!d.on) {
                    if (Math.abs(ev.clientX - d.x) + Math.abs(ev.clientY - d.y) <= 5) return;
                    d.on = true;
                    agendaDragFetch(d);
                }
                ev.preventDefault();
                agendaDragPaint(ev);
            }
            function agendaPointerUp(ev) {
                const d = agDrag;
                if (!d) return;
                if (d.on) { ev.preventDefault(); agDragSuppress = true; setTimeout(() => { agDragSuppress = false; }, 0); }
                agendaDragEnd(d.on ? ev : null);
            }
            // Sudrash tugadi: ev — tashlash (null — bekor / oddiy bosish).
            function agendaDragEnd(ev) {
                const d = agDrag;
                agDrag = null;
                document.removeEventListener('pointermove', agendaPointerMove, true);
                document.removeEventListener('pointerup', agendaPointerUp, true);
                const tip = document.getElementById('agDragTip');
                if (tip) tip.remove();
                const m = document.getElementById('ttAgendaModal');
                if (m) {
                    m.classList.remove('is-ag-dragging');
                    m.querySelectorAll('[data-ag-free]').forEach(c => c.classList.remove('is-ok', 'is-warn', 'is-bad', 'is-over'));
                }
                if (!d || !ev || ttAgenda !== d.st) return;
                const target = document.elementFromPoint(ev.clientX, ev.clientY);
                const cell = target && target.closest ? target.closest('[data-ag-free]') : null;
                if (!cell) {
                    if (target && target.closest && target.closest('#ttAgendaModal td')) ttToast('Bu para band — bo‘sh paraga tashlang.', 'warn');
                    return;
                }
                const [date, pair] = cell.dataset.agFree.split('|');
                if (d.wait || !d.mv) {
                    // Javob hali kelmagan: katak eslab qolinadi ("tekshirilmoqda…") — javob kelgach avtomatik davom etadi (agendaDragFetch).
                    agPending = { d, st: d.st, key: d.key, date, pair: +pair };
                    agendaRender(false);
                    return;
                }
                agendaDropApply(d.st, d.key, d.mv, date, +pair);
            }
            function agendaClick(e) {
                const st = ttAgenda;
                if (!st) return;
                if (agDragSuppress) { e.preventDefault(); e.stopPropagation(); return; }
                if (e.target === e.currentTarget) { ttAgendaClose(); return; }
                const t = e.target.closest ? e.target : null;
                // Mobil (tooltip yo'q): ko'chirilmaydigan darsni bosish — to'liq matn ochiladi / yopiladi.
                const tipEl = t && t.closest('[data-ag-tip]');
                if (tipEl && !tipEl.hasAttribute('data-ag-drag')) { tipEl.classList.toggle('ag-open'); return; }
                const pick = t && t.closest('[data-ag-pick]');
                if (pick && !pick.disabled) {
                    const [date, pair] = pick.dataset.agPick.split('|');
                    st.pick = { date, pair: +pair, choice: 'one' };
                    st.selFor = null;
                    const mv = st.data && st.data.move;
                    // Haftalik dars, keyingi haftalar bor — tanlangan para keyingi haftalarda ham tekshiriladi (server).
                    if (mv && mv.kind === 'weekly' && (mv.rest_weeks || []).length > 1) { st.restFor = date + '|' + pair; ttAgendaLoad(); }
                    else agendaRender(false);
                    return;
                }
                // Ko'chirsa bo'ladigan dars kartochkasini bosish — uni ko'chiriladigan dars qilib tanlaydi (ichidagi havola / tugma — o'z ishini qiladi).
                const card = t && t.closest('[data-ag-drag]');
                if (card && !t.closest('a, button, input, select, textarea, label')) { agendaSelect(st, card.dataset.agDrag); return; }
                const ch = t && t.closest('input[name="agChoice"]');
                if (ch && st.pick) {
                    st.pick.choice = ch.value;
                    const mv = st.data && st.data.move;
                    // Bir nechta hafta / kun: boshlang'ich tanlov — shu hafta / shu kun.
                    if (ch.value === 'weeks' || ch.value === 'days') {
                        st.pick.items = st.pick.items && st.pick.items.length ? st.pick.items
                            : [ch.value === 'weeks' ? mv.week : ((mv.block_days || []).some(x => x.date === st.pick.date) ? st.pick.date : ((mv.block_days || [])[0] || {}).date)].filter(Boolean);
                        agendaSelCheck(st);
                    } else agendaRender(false);
                    return;
                }
                const it = t && t.closest('input[data-ag-item]');
                if (it && st.pick) {
                    const v = st.pick.choice === 'weeks' ? +it.dataset.agItem : it.dataset.agItem;
                    const set = new Set(st.pick.items || []);
                    if (it.checked) set.add(v); else set.delete(v);
                    st.pick.items = [...set].sort((a, b) => a < b ? -1 : a > b ? 1 : 0);
                    agendaSelCheck(st);
                    return;
                }
                const b = t && t.closest('[data-ag]');
                if (!b) return;
                const a = b.dataset.ag;
                if (a === 'close') ttAgendaClose();
                // Sana yoki kun/hafta almashdi: kutilayotgan tashlash bekor, variantlar keshi tozalanadi.
                else if (a === 'day' || a === 'week') { agendaPendingCancel(true); agendaCacheClear(); st.range = a; st.pick = null; st.restFor = null; st.selFor = null; ttAgendaLoad(); }
                else if (a === 'prev' || a === 'next') { agendaPendingCancel(true); agendaCacheClear(); st.date = agendaStep(st.date, st.range, a === 'next' ? 1 : -1); st.pick = null; st.restFor = null; st.selFor = null; st.msg = null; ttAgendaLoad(); }
                else if (a === 'unpick') { st.pick = null; st.restFor = null; st.selFor = null; agendaRender(false); }
                else if (a === 'submit') agendaSubmit();
            }

            // "Ko'rsatish" havolasi bosilganda (capture — karta/qator tanlash ishlovchilariga o'tmaydi); fokus — ttFocusStart (pastda).
            document.addEventListener('click', ev => {
                const a = ev.target && ev.target.closest ? ev.target.closest('[data-focus]') : null;
                if (!a) return;
                ev.preventDefault();
                ev.stopPropagation();
                let show = null;
                try { show = JSON.parse(a.dataset.focus); } catch (e) { return; }
                ttFocusStart(show);
            }, true);
            // ===== To'qnashuvlar: qisqa belgi, rang, bir qatorli tafsilot (server — tuzilgan ro'yxat, ko'rish qamrovi bo'yicha) =====
            // room_lectures — bir zalda bir vaqtda ikki xil ma'ruza (bitta oqim emas). Ro'yxatda yo'q tur — umumiy o'zbekcha nom
            // (xom kalit hech qayerda ko'rinmaydi).
            const CF_LABEL = { teacher_busy: "O'qituvchi band", group_busy: 'Guruh band', lecture_overlap: "Ma'ruza bilan ustma-ust",
                room_capacity: "Xona sig'maydi", room_busy: 'Xona band', room_lectures: "Zal bir vaqtda ikki ma'ruzaga" };
            const cfLabel = kind => CF_LABEL[kind] || "To'qnashuv";
            const CF_TODO = { teacher_busy: "boshqa vaqt yoki o'qituvchi tanlang", group_busy: 'darsni boshqa vaqtga suring',
                lecture_overlap: "amaliyot vaqtini ma'ruzadan keyinga suring", room_capacity: 'kattaroq xona tanlang', room_busy: 'boshqa xona tanlang',
                room_lectures: "bitta ma'ruza oqimiga birlashtiring yoki boshqa zal tanlang" };
            const cfLive = items => (items || []).filter(i => !i.past);
            const cfKindLevel = kind => (kind === 'teacher_busy' || kind === 'group_busy' || kind === 'lecture_overlap') ? 'red' : 'yellow';
            // Rang: qizil — o'qituvchi yoki guruh ikki joyda; sariq — faqat xona; hammasi o'tgan — kulrang (past); yo'q — null.
            function cfLevel(items) {
                const live = cfLive(items);
                if (!live.length) return (items || []).length ? 'past' : null;
                return live.some(i => cfKindLevel(i.kind) === 'red') ? 'red' : 'yellow';
            }
            // Kartadagi qisqa belgi: "O'qituvchi band (2) · Xona sig'maydi (1)"; faqat o'tganlari — "o'tgan".
            function cfBadgeText(items) {
                const live = cfLive(items);
                if (!live.length) return (items || []).length ? 'o\u2018tgan' : '';
                const n = {};
                cfMergeItems(live).forEach(i => { const l = cfLabel(i.kind); n[l] = (n[l] || 0) + 1; });   // tafsilot oynasidagi qatorlar soni
                // Tartib — CF_LABEL bo'yicha, noma'lum turlar ("To'qnashuv") oxirida.
                const order = Object.values(CF_LABEL), at = l => (order.includes(l) ? order.indexOf(l) : order.length);
                return Object.keys(n).sort((x, y) => at(x) - at(y)).map(l => l + ' (' + n[l] + ')').join(' · ');
            }
            // Uzun guruh ro'yxati: avval 4 tasi, umumiy boshi ("d1/d22-") takrorlanmaydi; qolgani "… (N guruh)":
            // "d1/d22-01a, 01b, 01c, 02a … (12 guruh)".
            function cfGroups(list) {
                const g = list || [];
                let prefix = null;
                const shown = g.slice(0, 4).map(name => {
                    const s = String(name);
                    if (prefix !== null && s.startsWith(prefix) && s.length > prefix.length) return s.slice(prefix.length);
                    const cut = s.lastIndexOf('-');
                    prefix = cut > 0 ? s.slice(0, cut + 1) : null;
                    return s;
                });
                return shown.join(', ') + (g.length > 4 ? ' … (' + g.length + ' guruh)' : '');
            }
            // Xona sig'imi (room_capacity): "65 o'rin, 98 talaba (+33)"; raqamlar yo'q — bo'sh.
            const cfCapText = i => (+i.volume > 0 && +i.students > 0
                ? i.volume + " o'rin, " + i.students + ' talaba (+' + (i.over != null ? i.over : i.students - i.volume) + ')' : '');
            const cfDate = d => String(d || '').split('-').reverse().slice(0, 2).join('.');
            const cfWhen = i => i.dates || (i.date_from ? cfDate(i.date_from) + (i.date_to && i.date_to !== i.date_from ? '–' + cfDate(i.date_to) : '') : '');
            // Kim / nima: sikl — who; haftalik — o'qituvchi yoki xona.
            const cfWho = i => i.who !== undefined ? i.who : (i.type === 'teacher' ? i.teacher_name : i.type === 'room' ? i.room : (i.teacher_name || i.room));
            // "O'qituvchi band": o'qituvchi nomi — kun/hafta jadvali oynasi havolasi (to'qnashuv sanasi; move — ko'chiriladigan dars
            // kaliti, oynada ko'k ramka). teacher_id yoki sana yo'q — oddiy matn.
            function agendaLinkHtml(a, label) {
                const text = label || (a && a.teacher_name) || "O'qituvchi jadvali";
                if (!a || !(+a.teacher_id > 0) || !a.date) return esc(text);
                const info = { teacher_id: +a.teacher_id, teacher_name: a.teacher_name || '', date: String(a.date).slice(0, 10), move: a.move || null };
                return '<a href="#" class="tt-agenda-link" data-agenda="' + esc(JSON.stringify(info)) + '" title="O\'qituvchi kun jadvali va bo\'sh paralar">' +
                    esc(text) + '</a>';
            }
            // Ro'yxatdagi "O'qituvchi band" yozuvlari (biriktirish ogohlantirishi, Takliflar, "Ko'rsatish" ma'lumoti) — har o'qituvchi
            // va sana uchun bitta havola: "📅 MUXAMMADIYEV S. B. jadvali, 19.11".
            function agendaLinksHtml(list, move) {
                const seen = new Set(), out = [];
                (list || []).forEach(x => {
                    if (!x || x.kind !== 'teacher_busy' || !(+x.teacher_id > 0)) return;
                    const date = x.date_from || (x.dates || [])[0] || x.date || null;
                    const k = x.teacher_id + '|' + date;
                    if (!date || seen.has(k)) return;
                    seen.add(k);
                    out.push(agendaLinkHtml({ teacher_id: x.teacher_id, teacher_name: x.teacher_name, date, move },
                        '📅 ' + (x.teacher_name || "O'qituvchi") + ' jadvali, ' + cfDate(date)));
                });
                return out.length ? ' ' + out.join(' ') : '';
            }
            // Bir xil turdagi va bir xil xona / o'qituvchi / guruhdagi yozuvlar (server har sana yoki boshqa guruhcha uchun alohida beradi:
            // "Xona sig'maydi" 6 marta) — bitta qator: guruhlar va sanalar birlashadi; "Ko'rsatish" — barcha guruhlar, kartalar, to'liq
            // sana va soat oralig'i. O'tgan va kelgusi alohida (o'tgani kulrang), ma'ruza va amaliy alohida (ko'rsatma har xil).
            function cfMergeItems(items) {
                const out = [], byKey = {};
                (items || []).forEach(i => {
                    const k = [i.kind, i.type || '', cfWho(i) ?? '', i.lecture ? 'L' : 'P', i.past ? 1 : 0].join('|');
                    const when = cfWhen(i), at = i.date_from || i.from || '';
                    const m = byKey[k];
                    if (!m) {
                        byKey[k] = { item: Object.assign({}, i, { groups: (i.groups || []).slice() }), when: when ? [[at, when]] : [] };
                        out.push(byKey[k]);
                        return;
                    }
                    (i.groups || []).forEach(g => { if (!m.item.groups.includes(g)) m.item.groups.push(g); });
                    if (when && !m.when.some(w => w[1] === when)) m.when.push([at, when]);
                    // Xona sig'imi: har sana oralig'ining talabalari — eng kattasi ko'rsatiladi.
                    if (+i.students > (+m.item.students || 0)) {
                        Object.assign(m.item, { volume: i.volume, students: i.students, over: i.over, room_name: i.room_name, room_code: i.room_code });
                    }
                    m.item.show = cfMergeShow(m.item.show, i.show);
                });
                return out.map(m => (m.when.length > 1
                    ? Object.assign(m.item, { dates: m.when.sort((a, b) => String(a[0]).localeCompare(String(b[0]))).map(w => w[1]).join(', ') })
                    : m.item));
            }
            function cfMergeShow(a, b) {
                if (!a || !b) return a || b || null;
                const gk = g => [g.faculty, g.specialty, +g.course, g.group].map(v => String(v ?? '').trim().toLowerCase()).join('|');
                const seen = new Set((a.groups || []).map(gk));
                const groups = (a.groups || []).concat((b.groups || []).filter(g => !seen.has(gk(g)) && seen.add(gk(g))));
                const ds = [...(a.dates || []), ...(b.dates || [])].filter(Boolean).sort();
                const lo = (x, y) => (x == null ? y : y == null ? x : Math.min(x, y)), hi = (x, y) => (x == null ? y : y == null ? x : Math.max(x, y));
                return Object.assign({}, a, { groups, card_ids: [...new Set([...(a.card_ids || []), ...(b.card_ids || [])].map(Number))],
                    dates: ds.length ? [ds[0], ds[ds.length - 1]] : [], hour_from: lo(a.hour_from, b.hour_from), hour_to: hi(a.hour_to, b.hour_to) });
            }
            // Bir qator: kim/nima to'qnashdi, qaysi sanalarda, nima qilish kerak (o'tgan — kulrang).
            function cfLineHtml(i, ctx = {}) {
                const when = cfWhen(i);
                // Kim / nima (+ guruhlar 3 ta, "+N ta"); hech biri yo'q — server matni.
                const who = cfWho(i);
                const cap = cfCapText(i);
                // O'qituvchi band — nomi kun jadvali havolasi (ctx.move — ko'chiriladigan dars).
                const whoHtml = who && i.kind === 'teacher_busy' && +i.teacher_id > 0
                    ? agendaLinkHtml({ teacher_id: i.teacher_id, teacher_name: i.teacher_name || who,
                        date: i.date_from || ((i.show || {}).dates || [])[0] || i.from, move: ctx.move }, who)
                    : esc(who || '');
                const body = (who !== undefined && who !== null) || (i.groups || []).length
                    ? (who ? ' ' + whoHtml : '') + (cap ? ' — <span class="cf-cap">' + esc(cap) + '</span>' : '') +
                        ((i.groups || []).length ? ' — ' + esc(cfGroups(i.groups)) : '')
                    : ' ' + esc(String(i.detail || '').replace(/^[^:]*:\s*/, ''));
                return '<li class="cf-line cf-' + (i.past ? 'past' : cfKindLevel(i.kind)) + '"' + (ctx.idx != null ? ' data-cf-i="' + ctx.idx + '"' : '') + '><b>' + esc(cfLabel(i.kind)) + ':</b>' + body +
                    (when ? ', ' + esc(when) : '') + (i.past ? ' <span class="cf-past-tag">o\u2018tgan</span>'
                        : ' <span class="cf-todo">→ ' + esc(i.todo || CF_TODO[i.kind] || '') + '</span>') + focusLinkHtml(i.show) + '</li>';
            }
            // Oqim ma'ruzasi to'qnashuvi guruhcha kartalarida takrorlanmaydi: birinchi (egasi) blokda to'liq, qolganlarida — havola.
            function cfLectureOwners(rows) {
                const owner = {};
                (rows || []).forEach(row => (row.blocks || []).forEach(b => (b.conflicts || []).forEach(i => {
                    if (i.lecture && i.lecture_id && !owner[i.lecture_id]) owner[i.lecture_id] = b.key;
                })));
                return owner;
            }
            // Guruhchalarning joylashuvi / ma'ruza soati har xil bo'lsa, bitta ma'ruzaning to'qnashuvlari ham har xil: egasi blokiga
            // boshqa bloklardagi farqli bandlar qo'shiladi (aks holda "ma'ruzada muammo bor ↗" egasidagi boshqa bandni ko'rsatardi).
            function cfMergeLectureItems(rows, owner) {
                const byKey = {};
                (rows || []).forEach(r => (r.blocks || []).forEach(b => { byKey[b.key] = b; }));
                (rows || []).forEach(r => (r.blocks || []).forEach(b => (b.conflicts || []).forEach(i => {
                    const ok = i.lecture && i.lecture_id ? owner[i.lecture_id] : null;
                    const target = ok && ok !== b.key ? byKey[ok] : null;
                    if (!target) return;
                    const sig = x => [x.kind, x.line || x.detail || '', x.past ? 1 : 0].join('|');
                    if (!(target.conflicts || []).some(x => sig(x) === sig(i))) target.conflicts = (target.conflicts || []).concat([i]);
                })));
            }
            function cfSplit(key, items, owner) {
                const own = (items || []).filter(i => !i.lecture || !i.lecture_id || owner[i.lecture_id] === key);
                const elsewhere = [...new Set((items || []).filter(i => i.lecture && i.lecture_id && owner[i.lecture_id] !== key && !i.past)
                    .map(i => i.lecture_id))];
                return { own, elsewhere };
            }
            // Blokdagi belgi (qisqa) va "ma'ruzada muammo bor ↗" havolasi; tafsilot — bosilganda.
            function cfBadgeHtml(key, items, owner) {
                const { own, elsewhere } = cfSplit(key, items, owner);
                const lvl = cfLevel(own);
                return (lvl ? '<span class="cyc-conflict-badge lvl-' + lvl + '" role="button" tabindex="0" data-cf-key="' + esc(key) + '" title="Bosing — tafsilot">' +
                        esc(cfBadgeText(own)) + '</span>' : '') +
                    elsewhere.map(id => '<span class="cf-lecture-link" role="button" tabindex="0" data-cf-lecture="' + id + '" title="Oqim ma\'ruzasi to\'qnashuvi — bir marta, ma\'ruza egasi blokida">ma\'ruzada muammo bor ↗</span>').join('');
            }
            function cfBlockClass(key, items, owner) {
                const lvl = cfLevel(cfSplit(key, items, owner).own);
                return lvl === 'red' ? ' is-conflict' : lvl === 'yellow' ? ' is-conflict-warn' : lvl === 'past' ? ' is-conflict-past' : '';
            }
            // Sikl paneli yig'indisi: kelgusi to'qnashuvlar turlari bo'yicha (oqim ma'ruzasi — bir marta).
            function cfSummaryCounts(cards) {
                const seen = new Set(), n = { teacher: 0, room: 0 };
                (cards || []).forEach(c => cfLive(c.conflicts).forEach(i => {
                    const k = i.lecture && i.lecture_id ? 'L' + i.lecture_id + '|' + i.kind + '|' + i.who : c.key + '|' + i.kind + '|' + i.who + '|' + (i.groups || []).join(',');
                    if (seen.has(k)) return;
                    seen.add(k);
                    n[cfKindLevel(i.kind) === 'red' ? 'teacher' : 'room']++;
                }));
                return n;
            }
            const cfMatchesFilter = (card, f) => !f || cfLive(card.conflicts).some(i => (cfKindLevel(i.kind) === 'red' ? 'teacher' : 'room') === f);

            // ===== "Ko'rsatish": to'qnashuvni jadvalda ko'rsatish =====
            // Server har to'qnashuv matni bilan birga tuzilgan ma'lumot (show) beradi — matn parse qilinmaydi: kind, teacher_id /
            // room_code, groups [{group, faculty, specialty, course}], subject, dates [from, to], hour_from / hour_to, card_ids,
            // view (week — haftalik jadval, cycle — sikl jadvali), week. Bosilganda: guruh filtri vaqtincha shu guruhlarga (boshqa
            // fakultet/yo'nalish/kursda bo'lsa — qamrov ham vaqtincha kengayadi), to'qnashuv kunlari/paralari qizil ramka, birinchisiga
            // scroll, tepada lenta; "Yopish" oldingi ko'rinish, hafta, qamrov va filtrni tiklaydi.
            const focusNorm = v => String(v ?? '').trim().toLowerCase();
            const focusGKey = g => focusNorm(g.faculty) + '|' + focusNorm(g.specialty) + '|' + (+g.course || 0) + '|' + focusNorm(g.group);
            const focusSplit = name => String(name || '').split(/\s*\+\s*/u).map(x => x.trim()).filter(Boolean);
            let focusHave = { src: null, set: null };
            // Ko'rish huquqi: "Butun doska" — barcha guruhlar (cheklangan rolga ham server shu qamrovni beradi); "Faqat meniki" /
            // "Mas'ul fanlarim" / "Kafedraniki" — faqat yuklangan qamrovdagi (cards) guruhlar. Qolganlari faqat matnda qoladi.
            function focusVisibleGroups(show) {
                const groups = (show && show.groups) || [];
                if (scopeMode === 'all') return groups.slice();
                if (focusHave.src !== cards) {
                    const set = new Set();
                    cards.forEach(c => cardGroups(c).forEach(g => focusSplit(g).forEach(n =>
                        set.add(focusGKey({ group: n, faculty: c.faculty_name, specialty: c.specialty_name, course: c.course })))));
                    focusHave = { src: cards, set };
                }
                return groups.filter(g => focusHave.set.has(focusGKey(g)));
            }
            // Havola: ko'rinadigan guruh bo'lmasa — yo'q (to'qnashuv matni o'zgarmaydi).
            function focusLinkHtml(show, label) {
                if (!show || !(show.groups || []).length) return '';
                const vis = focusVisibleGroups(show);
                if (!vis.length) return '';
                return '<a href="#" class="cf-show" data-focus="' + esc(JSON.stringify(show)) + '" title="Jadvalda ko\'rsatish: ' +
                    esc(vis.map(g => g.group).join(', ')) + '">' + esc(label || 'Ko\'rsatish') + '</a>';
            }
            // Bir nechta to'qnashuv (biriktirish ogohlantirishi, Takliflar): har biriga — "Ko'rsatish: guruhlar, sanalar".
            function focusLinksHtml(list) {
                const items = (list || []).filter(x => x && (x.groups || []).length);
                if (items.length < 2) return items.length ? ' ' + focusLinkHtml(items[0]) : '';
                return ' ' + items.map(x => focusLinkHtml(x, 'Ko\'rsatish: ' + focusVisibleGroups(x).map(g => g.group).join(', ') +
                    (x.dates && x.dates.length ? ', ' + focusDatesText(x.dates) : ''))).filter(Boolean).join(' ');
            }
            // "13–24.11", oylar har xil — "28.10–03.11", bitta kun — "15.09".
            function focusDatesText(d) {
                const a = (d || [])[0], b = (d || [])[1] || a;
                if (!a) return '';
                const dm = x => String(x).slice(8, 10) + '.' + String(x).slice(5, 7);
                if (b === a) return dm(a);
                return String(a).slice(0, 7) === String(b).slice(0, 7) ? String(a).slice(8, 10) + '–' + dm(b) : dm(a) + '–' + dm(b);
            }
            // Boshlanish vaqti: hour_unit "row" — qo'ng'iroq jadvalidagi qator raqami (haftalik dars); "hour" — kunning akademik
            // soati (sikl darsi): to'liq (80–90 daqiqalik) parada bir qatorda ikki soat — cycHourTimes() bo'yicha.
            function focusTimeText(show) {
                const h = +show.hour_from || 0;
                if (show.hour_unit === 'hour') { const t = cycHourTimes()[h]; return t ? t[0] : ''; }
                const it = boardSchedule().filter(x => x.type === 'pair')[h - 1];
                return it && it.start ? it.start : '';
            }
            // "To'qnashuvni ko'rish: O'qituvchi X — d1/d22-01a va d1/d22-01b, 13–24.11, 08:30" (xona — NOMI: "Xona 123-amaliyot xonasi — …").
            function focusBannerText(show, groups) {
                const who = show.kind === 'teacher_busy' ? "O'qituvchi " + (show.teacher_name || '')
                    : (show.kind === 'room_busy' || show.kind === 'room_capacity') ? 'Xona ' + (show.room_name || show.room_code || '') : (CF_LABEL[show.kind] || "To'qnashuv");
                const names = (groups || []).map(g => g.group);
                const list = names.length > 1 ? names.slice(0, -1).join(', ') + ' va ' + names[names.length - 1] : (names[0] || '');
                return "To'qnashuvni ko'rish: " + [who.trim() + (list ? ' — ' + list : ''), focusDatesText(show.dates), focusTimeText(show)]
                    .filter(Boolean).join(', ');
            }
            function renderFocusBar() {
                let bar = document.getElementById('ttFocusBar');
                if (!ttFocus) { if (bar) bar.remove(); return; }
                if (!bar) {
                    bar = document.createElement('div');
                    bar.id = 'ttFocusBar';
                    $('mainArea').insertBefore(bar, $('mainArea').firstChild);
                }
                const sh = ttFocus.show || {};
                bar.innerHTML = '<span>' + esc(focusBannerText(ttFocus.show, ttFocus.groups)) + '</span><span>·</span>' +
                    // O'qituvchi band — shu kundagi jadvali (bo'sh paralar, ko'chirish).
                    (sh.kind === 'teacher_busy' && +sh.teacher_id > 0 && (sh.dates || [])[0]
                        ? agendaLinkHtml({ teacher_id: sh.teacher_id, teacher_name: sh.teacher_name, date: sh.dates[0] }, "O'qituvchi jadvali") + '<span>·</span>' : '') +
                    '<button type="button" id="ttFocusClose">Yopish</button>';
                bar.querySelector('#ttFocusClose').onclick = ttFocusClose;
            }
            // Sikl jadvali: to'qnashuvdagi guruhlar qatorlari (guruh qatori, oqim qatori yoki bo'lak qatori — "Fan (a)" — a'zolari
            // orasida; qamrovi bilan). Bo'lak qatorlari ham tanlovda: ularning bloklari ham qizil ramka oladi, faqat bo'lakda
            // qatnashgan guruh bo'lsa ham filtr bo'sh qolmaydi.
            function focusCycleRowKeys(allRows) {
                const keys = ttFocus ? ttFocus.keys : new Set();
                return (allRows || []).filter(r => [r.group, ...(r.subgroups || [])].flatMap(focusSplit)
                    .some(n => keys.has(focusGKey({ group: n, faculty: r.faculty, specialty: r.specialty, course: r.course }))))
                    .map(r => r.row_key);
            }
            // Haftalik jadval ustunlari (guruhlar): fokusda — faqat to'qnashuvdagi guruhlar.
            function focusWeekColumns(rows) {
                if (!ttFocus || ttFocus.show.view === 'cycle') return rows;
                return rows.filter(r => focusSplit(r.group).some(n => ttFocus.keys.has(focusGKey({ group: n, faculty: r.faculty,
                    specialty: r.specialty, course: r.course }))));
            }
            // Aralash to'qnashuv (view: cross): o'qituvchi / xona kesimida shu o'qituvchi yoki xona darslari (haftalik va sikl) va
            // to'qnashuvdagi darslarning o'zi (card_ids) — biriktirishdan oldin ochilganda biriktirilayotgan dars hali boshqa (yoki
            // biriktirilmagan) ustunda turadi, u ham yonma-yon ko'rinsin.
            function focusCrossItems(mode, items) {
                const s = ttFocus && ttFocus.show;
                if (!s || s.view !== 'cross') return items;
                const ids = new Set((s.card_ids || []).map(String));
                const own = it => ids.has(String((it.c || it.l).id));
                if (mode === 'teacher' && s.teacher_id) return items.filter(it => own(it) || +(it.c || it.l).teacher_id === +s.teacher_id);
                if (mode === 'room' && s.room_code) return items.filter(it => own(it) || (it.c || it.l).auditorium_code === s.room_code);
                return items;
            }
            // Qizil ramka: haftalik — to'qnashgan darslar (card_ids) kataklari; sikl — fokus qatorlarining to'qnashuv sanalariga
            // tushadigan bloklari va sana sarlavhalari. Birinchisiga bir marta scroll.
            function focusHighlight() {
                if (!ttFocus) return;
                const s = ttFocus.show, hits = [];
                if (s.view === 'cycle') {
                    const grid = $('cycleGrid');
                    if (viewMode !== 'cycle' || !grid || !cyclePlanData) return;
                    const a = (s.dates || [])[0], b = (s.dates || [])[1] || a, idx = [];
                    (cyclePlanData.dates || []).forEach((d, i) => { if (a && d.iso >= a && d.iso <= b) idx.push(i); });
                    if (!idx.length) return;
                    const rows = new Set(cycleRowFilters), lo = idx[0], hi = idx[idx.length - 1];
                    grid.querySelectorAll('td.cyc-block[data-cycle-row]').forEach(td => {
                        const from = +td.dataset.cycleFrom, to = from + Math.max(1, +td.dataset.cycleSpan || 1) - 1;
                        if (rows.has(td.dataset.cycleRow) && from <= hi && to >= lo) hits.push(td);
                    });
                    const ths = grid.querySelectorAll('thead th.cyc-dcol');
                    idx.forEach(i => { if (ths[i]) ths[i].classList.add('tt-focus-date'); });
                } else {
                    if (s.view === 'cross' ? !CROSS_MODES.includes(viewMode) : viewMode !== 'group') return;
                    const ids = new Set((s.card_ids || []).map(String));
                    // Kesimdagi sikl darsi (data-cyc): o'sha karta va to'qnashuv sanalari ichida.
                    const a = (s.dates || [])[0], b = (s.dates || [])[1] || a;
                    const cycHit = ch => { const l = crossCycleShown[+ch.dataset.cyc];
                        return !!l && ids.has(String(l.id)) && (!a || (String(l.date) >= a && String(l.date) <= b)); };
                    // Birlashtirilgan blok (data-merge-ids) va bo'laklar sarlavhasi (data-parallel-ids) — ichidagi har bir karta bo'yicha.
                    const chipIds = ch => [ch.dataset.chip, ...String(ch.dataset.mergeIds || '').split(','),
                        ...String(ch.dataset.parallelIds || '').split(',')].filter(Boolean);
                    document.querySelectorAll('#grid [data-chip], #grid [data-cyc]').forEach(ch => {
                        const hit = ch.dataset.cyc !== undefined ? cycHit(ch) : chipIds(ch).some(x => ids.has(String(x)));
                        const td = hit && ch.closest ? ch.closest('td') : null;
                        if (td && !hits.includes(td)) hits.push(td);
                    });
                }
                hits.forEach(el => el.classList.add('tt-focus-hit'));
                if (!ttFocus.scrolled && hits.length) {
                    ttFocus.scrolled = true;
                    hits[0].scrollIntoView({ block: 'center', inline: 'center' });
                }
            }
            // Jadvalni yopib turadigan oyna/popuplar (to'qnashuv tafsiloti, Takliflar, biriktirish oynalari) yopiladi.
            function focusCloseOverlays() {
                if (typeof closeCycDayPop === 'function') closeCycDayPop();
                const sug = document.getElementById('ttSugModal');
                if (sug) sug.remove();
                if ($('cycAssignModal') && $('cycAssignModal').classList.contains('open') && typeof closeCycleAssign === 'function') closeCycleAssign();
                if ($('asgRoomModal')) $('asgRoomModal').classList.add('hidden');
                if ($('assignModal')) $('assignModal').classList.add('hidden');
            }
            // Qamrov (fakultet/yo'nalish/kurs) qiymatlari — tanlov ro'yxatidagi aynan yozilishi bilan (katta-kichik harf farq qilsa ham).
            function focusSpecOf(g) {
                return specList.find(x => focusNorm(x.faculty) === focusNorm(g.faculty) && focusNorm(x.specialty_name) === focusNorm(g.specialty)
                    && +x.course === +g.course) || null;
            }
            function focusRefresh() {
                reconcileSelection(false);
                fillSelectors();
                selected = null;
                fillGridInputs();
                if (weekNeedsReload()) {
                    loadBoard(board.id).catch(e => alert('Xatolik: ' + e.message));
                    return;
                }
                renderAll();
                ensureScopeLoaded();
            }
            function ttFocusStart(show) {
                const groups = focusVisibleGroups(show);
                if (!board || !groups.length) return;
                focusCloseOverlays();
                // Oldingi holat — faqat birinchi fokusda (fokusdan fokusga o'tilsa ham Yopish asl holatga qaytaradi).
                if (!ttFocus) {
                    ttFocus = { prev: { viewMode, curWeek, fac: [...selectedFaculties], dir: [...selectedDirs], crs: [...selectedCourses],
                        cycleRowFilters: cycleRowFilters.slice(), typeFilter, weeklyLayer, cycleLayer } };
                }
                // Dars turi filtri (Ma'ruza / Amaliy) vaqtincha "Hammasi": to'qnashuvning ikkala tomoni ham ko'rinsin.
                if (typeFilter !== 'all') setTypeFilter('all');
                Object.assign(ttFocus, { show, groups, keys: new Set(groups.map(focusGKey)), scrolled: false });
                groups.forEach(g => {
                    const sp = focusSpecOf(g);
                    if (!sp) return;
                    selectedFaculties.add(sp.faculty); selectedDirs.add(sp.specialty_name); selectedCourses.add(+sp.course);
                });
                // Aralash (haftalik + sikl) to'qnashuv — haftalik o'qituvchi / xona kesimi: u yerda ikkala turdagi dars ham chiqadi.
                const crossMode = show.kind === 'teacher_busy' ? 'teacher' : (show.kind === 'room_busy' || show.kind === 'room_capacity') ? 'room' : null;
                const view = show.view === 'cycle' ? 'cycle' : (show.view === 'cross' && crossMode) ? crossMode : 'group';
                if (viewMode !== view && [...$('viewMode').options].some(o => o.value === view)) { viewMode = view; $('viewMode').value = view; }
                if (view !== 'cycle' && +show.week > 0) curWeek = +show.week;
                // Haftalik to'qnashuvlar ichki (haqiqiy) jadval bo'yicha: tashqi qatlam ochiq bo'lsa — vaqtincha ichki.
                if (view !== 'cycle' && weeklyLayer !== 'internal' && $('wkLayerInternal')) focusSetLayer('internal');
                // Sikl to'qnashuvlari ham ichki (kafedra) jadval bo'yicha: tashqi qatlam ochiq bo'lsa — vaqtincha ichki (saqlanmaydi).
                if (view === 'cycle' && cycleLayer !== 'internal' && $('cycLayerInternal')) { cycleLayer = 'internal'; renderCycleLayerUi(null); }
                renderFocusBar();
                focusRefresh();
            }
            // Haftalik qatlamni vaqtincha almashtirish (saqlanmaydi; kartalar yuklangan ichki/tashqi qiymatlaridan).
            function focusSetLayer(l) {
                weeklyLayer = l;
                applyWeeklyLayer(allCards);
                invalidateWeeklyConflicts();
                renderWeeklyLayerUi();
            }
            // Boshqa doska ochildi yoki doska yopildi: fokus o'sha doskaniki — tashlanadi. Doskaga bog'liq bo'lmagan ko'rinish
            // sozlamalari (kesim, dars turi, qatlamlar) oldingisiga qaytadi; qamrov, hafta va guruh filtri — yangi doskaniki.
            function ttFocusDiscard() {
                if (!ttFocus) return;
                const p = ttFocus.prev;
                ttFocusForget();
                if (viewMode !== p.viewMode) { viewMode = p.viewMode; $('viewMode').value = p.viewMode; }
                if (typeFilter !== p.typeFilter) setTypeFilter(p.typeFilter);
                if (weeklyLayer !== p.weeklyLayer) { weeklyLayer = p.weeklyLayer; renderWeeklyLayerUi(); }
                if (cycleLayer !== p.cycleLayer) { cycleLayer = p.cycleLayer; renderCycleLayerUi(null); }
            }
            // Fokusni tiklamasdan unutish (foydalanuvchi filtrni o'zi o'zgartirdi).
            function ttFocusForget() {
                ttFocus = null;
                renderFocusBar();
            }
            function ttFocusClose() {
                if (!ttFocus) return;
                const p = ttFocus.prev;
                ttFocusForget();
                selectedFaculties = new Set(p.fac); selectedDirs = new Set(p.dir); selectedCourses = new Set(p.crs);
                if (viewMode !== p.viewMode) { viewMode = p.viewMode; $('viewMode').value = p.viewMode; }
                curWeek = p.curWeek;
                if (typeFilter !== p.typeFilter) setTypeFilter(p.typeFilter);
                if (weeklyLayer !== p.weeklyLayer) focusSetLayer(p.weeklyLayer);
                if (cycleLayer !== p.cycleLayer) { cycleLayer = p.cycleLayer; renderCycleLayerUi(null); }
                cycleRowFilters = p.cycleRowFilters.slice();
                cycleRowStoreKey = cycleRowStorageKey();   // tiklangan tanlov saqlangandan qayta o'qilmaydi (saqlash bloklangan bo'lsa ham qoladi)
                focusRefresh();
            }
            // Xona sig'imi: kiritilmagan (0) yoki shubhali (≤ 10) — ro'yxatda ajratiladi (amaliy xona "10 o'rin" tekshiruvi uchun).
            function audVolumeHtml(v) {
                const n = +v || 0;
                if (!n) return '<span class="aud-vol-bad" title="Sig\'im kiritilmagan — xona sig\'imi to\'qnashuvi aniqlanmaydi">0 · kiritilmagan</span>';
                if (n <= 10) return '<span class="aud-vol-warn" title="Shubhali sig\'im — haqiqiy o\'rinlar sonini tekshiring">' + n + ' · shubhali</span>';
                return String(n);
            }

            // Ichki jadval: kun ustunini tanlash, kun oynasi va soatni surish.
            let cycDaySel = null;   // {key, offset}
            function cycBlockByKey(key) {
                return (cyclePlanData && cyclePlanData.rows || []).flatMap(row => row.blocks || []).find(b => b.key === key) || null;
            }
            // ===== Tanlov — Excel kabi (surish va so'rov uchun), faqat bitta blok ichida =====
            // Tanlov birligi — kunning bo'lagi: M (shu kunning butun ma'ruzasi) yoki A (butun amaliyoti), faqat shu kun doirasida; bo'sh soat, dam
            // olish va o'tgan kun tanlanmaydi (bugungi — faqat admin / registrator ofisi). Oddiy bosish — kun oynasi va boshlanish nuqtasi (faol
            // katak); Shift+bosish — boshlanish nuqtasidan shu katakkacha to'rtburchak (kunlar × soatlar, oldingi tanlov o'rniga); Ctrl/Cmd+bosish —
            // bitta bo'lak qo'shiladi / olinadi (boshlanish nuqtasi shu katakka o'tadi); Ctrl+Shift — to'rtburchak tanlovga qo'shiladi. Kun
            // oynasidagi rejim radiosi — tanlovga filtr. Blok sarlavhasida ikki marta bosish yoki "Hammasini tanlash" — blokning barcha kunlari;
            // Esc yoki bo'sh joyga bosish — tozalaydi.
            // cycMultiSel = { key, parts: Map(kun → Set('lecture' | 'practice')), offsets: Set(kunlar) }. Bo'sh to'plamli kun — radio filtridan
            // keyin shu rejimdagi bo'lagi yo'q kun: tanlovda qoladi (uzuq ramka; boshqa rejimga qaytsa — yana tanlanadi), surilmaydi.
            let cycMultiSel = null;
            let cycSelAnchor = null;   // { key, offset, hour } — boshlanish nuqtasi (oxirgi oddiy yoki Ctrl bilan bosilgan katak)
            const CYC_PARTS = ['lecture', 'practice'];
            const CYC_LOOK_LABEL = { both: 'Birga', lecture: 'Faqat ma\'ruza', practice: 'Faqat amaliy' };
            // Bugungi kun — faqat shu rollar (dars boshlangan, hatto tugagan bo'lsa ham; server ham tekshiradi — TimetableStaffToday).
            // Server TODAY_STAFF_ROLES (= TIMETABLE_FULL_EDIT_ROLES) bilan bir xil.
            const CYC_TODAY_ROLES = ['admin', 'superadmin', 'registrator_ofisi', 'kichik_admin', 'oquv_bolimi', 'oquv_bolimi_boshligi'];
            // Kunni tanlab bo'ladimi: darsi bor, kelgusi kun; bugungi — admin / registrator ofisi (har qanday holatda); o'tgan — hech kim.
            function cycSelEligible(block, offset) {
                const dp = block && block.day_plan ? block.day_plan[offset] : null;
                const dt = dp && cyclePlanData ? (cyclePlanData.dates || [])[block.from + (+offset)] : null;
                if (!dt || (+dp.lec || 0) + (+dp.prc || 0) <= 0) return false;
                const today = cycLocalToday();
                if (dt.iso > today) return true;
                return dt.iso === today && Boolean(cyclePlanData.day_edit) && CYC_TODAY_ROLES.includes(TIMETABLE_ROLE);
            }
            // Kun bo'lagining soatlari [boshi, oxiri) — jadval chizilishi kabi (ma'ruza — start dan, amaliy — ps dan yoki ma'ruzadan keyin).
            function cycPartRange(dp, part) {
                if (!dp) return null;
                const st = +dp.start || 1, lec = +dp.lec || 0, prc = +dp.prc || 0;
                if (part === 'lecture') return lec > 0 ? [st, st + lec] : null;
                const ps = dp.ps != null ? +dp.ps : st + lec;
                return prc > 0 ? [ps, ps + prc] : null;
            }
            const cycHourPart = (dp, hour) => CYC_PARTS.find(p => { const r = cycPartRange(dp, p); return r && hour >= r[0] && hour < r[1]; }) || null;
            const cycCellPart = c => c && c.classList ? (c.classList.contains('is-lecture') ? 'lecture' : c.classList.contains('is-practice') ? 'practice' : null) : null;
            // Rejim → kun bo'laklari.
            const cycModeParts = mode => mode === 'lecture' ? ['lecture'] : mode === 'practice' ? ['practice'] : CYC_PARTS;
            // Bo'lakni tanlab bo'ladimi: kun tanlanadi (cycSelEligible) va shu bo'lak bor; o'qituvchi / fan mas'uli (tahrir yo'q) — faqat so'rash
            // mumkin bo'lgan bo'lak (o'z darsi yoki mas'ul fani, ertangi va keyingi kunlar — cycCanAsk).
            function cycPartOk(key, offset, part) {
                const block = cycBlockByKey(key);
                const dp = block && block.day_plan ? block.day_plan[offset] : null;
                if (!dp || !cycPartRange(dp, part) || !cycSelEligible(block, offset)) return false;
                if (cyclePlanData.day_edit || !['oqituvchi', 'fan_masuli'].includes(TIMETABLE_ROLE)) return true;
                const card = (cyclePlanData.cycle_cards || []).find(item => item.key === key);
                const date = (cyclePlanData.dates || [])[block.from + (+offset)];
                return typeof cycCanAsk === 'function' && cycCanAsk(card, dp, date, cycLocalToday(), part);
            }
            // Tanlangan bo'laklar → kunni surish rejimi (server day_modes): ikkalasi — "Birga"; faqat M — "Faqat ma'ruza" (amaliysiz kunda —
            // "Birga", kun oynasidagi kabi); faqat A — "Faqat amaliy".
            function cycPartsMode(dp, parts) {
                const L = Boolean(parts && parts.has('lecture')), P = Boolean(parts && parts.has('practice'));
                if (L && P) return 'both';
                if (L) return +(dp && dp.prc) > 0 ? 'lecture' : 'both';
                return P ? 'practice' : null;
            }
            // Faol (bo'lagi tanlangan) kunlar, tartiblangan.
            const cycSelOffsets = key => (cycMultiSel && cycMultiSel.key === key
                ? [...cycMultiSel.parts].filter(([, s]) => s.size).map(([o]) => o).sort((a, b) => a - b) : []);
            // Har faol kunning surish rejimi: { kun: rejim }.
            function cycSelModes(key) {
                const block = cycBlockByKey(key), out = {};
                cycSelOffsets(key).forEach(o => {
                    const m = cycPartsMode(block && block.day_plan ? block.day_plan[o] : null, cycMultiSel.parts.get(o));
                    if (m) out[o] = m;
                });
                return out;
            }
            // Tanlov ko'rinishi (yorliq va radio): hammasi bir xil — 'both' | 'lecture' | 'practice', aralash — 'mixed', bo'sh — null. Bitta
            // bo'lakli kun (masalan, amaliysiz) har ikki rejimga mos keladi.
            function cycSelLook(key) {
                const block = cycBlockByKey(key);
                const strict = new Set(), singles = new Set();
                cycSelOffsets(key).forEach(o => {
                    const dp = block && block.day_plan ? block.day_plan[o] : null, s = cycMultiSel.parts.get(o);
                    if (cycPartRange(dp, 'lecture') && cycPartRange(dp, 'practice')) strict.add(s.size > 1 ? 'both' : [...s][0]);
                    else s.forEach(p => singles.add(p));
                });
                if (strict.size > 1) return 'mixed';
                if (strict.size === 1) {
                    const m = [...strict][0];
                    return m === 'both' || [...singles].every(p => p === m) ? m : 'mixed';
                }
                return singles.size > 1 ? 'both' : singles.size ? [...singles][0] : null;
            }
            function cycSelSet(key, parts) {
                cycMultiSel = parts && parts.size ? { key: key, parts: parts, offsets: new Set(parts.keys()) } : null;
                cycMultiPaint();
            }
            const cycSelCopy = key => new Map(cycMultiSel && cycMultiSel.key === key ? [...cycMultiSel.parts].map(([o, s]) => [o, new Set(s)]) : []);
            // To'rtburchak: kunlar × soatlar oralig'iga tegib o'tgan bo'laklar — har biri butunligicha (shu kun doirasida).
            function cycSelRect(key, a, b) {
                const block = cycBlockByKey(key), out = new Map();
                if (!block) return out;
                const h0 = Math.min(a.hour, b.hour), h1 = Math.max(a.hour, b.hour);
                for (let o = Math.min(a.offset, b.offset); o <= Math.max(a.offset, b.offset); o++) {
                    if (typeof cycleColHidden === 'function' && cycleColHidden(block.from + o)) continue;
                    const dp = block.day_plan ? block.day_plan[o] : null;
                    const s = new Set(CYC_PARTS.filter(p => { const r = cycPartRange(dp, p); return r && r[0] <= h1 && r[1] > h0 && cycPartOk(key, o, p); }));
                    if (s.size) out.set(o, s);
                }
                return out;
            }
            const cycSelDenyText = () => cyclePlanData && !cyclePlanData.day_edit && ['oqituvchi', 'fan_masuli'].includes(TIMETABLE_ROLE)
                ? 'Bu darsni tanlab bo\'lmaydi: so\'rov faqat o\'z darsingiz (yoki mas\'ul faningiz) uchun, ertangi va keyingi kunlarga.'
                : 'Bu darsni tanlab bo\'lmaydi: o\'tgan kun (bugungi darsni faqat admin va registrator ofisi ko\'chiradi).';
            // Ctrl / Shift bilan bosish (Excel kabi). part — bosilgan katak bo'lagi (bo'sh soat — null).
            function cycSelClick(key, offset, hour, part, ctrl, shift) {
                offset = +offset;
                hour = +hour;
                const a = cycSelAnchor && cycSelAnchor.key === key ? cycSelAnchor : null;
                let parts = cycSelCopy(key);
                if (shift) {
                    const rect = cycSelRect(key, a || { offset: offset, hour: hour }, { offset: offset, hour: hour });
                    if (!ctrl) parts = rect;
                    else rect.forEach((s, o) => { const t = parts.get(o) || new Set(); s.forEach(p => t.add(p)); parts.set(o, t); });
                    if (!a) cycSelAnchor = { key: key, offset: offset, hour: hour };
                    if (!rect.size) ttToast('Bu oraliqda tanlab bo\'ladigan dars yo\'q (bo\'sh soat, o\'tgan yoki dam olish kuni).', 'warn');
                    cycSelSet(key, parts);
                    return;
                }
                if (!part) { ttToast('Bo\'sh soat tanlanmaydi — M yoki A katagini bosing.', 'warn'); return; }
                if (!cycPartOk(key, offset, part)) { ttToast(cycSelDenyText(), 'warn'); return; }
                // Tanlov hali yo'q, kun oynasi ochiq (faol katak) — o'sha katak bo'lagi ham birinchi bo'lib kiradi.
                if (!parts.size && a && cycDaySel && cycDaySel.key === key && cycDaySel.offset === a.offset) {
                    const block = cycBlockByKey(key);
                    const ap = cycHourPart(block && block.day_plan ? block.day_plan[a.offset] : null, a.hour);
                    if (ap && (a.offset !== offset || ap !== part) && cycPartOk(key, a.offset, ap)) parts.set(a.offset, new Set([ap]));
                }
                const s = parts.get(offset) || new Set();
                if (s.has(part)) s.delete(part); else s.add(part);
                if (s.size) parts.set(offset, s); else parts.delete(offset);
                cycSelAnchor = { key: key, offset: offset, hour: hour };
                cycSelSet(key, parts);
            }
            // Kun oynasidagi rejim radiosi — tanlovga filtr: tanlangan kunlarda faqat shu rejim bo'laklari ("Birga" — ikkalasi); bo'lagi yo'q
            // kun tanlovda qoladi (surilmaydi), boshqa rejimga qaytilsa — yana tanlanadi.
            function cycSelApplyMode(key, mode) {
                if (!cycMultiSel || cycMultiSel.key !== key) return;
                const parts = new Map();
                cycMultiSel.offsets.forEach(o => parts.set(o, new Set(cycModeParts(mode).filter(p => cycPartOk(key, o, p)))));
                cycSelSet(key, parts);
            }
            // "Hammasini tanlash" — blokning barcha kunlari: tanlov ko'rinishi (bir xil bo'lsa) yoki surish rejimi bo'yicha bo'laklar.
            function cycSelAll(key) {
                const block = cycBlockByKey(key);
                const look = cycSelLook(key);
                const mode = look && look !== 'mixed' ? look : cycMoveMode;
                const parts = new Map();
                Object.keys(block && block.day_plan || {}).map(Number).forEach(o => {
                    const s = new Set(cycModeParts(mode).filter(p => cycPartOk(key, o, p)));
                    if (s.size) parts.set(o, s);
                });
                cycSelSet(key, parts);
                if (!parts.size) ttToast('Bu blokda tanlab bo\'ladigan (kelgusi) dars yo\'q.', 'warn');
            }
            function cycSelClear() { if (cycMultiSel) { cycMultiSel = null; cycMultiPaint(); } }
            // Tanlangan bo'laklar (ramka + och fon; bo'lagi yo'q kun — uzuq ramka) va tepadagi yorliq:
            // "Tanlangan: 5 kun · Faqat ma'ruza · Esc — bekor".
            function cycMultiPaint() {
                document.querySelectorAll('#cycleGrid .cyc-mk-cell.is-multi-sel, #cycleGrid .cyc-mk-cell.is-multi-idle')
                    .forEach(c => c.classList.remove('is-multi-sel', 'is-multi-idle'));
                let badge = document.getElementById('cycSelBadge');
                if (cycMultiSel && !cycBlockByKey(cycMultiSel.key)) cycMultiSel = null;   // blok yo'qolgan (qayta yuklash, filtr)
                if (!cycMultiSel) { if (badge) badge.remove(); return; }
                const key = cycMultiSel.key;
                const painted = [];
                cycMultiSel.parts.forEach((s, o) => document.querySelectorAll('#cycleGrid .cyc-mk-cell[data-mk-key="' + CSS.escape(key) + '"][data-mk-day="' + o + '"]')
                    .forEach(c => {
                        const p = cycCellPart(c);
                        if (!p || (s.size && !s.has(p))) return;
                        c.classList.add(s.size ? 'is-multi-sel' : 'is-multi-idle');
                        painted.push(c);
                    }));
                if (!badge) {
                    badge = document.createElement('div');
                    badge.id = 'cycSelBadge';
                    badge.addEventListener('click', ev => {
                        const b = ev.target.closest ? ev.target.closest('[data-sel-act]') : null;
                        if (!b || !cycMultiSel) return;
                        if (b.dataset.selAct === 'all') cycSelAll(cycMultiSel.key); else cycSelClear();
                    });
                    document.body.appendChild(badge);
                }
                const active = cycSelOffsets(key);
                const look = cycSelLook(key);
                const count = part => active.filter(o => cycMultiSel.parts.get(o).has(part)).length;
                const lookText = look === 'mixed' ? 'Aralash (M ' + count('lecture') + ', A ' + count('practice') + ')' : (CYC_LOOK_LABEL[look] || '');
                const idle = cycMultiSel.offsets.size - active.length;
                badge.innerHTML = '<b>Tanlangan: ' + cycMultiSel.offsets.size + ' kun' + (lookText ? ' · ' + esc(lookText) : '') + '</b>'
                    + (idle ? ' · ' + idle + ' kunda ' + ({ lecture: 'ma\'ruza', practice: 'amaliy' }[cycMoveMode] || 'dars') + ' yo\'q' : '')
                    + ' · Esc — bekor'
                    + (cyclePlanData && cyclePlanData.day_edit ? ' · ↑ ↓ — 1 qadam, sudrab — hammasi' : '')
                    + ' <button type="button" data-sel-act="all">Hammasini tanlash</button><button type="button" data-sel-act="clear" aria-label="Tanlovni bekor qilish">×</button>';
                // Jadval tepasida (sana sarlavhasi ustida — blok sarlavhasi va kataklarni yopmaydi), bo'yalgan eng chap ustun ro'parasida
                // (kataklar soat qatorlari bo'yicha chiziladi — birinchi topilgani eng chapdagisi bo'lmasligi mumkin).
                const wrap = $('cycleGridWrap');
                const wr = wrap ? wrap.getBoundingClientRect() : { left: 8, top: 8 };
                const left = painted.length ? Math.min(...painted.map(c => c.getBoundingClientRect().left)) : wr.left;
                badge.style.left = Math.max(8, Math.min(window.innerWidth - badge.offsetWidth - 8, left)) + 'px';
                badge.style.top = Math.max(8, wr.top + 2) + 'px';
            }
            // So'rov uchun blokning kelgusi kunlari (shu turdagi darsi bor): sana, hafta kuni, sikl kuni, hozirgi vaqt.
            function cycAskDays(block, kind) {
                const dates = cyclePlanData.dates || [], times = cycHourTimes(), today = cycLocalToday();
                const lbl = (h, n) => (times[h] ? times[h][0] : h + '-soat') + '–' + (times[h + n - 1] ? times[h + n - 1][1] : '');
                return Object.keys(block && block.day_plan || {}).map(o => {
                    const dp = block.day_plan[o], dt = dates[block.from + (+o)];
                    const n = kind === 'lecture' ? +dp.lec || 0 : +dp.prc || 0;
                    if (!dt || dt.iso <= today || n <= 0) return null;
                    const st = kind === 'lecture' ? (+dp.start || 1) : (dp.ps != null ? +dp.ps : (+dp.start || 1) + (+dp.lec || 0));
                    return { offset: +o, iso: dt.iso, d: dt.d, k: dp.k, time: lbl(st, n), dow: crDow(dt.iso) };
                }).filter(Boolean).sort((a, b) => a.iso < b.iso ? -1 : 1);
            }
            // So'rov formasi uchun kun rejasi: ma'ruza — davomiyligi lec, boshi start (ps — e'tiborsiz).
            const cycAskDp = (dp, kind) => kind === 'lecture' ? Object.assign({}, dp, { prc: +dp.lec || 1, ps: +dp.start || 1, lec: 0, start: +dp.start || 1 }) : dp;
            // Kun oynasini yopadi; kunlar tanlovi (cycMultiSel) qoladi — uni Esc / bo'sh joyga bosish / cycSelClear tozalaydi.
            function closeCycDayPop() {
                const pop = document.getElementById('cycDayPop');
                if (pop) pop.remove();
                cycPopUnwatch();
                document.querySelectorAll('#cycleGrid .cyc-mk-cell.is-day-sel')
                    .forEach(c => c.classList.remove('is-day-sel', 'is-day-top', 'is-day-bottom'));
                cycDaySel = null;
            }
            // ===== Sikl kunini surish rejimi: "Birga" (ma'ruza va amaliy) · "Faqat ma'ruza" · "Faqat amaliy" =====
            // Kun oynasida tanlanadi (↑/↓ shu rejim bilan); katakni sudrash: M — faqat ma'ruza, A — faqat amaliy, tanlangan tugma
            // (sukut — Shift) bilan — birga. Tugma — shaxsiy sozlama (brauzerda, "Umumiy sozlamalar" va kun oynasida).
            let cycMoveMode = 'both';
            const CYC_BOTH_KEYS = { shift: 'Shift', alt: 'Alt', ctrl: 'Ctrl' };
            function cycBothKey() {
                let v = null;
                try { v = localStorage.getItem('tt.cycBothKey'); } catch (_) { }
                return CYC_BOTH_KEYS[v] ? v : 'shift';
            }
            function setCycBothKey(v) {
                try { localStorage.setItem('tt.cycBothKey', CYC_BOTH_KEYS[v] ? v : 'shift'); } catch (_) { }
            }
            const cycBothKeyLabel = () => CYC_BOTH_KEYS[cycBothKey()];
            const cycBothKeyDown = ev => Boolean(ev && ev[cycBothKey() + 'Key']);
            // ===== "Faqat ma'ruza": yangi vaqtni to'sib turgan amaliyot (kun oynasida; shaxsiy sozlama — brauzerda) =====
            // on — "Amaliyot bilan o'rin almashish" (sukut — yoqilgan; o'chirilsa — avvalgidek: kesishsa xato); how — usul: swap (ma'ruzaning
            // bo'shagan joyiga, sig'masa — keyin/oldin), after (ma'ruzadan keyin), gap (N para oraliq bilan), pair (aniq paradan).
            const CYC_PLACE_HOW = { swap: 'O\'rin almashish', after: 'Ma\'ruzadan keyin', gap: 'Oraliq bilan', pair: 'Aniq para' };
            function cycPracPlace() {
                let v = null;
                try { v = JSON.parse(localStorage.getItem('tt.cycPracPlace') || 'null'); } catch (_) { }
                v = v && typeof v === 'object' ? v : {};
                const num = (x, lo, hi, def) => { const n = parseInt(x, 10); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : def; };
                return { on: v.on !== false, how: CYC_PLACE_HOW[v.how] ? v.how : 'swap', gap: num(v.gap, 0, 6, 1), pair: num(v.pair, 1, 12, 3) };
            }
            function setCycPracPlace(patch) {
                try { localStorage.setItem('tt.cycPracPlace', JSON.stringify(Object.assign(cycPracPlace(), patch))); } catch (_) { }
            }
            // So'rov parametrlari (cycle-lecture-slots, cycle-time-proposal): practice_place (+ practice_gap / practice_pair).
            function cycPracPlaceParams(p = cycPracPlace()) {
                if (!p.on) return { practice_place: 'keep' };
                return Object.assign({ practice_place: p.how }, p.how === 'gap' ? { practice_gap: p.gap } : {}, p.how === 'pair' ? { practice_pair: p.pair } : {});
            }
            // Sudrash / ↑ ↓ da ma'ruza–amaliy kesishuvi mijozda xato emas: ma'ruza (o'rin almashish yoqilgan) — server amaliyotni joylaydi;
            // amaliy — ma'ruza bilan o'rin almashish taklif qilinadi.
            const cycOverlapOk = mode => mode === 'practice' || (mode === 'lecture' && cycPracPlace().on);
            // Kun oynasidagi sozlama: belgi va usul (gap — necha para, pair — qaysi para).
            function cycPracPlaceHtml() {
                const p = cycPracPlace();
                const pairs = boardSchedule().filter(it => it.type === 'pair');
                return '<div class="dp-swap"><label><input type="checkbox" data-dp-swap' + (p.on ? ' checked' : '') + '> Amaliyot bilan o\'rin almashish</label>'
                    + (p.on ? '<div class="dp-swap-how">To\'sib turgan amaliyot: <select data-dp-swap-how>' + Object.entries(CYC_PLACE_HOW).map(([v, t]) =>
                        '<option value="' + v + '"' + (v === p.how ? ' selected' : '') + '>' + t + '</option>').join('') + '</select>'
                        + (p.how === 'gap' ? ' <input type="number" min="0" max="6" data-dp-swap-gap value="' + p.gap + '"> para keyin' : '')
                        + (p.how === 'pair' ? ' <select data-dp-swap-pair>' + pairs.map((it, i) => '<option value="' + (i + 1) + '"' + (i + 1 === p.pair ? ' selected' : '') + '>'
                            + esc((it.abbr && it.abbr !== '—' ? it.abbr : i + 1) + ' para' + (it.start ? ' (' + it.start + ')' : '')) + '</option>').join('') + '</select>' : '')
                        + '</div>' : '<div class="dp-sub">O\'chiq: ma\'ruza amaliyot bilan kesishsa — xato.</div>') + '</div>';
            }
            function cycPracPlaceBind(pop, reopen) {
                const on = pop.querySelector('[data-dp-swap]');
                if (on) on.onchange = () => { setCycPracPlace({ on: on.checked }); reopen(); };
                const how = pop.querySelector('[data-dp-swap-how]');
                if (how) how.onchange = () => { setCycPracPlace({ how: how.value }); reopen(); };
                const gap = pop.querySelector('[data-dp-swap-gap]');
                if (gap) gap.onchange = () => setCycPracPlace({ gap: gap.value });
                const pair = pop.querySelector('[data-dp-swap-pair]');
                if (pair) pair.onchange = () => setCycPracPlace({ pair: pair.value });
            }
            // Rejim bo'yicha kunning yangi holati: { lec: [boshi, oxiri) | null, prc: [boshi, oxiri) | null, base } — base — ↑/↓ va
            // sudrash hisoblanadigan boshlanish (birga — kun boshi, ma'ruza — ma'ruza boshi, amaliy — amaliy boshi).
            function cycDayShape(dp, mode, delta, baseSt) {
                const st = baseSt != null ? +baseSt : (+dp.start || 1), lec = +dp.lec || 0, prc = +dp.prc || 0;
                const ps = dp.ps != null ? +dp.ps : (+dp.start || 1) + lec;
                const psOff = ps - (+dp.start || 1);
                let L = lec ? [st, st + lec] : null, P = prc ? [st + psOff, st + psOff + prc] : null, base = st;
                if (mode === 'lecture') { L = lec ? [(+dp.start || 1) + delta, (+dp.start || 1) + delta + lec] : null; P = prc ? [ps, ps + prc] : null; base = +dp.start || 1; }
                else if (mode === 'practice') { L = lec ? [+dp.start || 1, (+dp.start || 1) + lec] : null; P = prc ? [ps + delta, ps + delta + prc] : null; base = ps; }
                else { L = L && [L[0] + delta, L[1] + delta]; P = P && [P[0] + delta, P[1] + delta]; }
                return { lec: L, prc: P, base: base };
            }
            // Mijozdagi tekshiruv (bandlik — serverda): kun chegarasi va ma'ruza–amaliy kesishuvi. Xato matni yoki ''.
            // overlapOk — kesishuv xato emas (cycOverlapOk: o'rin almashish serverda).
            // ↑ ↓ qadami (server cycleDayJump kabi, shu qatorning kun rejasi bo'yicha): surilayotgan qism yo'nalishda ikkinchi qism bilan yonma-yon
            // bo'lsa — o'rin almashadi (ikkinchisi butunligicha birinchisining joyiga, birinchisi uning ortidan); aks holda — 1 soat.
            // Natija: { delta (qism boshining siljishi), swap, shape (cycDayShape kabi) }.
            function cycDayJump(dp, mode, dir) {
                const L = cycPartRange(dp, 'lecture'), P = cycPartRange(dp, 'practice');
                const plain = { delta: dir, swap: false, shape: cycDayShape(dp, mode, dir, null) };
                if (mode === 'both' || !L || !P) return plain;
                const llen = L[1] - L[0], plen = P[1] - P[0];
                if (mode === 'lecture') {
                    if (dir > 0 ? P[0] !== L[1] : P[1] !== L[0]) return plain;
                    const h = dir > 0 ? L[0] + plen : L[0] - plen, at = dir > 0 ? L[0] : h + llen;
                    return { delta: h - L[0], swap: true, shape: { lec: [h, h + llen], prc: [at, at + plen], base: L[0] } };
                }
                if (dir > 0 ? L[0] !== P[1] : L[1] !== P[0]) return plain;
                const h = dir > 0 ? P[0] + llen : L[0], la = dir > 0 ? P[0] : L[0] + plen;
                return { delta: h - P[0], swap: true, shape: { lec: [la, la + llen], prc: [h, h + plen], base: P[0] } };
            }
            function cycDayShapeError(shape, dayHours, overlapOk = false) {
                const out = r => r && (r[0] < 1 || r[1] - 1 > dayHours);
                if (out(shape.lec) || out(shape.prc)) return 'Kun chegarasidan chiqadi';
                if (!overlapOk && shape.lec && shape.prc && shape.lec[0] < shape.prc[1] && shape.prc[0] < shape.lec[1]) return 'Ma\'ruza va amaliy ustma-ust';
                return '';
            }
            // Kun oynasidagi kun ustuni: faqat berilgan bo'laklar (M / A) kataklari — bo'sh soatlar emas; ramka boshi va oxiri — har uzluksiz
            // bo'lakning birinchi va oxirgi katagida (ma'ruza bilan amaliy orasida bo'sh soat bo'lsa — ikki bo'lak).
            function cycDaySelPaint(key, offset, parts) {
                const cells = [...document.querySelectorAll('#cycleGrid .cyc-mk-cell[data-mk-key="' + CSS.escape(key) + '"][data-mk-day="' + offset + '"]')]
                    .filter(c => parts.includes(cycCellPart(c))).sort((a, b) => a.dataset.mkHour - b.dataset.mkHour);
                cells.forEach((c, i) => {
                    const h = +c.dataset.mkHour;
                    c.classList.add('is-day-sel');
                    if (i === 0 || +cells[i - 1].dataset.mkHour !== h - 1) c.classList.add('is-day-top');
                    if (i === cells.length - 1 || +cells[i + 1].dataset.mkHour !== h + 1) c.classList.add('is-day-bottom');
                });
            }
            function openCycDayPop(key, offset, anchor, keepMulti = false) {
                const multi = keepMulti ? cycMultiSel : null;
                closeCycDayPop();
                cycMultiSel = multi;
                cycMultiPaint();
                const block = cycBlockByKey(key);
                const dp = block && block.day_plan ? block.day_plan[offset] : null;
                if (!block || !dp) return;
                cycDaySel = { key: key, offset: +offset };
                const dates = cyclePlanData.dates || [];
                const date = dates[block.from + (+offset)];
                const dayHours = Math.max(1, +cyclePlanData.day_hours || 6);
                const total = (+dp.lec || 0) + (+dp.prc || 0);
                const st = +dp.start || 1;
                // Soatlar oralig'i va qaysi paralarga to'g'ri kelishi (to'liq parada 1 para = 2 soat).
                const bell = boardSchedule().filter(it => it.type === 'pair');
                const pm = t => { const m = /^(\d{1,2}):(\d{2})$/.exec(t || ''); return m ? (+m[1]) * 60 + (+m[2]) : null; };
                const d0 = bell.length ? (pm(bell[0].end) - pm(bell[0].start)) : 80;
                const hpp = d0 >= 60 ? 2 : 1;
                const pairName = h => { const pt = bell[Math.ceil(h / hpp) - 1]; return pt ? (pt.abbr && pt.abbr !== '—' ? pt.abbr : (pt.name || '')) : ''; };
                const range = (a, n) => {
                    if (n <= 0) return '';
                    const b = a + n - 1;
                    const p1 = pairName(a), p2 = pairName(b);
                    const paras = p1 ? (p1 === p2 ? p1 + '-para' : p1 + '–' + p2 + ' para') : '';
                    return a + (n > 1 ? '–' + b : '') + '-soat' + (paras ? ' (' + paras + ')' : '');
                };
                const canEdit = Boolean(cyclePlanData.day_edit);
                const dayCard = (cyclePlanData.cycle_cards || []).find(item => item.key === key);
                const pendingSlot = pendingDaySlot(dayCard, dp.k - 1);
                const pendingAsk = pendingPracticeAsk(dayCard, date && date.iso);
                // Bosilgan katak: M — ma'ruza so'rovi, A — amaliy so'rovi (ikkalasi ruxsat etilgan bo'lsa — bosilgani birinchi).
                const askKinds = ['lecture', 'practice'].filter(kd => cycCanAsk(dayCard, dp, date, cycLocalToday(), kd))
                    .sort((a, b) => (anchor && anchor.classList && anchor.classList.contains('is-lecture') ? (a === 'lecture' ? -1 : 1) : (a === 'practice' ? -1 : 1)));
                // Tasdiq kutilayotgan bo'lsa, keyingi ↑/↓ shu so'ralgan soatdan hisoblanadi.
                // Faqat o'z so'rovi: registrator/o'quv bo'limi boshqaning so'rovidan emas, joriy soatdan siljitadi.
                const baseSt = pendingSlot && pendingSlot.mine && (pendingSlot.payload.mode || 'both') === 'both' ? +pendingSlot.payload.start_hour : st;
                // Amaliy alohida soatda (ps, tasdiqlangan so'rov) — kun bilan birga suriladi: chegaralar shu oraliq bo'yicha.
                const psOff = dp.ps != null ? (+dp.ps - st) : (+dp.lec || 0);
                // Surish rejimi: ma'ruzasiz kunda — faqat amaliy; amaliysiz kunda — "Faqat amaliy" yo'q. Tanlovdagi kun — tanlangan bo'laklari
                // bo'yicha; bir nechta kun tanlangan bo'lsa radio — tanlovga filtr (hamma uch rejim), ↑ ↓ — har kun o'z bo'laklari bilan.
                const selHere = Boolean(cycMultiSel && cycMultiSel.key === key && cycMultiSel.parts.has(+offset));
                const selParts = selHere ? cycMultiSel.parts.get(+offset) : null;
                const selMany = selHere && cycMultiSel.offsets.size > 1;
                const selLook = selHere ? cycSelLook(key) : null;
                const dayModes = (+dp.lec || 0) > 0 ? ((+dp.prc || 0) > 0 ? ['both', 'lecture', 'practice'] : ['both']) : ['practice'];
                const modes = selMany ? ['both', 'lecture', 'practice'] : dayModes;
                const moveMode = typeof cycMoveMode === 'string' && dayModes.includes(cycMoveMode) ? cycMoveMode : dayModes[0];
                const curMode = (selParts && cycPartsMode(dp, selParts)) || moveMode;
                const radioMode = selMany ? selLook : curMode;   // 'mixed' — hech biri belgilanmaydi
                // Kun ustuni: faqat rejimga mos dars kataklari (bo'sh soat — yo'q), ramka boshi / oxiri — har uzluksiz bo'lakda.
                cycDaySelPaint(key, offset, selParts && selParts.size ? [...selParts] : cycModeParts(curMode));
                const bothKeyLabel = typeof cycBothKeyLabel === 'function' ? cycBothKeyLabel() : 'Shift';
                const isSubRow = dayCard && dayCard.placement_group && dayCard.placement_group !== dayCard.group;
                const modeLabels = { both: 'Birga', lecture: 'Faqat ma\'ruza', practice: 'Faqat amaliy' };
                // ↑/↓ chegaralari va qadam — tanlangan rejim bo'yicha, shu rejimdagi kutilayotgan o'z so'rovi soatidan (bo'lsa):
                // tasdiq kutilayotganda keyingi bosish so'ralgan soatdan davom etadi.
                const savedBase = curMode !== 'both' && typeof cycDayShape === 'function' ? cycDayShape(dp, curMode, 0, null).base : null;
                const modePending = curMode !== 'both' && savedBase != null ? pendingDaySlot(dayCard, dp.k - 1, curMode) : null;
                const pendOff = modePending && modePending.mine ? +modePending.payload.start_hour - savedBase : 0;
                const shapeAt = d => typeof cycDayShape === 'function' ? cycDayShape(dp, curMode, d + pendOff, curMode === 'both' ? baseSt : null) : null;
                // ↑ ↓ "Faqat ma'ruza / amaliy": qadam (cycDayJump — yonma-yon qism bilan o'rin almashish yoki 1 soat); o'z so'rovi tasdiq kutilayotgan
                // bo'lsa — avvalgidek, so'ralgan soatdan 1 soat. Bir nechta kun — har kun serverda tekshiriladi (tugma o'chirilmaydi).
                const jumpOk = curMode !== 'both' && !(modePending && modePending.mine);
                const canStep = d => {
                    if (selMany) return true;
                    if (jumpOk && typeof cycDayJump === 'function') { const j = cycDayJump(dp, curMode, d); return !cycDayShapeError(j.shape, dayHours, j.swap || cycOverlapOk(curMode)); }
                    const sh = shapeAt(d);
                    return sh ? !cycDayShapeError(sh, dayHours, cycOverlapOk(curMode)) : true;
                };
                const stepBase = curMode === 'both' ? baseSt : (savedBase != null ? savedBase + pendOff : baseSt);
                const pop = document.createElement('div');
                pop.id = 'cycDayPop';
                pop.innerHTML =
                    '<div class="dp-head"><div><div class="dp-title">' + esc(block.subject) + '</div>' +
                    '<div class="dp-sub">' + dp.k + '-kun' + (date ? ' · ' + esc(date.d) : '') + ' · jami ' + total + ' soat</div></div>' +
                    '<button type="button" class="dp-close" aria-label="Yopish">&times;</button></div>' +
                    (dp.lec > 0 ? '<div class="dp-row"><span class="dp-tag l">M</span><div><b>Ma\'ruza ' + dp.lec + ' s</b> <span class="dp-sub">' + range(st, +dp.lec) + '</span>' +
                        (dp.tl ? '<div class="dp-topic">' + esc(dp.tl) + '</div>' : '') + '</div></div>' : '') +
                    (dp.prc > 0 ? '<div class="dp-row"><span class="dp-tag p">A</span><div><b>Amaliy ' + dp.prc + ' s</b> <span class="dp-sub">' + range(dp.ps != null ? +dp.ps : st + (+dp.lec || 0), +dp.prc) + '</span>' +
                        (dp.tp ? '<div class="dp-topic">' + esc(dp.tp) + '</div>' : '') + '</div></div>' : '') +
                    (total === 0 ? '<div class="dp-sub">Bu kuni KTR bo\'yicha dars yo\'q.</div>' : '') +
                    (dp.ktr ? '' : '<div class="dp-note">KTR kiritilmagan — soatlar reja bo\'yicha taxminiy.</div>') +
                    (pendingSlot ? '<div class="dp-pending">&#9203; So\'rov: ' + ({ lecture: 'ma\'ruza', practice: 'amaliy' }[pendingSlot.payload.mode] || 'darslar') + ' <b>' + (+pendingSlot.payload.start_hour) + '-soatdan</b> — ' + crStageText(pendingSlot) + '</div>' : '') +
                    (pendingAsk ? '<div class="dp-pending">&#9203; So\'rov: ' + (pendingAsk.payload.training_type === 'lecture' ? 'ma\'ruza (oqim)' : 'amaliy') + ' <b>'
                        + (+pendingAsk.payload.start_hour) + '-soatdan</b>' + ((pendingAsk.payload.dates || []).length > 1 ? ' · ' + pendingAsk.payload.dates.length + ' kun' : '')
                        + ' — ' + crStageText(pendingAsk) + '</div>' : '') +
                    // O'qituvchi / fan mas'uli: o'z darsi yoki mas'ul fanidagi dars (ertangi va keyingi kunlar) — vaqt o'zgarishi so'rovi:
                    // M katagi — ma'ruza (butun oqim), A katagi — amaliy (shu guruhcha); Ctrl+bosish — bir nechta kun.
                    (askKinds.length
                        ? '<div class="dp-actions">' + askKinds.map(kd => '<button type="button" data-dp-ask="' + kd + '" class="dp-ask px-2 py-1 rounded bg-blue-600 text-white">'
                            + (askKinds.length > 1 ? (kd === 'lecture' ? 'Ma\'ruza vaqtini so\'rash' : 'Amaliy vaqtini so\'rash') : 'Vaqtini o\'zgartirishni so\'rash') + '</button>').join(' ')
                            + '</div>' + (cycMultiSel && cycMultiSel.key === key && cycMultiSel.offsets.size > 1
                                ? '<div class="dp-sub">Tanlangan kunlar: ' + cycMultiSel.offsets.size + ' (Ctrl+bosish bilan qo\'shiladi / olinadi)</div>'
                                : '<div class="dp-hint">Ctrl+bosish — bir nechta kunni tanlash.</div>') : '') +
                    (canEdit && total > 0
                        ? (modes.length > 1 ? '<div class="dp-modes" role="radiogroup" aria-label="Surish rejimi">' + modes.map(m => '<label><input type="radio" name="dpMode" value="' + m + '"' +
                            (m === radioMode ? ' checked' : '') + '> ' + modeLabels[m] + '</label>').join('') + '</div>' : '') +
                          (selMany ? '<div class="dp-sub">Rejim tanlangan ' + cycMultiSel.offsets.size + ' kunga qo\'llanadi'
                            + (selLook === 'mixed' ? ' (hozir aralash: M ' + cycSelOffsets(key).filter(o => cycMultiSel.parts.get(o).has('lecture')).length
                                + ', A ' + cycSelOffsets(key).filter(o => cycMultiSel.parts.get(o).has('practice')).length + ' kun)' : '') + '.</div>' : '') +
                          (curMode === 'practice' ? '<div class="dp-sub">Amaliy: ' + (isSubRow ? 'faqat shu guruhcha' : 'oqimdagi barcha guruhchalar') + '</div>' : '') +
                          // Ma'ruza va amaliy bor kun: ma'ruza surilganda to'sib turgan amaliyot qayerga o'tadi (sudrashda ham shu sozlama).
                          ((+dp.lec || 0) > 0 && (+dp.prc || 0) > 0 ? cycPracPlaceHtml() : '') +
                          '<div class="dp-actions"><button type="button" data-dp-move="-1" title="Bir qadam yuqoriga (yonidagi ma\'ruza / amaliy bilan o\'rin almashib yoki 1 soat)"' + (!selMany && Math.min(baseSt, baseSt + psOff) <= 1 && curMode === 'both' || !canStep(-1) ? ' disabled' : '') + '>&#8593;</button>' +
                          '<button type="button" data-dp-move="1" title="Bir qadam pastga (yonidagi ma\'ruza / amaliy bilan o\'rin almashib yoki 1 soat)"' + (!selMany && Math.max(baseSt + (+dp.lec || 0), baseSt + psOff + (+dp.prc || 0)) - 1 >= dayHours && curMode === 'both' || !canStep(1) ? ' disabled' : '') + '>&#8595;</button>' +
                          '<span class="dp-sub">' + (curMode === 'lecture' ? 'Ma\'ruza ' + st : curMode === 'practice' ? 'Amaliy ' + (dp.ps != null ? +dp.ps : st + (+dp.lec || 0)) : 'Darslar ' + st) + '-soatdan boshlanadi</span></div>' +
                          '<div class="dp-hint">Katakni sudrang: M — faqat ma\'ruza, A — faqat amaliy; <b>' + esc(bothKeyLabel) + '</b> bilan — hammasi birga. ' +
                          '<label>Tugma: <select data-dp-bothkey>' + Object.entries({ shift: 'Shift', alt: 'Alt', ctrl: 'Ctrl' }).map(([v, t]) => '<option value="' + v + '"' +
                            (t === bothKeyLabel ? ' selected' : '') + '>' + t + '</option>').join('') + '</select></label></div>'
                        : '') +
                    // Bir nechta kun: tanlangan kunlarni sudrash / ↑ ↓ — hammasiga birga (tahrirlovchi); so'rovda — kunlar oldindan belgilanadi.
                    (askKinds.length || (canEdit && total > 0)
                        ? '<div class="dp-hint dp-multi">' + (cycMultiSel && cycMultiSel.key === key && cycMultiSel.offsets.size > 1
                            ? 'Tanlangan: ' + cycMultiSel.offsets.size + ' kun' + (canEdit ? ' — katakni sudrang yoki ↑ ↓: hammasi birga.' : '.')
                            : 'Ctrl+bosish — dars (M yoki A) qo\'shish / olish, Shift+bosish — to\'rtburchak (Excel kabi), Ctrl+Shift — qo\'shib tanlash.')
                            + ' <button type="button" data-dp-selall>Hammasini tanlash</button></div>' : '');
                document.body.appendChild(pop);
                const r = anchor.getBoundingClientRect();
                const left = Math.min(window.innerWidth - pop.offsetWidth - 8, r.right + 8);
                const top = Math.min(window.innerHeight - pop.offsetHeight - 8, Math.max(8, r.top - 20));
                pop.style.left = Math.max(8, left) + 'px';
                pop.style.top = top + 'px';
                pop.querySelector('.dp-close').onclick = closeCycDayPop;
                pop.querySelectorAll('[data-dp-ask]').forEach(askBtn => askBtn.onclick = () => {
                    const kd = askBtn.dataset.dpAsk;
                    // Tanlovdagi shu turdagi (M — ma'ruza, A — amaliy) kunlar oldindan belgilanadi; aralash tanlovda ham — har tugma o'z turi bilan.
                    const ofKind = cycSelOffsets(key).filter(o => cycMultiSel.parts.get(o).has(kd));
                    const sel = ofKind.length ? ofKind : [+offset];
                    const days = cycAskDays(block, kd);
                    closeCycDayPop();
                    openCycleTimeProposal(Object.assign({}, dayCard, { type: kd }), cycAskDp(dp, kd), date,
                        { kind: kd, days: days, preselect: days.filter(x => sel.includes(x.offset)).map(x => x.iso) });
                });
                pop.querySelectorAll('[data-dp-move]').forEach(btn => btn.onclick = () => {
                    const d = +btn.dataset.dpMove;
                    // Bir nechta kun tanlangan (shu kun ham) — hammasi birga, har kun o'z bo'laklari (rejimi) bilan va o'z boshidan (sudrash va
                    // klaviatura ↑ ↓ kabi), bitta so'rov.
                    if (selMany) {
                        const offs = cycSelOffsets(key);
                        if (!offs.length) { ttToast('Tanlangan kunlarda bu rejimdagi dars yo\'q.', 'warn'); return; }
                        cycDaysApply(key, offs, cycSelModes(key), d, null, { reopen: true, extra: { step: 'jump' } });
                        return;
                    }
                    // Faqat ma'ruza / faqat amaliy — qadam (yonma-yon qism bilan o'rin almashish yoki 1 soat); avval tekshiruv, kerak bo'lsa oyna.
                    if (curMode !== 'both') {
                        cycDaysApply(key, [+offset], curMode, d, null, jumpOk ? { extra: { step: 'jump' }, reopen: true }
                            : { extra: { start_hour: stepBase + d, delta: undefined }, reopen: true });
                        return;
                    }
                    moveCycDay(key, +offset, stepBase + d, (date ? date.d + ' (' + dp.k + '-kun)' : dp.k + '-kun') + ': ' + stepBase + '-soatdan → '
                        + (stepBase + d) + '-soatdan', curMode);
                });
                cycPracPlaceBind(pop, () => openCycDayPop(key, offset, anchor, true));
                // Rejim radiosi: surish rejimi va tanlovga filtr (shu kun tanlovda bo'lsa); tanlov saqlanadi, bo'yoq darhol yangi rejimga mos.
                pop.querySelectorAll('input[name="dpMode"]').forEach(r => r.onchange = () => {
                    cycMoveMode = r.value;
                    if (selHere) cycSelApplyMode(key, r.value);
                    openCycDayPop(key, offset, anchor, true);
                });
                const keySel = pop.querySelector('[data-dp-bothkey]');
                if (keySel) keySel.onchange = () => { setCycBothKey(keySel.value); openCycDayPop(key, offset, anchor, true); };
                const selAll = pop.querySelector('[data-dp-selall]');
                if (selAll) selAll.onclick = () => { cycSelAll(key); openCycDayPop(key, offset, anchor, true); };
            }
            // Fan nomi bosilganda: blok bo'yicha jami soatlar, sanalar, o'qituvchi va xona.
            function openCycSubjPop(key, anchor) {
                closeCycDayPop();
                const block = cycBlockByKey(key);
                if (!block) return;
                cycDaySel = { key: key, offset: -1 };
                const plan = Object.values(block.day_plan || {});
                const sumLec = plan.reduce((a, d) => a + (+d.lec || 0), 0);
                const sumPrc = plan.reduce((a, d) => a + (+d.prc || 0), 0);
                const hasKtr = plan.some(d => d.ktr);
                const dates = cyclePlanData.dates || [];
                const d1 = dates[block.from], d2 = dates[block.to];
                const cmp = (got, plan) => plan == null ? got + ' s' : got + ' / ' + plan + ' s' + (+got !== +plan ? ' <b style="color:#b91c1c">(farq ' + (got - plan) + ')</b>' : '');
                const pop = document.createElement('div');
                pop.id = 'cycDayPop';
                pop.innerHTML =
                    '<div class="dp-head"><div><div class="dp-title">' + esc(block.subject) + '</div>' +
                    '<div class="dp-sub">' + block.days + ' kun' + (d1 && d2 ? ' · ' + esc(d1.d) + ' – ' + esc(d2.d) : '') + '</div></div>' +
                    '<button type="button" class="dp-close" aria-label="Yopish">&times;</button></div>' +
                    '<div class="dp-row"><span class="dp-tag l">M</span><div><b>Ma\'ruza</b> <span class="dp-sub">' + cmp(sumLec, block.lecture_hours) + '</span></div></div>' +
                    '<div class="dp-row"><span class="dp-tag p">A</span><div><b>Amaliy</b> <span class="dp-sub">' + cmp(sumPrc, block.practice_hours) + '</span></div></div>' +
                    '<div class="dp-row"><span style="width:16px;text-align:center">&#128100;</span><div><b>O\'qituvchi:</b> ' + (block.teacher_name ? esc(block.teacher_name) : '<span class="dp-sub">biriktirilmagan</span>') + '</div></div>' +
                    '<div class="dp-row"><span style="width:16px;text-align:center">&#127979;</span><div><b>Xona:</b> ' + (block.auditorium_name || block.auditorium_code ? esc(block.auditorium_name || block.auditorium_code) : '<span class="dp-sub">biriktirilmagan</span>') + '</div></div>' +
                    (hasKtr ? '' : '<div class="dp-note">KTR kiritilmagan — soatlar reja bo\'yicha taxminiy.</div>') +
                    '<div class="dp-actions"><span class="dp-sub">Kun bo\'yicha ma\'lumot uchun M / A katagini bosing.</span></div>';
                document.body.appendChild(pop);
                const r = anchor.getBoundingClientRect();
                pop.style.left = Math.max(8, Math.min(window.innerWidth - pop.offsetWidth - 8, r.left)) + 'px';
                pop.style.top = Math.max(8, Math.min(window.innerHeight - pop.offsetHeight - 8, r.bottom + 6)) + 'px';
                pop.querySelector('.dp-close').onclick = closeCycDayPop;
            }

            const cycLocalToday = () => { const d = new Date(); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); };
            // Soat qatorlari (yarim para) vaqtlari: [qator (1..) => [boshlanish, tugash]] — qo'ng'iroq jadvalidan.
            function cycHourTimes() {
                const pm = t => { const m = /^(\d{1,2}):(\d{2})$/.exec(t || ''); return m ? (+m[1]) * 60 + (+m[2]) : null; };
                const fmt = v => String(Math.floor(v / 60)).padStart(2, '0') + ':' + String(v % 60).padStart(2, '0');
                const out = [null];
                boardSchedule().filter(it => it.type === 'pair' && it.start && it.end).forEach(it => {
                    const a = pm(it.start), b = pm(it.end);
                    if (b - a <= 45) out.push([it.start, it.end]); else { out.push([it.start, fmt(a + 40)]); out.push([fmt(a + 40), it.end]); }
                });
                return out;
            }
            // Sikl darsini boshqa soatga ko'chirish so'rovi: kafedra mudiri, so'ng registrator ofisi tasdiqlagach jadvalga tushadi. Kun
            // o'zgarmaydi (sikl kunlari ketma-ket), faqat boshlanish soati. Amaliy — shu guruhcha (shu kun / blok oxirigacha / tanlangan
            // kunlar); ma'ruza — butun oqim (shu kun / tanlangan kunlar). opts: { kind, days: [{iso, d, k, time, dow}], preselect: [iso] }.
            function openCycleTimeProposal(card, dp, date, opts = {}) {
                const prior = document.getElementById('teacherTimeProposal');
                if (prior) prior.remove();
                const lecture = (opts.kind || card.type) === 'lecture';
                const times = cycHourTimes();
                const prc = +dp.prc || 1, cur = dp.ps != null ? +dp.ps : (+dp.start || 1) + (+dp.lec || 0);
                const maxStart = Math.max(1, Math.min(+(cyclePlanData && cyclePlanData.day_hours) || times.length - 1, times.length - 1) - prc + 1);
                const label = h => (times[h] ? times[h][0] : h + '-soat') + '–' + (times[h + prc - 1] ? times[h + prc - 1][1] : '');
                const days = (opts.days || []).filter(x => x && x.iso);
                const pre = new Set((opts.preselect || []).length ? opts.preselect : [date.iso]);
                const multiStart = pre.size > 1;
                const m = document.createElement('div');
                m.id = 'teacherTimeProposal'; m.className = 'cr-proposal-overlay';
                m.innerHTML = '<form class="cr-proposal-form"><h3 class="font-bold text-lg">Vaqtini o‘zgartirishni so‘rash</h3>' +
                    '<p>' + esc(card.subject) + ' · ' + esc(card.group) + ' · ' + (lecture ? 'ma’ruza' : 'amaliy') + ' (sikl)</p>' +
                    (lecture ? '<p class="text-sm font-semibold text-amber-700" data-flow>Ma’ruza butun oqim uchun o‘zgaradi.</p>' : '') +
                    '<p class="text-sm">' + esc(date.d) + ' (' + dp.k + '-kun) · hozir: ' + esc(label(cur)) + '</p>' +
                    '<p class="text-sm">Avval kafedra mudiri, keyin registrator ofisi yoki o‘quv bo‘limi tasdiqlaydi. Shu vaqtgacha jadval o‘zgarmaydi. Kun, guruh, fan, xona va o‘qituvchi o‘zgarmaydi.</p>' +
                    // Sudrab ochilganda (opts.start) — yangi vaqt oldindan tanlangan; aks holda hozirgi.
                    '<label>Yangi boshlanish vaqti<select name="start_hour" required>' + Array.from({ length: maxStart }, (_, i) => i + 1)
                        .map(h => '<option value="' + h + '"' + (h === (opts.start >= 1 && opts.start <= maxStart ? +opts.start : cur) ? ' selected' : '') + '>'
                            + esc(label(h)) + '</option>').join('') + '</select></label>' +
                    // Ma'ruza: yangi vaqtni to'sib turgan amaliyot qayerga o'tadi (kun oynasidagi sozlama sukut bo'yicha) — tasdiqlansa birga.
                    (lecture ? (() => {
                        const pp = cycPracPlace(), cur = pp.on ? pp.how : 'keep';
                        const pairs = boardSchedule().filter(it => it.type === 'pair');
                        return '<label>To‘sib turgan amaliyot<select name="practice_place">' + [['swap', 'O‘rin almashish (ma’ruzaning bo‘shagan joyiga)'],
                            ['after', 'Ma’ruzadan keyin'], ['gap', 'Oraliq bilan'], ['pair', 'Aniq para'], ['keep', 'Tegmaslik (kesishsa — xato)']]
                            .map(([v, t]) => '<option value="' + v + '"' + (v === cur ? ' selected' : '') + '>' + t + '</option>').join('') + '</select></label>'
                            + '<label data-pp-gap' + (cur === 'gap' ? '' : ' hidden') + '>Necha para oraliq<input type="number" name="practice_gap" min="0" max="6" value="' + pp.gap + '"></label>'
                            + '<label data-pp-pair' + (cur === 'pair' ? '' : ' hidden') + '>Qaysi paradan<select name="practice_pair">' + pairs.map((it, i) => '<option value="' + (i + 1) + '"'
                                + (i + 1 === pp.pair ? ' selected' : '') + '>' + esc((it.abbr && it.abbr !== '—' ? it.abbr : i + 1) + ' para' + (it.start ? ' (' + it.start + ')' : '')) + '</option>').join('') + '</select></label>'
                            + '<p class="text-sm text-teal-700" data-swaps></p>';
                    })() : '') +
                    '<label>Qaysi kunlar<select name="scope"><option value="day"' + (multiStart ? '' : ' selected') + '>Faqat shu kun</option>' +
                        (lecture ? '' : '<option value="rest">Shu kundan blok oxirigacha</option>') +
                        (days.length > 1 ? '<option value="multi"' + (multiStart ? ' selected' : '') + '>Bir nechta kunni tanlash</option>' : '') + '</select></label>' +
                    (days.length > 1 ? '<div class="cr-days" data-days' + (multiStart ? '' : ' hidden') + '>' + days.map(x => '<label data-day="' + esc(x.iso) + '"><input type="checkbox" value="'
                        + esc(x.iso) + '"' + (pre.has(x.iso) ? ' checked' : '') + '> ' + esc(x.d + ' · ' + x.dow + (x.k ? ' · ' + x.k + '-kun' : '') + ' · hozir ' + x.time) + '</label>').join('')
                        + '<span class="text-xs text-slate-500">Bitta yangi vaqt barcha tanlangan kunlarga — bitta so‘rov, tasdiqda hammasi birga qo‘llanadi.</span></div>' : '') +
                    '<label>O‘zgarish sababi<textarea name="reason" required maxlength="1000" rows="3"></textarea></label>' +
                    '<p role="alert" class="text-red-600"></p><button type="button" data-recheck>Vaqtni qayta tekshirish</button><div class="flex justify-end gap-3"><button type="button" data-close>Bekor</button>' +
                    '<button type="submit" class="px-3 py-2 bg-blue-600 text-white rounded">Taklif yuborish</button></div></form>';
                document.body.appendChild(m);
                m.querySelector('[data-close]').onclick = () => m.remove();
                m.onclick = ev => { if (ev.target === m) m.remove(); };
                const form = m.querySelector('form');
                const box = m.querySelector('[data-days]');
                const picked = () => box ? [...box.querySelectorAll('input:checked')].map(i => i.value).sort() : [];
                const body = () => {
                    const b = { specialty_name: card.specialty, course: card.course, subject_name: card.subject, group_name: card.group,
                        start_hour: form.elements.start_hour.value, training_type: lecture ? 'lecture' : 'practice' };
                    if (lecture) {
                        const pl = form.elements.practice_place.value;
                        Object.assign(b, { practice_place: pl }, pl === 'gap' ? { practice_gap: form.elements.practice_gap.value } : {},
                            pl === 'pair' ? { practice_pair: form.elements.practice_pair.value } : {});
                    }
                    const sc = form.elements.scope.value;
                    return sc === 'multi' ? Object.assign(b, { dates: picked() }) : Object.assign(b, { date: date.iso, scope: sc });
                };
                let seq = 0;
                const check = async () => {
                    const my = ++seq, button = form.querySelector('[type="submit"]'), status = form.querySelector('[role="alert"]');
                    button.disabled = true;
                    if (box) box.querySelectorAll('.cr-day-bad').forEach(x => x.classList.remove('cr-day-bad'));
                    if (form.elements.scope.value === 'multi' && !picked().length) {
                        status.className = 'text-red-600'; status.textContent = 'Kamida bitta kunni tanlang.'; return;
                    }
                    status.className = 'text-slate-600'; status.textContent = 'Vaqt tekshirilmoqda…';
                    try {
                        const r = await api(BASE + '/boards/' + board.id + '/cycle-time-proposal/check', 'POST', body());
                        if (my !== seq || !m.isConnected) return;
                        status.className = 'text-green-700'; status.textContent = r.message + ' ' + r.old + ' → ' + r.new;
                        const sw = m.querySelector('[data-swaps]');
                        if (sw) sw.textContent = r.swaps || '';
                        // Ma'ruza: oqimdagi guruhchalar (server ro'yxati) — "Ma'ruza butun oqim uchun o'zgaradi: 05a, 05b … (N guruhcha)".
                        const fl = m.querySelector('[data-flow]');
                        if (fl && (r.units || []).length) {
                            const lb = lectureLabel('', r.units);
                            fl.textContent = 'Ma’ruza butun oqim uchun o‘zgaradi: ' + lb.text.replace(/^Ma'ruza · oqim \(/, '').replace(/\)$/, '') + ' (' + r.units.length + ' guruhcha)';
                            fl.title = lb.title;
                        }
                        button.disabled = false;
                    } catch (e) {
                        if (my !== seq || !m.isConnected) return;
                        const sw0 = m.querySelector('[data-swaps]');
                        if (sw0) sw0.textContent = '';
                        // Ko'p kunli: muammoli kunlar ("12.11: …") belgilanadi — shu kunni olib tashlab qayta tekshiring.
                        const bad = form.elements.scope.value === 'multi' ? String(e.message).split('\n').map(l => (/^(\d{2}\.\d{2}):/.exec(l) || [])[1]).filter(Boolean) : [];
                        if (box) bad.forEach(dm => box.querySelectorAll('label[data-day]').forEach(l => { if (l.dataset.day.slice(8, 10) + '.' + l.dataset.day.slice(5, 7) === dm) l.classList.add('cr-day-bad'); }));
                        status.className = 'text-red-600';
                        status.textContent = e.message + (bad.length ? '\nQizil belgilangan kun(lar)ni olib tashlab, qayta tekshiring.' : '');
                    }
                };
                m.querySelector('[data-recheck]').onclick = check;
                form.elements.start_hour.onchange = check;
                if (lecture) {
                    form.elements.practice_place.onchange = () => {
                        m.querySelector('[data-pp-gap]').hidden = form.elements.practice_place.value !== 'gap';
                        m.querySelector('[data-pp-pair]').hidden = form.elements.practice_place.value !== 'pair';
                        check();
                    };
                    form.elements.practice_gap.onchange = check;
                    form.elements.practice_pair.onchange = check;
                }
                form.elements.scope.onchange = () => { if (box) box.hidden = form.elements.scope.value !== 'multi'; check(); };
                if (box) box.onchange = check;
                check();
                form.onsubmit = async ev => {
                    ev.preventDefault();
                    const button = form.querySelector('[type="submit"]');
                    button.disabled = true;
                    try {
                        const r = await api(BASE + '/boards/' + board.id + '/cycle-time-proposal', 'POST', Object.assign(body(), { reason: form.elements.reason.value }));
                        m.remove();
                        // To'qnashuvdagi kunlar darhol joylangan bo'lishi mumkin: "2 kun darhol joylandi, 3 kun — so'rov #…".
                        ttToast(esc(r.message || ''), 'ok');
                        await loadChangeRequests();
                        if ((r.applied_days || []).length) await loadCyclePlan();
                    } catch (e) { form.querySelector('[role="alert"]').className = 'text-red-600'; form.querySelector('[role="alert"]').textContent = e.message; button.disabled = false; }
                };
            }

            async function moveCycDay(key, offset, newStart, hint, mode) {
                const card = (cyclePlanData && cyclePlanData.cycle_cards || []).find(item => item.key === key);
                const block = cycBlockByKey(key);
                const dp = block && block.day_plan ? block.day_plan[offset] : null;
                if (!card || !dp) return;
                cycBusyShow(key, [offset], mode || 'both', 'saqlanmoqda…');
                try {
                    const res = await api(BASE + '/boards/' + board.id + '/cycle-lecture-slots', 'POST', {
                        specialty_name: card.specialty, course: card.course,
                        group_name: card.group, subject_name: card.subject,
                        training_type: card.type || 'practice', view: cycleEffView(), placement_group: (card && card.placement_group) || undefined,
                        sub_group: card.placement_group && card.placement_group !== card.group ? card.group : undefined,
                        day_index: dp.k - 1, start_hour: newStart, mode: mode || 'both',
                        _change_hint: hint || undefined,
                    }, { timeout: CYC_DAYS_TIMEOUT_MS });
                    cycBusyHide();
                    if (res && res.pending_approval) {
                        // So'rov bo'ldi: umumiy qayta yuklash o'rniga shu yerda — oyna so'ralgan soat bilan qayta ochiladi.
                        clearTimeout(pendingReloadTimer);
                        await loadChangeRequests();
                    }
                    await loadCyclePlan();
                    if (res && res.today_moved) ttToast(esc(res.hemis_hint || TT_HEMIS_HINT), 'warn');
                    const cells = document.querySelectorAll('#cycleGrid .cyc-mk-cell[data-mk-key="' + CSS.escape(key) + '"][data-mk-day="' + offset + '"]');
                    // O'zgargan kun ustuni bir necha soniya yonib turadi — nima o'zgargani ko'rinsin.
                    cells.forEach(c => { c.classList.remove('cyc-just-changed'); void c.offsetWidth; c.classList.add('cyc-just-changed'); });
                    setTimeout(() => cells.forEach(c => c.classList.remove('cyc-just-changed')), 2600);
                    const cell = cells[0];
                    if (cell) openCycDayPop(key, offset, cell);
                } catch (e) {
                    cycBusyHide();
                    if (cycTimedOut(e)) { try { await loadCyclePlan(); } catch (_) { } }
                    alert('Kun soatini o\'zgartirib bo\'lmadi: ' + cycErrText(e));
                }
            }

            // To'qnashuv tafsilotlari: har biri bitta qator (kim/nima, qachon, nima qilish kerak). Ma'ruza havolasi — egasi blokiga.
            function openCfPop(el) {
                let key = el.dataset.cfKey;
                if (el.dataset.cfLecture) {
                    key = cfOwners[el.dataset.cfLecture];
                    const target = key && document.querySelector('#cycleGrid [data-cf-key="' + CSS.escape(key) + '"]');
                    if (target) { target.scrollIntoView({ block: 'center', inline: 'center' }); el = target; }
                }
                // Jadvaldagi blok; bo'lmasa (panel kartasi) — sikl kartasining o'z ro'yxati.
                const pc = key && !cfBlocks[key] ? ((cyclePlanData && cyclePlanData.cycle_cards) || []).find(c => c.key === key) : null;
                const b = key && (cfBlocks[key] || (pc ? { key: pc.key, subject: pc.subject, group: pc.group, conflicts: pc.conflicts || [] } : null));
                if (!b) return;
                closeCycDayPop();
                const own = cfMergeItems(cfSplit(key, b.conflicts, cfOwners).own);
                const pop = document.createElement('div');
                pop.id = 'cycDayPop';
                pop.innerHTML = '<div class="dp-head"><div><div class="dp-title">' + esc(b.subject) + '</div><div class="dp-sub">' + esc(b.group) + ' · to\u2018qnashuvlar</div></div>' +
                    '<button type="button" class="dp-close" aria-label="Yopish">&times;</button></div>' +
                    // Turlarga ajratilgan bloklar (haftalik oynadagidek): [Ko'rsatish] — xona / o'qituvchining shu kungi darslari, guruh darslari;
                    // qatorlarda o'qituvchi jadvali havolasi (ko'chiriladigan dars — shu blokning to'qnashuv sanasidagi amaliyoti).
                    cycCfBlocksHtml(own, key) +
                    // Amallar: bo'sh smenaga o'tkazish, boshqa o'qituvchi, vaqtincha kafedra mudiri; o'qituvchi / xona havolalari.
                    cycActionsHtml(cycCardOf(key), own);
                document.body.appendChild(pop);
                // Joy: pastda sig'masa — yuqoriga; kontent (maslahat, forma) o'zgarsa qayta hisoblanadi.
                const reposition = cycPopWatch(pop, el);
                cycActionsBind(pop, cycCardOf(key), own, reposition);
                cycCfBlocksBind(pop, own, cycCardOf(key) || pc, reposition, key);
                loadShiftAdvice(pop, key, own);
                pop.querySelector('.dp-close').onclick = closeCycDayPop;
            }

            // "Smenani almashtiring" (o'qituvchi ikki sikl amaliyotida band): guruhchaning smena variantlari blok sanalarida serverda
            // tekshiriladi — oyna ochilganda bir marta (har chizishda emas); javob kelguncha server ko'rsatmasi turadi.
            const cfWantsShiftAdvice = i => i.kind === 'teacher_busy' && !i.lecture && !i.past;
            async function loadShiftAdvice(pop, key, items) {
                // Qator — to'qnashuv tartib raqami bo'yicha (data-cf-i; bloklarda qatorlar turi bo'yicha guruhlangan — joyi boshqacha).
                const lis = [...pop.querySelectorAll('.cf-list > li')];
                const liOf = n => lis.find(li => li.dataset && li.dataset.cfI === String(n)) || lis[n];
                const spans = (items || []).map((i, n) => (cfWantsShiftAdvice(i) && liOf(n) ? liOf(n).querySelector('.cf-todo') : null)).filter(Boolean);
                if (!spans.length || !key) return;
                spans.forEach(sp => sp.classList.add('cf-checking'));
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/cycle-shift-advice', 'POST', { key });
                    const a = j && j.advice;
                    if (a && a.text) spans.forEach(sp => { sp.textContent = '→ ' + a.text; sp.dataset.advice = a.kind || ''; });
                    if (pop._onAdvice) pop._onAdvice(a || null);   // "Bo'sh smenaga o'tkazish" tugmasi
                } catch (e) {
                    console.warn('Smena maslahati olinmadi:', e);   // server ko'rsatmasi qoladi
                    if (pop._onAdvice) pop._onAdvice(null);
                } finally {
                    spans.forEach(sp => sp.classList.remove('cf-checking'));
                }
            }

            // ===== Sikl amallari (to'qnashuv oynasi va "Sikl fan kartalari" kartasi) =====
            // "Bo'sh smenaga o'tkazish" (smena maslahati bo'yicha; o'qituvchi, xona va vaqt saqlanadi), "Boshqa o'qituvchi" (biriktirish
            // oynasi), "Vaqtincha kafedra mudiriga yozish" (butun blok yoki faqat to'qnashuv sanalari) va "Asl holatga qaytarish";
            // joylanmagan kartaga — "Joylash uchun tanlash" va "Tashqi jadvaldagi joyiga joylash"; o'qituvchi / xona — jadval havolasi.
            // Huquq (haftalikdagidek): admin / registrator — darhol; kafedra mudiri — o'z kafedrasi (server tekshiradi); o'qituvchi va
            // fan mas'uli — tugmalar yo'q (kun oynasida "Vaqtini o'zgartirishni so'rash"). Faqat ichki jadval.
            let cycPopState = null;   // { pop, el, reposition, ro, outside } — ochiq oyna (yopilganda tinglovchilar olinadi)
            let cycExtCache = null;   // { data: cyclePlanData, p: Promise<tashqi qatlam rejasi> }
            function cycCardOf(key) {
                const list = (typeof cyclePlanData !== 'undefined' && cyclePlanData && cyclePlanData.cycle_cards) || [];
                return list.find(c => c.key === key) || null;
            }
            function cycActAllowed() {
                return typeof TIMETABLE_READ_ONLY !== 'undefined' && !TIMETABLE_READ_ONLY && !!cyclePlanData && cyclePlanData.layer === 'internal'
                    && ((typeof WEEKLY_ADMIN !== 'undefined' && WEEKLY_ADMIN) || TIMETABLE_ROLE === 'kafedra_mudiri');
            }
            function cycCardBody(card) {
                return { specialty_name: card.specialty, course: card.course, group_name: card.group, subject_name: card.subject,
                    training_type: card.type || 'practice', view: cycleEffView(), placement_group: card.placement_group || undefined, layer: 'internal' };
            }
            // Joy: element ostida; pastda sig'masa — yuqoriga (pastki cheti element tepasida); so'ng ekran ichiga siqiladi. Balandligi
            // ekrandan oshmaydi (CSS max-height, ichida scroll). Kontent o'zgarsa (maslahat, xabar, forma), oyna o'lchami va scroll'da qayta.
            function cycPopPlace(pop, el) {
                if (!pop || !pop.style) return;
                const W = window.innerWidth || 1024, H = window.innerHeight || 768;
                const w = pop.offsetWidth || 280, h = Math.min(pop.offsetHeight || 120, H - 16);
                const r = el && el.getBoundingClientRect && el.isConnected !== false ? el.getBoundingClientRect() : (cycPopPlace.last || { left: 8, top: 8, bottom: 8 });
                cycPopPlace.last = r;
                const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
                let top = (r.bottom || 0) + 6;
                if (top + h > H - 8) top = (r.top !== undefined ? r.top : (r.bottom || 0)) - h - 6;   // pastda joy yo'q — yuqoriga
                pop.style.left = Math.round(clamp(r.left || 0, 8, Math.max(8, W - w - 8))) + 'px';
                pop.style.top = Math.round(clamp(top, 8, Math.max(8, H - h - 8))) + 'px';
            }
            function cycPopWatch(pop, el) {
                cycPopUnwatch();
                const reposition = () => cycPopPlace(pop, el);
                const outside = ev => { if (!pop.contains || pop.contains(ev.target) || (el && el.contains && el.contains(ev.target))) return; if (!cycDaySel) closeCycDayPop(); };
                cycPopState = { pop, reposition, ro: null, outside };
                if (typeof ResizeObserver === 'function') { cycPopState.ro = new ResizeObserver(reposition); cycPopState.ro.observe(pop); }
                if (window.addEventListener) { window.addEventListener('resize', reposition); window.addEventListener('scroll', reposition, true); }
                if (document.addEventListener) setTimeout(() => { if (cycPopState && cycPopState.pop === pop) document.addEventListener('mousedown', outside, true); }, 0);
                reposition();
                return reposition;
            }
            function cycPopUnwatch() {
                if (!cycPopState) return;
                if (window.removeEventListener) { window.removeEventListener('resize', cycPopState.reposition); window.removeEventListener('scroll', cycPopState.reposition, true); }
                if (document.removeEventListener) document.removeEventListener('mousedown', cycPopState.outside, true);
                if (cycPopState.ro) cycPopState.ro.disconnect();
                cycPopState = null;
            }
            // Jadval sanasi: kelgusi to'qnashuv sanasi, bo'lmasa blok boshi, bo'lmasa bugun.
            function cycCardDate(card, own) {
                const it = (own || []).find(i => !i.past && i.date_from);
                const d = cyclePlanData && cyclePlanData.dates && card.start_index !== null && card.start_index !== undefined ? cyclePlanData.dates[card.start_index] : null;
                return (it && it.date_from) || (d && d.iso) || new Date().toISOString().slice(0, 10);
            }
            // Belgilar: amaliy (mudir_ph) va oqim ma'ruzasi (mudir_ph_lec) — har biri mudir, xona, asl o'qituvchi, sanalar; qaytarish — ikkalasi.
            function cycPhHtml(card) {
                const one = (ph, what) => {
                    const ds = ph.dates && ph.dates.length ? ph.dates.map(cfDate).join(', ') : 'butun blok';
                    return '<div><b>Vaqtincha kafedra mudirida' + what + ':</b> ' + esc(ph.mudir_name || ph.teacher_name || '') +
                        (ph.room_name ? ' · ' + esc(ph.room_name) : '') + '<div>Asl o‘qituvchi: ' + esc(ph.orig_teacher_name || '—') +
                        (ph.orig_room_name ? ', asl xona: ' + esc(ph.orig_room_name) : '') + '; sanalar: ' + esc(ds) + '</div>' +
                        (ph.reason ? '<div>Sabab: ' + esc(ph.reason) + '</div>' : '') +
                        (ph.by_name || ph.at ? '<div class="dp-sub">' + esc([ph.by_name, String(ph.at || '').slice(0, 16)].filter(Boolean).join(', ')) + '</div>' : '') + '</div>';
                };
                const ph = card && card.mudir_ph, lec = card && card.mudir_ph_lec;
                if (!ph && !lec) return '';
                return '<div class="cyc-ph" data-cyc-ph>' + (ph ? one(ph, lec ? ' (amaliy)' : '') : '') +
                    (lec ? one(lec, ' (ma‘ruza — butun oqim' + ((lec.units || []).length ? ', ' + lec.units.length + ' guruhcha' : '') + ')') : '') +
                    (cycActAllowed() ? '<button type="button" data-cyc-ph-revert>Asl holatga qaytarish</button>' : '') + '</div>';
            }
            function cycActionsHtml(card, own) {
                if (!card) return '';
                const t = card.teacher, r = card.room;
                const edit = typeof TIMETABLE_READ_ONLY !== 'undefined' && !TIMETABLE_READ_ONLY;
                let btns = '';
                if (!card.placed) {
                    if (edit) btns += '<button type="button" data-cyc-select>Joylash uchun tanlash</button><button type="button" data-cyc-ext hidden>Tashqi jadvaldagi joyiga joylash</button>'
                        // Tugma ko'rinmasa — sababi (tashqi qatlam tanlangan yoki tashqi jadvalda joyi yo'q).
                        + '<div data-cyc-ext-why class="dp-sub" hidden style="width:100%;font-size:11px"></div>';
                } else if (cycActAllowed() && card.type !== 'lecture') {
                    if ((own || []).some(cfWantsShiftAdvice)) btns += '<button type="button" data-cyc-shift disabled title="tekshirilmoqda…">Bo‘sh smenaga o‘tkazish</button>';
                    btns += '<button type="button" data-cyc-teacher>Boshqa o‘qituvchi</button>';
                    // Amaliy yoki ma'ruza to'qnashuvi hali mudirga yozilmagan bo'lsa.
                    // Yozish — faqat jadval administratorlari (kafedra mudiri — yo'q; qaytarish — bor).
                    if (typeof WEEKLY_ADMIN !== 'undefined' && WEEKLY_ADMIN && (own || []).some(i => !i.past && (i.lecture ? !card.mudir_ph_lec : !card.mudir_ph))) btns += '<button type="button" data-cyc-mudir>Vaqtincha kafedra mudiriga yozish</button>';
                }
                return '<div class="cyc-links"><div><span class="dp-sub">O‘qituvchi:</span> ' +
                    (t && t.id ? '<a href="#" class="tt-agenda-link" data-cyc-agenda="t">' + esc(t.name) + '</a>' : '<i>biriktirilmagan</i>') + '</div>' +
                    '<div><span class="dp-sub">Xona:</span> ' + (r && r.code ? '<a href="#" class="tt-agenda-link" data-cyc-agenda="r">' + esc(r.name) + '</a>' : '<i>biriktirilmagan</i>') + '</div></div>' +
                    cycPhHtml(card) + '<div data-cyc-msg class="cyc-msg"></div>' + (btns ? '<div class="cyc-acts">' + btns + '</div>' : '') + '<div data-cyc-form></div>';
            }
            // Tashqi qatlamdagi joyi (o'quv bo'limi jadvali): shu oqim qatori va fan bloki boshi — kalendar indeksi yoki null.
            async function cycExtPlace(card) {
                if (!cycExtCache || cycExtCache.data !== cyclePlanData) {
                    const body = Object.assign(scopeBody(), { layer: 'external', holidays: cycleHolidays, view: 'flow' });
                    if ($('cycleStart').value) body.start_date = $('cycleStart').value;
                    cycExtCache = { data: cyclePlanData, p: api(BASE + '/boards/' + board.id + '/cycle-plan', 'POST', body) };
                }
                const j = await cycExtCache.p;
                const base = s => String(s || '').replace(/\s*\([a-z]\)\s*$/i, '').trim().toLowerCase();
                for (const row of (j && j.rows) || []) {
                    if (row.group !== card.placement_group && !(row.subgroups || []).includes(card.group)) continue;
                    const b = (row.blocks || []).find(x => base(x.subject) === base(card.subject));
                    if (b && b.from !== undefined && b.from !== null) return +b.from;
                }
                return null;
            }
            function cycSelectForPlace(key) {
                cycleDragKey = key;
                $('cardPanel').querySelectorAll('.cycle-pn-card').forEach(o => o.classList.toggle('cycle-pn-selected', o.dataset.cycleKey === key));
                highlightCycleRow(key);
                // Jadval guruh qatoriga suriladi (gorizontal + vertikal): birinchi bo'sh (blok emas) katak, bo'lmasa qatorning birinchi katagi.
                const rows = [...$('cycleGrid').querySelectorAll('.cyc-pick-row')];
                const target = rows.find(x => !x.classList.contains('cyc-block')) || rows[0];
                if (target && target.scrollIntoView) target.scrollIntoView({ block: 'center', inline: 'center' });
                // Qatori hozirgi filtrda (oqim filtri) yo'q — "Guruhni ko'rsatish": filtr tozalanib qayta chiziladi.
                if (!rows.length && typeof cycleGroupFilter !== 'undefined' && cycleGroupFilter) {
                    $('cycleMsg').innerHTML = 'Bu guruh hozirgi filtrda ko\'rinmaydi — <button type="button" data-cyc-pick-show style="border:1px solid #2563eb;border-radius:5px;padding:0 8px;color:#1d4ed8;background:#fff">Guruhni ko\'rsatish</button>';
                    $('cycleMsg').querySelector('[data-cyc-pick-show]').onclick = async () => {
                        cycleGroupFilter = '';
                        if ($('cycleGroupFilter')) $('cycleGroupFilter').value = '';
                        await loadCyclePlan();
                        cycSelectForPlace(key);
                    };
                    return;
                }
                $('cycleMsg').textContent = 'Endi shu oqim qatoridagi boshlanish kunini bosing.';
            }
            async function cycPhRevert(card, btn) {
                if (btn) btn.disabled = true;
                try {
                    await api(BASE + '/boards/' + board.id + '/cycle-mudir-placeholder/revert', 'POST', Object.assign(cycCardBody(card), { key: card.key }));
                    closeCycDayPop();
                    ttToast('<b>Asl holatga qaytarildi</b><div>' + esc(card.group + ' · ' + card.subject) + ' — asl o‘qituvchi va xona</div>', 'ok');
                    await loadCyclePlan();
                } catch (e) {
                    if (btn) btn.disabled = false;
                    alert('Qaytarib bo‘lmadi: ' + e.message);
                }
            }
            function cycActionsBind(pop, card, own, reposition) {
                if (!pop || !pop.addEventListener || !card) return;
                const msg = (html, bad) => {
                    const m = pop.querySelector('[data-cyc-msg]');
                    if (m) { m.style.color = bad ? '#b91c1c' : '#166534'; m.innerHTML = html; }
                    reposition();
                };
                const form = html => { const f = pop.querySelector('[data-cyc-form]'); if (f) f.innerHTML = html || ''; reposition(); };
                // Smena maslahati (loadShiftAdvice) — tugma holati: bo'sh / qisman bo'lsa faol, smena nomi bilan.
                pop._onAdvice = a => {
                    pop._advice = a;
                    const b = pop.querySelector('[data-cyc-shift]');
                    if (!b) return;
                    const ok = !!(a && (a.kind === 'free' || a.kind === 'partial') && +a.start > 0);
                    b.disabled = !ok;
                    b.title = a && a.text ? a.text : 'maslahat olinmadi';
                    if (ok && a.label) b.textContent = 'Bo‘sh smenaga o‘tkazish — ' + a.label;
                    reposition();
                };
                const futureDates = () => {
                    const ds = new Set();
                    (own || []).filter(i => !i.past && !i.lecture && i.date_from).forEach(i => ds.add(i.date_from + (i.date_to && i.date_to !== i.date_from ? '–' + i.date_to : '')));
                    return [...ds].map(x => x.split('–').map(cfDate).join('–')).join(', ');
                };
                async function doShift(force) {
                    const a = pop._advice;
                    if (!a) return;
                    form('');
                    msg('Saqlanmoqda…');
                    try {
                        const o = await api(BASE + '/boards/' + board.id + '/cycle-assign-options', 'POST',
                            Object.assign(cycCardBody(card), { start_date: $('cycleStart').value, holidays: cycleHolidays }));
                        const cur = (o && o.current) || {};
                        const res = await api(BASE + '/boards/' + board.id + '/cycle-assign', 'POST', Object.assign(cycCardBody(card), {
                            teacher_id: cur.teacher_id ? +cur.teacher_id : null, auditorium_code: cur.auditorium_code || null, lesson_time: cur.lesson_time || null,
                            shift_start: +a.start, start_date: $('cycleStart').value, holidays: cycleHolidays, force: force ? 1 : undefined }));
                        const rest = (a.remaining || []).map(r => cfDate(r.date));
                        msg(res && res.pending_approval ? 'So‘rov yuborildi — tasdiq kutilmoqda.'
                            : '✓ ' + esc(a.label || '') + ' ga o‘tkazildi' + (rest.length ? '; to‘qnashuv faqat ' + esc(rest.join(', ')) + ' da qoldi' : ' — to‘qnashuv yo‘q'));
                        const b = pop.querySelector('[data-cyc-shift]');
                        if (b) b.remove();
                        await loadCyclePlan();
                    } catch (e) {
                        if (e.data && e.data.needs_confirm) {
                            msg('');
                            form('<div class="cyc-confirm"><div>' + esc(e.message) + '</div><button type="button" data-cyc-confirm="shift">Baribir o‘tkazish</button> <button type="button" data-cyc-cancel>Bekor</button></div>');
                        } else msg(esc(e.message), true);
                    }
                }
                pop.addEventListener('click', async ev => {
                    const t = ev.target && ev.target.closest ? ev.target.closest('[data-cyc-agenda],[data-cyc-select],[data-cyc-ext],[data-cyc-shift],[data-cyc-teacher],[data-cyc-mudir],[data-cyc-mudir-save],[data-cyc-ph-revert],[data-cyc-confirm],[data-cyc-cancel]') : null;
                    if (!t || t.disabled) return;
                    ev.preventDefault();
                    ev.stopPropagation();
                    const date = cycCardDate(card, own);
                    if (t.dataset.cycAgenda === 't') { closeCycDayPop(); ttAgendaOpen({ teacher_id: +card.teacher.id, teacher_name: card.teacher.name, date, range: 'day' }); return; }
                    if (t.dataset.cycAgenda === 'r') { closeCycDayPop(); ttAgendaOpen({ room_code: card.room.code, room_name: card.room.name, date, range: 'week' }); return; }
                    if (t.hasAttribute('data-cyc-select')) { closeCycDayPop(); cycSelectForPlace(card.key); return; }
                    if (t.hasAttribute('data-cyc-ext')) { closeCycDayPop(); placeCycleCardAt(card, +t.dataset.from, 1); return; }
                    if (t.hasAttribute('data-cyc-teacher')) { closeCycDayPop(); openCycleAssign(card.key); return; }
                    if (t.hasAttribute('data-cyc-ph-revert')) { cycPhRevert(card, t); return; }
                    if (t.hasAttribute('data-cyc-cancel')) { form(''); return; }
                    if (t.dataset.cycConfirm === 'shift') { doShift(true); return; }
                    if (t.hasAttribute('data-cyc-shift')) {
                        const a = pop._advice;
                        if (a && a.kind === 'partial') {
                            // Qisman: qoladigan sanalar (va kim bilan) — tasdiqdan keyin o'tkaziladi.
                            form('<div class="cyc-confirm"><div><b>' + esc(a.label || '') + ' ga o‘tkazilsa</b> to‘qnashuv faqat shu sanalarda qoladi:</div><ul data-cyc-remaining>' +
                                (a.remaining || []).map(r => '<li>' + esc(cfDate(r.date)) + ((r.with || []).length ? ' — ' + esc(r.with.slice(0, 3).join('; ')) + (r.with.length > 3 ? ' +' + (r.with.length - 3) + ' ta' : '') : '') + '</li>').join('') +
                                '</ul><button type="button" data-cyc-confirm="shift">O‘tkazish</button> <button type="button" data-cyc-cancel>Bekor</button></div>');
                        } else doShift(false);
                        return;
                    }
                    if (t.hasAttribute('data-cyc-mudir')) {
                        const fd = futureDates();
                        // Ma'ruza oqim darajasida: belgi oqimdagi barcha guruhchalarga tegadi — ogohlantirish (guruhchalar soni bilan).
                        const flowN = ((cyclePlanData && cyclePlanData.cycle_cards) || []).filter(x => x.subject === card.subject
                            && (x.placement_group || x.group) === (card.placement_group || card.group)).length;
                        const lecWarn = !card.mudir_ph_lec;   // ma'ruza belgisi hali yo'q — yozishda ma'ruza ham o'tishi mumkin
                        form('<div class="cyc-confirm"><div><b>Vaqtincha kafedra mudiriga yozish</b> — o‘qituvchi ham, xona ham: fan kafedrasi mudiri va «Kafedra mudiri xonasi»; asl o‘qituvchi, xona va smena saqlanadi. Kafedra mudiriga xabar yuboriladi.</div>' +
                            (lecWarn ? '<div class="cyc-warn" style="margin-top:4px;color:#92400e"><b>Diqqat:</b> ma‘ruza bo‘lsa, u butun oqim' + (flowN > 1 ? ' (' + flowN + ' guruhcha)' : '') +
                                ' uchun kafedra mudiriga o‘tadi (“Butun blok” — barcha kunlari, “Faqat to‘qnashuv sanalari” — ma‘ruza to‘qnashuvi sanalari).</div>' : '') +
                            '<label><input type="radio" name="cycPhScope" value="conflicts" checked> Faqat to‘qnashuv sanalari' + (fd ? ' (' + esc(fd) + ')' : '') + '</label><br>' +
                            '<label><input type="radio" name="cycPhScope" value="all"> Butun blok</label>' +
                            '<input type="text" data-cyc-reason maxlength="500" placeholder="Sabab (ixtiyoriy)" style="width:100%;margin-top:4px">' +
                            '<div style="margin-top:4px"><button type="button" data-cyc-mudir-save>Yozish</button> <button type="button" data-cyc-cancel>Bekor</button></div></div>');
                        return;
                    }
                    if (t.hasAttribute('data-cyc-mudir-save')) {
                        const scope = (pop.querySelector('input[name="cycPhScope"]:checked') || {}).value || 'conflicts';
                        const reason = (pop.querySelector('[data-cyc-reason]') || {}).value || '';
                        t.disabled = true;
                        try {
                            const res = await api(BASE + '/boards/' + board.id + '/cycle-mudir-placeholder', 'POST', Object.assign(cycCardBody(card), { key: card.key, scope, reason }));
                            closeCycDayPop();
                            ttToast('<b>' + (typeof mudirNotifiedText === 'function' ? mudirNotifiedText(res) : 'Vaqtincha kafedra mudiriga yozildi') + '</b><div>' + esc(card.group + ' · ' + card.subject) + (scope === 'all' ? ' — butun blok' : ' — to‘qnashuv sanalari')
                                + (res && res.lecture ? ' (ma‘ruza ham — butun oqim)' : '') + '</div>', 'ok');
                            await loadCyclePlan();
                        } catch (e) { t.disabled = false; msg(esc(e.message), true); }
                    }
                });
                // Joylanmagan karta: tashqi jadvaldagi joyi bo'lsa — "Tashqi jadvaldagi joyiga joylash (sana)".
                const extBtn = pop.querySelector('[data-cyc-ext]');
                const extWhy = pop.querySelector('[data-cyc-ext-why]');
                const sayExtWhy = text => { if (extWhy) { extWhy.textContent = text; extWhy.hidden = false; reposition(); } };
                if (extBtn && extBtn.setAttribute && typeof cycleLayer !== 'undefined' && cycleLayer === 'external') sayExtWhy("Tashqi jadval tanlangan — Ichki'ga o'ting");
                else if (extBtn && extBtn.setAttribute) cycExtPlace(card).then(from => {
                    if (!pop.isConnected) return;
                    if (from === null) { sayExtWhy("Tashqi jadvalda joyi yo'q — 'Joylash uchun tanlash'dan foydalaning"); return; }
                    const d = cyclePlanData && cyclePlanData.dates ? cyclePlanData.dates[from] : null;
                    extBtn.dataset.from = String(from);
                    extBtn.hidden = false;
                    if (d && d.iso) extBtn.textContent = 'Tashqi jadvaldagi joyiga joylash (' + cfDate(d.iso) + ' dan)';
                    reposition();
                }).catch(e => console.warn('Tashqi joy olinmadi:', e));
            }
            // Sikl karta oynasi: to'qnashuvlar turlarga ajratilgan bloklarda — har blok tur va kim bo'yicha ("O'qituvchi band: X", "Xona band:
            // 123-amaliyot xonasi", "Xona sig'maydi: …"), sarlavha "To'qnashuv — sabab: o'qituvchi band va xona band"; qatorlar — tuzilgan
            // ro'yxatdan (cfLineHtml, "Ko'rsatish" bilan), yashirilmaydi.
            function cycCfBlocks(own) {
                const m = new Map();
                own.forEach((i, n) => {
                    const who = cfWho(i) || '';
                    const k = i.kind + '|' + who;
                    if (!m.has(k)) m.set(k, { kind: i.kind, who, items: [], idx: [] });
                    m.get(k).items.push(i);
                    m.get(k).idx.push(n);
                });
                const order = Object.keys(CF_LABEL), at = k => (order.includes(k) ? order.indexOf(k) : order.length);
                return [...m.values()].sort((a, b) => at(a.kind) - at(b.kind));
            }
            // Sikl to'qnashuv yozuvi → haftalik bloklar bilan bir xil sabab (cbShowDetail uchun): sana — birinchi kelgusi (bo'lmasa birinchi) sana.
            const CYC_CB_KIND = { teacher_busy: 'teacher', room_busy: 'room', room_lectures: 'room', group_busy: 'group', lecture_overlap: 'group', room_capacity: 'capacity' };
            function cbFromCycleItem(i) {
                const kind = CYC_CB_KIND[i.kind];
                if (!kind) return null;
                const date = i.date_from || i.from || ((i.show || {}).dates || [])[0] || '';
                const day = date ? ((new Date(date + 'T00:00:00').getDay() + 6) % 7) + 1 : 0;
                return { kind, who: kind === 'room' ? ((i.show && i.show.room_name) || cfWho(i) || '') : (cfWho(i) || ''), date, day,
                    room_code: i.room || (i.show || {}).room_code || '', teacher_id: +i.teacher_id || null, groups: i.groups || [], hit_groups: i.groups || [],
                    // Shu birlikning ma'ruzasi to'qnashgan bo'lsa — uning darsi (agenda kaliti "l|<dars>|<sana>|<soat>"): kun ro'yxatida "shu dars".
                    lecture_id: i.lecture ? (+i.lecture_id || null) : null,
                    subject: i.with || '', time: i.time || '', show: i.show || null };
            }
            // Bloklardagi [Ko'rsatish]: xona / o'qituvchi — shu kungi darslar (teacher-agenda), guruh — to'qnashgan darslar; fokus — yozuvning show'i.
            // key — sikl birligi kaliti: kun ro'yxatida "shu dars" — aynan shu birlik yozuvi (agenda kaliti "c|<key>|<sana>"), guruhi emas.
            function cycCfBlocksBind(pop, own, card, reposition, key) {
                const blocks = cycCfBlocks(own);
                pop.querySelectorAll('[data-cyc-room-pick]').forEach(a => a.onclick = async ev => {
                    ev.preventDefault(); ev.stopPropagation();
                    const k = key || (card && card.key);
                    if (!k) return;
                    closeCycDayPop();
                    await openCycleAssign(k);
                    const sel = document.getElementById('cycAssignRoom');
                    if (sel && sel.focus) { sel.focus(); if (sel.scrollIntoView) sel.scrollIntoView({ block: 'center' }); }
                });
                pop.querySelectorAll('[data-cyc-cb-show]').forEach(a => a.onclick = ev => {
                    ev.preventDefault(); ev.stopPropagation();
                    const i = +a.dataset.cycCbShow, el = pop.querySelector('[data-cyc-cb-detail="' + i + '"]'), blk = blocks[i];
                    if (!el || !blk) return;
                    el.hidden = !el.hidden;
                    if (!el.hidden && !el.dataset.loaded) {
                        el.dataset.loaded = '1';
                        const items = blk.items.map(cbFromCycleItem).filter(Boolean);
                        const b = { kind: CYC_CB_KIND[blk.kind], who: items[0] ? items[0].who : blk.who, date: items[0] ? items[0].date : '', day: items[0] ? items[0].day : 0, items };
                        const ctx = { card: { id: 0, teacher_id: card && card.teacher ? +card.teacher.id : null, subject_name: card ? card.subject : '' }, ids: [],
                            mineGroups: card ? [card.group] : [], cycKey: key || (card && card.key) || null, day: b.day, pair: 1, len: 1, placed: true,
                            close: closeCycDayPop, reposition };
                        cbShowDetail(el, b, ctx).then(() => reposition && reposition());
                    }
                    if (reposition) reposition();
                });
            }
            function cycCfBlocksHtml(own, key) {
                const blocks = cycCfBlocks(own);
                const kinds = [...new Set(blocks.filter(b => b.items.some(i => !i.past)).map(b => cfLabel(b.kind).toLowerCase()))];
                const title = "To'qnashuv" + (kinds.length ? ' — sabab: ' + (kinds.length > 1 ? kinds.slice(0, -1).join(', ') + ' va ' + kinds[kinds.length - 1] : kinds[0]) : '');
                const kindAttr = { teacher_busy: 'teacher', group_busy: 'group', room_busy: 'room', room_capacity: 'capacity', lecture_overlap: 'group', room_lectures: 'room' };
                return '<div class="cb-title" data-cb-title style="font-weight:600;color:#991b1b;margin-top:4px">' + esc(title) + '</div>' +
                    blocks.map((b, bi) => '<div class="cb-block" data-cb-block="' + (kindAttr[b.kind] || 'other') + '" style="margin-top:3px">' +
                        '<div style="display:flex;justify-content:space-between;gap:6px;align-items:baseline"><b data-cb-head>' + esc(cfLabel(b.kind) + (b.who ? ': ' + b.who : '')) + '</b>' +
                        '<span style="white-space:nowrap">' +
                        // Sikl: "Xona band" — "Boshqa xona tanlash" (sikl biriktirish oynasi, xona tanlovi: bandlik va sig'im serverda tekshiriladi).
                        // Faqat biriktirish oynasi aynan shu darsni o'zgartirsa: amaliy to'qnashuv (blok — amaliy) yoki kartaning o'zi ma'ruza; birlashgan
                        // blokdagi ma'ruza xonasi to'qnashuvi — amaliy biriktirish ma'ruzaga tegmaydi, havola yo'q.
                        (kindAttr[b.kind] === 'room' && typeof cycActAllowed === 'function' && cycActAllowed()
                            && (b.items.every(i => !i.lecture) || ((typeof cycCardOf === 'function' && cycCardOf(key)) || {}).type === 'lecture') ? '<a href="#" data-cyc-room-pick style="text-decoration:underline dotted;margin-right:8px">Boshqa xona tanlash</a>' : '') +
                        (['room', 'teacher', 'group'].includes(kindAttr[b.kind]) ? '<a href="#" data-cyc-cb-show="' + bi + '" style="text-decoration:underline dotted">Ko\'rsatish</a>' : '') + '</span></div>' +
                        '<ul class="cf-list">' + b.items.map((i, n) => cfLineHtml(i, { move: !i.lecture && i.date_from ? 'c|' + key + '|' + i.date_from : null, idx: b.idx[n] })).join('') + '</ul>' +
                        '<div data-cyc-cb-detail="' + bi + '" hidden style="margin-top:3px"></div></div>').join('');
            }
            // Panel kartasi oynasi: to'qnashuvlar (bo'lsa), havolalar va amallar.
            function openCycCardPop(key, el) {
                const card = cycCardOf(key);
                if (!card) return;
                closeCycDayPop();
                const split = card.conflict ? cfSplit(key, card.conflicts, cfOwners) : { own: [] };
                const own = cfMergeItems(split.own);
                const pop = document.createElement('div');
                pop.id = 'cycDayPop';
                pop.innerHTML = '<div class="dp-head"><div><div class="dp-title">' + esc(card.subject) + '</div><div class="dp-sub">' + esc(card.group) + ' · ' +
                    esc(cycleCardStateText(card)) + '</div></div><button type="button" class="dp-close" aria-label="Yopish">&times;</button></div>' +
                    (own.length ? cycCfBlocksHtml(own, key) : '') +
                    cycActionsHtml(card, own);
                document.body.appendChild(pop);
                const reposition = cycPopWatch(pop, el);
                cycActionsBind(pop, card, own, reposition);
                if (own.length) cycCfBlocksBind(pop, own, card, reposition, key);
                if (own.length) loadShiftAdvice(pop, key, own);
                pop.querySelector('.dp-close').onclick = closeCycDayPop;
            }

            // Panel (sikl va haftalik kartalar) to'qnashuv belgisi — barcha rejimlarda (faqat ko'rishda ham) bosiladi: tafsilot oynasi.
            // Capture bosqichida: karta tanlash/joylash ishlovchisiga o'tmaydi.
            if ($('cardPanel')) $('cardPanel').addEventListener('click', ev => {
                const cf = ev.target && ev.target.closest ? ev.target.closest('[data-cf-key],[data-cf-lecture],[data-wcf]') : null;
                if (!cf) return;
                ev.preventDefault();
                ev.stopPropagation();
                if (cf.dataset.wcf) {
                    // Haftalik panel kartasi: karta oynasi, to'qnashuv bloklari [Ko'rsatish] bilan ochiq (xona / o'qituvchi kunlik ro'yxati, haftalik
                    // jadval havolalari); ichki jadval va hafta tanlanmagan bo'lsa — eski qisqa oyna.
                    const c = (cards || []).find(x => +x.id === +cf.dataset.wcf) || (allCards || []).find(x => +x.id === +cf.dataset.wcf);
                    if (c && curWeek && weeklyLayer === 'internal' && effPlace(c)) openPanelCardPop(c, cf, { cfOpen: true });
                    else openWeekCfPop(cf);
                } else openCfPop(cf);
            }, true);
            // Haftalik panel kartasining to'qnashuvlari (joriy hafta, /conflicts?items=1&week=N) — har biri alohida qatorda.
            function openWeekCfPop(el) {
                const id = +el.dataset.wcf;
                const c = (allCards || []).find(x => +x.id === id);
                const items = curWeek && weeklyConflictItems[id] ? (weeklyConflictItems[id][curWeek] || []) : [];
                closeCycDayPop();
                const pop = document.createElement('div');
                pop.id = 'cycDayPop';
                pop.innerHTML = '<div class="dp-head"><div><div class="dp-title">' + esc(c ? c.subject_name : '') + '</div><div class="dp-sub">' +
                    esc(c ? cardGroups(c).join(', ') : '') + (curWeek ? ' · ' + curWeek + '-hafta' : '') + ' · to\u2018qnashuvlar</div></div>' +
                    '<button type="button" class="dp-close" aria-label="Yopish">&times;</button></div><ul class="cf-list">' +
                    (items.length ? cfMergeItems(items).map(i => cfLineHtml(i, { move: curWeek ? 'w|' + id + '|' + curWeek : null })).join('')
                        : '<li class="cf-line">' + esc(cardConflict(c) || '') + '</li>') +
                    (weeklyCapLine(c) ? '<li class="cf-line cf-cap-warn">' + esc(weeklyCapLine(c)) + '</li>' : '') + '</ul>' +
                    (c && mudirPhAllowed() && !phOf(c) ? '<div style="padding:4px 8px"><button type="button" data-cf-mudir style="border:1px solid #ca8a04;color:#854d0e;background:#fefce8;border-radius:5px;padding:1px 8px">Vaqtincha kafedra mudiriga yozish</button></div>' : '');
                document.body.appendChild(pop);
                const cfMudir = pop.querySelector('[data-cf-mudir]');
                if (cfMudir) cfMudir.onclick = () => { closeCycDayPop(); openMudirPhConfirm(c, mudirPhSlot(c)); };
                const r = el.getBoundingClientRect();
                pop.style.left = Math.max(8, Math.min(window.innerWidth - pop.offsetWidth - 8, r.left)) + 'px';
                pop.style.top = Math.max(8, Math.min(window.innerHeight - pop.offsetHeight - 8, r.bottom + 6)) + 'px';
                pop.querySelector('.dp-close').onclick = closeCycDayPop;
            }
            // ===== Sikl katagini sudrash (ichki jadval, yarim para — bitta soat qatori qadami) =====
            // M katagi — faqat ma'ruza, A katagi — faqat amaliy, tanlangan tugma (sukut — Shift) bilan — birga. Sudrash paytida yangi
            // joy kataklarda yashil (mumkin) yoki qizil (kun chegarasi / ma'ruza–amaliy ustma-ust) va vaqt yorlig'i; bandlik — serverda
            // (qo'yib yuborilganda xato matni). Oddiy bosish — kun oynasi (5 px dan kam siljish — sudrash emas).
            let cycCellDragged = false;
            // Surish rejimi: bitta (hamma kunga) — 'both' | 'lecture' | 'practice', yoki har kunga o'zi — { kun: rejim } (aralash tanlov).
            const cycModeOf = (mode, o) => typeof mode === 'string' ? mode : (mode && mode[o]) || 'both';
            function cycModeUniform(mode, offsets) {
                if (typeof mode === 'string') return mode;
                const set = new Set(offsets.map(o => cycModeOf(mode, o)));
                return set.size === 1 ? [...set][0] : null;
            }
            const cycModeHas = (mode, offsets, m) => offsets.some(o => cycModeOf(mode, o) === m);
            const cycStepText = (delta, jump) => jump ? (delta > 0 ? '1 qadam pastga' : '1 qadam tepaga') : (delta > 0 ? '+' : '') + delta + ' soat';
            // Ko'p kunli surish so'rovi (cycle-lecture-slots, day_indexes): tanlangan kunlar (blok ichidagi siljishlar) → sikl kunlari; aralash
            // rejim — day_modes (bitta so'rov: hammasi bitta tranzaksiyada, bitta qaytarish). ↑ ↓ qadami (step=jump) — to'sib turgan boshqa
            // guruhcha amaliyoti doim "o'rin almashish" qoidasi bilan (sozlamadagi usul faqat sudrashda; o'chiq bo'lsa — tegilmaydi).
            function cycDaysBody(key, offsets, mode, delta, extra = {}) {
                const card = (cyclePlanData && cyclePlanData.cycle_cards || []).find(item => item.key === key);
                const block = cycBlockByKey(key);
                if (!card || !block) throw new Error('Sikl bloki topilmadi.');
                const uni = cycModeUniform(mode, offsets);
                const place = cycModeHas(mode, offsets, 'lecture') || extra.lecture_swap
                    ? (extra.step === 'jump' ? { practice_place: cycPracPlace().on ? 'swap' : 'keep' } : cycPracPlaceParams()) : {};
                return Object.assign({
                    specialty_name: card.specialty, course: card.course, group_name: card.group, subject_name: card.subject,
                    training_type: card.type || 'practice', view: cycleEffView(), placement_group: card.placement_group || undefined,
                    sub_group: card.placement_group && card.placement_group !== card.group ? card.group : undefined,
                    day_indexes: offsets.map(o => block.day_plan[o].k - 1), mode: uni || 'both', delta: delta,
                    day_modes: uni ? undefined : Object.fromEntries(offsets.map(o => [block.day_plan[o].k - 1, cycModeOf(mode, o)])),
                }, place, extra);
            }
            // Ko'p kunli surish: so'rovning vaqt chegarasi (gateway ~60 s dan biroz ko'p — javob kelsa ham, 504 bo'lsa ham bir xil matn),
            // bo'lak hajmi (5 kundan ko'p — 5 kunlik bo'laklar ketma-ket).
            const CYC_DAYS_TIMEOUT_MS = 65000;
            const CYC_DAYS_CHUNK = 5;
            const CYC_TIMEOUT_TEXT = 'Server javob bermadi (vaqt tugadi). Kamroq kun tanlab qayta urinib ko\'ring.';
            const cycTimedOut = e => Boolean(e && (e.status === 504 || e.status === 'timeout'));
            const cycErrText = e => cycTimedOut(e) ? CYC_TIMEOUT_TEXT : String((e && e.message) || e);
            const cycDaysRequest = (key, offsets, mode, delta, extra) =>
                api(BASE + '/boards/' + board.id + '/cycle-lecture-slots', 'POST', cycDaysBody(key, offsets, mode, delta, extra), { timeout: CYC_DAYS_TIMEOUT_MS });
            function cycChunks(offsets) {
                const out = [];
                for (let i = 0; i < offsets.length; i += CYC_DAYS_CHUNK) out.push(offsets.slice(i, i + CYC_DAYS_CHUNK));
                return out.length ? out : [[]];
            }
            // Tasdiq talab qilinadigan doskada kafedra mudiri: so'rov yoziladi xolos (og'ir ish — tasdiqda) — bo'linmaydi (bitta so'rov).
            const cycApprovalGated = () => TIMETABLE_ROLE === 'kafedra_mudiri'
                && Boolean((typeof changeReqs !== 'undefined' && changeReqs.approval_required) || (board && board.settings && board.settings.approval_required));
            // So'rov ketayotganda: kursor "wait", har kunning surilayotgan bo'lagi birinchi katagida "tekshirilmoqda…" / "saqlanmoqda…",
            // tanlov yorlig'ida jarayon ("Tekshirilmoqda: 6–10-kun (2/2)").
            function cycBusyShow(key, offsets, mode, text, progress = '') {
                cycBusyHide();
                document.body.classList.add('cyc-busy');
                const block = cycBlockByKey(key);
                offsets.forEach(o => {
                    const parts = cycModeParts(cycModeOf(mode, o));
                    const cells = [...document.querySelectorAll('#cycleGrid .cyc-mk-cell[data-mk-key="' + CSS.escape(key) + '"][data-mk-day="' + o + '"]')]
                        .filter(c => parts.includes(cycCellPart(c))).sort((a, b) => a.dataset.mkHour - b.dataset.mkHour);
                    if (cells[0]) { cells[0].classList.add('is-cyc-busy'); cells[0].setAttribute('data-busy-note', text); }
                });
                const badge = document.getElementById('cycSelBadge');
                if (badge && offsets.length) {
                    const k = o => (block && block.day_plan && block.day_plan[o] ? block.day_plan[o].k : +o + 1);
                    const span = k(offsets[0]) + (offsets.length > 1 ? '–' + k(offsets[offsets.length - 1]) : '') + '-kun';
                    const el = document.createElement('span');
                    el.dataset.selBusy = '';
                    el.textContent = text.charAt(0).toUpperCase() + text.slice(1).replace(/…$/, '') + ': ' + span + (progress ? ' (' + progress + ')' : '') + '…';
                    badge.prepend(el);
                }
            }
            function cycBusyHide() {
                document.body.classList.remove('cyc-busy');
                document.querySelectorAll('#cycleGrid .cyc-mk-cell.is-cyc-busy').forEach(c => { c.classList.remove('is-cyc-busy'); c.removeAttribute('data-busy-note'); });
                document.querySelectorAll('#cycSelBadge [data-sel-busy]').forEach(el => el.remove());
            }
            // Oldindan tekshiruv (dry_run): 5 kundan ko'p bo'lsa — 5 kunlik bo'laklarda ketma-ket, natijalar bitta javobga birlashtiriladi
            // (bitta tasdiq oynasi). Har kun alohida tekshiriladi — bo'lib yuborish natijani o'zgartirmaydi.
            async function cycDaysDry(key, offsets, mode, delta, extra = {}, busy = true) {
                const parts = cycChunks(offsets);
                const out = { ok: true, dry_run: true, days: [], applied: 0, undo: null };
                try {
                    for (let i = 0; i < parts.length; i++) {
                        if (busy) cycBusyShow(key, parts[i], mode, 'tekshirilmoqda…', parts.length > 1 ? (i + 1) + '/' + parts.length : '');
                        const j = await cycDaysRequest(key, parts[i], mode, delta, Object.assign({}, extra, { dry_run: 1 }));
                        out.days = out.days.concat((j && j.days) || []);
                        if (j && j.hemis_hint) out.hemis_hint = j.hemis_hint;
                    }
                } finally {
                    if (busy) cycBusyHide();
                }
                return out;
            }
            const CYC_MODE_WHAT = { both: 'darslar', lecture: 'ma\'ruza', practice: 'amaliy' };
            const CYC_DAY_STATUS = { ok: 'o\'zgaradi', conflict: 'to\'qnashuv', nofit: 'sig\'maydi', blocked: 'o\'zgarmaydi', past: 'o\'tgan / boshlangan',
                same: 'o\'zgarmaydi', skip: 'dars yo\'q' };
            const cycDayLabel = d => (d.date ? d.date.slice(8, 10) + '.' + d.date.slice(5, 7) + ' ' : '') + '(' + (+d.day_index + 1) + '-kun)';
            const cycHourLabel = h => { const t = cycHourTimes()[h]; return t ? t[0] : h + '-soat'; };
            // Oxirgi surish — Ctrl+Z / "Qaytarish" (server oldingi qiymatlarni saqlaydi; bitta so'rov).
            let cycLastUndo = null;   // { key, token }
            let cycDaysBusy = false;
            // Natija qisqa matni: "5 kun: ma'ruza 08:30 → 12:00" (kunlarda har xil bo'lsa — "+2 soat" / "1 qadam pastga"; aralash — "darslar
            // (aralash)"; ↑ ↓ qadamida qo'shni dars bilan o'rin almashgan kunlar soni).
            function cycDaysSummary(days, mode, delta, jump = false) {
                const done = days.filter(d => d.applied);
                const pairs = [...new Set(done.map(d => d.from + '>' + d.to))];
                const how = pairs.length === 1 ? cycHourLabel(done[0].from) + ' → ' + cycHourLabel(done[0].to) : cycStepText(delta, jump);
                const moved = new Set(done.flatMap(d => (d.swaps || []).filter(w => w.how !== 'pin').map(w => w.unit)));
                const ms = new Set(done.map(d => d.mode).filter(Boolean));
                if (!ms.size) (typeof mode === 'string' ? [mode] : Object.values(mode || {})).forEach(m => ms.add(m));
                const what = ms.size > 1 ? 'darslar (aralash)' : CYC_MODE_WHAT[[...ms][0] || 'both'];
                const swapped = done.filter(d => d.jump).length;
                return done.length + ' kun: ' + what + ' ' + how + (swapped ? ' · yonidagi dars bilan o\'rin almashdi: ' + swapped + ' kun' : '')
                    + (done.some(d => d.lecture) ? ' · ma\'ruza bilan o\'rin almashdi' : '')
                    + (moved.size ? ' · amaliyot ko\'chdi: ' + moved.size + ' guruhcha' : '');
            }
            // Ko'chadigan amaliyotlar: "d2/d23-08a 10:00 → 08:30, 09a 10:00 → 08:30, 09b 10:00 → 12:00 (sig'madi — keyinga)" — birinchi
            // guruhcha to'liq nomi bilan, shu oqimdagi keyingilari qisqa; takrorlar (ko'p kunda bir xil) bir marta.
            function cycSwapNote(w) {
                const dir = { after: 'keyinga', before: 'oldinga' }[w.how];
                if (dir && w.why) return (w.why === 'busy' ? 'band' : 'sig\'madi') + ' — ' + dir;
                const t = { swap: '', after: 'ma\'ruzadan keyin', before: 'ma\'ruzadan oldin', gap: 'oraliq bilan', pair: 'tanlangan para', pin: 'siz surgan' }[w.how];
                return t == null ? String(w.how) : t;
            }
            function cycSwapsText(list) {
                const seen = new Set(), out = [];
                let prefix = null;
                (list || []).forEach(w => {
                    const k = [w.unit, w.from, w.to, w.how, w.why, w.busy].join('|');
                    if (seen.has(k)) return;
                    seen.add(k);
                    const m = /^(.*-)([^-]+)$/.exec(String(w.unit));
                    const name = prefix !== null && m && m[1] === prefix ? m[2] : w.unit;
                    if (prefix === null && m) prefix = m[1];
                    const note = cycSwapNote(w);
                    out.push(name + ' ' + cycHourLabel(w.from) + ' → ' + cycHourLabel(w.to) + (note ? ' (' + note + ')' : '') + (w.busy ? ' — band!' : ''));
                });
                return out.join(', ');
            }
            // Surishdan keyin kun oynasini qayta ochish (↑ ↓ kun oynasidan bosilgan bo'lsa); kunlar tanlovi qoladi (keyingi ↑ ↓ ham hammasiga).
            function cycReopenDay(key, offset) {
                const cell = document.querySelector('#cycleGrid .cyc-mk-cell[data-mk-key="' + CSS.escape(key) + '"][data-mk-day="' + offset + '"]');
                if (cell) openCycDayPop(key, offset, cell, true);
            }
            // Qo'llash (dry_run emas). Tasdiq talab qilinadigan doskada — so'rov; aks holda jadval yangilanadi, qisqa xabar + "Qaytarish".
            // 5 kundan ko'p — 5 kunlik bo'laklarda ketma-ket (tasdiq doskasida — bitta so'rov). Hammasi yoki hech narsa: biror bo'lak xato
            // bersa, oldingi bo'laklar qaytarish kalitlari bilan teskari tartibda qaytariladi; oxirida bitta xabar va bitta Ctrl+Z (hamma
            // bo'laklar). Vaqt tugasa — jadval qayta yuklanadi (server shu bo'lakni saqlagan bo'lishi mumkin).
            async function cycDaysCommit(key, offsets, mode, delta, extra = {}) {
                const parts = cycApprovalGated() ? [offsets] : cycChunks(offsets);
                const tokens = [];
                const j = { ok: true, days: [], applied: 0, undo: null, today_moved: false };
                try {
                    for (let i = 0; i < parts.length; i++) {
                        cycBusyShow(key, parts[i], mode, 'saqlanmoqda…', parts.length > 1 ? (i + 1) + '/' + parts.length : '');
                        let r;
                        try {
                            r = await cycDaysRequest(key, parts[i], mode, delta, extra);
                        } catch (e) {
                            const back = tokens.length ? await cycUndoTokens(key, tokens) : true;
                            if (cycTimedOut(e) || !back) {
                                try { await loadCyclePlan(); } catch (_) { }
                            }
                            const err = new Error(cycErrText(e) + (parts.length > 1 ? (back
                                ? (tokens.length ? ' Oldingi bo\'laklar qaytarildi — hech narsa o\'zgarmadi.' : '')
                                : ' Oldingi bo\'laklarni qaytarib bo\'lmadi — jadvalni tekshiring.') : ''));
                            err.status = e && e.status;
                            throw err;
                        }
                        if (r && r.pending_approval) { onPendingApproval(r); return r; }
                        if (r && r.undo) tokens.push(r.undo);
                        j.days = j.days.concat((r && r.days) || []);
                        j.applied += +((r && r.applied) || 0);
                        j.today_moved = j.today_moved || Boolean(r && r.today_moved);
                        if (r && r.hemis_hint) j.hemis_hint = r.hemis_hint;
                    }
                } finally {
                    cycBusyHide();
                }
                j.undo = tokens.length ? tokens[tokens.length - 1] : null;
                const days = j.days;
                const left = days.filter(d => !d.applied && !['same', 'skip'].includes(d.status));
                if (tokens.length) cycLastUndo = { key: key, tokens: tokens };
                await loadCyclePlan();
                const block = cycBlockByKey(key);
                days.filter(d => d.applied).forEach(d => {
                    const o = block ? Object.keys(block.day_plan || {}).find(x => block.day_plan[x].k - 1 === d.day_index) : null;
                    document.querySelectorAll('#cycleGrid .cyc-mk-cell[data-mk-key="' + CSS.escape(key) + '"][data-mk-day="' + o + '"]')
                        .forEach(c => { c.classList.remove('cyc-just-changed'); void c.offsetWidth; c.classList.add('cyc-just-changed'); });
                });
                ttToast((days.some(d => d.applied) ? esc(cycDaysSummary(days, mode, delta, extra.step === 'jump')) : 'Hech bir kun o\'zgarmadi.')
                    + (j.undo ? ' <button type="button" class="tt-toast-btn" data-cyc-undo>Qaytarish (Ctrl+Z)</button>' : '')
                    + (j.today_moved ? '<div class="tt-toast-sub" data-hemis-hint>' + esc(j.hemis_hint || TT_HEMIS_HINT) + '</div>' : '')
                    + (left.length ? '<div class="tt-toast-sub">' + left.length + ' kun o\'zgarmadi: ' + esc(left.map(d => cycDayLabel(d) + ' — '
                        + (CYC_DAY_STATUS[d.status] || d.status)).join('; ')) + '</div>' : ''), j.undo ? 'ok' : 'warn');
                return j;
            }
            // Qaytarish kalitlari — teskari tartibda (oxirgi bo'lak birinchi: har biri "keyin o'zgarmagan" tekshiruvidan o'tadi). true — hammasi.
            async function cycUndoTokens(key, tokens) {
                for (const t of tokens.slice().reverse()) {
                    try { await cycDaysRequest(key, [], 'both', null, { undo: t, day_indexes: undefined, delta: undefined, mode: undefined }); }
                    catch (e) { return false; }
                }
                return true;
            }
            async function cycUndo() {
                const u = cycLastUndo;
                if (!u) { ttToast('Qaytariladigan surish yo\'q.', 'warn'); return; }
                cycLastUndo = null;
                try {
                    // Bo'laklab saqlangan surish — hamma bo'laklar bitta harakat sifatida (teskari tartibda).
                    let j = null;
                    for (const t of (u.tokens || [u.token]).slice().reverse()) {
                        j = await cycDaysRequest(u.key, [], 'both', null, { undo: t, day_indexes: undefined, delta: undefined, mode: undefined });
                        if (j && j.pending_approval) { onPendingApproval(j); return; }
                    }
                    await loadCyclePlan();
                    ttToast('Oxirgi surish qaytarildi.', 'ok');
                } catch (e) {
                    ttToast('Qaytarib bo\'lmadi: ' + esc(cycErrText(e)), 'warn');
                    // Bo'laklardan bir qismi qaytgan bo'lishi mumkin — jadval qayta yuklanadi.
                    if ((u.tokens || []).length > 1) { try { await loadCyclePlan(); } catch (_) { } }
                }
            }
            // Oldindan tekshiruv natijasi oynasi: qaysi kunlar o'zgaradi, qaysilarida to'qnashuv (sababi bilan), qaysilari sig'maydi; ma'ruza
            // surilganda — to'sib turgan amaliyot qayerga ko'chadi ("Amaliyot o'rin almashadi: …"); teskari holat (opts.reverse) — "Ma'ruza bilan
            // o'rin almashsinmi?". opts: { extra (so'rovga qo'shimcha), reverse, reopen }.
            function cycDaysDialog(key, offsets, mode, delta, dry, opts = {}) {
                const prior = document.getElementById('cycMultiDlg');
                if (prior) prior.remove();
                const block = cycBlockByKey(key);
                const days = dry.days || [];
                const offOf = d => offsets.find(o => block && block.day_plan[o] && block.day_plan[o].k - 1 === d.day_index);
                const ok = days.filter(d => d.status === 'ok'), conf = days.filter(d => d.status === 'conflict');
                const moving = ok.concat(conf);
                const swaps = moving.flatMap(d => d.swaps || []);
                const lec = moving.map(d => d.lecture).find(Boolean);
                const pairs = [...new Set(moving.map(d => d.from + '>' + d.to))];
                const uni = cycModeUniform(mode, offsets);
                const jump = (opts.extra || {}).step === 'jump';
                const what = { both: 'Darslar', lecture: 'Ma\'ruza', practice: 'Amaliy' }[uni] || 'Darslar';
                const head = moving.length ? what + ' ' + (pairs.length === 1 ? cycHourLabel(moving[0].from) + ' → ' + cycHourLabel(moving[0].to)
                    : cycStepText(delta, jump)) + ' (' + (uni === 'lecture' ? 'oqim, ' : '') + moving.length + ' kun).' : '';
                const multi = days.length > 1;
                // Aralash tanlov: har kun qatorida turi (M — ma'ruza, A — amaliy, M+A — birga).
                const tag = d => uni ? '' : '<span class="cmd-mode">' + ({ both: 'M+A', lecture: 'M', practice: 'A' }[d.mode] || '') + '</span> ';
                const m = document.createElement('div');
                m.id = 'cycMultiDlg';
                m.className = 'cr-proposal-overlay';
                m.innerHTML = '<div class="cr-proposal-form"><h3 class="font-bold text-lg">' + (opts.reverse ? 'Ma\'ruza bilan o\'rin almashsinmi?' : multi ? 'Bir nechta kunni surish' : 'Kunni surish') + '</h3>'
                    + '<p class="text-sm">' + esc((block ? block.subject + ' · ' : '') + (uni ? CYC_MODE_WHAT[uni] : 'darslar (aralash)') + ' ' + cycStepText(delta, jump) + ' · ' + days.length + ' kun') + '</p>'
                    + (head ? '<p class="text-sm font-semibold" data-cmd-head>' + esc(head) + '</p>' : '')
                    + (opts.reverse && lec ? '<p class="text-sm" data-cmd-lec>' + esc('Ma\'ruza (butun oqim) ' + cycHourLabel(lec.from) + ' → ' + cycHourLabel(lec.to) + '.') + '</p>' : '')
                    + (swaps.length ? '<p class="text-sm cmd-swaps" data-cmd-swaps>' + esc('Amaliyot o\'rin almashadi: ' + cycSwapsText(swaps) + '.') + '</p>' : '')
                    // Bugungi kun ham o'zgaradi (admin / registrator ofisi) — HEMIS eslatmasi.
                    + (moving.some(d => d.today) ? '<p class="text-sm tt-hemis-hint" data-cmd-hemis>' + esc(dry.hemis_hint || TT_HEMIS_HINT) + '</p>' : '')
                    + '<ul class="cmd-list">' + days.map(d => '<li class="cmd-' + esc(d.status) + '">' + tag(d) + '<b>' + esc(cycDayLabel(d)) + '</b> '
                        + (d.from != null && d.to != null ? esc(cycHourLabel(d.from) + ' → ' + cycHourLabel(d.to)) + ' ' : '')
                        + '— ' + esc(CYC_DAY_STATUS[d.status] || d.status) + (d.why ? ': ' + esc(d.why) : '')
                        + (multi && (d.swaps || []).length && ['ok', 'conflict'].includes(d.status) ? '<div class="cmd-sub">' + esc('amaliyot: ' + cycSwapsText(d.swaps)) + '</div>' : '')
                        + '</li>').join('') + '</ul>'
                    + '<div class="flex justify-end gap-2 flex-wrap"><button type="button" data-cmd="cancel">Bekor</button>'
                    + (cycModeHas(mode, offsets, 'lecture') && swaps.some(w => w.how !== 'pin') && !opts.reverse ? '<button type="button" data-cmd="keep">Faqat ma\'ruzani (amaliyotga tegmasdan — xato beradi)</button>' : '')
                    + (conf.length ? '<button type="button" data-cmd="force" class="px-3 py-2 rounded bg-amber-600 text-white">Baribir hammasiga (' + (ok.length + conf.length) + ')</button>' : '')
                    + '<button type="button" data-cmd="apply" class="px-3 py-2 rounded bg-blue-600 text-white"' + (ok.length ? '' : ' disabled') + '>'
                        + (opts.reverse ? 'Ha, o\'rin almashsin' : 'Qo\'llash') + ' (' + ok.length + ')</button></div>'
                    + '<p role="alert" class="text-red-600"></p></div>';
                document.body.appendChild(m);
                const close = () => m.remove();
                m.onclick = ev => { if (ev.target === m) close(); };
                m.querySelector('[data-cmd="cancel"]').onclick = close;
                const run = async (list, extra) => {
                    if (cycDaysBusy) { ttToast('Avvalgi surish hali tugamadi — kuting.', 'warn'); return; }
                    m.querySelectorAll('button').forEach(b => { b.disabled = true; });
                    cycDaysBusy = true;
                    const msg = m.querySelector('[role="alert"]');
                    msg.className = 'text-slate-600';
                    msg.textContent = '⌛ Saqlanmoqda: ' + list.length + ' kun…';
                    try {
                        await cycDaysCommit(key, list, mode, delta, Object.assign({}, opts.extra || {}, extra));
                        close();
                        if (opts.reopen) cycReopenDay(key, list[0] != null ? list[0] : offsets[0]);
                    } catch (e) {
                        msg.className = 'text-red-600';
                        msg.textContent = cycErrText(e);
                        m.querySelectorAll('button').forEach(b => { b.disabled = false; });
                    } finally {
                        cycDaysBusy = false;
                    }
                };
                m.querySelector('[data-cmd="apply"]').onclick = () => run(ok.map(offOf).filter(o => o != null), {});
                const force = m.querySelector('[data-cmd="force"]');
                if (force) force.onclick = () => run(ok.concat(conf).map(offOf).filter(o => o != null).sort((a, b) => a - b), { force: 1 });
                const keep = m.querySelector('[data-cmd="keep"]');
                if (keep) keep.onclick = () => run(ok.concat(conf).map(offOf).filter(o => o != null).sort((a, b) => a - b), { practice_place: 'keep' });
            }
            // Tanlangan kunlarni surish (sudrash yoki ↑ ↓): avval tekshiruv; muammo va amaliyot ko'chishi yo'q — darhol, bo'lsa — oyna.
            // "Faqat amaliy" ma'ruza ustiga tushsa — ma'ruza bilan o'rin almashish taklifi (lecture_swap, oldindan ko'rinish bilan).
            // opts.locked — chaqiruvchi qulfni (cycDaysBusy) oldindan olgan (sudrash: tekshiruv javobini kutish paytida boshqa surish
            // boshlanmasin); qulf shu yerda bo'shatiladi.
            async function cycDaysApply(key, offsets, mode, delta, dry, opts = {}) {
                if (!offsets.length || !delta) { if (opts.locked) cycDaysBusy = false; return; }
                // Oldingi surish hali ketmoqda — jim e'tiborsiz qoldirilmaydi.
                if (cycDaysBusy && !opts.locked) { ttToast('Avvalgi surish hali tugamadi — kuting.', 'warn'); return; }
                cycDaysBusy = true;
                const extra = opts.extra || {};
                try {
                    // Tekshiruv natijasi yo'q — darhol "tekshirilmoqda…" (ko'p kunda xabar ham), 5 kundan ko'p — bo'laklab.
                    if (!dry || !dry.days) {
                        if (offsets.length > 1) ttToast('&#8987; Tekshirilmoqda: ' + offsets.length + ' kun…', '');
                        dry = await cycDaysDry(key, offsets, mode, delta, extra);
                    }
                    const days = dry.days || [];
                    // Kunning rejimi: server javobidan, bo'lmasa — so'rovdagi (aralash tanlovda har kun o'zi).
                    const block = cycBlockByKey(key);
                    const dayMode = d => d.mode || cycModeOf(mode, offsets.find(o => block && block.day_plan[o] && block.day_plan[o].k - 1 === d.day_index));
                    if (!extra.lecture_swap && days.some(d => dayMode(d) === 'practice' && d.status === 'blocked' && /Ma.ruza vaqti bilan ustma-ust/.test(d.why || ''))) {
                        const ex2 = Object.assign({}, extra, { lecture_swap: 1 });
                        const dry2 = await cycDaysDry(key, offsets, mode, delta, ex2);
                        cycDaysDialog(key, offsets, mode, delta, dry2, Object.assign({}, opts, { extra: ex2, reverse: true }));
                        return;
                    }
                    // Faqat qo'shni amaliyot o'rin almashdi (↑ ↓ qadami, "pin") — oynasiz; boshqa guruhcha amaliyoti ko'chsa yoki ma'ruza
                    // (butun oqim) o'rin almashsa — oyna.
                    const moves = days.some(d => (d.swaps || []).some(w => w.how !== 'pin') || d.lecture);
                    // Bugungi kun ham o'zgarsa — oyna (HEMIS eslatmasi bilan) — darhol emas.
                    if (!moves && !days.some(d => d.today && ['ok', 'conflict'].includes(d.status))
                        && days.some(d => d.status === 'ok' || d.status === 'conflict') && days.every(d => ['ok', 'same', 'skip'].includes(d.status))) {
                        if (offsets.length > 1) ttToast('&#8987; Saqlanmoqda: ' + offsets.length + ' kun…', '');
                        await cycDaysCommit(key, offsets, mode, delta, extra);
                        if (opts.reopen) cycReopenDay(key, offsets[0]);
                    } else {
                        cycDaysDialog(key, offsets, mode, delta, dry, opts);
                    }
                } catch (e) {
                    ttToast('Ko\'chirib bo\'lmadi: ' + esc(cycErrText(e)), 'warn');
                } finally {
                    cycDaysBusy = false;
                }
            }
            function setupCycCellDrag(grid) {
                // { key, offset, hour, kind, dp, x, y, moving, delta, mode, shape, bad, multi, modes (ko'p kun — har kun rejimi), fixed (tanlangan
                // bitta kun — o'z rejimi), look, staff, ask, dry, cancel }
                let st = null;
                const cellsOf = (key, offset) => [...grid.querySelectorAll('.cyc-mk-cell[data-mk-key="' + CSS.escape(key) + '"][data-mk-day="' + offset + '"]')];
                const clear = () => {
                    grid.classList.remove('is-cyc-dragging');
                    grid.querySelectorAll('.cyc-mk-cell.is-drag-ok, .cyc-mk-cell.is-drag-bad, .cyc-mk-cell.is-drag-nofit')
                        .forEach(c => { c.classList.remove('is-drag-ok', 'is-drag-bad', 'is-drag-nofit'); c.removeAttribute('data-drag-note'); });
                    const tip = document.getElementById('cycDragTip');
                    if (tip) tip.remove();
                };
                const timeOf = r => { const t = cycHourTimes(); return r ? ((t[r[0]] ? t[r[0]][0] : r[0] + '-soat') + '–' + (t[r[1] - 1] ? t[r[1] - 1][1] : (r[1] - 1) + '-soat')) : ''; };
                const rangesOf = (shape, mode) => mode === 'lecture' ? [shape.lec] : mode === 'practice' ? [shape.prc] : [shape.lec, shape.prc];
                const dryKey = () => (st.multi ? 'sel' : st.mode) + '|' + st.delta;
                // Ko'p kunda kunning rejimi: tahrirlovchi — tanlangan bo'laklari bo'yicha; so'rov — katak turi.
                const modeOf = o => st.ask ? st.kind : (st.modes && st.modes[o]) || st.mode;
                // Ko'p kun (tahrirlovchi): server tekshiruvi (dry_run) — rejim / siljish o'zgarganda, 250 ms kechikib; shu sudrash ichida keshlanadi.
                const scheduleDry = () => {
                    if (!st || !st.multi || !st.staff || !st.delta || st.dry[dryKey()] !== undefined) return;
                    const k = dryKey(), s0 = st;
                    clearTimeout(s0.dryTimer);
                    s0.dryTimer = setTimeout(async () => {
                        if (st !== s0 || dryKey() !== k || s0.dry[k] !== undefined) return;
                        s0.dry[k] = null;   // so'ralmoqda
                        // Va'da saqlanadi: qo'yib yuborilganda javob hali kelmagan bo'lsa — qayta so'ralmaydi, shu kutiladi (finish).
                        s0.dryP = s0.dryP || {};
                        s0.dryP[k] = cycDaysDry(s0.key, s0.multi, s0.modes, s0.delta, {}, false)
                            .then(r => { s0.dry[k] = r; }, e => { s0.dry[k] = { error: cycErrText(e), days: [] }; });
                        await s0.dryP[k];
                        if (st === s0 && dryKey() === k && s0.moving) paint(s0.lastEv);
                    }, 250);
                };
                const paint = ev => {
                    clear();
                    grid.classList.add('is-cyc-dragging');
                    st.lastEv = { clientX: ev.clientX, clientY: ev.clientY, shiftKey: ev.shiftKey, altKey: ev.altKey, ctrlKey: ev.ctrlKey, metaKey: ev.metaKey };
                    const dayHours = Math.max(1, +cyclePlanData.day_hours || 6);
                    // O'qituvchi / fan mas'uli: so'rov — katak turi bo'yicha (birga surish yo'q). Tanlangan bo'lak sudralsa — tanlovning o'z rejimi
                    // (tugma hisobga olinmaydi).
                    st.mode = st.fixed || (!st.ask && cycBothKeyDown(ev) ? 'both' : (st.kind === 'lecture' ? 'lecture' : 'practice'));
                    st.shape = cycDayShape(st.dp, st.mode, st.delta, null);
                    st.bad = cycDayShapeError(st.shape, dayHours, cycOverlapOk(st.mode));
                    // Ma'ruza–amaliy kesishuvi (xato emas): ma'ruza — amaliyot usul bo'yicha ko'chadi; amaliy — ma'ruza bilan o'rin almashish taklifi.
                    const over = !st.ask && st.mode !== 'both' && st.shape.lec && st.shape.prc && st.shape.lec[0] < st.shape.prc[1] && st.shape.prc[0] < st.shape.lec[1];
                    const overText = !over ? '' : st.mode === 'lecture' ? ' · amaliyot: ' + CYC_PLACE_HOW[cycPracPlace().how].toLowerCase()
                        : ' · ma\'ruza bilan o\'rin almashish taklif qilinadi';
                    const what = st.multi && !st.ask ? ({ both: 'Birga', lecture: 'Ma\'ruza', practice: 'Amaliy' }[st.look] || 'Aralash')
                        : { both: 'Birga', lecture: 'Ma\'ruza', practice: 'Amaliy' }[st.mode];
                    let text;
                    if (st.multi) {
                        // Har tanlangan kunda yangi o'rin: xira soya; to'qnashuvli (server) — qizil; kunga sig'maydigan — kulrang, "sig'maydi".
                        const block = cycBlockByKey(st.key);
                        const dry = st.dry[dryKey()];
                        const srv = {};
                        ((dry && dry.days) || []).forEach(d => { srv[d.day_index] = d; });
                        let conf = 0, bad = 0;
                        st.multi.forEach(o => {
                            const dp = block && block.day_plan ? block.day_plan[o] : null;
                            if (!dp) return;
                            const m = modeOf(o);
                            const shape = cycDayShape(dp, m, st.delta, null);
                            const d = srv[dp.k - 1];
                            // Amaliy ma'ruza ustiga (server: blocked) — taklif qilinadi: qizil, sig'maydigan emas.
                            const offer = Boolean(d && m === 'practice' && d.status === 'blocked' && /Ma.ruza vaqti bilan ustma-ust/.test(d.why || ''));
                            // Server natijasi bo'lsa — o'sha (masalan, smenasi qotirilgan amaliy "Birga" surilmaydi); bo'lmasa — mijozdagi taxmin.
                            const nofit = !offer && (d ? ['nofit', 'blocked', 'past'].includes(d.status) : Boolean(cycDayShapeError(shape, dayHours, cycOverlapOk(m))));
                            const isConf = !nofit && Boolean(d && (d.status === 'conflict' || offer));
                            if (nofit) bad++; else if (isConf) conf++;
                            // Sig'maydigan kun — hozirgi joyida kulrang; qolganlari — yangi o'rnida.
                            const ranges = rangesOf(nofit ? cycDayShape(dp, m, 0, null) : shape, m);
                            let first = true;
                            cellsOf(st.key, o).forEach(c => {
                                const h = +c.dataset.mkHour;
                                if (!ranges.some(r => r && h >= r[0] && h < r[1])) return;
                                c.classList.add(nofit ? 'is-drag-nofit' : isConf ? 'is-drag-bad' : 'is-drag-ok');
                                if (nofit && first) { c.setAttribute('data-drag-note', 'sig\'maydi'); first = false; }
                            });
                        });
                        st.counts = { conf: conf, bad: bad };
                        text = (st.delta > 0 ? '+' : '') + st.delta + ' soat · ' + st.multi.length + ' kun'
                            + (conf ? ' · ' + conf + ' ta to\'qnashuv' : '') + (bad ? ' · ' + bad + ' ta sig\'maydi' : '')
                            + (st.staff && st.delta && dry === null ? ' · tekshirilmoqda…' : '') + ' (' + what.toLowerCase() + ')';
                    } else {
                        const moving = rangesOf(st.shape, st.mode);
                        cellsOf(st.key, st.offset).forEach(c => {
                            const h = +c.dataset.mkHour;
                            if (moving.some(r => r && h >= r[0] && h < r[1])) c.classList.add(st.bad ? 'is-drag-bad' : 'is-drag-ok');
                        });
                        const shown = st.mode === 'practice' ? st.shape.prc : st.shape.lec || st.shape.prc;
                        text = what + ': ' + timeOf(shown) + (st.bad ? ' — ' + st.bad : overText);
                    }
                    const tip = document.createElement('div');
                    tip.id = 'cycDragTip';
                    tip.className = (st.multi ? st.counts.conf || st.counts.bad : st.bad) ? 'is-bad' : '';
                    tip.textContent = text + (st.ask ? ' — so\'rov' : st.mode === 'both' || st.multi || st.fixed ? '' : ' (' + cycBothKeyLabel() + ' — birga)');
                    document.body.appendChild(tip);
                    tip.style.left = Math.min(window.innerWidth - tip.offsetWidth - 8, ev.clientX + 14) + 'px';
                    tip.style.top = Math.max(8, ev.clientY - 30) + 'px';
                    scheduleDry();
                };
                grid.addEventListener('pointerdown', ev => {
                    if (ev.button !== 0 || !cyclePlanData) return;
                    const cell = ev.target.closest ? ev.target.closest('.cyc-mk-cell.is-lecture, .cyc-mk-cell.is-practice') : null;
                    if (!cell || cell.disabled) return;
                    const key = cell.dataset.mkKey, offset = +cell.dataset.mkDay;
                    const block = cycBlockByKey(key);
                    const dp = block && block.day_plan ? block.day_plan[offset] : null;
                    if (!dp) return;
                    // Alohida ma'ruza bloki: kunlari blok joylashuvidan (panel / tashqi jadval) — kataklar sudralmaydi.
                    if (block.type === 'lecture' && block.lecture_separate) return;
                    const kind = cell.classList.contains('is-lecture') ? 'lecture' : 'practice';
                    const staff = Boolean(cyclePlanData.day_edit) && !(typeof TIMETABLE_READ_ONLY !== 'undefined' && TIMETABLE_READ_ONLY);
                    // O'qituvchi / fan mas'uli: sudrash — so'rov oynasi (shu darsga so'rash mumkin bo'lgan kunlar).
                    const card = (cyclePlanData.cycle_cards || []).find(item => item.key === key);
                    const askable = o => { const dpo = block.day_plan[o]; const dt = (cyclePlanData.dates || [])[block.from + (+o)];
                        return Boolean(dpo && dt && card && typeof cycCanAsk === 'function' && cycCanAsk(card, dpo, dt, cycLocalToday(), kind)); };
                    const ask = !staff && askable(offset);
                    if (!staff && !ask) return;
                    // Tanlangan bo'lak (shu kunning M yoki A si) sudralsa — butun tanlov, har kun o'z bo'laklari bilan; tanlanmagan katak — faqat
                    // shu kun (M — ma'ruza, A — amaliy, tugma bilan — birga).
                    const sel = cycSelOffsets(key);
                    const inSel = Boolean(cycMultiSel && cycMultiSel.key === key && (cycMultiSel.parts.get(offset) || new Set()).has(kind));
                    let multi = null, fixed = null;
                    if (inSel && ask && new Set(sel.flatMap(o => [...cycMultiSel.parts.get(o)])).size > 1) {
                        // So'rov bitta tur uchun: aralash tanlovni sudrab bo'lmaydi (kun oynasidagi so'rov tugmalari — har biri o'z turi bilan).
                        st = { key: key, offset: offset, x: ev.clientX, y: ev.clientY, moving: false, mixedAsk: true, dry: {} };
                        return;
                    }
                    if (inSel) {
                        multi = ask ? sel.filter(askable) : sel;
                        if (multi.length <= 1) { multi = null; if (!ask) fixed = cycSelModes(key)[offset] || null; }
                    }
                    const modes = multi && !ask ? cycSelModes(key) : null;
                    st = { key: key, offset: offset, hour: +cell.dataset.mkHour, dp: dp, kind: kind, x: ev.clientX, y: ev.clientY, moving: false, delta: 0,
                        staff: staff, ask: ask, multi: multi, fixed: fixed, look: multi && !ask ? cycSelLook(key) : null,
                        modes: modes ? Object.fromEntries(multi.map(o => [o, modes[o]])) : null, dry: {} };
                });
                document.addEventListener('pointermove', ev => {
                    if (!st) return;
                    if (!st.moving) {
                        if (Math.abs(ev.clientX - st.x) + Math.abs(ev.clientY - st.y) < 5) return;
                        st.moving = true;
                        if (st.mixedAsk) {
                            st.cancel = true;
                            ttToast('Tanlovda ma\'ruza va amaliy aralash — so\'rov bitta tur uchun. Bitta turini qoldiring (Ctrl+bosish) yoki kun oynasidagi '
                                + '"Ma\'ruza vaqtini so\'rash" / "Amaliy vaqtini so\'rash" tugmasini bosing.', 'warn');
                        }
                        closeCycDayPop();
                    }
                    if (st.cancel) return;
                    // Sichqoncha ostidagi katak soat qatori (bitta kun — shu kun ustuni, ko'p kun — tanlangan kunlardan istalgani);
                    // boshqa joyda — oxirgi qiymat qoladi.
                    const under = document.elementFromPoint(ev.clientX, ev.clientY);
                    const c = under && under.closest ? under.closest('.cyc-mk-cell') : null;
                    if (c && c.dataset.mkKey === st.key && (st.multi ? st.multi.includes(+c.dataset.mkDay) : +c.dataset.mkDay === st.offset)) {
                        st.delta = +c.dataset.mkHour - st.hour;
                    }
                    paint(ev);
                });
                const finish = async (ev, cancel) => {
                    const s0 = st;
                    st = null;
                    if (!s0 || !s0.moving) return;
                    clearTimeout(s0.dryTimer);
                    clear();
                    cycCellDragged = true;
                    setTimeout(() => { cycCellDragged = false; }, 0);
                    // Bekor / joyida qoldi — tanlov bo'yog'i rejim bo'yicha qayta chiziladi (saqlansa — jadval qayta yuklanib chiziladi).
                    if (cancel || !s0.delta || s0.cancel) { cycMultiPaint(); return; }
                    const block = cycBlockByKey(s0.key);
                    const date = block ? (cyclePlanData.dates || [])[block.from + s0.offset] : null;
                    if (s0.ask) {
                        // So'rov oynasi: tanlangan kunlar (yoki shu kun) va yangi vaqt oldindan to'ldiriladi; sabab so'raladi.
                        const card = (cyclePlanData.cycle_cards || []).find(item => item.key === s0.key);
                        const days = cycAskDays(block, s0.kind);
                        const offs = s0.multi || [s0.offset];
                        const r = s0.kind === 'lecture' ? s0.shape.lec : s0.shape.prc;
                        openCycleTimeProposal(Object.assign({}, card, { type: s0.kind }), cycAskDp(s0.dp, s0.kind), date,
                            { kind: s0.kind, days: days, preselect: days.filter(x => offs.includes(x.offset)).map(x => x.iso), start: r ? r[0] : null });
                        return;
                    }
                    if (s0.multi) {
                        const k = 'sel|' + s0.delta;
                        const ready = () => (s0.dry[k] && s0.dry[k].days && !s0.dry[k].error ? s0.dry[k] : null);
                        // Sudrash paytidagi tekshiruv hali ketmoqda — qayta so'ralmaydi: darhol "tekshirilmoqda…", javob kelishi bilan davom etadi.
                        // Tekshiruv boshlanmagan bo'lsa — cycDaysApply o'zi darhol ko'rsatadi va so'raydi.
                        if (!ready() && s0.dry[k] === null && s0.dryP && s0.dryP[k]) {
                            if (cycDaysBusy) { ttToast('Avvalgi surish hali tugamadi — kuting.', 'warn'); return; }
                            // Qulf kutishdan oldin olinadi: shu paytda ↑ ↓ boshqa surishni boshlamasin (ogohlantirish chiqadi), bu sudrash
                            // esa javob kelgach o'z qulfi bilan davom etadi (cycDaysApply bo'shatadi).
                            cycDaysBusy = true;
                            cycBusyShow(s0.key, s0.multi, s0.modes, 'tekshirilmoqda…');
                            try { await s0.dryP[k]; } finally { cycBusyHide(); }
                            await cycDaysApply(s0.key, s0.multi, s0.modes, s0.delta, ready(), { locked: true });
                            return;
                        }
                        await cycDaysApply(s0.key, s0.multi, s0.modes, s0.delta, ready());
                        return;
                    }
                    if (s0.bad) { ttToast('Ko\'chirib bo\'lmadi: ' + esc(s0.bad) + '.', 'warn'); return; }
                    // Faqat ma'ruza / faqat amaliy — tekshiruv (o'rin almashish rejasi, teskari taklif) va kerak bo'lsa tasdiq oynasi orqali.
                    if (s0.mode !== 'both') {
                        await cycDaysApply(s0.key, [s0.offset], s0.mode, s0.delta, null);
                        return;
                    }
                    // "Birga": kun boshi delta bilan (ma'ruzasiz kunda — amaliy boshi; amaliy o'z soatida bo'lsa ham kun boshi).
                    const from = +s0.dp.start || 1;
                    await moveCycDay(s0.key, s0.offset, from + s0.delta,
                        (date ? date.d + ' (' + s0.dp.k + '-kun)' : s0.dp.k + '-kun') + ': ' + from + '-soatdan → ' + (from + s0.delta) + '-soatdan (sudrab)', 'both');
                };
                document.addEventListener('pointerup', ev => finish(ev, false));
                document.addEventListener('pointercancel', ev => finish(ev, true));
                // Esc sudrash paytida — faqat sudrash bekor qilinadi (tanlov qoladi).
                document.addEventListener('keydown', ev => { if (ev.key === 'Escape' && st && st.moving) { ev.stopImmediatePropagation(); finish(ev, true); } });
                // Tugma sudrash paytida bosilsa / qo'yib yuborilsa — rejim darhol almashadi.
                const repaint = ev => { if (st && st.moving && !st.cancel) paint({ clientX: st.lastEv.clientX, clientY: st.lastEv.clientY, shiftKey: ev.shiftKey, altKey: ev.altKey, ctrlKey: ev.ctrlKey, metaKey: ev.metaKey }); };
                document.addEventListener('keydown', repaint);
                document.addEventListener('keyup', repaint);
                // Klaviatura: tanlangan kunlarda ↑ ↓ — 1 soatga (sudrash kabi; rejim — kun oynasidagi tanlov, sukut — birga); Ctrl+Z — qaytarish.
                const typing = t => t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));
                document.addEventListener('keydown', ev => {
                    if (typeof viewMode !== 'undefined' && viewMode !== 'cycle') return;
                    if (typing(ev.target) || document.getElementById('cycMultiDlg') || document.getElementById('teacherTimeProposal')) return;
                    if ((ev.ctrlKey || ev.metaKey) && !ev.shiftKey && !ev.altKey && String(ev.key).toLowerCase() === 'z' && cycLastUndo) {
                        ev.preventDefault();
                        cycUndo();
                        return;
                    }
                    if ((ev.key !== 'ArrowUp' && ev.key !== 'ArrowDown') || !cycMultiSel || !cyclePlanData || !cyclePlanData.day_edit
                        || (typeof TIMETABLE_READ_ONLY !== 'undefined' && TIMETABLE_READ_ONLY)) return;
                    ev.preventDefault();
                    // Har kun o'z tanlangan bo'laklari bilan (rejim radiosi tanlovni filtrlaydi), bitta qadam: yonidagi dars bilan o'rin almashish
                    // yoki 1 soat (step=jump).
                    const key = cycMultiSel.key;
                    const offs = cycSelOffsets(key);
                    if (!offs.length) { ttToast('Tanlangan kunlarda bu rejimdagi dars yo\'q.', 'warn'); return; }
                    cycDaysApply(key, offs, cycSelModes(key), ev.key === 'ArrowUp' ? -1 : 1, null, { extra: { step: 'jump' } });
                });
                // Xabardagi "Qaytarish".
                document.addEventListener('click', ev => {
                    const b = ev.target && ev.target.closest ? ev.target.closest('[data-cyc-undo]') : null;
                    if (!b) return;
                    ev.preventDefault();
                    b.disabled = true;
                    cycUndo();
                });
            }
            function setupCycleMarking() {
                const grid = $('cycleGrid');
                if (!grid || grid.dataset.mkReady) return;
                grid.dataset.mkReady = '1';
                setupCycCellDrag(grid);
                grid.addEventListener('click', ev => {
                    // To'qnashuv belgisi / "ma'ruzada muammo bor ↗" — tafsilot oynasi (fan oynasi ochilmaydi).
                    const cf = ev.target.closest ? ev.target.closest('[data-cf-key],[data-cf-lecture]') : null;
                    if (cf) {
                        ev.preventDefault();
                        ev.stopPropagation();
                        openCfPop(cf);
                        return;
                    }
                    // Guruhcha qatoridagi bo'lak ishorasi: o'sha bo'lak qatorini ochadi.
                    const ghost = ev.target.closest ? ev.target.closest('.cyc-ghost-btn[data-ghost-row]') : null;
                    if (ghost) {
                        ev.preventDefault();
                        cycleRowFilters = [ghost.dataset.ghostRow];
                        cycleRowFiltersApply();
                        return;
                    }
                    const subj = ev.target.closest ? ev.target.closest('.cyc-mk-title[data-mk-subj]') : null;
                    if (subj) {
                        ev.preventDefault();
                        if (cycTitleDragged) { cycTitleDragged = false; return; }   // siljitish tugadi — popover ochilmaydi
                        if (cycDaySel && cycDaySel.key === subj.dataset.mkSubj && cycDaySel.offset === -1) { closeCycDayPop(); return; }
                        openCycSubjPop(subj.dataset.mkSubj, subj);
                        return;
                    }
                    const cell = ev.target.closest ? ev.target.closest('.cyc-mk-cell') : null;
                    if (!cell || cell.disabled) return;
                    ev.preventDefault();
                    if (cycCellDragged) { cycCellDragged = false; return; }   // sudrash tugadi — kun oynasi ochilmaydi
                    const key = cell.dataset.mkKey, o = +cell.dataset.mkDay, hour = +cell.dataset.mkHour;
                    const popDay = cycDaySel && cycDaySel.key === key && cycDaySel.offset >= 0 ? cycDaySel.offset : null;
                    // Excel kabi: Ctrl/Cmd+bosish — bitta dars (M yoki A) qo'shish / olish; Shift+bosish — boshlanish nuqtasidan to'rtburchak;
                    // Ctrl+Shift — to'rtburchakni qo'shish (cycSelClick). Kun oynasi ochiq bo'lsa — yangilanadi.
                    if (ev.ctrlKey || ev.metaKey || ev.shiftKey) {
                        cycSelClick(key, o, hour, cycCellPart(cell), ev.ctrlKey || ev.metaKey, ev.shiftKey);
                        if (popDay !== null) openCycDayPop(key, popDay, document.querySelector('#cycleGrid .cyc-mk-cell.is-day-sel') || cell, true);
                        return;
                    }
                    // Oddiy bosish — boshlanish nuqtasi (faol katak) shu katak.
                    cycSelAnchor = { key: key, offset: o, hour: hour };
                    if (cycDaySel && cycDaySel.key === key && cycDaySel.offset === o) {
                        closeCycDayPop();
                        return;
                    }
                    // Tanlangan kun bosilsa — tanlov qoladi (so'rov / surish shu kunlar bilan); boshqa kun — tanlov tozalanadi.
                    openCycDayPop(key, o, cell, Boolean(cycMultiSel && cycMultiSel.key === key && cycMultiSel.offsets.has(o)));
                });
                // Blok sarlavhasida (fan nomi) ikki marta bosish — blokning barcha kunlari.
                grid.addEventListener('dblclick', ev => {
                    const subj = ev.target.closest ? ev.target.closest('.cyc-mk-title[data-mk-subj]') : null;
                    if (!subj) return;
                    ev.preventDefault();
                    closeCycDayPop();
                    cycSelAll(subj.dataset.mkSubj);
                });
                document.addEventListener('keydown', ev => { if (ev.key === 'Escape') { closeCycDayPop(); cycSelClear(); } });
                // Jadval aylantirilganda tepadagi yorliq tanlangan ustunlar bilan birga yuradi.
                const wrapEl = $('cycleGridWrap');
                if (wrapEl) wrapEl.addEventListener('scroll', () => { if (cycMultiSel) cycMultiPaint(); }, { passive: true });
                // Fan nomi (role=button) klaviaturadan ham ochiladi: Enter / Space.
                grid.addEventListener('keydown', ev => {
                    if (ev.key !== 'Enter' && ev.key !== ' ') return;
                    const subj = ev.target.closest ? ev.target.closest('.cyc-mk-title[data-mk-subj]') : null;
                    if (!subj) return;
                    ev.preventDefault();
                    subj.click();
                });
                document.addEventListener('mousedown', ev => {
                    if (ev.target.closest && (ev.target.closest('#cycDayPop') || ev.target.closest('.cyc-mk-cell') || ev.target.closest('.cyc-mk-title'))) return;
                    if (cycDaySel) closeCycDayPop();
                    // Bo'sh joyga bosish — kunlar tanlovi ham tozalanadi (yorliq, oyna, xabar va so'rov formasi — bundan mustasno).
                    if (cycMultiSel && !(ev.target.closest && ev.target.closest('#cycSelBadge, #cycMultiDlg, #ttToastBox, #teacherTimeProposal'))) cycSelClear();
                });
            }

            function setupCycleGridEvents() {
                if (cycleGridEventsReady) return;
                cycleGridEventsReady = true;
                const grid = $('cycleGrid');
                const cellOf = ev => ev.target && ev.target.closest ? ev.target.closest('[data-cycle-from]') : null;
                // Birlashtirilgan katakda aniq kun: katak boshidan sichqoncha
                // X-koordinatasigacha nechta ustun borligi hisoblanadi.
                const indexAt = (cell, ev) => {
                    const span = Math.max(1, +cell.dataset.cycleSpan || 1);
                    const visible = cycleVisibleIdx(+cell.dataset.cycleFrom || 0, span);
                    const rect = cell.getBoundingClientRect();
                    const colW = rect.width / visible.length;
                    const off = colW > 0 && ev.clientX != null ? Math.floor((ev.clientX - rect.left) / colW) : 0;
                    return visible[Math.min(visible.length - 1, Math.max(0, off))];
                };
                const clearDropMark = () => {
                    if (cycleDropCell) { cycleDropCell.classList.remove('cycle-drop-target'); cycleDropCell = null; }
                    clearCycleDropMark();
                };
                grid.addEventListener('dragenter', ev => { if (cellOf(ev)) ev.preventDefault(); });
                grid.addEventListener('dragover', ev => {
                    const cell = cellOf(ev);
                    if (!cell) return;
                    // dragover'da preventDefault bo'lmasa brauzer drop'ni umuman bermaydi.
                    ev.preventDefault();
                    if (ev.dataTransfer) ev.dataTransfer.dropEffect = 'move';
                    if (cycleDropCell !== cell) { cycleDropCell = cell; }

                    // Nishon aynan sichqoncha turgan kun ustuniga tushadi.
                    const index = indexAt(cell, ev);
                    const card = (cyclePlanData && cyclePlanData.cycle_cards || [])
                        .find(item => item.key === cycleDragKey);
                    const allowed = cycCardRowOk(card, cell.dataset.cycleRow);

                    markCycleDrop(cell, index, allowed);
                });
                grid.addEventListener('dragleave', ev => {
                    if (!ev.relatedTarget || !grid.contains(ev.relatedTarget)) clearDropMark();
                });
                grid.addEventListener('drop', async ev => {
                    const cell = cellOf(ev);
                    if (!cell) return;
                    ev.preventDefault();
                    clearDropMark();
                    // Kalit sudrash boshlanganda saqlanadi; ba'zi brauzerlarda
                    // u yo'qolsa, dataTransfer'dagi nusxadan olinadi.
                    const key = cycleDragKey || (ev.dataTransfer && ev.dataTransfer.getData('text/plain')) || '';
                    const card = (cyclePlanData.cycle_cards || []).find(item => item.key === key);
                    const rowKey = cell.dataset.cycleRow;
                    const index = indexAt(cell, ev);
                    cycleDragKey = null;
                    if (!card) {
                        showCyclePlacementResult(null, index, 'Karta ma\u2019lumoti topilmadi. Sahifani yangilab qayta urinib ko\u2018ring.');
                        return;
                    }
                    if (!cycCardRowOk(card, rowKey)) {
                        console.warn('Sikl: qator mos kelmadi', {kartaQatori: card.row_key, katakQatori: rowKey});
                        showCyclePlacementResult(card, index, 'Fan kartasini faqat o\u2018z oqimining qatoriga joylang.');
                        return;
                    }
                    await placeCycleCardAt(card, index, +cell.dataset.cyclePair || 1);
                });
                grid.addEventListener('dragstart', ev => {
                    // Belgilash rejimida bloklar ko'chirilmaydi.
                    if (cyclePlanData && cyclePlanData.mark_mode) { ev.preventDefault(); return; }
                    if (ev.target.closest && ev.target.closest('[data-cycle-gear]')) { ev.preventDefault(); return; }
                    const block = ev.target && ev.target.closest ? ev.target.closest('.cyc-block[data-cycle-key]') : null;
                    if (!block) return;
                    cycleDragKey = block.dataset.cycleKey;
                    ev.dataTransfer.effectAllowed = 'move';
                    ev.dataTransfer.setData('text/plain', cycleDragKey);
                    highlightCycleRow(cycleDragKey);
                });
                grid.addEventListener('dragend', () => { cycleDragKey = null; highlightCycleRow(null); clearDropMark(); });
                grid.addEventListener('click', async ev => {
                    const addBtn = ev.target.closest ? ev.target.closest('.cyc-addpair') : null;
                    if (addBtn) {
                        ev.preventDefault();
                        cyclePairsShown = (cyclePairsShown || 1) + 1;
                        if (cyclePlanData) renderCyclePlan(cyclePlanData);
                        return;
                    }
                    const gear = ev.target.closest ? ev.target.closest('[data-cycle-gear]') : null;
                    if (gear) { ev.preventDefault(); ev.stopPropagation(); openCycleAssign(gear.dataset.cycleGear); return; }
                    const shiftBtn = ev.target.closest ? ev.target.closest('[data-cycle-shift]') : null;
                    if (shiftBtn) {
                        ev.preventDefault();
                        ev.stopPropagation();
                        const block = shiftBtn.closest('.cyc-block');
                        const card = (cyclePlanData.cycle_cards || []).find(item => item.key === (block && block.dataset.cycleKey));
                        if (!card || !card.placed) return;
                        const direction = +shiftBtn.dataset.cycleShift;
                        shiftBtn.disabled = true;
                        try {
                            const result = await api(BASE + '/boards/' + board.id + '/cycle-place', 'POST', {
                                ...cycleOverlapParams(), ...cycleLayerParams(),
                                action: 'shift', specialty_name: card.specialty, course: card.course,
                                group_name: card.group, subject_name: card.subject, start_index: card.start_index,
                                training_type: card.type || 'practice', pair: card.pair || 1, view: card.view || cycleEffView(), placement_group: (card && card.placement_group) || undefined,
                                direction: direction, start_date: $('cycleStart').value, holidays: cycleHolidays,
                            });
                            await loadCyclePlan();
                            $('cycleMsg').textContent = (result.shifted || 0) + ' ta sikl karta ' +
                                (direction < 0 ? '1 o\'quv kuni orqaga' : '1 o\'quv kuni oldinga') + ' surildi.';
                        } catch (e) {
                            alert('Sikl kartalarini surib bo\'lmadi: ' + e.message);
                        } finally {
                            shiftBtn.disabled = false;
                        }
                        return;
                    }
                    const cell = cellOf(ev);
                    if (!cell || !cycleDragKey) return;
                    const card = (cyclePlanData.cycle_cards || []).find(item => item.key === cycleDragKey);
                    const rowKey = cell.dataset.cycleRow;
                    const index = indexAt(cell, ev);
                    cycleDragKey = null;
                    highlightCycleRow(null);
                    if (!card || !cycCardRowOk(card, rowKey)) {
                        showCyclePlacementResult(card, index, card
                            ? 'Fan kartasini faqat o\u2018z oqimining qatoriga joylang.'
                            : 'Karta ma\u2019lumoti topilmadi. Sahifani yangilab qayta urinib ko\u2018ring.');
                        return;
                    }
                    placeCycleCardAt(card, index, +cell.dataset.cyclePair || 1);
                });
            }
            // ── Sikl paneli va hafta tanlovi (weekSel) ──
            // Hafta tanlangan bo'lsa panel faqat shu haftaga tegishli kartalarni ko'rsatadi ("Butun semestr" — hammasi), hisoblagichlar
            // ham shu tanlov bo'yicha; jadval shu hafta ustunlariga suriladi, qolgan sanalar xira.
            let cyclePanelAll = false, cyclePanelWeek = null, cycleWkScrolled = null;
            const isoOf = d => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
            // Tanlangan hafta: {from, to (dushanba–yakshanba, Y-m-d), label: "8-hafta (02.11–07.11)"}; tanlanmagan — null.
            function cycleSelWeek() {
                if (!curWeek) return null;
                const a = weekMonday(curWeek);
                if (!a) return null;
                const b = new Date(a);
                b.setDate(b.getDate() + 6);
                return { from: isoOf(a), to: isoOf(b), label: curWeek + '-hafta (' + weekDates(curWeek) + ')' };
            }
            // To'qnashuv yozuvi shu haftada (kelgusi sanalar; o'tgan yozuv — butun oralig'i).
            const cfItemInWeek = (i, wk) => { const a = i.date_from || i.from, b = i.date_to || i.to || a; return Boolean(a && a <= wk.to && b >= wk.from); };
            // Panel kartasi shu haftaga tegishlimi: joylanmagan — doim; joylangan, lekin to'qnashuvli — to'qnashuv sanasi shu haftada.
            function cycleCardInWeek(card, wk) {
                if (!wk || !card.placed) return true;
                return (card.conflicts || []).some(i => cfItemInWeek(i, wk));
            }
            // Panel kartasi holati: "joylanmagan" yoki "joylangan · to'qnashuv 13.11–24.11" (kelgusi sanalar, bo'lmasa — hammasi).
            function cycleCardStateText(card) {
                if (!card.placed) return 'joylanmagan';
                const live = cfLive(card.conflicts), items = live.length ? live : (card.conflicts || []);
                const a = items.map(i => i.date_from || i.from).filter(Boolean).sort()[0];
                const b = items.map(i => i.date_to || i.to || i.date_from || i.from).filter(Boolean).sort().pop();
                return 'joylangan · to\u2018qnashuv' + (a ? ' ' + cfDate(a) + (b && b !== a ? '–' + cfDate(b) : '') : '');
            }
            // "Vaqtincha kafedra mudirida" belgisi shu haftadami: belgi sanalari (amaliy — mudir_ph, oqim ma'ruzasi — mudir_ph_lec) hafta
            // oralig'ida; sanasiz belgi (butun blok) — blok sanalari (start_index–end_index) hafta bilan kesishsa. Joylangan va to'qnashuvsiz
            // karta ham (panel ro'yxatidagi cycleCardInWeek mezonidan farqli).
            function cyclePhInWeek(card, wk, dates) {
                if (!wk) return true;
                const a = (dates || [])[card.start_index], b = (dates || [])[card.end_index ?? card.start_index] || a;
                return [card.mudir_ph, card.mudir_ph_lec].filter(Boolean).some(ph => (ph.dates && ph.dates.length
                    ? ph.dates.some(d => d >= wk.from && d <= wk.to)
                    : !a || (a.iso <= wk.to && b.iso >= wk.from)));
            }
            // Panel guruh filtri: jadvaldagi ko'p tanlov (cycleRowFilters — bo'lak qatorlari bilan) va oqim tanlovi.
            function cycleCardGroupMatch(card, rowKeys) {
                return (!rowKeys || (card.row_keys || [card.row_key]).some(k => rowKeys.has(k))) && (!cycleGroupFilter || card.group === cycleGroupFilter);
            }
            // Jadval: tanlangan hafta ustunlari ajratiladi, boshqa sanalar va hafta tashqarisidagi bloklar xira; hafta almashganda — scroll.
            function cycleWeekHighlight() {
                const grid = $('cycleGrid');
                if (!grid || !cyclePlanData || viewMode !== 'cycle') return;
                const wk = cycleSelWeek(), on = Boolean(wk && !cyclePanelAll);
                const idx = [];
                (cyclePlanData.dates || []).forEach((d, i) => { if (on && d.iso >= wk.from && d.iso <= wk.to) idx.push(i); });
                const lo = idx.length ? idx[0] : -1, hi = idx.length ? idx[idx.length - 1] : -1;
                let first = null;
                grid.querySelectorAll('thead .cyc-dcol').forEach((th, i) => {
                    const inside = on && lo >= 0 && i >= lo && i <= hi;
                    th.classList.toggle('cyc-wk-on', inside);
                    th.classList.toggle('cyc-wk-out', on && !inside);
                    // Yashirilgan dam olish ustuni (eni 0) — keyingi ko'rinadigan kun.
                    if (inside && !first && !th.classList.contains('cyc-col-hidden')) first = th;
                });
                grid.querySelectorAll('td.cyc-block[data-cycle-from]').forEach(td => {
                    const from = +td.dataset.cycleFrom, to = from + Math.max(1, +td.dataset.cycleSpan || 1) - 1;
                    td.classList.toggle('cyc-wk-out', on && (lo < 0 || to < lo || from > hi));
                });
                const key = on ? wk.from : '';
                if (on && first && cycleWkScrolled !== key) cycleScrollToDay(first);
                cycleWkScrolled = key;
            }
            // Tanlangan haftaning birinchi kuni qotirilgan ustunlardan darhol keyin, ko'rinadigan maydon boshida turadi
            // (scrollIntoView "center" sticky ustunlarni hisobga olmaydi — hafta o'ng chetdan tashqarida qolardi).
            function cycleScrollToDay(th) {
                const wrap = $('cycleGridWrap'), grid = $('cycleGrid');
                if (!wrap || !grid || !th.getBoundingClientRect) return;
                // Chapdagi qotirilgan (sticky) "Guruh/Oqim" va "Para" ustunlarining o'ng cheti (ekranda; ular doim chap chetda turadi) —
                // kun ustuni aynan shu yerga keladi.
                let edge = wrap.getBoundingClientRect().left;
                grid.querySelectorAll('thead .cyc-gcol, thead .cyc-mk-side').forEach(c => { edge = Math.max(edge, c.getBoundingClientRect().right); });
                wrap.scrollLeft = Math.round(wrap.scrollLeft + th.getBoundingClientRect().left - edge);   // brauzer 0..max oralig'iga o'zi cheklaydi
            }
            // Panel qamrovi (guruh filtri va tanlangan hafta; "Butun semestr" — butun semestr): panel ro'yxati ham, "Sikl bloklari"
            // hisoblagichi ham shu to'plamdan. Hafta bo'yicha — to'qnashuvlar ro'yxati ham shu haftaniki. ph — "Vaqtincha kafedra mudirida"
            // bo'limi: shu guruh filtri, hafta bo'yicha esa belgi sanalari (joylangan va to'qnashuvsiz bo'lsa ham).
            function cycleScopedCards(j) {
                const cycleCards = (j && j.cycle_cards) || [];
                const wk = cycleSelWeek(), wkOn = Boolean(wk && !(cyclePanelWeek === curWeek && cyclePanelAll));
                const rowKeys = cycleRowFilters.length ? new Set(cycleVisibleRows((j && j.rows) || []).map(r => r.row_key)) : null;
                const scoped = cycleCards.filter(card => cycleCardGroupMatch(card, rowKeys) && (!wkOn || cycleCardInWeek(card, wk)))
                    .map(card => (wkOn && card.placed ? Object.assign({}, card, { conflicts: (card.conflicts || []).filter(i => cfItemInWeek(i, wk)) }) : card));
                const dates = (j && j.dates) || (cyclePlanData && cyclePlanData.dates) || [];
                const ph = cycleCards.filter(card => (card.mudir_ph || card.mudir_ph_lec) && cycleCardGroupMatch(card, rowKeys) && (!wkOn || cyclePhInWeek(card, wk, dates)));
                return { wk, wkOn, scoped, ph };
            }
            // "Vaqtincha kafedra mudirida" bo'limi (panel ostida): qamrovdagi belgili bloklar — mudir, sanalar, sabab va "Asl holatga qaytarish".
            function cycPhSectionHtml(cards) {
                const list = (cards || []).filter(c => c.mudir_ph || c.mudir_ph_lec).sort((a, b) => (a.group + a.subject).localeCompare(b.group + b.subject, 'uz', { numeric: true }));
                if (!list.length) return '';
                return '<div class="cyc-ph-sec" data-cyc-ph-sec><b>Vaqtincha kafedra mudirida — ' + list.length + ' ta</b>' + list.map(c => {
                    const ph = c.mudir_ph || c.mudir_ph_lec;
                    const ds = (ph.dates && ph.dates.length ? ph.dates.map(cfDate).join(', ') : 'butun blok') + (c.mudir_ph_lec ? (c.mudir_ph ? ' (+ ma‘ruza)' : ' (ma‘ruza)') : '');
                    return '<div class="cyc-ph-item"><div><b>' + esc(c.group) + '</b> · ' + esc(c.subject) + '</div><div>' + esc(ph.mudir_name || ph.teacher_name || '') +
                        ' (asl: ' + esc(ph.orig_teacher_name || '—') + '); ' + esc(ds) + (ph.reason ? '; sabab: ' + esc(ph.reason) : '') + '</div>' +
                        (cycActAllowed() ? '<button type="button" data-cyc-ph-revert-key="' + esc(c.key) + '">Asl holatga qaytarish</button>' : '') + '</div>';
                }).join('') + '</div>';
            }
            function renderCycleCards(j) {
                const cycleCards = (j && j.cycle_cards) || [];
                const groups = [...new Set(cycleCards.map(card => card.group).filter(Boolean))]
                    .sort((a, b) => a.localeCompare(b, 'uz', { numeric: true }));
                const groupFilter = $('cycleGroupFilter');
                groupFilter.innerHTML = '<option value="">Barcha oqimlar</option>' + groups.map(group =>
                    '<option value="' + esc(group) + '" title="' + esc(group) + '">' + esc(group) + '</option>'
                ).join('');
                if (!groups.includes(cycleGroupFilter)) cycleGroupFilter = '';
                groupFilter.value = cycleGroupFilter;
                groupFilter.classList.toggle('hidden', !groups.length);
                groupFilter.onchange = () => {
                    cycleGroupFilter = groupFilter.value;
                    renderCycleCards(j);
                };
                $('skipToggle').classList.add('hidden');
                $('unplacedExportBtn').classList.add('hidden');
                $('subjectColorsBtn').classList.toggle('hidden', !cycleCards.length);
                $('cardPanelTitle').textContent = 'Sikl fan kartalari';
                if (j && j.mark_mode && j.mark_ready === false) {
                    $('cycleMsg').textContent = 'Diqqat: ma' + String.fromCharCode(39) + 'ruza belgilari uchun migratsiya bajarilmagan (php artisan migrate).';
                }
                $('cardPanelHint').textContent = TIMETABLE_READ_ONLY
                    ? 'Faqat ko\u2018rish: to\u2018qnashuv belgisini bosing — tafsilot.'
                    : (j && j.mark_mode)
                    ? 'Blok ichidagi kataklarni bosing yoki sudrang — belgilangan soatlar ma\'ruza bo\'ladi.'
                    : 'Kartani bosing, so‘ng o‘z oqim qatoridagi boshlanish kunini bosing (yoki sudrab tashlang)';
                $('cardPanelHint').classList.remove('hidden');
                // Hafta tanlovi: boshqa hafta tanlansa — yana shu hafta bo'yicha ("Butun semestr" o'chadi).
                if (cyclePanelWeek !== curWeek) { cyclePanelWeek = curWeek; cyclePanelAll = false; }
                const { wk, wkOn, scoped, ph } = cycleScopedCards(j);
                // To'qnashuvli blok (joyida, lekin o'qituvchi yoki xona band) ham joylanmaganlar qatorida — sababi bilan.
                const unplaced = scoped.filter(card => (!card.placed || card.conflict) && (!cycleCfFilter || cfMatchesFilter(card, cycleCfFilter))).sort((a, b) =>
                    (a.group + a.subject).localeCompare(b.group + b.subject, 'uz', { numeric: true }));
                $('unplacedCount').textContent = unplaced.length + ' ta';
                // Sarlavha: "8-hafta (02.11–07.11): N ta · vaqtincha kafedra mudirida: M ta" (bosilsa — bo'limga) va "Butun semestr" almashtirgichi.
                const phGo = ph.length ? ' <button type="button" class="cyc-ph-go" data-cyc-ph-go title="Bosing — «Vaqtincha kafedra mudirida» bo\u2018limiga">· vaqtincha kafedra mudirida: ' + ph.length + ' ta</button>' : '';
                const wkHead = wk ? '<div class="cyc-wk-head"><span>' + esc((wkOn ? wk.label : 'Butun semestr') + ': ' + unplaced.length + ' ta') + phGo + '</span>' +
                    '<label class="cyc-wk-all"><input type="checkbox" data-cyc-all' + (cyclePanelAll ? ' checked' : '') + '> Butun semestr</label></div>' : '';
                // Yig'indi: kelgusi to'qnashuvlar turlari bo'yicha (tanlov — hafta va guruhlar); bosilsa — shu turdagi kartalar.
                const cfN = cfSummaryCounts(scoped);
                const cfBtn = (k, label) => '<button type="button" data-cf-filter="' + k + '" class="cf-sum-btn' + (cycleCfFilter === k ? ' on' : '') + '">' + label + ' — ' + cfN[k] + '</button>';
                const cfSummary = (cfN.teacher || cfN.room || cycleCfFilter)
                    ? '<div class="cf-summary">Kelgusi to\u2018qnashuvlar: ' + cfBtn('teacher', 'o\u2018qituvchi') + ', ' + cfBtn('room', 'xona') +
                        (cycleCfFilter ? ' <button type="button" data-cf-filter="" class="cf-sum-clear">hammasi</button>' : '') + '</div>' : '';
                $('cardPanel').innerHTML = wkHead + cfSummary + (unplaced.map(card => {
                    // Panel kartasi jadvaldagi blok bilan bir xil rangda — qaysi fan
                    // qayerga tushishi ko'rinib tursin.
                    const color = subjColor(card.subject);
                    // Alohida ma'ruza kartasi sodda ko'rinishda ham belgilanadi (oqim qatoriga, amaliydan alohida joylanadi).
                    const typeChip = (j && j.simple && !card.separate)
                        ? ''
                        : '<span class="cycle-pn-type ' + (card.type || 'practice') + '">' + (card.type === 'lecture' ? "Ma'ruza" : 'Amaliy') + '</span>';
                    // Oqim ma'ruzasi to'qnashuvi — faqat ma'ruza egasi kartasida; boshqalarida "ma'ruzada muammo bor ↗" (bosiladi).
                    const split = card.conflict ? cfSplit(card.key, card.conflicts, cfOwners) : { own: [], elsewhere: [] };
                    const lvl = card.conflict ? cfLevel(split.own) : null;
                    const ownText = cfBadgeText(split.own);
                    return '<div class="cycle-pn-card' + infoOnlyClass(card) + (lvl === 'red' ? ' is-conflict' : lvl === 'yellow' ? ' is-conflict-warn' : '') + '" draggable="' + (TIMETABLE_READ_ONLY ? 'false' : 'true') + '" data-cycle-key="' + esc(card.key) +
                        '" style="background:' + color.bg + ';border-left-color:' + color.border + ';" ' +
                        'title="' + esc(card.subject) + ' — ' + esc(card.group) + '">' +
                        '<span class="cycle-pn-subject">' + typeChip + esc(card.subject) + infoOnlyBadgeHtml(card) + '</span>' +
                        '<span class="cycle-pn-meta"><span>' + esc(cycleFlowShort(card.group)) + ' · ' + esc(card.course) + '-kurs</span><span class="cycle-pn-days">' + card.days + ' kun' + (card.hours ? ' · ' + card.hours + ' soat' : '')
                            + ((card.lecture_list || []).length ? ' (' + card.lecture_list.join('+') + ')' : '') + '</span></span>' +
                        // Holat: "joylanmagan" yoki "joylangan · to'qnashuv 13.11–24.11" (joylanmagan bilan aralashmasin).
                        '<span class="cycle-pn-state' + (card.placed ? ' is-placed' : '') + '">' + esc(cycleCardStateText(card)) + '</span>' +
                        (card.conflict && (ownText || !split.elsewhere.length)
                            ? '<span class="cycle-pn-conflict lvl-' + (lvl || 'red') + '" role="button" tabindex="0" data-cf-key="' + esc(card.key) + '" title="Bosing — tafsilot">⚠ ' + esc(ownText || card.conflict) + '</span>' : '') +
                        split.elsewhere.map(id => '<span class="cf-lecture-link" role="button" tabindex="0" data-cf-lecture="' + id + '" title="Oqim ma\'ruzasi to\'qnashuvi — bir marta, ma\'ruza egasi blokida">ma\'ruzada muammo bor ↗</span>').join('') +
                        '</div>';
                }).join('') || '<div class="text-xs text-slate-400 p-2">' + (wkOn ? 'Bu haftada joylanmagan yoki to\u2018qnashuvli sikl kartasi yo\u2018q.'
                    : 'Barcha sikl fan kartalari joylashgan.') + '</div>') + cycPhSectionHtml(ph);
                $('cardPanel').querySelectorAll('[data-cf-filter]').forEach(b => b.onclick = () => {
                    cycleCfFilter = cycleCfFilter === b.dataset.cfFilter ? '' : b.dataset.cfFilter;
                    renderCycleCards(j);
                });
                $('cardPanel').querySelectorAll('[data-cyc-ph-revert-key]').forEach(b => b.onclick = ev => {
                    ev.stopPropagation();
                    const c = cycleCards.find(x => x.key === b.dataset.cycPhRevertKey);
                    if (c) cycPhRevert(c, b);
                });
                const allBox = $('cardPanel').querySelector('[data-cyc-all]');
                if (allBox) allBox.onchange = () => { cyclePanelAll = allBox.checked; renderCycleCards(j); };
                // Sarlavhadagi "vaqtincha kafedra mudirida: N ta" — panel ichida bo'limga suriladi (sahifa siljimaydi) va bir lahza ajraladi.
                const phGoBtn = $('cardPanel').querySelector('[data-cyc-ph-go]');
                if (phGoBtn) phGoBtn.onclick = () => {
                    const pn = $('cardPanel'), sec = pn.querySelector('[data-cyc-ph-sec]');
                    if (!sec) return;
                    pn.scrollTop = Math.max(0, Math.round(pn.scrollTop + sec.getBoundingClientRect().top - pn.getBoundingClientRect().top));
                    sec.classList.remove('cyc-ph-flash');
                    void sec.offsetWidth;   // animatsiya qayta boshlansin
                    sec.classList.add('cyc-ph-flash');
                };
                cycleWeekHighlight();
                if (typeof renderStats === 'function') renderStats();   // "Sikl bloklari" — shu qamrov bo'yicha (guruh, hafta, "Butun semestr")
                $('cardPanel').querySelectorAll('.cycle-pn-card').forEach(card => {
                    // Faqat ko'rish rejimi: joylash ko'rsatmalari va sudrash yo'q.
                    if (TIMETABLE_READ_ONLY) return;
                    // Bosib tanlash: sudrash ishlamagan holatlarda ham karta
                    // joylanadi — tanlangan karta belgilanib turadi, keyin
                    // jadvaldan boshlanish kuni bosiladi.
                    // Bosilsa — karta oynasi (haftalikdagidek): o'qituvchi / xona jadvali, "Joylash uchun tanlash", "Tashqi jadvaldagi
                    // joyiga joylash", to'qnashuvli blokka — smena, boshqa o'qituvchi, vaqtincha kafedra mudiri. Tanlangan karta qayta
                    // bosilsa — tanlov bekor qilinadi.
                    card.addEventListener('click', () => {
                        if (cycleDragKey === card.dataset.cycleKey) {
                            cycleDragKey = null;
                            card.classList.remove('cycle-pn-selected');
                            highlightCycleRow(null);
                            $('cycleMsg').textContent = '';
                            return;
                        }
                        openCycCardPop(card.dataset.cycleKey, card);
                    });
                    card.addEventListener('dragstart', ev => {
                        cycleDragKey = card.dataset.cycleKey;
                        ev.dataTransfer.effectAllowed = 'move';
                        ev.dataTransfer.setData('text/plain', cycleDragKey);
                        highlightCycleRow(cycleDragKey);
                    });
                    card.addEventListener('dragend', () => { cycleDragKey = null; highlightCycleRow(null); });
                });
                $('cardPanel').ondragover = ev => { if (cycleDragKey) ev.preventDefault(); };
                $('cardPanel').ondrop = async ev => {
                    ev.preventDefault();
                    if (!cycleDragKey) return;
                    const card = cycleCards.find(item => item.key === cycleDragKey);
                    cycleDragKey = null;
                    if (!card || !card.placed) return;
                    try {
                        await api(BASE + '/boards/' + board.id + '/cycle-place', 'POST', {
                            ...cycleOverlapParams(), ...cycleLayerParams(),
                            action: 'remove', specialty_name: card.specialty, course: card.course,
                            group_name: card.group, subject_name: card.subject,
                            training_type: card.type || 'practice', view: card.view || cycleEffView(), placement_group: (card && card.placement_group) || undefined,
                        });
                        await loadCyclePlan();
                    } catch (e) { alert('Sikl blokini olib bo‘lmadi: ' + e.message); }
                };
            }
            // ── Fan ranglari modali ──
            // Ro'yxat modal ochilganda quriladi; tanlangan ranglar Saqlashda
            // doska sozlamalariga yoziladi va jadval qayta chiziladi.
            let scDraft = {};
            function openSubjectColorsModal() {
                const names = [...new Set(((cyclePlanData && cyclePlanData.cycle_cards) || [])
                    .map(card => card.subject).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'uz'));
                if (!names.length) {
                    alert('Sikl fanlari topilmadi.');
                    return;
                }
                scDraft = { ...subjectColorOverrides };
                $('scList').innerHTML = names.map(name => {
                    const color = subjColor(name);
                    const custom = scDraft[name] ? ' checked' : '';
                    return '<label class="flex items-center gap-3 py-1.5 border-b border-gray-50 last:border-0">' +
                        '<input type="color" class="sc-input w-9 h-8 p-0 border border-gray-200 rounded cursor-pointer" ' +
                            'data-subject="' + esc(name) + '" value="' + esc(color.bg) + '">' +
                        '<span class="flex-1 text-xs text-gray-700">' + esc(name) + '</span>' +
                        '<span class="text-[10px] text-gray-400 flex items-center gap-1">' +
                            '<input type="checkbox" class="sc-auto" data-subject="' + esc(name) + '"' +
                            (custom ? '' : ' checked') + '> avtomatik</span></label>';
                }).join('');
                $('scList').querySelectorAll('.sc-input').forEach(input => {
                    input.oninput = () => {
                        scDraft[input.dataset.subject] = input.value.toLowerCase();
                        const auto = $('scList').querySelector('.sc-auto[data-subject="' + CSS.escape(input.dataset.subject) + '"]');
                        if (auto) auto.checked = false;
                    };
                });
                $('scList').querySelectorAll('.sc-auto').forEach(box => {
                    box.onchange = () => {
                        if (box.checked) delete scDraft[box.dataset.subject];
                        else scDraft[box.dataset.subject] = subjColor(box.dataset.subject).bg;
                    };
                });
                $('subjectColorsModal').classList.remove('hidden');
            }
            if ($('subjectColorsBtn')) $('subjectColorsBtn').onclick = openSubjectColorsModal;
            if ($('scClose')) $('scClose').onclick = () => $('subjectColorsModal').classList.add('hidden');
            if ($('scReset')) $('scReset').onclick = () => { scDraft = {}; openSubjectColorsModalRefresh(); };
            function openSubjectColorsModalRefresh() {
                subjectColorOverrides = { ...scDraft };
                $('subjectColorsModal').classList.add('hidden');
                openSubjectColorsModal();
            }
            if ($('scSave')) $('scSave').onclick = async () => {
                subjectColorOverrides = { ...scDraft };
                try {
                    await saveSubjectColorOverrides();
                    $('subjectColorsModal').classList.add('hidden');
                    if (cyclePlanData) { renderCyclePlan(cyclePlanData); renderCycleCards(cyclePlanData); }
                } catch (e) { alert('Ranglarni saqlab bo‘lmadi: ' + e.message); }
            };

            if ($('cycleRefresh')) $('cycleRefresh').onclick = () => loadCyclePlan();
            // Ko'rinish rejimi: oqim bo'yicha / guruh bo'yicha
            function setCycleViewMode(mode) {
                if (cycleViewMode === mode) return;
                cycleViewMode = mode;
                const on = ['bg-blue-600', 'font-semibold', 'text-white'];
                const off = ['bg-white', 'text-gray-500'];
                [['cycViewFlow', 'flow'], ['cycViewGroup', 'group']].forEach(([id, m]) => {
                    const btn = $(id);
                    if (!btn) return;
                    btn.classList.remove(...on, ...off);
                    btn.classList.add(...(m === mode ? on : off));
                });
                loadCyclePlan();
            }
            if ($('cycViewFlow')) $('cycViewFlow').onclick = () => setCycleViewMode('flow');
            if ($('cycViewGroup')) $('cycViewGroup').onclick = () => setCycleViewMode('group');
            if ($('cycleStart')) $('cycleStart').onchange = loadCyclePlan;
            // Qatlam: tashqi / ichki
            function setCycleLayer(layer) {
                if (cycleLayer === layer) return;
                cycleLayer = layer;
                renderCycleLayerUi(null);
                loadCyclePlan();
            }
            if ($('cycLayerExternal')) $('cycLayerExternal').onclick = () => setCycleLayer('external');
            function renderMineUi() {
                [['mineAll', 'all'], ['mineKafedra', 'kafedra'], ['mineSubjects', 'subjects'], ['mineOnly', 'mine']].forEach(([id, mode]) => {
                    const b = $(id);
                    if (b) b.className = 'px-2 py-1 ' + (scopeMode === mode ? 'bg-blue-600 font-semibold text-white' : 'bg-white text-gray-500');
                });
            }
            function setScopeMode(mode) {
                if (scopeMode === mode) return;
                scopeMode = mode;
                mineOnly = mode !== 'all';
                try { localStorage.setItem(SCOPE_KEY, mode); } catch (e) { }
                renderMineUi();
                // O'qituvchi / fan mas'uli / kafedra mudiri: doska shu qamrov bilan qayta yuklanadi (server faqat kerakli kartalarni beradi).
                if (TIMETABLE_SCOPED_DATA && board) {
                    loadBoard(board.id).then(() => { if (viewMode === 'cycle') loadCyclePlan(); }).catch(e => alert('Xatolik: ' + e.message));
                    return;
                }
                cards = scopeCards(allCards);
                // Oldingi qamrov bo'sh edi (ish maydoni yashirin) yoki yangisi bo'sh — ro'yxat/ko'rinish qaytadan
                // (qamrov tugmalari yashirinib qolmasin).
                if ($('mainArea').classList.contains('hidden') || !cards.length) showLoadedCards();
                else if (typeof renderAll === 'function') renderAll();
                if (viewMode === 'cycle') loadCyclePlan();
            }
            function renderWeeklyLayerUi() {
                [['wkLayerExternal', 'external'], ['wkLayerInternal', 'internal']].forEach(([id, l]) => {
                    const b = $(id);
                    if (b) b.className = 'px-2 py-1 ' + (weeklyLayer === l ? 'bg-blue-600 font-semibold text-white' : 'bg-white text-gray-500');
                });
                if ($('weeklyLayerBox')) $('weeklyLayerBox').classList.toggle('hidden', viewMode === 'cycle');
                if ($('weeklyExcel')) $('weeklyExcel').classList.toggle('hidden', viewMode === 'cycle');
                if ($('compactWeekBtn')) $('compactWeekBtn').classList.toggle('hidden',
                    !(WEEKLY_ADMIN && weeklyLayer === 'internal' && curWeek && viewMode !== 'cycle'));
                if ($('suggestWeekBtn')) $('suggestWeekBtn').classList.toggle('hidden',
                    !(SUGGEST_ROLES.includes(TIMETABLE_ROLE) && weeklyLayer === 'internal' && curWeek && viewMode !== 'cycle'));
                document.body.classList.toggle('tt-weekly-external', weeklyLayer === 'external');
            }
            async function setWeeklyLayer(l) {
                if (weeklyLayer === l) return;
                weeklyLayer = l;
                try { localStorage.setItem('lms:timetable-weekly-layer', l); } catch (e) { }
                selected = null;
                renderWeeklyLayerUi();
                // Serverdan qayta yuklanadi: shu ko'rinishda joyida qilingan biriktirishlar (o'qituvchi/xona)
                // kartaning birinchi yuklashdagi nusxasidan tiklanib, eskisi qaytib chiqmasin.
                if (board) {
                    try { await loadBoard(board.id); } catch (e) { alert('Xatolik: ' + e.message); }
                }
            }
            if ($('wkLayerExternal')) { $('wkLayerExternal').onclick = () => setWeeklyLayer('external'); $('wkLayerInternal').onclick = () => setWeeklyLayer('internal'); renderWeeklyLayerUi(); }
            if ($('mineAll')) {
                $('mineAll').onclick = () => setScopeMode('all');
                $('mineOnly').onclick = () => setScopeMode('mine');
                if ($('mineKafedra')) $('mineKafedra').onclick = () => setScopeMode('kafedra');
                if ($('mineSubjects')) $('mineSubjects').onclick = () => setScopeMode('subjects');
                renderMineUi();
            }
            if ($('cycLayerInternal')) $('cycLayerInternal').onclick = () => setCycleLayer('internal');
            // Dam olish kunlarini yashirish (brauzerda eslab qolinadi)
            if ($('cycleHideOff')) {
                $('cycleHideOff').checked = cycleHideOff;
                $('cycleHideOff').onchange = () => {
                    cycleHideOff = $('cycleHideOff').checked;
                    try { localStorage.setItem('lms:cycle-hide-off', cycleHideOff ? '1' : '0'); } catch (e) { }
                    if (cyclePlanData) { renderCyclePlan(cyclePlanData); renderCycleCards(cyclePlanData); }
                };
            }
            // Sikl kesishishiga ruxsat (doska bo'yicha brauzerda eslab qolinadi)
            function cycleOverlapKey() { return board ? 'lms:cycle-overlap:' + board.id : ''; }
            function cycleOverlapParams() {
                const on = !!($('cycleAllowOverlap') && $('cycleAllowOverlap').checked);
                const days = Math.max(1, parseInt(($('cycleOverlapDays') || {}).value, 10) || 1);
                const gap = { ignore_gap: $('cycleIgnoreGap') && $('cycleIgnoreGap').checked ? 1 : 0 };
                return on ? { allow_overlap: 1, overlap_days: days, ...gap } : { allow_overlap: 0, ...gap };
            }
            function syncCycleOverlapUi() {
                if (!$('cycleAllowOverlap')) return;
                $('cycleOverlapDays').disabled = !$('cycleAllowOverlap').checked;
                try { localStorage.setItem(cycleOverlapKey(), JSON.stringify(cycleOverlapParams())); } catch (e) { }
            }
            function loadCycleOverlapUi() {
                if (!$('cycleAllowOverlap')) return;
                let saved = null;
                try { saved = JSON.parse(localStorage.getItem(cycleOverlapKey()) || 'null'); } catch (e) { }
                $('cycleAllowOverlap').checked = !!(saved && saved.allow_overlap);
                if (saved && saved.overlap_days) $('cycleOverlapDays').value = saved.overlap_days;
                if ($('cycleIgnoreGap')) $('cycleIgnoreGap').checked = !!(saved && saved.ignore_gap);
                $('cycleOverlapDays').disabled = !$('cycleAllowOverlap').checked;
            }
            if ($('cycleAllowOverlap')) {
                $('cycleAllowOverlap').onchange = syncCycleOverlapUi;
                $('cycleOverlapDays').onchange = syncCycleOverlapUi;
                if ($('cycleIgnoreGap')) $('cycleIgnoreGap').onchange = syncCycleOverlapUi;
            }

            // Bayram qo'shish
            if ($('cycleHolAddBtn')) $('cycleHolAddBtn').onclick = () => {
                const d = $('cycleHolAdd').value;
                if (!d || cycleHolidays.includes(d)) return;
                cycleHolidays = [...cycleHolidays, d].sort();
                $('cycleHolAdd').value = '';
                renderHolChips();
                loadCyclePlan();
            };
            // Bayramni olib tashlash (chipdagi ×)
            if ($('cycleHolList')) $('cycleHolList').addEventListener('click', ev => {
                if (!ev.target.classList.contains('cyc-hol-x')) return;
                cycleHolidays = cycleHolidays.filter(d => d !== ev.target.dataset.d);
                renderHolChips();
                loadCyclePlan();
            });

            // ===== Qoidalar (aSc "Взаимосвязи" uslubida) =====
            let rulesData = [];        // [{id, condition, description, subjects, scopes, weight, active, note}]
            let ruleConditions = {};   // {kod: tavsif}
            let ruleSelId = null;      // ro'yxatda tanlangan qoida id
            let ruleEditing = null;    // tahrirlanayotgan qoida (yoki null = yangi)

            const WEIGHT_LABEL = { majburiy: 'Majburiy', normal: 'Normal', yengil: 'Yengil' };
            function toggleRuleParams(condition) {
                const panel = $('ruleLectureWeekOptions');
                if (panel) panel.classList.toggle('hidden', condition !== 'lecture_week_distribution');
                const joint = $('ruleJointOptions');
                if (joint) joint.classList.toggle('hidden', condition !== 'joint_groups');
                if (condition === 'joint_groups') renderJointPairs();
            }
            // ===== "Guruhchalar birga o'tadi": qo'lda juftliklar (muharrirda) =====
            let ruleJointPairs = [];   // [["p/st26-03c", "p/st26-04c"], ...]
            // Qamrovdagi (tanlangan yo'nalish · kurs; tanlanmasa — barchasi) amaliy guruhchalari.
            function jointScopeGroups() {
                const picked = $('ruleAllScopes') && $('ruleAllScopes').checked ? null
                    : new Set([...document.querySelectorAll('#ruleScopeList .rule-scope:checked')].map(c => c.value));
                const out = new Set();
                (typeof cards !== 'undefined' ? cards : []).forEach(c => {
                    if (c.training_type === 'lecture' || (picked && picked.size && !picked.has((c.faculty_name || '') + '|' + c.specialty_name + '|' + c.course))) return;
                    cardGroups(c).forEach(g => out.add(g));
                });
                return [...out].sort((a, b) => a.localeCompare(b, 'uz', { numeric: true }));
            }
            function renderJointPairs() {
                if (!$('ruleJointPairs')) return;
                const used = new Set(ruleJointPairs.flat());
                const opts = jointScopeGroups().filter(g => !used.has(g));
                const optHtml = first => (first ? '<option value="">— ixtiyoriy —</option>' : '<option value="">— guruhcha —</option>')
                    + opts.map(g => '<option value="' + esc(g) + '">' + esc(g) + '</option>').join('');
                $('ruleJointA').innerHTML = optHtml(false);
                $('ruleJointB').innerHTML = optHtml(false);
                $('ruleJointC').innerHTML = optHtml(true);
                $('ruleJointPairs').innerHTML = ruleJointPairs.length ? ruleJointPairs.map((p, i) =>
                    '<div class="flex items-center gap-2 py-0.5"><span>' + esc(p.join(' + ')) + '</span>'
                    + '<button type="button" class="text-red-600 hover:underline" data-joint-del="' + i + '">o‘chirish</button></div>').join('')
                    : '<div class="text-[11px] text-sky-700">Qo‘lda juftlik yo‘q — hamma guruhchalar guruh bo‘yicha birlashadi.</div>';
                $('ruleJointPairs').querySelectorAll('[data-joint-del]').forEach(b => b.onclick = () => {
                    ruleJointPairs.splice(+b.dataset.jointDel, 1);
                    renderJointPairs();
                });
            }
            if ($('ruleJointAdd')) $('ruleJointAdd').onclick = () => {
                const pick = [$('ruleJointA').value, $('ruleJointB').value, $('ruleJointC').value].filter(Boolean);
                if (new Set(pick).size < 2) { $('ruleEditMsg').textContent = 'Juftlik uchun kamida ikki xil guruhcha tanlang.'; return; }
                $('ruleEditMsg').textContent = '';
                ruleJointPairs.push([...new Set(pick)]);
                renderJointPairs();
            };
            if ($('ruleScopeList')) $('ruleScopeList').addEventListener('change', () => {
                if ($('ruleJointOptions') && !$('ruleJointOptions').classList.contains('hidden')) renderJointPairs();
            });
            if ($('ruleAllScopes')) $('ruleAllScopes').addEventListener('change', () => {
                if ($('ruleJointOptions') && !$('ruleJointOptions').classList.contains('hidden')) renderJointPairs();
            });
            // Qo'llash / ajratish: avval sinov (dry_run) natijasi oynada, "Tasdiqlash" — haqiqiy bajarish va doska qayta yuklanadi.
            async function jointRun(rule, kind, after) {
                const url = BASE + '/boards/' + board.id + '/rules/' + rule.id + '/' + (kind === 'split' ? 'split-joint' : 'apply-joint');
                let dry;
                try { dry = await api(url, 'POST', { dry_run: 1 }); } catch (e) { $('rulesMsg').textContent = 'Xatolik: ' + e.message; return; }
                const prior = document.getElementById('jointRunModal');
                if (prior) prior.remove();
                const placed = p => p ? ((boardDayName ? boardDayName(p.day) : p.day + '-kun') + ', ' + p.pair + '-para') : 'panelda';
                const resText = r => kind === 'split' ? esc(r.card_to || '') :
                    (Array.isArray(r.card_to) && r.card_to.length ? r.cards_from.length + ' karta → ' + r.card_to.length + ' (' + r.placed_at.map(placed).join('; ') + ')' : '—');
                const rows = (dry.list || []);
                const m = document.createElement('div');
                m.id = 'jointRunModal';
                m.className = 'cr-proposal-overlay';
                m.innerHTML = '<div class="cr-proposal-form" style="width:min(900px,96vw);max-height:86vh;overflow:auto">'
                    + '<h3 class="font-bold text-lg">' + (kind === 'split' ? 'Guruhchalarga ajratish' : 'Guruhchalarni birlashtirish') + ' — sinov natijasi</h3>'
                    + '<p class="text-sm">' + esc(rule.description || '') + '</p>'
                    + (rows.length ? '<table class="w-full text-xs border-collapse tt-rules-table" style="margin-top:6px"><thead><tr><th>Fan</th><th>Guruhchalar</th><th>Natija</th><th>Ogohlantirish</th></tr></thead><tbody>'
                        + rows.map(r => '<tr><td>' + esc(r.subject) + '</td><td>' + esc(r.groups) + '</td><td>' + resText(r) + '</td>'
                            + '<td class="' + (r.warning ? 'text-amber-700' : '') + '">' + esc(r.warning || '') + '</td></tr>').join('') + '</tbody></table>'
                        : '<p class="text-sm text-gray-500" style="margin-top:6px">' + (kind === 'split' ? 'Ajratiladigan birlashgan karta yo‘q.' : 'Birlashtiriladigan karta yo‘q.') + '</p>')
                    + '<p role="alert" class="text-red-600"></p><div class="flex justify-end gap-3" style="margin-top:8px"><button type="button" data-close>Bekor</button>'
                    + ((kind === 'split' ? dry.cards : dry.merged) ? '<button type="button" data-ok class="px-3 py-2 bg-blue-600 text-white rounded">Tasdiqlash</button>' : '')
                    + '</div></div>';
                document.body.appendChild(m);
                m.querySelector('[data-close]').onclick = () => m.remove();
                const ok = m.querySelector('[data-ok]');
                if (ok) ok.onclick = async () => {
                    ok.disabled = true;
                    try {
                        const r = await api(url, 'POST', {});
                        m.remove();
                        $('rulesMsg').textContent = kind === 'split' ? ('Ajratildi: ' + (r.cards || 0) + ' karta → +' + (r.created || 0))
                            : ('Birlashtirildi: ' + (r.merged || 0) + ' to‘plam, o‘chirilgan kartalar: ' + (r.removed || 0));
                        if (after) await after();
                        await loadBoard(board.id);
                    } catch (e) { ok.disabled = false; m.querySelector('[role="alert"]').textContent = e.message; }
                };
            }
            const boardDayName = d => ((board && board.day_names) || ['Dushanba', 'Seshanba', 'Chorshanba', 'Payshanba', 'Juma', 'Shanba', 'Yakshanba'])[d - 1] || (d + '-kun');

            // Qoidalar — faqat to'liq huquqli rollarga (server boshqalarga 403): o'qituvchi, fan mas'uli, kafedra mudiri, o'quv bo'limida so'ralmaydi.
            const TIMETABLE_CAN_RULES = !TIMETABLE_ASSIGNMENT_ONLY;
            async function loadRules() {
                if (!board || !TIMETABLE_CAN_RULES) return;
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/rules');
                    rulesData = j.rules || [];
                    ruleConditions = j.conditions || {};
                    renderRulesTable();
                    updateRulesBadge();
                } catch (e) {
                    $('rulesBody').innerHTML = '';
                    $('rulesMsg').textContent = 'Xatolik: ' + e.message;
                }
            }
            function updateRulesBadge() {
                const n = rulesData.filter(r => r.active).length;
                const b = $('rulesBadge');
                if (!b) return;
                b.textContent = n || '';
                b.classList.toggle('hidden', !n);
            }
            const ruleSubjLabel = r => (r.subjects && r.subjects.length)
                ? (r.subjects.length > 2 ? (r.subjects.length + ' ta fan') : r.subjects.join(', '))
                : 'Barcha fanlar';
            // Qamrov qiymati: yangi — "fakultet|yo'nalish|kurs", eski — "yo'nalish · kurs" (barcha fakultetlar).
            const ruleScopeText = v => String(v).includes('|') ? String(v).split('|').filter(Boolean).join(' · ') : v + ' (barcha fakultetlar)';
            const ruleScopeLabel = r => (r.scopes && r.scopes.length)
                ? (r.scopes.length > 2 ? (r.scopes.length + ' ta fakultet·yo\'nalish·kurs') : r.scopes.map(ruleScopeText).join('; '))
                : 'Barchasi';

            function renderRulesTable() {
                $('rulesEmpty').classList.toggle('hidden', rulesData.length > 0);
                $('rulesBody').innerHTML = rulesData.map((r, i) =>
                    '<tr data-id="' + r.id + '" class="' + (r.id === ruleSelId ? 'sel ' : '') + (r.active ? '' : 'off') + '">' +
                    '<td>' + (i + 1) + '</td>' +
                    '<td style="text-align:center">' + (r.active ? '✔' : '✕') + '</td>' +
                    '<td>' + esc(ruleSubjLabel(r)) + '</td>' +
                    '<td>' + esc(ruleScopeLabel(r)) + '</td>' +
                    '<td>' + esc(r.description || r.condition) + '</td>' +
                    '<td><span class="tt-rule-w ' + esc(r.weight) + '">' + esc(WEIGHT_LABEL[r.weight] || r.weight) + '</span></td>' +
                    '<td>' + esc(r.note || '') + '</td></tr>').join('');
                // "Qo'llash" / "Ajratish" — faqat tanlangan "Guruhchalar birga o'tadi" qoidasi uchun.
                const selJ = rulesData.find(x => x.id === ruleSelId);
                ['ruleJointApplyBtn', 'ruleJointSplitBtn'].forEach(id => { if ($(id)) $(id).disabled = !(selJ && selJ.condition === 'joint_groups'); });
                $('rulesBody').querySelectorAll('tr').forEach(tr => {
                    tr.onclick = () => { ruleSelId = +tr.dataset.id; renderRulesTable(); };
                    tr.ondblclick = () => { ruleSelId = +tr.dataset.id; openRuleEditor(rulesData.find(x => x.id === ruleSelId)); };
                });
            }

            // --- Qoidalar oynasi
            if ($('rulesBtn')) $('rulesBtn').onclick = () => {
                if (!board) return;
                $('rulesMsg').textContent = '';
                $('rulesModal').classList.remove('hidden');
                loadRules();
            };
            const closeRules = () => $('rulesModal').classList.add('hidden');
            if ($('rulesClose')) $('rulesClose').onclick = closeRules;
            if ($('rulesOkBtn')) $('rulesOkBtn').onclick = closeRules;

            // --- Qoida muharriri (shart tanlash oynasi)
            function openRuleEditor(rule) {
                ruleEditing = rule || null;
                $('ruleEditTitle').textContent = rule ? 'Qoidani tahrirlash' : 'Yangi qoida';
                $('ruleEditMsg').textContent = '';
                $('ruleWeight').value = rule ? rule.weight : 'normal';
                $('ruleNote').value = rule ? (rule.note || '') : '';
                $('ruleActive').checked = rule ? !!rule.active : true;
                $('ruleSubjSearch').value = '';
                $('ruleLectureWeekMode').value = rule && rule.params && rule.params.distribution
                    ? rule.params.distribution : 'auto';
                ruleJointPairs = rule && rule.condition === 'joint_groups' && rule.params && Array.isArray(rule.params.pairs)
                    ? rule.params.pairs.map(p => [...p]) : [];

                // Shartlar ro'yxati (radio)
                const cur = rule ? rule.condition : '';
                $('ruleCondList').innerHTML = Object.entries(ruleConditions).map(([code, label]) =>
                    '<label class="tt-cond-item' + (code === cur ? ' sel' : '') + '">' +
                    '<input type="radio" name="ruleCond" value="' + esc(code) + '"' + (code === cur ? ' checked' : '') + '>' +
                    esc(label) + '</label>').join('');
                $('ruleCondList').querySelectorAll('input[name=ruleCond]').forEach(inp => {
                    inp.onchange = () => {
                        $('ruleCondList').querySelectorAll('.tt-cond-item')
                            .forEach(el => el.classList.toggle('sel', el.contains(inp) && inp.checked));
                        toggleRuleParams(inp.value);
                    };
                });
                toggleRuleParams(cur);

                // Fanlar va qamrov ro'yxatlari — doskadagi kartalardan
                const subs = [...new Set(cards.map(c => c.subject_name))].sort((a, b) => a.localeCompare(b, 'uz'));
                // Qamrov: fakultet bo'yicha guruhlangan "fakultet|yo'nalish|kurs" (karta fakulteti bo'sh — "Fakultetsiz").
                const scopeKey = c => (c.faculty_name || '') + '|' + c.specialty_name + '|' + c.course;
                const scopes = [...new Set(cards.map(scopeKey))].sort((a, b) => a.localeCompare(b, 'uz', { numeric: true }));
                const selSubs = new Set(rule ? rule.subjects : []);
                // Eski qiymat ("yo'nalish · kurs") — barcha fakultetlardagi shu yo'nalish·kurs belgilanadi (saqlanganda yangi formatga o'tadi).
                const norm = v => String(v || '').trim().toLowerCase().replace(/\s+/g, ' ');
                const selScopes = new Set();
                (rule ? rule.scopes : []).forEach(v => {
                    if (String(v).includes('|')) {
                        const [f, sp, c] = String(v).split('|');
                        scopes.filter(k => { const [kf, ks, kc] = k.split('|'); return norm(ks) === norm(sp) && +kc === +c && (!norm(f) || !norm(kf) || norm(kf) === norm(f)); })
                            .forEach(k => selScopes.add(k));
                    } else {
                        const parts = String(v).split(' · ');
                        const c = parts.pop(), sp = parts.join(' · ');
                        scopes.filter(k => { const [, ks, kc] = k.split('|'); return norm(ks) === norm(sp) && +kc === +c; }).forEach(k => selScopes.add(k));
                    }
                });
                $('ruleAllSubjects').checked = !selSubs.size;
                $('ruleAllScopes').checked = !selScopes.size;
                $('ruleSubjList').innerHTML = subs.map(s =>
                    '<label class="tt-pick-item"><input type="checkbox" class="rule-subj" value="' + esc(s) + '"' +
                    (selSubs.has(s) ? ' checked' : '') + '>' + esc(s) + '</label>').join('') ||
                    '<div class="text-[11px] text-gray-400 p-1">Fan yo\'q</div>';
                const byFac = {};
                scopes.forEach(k => { (byFac[k.split('|')[0]] = byFac[k.split('|')[0]] || []).push(k); });
                $('ruleScopeSearch').value = '';
                $('ruleScopeList').innerHTML = Object.keys(byFac).sort((a, b) => a.localeCompare(b, 'uz', { numeric: true })).map(f =>
                    '<div class="rule-scope-fac" data-fac="' + esc(f) + '">' +
                    '<label class="tt-pick-item" style="font-weight:700;color:#1e3a8a"><input type="checkbox" class="rule-scope-facall">' + esc(f || 'Fakultetsiz') + '</label>' +
                    byFac[f].map(k => {
                        const [kf, ks, kc] = k.split('|');
                        return '<label class="tt-pick-item" style="padding-left:18px"><input type="checkbox" class="rule-scope" value="' + esc(k) + '"' +
                            (selScopes.has(k) ? ' checked' : '') + '>' + esc((kf ? kf + ' · ' : '') + ks + ' · ' + kc) + '</label>';
                    }).join('') + '</div>').join('') ||
                    '<div class="text-[11px] text-gray-400 p-1">Yo\'nalish yo\'q</div>';
                syncScopeFacBoxes();

                if (cur === 'joint_groups') renderJointPairs();   // qamrov ro'yxati endi tayyor
                $('ruleEditModal').classList.remove('hidden');
            }
            // "Barchasi" belgilansa — alohida tanlovlar tozalanadi
            if ($('ruleAllSubjects')) $('ruleAllSubjects').onchange = function () {
                if (this.checked) $('ruleSubjList').querySelectorAll('.rule-subj').forEach(c => c.checked = false);
            };
            if ($('ruleAllScopes')) $('ruleAllScopes').onchange = function () {
                if (this.checked) $('ruleScopeList').querySelectorAll('.rule-scope').forEach(c => c.checked = false);
                if (this.checked) syncScopeFacBoxes();
                refreshJointPairsIfOpen();
            };
            // Alohida fan belgilansa — "Barchasi" olib tashlanadi
            if ($('ruleSubjList')) $('ruleSubjList').addEventListener('change', ev => {
                if (ev.target.classList.contains('rule-subj') && ev.target.checked) $('ruleAllSubjects').checked = false;
            });
            const refreshJointPairsIfOpen = () => {
                if ($('ruleJointOptions') && !$('ruleJointOptions').classList.contains('hidden') && typeof renderJointPairs === 'function') renderJointPairs();
            };
            // Fakultet sarlavhasi: belgilansa — uning barcha yo'nalish·kurslari; qisman tanlangan bo'lsa — oraliq holat.
            function syncScopeFacBoxes() {
                document.querySelectorAll('#ruleScopeList .rule-scope-fac').forEach(box => {
                    const items = [...box.querySelectorAll('.rule-scope')], n = items.filter(i => i.checked).length;
                    const head = box.querySelector('.rule-scope-facall');
                    head.checked = items.length > 0 && n === items.length;
                    head.indeterminate = n > 0 && n < items.length;
                });
            }
            if ($('ruleScopeList')) $('ruleScopeList').addEventListener('change', ev => {
                if (ev.target.classList.contains('rule-scope-facall')) {
                    ev.target.closest('.rule-scope-fac').querySelectorAll('.rule-scope').forEach(i => { i.checked = ev.target.checked; });
                }
                if ((ev.target.classList.contains('rule-scope') || ev.target.classList.contains('rule-scope-facall')) && ev.target.checked) $('ruleAllScopes').checked = false;
                syncScopeFacBoxes();
                refreshJointPairsIfOpen();   // qamrov holati yangilangach — qo'lda juftlash guruhchalari ham yangi qamrov bo'yicha
            });
            // Qamrov qidirish (fakultet, yo'nalish yoki kurs bo'yicha); mos qatori yo'q fakultet bo'limi yashiriladi.
            if ($('ruleScopeSearch')) $('ruleScopeSearch').oninput = function () {
                const q = this.value.toLowerCase().trim();
                document.querySelectorAll('#ruleScopeList .rule-scope-fac').forEach(box => {
                    const facHit = !q || box.dataset.fac.toLowerCase().includes(q);
                    let any = false;
                    box.querySelectorAll('.rule-scope').forEach(i => {
                        const show = facHit || i.parentElement.textContent.toLowerCase().includes(q);
                        i.parentElement.style.display = show ? '' : 'none';
                        any = any || show;
                    });
                    box.style.display = any ? '' : 'none';
                });
            };
            // Fan qidirish
            if ($('ruleSubjSearch')) $('ruleSubjSearch').oninput = function () {
                const q = this.value.toLowerCase().trim();
                $('ruleSubjList').querySelectorAll('.tt-pick-item').forEach(el =>
                    el.style.display = (!q || el.textContent.toLowerCase().includes(q)) ? '' : 'none');
            };

            const closeRuleEditor = () => $('ruleEditModal').classList.add('hidden');
            if ($('ruleEditClose')) $('ruleEditClose').onclick = closeRuleEditor;
            if ($('ruleCancelBtn')) $('ruleCancelBtn').onclick = closeRuleEditor;

            if ($('ruleSaveBtn')) $('ruleSaveBtn').onclick = async function () {
                const cond = $('ruleCondList').querySelector('input[name=ruleCond]:checked');
                if (!cond) { $('ruleEditMsg').textContent = 'Shartni tanlang.'; return; }
                const body = {
                    condition: cond.value,
                    weight: $('ruleWeight').value,
                    active: $('ruleActive').checked ? 1 : 0,
                    note: $('ruleNote').value.trim(),
                    subjects: $('ruleAllSubjects').checked ? []
                        : [...$('ruleSubjList').querySelectorAll('.rule-subj:checked')].map(c => c.value),
                    scopes: $('ruleAllScopes').checked ? []
                        : [...$('ruleScopeList').querySelectorAll('.rule-scope:checked')].map(c => c.value),
                };
                if (cond.value === 'lecture_week_distribution') {
                    body.params = { distribution: $('ruleLectureWeekMode').value };
                }
                if (cond.value === 'joint_groups') {
                    body.params = { mode: 'guruh', pairs: ruleJointPairs };
                }
                if (ruleEditing) body.id = ruleEditing.id;
                this.disabled = true;
                try {
                    await api(BASE + '/boards/' + board.id + '/rules', 'POST', body);
                    closeRuleEditor();
                    await loadRules();
                    if (cond.value === 'lecture_week_distribution') {
                        $('rulesMsg').textContent = 'Qoida saqlandi. Qo\'llash uchun Kartochkalarni qayta yarating.';
                    }
                    if (cond.value === 'joint_groups') {
                        $('rulesMsg').textContent = 'Qoida saqlandi. Kartalarni birlashtirish uchun qoidani tanlab «Qo\'llash» ni bosing.';
                    }
                } catch (e) { $('ruleEditMsg').textContent = 'Xatolik: ' + e.message; }
                this.disabled = false;
            };

            // --- Ro'yxat tugmalari
            const selRule = () => rulesData.find(r => r.id === ruleSelId);
            if ($('ruleAddBtn')) $('ruleAddBtn').onclick = () => openRuleEditor(null);
            if ($('ruleEditBtn')) $('ruleEditBtn').onclick = () => {
                const r = selRule();
                if (!r) { $('rulesMsg').textContent = 'Avval qoidani tanlang.'; return; }
                openRuleEditor(r);
            };
            if ($('ruleDelBtn')) $('ruleDelBtn').onclick = async () => {
                const r = selRule();
                if (!r) { $('rulesMsg').textContent = 'Avval qoidani tanlang.'; return; }
                if (!confirm('Qoida o\'chirilsinmi?\n\n' + (r.description || r.condition))) return;
                const doDelete = async () => {
                    await api(BASE + '/boards/' + board.id + '/rules/' + r.id, 'POST', { _method: 'DELETE' });
                    ruleSelId = null;
                    await loadRules();
                };
                // "Guruhchalar birga o'tadi": birlashtirilgan kartalarni avval guruhchalarga ajratish taklifi (tasdiqlansa — keyin o'chiriladi).
                if (r.condition === 'joint_groups' && confirm('Bu qoida bo\'yicha birlashtirilgan kartalar guruhchalarga ajratilsinmi?\n(Bekor — kartalar shundayligicha qoladi, faqat qoida o\'chadi.)')) {
                    await jointRun(r, 'split', doDelete);
                    return;
                }
                try {
                    // POST + _method spoofing — fayldagi boshqa o'chirishlar bilan bir xil uslub
                    await api(BASE + '/boards/' + board.id + '/rules/' + r.id, 'POST', { _method: 'DELETE' });
                    ruleSelId = null;
                    await loadRules();
                    $('rulesMsg').textContent = 'O\'chirildi';
                } catch (e) { $('rulesMsg').textContent = 'Xatolik: ' + e.message; }
            };
            async function ruleState(bodyExtra) {
                const r = selRule();
                if (!r) { $('rulesMsg').textContent = 'Avval qoidani tanlang.'; return; }
                try {
                    await api(BASE + '/boards/' + board.id + '/rules/' + r.id + '/state', 'POST', bodyExtra(r));
                    await loadRules();
                    $('rulesMsg').textContent = '';
                } catch (e) { $('rulesMsg').textContent = 'Xatolik: ' + e.message; }
            }
            if ($('ruleToggleBtn')) $('ruleToggleBtn').onclick = async () => {
                const r = selRule();
                await ruleState(x => ({ active: x.active ? 0 : 1 }));
                // Nofaol qilingan "Guruhchalar birga o'tadi" — birlashgan kartalarni ajratish taklifi.
                if (r && r.condition === 'joint_groups' && r.active
                    && confirm('Qoida nofaol qilindi. Bu qoida bo\'yicha birlashtirilgan kartalar guruhchalarga ajratilsinmi?')) {
                    await jointRun(r, 'split');
                }
            };
            if ($('ruleJointApplyBtn')) $('ruleJointApplyBtn').onclick = () => { const r = selRule(); if (r && r.condition === 'joint_groups') jointRun(r, 'apply'); };
            if ($('ruleJointSplitBtn')) $('ruleJointSplitBtn').onclick = () => { const r = selRule(); if (r && r.condition === 'joint_groups') jointRun(r, 'split'); };
            if ($('ruleUpBtn')) $('ruleUpBtn').onclick = () => ruleState(() => ({ move: 'up' }));
            if ($('ruleDownBtn')) $('ruleDownBtn').onclick = () => ruleState(() => ({ move: 'down' }));

            function buildGroupRows() {
                groupRows = [];
                flowStudents = {};
                const seen = {};
                const flowGroupSeen = {};
                const groupFlowStudents = {};
                specCards().forEach(c => {
                    const flowKey = (c.faculty_name || '') + '|' + (c.specialty_name || '') + '|' + c.course + '|' + (c.oqim_label || '');
                    if (c.training_type === 'lecture') {
                        flowStudents[flowKey] = Math.max(flowStudents[flowKey] || 0, +c.students || 0);
                    }
                    cardGroups(c).forEach(g => {
                        const k = gkey(c, g);
                        if (!seen[k]) {
                            seen[k] = 1;
                            groupRows.push({ key: k, oqim_label: c.oqim_label || '', lang: c.lang || 'uz', group: g, faculty: c.faculty_name || '', specialty: c.specialty_name || '', course: c.course });
                        }
                        if (c.training_type !== 'lecture') {
                            const groupFlowKey = flowKey + '|' + g;
                            if (!flowGroupSeen[groupFlowKey]) {
                                flowGroupSeen[groupFlowKey] = 1;
                                groupFlowStudents[flowKey] = (groupFlowStudents[flowKey] || 0) + (+c.students || 0);
                            }
                        }
                    });
                });
                // Ma'ruza oqimi mavjud bo'lsa uning jami olinadi; aks holda
                // amaliy kartalardan har bir guruh talabasini faqat bir marta qo'shamiz.
                Object.keys(groupFlowStudents).forEach(flowKey => {
                    if (!Object.prototype.hasOwnProperty.call(flowStudents, flowKey)) {
                        flowStudents[flowKey] = groupFlowStudents[flowKey];
                    }
                });
                // Fakultet → yo'nalish → kurs → oqim → guruh: bir blok ketma-ket tursin.
                const sk = x => x.faculty + '|' + x.specialty + '|' + x.course + '|' + x.oqim_label + x.group;
                groupRows.sort((a, b) => sk(a).localeCompare(sk(b), undefined, { numeric: true }));
                // "Ko'rsatish": vaqtincha — faqat to'qnashuvdagi guruhlar ustunlari.
                groupRows = focusWeekColumns(groupRows);
                // Fan mas'uli "Joylash" + "Faqat shu guruh": faqat joylanayotgan kartaning fakulteti / yo'nalishi / kursi ustunlari.
                if (fmPick && fmOwnOnly) {
                    const fc = fmPick.card;
                    groupRows = groupRows.filter(r => r.faculty === (fc.faculty_name || '') && r.specialty === (fc.specialty_name || '') && +r.course === +fc.course);
                }
            }

            // Karta uzunligi yarim-slot birligida (1=0.5 para, 2=1 para ...). Sukut 2.
            const cardLen = c => Math.max(1, parseInt(c.len_half) || 2);
            // Serverdagi isSharedRoom bilan bir xil: raqamsiz va "mashg'ulot"/"umumiy" so'zli nom.
            const isSharedRoomName = name => {
                const n = String(name || '').trim();
                return n !== '' && !/\d/.test(n) && /mashg|umumiy/i.test(n);
            };
            // Bitta fanning turli bo'laklari ("Fan (a)" va "Fan (b)") — guruhning turli talabalari,
            // bir vaqtda parallel o'tadi: guruh bandligi hisoblanmaydi (serverdagi bolakSiblings).
            const BOLAK_RX = /^(.*?)\s*\((\p{L})\)\s*$/u;
            // Parallel to'plam (serverdagi bolakSiblings): asosiy nom bir xil, harf har xil; bir tur, bir qamrov (fakultet, yo'nalish,
            // kurs) va bir oqim (ikkalasida ham bo'lsa). Talabalar soni hisobga olinmaydi.
            function bolakSiblings(a, b) {
                const ma = BOLAK_RX.exec(String(a.subject_name || '').trim()), mb = BOLAK_RX.exec(String(b.subject_name || '').trim());
                if (!(ma && mb && ma[1].trim().toLowerCase() === mb[1].trim().toLowerCase() && ma[2].toLowerCase() !== mb[2].toLowerCase())) return false;
                if ((a.training_type || '') !== (b.training_type || '')) return false;
                const scope = x => [x.faculty_name || '', x.specialty_name || '', +x.course].join('|').toLowerCase();
                if (a.specialty_name !== undefined && b.specialty_name !== undefined && scope(a) !== scope(b)) return false;
                if (a.oqim_label && b.oqim_label && String(a.oqim_label).trim().toLowerCase() !== String(b.oqim_label).trim().toLowerCase()) return false;
                return true;
            }
            const cardGroupsSafe = c => (c.group_names && c.group_names.length) ? c.group_names : (c.group_name ? [c.group_name] : []);
            // Ikki karta kamida bitta umumiy faol haftaga egami (bekor qilinmagan haftalar, panjara haftalari ichida).
            function weeksIntersect(a, b) {
                const total = Math.min(+a.term_weeks || +curGrid().weeks || +board.weeks || 15, +b.term_weeks || +curGrid().weeks || +board.weeks || 15);
                for (let w = 1; w <= total; w++) {
                    const oa = overrides[a.id + '|' + w], ob = overrides[b.id + '|' + w];
                    if (!(oa && oa.cancelled) && !(ob && ob.cancelled)) return true;
                }
                return false;
            }
            // Konflikt: karta (day,pair) ga qo'yilsa — sabablar ro'yxati (tanlangan hafta effektiv joylashuvi bo'yicha).
            // `pair` — yarim-slot indeksi; dars cardLen(card) ta yarim-slotni egallaydi,
            // shu oraliq [pair, pair+len) boshqa kartaning oralig'i bilan kesishsa — band.
            // Band qilgan dars: "2-son davolash, 3-kurs · d2/d24-05a · Patologik anatomiya (amaliy)".
            function describeCardBrief(o) {
                const gs = cardGroups(o).map(g => String(g).replace(/\s*\(.*\)\s*$/, ''));
                const gText = gs.length > 4 ? gs.slice(0, 4).join(', ') + ' +' + (gs.length - 4) : gs.join(', ');
                return (o.faculty_name ? o.faculty_name + ', ' : '') + o.course + '-kurs'
                    + (o.training_type === 'lecture' && o.oqim_label ? ' · ' + o.oqim_label : '')
                    + (gText ? ' · ' + gText : '') + ' · ' + o.subject_name + ' (' + (o.training_type === 'lecture' ? "ma'ruza" : 'amaliy') + ')';
            }
            function conflictsAt(card, day, pair, ignoredIds = []) {
                return conflictsAtDetail(card, day, pair, ignoredIds).map(x => x.text);
            }
            // conflictsAt tafsiloti: [{ kind: 'group' | 'teacher' | 'room', who (kesishgan guruhlar / o'qituvchi / xona nomi), text, cardId (band qilgan
            // dars) }] — tartib va matn conflictsAt bilan bir xil.
            // opts.room — boshqa xona bilan sinash ({ code, name }: "sariq" katakda xona tanlash).
            function conflictsAtDetail(card, day, pair, ignoredIds = [], opts = {}) {
                if (isNonBlocking(card)) return [];
                const my = cardGKeys(card);   // guruh kaliti (fakultet+yo'nalish+kurs+nom)
                const errs = [];
                // Vaqtincha kafedra mudirida — to'qnashuv tekshirilmaydi va boshqalarni ham to'qnashuvli qilmaydi (serverdagi clashWith).
                if (phOf(card)) return errs;
                const effectiveSource = opts.room ? Object.assign({}, effectiveCard(card), { auditorium_code: opts.room.code, auditorium_name: opts.room.name })
                    : effectiveCard(card);
                const a0 = pair, a1 = pair + cardLen(card);   // [a0, a1)
                cards.forEach(o => {
                    if (o.id === card.id || ignoredIds.includes(o.id) || phOf(o) || isNonBlocking(o)) return;
                    const effectiveOther = effectiveCard(o);
                    // Tashqi qatlamda joylash andozaga (barcha haftalar) yoziladi va server bandlikni
                    // andoza bo'yicha tekshiradi — haftaning ko'rinishdagi surilishi/bekori hisobga olinmaydi.
                    const pl = weeklyLayer === 'external' ? (o.day && o.pair ? { day: o.day, pair: o.pair } : null) : effPlace(o);
                    if (!pl || pl.day !== day) return;
                    const b0 = pl.pair, b1 = pl.pair + cardLen(o);   // [b0, b1)
                    if (a0 >= b1 || b0 >= a1) return;   // yarim-slot oraliqlari kesishmasa — konflikt yo'q
                    // Guruh bandligi kalit bo'yicha: bir xil nomli, lekin turli
                    // fakultetdagi guruhlar bir-biriga to'sqinlik qilmasin.
                    const ov = cardGKeys(o).filter(k => my.includes(k));
                    // Tashqi jadval — umumiy shablon: hech qachon bir haftaga tushmaydigan kartalar
                    // bitta katakni bo'lisha oladi (serverdagi findExternalConflicts kabi).
                    if (ov.length && !bolakSiblings(card, o) && !(weeklyLayer === 'external' && !weeksIntersect(card, o)))
                        errs.push({ kind: 'group', cardId: o.id, who: ov.map(k => k.split('¦').pop()).join(','), text: 'Guruh band: ' + ov.map(k => k.split('¦').pop()).join(',') + ' — ' + describeCardBrief(o) });
                    if (card.teacher_id && o.teacher_id === card.teacher_id)
                        errs.push({ kind: 'teacher', cardId: o.id, who: o.teacher_name || '', text: "O'qituvchi band: " + o.teacher_name + ' — ' + describeCardBrief(o) });
                    // Raqamsiz umumiy xona ("amaliy mashg'ulot xonasi") — bandlik tekshirilmaydi (serverdagi isSharedRoom).
                    if (effectiveSource.auditorium_code && effectiveOther.auditorium_code === effectiveSource.auditorium_code
                        && !isSharedRoomName(effectiveOther.auditorium_name))
                        errs.push({ kind: 'room', cardId: o.id, who: effectiveOther.auditorium_name || effectiveOther.auditorium_code || '', text: 'Auditoriya band: ' + effectiveOther.auditorium_name + ' — ' + describeCardBrief(o) });
                });
                return errs;
            }
            // Joylash hukmi — "Joylash uchun tanlash" kataklari va sudrash uchun umumiy: tone — ok (yashil), teacher (to'q qizil: o'qituvchi band
            // yoki kun oxiriga sig'maydi), group (och qizil: guruh band), room (sariq: faqat xona band — xonani almashtirib joylash mumkin).
            // title — har sabab alohida qatorda (takrorlarsiz, 10 tadan ortig'i "… yana N ta"); causes — sabab bo'lgan darslar: id => eng og'ir tur.
            const PLACE_ROOM_HINT = 'Kartaning xonasini almashtirsangiz, shu vaqtga joylash mumkin.';
            const PLACE_RANK = { teacher: 3, other: 3, group: 2, room: 1 };
            function placeVerdict(items) {
                if (!items || !items.length) return { tone: 'ok', items: [], title: '', causes: {} };
                const top = items.reduce((a, x) => (PLACE_RANK[x.kind] > PLACE_RANK[a] ? x.kind : a), 'room');
                const tone = top === 'other' ? 'teacher' : top;
                const texts = [...new Set(items.map(x => x.text))];
                const causes = {};
                items.forEach(x => { if (x.cardId && (!causes[x.cardId] || PLACE_RANK[x.kind] > PLACE_RANK[causes[x.cardId]])) causes[x.cardId] = x.kind; });
                return { tone, items, causes,
                    title: texts.slice(0, 10).join('\n') + (texts.length > 10 ? '\n… yana ' + (texts.length - 10) + ' ta' : '') + (tone === 'room' ? '\n' + PLACE_ROOM_HINT : '') };
            }
            // Katak atributlari: rang sinfi (tt-bad + tur), title va sabab darslar (sichqoncha turganda ramka).
            const placeCauseAttr = v => ' data-bad-ids="' + Object.entries(v.causes).map(([id, k]) => id + ':' + k).join(',') + '" data-bad-tone="' + v.tone + '"';
            const placeBadCls = v => ' tt-bad tt-bad-' + v.tone;

            // ===== Joylash (bosish yoki drag-and-drop uchun umumiy) =====
            // Kartani joyidan olib tashlash — modal tugmasi va panelga sudrash uchun umumiy.
            // Shablon ko'rinishida barcha haftalardan; hafta tanlangan bo'lsa faqat shu haftada.
            // Qatlam almashtirilganda yo'qolmasin: joylashuv o'z qatlamining maydoniga ham yoziladi.
            function rememberLayerPlace(card, d, p) {
                if (weeklyLayer === 'external') { card.ext_day = d; card.ext_pair = p; }
                else if (card._int) { card._int.day = d; card._int.pair = p; }
            }
            function weeklyEditGuard() {
                if (weeklyCanEdit()) return;
                throw new Error(weeklyLayer === 'external'
                    ? 'Tashqi dars jadvalini o\'quv bo\'limi tahrirlaydi. Ichki jadvalga o\'ting.'
                    : 'Ichki dars jadvalini kafedra mudiri tahrirlaydi.');
            }
            async function unplaceOneCard(card) {
                weeklyEditGuard();
                if (!curWeek || weeklyLayer === 'external') {
                    await api(BASE + '/cards/' + card.id + '/place', 'POST', { layer: weeklyLayer });
                    card.day = null; card.pair = null;
                    rememberLayerPlace(card, null, null);
                } else {
                    const key = card.id + '|' + curWeek;
                    const ov = overrides[key];
                    // Hafta-hafta (shablonsiz) ichki jadval: shablonda joyi yo'q kartani panelga qaytarish —
                    // shu haftadagi joylashuvni olib tashlash (reset), "bu haftada o'tilmaydi" (cancel) emas.
                    if (ov && !ov.cancelled && !card.day) {
                        await api(BASE + '/cards/' + card.id + '/week-override', 'POST', { week: curWeek, action: 'reset' });
                        delete overrides[key];
                        return;
                    }
                    await api(BASE + '/cards/' + card.id + '/week-override', 'POST', { week: curWeek, action: 'cancel' });
                    overrides[key] = {
                        day: null, pair: null, cancelled: true,
                        auditorium_code: null, auditorium_name: null, auditorium_volume: null,
                    };
                }
            }
            async function placeOneCard(card, d, p) {
                weeklyEditGuard();
                if (!curWeek || weeklyLayer === 'external') {
                    await api(BASE + '/cards/' + card.id + '/place', 'POST', { day: d, pair: p, layer: weeklyLayer });
                    card.day = d; card.pair = p;
                    rememberLayerPlace(card, d, p);
                } else {
                    // Amaliy dars yaxlit: ko'p bo'lakli dars — butun birlik (shu bo'lak (d, p) da, qolganlari o'z tartibida ketma-ket).
                    const plan = unitMovePlan(card, p);
                    if (plan) { await placeUnitAt(card, d, plan[0][1]); return; }
                    await api(BASE + '/cards/' + card.id + '/week-override', 'POST',
                        { week: curWeek, action: 'move', day: d, pair: p });
                    const key = card.id + '|' + curWeek;
                    overrides[key] = { ...(overrides[key] || {}), day: d, pair: p, cancelled: false };
                }
            }
            async function placeCardAt(card, d, p) {
                try { await placeOneCard(card, d, p); selected = null; renderAll(); }
                catch (e) { alert('Konflikt: ' + e.message); }
            }
            // ===== Sariq katak (faqat xona band): boshqa xona bilan joylash =====
            // Xonalar: faol, hozirgisidan boshqa, sig'imi talabalar sonidan kam emas (sig'imi kiritilmagani — yo'q), shu vaqtda bo'sh
            // (conflictsAtDetail shu xona bilan — xona sababi yo'q). Tartib — server reytingi (unit-busy room_rank: odatdagi, o'qituvchiniki,
            // kafedraniki, shu bino, sig'imi yaqin) sabab yorlig'i bilan; reyting kelmasa — sig'imi yaqini. Tanlansa — bitta so'rov (placeCardWithRoom):
            // tanlangan hafta — shu hafta istisnosi shu xona bilan, shablon — kartaning o'zi shu xona bilan. Tashqi jadvalda xona yo'q — sariq katak
            // oddiy joylashdek. Bekor / Esc / fon — hech narsa.
            let placeRoomsAll = null;
            function placeRoomCandidates(card, d, p, rooms, rank) {
                const cur = effectiveCard(card).auditorium_code || '';
                const need = +card.students || 0;
                const pos = {};
                ((rank && rank.order) || []).forEach((code, i) => { pos[code] = i; });
                // Ko'p bo'lakli amaliy dars — xona butun birlik oralig'ida bo'sh bo'lsin (hamma bo'lak shu xonaga).
                const plan = (curWeek && weeklyLayer === 'internal' && unitMovePlan(card, p)) || [[card, p]];
                const mine = plan.map(([x]) => x.id);
                return rooms.filter(r => r.code && r.code !== cur && +r.volume > 0 && (!need || +r.volume >= need)
                        && !plan.some(([x, at]) => conflictsAtDetail(x, d, at, mine, { room: { code: r.code, name: r.name || r.code } }).some(k => k.kind === 'room')))
                    .map(r => ({ r, at: r.code in pos ? pos[r.code] : Infinity }))
                    .sort((a, b) => a.at - b.at || (+a.r.volume - +b.r.volume) || String(a.r.name || a.r.code).localeCompare(String(b.r.name || b.r.code), undefined, { numeric: true }))
                    .map(x => x.r);
            }
            async function openPlaceRoomPick(card, d, p) {
                // Tashqi jadval: server faqat guruh bandligini tekshiradi (xona bu qatlamda yo'q) — oddiy joylash.
                if (weeklyLayer === 'external') { placeCardAt(card, d, p); return; }
                const prior = document.getElementById('ttPlaceRoom');
                if (prior) prior.remove();
                const m = document.createElement('div');
                m.id = 'ttPlaceRoom';
                m.className = 'cr-proposal-overlay';
                const week = curWeek && weeklyLayer !== 'external';
                const when = (boardDayNames()[d - 1] || d + '-kun') + ' ' + (slotRangeText(p, cardLen(card)) || '');
                const why = [...new Set(conflictsAtDetail(card, d, p).map(x => x.text))];
                m.innerHTML = '<div class="cr-proposal-form" role="dialog" aria-modal="true" aria-label="Boshqa xona bilan joylash">'
                    + '<h3 class="font-bold text-lg">Boshqa xona bilan joylash</h3>'
                    + '<p>' + esc(card.subject_name) + ' · ' + esc(card.training_type === 'lecture' ? (card.oqim_label || '') : (card.group_name || '')) + ' → ' + esc(when)
                    + (week ? ' · ' + curWeek + '-hafta (faqat shu hafta)' : ' · barcha haftalar (shu kartaning xonasi almashtiriladi)') + '</p>'
                    + '<p class="text-sm text-amber-700" style="white-space:pre-line" data-pr-why>' + esc(why.join('\n')) + '</p>'
                    + '<p class="text-sm" data-pr-what>' + (week ? 'Xonalar' : 'Shu vaqtda bo‘sh va sig‘adigan xonalar') + (+card.students ? ' (' + +card.students + ' talaba)' : '') + ':</p>'
                    + '<input type="search" data-pr-q placeholder="' + (week ? 'Xona yoki bino qidirish…' : 'Xona qidirish…') + '" aria-label="Xona qidirish" autocomplete="off">'
                    + '<div class="rm-list" role="listbox" aria-label="Xonalar" data-pr-list><div class="p-3 text-sm text-slate-400">Yuklanmoqda…</div></div>'
                    + '<p class="text-sm" role="alert" data-pr-msg></p>'
                    + '<div class="flex justify-end gap-2"><button type="button" data-close>Bekor</button></div></div>';
                document.body.appendChild(m);
                let busy = false;
                const onKey = e => { if (e.key === 'Escape' && !busy) { e.preventDefault(); e.stopPropagation(); close(); } };
                const close = () => { m.remove(); document.removeEventListener('keydown', onKey, true); };
                document.addEventListener('keydown', onKey, true);
                m.onclick = ev => { if (ev.target === m && !busy) close(); };
                m.querySelector('[data-close]').onclick = () => { if (!busy) close(); };
                const list = m.querySelector('[data-pr-list]'), msg = m.querySelector('[data-pr-msg]'), q = m.querySelector('[data-pr-q]');
                let rooms = [], rank = null;
                const run = async room => {
                    busy = true;
                    m.querySelectorAll('[data-pr-list] button').forEach(b => { b.disabled = true; });
                    msg.className = 'text-sm text-slate-600';
                    msg.textContent = 'Joylanmoqda…';
                    try {
                        const r = await placeCardWithRoom(card, d, p, room);
                        close();
                        selected = null;
                        renderAll();
                        // Tasdiqqa ketgan bo'lsa — xabar onPendingApproval'da (doska qayta yuklanadi).
                        if (!(r && r.pending_approval)) ttToast(esc('Joylandi: ' + (room.name || room.code) + ' xonasi bilan.'), 'ok');
                    } catch (e) {
                        busy = false;
                        m.querySelectorAll('[data-pr-list] button').forEach(b => { b.disabled = false; });
                        msg.className = 'text-sm text-red-600';
                        msg.textContent = 'Joylanmadi: ' + e.message;
                    }
                };
                // Tanlangan hafta (ichki): server ro'yxati (room-options — "Boshqa xona tanlash" bilan bir xil: bino guruhlari, bo'sh tepada, band /
                // sig'maydi / biriktirilgan — kulrang, sababi bilan); birlik — boshidan (unitMovePlan). Shablon — mijozdagi bo'sh xonalar (pastda).
                if (week) {
                    const plan = unitMovePlan(card, p);
                    let j = null;
                    try {
                        j = await api(BASE + '/cards/' + card.id + '/room-options?' + new URLSearchParams({ week: curWeek, day: d, pair: plan ? plan[0][1] : p }));
                    } catch (e) {
                        if (document.body.contains(m)) list.innerHTML = '<div class="p-3 text-sm text-red-600">' + esc(e.message) + '</div>';
                        return;
                    }
                    if (!document.body.contains(m)) return;
                    const all = ((j && j.rooms) || []).filter(r => !r.current);
                    m.querySelector('[data-pr-what]').textContent = roomListHeadText(j && j.when, all);
                    const why2 = r => r.kind === 'busy' ? (r.busy || 'band') : r.kind === 'capacity' ? "sig'maydi" + (r.cap ? ' (+' + r.cap.over + ')' : '')
                        : r.kind === 'assigned' ? (r.note || 'biriktirilgan') : '';
                    const render2 = () => {
                        const shown = all.filter(r => roomMatches(r, q.value || '', true));
                        list.innerHTML = roomListGrouped(shown, r => '<button type="button" class="rm-row" data-pr-code="' + esc(r.code) + '"' + (r.free ? '' : ' disabled aria-disabled="true" style="opacity:.55"')
                            + (r.note_full ? ' title="' + esc(r.note_full) + '"' : '') + '>'
                            + '<b>' + esc(r.name || r.code) + '</b>' + (roomBuildingTag(r) ? '<span data-pr-bld>' + esc(roomBuildingTag(r)) + '</span>' : '')
                            + (r.free && r.why ? '<span class="rm-why">' + esc(r.why) + '</span>' : '')
                            + (!r.free ? '<span data-pr-note>' + esc(why2(r)) + '</span>' : '')
                            + '<span class="rm-vol">' + (+r.volume ? r.volume + ' o‘rin' : 'sig‘imi kiritilmagan') + '</span></button>',
                            g => '<div class="rm-group" data-pr-group style="position:sticky;top:0;background:#e2e8f0;color:#334155;font-weight:600;font-size:11px;padding:2px 10px">' + esc(g) + '</div>')
                            || '<div class="p-3 text-sm text-slate-400" data-pr-none>' + (all.length ? 'Qidiruv bo‘yicha xona topilmadi' : 'Shu vaqtda xona topilmadi') + '</div>';
                    };
                    render2();
                    q.oninput = render2;
                    q.focus();
                    list.onclick = ev => {
                        const row = ev.target.closest ? ev.target.closest('[data-pr-code]') : null;
                        const room = row && all.find(r => r.code === row.dataset.prCode);
                        if (room && room.free && !busy) run(room);
                    };
                    return;
                }
                try {
                    const [all, ub] = await Promise.all([
                        placeRoomsAll || api(AUDS_URL).then(x => (placeRoomsAll = (x || []).filter(r => r.active !== false))),
                        api(BASE + '/boards/' + board.id + '/unit-busy?' + new URLSearchParams(asgUnitParams(card))).catch(() => null)]);
                    rooms = all;
                    rank = ub && ub.room_rank;
                } catch (e) {
                    if (document.body.contains(m)) list.innerHTML = '<div class="p-3 text-sm text-red-600">' + esc(e.message) + '</div>';
                    return;
                }
                if (!document.body.contains(m)) return;
                const rankWhy = (rank && rank.why) || {};
                const cands = placeRoomCandidates(card, d, p, rooms, rank);
                const render = () => {
                    const shown = cands.filter(r => roomMatches(r, q.value || ''));
                    list.innerHTML = shown.map(r => '<button type="button" class="rm-row" data-pr-code="' + esc(r.code) + '">'
                        + '<b>' + esc(r.name || r.code) + '</b><span>' + esc([r.building_name, r.auditorium_type_name].filter(Boolean).join(' · ')) + '</span>'
                        + (rankWhy[r.code] ? '<span class="rm-why">' + esc(rankWhy[r.code]) + '</span>' : '')
                        + '<span class="rm-vol">' + r.volume + ' o‘rin</span></button>').join('')
                        || '<div class="p-3 text-sm text-slate-400" data-pr-none>' + (cands.length ? 'Qidiruv bo‘yicha xona topilmadi' : 'Shu vaqtda bo‘sh va sig‘adigan xona topilmadi') + '</div>';
                };
                render();
                q.oninput = render;
                q.focus();
                list.onclick = ev => {
                    const row = ev.target.closest ? ev.target.closest('[data-pr-code]') : null;
                    if (row && !busy) run(cands.find(r => r.code === row.dataset.prCode));
                };
            }
            // Kartani (d, p) ga shu xona bilan joylash — bitta so'rov (yo xona ham, joy ham, yo hech biri; kafedra mudirida — bitta tasdiq
            // so'rovi): tanlangan hafta (ichki) — shu hafta istisnosi xona bilan (week-override); shablon (ichki) — kartaning o'zi shu xona bilan
            // (place + auditorium_code; faqat shu kartaning xonasi o'zgaradi). Qaytaradi: server javobi (pending_approval — tasdiqqa ketdi).
            async function placeCardWithRoom(card, d, p, room) {
                weeklyEditGuard();
                // Ko'p bo'lakli amaliy dars — butun birlik shu xona bilan (unit-place; hamma bo'lak shu haftada shu xonada).
                const plan = curWeek ? unitMovePlan(card, p) : null;
                if (plan) {
                    const r = await api(BASE + '/cards/' + card.id + '/unit-place', 'POST', { week: curWeek, layer: 'internal', day: d, pair: plan[0][1], auditorium_code: room.code });
                    if (r && r.pending_approval) return r;
                    applyUnitPayload(r && r.unit, curWeek);
                    plan.forEach(([x]) => {
                        const k = x.id + '|' + curWeek;
                        if (overrides[k] && !overrides[k].cancelled) Object.assign(overrides[k], { auditorium_code: room.code, auditorium_name: room.name || room.code, auditorium_volume: +room.volume || null });
                    });
                    return r;
                }
                if (curWeek) {
                    const r = await api(BASE + '/cards/' + card.id + '/week-override', 'POST', { week: curWeek, action: 'move', day: d, pair: p, auditorium_code: room.code });
                    if (r && r.pending_approval) return r;
                    const key = card.id + '|' + curWeek;
                    overrides[key] = Object.assign({}, overrides[key] || {}, { day: d, pair: p, cancelled: false,
                        auditorium_code: room.code, auditorium_name: room.name || room.code, auditorium_volume: +room.volume || null });
                    return r;
                }
                const r = await api(BASE + '/cards/' + card.id + '/place', 'POST', { day: d, pair: p, layer: 'internal', auditorium_code: room.code });
                if (r && r.pending_approval) return r;
                card.day = d; card.pair = p;
                card.auditorium_code = room.code; card.auditorium_name = room.name || room.code;
                rememberLayerPlace(card, d, p);
                return r;
            }
            // ===== Parallel bo'laklar ("Fan (a)", "(b)", "(c)" — guruhning turli talabalari, bir vaqtda yonma-yon) =====
            const bolakLetter = c => { const m = BOLAK_RX.exec(String(c.subject_name || '').trim()); return m ? m[2].toLowerCase() : ''; };
            const parallelSet = c => (c && c.training_type !== 'lecture' && BOLAK_RX.test(String(c.subject_name || '').trim())
                ? cards.filter(x => x.id !== c.id && !isCycleCardAny(x) && bolakSiblings(c, x)) : []);
            // "parallel: a · b · c" belgisi (sichqoncha olib borilsa — qolganlari ajratiladi: data-par-ids).
            function parallelBadgeHtml(c) {
                const set = parallelSet(c);
                if (!set.length) return '';
                const letters = [...new Set([c, ...set].map(bolakLetter).filter(Boolean))].sort();
                return '<div class="tt-par-badge" data-par-ids="' + [c.id, ...set.map(x => x.id)].join(',') + '" title="Parallel bo\'laklar — guruhning turli talabalari, bir vaqtda yonma-yon">parallel: ' +
                    letters.map(l => l === bolakLetter(c) ? '<b>' + esc(l) + '</b>' : esc(l)).join(' · ') + '</div>';
            }
            // Sichqoncha belgida — to'plamning qolgan kartalari (panel va jadval) ajratiladi.
            document.addEventListener('mouseover', ev => {
                const b = ev.target && ev.target.closest ? ev.target.closest('[data-par-ids]') : null;
                document.querySelectorAll('.tt-par-hl').forEach(x => x.classList.remove('tt-par-hl'));
                if (!b) return;
                b.dataset.parIds.split(',').forEach(id => document.querySelectorAll('.pn-card[data-id="' + id + '"], #grid [data-chip="' + id + '"]')
                    .forEach(x => x.classList.add('tt-par-hl')));
            });
            // "Joylash uchun tanlash": sichqoncha band katakda — sabab bo'lgan dars(lar) jadvalda shu sabab rangidagi ramka bilan (ekranda bo'lsa;
            // bitta dars ikki sababga — og'irrog'i). Birlashtirilgan chip (data-merge-ids) — qismlaridan biri sabab bo'lsa ham.
            let placeCauseCell = null;
            const PLACE_CAUSE_CLS = ['tt-cause-teacher', 'tt-cause-group', 'tt-cause-room'];
            function placeCauseMark(td) {
                if (td === placeCauseCell) return;
                placeCauseCell = td;
                document.querySelectorAll('#grid .tt-cause-teacher, #grid .tt-cause-group, #grid .tt-cause-room').forEach(x => x.classList.remove(...PLACE_CAUSE_CLS));
                if (!td) return;
                const want = {};
                String(td.dataset.badIds || '').split(',').forEach(x => { const [id, k] = x.split(':'); if (id && k) want[id] = k; });
                document.querySelectorAll('#grid [data-chip]').forEach(el => {
                    const kinds = [el.dataset.chip, ...String(el.dataset.mergeIds || '').split(',')].map(id => want[id]).filter(Boolean);
                    if (!kinds.length) return;
                    const k = kinds.sort((a, b) => PLACE_RANK[b] - PLACE_RANK[a])[0];
                    el.classList.add('tt-cause-' + (k === 'other' ? 'teacher' : k));
                });
            }
            document.addEventListener('mouseover', ev => placeCauseMark(ev.target && ev.target.closest ? ev.target.closest('#grid td[data-bad-ids]') : null));
            // Bittasi ko'chirilgach — qolganlarini ham shu vaqtga ko'chirish taklifi (sahifa ichida; o'zi ko'chirilmaydi).
            function parallelMoveOffer(moved, others, d, p) {
                let box = document.getElementById('ttParOffer');
                if (box) box.remove();
                if (!others.length) return null;
                box = document.createElement('div');
                box.id = 'ttParOffer';
                box.setAttribute('role', 'status');
                box.style.cssText = 'position:fixed;right:16px;bottom:16px;z-index:80;background:#eef2ff;border:1px solid #6366f1;color:#312e81;border-radius:8px;padding:8px 10px;font-size:12px;box-shadow:0 8px 24px #0002;max-width:360px';
                const when = (boardDayNames()[d - 1] || (d + '-kun')) + ', ' + slotParaLabel(p);
                box.innerHTML = '«' + esc(moved.subject_name) + '» ' + esc(when) + ' ga ko\'chdi. Parallel bo\'laklar (' + esc(others.map(bolakLetter).join(', ')) + ') ham shu vaqtga ko\'chirilsinmi?' +
                    '<div style="margin-top:6px;display:flex;gap:6px"><button type="button" data-par-yes style="background:#4f46e5;color:#fff;border-radius:5px;padding:1px 8px">Ha, ko\'chirish</button>' +
                    '<button type="button" data-par-no style="border:1px solid #a5b4fc;border-radius:5px;padding:1px 8px">Yo\'q</button></div><div data-par-msg style="color:#b91c1c;margin-top:4px"></div>';
                document.body.appendChild(box);
                box.addEventListener('click', async ev => {
                    if (ev.target.closest('[data-par-no]')) { box.remove(); return; }
                    const yes = ev.target.closest('[data-par-yes]');
                    if (!yes) return;
                    yes.disabled = true;
                    const errs = [];
                    for (const x of others) {
                        try { await placeUnitAt(x, d, p); } catch (e) { errs.push(bolakLetter(x) + ': ' + e.message); }
                    }
                    renderAll();
                    if (errs.length) { box.querySelector('[data-par-msg]').textContent = errs.join(' · '); yes.disabled = false; }
                    else box.remove();
                });
                return box;
            }
            // Birlashtirilgan (ketma-ket) blok — kartalarni ketma-ket paralarga joylaymiz
            // parallel — bo'lakli fan bo'laklari: hammasi bitta katakka (ketma-ket emas).
            async function placeBlockAt(ids, d, p, parallel, offs) {
                // Amaliy dars — birlik bilan (barcha bo'laklari, ketma-ket): p — sudralgan bo'lak qo'yiladigan joy, birlik boshi undan
                // oldingi bo'laklar uzunligicha yuqorida. Sig'masa — server sababi, hech narsa o'zgarmaydi.
                const first = !parallel ? cards.find(x => x.id === ids[0]) : null;
                // Shu haftada bekor qilingan dars ("Ko'rsatish" bilan panelda) sudrab qaytarilsa — avvalgidek shu kartaning o'zi tiklanadi
                // (week-override move); birlik faqat o'tiladigan bo'laklardan.
                if (first && first.training_type !== 'lecture' && activeInWeek(first, curWeek)) {
                    const list = unitOf(first);
                    const start = p - unitLen(list.slice(0, Math.max(0, list.indexOf(first))));
                    // Parallel bo'laklar: avval shu joyda turganlari (yoki hammasi joylanmagan bo'lsa — joylanmaganlari) — ko'chirish taklifi uchun.
                    const oldPl = effPlace(first);
                    const mates = parallelSet(first).filter(x => {
                        const pl = effPlace(x);
                        return oldPl ? !!(pl && +pl.day === +oldPl.day && +pl.pair === +oldPl.pair) : !pl;
                    });
                    try {
                        await placeUnitAt(first, d, start); selected = null; renderAll();
                        parallelMoveOffer(first, mates, d, start);
                    }
                    catch (e) { alert(e.message); renderAll(); }
                    return;
                }
                // Bo'laklar o'z siljishini saqlab ko'chadi ((a) 12:40 da bo'lsa, yangi joyda ham yarim para keyin)
                // Ketma-ket blok: har karta oldingilarining uzunligi (yarim-slot) qadar keyin turadi
                // (2 soat + 1 soat → p va p+2; avval k qo'shilardi va kartalar ustma-ust tushardi).
                const seqOff = [];
                ids.reduce((acc, id, k) => { seqOff[k] = acc; const x = cards.find(c => c.id === id); return acc + (x ? cardLen(x) : 1); }, 0);
                const at = k => p + (parallel ? ((offs && offs[k]) || 0) : seqOff[k]);
                // Bo'laklar birga ko'chadi: birortasi sig'masa (o'qituvchi/xona band) — hech biri
                // ko'chirilmaydi, aks holda so'rovlar birma-bir ketib, guruh yarim ko'chgan holda qolardi.
                if (parallel) {
                    for (const id of ids) {
                        const card = cards.find(x => x.id === id);
                        const errs = card ? conflictsAt(card, d, at(ids.indexOf(id)), ids) : [];
                        if (errs.length) { alert('Konflikt (' + card.subject_name + '): ' + errs.join('; ')); return; }
                    }
                }
                try {
                    const moves = ids.map((id, k) => ({ card: cards.find(x => x.id === id), pair: at(k) }))
                        .filter(move => move.card);
                    {
                        // Pastga surilganda oxirgi qism avval ko'chadi: oldingi qismga joy bo'shatadi
                        // (aks holda blok o'z eski joyi bilan "Guruh band" konfliktiga tushadi).
                        const later = moves.every(move => {
                            const pl = effPlace(move.card);
                            return pl && +pl.day === d && move.pair >= +pl.pair;
                        });
                        moves.sort((a, b) => later ? b.pair - a.pair : a.pair - b.pair);
                    }
                    for (const move of moves) await placeOneCard(move.card, d, move.pair);
                    selected = null; renderAll();
                } catch (e) { alert('Konflikt: ' + e.message); }
            }
            // Sudrash: katak (bir necha yarim-slotli — rowspan) ichida sichqoncha qaysi yarim-slotda — har para katagi ikkita
            // yarim para nishoni (08:30 / 09:10, 12:00 / 12:40 …).
            function dropSlotAt(td, ev) {
                const base = +td.dataset.pair, rs = td.rowSpan || 1;
                if (rs <= 1 || !ev || !td.getBoundingClientRect) return base;
                const r = td.getBoundingClientRect();
                const k = Math.floor((ev.clientY - r.top) / ((r.height || 1) / rs));
                return base + Math.max(0, Math.min(rs - 1, k));
            }
            // Sudralayotgan dars d kuni p ga tushsa: birlik boshi, uzunligi va to'qnashuvlar (birlikning o'z bo'laklari hisobga olinmaydi).
            function dragPlan(ids, d, p, parallel) {
                const first = cards.find(x => x.id === ids[0]);
                if (!first) return null;
                if (!parallel && first.training_type !== 'lecture' && activeInWeek(first, curWeek)) {
                    const list = unitOf(first);
                    const start = p - unitLen(list.slice(0, Math.max(0, list.indexOf(first))));
                    const mine = list.map(x => x.id);
                    let at = start;
                    const items = [];
                    list.forEach(x => { items.push(...conflictsAtDetail(x, d, at, mine)); at += cardLen(x); });
                    const maxRow = boardSchedule().filter(it => it.type === 'pair').length || 12;
                    if (start < 1 || start + unitLen(list) - 1 > maxRow) items.push({ kind: 'other', cardId: null, text: 'kun oxiri' });
                    return { start, len: unitLen(list), items, errs: items.map(x => x.text) };
                }
                const len = parallel ? Math.max(...ids.map(id => { const x = cards.find(c => c.id === id); return x ? cardLen(x) : 1; }))
                    : ids.reduce((n, id) => { const x = cards.find(c => c.id === id); return n + (x ? cardLen(x) : 1); }, 0);
                const items = conflictsAtDetail(first, d, p, ids);
                return { start: p, len, items, errs: items.map(x => x.text) };
            }
            // Sudrash nishoni rangi (tanlashdagi bilan bir xil hukm): drag-ok | drag-bad + drag-bad-<tur>.
            const DRAG_TONES = ['drag-ok', 'drag-bad', 'drag-bad-teacher', 'drag-bad-group', 'drag-bad-room', 'drag-bad-closed'];
            function dragPaint(el, items) {
                el.classList.remove(...DRAG_TONES);
                const v = placeVerdict(items);
                if (v.tone === 'ok') el.classList.add('drag-ok'); else el.classList.add('drag-bad', 'drag-bad-' + v.tone);
            }
            // Sudrash paytida tushadigan vaqt oralig'i ("12:40–15:00") — sichqoncha yonida.
            function dragTip(ev, plan) {
                let tip = document.getElementById('ttDragTip');
                if (!plan) { if (tip) tip.remove(); return; }
                if (!tip) {
                    tip = document.createElement('div');
                    tip.id = 'ttDragTip';
                    tip.style.cssText = 'position:fixed;z-index:90;pointer-events:none;font:600 11px/1.2 system-ui,sans-serif;padding:3px 7px;border-radius:6px;box-shadow:0 2px 8px #0003';
                    document.body.appendChild(tip);
                }
                const bad = plan.errs.length > 0;
                tip.textContent = (slotRangeText(plan.start, plan.len) || '') + (bad ? ' — band' : '');
                tip.style.background = bad ? '#fee2e2' : '#dcfce7';
                tip.style.color = bad ? '#991b1b' : '#166534';
                tip.style.left = (ev.clientX + 14) + 'px';
                tip.style.top = (ev.clientY + 12) + 'px';
            }
            let unitPanelLen = {};   // panel kartasi id → birlik bo'laklari uzunligi (jami soat yozuvi uchun)
            // ===== Drag-and-drop holati (blok = bir yoki bir necha ketma-ket karta) =====
            let dragCardIds = null;
            let dragParallel = false;
            let dragOffsets = null;   // bo'laklar sarlavhasi: har bo'lakning katak boshidan siljishi (yarim-slot)
            function startDrag(ids, ev, parallel, offs) {
                if (TIMETABLE_READ_ONLY) { if (ev) ev.preventDefault(); return; }
                dragCardIds = Array.isArray(ids) ? ids.slice() : [ids];
                dragParallel = !!parallel;
                dragOffsets = Array.isArray(offs) ? offs.slice() : null;
                // Bo'lak katagi ichidagi yarim-slot chiziqlari tushish nishoniga aylanadi
                setTimeout(() => { const g = document.getElementById('grid'); if (g && dragCardIds) g.classList.add('tt-dragging'); }, 0);
                if (ev && ev.dataTransfer) {
                    ev.dataTransfer.effectAllowed = 'move';
                    try { ev.dataTransfer.setData('text/plain', dragCardIds.join(',')); } catch (e) { /* ba'zi brauzerlar */ }
                }
            }
            // Sudrash tugagach holatni tozalash (tashlanmagan bo'lsa ham)
            document.addEventListener('dragend', () => {
                dragCardIds = null;
                dragParallel = false;
                dragOffsets = null;
                const gEl = document.getElementById('grid');
                if (gEl) gEl.classList.remove('tt-dragging');
                document.querySelectorAll('.drag-ok, .drag-bad').forEach(el => el.classList.remove(...DRAG_TONES));
                const panel = document.getElementById('cardPanel');
                if (panel) panel.classList.remove('pn-drop');
                dragTip(null, null);
            });

            // ===== Faol katak: sichqoncha ustidan o'tganda belgilash + strelkalar bilan yurish =====
            let activeCell = null;
            function setActiveCell(td) {
                if (activeCell === td) return;
                if (activeCell) activeCell.classList.remove('tt-active');
                activeCell = td || null;
                if (activeCell) activeCell.classList.add('tt-active');
            }
            // Sichqoncha katak ustidan o'tganda faollashtiramiz (delegatsiya — qayta render'da ham ishlaydi)
            $('grid').addEventListener('mouseover', ev => {
                const td = ev.target.closest && ev.target.closest('#grid td[data-day]');
                if (td) setActiveCell(td);
            });
            // Strelkalar — faol katakni yo'nalish bo'yicha eng yaqin katakka ko'chiramiz
            document.addEventListener('keydown', ev => {
                if (!activeCell || !activeCell.isConnected) return;
                const dir = { ArrowRight: 'r', ArrowLeft: 'l', ArrowDown: 'd', ArrowUp: 'u' }[ev.key];
                if (!dir) return;
                const t = ev.target;
                if (t && (t.tagName === 'INPUT' || t.tagName === 'SELECT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
                ev.preventDefault();
                const cells = [...document.querySelectorAll('#grid td[data-day]')];
                const r = activeCell.getBoundingClientRect();
                const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
                let best = null, bestScore = Infinity;
                for (const td of cells) {
                    if (td === activeCell) continue;
                    const rr = td.getBoundingClientRect();
                    const x = rr.left + rr.width / 2, y = rr.top + rr.height / 2;
                    const dx = x - cx, dy = y - cy;
                    let ok, score;
                    if (dir === 'r') { ok = dx > 3; score = dx + Math.abs(dy) * 3; }
                    else if (dir === 'l') { ok = dx < -3; score = -dx + Math.abs(dy) * 3; }
                    else if (dir === 'd') { ok = dy > 3; score = dy + Math.abs(dx) * 3; }
                    else { ok = dy < -3; score = -dy + Math.abs(dx) * 3; }
                    if (ok && score < bestScore) { bestScore = score; best = td; }
                }
                if (best) { setActiveCell(best); best.scrollIntoView({ block: 'nearest', inline: 'nearest' }); }
            });

            // ===== Render =====
            function renderAll() { resetCompactCache(); try { buildSubjectColors(colorScopeCards()); } catch (e) { } buildGroupRows(); renderPanel(); renderGrid(); renderStats(); updateCheckBadge(); syncUrl(); markPendingChanges(); renderWeeklyLayerUi(); refreshWeeklyConflicts(); }

            // ===== Ichki (haftalik) jadvaldagi to'qnashuvlar: karta joyida qoladi, lekin "Joylashgan" hisobiga kirmaydi va =====
            // joylanmaganlar panelida sababi bilan chiqadi. Joylashuv/o'qituvchi/xona o'zgarsa — serverdan qayta so'raladi.
            let weeklyConflicts = {};   // karta id => { hafta: sabab } — faqat kelgusi (karta qizil)
            let weeklyConflictItems = {};   // karta id => { hafta: [tuzilgan ro'yxat] } — o'tganlari ham (past)
            // Xona sig'imi (1.4) — ogohlantirish, to'qnashuv emas (hisoblagichga kirmaydi): tanlangan hafta, karta id => {…, line}.
            let weeklyCapWarn = { week: 0, map: {} };
            // Faqat ichki qatlam: tashqi jadvalda xona biriktirilmaydi (applyWeeklyLayer) — ichki xona haqidagi ogohlantirish ko'rinmaydi.
            const weeklyCapLine = c => (c && curWeek && weeklyLayer === 'internal' && weeklyCapWarn.week === curWeek && weeklyCapWarn.map[c.id]
                ? weeklyCapWarn.map[c.id].line || '' : '');
            let conflictSig = '';
            let conflictTimer = null;
            let conflictGen = 0;   // so'rov avlodi: kechikkan (eskirgan holat uchun) javob yangisining ustiga yozmasin
            function conflictSignature() {
                if (!board) return '';
                return board.id + '#' + allCards.map(c => [c.id, c.day, c.pair, c.len_half, c.start_half, c.teacher_id, c.auditorium_code].join(':')).join(',') + '#' +
                    Object.keys(overrides).map(k => [k, overrides[k].day, overrides[k].pair, overrides[k].cancelled ? 1 : 0, overrides[k].auditorium_code].join(':')).join(',');
            }
            // Doska qayta yuklandi (dastur kalendari/ta'til, panjara sozlamasi, boshqalarning o'zgarishi) — karta maydonlari
            // o'zgarmasa ham sanalar boshqacha bo'lishi mumkin: keyingi chizishda albatta qayta so'raladi.
            function invalidateWeeklyConflicts() { conflictSig = ''; }
            function refreshWeeklyConflicts() {
                const sig = conflictSignature();
                if (!sig || sig === conflictSig) return;
                conflictSig = sig;
                clearTimeout(conflictTimer);
                const boardId = board.id, gen = ++conflictGen;
                conflictTimer = setTimeout(async () => {
                    try {
                        const j = await api(BASE + '/boards/' + boardId + '/conflicts');
                        if (gen !== conflictGen || !board || board.id !== boardId) return;
                        weeklyConflicts = j.weekly || {};
                        weeklyConflictItems = {};
                        renderStats();
                        loadWeekConflictItems();
                        if (viewMode !== 'cycle') renderPanel();
                    } catch (e) { console.warn('To\'qnashuvlar olinmadi:', e); }
                }, 600);
            }
            // Tanlangan hafta to'qnashuvlarining tuzilgan ro'yxati (panel kartasidagi qisqa belgi uchun) — faqat shu hafta, yengil so'rov.
            async function loadWeekConflictItems() {
                if (!board || !curWeek || weeklyLayer === 'external' || weeklyConflictItems.__week === curWeek || weeklyConflictItems.__loading === curWeek) return;
                const boardId = board.id, week = curWeek, gen = conflictGen;
                weeklyConflictItems.__loading = week;
                try {
                    const j = await api(BASE + '/boards/' + boardId + '/conflicts?items=1&week=' + week);
                    if (gen !== conflictGen || !board || board.id !== boardId || curWeek !== week) return;
                    weeklyConflictItems = {};
                    Object.entries(j.weekly_items || {}).forEach(([id, weeks]) => { weeklyConflictItems[id] = weeks; });
                    weeklyConflictItems.__week = week;
                    const hadCaps = Object.keys(weeklyCapWarn.map).length > 0;
                    weeklyCapWarn = { week, map: j.weekly_caps || {} };
                    if (viewMode !== 'cycle') {
                        renderPanel();
                        // Sig'im belgisi katakdagi kartada — jadval ham qayta chiziladi (ogohlantirish bor yoki yo'qoldi).
                        if ((hadCaps || Object.keys(weeklyCapWarn.map).length) && typeof renderGrid === 'function') renderGrid();
                    }
                } catch (e) { /* belgi — matn bilan qoladi */ }
            }
            // Joylashgan kartaning ichki jadvaldagi to'qnashuvi (joriy hafta; shablon ko'rinishida — birorta haftada bo'lsa).
            function cardConflict(c) {
                if (isNonBlocking(c)) return null;
                if (weeklyLayer === 'external' || !effPlace(c)) return null;
                const byWeek = weeklyConflicts[c.id];
                if (!byWeek) return null;
                if (curWeek) return byWeek[curWeek] || null;
                const weeks = Object.keys(byWeek).sort((a, b) => a - b);
                return weeks.length ? weeks.join(', ') + '-hafta: ' + byWeek[weeks[0]] : null;
            }

            function renderStats() {
                // Shu haftada o'tilmaydigan kartalar hisobga olinmaydi — aks holda
                // ular "joylashmagan" bo'lib ko'rinib qolardi.
                const sc = weekActiveCards();
                const placed = sc.filter(c => effPlace(c) && !cardConflict(c)).length;
                // Sikl (4-6 kurs) kartalari haftalik panjaraga (kun/para) emas, sikl kalendariga
                // joylanadi — haftalik hisobga qo'shilsa, doim "joylanmagan" bo'lib ko'rinadi.
                const boardCards = cards.filter(c => !weekCancelled(c) && !isCycleCardAny(c));
                const totPlaced = boardCards.filter(c => effPlace(c)).length;
                const typeLbl = { all: '', lecture: ' · faqat ma\'ruza', practice: ' · faqat amaliy' }[typeFilter];
                const weekLbl = curWeek ? ' · ' + curWeek + '-hafta' : '';
                // Sikl bloklari — panel bilan bir xil qamrov (cycleScopedCards) va bir xil "joylangan" mezoni (card.placed; to'qnashuvli
                // blok ham joyida turibdi — panelda "joylangan · to'qnashuv"). To'qnashuvlilar alohida soni bilan.
                const cyc = (viewMode === 'cycle' && cyclePlanData && Array.isArray(cyclePlanData.cycle_cards)) ? cycleScopedCards(cyclePlanData).scoped : null;
                const cycCf = cyc ? cyc.filter(c => c.placed && c.conflict).length : 0;
                const first = cyc
                    ? '<span class="rounded-md px-2 py-1 bg-green-50 text-green-700" data-cycle-count title="Panel qamrovidagi sikl bloklari (fan × oqim/guruh × mashg\'ulot turi): joylangan / jami">Sikl bloklari: <b>' +
                        cyc.filter(c => c.placed).length + '/' + cyc.length + '</b>' + (cycCf ? ' · to\u2018qnashuvli: <b>' + cycCf + '</b>' : '') + '</span>'
                    : '<span class="rounded-md px-2 py-1 bg-green-50 text-green-700">Joylashgan: <b>' + placed + '/' + sc.length + '</b>' + typeLbl + weekLbl + '</span>';
                // O'qituvchi / fan / xona kesimida: shu haftada ko'rinayotgan haftalik va sikl darslari soni.
                const crossCount = CROSS_MODES.includes(viewMode) && curWeek
                    ? '<span class="rounded-md px-2 py-1 bg-teal-50 text-teal-700" data-cross-count title="Shu hafta kesimda ko\'rinayotgan darslar: haftalik jadval va sikl jadvali (ichki qatlam)">Haftalik: <b>' +
                        sc.filter(c => effPlace(c)).length + '</b> · Sikl: <b>' + cycleWeekLessons().length + '</b> dars</span>' : '';
                $('statChips').innerHTML = first + crossCount +
                    '<span class="rounded-md px-2 py-1 bg-gray-100 text-gray-600" title="Haftalik jadval kartalari (sikl fanlari bundan tashqari — ular sikl kalendarida)">Doska bo\'yicha (haftalik): <b>' + totPlaced + '/' + boardCards.length + '</b></span>';
                // Sikl rejimida panel soni va eksport tugmasi — renderCycleCards niki (panel qamrovi); haftalik ma'lumot ularni bosmaydi.
                if (!cyc) {
                    $('unplacedCount').textContent = (sc.length - placed) + ' ta';
                    $('unplacedExportBtn').classList.toggle('hidden', !sc.some(c => !effPlace(c) || cardConflict(c)));
                }
                $('weekHint').classList.toggle('hidden', !curWeek);
            }

            // Joylanmagan kartalar diagnostikasi (unplaced-export) — panel tugmasi va HEMIS solishtirish ogohlantirishi uchun.
            async function downloadUnplacedXlsx(params) {
                params.set('_', Date.now());
                const response = await fetch(BASE + '/boards/' + board.id + '/unplaced-export?' + params.toString(), {
                    headers: { 'Accept': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' },
                    cache: 'no-store',
                });
                if (!response.ok) {
                    const error = await response.json().catch(() => ({}));
                    throw new Error(error.error || 'HTTP ' + response.status);
                }
                const blob = await response.blob();
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'joylanmagan-kartalar-diagnostikasi-' + board.id + '.xlsx';
                document.body.appendChild(a);
                a.click();
                a.remove();
                URL.revokeObjectURL(url);
            }
            async function downloadUnplacedDiagnostics() {
                if (!board) return;
                const btn = $('unplacedExportBtn');
                const old = btn.innerHTML;
                btn.disabled = true;
                btn.innerHTML = '<i class="bi bi-hourglass-split" aria-hidden="true"></i> Tayyorlanmoqda...';
                try {
                    const params = new URLSearchParams();
                    [...selectedFaculties].forEach(v => params.append('faculty_names[]', v));
                    [...selectedDirs].forEach(v => params.append('specialty_names[]', v));
                    [...selectedCourses].forEach(v => params.append('courses[]', v));
                    params.set('type', typeFilter);
                    params.set('layer', weeklyLayer);
                    if (curWeek) params.set('week', curWeek);
                    await downloadUnplacedXlsx(params);
                } catch (e) {
                    alert('Diagnostika Excelini yuklab bo\'lmadi: ' + e.message);
                } finally {
                    btn.disabled = false;
                    btn.innerHTML = old;
                }
            }

            $('unplacedExportBtn').onclick = downloadUnplacedDiagnostics;
            // Butun doska bo'yicha joylanmagan kartalar hisoboti — tanlangan fakultetga qaramasdan, joriy qatlam (tashqi/ichki) bilan.
            // Katta doskada bir necha daqiqa oladi (60 s da nginx 504) — fonda tayyorlanadi: oynada progress, tayyor bo'lsa o'zi yuklanadi.
            // Oyna yopilsa ham hisobot tayyorlanaveradi; tugma qayta bosilsa server ishlab turgan shu hisobotni qaytaradi.
            if ($('unplacedReportBtn')) $('unplacedReportBtn').onclick = async function () {
                if (!board) return;
                const url = BASE + '/boards/' + board.id + '/unplaced-report';
                let m = $('unplacedReportModal');
                if (!m) {
                    m = document.createElement('div');
                    m.id = 'unplacedReportModal';
                    m.className = 'fixed inset-0 z-[9999] bg-black/40 flex items-start justify-center p-4';
                    document.body.appendChild(m);
                }
                const run = {};   // shu ochilish; oyna yopilsa (yoki qayta ochilsa) eski so'rovlar to'xtaydi
                m.run = run;
                m.innerHTML = '<div class="bg-white rounded-xl shadow-xl w-full max-w-md p-4 text-[12px]">' +
                    '<h3 class="font-semibold text-[14px] mb-2">Butun doska (Excel) — joylanmagan kartalar</h3>' +
                    '<div id="urStep" class="mb-1 text-gray-700">Navbatga qo\'yilmoqda…</div>' +
                    '<div class="tt-report-track"><div id="urBar" class="tt-report-bar" style="width: 0%"></div></div>' +
                    '<div id="urPct" class="mt-1 text-right text-gray-500">0%</div>' +
                    '<div id="urErr" class="hidden mt-2 p-2 rounded border border-red-300 bg-red-50 text-red-700"></div>' +
                    '<div class="mt-3 flex items-center justify-between gap-2"><span class="text-gray-500">Yopsangiz ham hisobot fonda tayyorlanaveradi.</span>' +
                    '<button type="button" id="urClose" class="px-3 py-1 rounded border bg-white">Yopish</button></div></div>';
                const alive = () => m.run === run && !run.closed;
                $('urClose').onclick = () => { run.closed = true; m.remove(); };
                // Xato holatida foiz va bosqich yangilanmaydi ("Tayyor 100%" chiqmasin); 100% — faqat tayyor hisobot.
                const show = st => {
                    if (st.status === 'error') return;
                    const pct = st.status === 'done' ? 100 : Math.max(0, Math.min(99, Math.round(Number(st.percent) || 0)));
                    $('urBar').style.width = pct + '%';
                    $('urPct').textContent = pct + '%';
                    $('urStep').textContent = st.status === 'done' ? 'Fayl yuklab olinmoqda…' : (st.step_label || st.message || '');
                };
                try {
                    const started = await api(url, 'POST', { layer: weeklyLayer });
                    const token = encodeURIComponent(started.token);
                    let st = started.state || {}, misses = 0;
                    while (alive()) {
                        show(st);
                        if (st.status === 'error') throw new Error(st.message || 'noma\'lum xato');
                        if (st.status === 'done') {
                            const r = await fetch(url + '/download?token=' + token, { cache: 'no-store' });
                            if (!r.ok) {
                                const j = await r.json().catch(() => ({}));
                                throw new Error(j.error || j.message || 'HTTP ' + r.status);
                            }
                            const blob = await r.blob();
                            const name = /filename="?([^";]+)"?/.exec(r.headers.get('Content-Disposition') || '');
                            const a = document.createElement('a');
                            a.href = URL.createObjectURL(blob);
                            a.download = name ? name[1] : 'joylanmagan_kartalar_butun_doska.xlsx';
                            document.body.appendChild(a);
                            a.click();
                            a.remove();
                            setTimeout(() => URL.revokeObjectURL(a.href), 5000);
                            if (alive()) $('urStep').textContent = 'Tayyor — fayl yuklab olindi.';
                            return;
                        }
                        await new Promise(r => setTimeout(r, 1500));
                        if (!alive()) return;
                        // Holatni so'rash bir-ikki marta uzilsa (tarmoq) — kutamiz; ketma-ket 3 marta bo'lmasa — xato.
                        try { st = await api(url + '/status?token=' + token); misses = 0; }
                        catch (e) { if (++misses >= 3) throw e; }
                    }
                } catch (e) {
                    if (!alive()) return;
                    $('urBar').classList.add('is-error');
                    $('urStep').textContent = 'Xatolik';
                    $('urPct').textContent = '';
                    $('urErr').textContent = 'Hisobotni tayyorlab bo\'lmadi: ' + e.message;
                    $('urErr').classList.remove('hidden');
                }
            };

            // Bo'lakli fan ("Tibbiyot kasbiga kirish. Terapiya (a)"): qisqa nomda asosiy qism
            // (oxirgi nuqtadan keyingisi — "Terapiya") va bo'lak harfi doim ko'rinadi,
            // aks holda uzun umumiy boshlanma tufayli (a) yoki (c) ekani bilinmay qolardi.
            function cardLabel(c, short) {
                const t = c.training_type === 'lecture' ? 'M' : 'A';
                const bm = BOLAK_RX.exec(String(c.subject_name || '').trim());
                if (bm) {
                    let baseName = bm[1].trim();
                    if (short) {
                        const parts = baseName.split(/\.\s+/).filter(Boolean);
                        if (parts.length > 1) baseName = parts[parts.length - 1];
                        if (baseName.length > 20) baseName = baseName.slice(0, 20) + '…';
                    }
                    return infoOnlyBadgeHtml(c) + '<b>[' + t + ']</b> ' + esc(baseName) + ' <b class="tt-bolak-tag">(' + esc(bm[2]) + ')</b>';
                }
                const name = short && c.subject_name.length > 26 ? c.subject_name.slice(0, 26) + '…' : c.subject_name;
                return infoOnlyBadgeHtml(c) + '<b>[' + t + ']</b> ' + esc(name);
            }
            // Karta ustiga kursor olib borilganda chiqadigan to'liq ma'lumot (sikldagi kabi).
            function cardTooltip(c, extra) {
                const bm = BOLAK_RX.exec(String(c.subject_name || '').trim());
                return [
                    c.subject_name + ' — ' + (c.training_type === 'lecture' ? "ma'ruza" : 'amaliy'),
                    bm ? '(' + bm[2] + ") bo'lak — guruh talabalarining bir qismi, boshqa bo'laklar bilan parallel" : '',
                    (c.oqim_label ? c.oqim_label + ' · ' : '') + 'Guruh: ' + cardGroups(c).join(', ') + (c.students ? ' · ' + c.students + ' talaba' : ''),
                    "O'qituvchi: " + (c.teacher_name || 'biriktirilmagan'),
                    'Xona: ' + (c.auditorium_name ? c.auditorium_name + (c.auditorium_volume ? " (sig'im " + c.auditorium_volume + ')' : '') : 'biriktirilmagan'),
                    c.kafedra_name ? 'Kafedra: ' + c.kafedra_name : '',
                    roomInactive(c.auditorium_code) ? '⚠ ' + ROOM_OFF_TEXT : '',
                    extra || '',
                ].filter(Boolean).join('\n');
            }

            // Joylashmagan kartalar — pastda gorizontal panel (aSc uslubida): tekis
            // ravishda ketma-ket chiqadi (fan bo'yicha saralangan, guruhlash chizig'i yo'q).
            // Hafta ko'rinishida shu haftada o'tilmaydigan kartalar bu yerga tushmaydi.
            // ===== "Vaqtincha kafedra mudiriga yozish" (to'qnashuv hal bo'lguncha) =====
            // Joy: tashqi jadvaldagi joyi; bo'lmasa — joylashgan joyi (to'qnashuvli karta); bo'lmasa — jadvaldan katak tanlanadi (mudirPick).
            // O'qituvchi — fan kafedrasi mudiri, xona — «Kafedra mudiri xonasi» (server). To'qnashuv tekshirilmaydi. Admin va kafedra mudiri.
            // Javob (notified — xabar yuborilgan kafedra mudirlari): "Kafedra mudiriga yozildi va xabar yuborildi: F.I.Sh."
            function mudirNotifiedText(res) {
                const who = (res && Array.isArray(res.notified) ? res.notified : []).filter(Boolean);
                return who.length ? 'Kafedra mudiriga yozildi va xabar yuborildi: ' + esc(who.join(', ')) : 'Kafedra mudiriga yozildi (xabar yuborilmadi — kafedra mudiri topilmadi)';
            }
            // "Vaqtincha kafedra mudiriga yozish" — faqat jadval administratorlari (registrator ofisi, o'quv bo'limi, adminlar); kafedra mudiri
            // yozmaydi (server 403). "Asl holatga qaytarish" — kafedra mudirida qoladi (o'z kafedrasi fanlari — server tekshiradi).
            const mudirPhAllowed = () => !TIMETABLE_READ_ONLY && weeklyLayer === 'internal' && !!curWeek && typeof WEEKLY_ADMIN !== 'undefined' && WEEKLY_ADMIN;
            const mudirPhRevertAllowed = () => !TIMETABLE_READ_ONLY && weeklyLayer === 'internal' && !!curWeek
                && (typeof WEEKLY_ADMIN !== 'undefined' && WEEKLY_ADMIN || TIMETABLE_ROLE === 'kafedra_mudiri');
            let mudirPick = null;   // tashqi joyi yo'q karta — jadvaldan katak kutilmoqda
            const phRevertErr = {};   // birlik kaliti → "asl o'qituvchiga qaytarib bo'lmadi" sababi
            function mudirPhSlot(c) {
                if (c.ext_day && c.ext_pair) return { day: +c.ext_day, pair: +c.ext_pair };
                const pl = effPlace(c);
                return pl ? { day: +pl.day, pair: +pl.pair } : null;
            }
            async function mudirPhInfo(c, slot) {
                const q = new URLSearchParams({ week: curWeek });
                if (slot) { q.set('day', slot.day); q.set('pair', slot.pair); }
                return api(BASE + '/cards/' + c.id + '/mudir-placeholder?' + q);
            }
            // Tasdiq oynasi (sahifa ichida): "… — Chorshanba, II para (10:00–12:40) ga kafedra mudiri <FISH> nomiga, «Kafedra mudiri
            // xonasi»da yoziladi. To'qnashuv tekshirilmaydi." + sabab (ixtiyoriy) + shu hafta / shu va keyingi haftalar.
            async function openMudirPhConfirm(c, slot) {
                slot = slot || mudirPhSlot(c);
                if (!slot) {
                    mudirPick = c; selected = c;
                    closePanelCardPop();
                    renderPanel(); renderGrid();
                    if ($('boardMsg')) $('boardMsg').textContent = 'Vaqtincha kafedra mudiriga yozish: jadvaldan katakni bosing.';
                    return;
                }
                let info;
                try { info = await mudirPhInfo(c, slot); } catch (e) { info = { ok: false, why: e.message }; }
                let m = document.getElementById('ttMudirPhModal');
                if (m) m.remove();
                m = document.createElement('div');
                m.id = 'ttMudirPhModal';
                m.setAttribute('role', 'dialog');
                m.style.cssText = 'position:fixed;inset:0;z-index:85;background:rgba(15,23,42,.35);display:flex;align-items:center;justify-content:center;padding:16px';
                const len = (info && info.len) || unitLen(unitOf(c));
                const when = (boardDayNames()[slot.day - 1] || (slot.day + '-kun')) + ', ' + slotParaLabel(slot.pair) + ' (' + slotRangeText(slot.pair, len) + ')';
                const text = cardGroups(c).join(', ') + ' · ' + c.subject_name + ' — ' + when + ' ga kafedra mudiri ' + ((info && info.mudir && info.mudir.name) || '—') +
                    " nomiga, «Kafedra mudiri xonasi»da yoziladi. To'qnashuv tekshirilmaydi.";
                m.innerHTML = '<div style="background:#fff;border-radius:10px;max-width:520px;width:100%;padding:12px 16px;box-shadow:0 20px 60px #0004;font-size:12px">' +
                    '<b>Vaqtincha kafedra mudiriga yozish</b>' +
                    (info && info.ok ? '<p data-ph-text style="margin:6px 0">' + esc(text) + '</p>' +
                        '<label style="display:block;margin:4px 0"><input type="radio" name="phScope" value="one" checked> faqat ' + curWeek + '-hafta</label>' +
                        '<label style="display:block;margin:4px 0"><input type="radio" name="phScope" value="rest"> shu va keyingi haftalar</label>' +
                        '<textarea data-ph-reason rows="2" maxlength="500" placeholder="Sabab (ixtiyoriy)" style="width:100%;border:1px solid #cbd5e1;border-radius:6px;padding:4px"></textarea>'
                        : '<p data-ph-why style="margin:6px 0;color:#b91c1c">' + esc((info && info.why) || 'Yozib bo\'lmaydi.') + '</p>') +
                    '<div data-ph-msg style="color:#b91c1c;margin-top:4px"></div>' +
                    '<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:8px"><button type="button" data-ph-cancel style="border:1px solid #cbd5e1;border-radius:6px;padding:2px 10px">Bekor</button>' +
                    (info && info.ok ? '<button type="button" data-ph-ok style="border-radius:6px;padding:2px 10px;background:#ca8a04;color:#fff">Yozish</button>' : '') + '</div></div>';
                document.body.appendChild(m);
                m.addEventListener('click', async ev => {
                    if (ev.target === m || (ev.target.closest && ev.target.closest('[data-ph-cancel]'))) { m.remove(); return; }
                    const ok = ev.target.closest && ev.target.closest('[data-ph-ok]');
                    if (!ok) return;
                    ok.disabled = true;
                    const scopeEl = m.querySelector('input[name="phScope"]:checked');
                    const reasonEl = m.querySelector('[data-ph-reason]');
                    try {
                        const res = await api(BASE + '/cards/' + c.id + '/mudir-placeholder', 'POST', { week: curWeek, scope: scopeEl ? scopeEl.value : 'one',
                            day: slot.day, pair: slot.pair, reason: reasonEl ? reasonEl.value : '' });
                        m.remove();
                        ttToast('<b>' + (typeof mudirNotifiedText === 'function' ? mudirNotifiedText(res) : 'Vaqtincha kafedra mudiriga yozildi') + '</b><div>' + esc(c.subject_name || '') + '</div>', 'ok');
                        mudirPick = null; selected = null;
                        closePanelCardPop();
                        await loadBoard(board.id);
                    } catch (e) { const t = m.querySelector('[data-ph-msg]'); if (t) t.textContent = e.message; ok.disabled = false; }
                });
                return m;
            }
            // Qaytarish: mode 'original' — mudirga yozilishidan oldingi holatiga (bandliksiz; joylanmagan edi — yana panelga), 'here' — shu joyda
            // asl o'qituvchi va xonaga (bandlik bilan). week — faqat shu hafta, bo'lmasa barcha haftalar.
            async function mudirPhRevert(c, btn, mode = 'original', week = null) {
                if (btn) btn.disabled = true;
                try {
                    const body = { mode };
                    if (week) body.week = week;
                    await api(BASE + '/cards/' + c.id + '/mudir-placeholder/revert', 'POST', body);
                    delete phRevertErr[unitKey(c)];
                    await loadBoard(board.id);
                } catch (e) {
                    phRevertErr[unitKey(c)] = (e.data && e.data.reasons) || [e.message];
                    if (btn) btn.disabled = false;
                    renderPanel();
                }
            }
            // Birlik mudirda qaysi haftalarda (yuklangan haftalik yozuvlardan).
            function mudirPhWeeks(c) {
                const ids = new Set(unitOf(c).map(x => x.id).concat([c.id]));
                const ws = new Set();
                Object.keys(overrides).forEach(k => {
                    const [id, w] = k.split('|').map(Number);
                    if (ids.has(id) && overrides[k] && overrides[k].mudir_placeholder) ws.add(w);
                });
                return [...ws].sort((a, b) => a - b);
            }
            // Xato — qizil "✖", uzun ro'yxat yig'ilgan: dastlabki 2 ta sabab va "yana N ta".
            function phErrHtml(err) {
                const list = (Array.isArray(err) ? err : [err]).filter(Boolean);
                if (!list.length) return '';
                const rest = list.slice(2);
                return '<div class="ph-err" style="color:#b91c1c;font-weight:600">✖ ' + list.slice(0, 2).map(esc).join(' · ') +
                    (rest.length ? ' <details style="display:inline"><summary style="display:inline;cursor:pointer;text-decoration:underline dotted">yana ' + rest.length + ' ta</summary>' +
                        rest.map(esc).join(' · ') + '</details>' : '') + '</div>';
            }
            // Bo'lim ro'yxati: shu haftada mudir belgili joylangan darslar (birlik bo'yicha bittadan) — panelning joylanmagan / to'qnashuvli
            // ro'yxatidan mustaqil, to'qnashuvsiz dars ham kiradi.
            function weeklyPhCards() {
                return curWeek && weeklyLayer === 'internal' ? [...new Map(weekActiveCards().filter(c => phOf(c) && effPlace(c))
                    .map(c => [unitKey(c), c])).values()] : [];
            }
            // Panel bo'limi: "Vaqtincha kafedra mudirida: N ta" — har birida "Asl o'qituvchiga qaytarish" (bandlik tekshiriladi).
            function mudirPhSectionHtml(list) {
                if (!list.length) return '';
                return '<div class="pn-mudir-ph" style="border:1px dashed #ca8a04;background:#fefce8;color:#713f12;border-radius:6px;padding:4px 6px;margin-bottom:6px;font-size:11px">' +
                    'Vaqtincha kafedra mudirida: <b>' + list.length + ' ta</b>' + list.map(c => {
                        const ph = phOf(c) || {};
                        const err = phRevertErr[unitKey(c)];
                        const weeks = mudirPhWeeks(c);
                        const weekSel = weeks.length > 1 ? ' <select data-ph-weeks="' + c.id + '" style="font-size:10px;border:1px solid #fcd34d;border-radius:4px">' +
                            '<option value="">barcha haftalar (' + weeks.length + ' ta)</option><option value="' + curWeek + '">faqat ' + curWeek + '-hafta</option></select>' : '';
                        return '<div class="pn-mudir-ph-item" data-ph-card="' + c.id + '" style="margin-top:3px;border-top:1px dotted #fde68a;padding-top:3px">' +
                            esc(cardGroups(c).join(', ') + ' · ' + c.subject_name) + ' <span style="color:#a16207">(asl o\'qituvchi: ' + esc(ph.orig_teacher_name || 'biriktirilmagan') + ')</span>' +
                            (weeks.length > 1 ? ' <span style="color:#a16207">· haftalar: ' + esc(weeks.join(', ')) + '</span>' : '') +
                            (mudirPhRevertAllowed() ? '<div style="margin-top:2px">' +
                                '<button type="button" data-ph-revert="' + c.id + '" data-ph-mode="original" title="Mudirga yozilishidan oldingi joy, o\'qituvchi va xona (bandlik tekshirilmaydi)" style="border:1px solid #16a34a;color:#166534;background:#f0fdf4;border-radius:4px;padding:0 5px">Asl holatga qaytarish</button> ' +
                                '<button type="button" data-ph-revert="' + c.id + '" data-ph-mode="here" title="Dars shu joyda qoladi — asl o\'qituvchi va xona (bandlik tekshiriladi)" style="border:1px solid #94a3b8;color:#334155;background:#fff;border-radius:4px;padding:0 5px">Shu joyda asl o\'qituvchiga</button>' +
                                weekSel + '</div>' : '') +
                            phErrHtml(err) + '</div>';
                    }).join('') + '</div>';
            }
            // ===== "Joylanmagan kartalar" paneli: qisman joylangan birlik belgisi, yaxlit joylash natijasi, karta oynasi =====
            const unitFixErr = {};   // birlik kaliti → oxirgi "yaxlit joylanmadi" sababi (kartada qizil izoh)
            const unitFixItems = {};   // birlik kaliti → tuzilgan sabablar (server conflict_items) — turlarga ajratilgan bloklar
            // Yaxlitlab bo'lmagan va shu hafta joylanmaganlarga o'tkazilgan birliklar: "doska|hafta|birlik" → {card_id, text, items}.
            // Panel tepasida xabar va "Joylash uchun tanlang"; birlik qayta joylansa yoki hafta / doska almashsa — ko'rinmaydi.
            const unitCleared = {};
            // Tasdiqqa yuborilgan unit-fix so'rovlari: "doska|hafta|birlik" → so'rov raqami (tasdiq rejimi: "tasdiq kutilmoqda", tugma o'chiq).
            // Boshqa hafta / doskada ko'rinmaydi; so'rov kutilayotganlar ro'yxatidan chiqsa (bekor qilindi, rad etildi, tasdiqlandi) — olinadi.
            const unitFixPending = {};
            const unitPendKey = c => (board ? board.id : 0) + '|' + curWeek + '|' + unitKey(c);
            function unitFixPendingSync() {
                const live = new Set(pendingReqs().map(r => +r.id));
                let gone = false;
                Object.keys(unitFixPending).forEach(k => { if (!live.has(+unitFixPending[k])) { delete unitFixPending[k]; gone = true; } });
                return gone;
            }
            const unitEditable = () => weeklyCanEdit() && !TIMETABLE_READ_ONLY && weeklyLayer === 'internal' && !!curWeek;
            // Fan mas'uli: mas'ul fani amaliy darsi (ichki jadval, shu hafta) — "Yaxlitlash", "Joylash uchun tanlang" (server ham tekshiradi).
            const fmUnitOk = c => TIMETABLE_ROLE === 'fan_masuli' && typeof fmCanPlace === 'function' && fmCanPlace(c);
            // Shu haftadagi bo'lingan birliklar (birlik kaliti → unitState + card): faqat amaliy, qamrovdagi (weekActiveCards).
            function weeklySplitUnits(uIdx = buildUnitIndex()) {
                const out = new Map();
                weekActiveCards().forEach(c => {
                    if (c.training_type === 'lecture' || out.has(unitKey(c))) return;
                    const st = unitState(c, curWeek, uIdx);
                    if (st.split) out.set(unitKey(c), Object.assign({ card: st.list[0] }, st));
                });
                return out;
            }
            // Panel bo'limi: "Bo'lingan: N ta" — har birida guruh · fan, soat (2+2+2), kunlar va "Yaxlitlash" (+ sig'masa — qizil sabab).
            function splitHeadHtml(units) {
                if (!units.size) return '';
                return '<div class="pn-split" data-pn-split style="border:1px solid #fca5a5;background:#fef2f2;color:#991b1b;border-radius:6px;padding:4px 6px;margin-bottom:6px;font-size:11px">' +
                    'Bo\'lingan: <b>' + units.size + ' ta</b> <span style="color:#b91c1c">(bir kunda bir fandan amaliy soatlar bo\'linmaydi)</span>' +
                    [...units.entries()].map(([k, st]) => {
                        const err = unitFixErr[k], errItems = unitFixItems[k], pend = unitFixPending[unitPendKey(st.card)];
                        return '<div class="pn-split-item" data-split-key="' + esc(k) + '" style="margin-top:3px;border-top:1px dotted #fecaca;padding-top:3px">' +
                            '<a href="#" data-split-go="' + esc(k) + '" style="text-decoration:underline dotted">' + esc(cardGroups(st.card).join(', ') + ' · ' + st.card.subject_name) + '</a>' +
                            ' — ' + st.len + ' soat (' + st.list.map(cardLen).join('+') + '): <span data-split-days>' + esc(unitDaysText(st.list)) + '</span>' +
                            (unitEditable() || fmUnitOk(st.card) ? ' <button type="button" data-unit-merge="' + esc(k) + '"' + (pend ? ' disabled' : '') + ' title="Bo\'laklar eng ko\'p soati turgan kunga ketma-ket (bandlik tekshiriladi)" style="border:1px solid #16a34a;color:#166534;background:#f0fdf4;border-radius:4px;padding:0 5px">Yaxlitlash</button>' : '') +
                            (pend ? ' <span data-unit-pending style="color:#b45309;font-weight:600">⏳ tasdiq kutilmoqda' + (pend > 0 ? ' (№' + esc(pend) + ')' : '') + '</span>' : '') +
                            (err ? (errItems && errItems.length
                                ? '<div class="pn-split-err" style="margin-top:2px">' + cbHtml(cbBlocks(errItems), false, { compact: true }) + '</div>'
                                : '<div class="pn-split-err" style="margin-top:2px;color:#b91c1c;font-weight:600">✖ ' + esc(err) + '</div>') : '') + '</div>';
                    }).join('') + '</div>';
            }
            // "Yaxlitlab bo'lmadi — d1/d26-03a joylanmaganlarga o'tkazildi (sabab: …). Joylash uchun tanlang." — shu hafta, joylanmagan birliklar.
            function unitClearedLive() {
                const pre = (board ? board.id : 0) + '|' + curWeek + '|';
                return Object.entries(unitCleared).filter(([k, v]) => {
                    if (!k.startsWith(pre)) return false;
                    const c = cards.find(x => x.id === +v.card_id);
                    return c && !unitOf(c, curWeek).some(x => placeInWeek(x, curWeek));
                });
            }
            function unitClearedHtml() {
                const live = unitClearedLive();
                if (!live.length) return '';
                return '<div data-pn-cleared style="border:1px solid #fcd34d;background:#fffbeb;color:#92400e;border-radius:6px;padding:4px 6px;margin-bottom:6px;font-size:11px">' +
                    live.map(([k, v]) => '<div data-cleared-key="' + esc(k) + '" style="margin-top:2px"><b>' + esc(v.text) + '</b> ' +
                        (unitEditable() || fmUnitOk(cards.find(x => x.id === +v.card_id)) ? '<button type="button" data-cleared-select="' + +v.card_id + '" style="border:1px solid #2563eb;color:#1d4ed8;background:#eff6ff;border-radius:4px;padding:0 5px">Joylash uchun tanlang</button>' : 'Joylash uchun tanlang.') +
                        (v.items && v.items.length ? '<div style="margin-top:2px">' + cbHtml(cbBlocks(v.items), false, { compact: true }) + '</div>' : '') +
                        '</div>').join('') + '</div>';
            }
            // "Bir kunga sig'maydi…" — sahifa ichidagi [Ha] / [Yo'q] oynasi (Esc, fon — Yo'q). Promise<boolean>.
            function ttYesNo(title, body) {
                return new Promise(resolve => {
                    const prior = document.getElementById('ttYesNo');
                    if (prior) prior.remove();
                    const m = document.createElement('div');
                    m.id = 'ttYesNo';
                    m.setAttribute('role', 'dialog');
                    m.setAttribute('aria-modal', 'true');
                    m.style.cssText = 'position:fixed;inset:0;z-index:85;background:rgba(15,23,42,.35);display:flex;align-items:center;justify-content:center;padding:16px';
                    m.innerHTML = '<div style="background:#fff;border-radius:10px;max-width:480px;width:100%;padding:12px 16px;box-shadow:0 20px 60px #0004;font-size:13px">' +
                        '<div data-yn-title style="font-weight:700;margin-bottom:6px">' + esc(title) + '</div>' +
                        (body ? '<div data-yn-body style="color:#991b1b;font-size:12px;white-space:pre-line;margin-bottom:8px">' + esc(body) + '</div>' : '') +
                        '<div style="display:flex;justify-content:flex-end;gap:8px"><button type="button" data-yn-no style="border:1px solid #94a3b8;border-radius:6px;padding:2px 12px">Yo\'q</button>' +
                        '<button type="button" data-yn-yes style="border:1px solid #d97706;color:#92400e;background:#fffbeb;border-radius:6px;padding:2px 12px;font-weight:600">Ha</button></div></div>';
                    const done = v => { m.remove(); document.removeEventListener('keydown', onKey, true); resolve(v); };
                    const onKey = e => { if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); done(false); } };
                    document.addEventListener('keydown', onKey, true);
                    m.addEventListener('click', ev => {
                        if (ev.target.closest('[data-yn-yes]')) done(true);
                        else if (ev.target === m || ev.target.closest('[data-yn-no]')) done(false);
                    });
                    document.body.appendChild(m);
                    const yes = m.querySelector('[data-yn-yes]');
                    if (yes && yes.focus) yes.focus();
                });
            }
            // "Qisman: 3 soatdan 2 soati joylangan (Seshanba 10:00); qolgani 1 soat" + shu birlik tugmalari (+ qizil izoh).
            function partialBadgeHtml(st, err) {
                const pend = unitFixPending[unitPendKey(st.card)];
                const placed = st.placed.slice().sort((a, b) => placeInWeek(a, curWeek).pair - placeInWeek(b, curWeek).pair);
                const at = placed.length ? placeInWeek(placed[0], curWeek) : null;
                const placedLen = unitLen(placed);
                const when = at ? ' (' + ((boardDayNames()[at.day - 1]) || (at.day + '-kun')) + ' ' + slotStart(at.pair) + ')' : '';
                return '<div class="pn-partial-badge" style="margin-top:3px;font-size:10px;color:#92400e;background:#fffbeb;border:1px solid #fcd34d;border-radius:4px;padding:2px 4px">' +
                    'Qisman: ' + st.len + ' soatdan ' + placedLen + ' soati joylangan' + esc(when) + '; qolgani ' + (st.len - placedLen) + ' soat' +
                    (unitEditable() ? '<div style="margin-top:2px"><button type="button" data-unit-fix="complete" data-unit-card="' + st.card.id + '"' + (pend ? ' disabled' : '') + ' style="border:1px solid #16a34a;color:#166534;background:#f0fdf4;border-radius:4px;padding:0 5px">yaxlit joylash</button> ' +
                        '<button type="button" data-unit-fix="clear" data-unit-card="' + st.card.id + '"' + (pend ? ' disabled' : '') + ' style="border:1px solid #d97706;color:#92400e;background:#fff;border-radius:4px;padding:0 5px">yaxlit bo\'shatish</button></div>' : '') +
                    (pend ? '<div data-unit-pending style="margin-top:2px;color:#b45309;font-weight:600">⏳ tasdiq kutilmoqda' + (pend > 0 ? ' (№' + esc(pend) + ')' : '') + '</div>' : '') +
                    (err ? '<div class="pn-partial-err" style="margin-top:2px;color:#b91c1c;font-weight:600">✖ ' + esc(err) + '</div>' : '') + '</div>';
            }
            // unit-fix: faqat berilgan birliklar (card_ids); natija — sahifa ichidagi oynada, sig'maganlari kartada qizil izoh bilan.
            async function runUnitFix(btn, action, units) {
                if (!units.length) return;
                if (action === 'clear' && !(await ttConfirm(units.length === 1
                    ? '«' + units[0].card.subject_name + '» (' + cardGroups(units[0].card).join(', ') + ') shu haftada butunlay joydan olinsinmi?'
                    : 'Qisman joylangan ' + units.length + ' ta dars shu haftada butunlay joydan olinsinmi?'))) return;
                if (btn) btn.disabled = true;
                let r;
                try {
                    r = await api(BASE + '/boards/' + board.id + '/unit-fix', 'POST', { week: curWeek, action, card_ids: units.flatMap(st => st.list.map(x => x.id)) });
                } catch (e) {
                    if (btn) btn.disabled = false;
                    // Sig'madi (422) — hech narsa o'zgarmadi: sababi tuzilgan bloklar bilan (failed + conflict_items).
                    if (e && e.data && Array.isArray(e.data.failed) && e.data.failed.length) r = e.data;
                    else { showUnitFixResult({ error: e.message }, action, units); return; }
                }
                // Yaxlitlab bo'lmadi (bitta birlik): tasdiq bilan — shu hafta jadvalidan olib, joylanmaganlarga o'tkazish (unplace_if_no_fit;
                // server qayta sinaydi — endi sig'sa, oddiy yaxlitlaydi). "Yo'q" — hozirgidek (sabab qatorda va natija oynasida).
                if (action === 'merge' && units.length === 1 && !(r && r.done) && r && r.failed && r.failed.length && !(r && r.pending_approval)) {
                    if (await ttYesNo('Bir kunga sig\'maydi. Darsni shu hafta jadvalidan olib, joylanmaganlarga o\'tkazaymi?', r.failed[0].error || '')) {
                        if (btn) btn.disabled = true;
                        try {
                            r = await api(BASE + '/boards/' + board.id + '/unit-fix', 'POST',
                                { week: curWeek, action, card_ids: units[0].list.map(x => x.id), unplace_if_no_fit: true });
                        } catch (e) {
                            if (btn) btn.disabled = false;
                            showUnitFixResult({ error: e.message }, action, units);
                            return;
                        }
                        delete unitFixErr[unitKey(units[0].card)]; delete unitFixItems[unitKey(units[0].card)];
                        (r && r.cleared || []).forEach(cl => {
                            unitCleared[unitPendKey(units[0].card)] = { card_id: units[0].list[0].id, text: cl.text,
                                items: Array.isArray(cl.conflict_items) ? cl.conflict_items : [] };
                        });
                        await loadBoard(board.id);
                        if (r && r.cleared && r.cleared.length) ttToast(esc(r.message || r.cleared[0].text), 'warn');
                        else showUnitFixResult(r || {}, action, units);
                        return;
                    }
                }
                units.forEach(st => { delete unitFixErr[unitKey(st.card)]; delete unitFixItems[unitKey(st.card)]; });
                // Tasdiq rejimi (so'rov yuborildi): "Yaxlitlandi: 0 ta" emas — qatorda "tasdiq kutilmoqda", tugma o'chiq (onPendingApproval —
                // xabar va so'rovlar ro'yxati).
                if (r && r.pending_approval) {
                    units.forEach(st => { unitFixPending[unitPendKey(st.card)] = +r.change_request_id || -1; });
                    if (btn) btn.disabled = true;
                    renderPanel();
                    return;
                }
                (r && r.failed || []).forEach(f => {
                    const st = units.find(u => u.list.some(x => (f.card_ids || []).includes(x.id)));
                    if (st) { unitFixErr[unitKey(st.card)] = f.error; unitFixItems[unitKey(st.card)] = Array.isArray(f.conflict_items) ? f.conflict_items : null; }
                });
                await loadBoard(board.id);
                showUnitFixResult(r || {}, action, units);
            }
            // Sahifa ichidagi natija oynasi (alert emas): bajarilganlar soni va har sig'magan karta — sababi bilan.
            function showUnitFixResult(r, action, units) {
                let m = document.getElementById('ttUnitFixModal');
                if (m) m.remove();
                m = document.createElement('div');
                m.id = 'ttUnitFixModal';
                m.setAttribute('role', 'dialog');
                m.style.cssText = 'position:fixed;inset:0;z-index:80;background:rgba(15,23,42,.35);display:flex;align-items:center;justify-content:center;padding:16px';
                const failed = (r && r.failed) || [];
                const head = r.error && !failed.length ? 'Xatolik: ' + r.error
                    : action === 'merge' ? (failed.length ? 'Yaxlitlab bo\'lmadi — hech narsa o\'zgarmadi' : (r.message || 'Yaxlitlandi: ' + (r.done || 0) + ' ta'))
                    : (action === 'clear' ? 'Yaxlit bo\'shatildi: ' : 'Yaxlit joylandi: ') + (r.done || 0) + ' ta' + (failed.length ? ' · joylanmadi: ' + failed.length + ' ta' : '');
                m.innerHTML = '<div style="background:#fff;border-radius:10px;max-width:560px;width:100%;max-height:80vh;overflow:auto;padding:12px 16px;box-shadow:0 20px 60px #0004;font-size:12px">' +
                    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><b>' + esc(head) + '</b>' +
                    '<button type="button" data-close style="font-size:18px;line-height:1">&times;</button></div>' +
                    (failed.length ? '<div style="color:#991b1b;margin-bottom:4px">' + (action === 'merge' ? 'Sababi:' : 'Yaxlit joylanmadi:') + '</div><ul style="margin:0;padding-left:16px">' + failed.map(f =>
                        '<li><b>' + esc(f.group + ' · ' + f.subject) + '</b> (' + esc(f.day || '') + '): ' + esc(f.error) + '</li>').join('') + '</ul>' : '') + '</div>';
                m.addEventListener('click', ev => { if (ev.target === m || ev.target.closest('[data-close]')) m.remove(); });
                document.body.appendChild(m);
            }
            // Tasdiq (sahifa ichida emas — oddiy confirm; testlarda almashtiriladi).
            const ttConfirm = async text => (typeof confirm === 'function' ? confirm(text) : true);
            // W-haftaning d-kuni sanasi (YYYY-MM-DD); d berilmasa — dushanba.
            function weekDayIso(W, d) {
                const m = weekMonday(W);
                if (!m) return null;
                const x = new Date(m); x.setDate(x.getDate() + Math.max(0, (d || 1) - 1));
                return x.getFullYear() + '-' + String(x.getMonth() + 1).padStart(2, '0') + '-' + String(x.getDate()).padStart(2, '0');
            }
            // Qatorning para nomi: "II para" (qo'ng'iroq jadvali abbr), ikkinchi yarmi — "(2-yarmi)".
            // Joylangan kartaning joyi (tanlangan hafta): "Chorshanba I–II para" — boshlanish va oxirgi qatorning para nomi.
            function placedSlotText(c) {
                const pl = effPlace(c);
                if (!pl) return '';
                const sched = boardSchedule().filter(it => it.type === 'pair');
                const ab = p => { const it = sched[p - 1]; const a = it && String(it.abbr || '').trim(); return a && a !== '—' ? a : String(p); };
                const a = ab(+pl.pair), b = ab(+pl.pair + Math.max(1, +c.len_half || 1) - 1);
                return (boardDayNames()[+pl.day - 1] || (pl.day + '-kun')) + ' ' + (a === b ? a : a + '–' + b) + ' para';
            }
            function slotParaLabel(p) {
                const sched = boardSchedule().filter(it => it.type === 'pair');
                const it = sched[p - 1];
                const ab = it && String(it.abbr || '').trim();
                if (!ab || ab === '—') return (it && it.name) || (p + '-katak');
                const second = p > 1 && sched[p - 2] && String(sched[p - 2].abbr || '').trim() === ab;
                return ab + ' para' + (second ? ' (2-yarmi)' : '');
            }
            // Xona sig'imi matni: "Tibbiyot klasteri, 1-qavat, 12-o'quv xona · 10 o'rin · 15 talaba (+5)".
            function roomCapLine(c) {
                if (isNonBlocking(c)) return infoOnlyText(c) + ": xona sig‘imi tekshirilmaydi";
                const e = effectiveCard(c);
                if (!e.auditorium_code && !e.auditorium_name) return '';
                const vol = +e.auditorium_volume || +((audCache || []).find(a => a.code === e.auditorium_code) || {}).volume || 0;
                const st = +c.students || 0;
                return (e.auditorium_name || e.auditorium_code) + (vol ? " · " + vol + " o'rin" : '') + (st ? ' · ' + st + ' talaba' + (vol && st > vol ? ' (+' + (st - vol) + ')' : '') : '');
            }
            // Panel kartasi oynasi: o'qituvchi (to'liq F.I.Sh. → kun/hafta jadvali, shu karta ko'chiriladigan dars), xona (sig'imi →
            // xona bandligi), tashqi jadval joyi (→ ichki jadvalda shu joy; "Shu joyga joylash"), "Joylash uchun tanlash".
            // Tahrir huquqi yo'q — faqat ko'rish (havolalar ishlaydi). O'qituvchi roli — vaqt so'rovi tugmasi.
            function openPanelCardPop(c, el, opts = {}) {
                closePanelCardPop();
                const W = curWeek || 0;
                const list = c.training_type === 'lecture' ? [c] : unitOf(c);
                const len = unitLen(list);
                const tName = c.teacher_id ? (teacherFullNames[c.teacher_id] || c.teacher_name || '') : '';
                const agendaDate = weekDayIso(W || 1, c.ext_day || 1) || new Date().toISOString().slice(0, 10);
                const tInfo = c.teacher_id ? { teacher_id: +c.teacher_id, teacher_name: c.teacher_name || tName, date: agendaDate, range: 'week',
                    move: W && weeklyLayer === 'internal' ? 'w|' + c.id + '|' + W : null } : null;
                const e = effectiveCard(c);
                const room = roomCapLine(c);
                const rInfo = e.auditorium_code ? { room_code: e.auditorium_code, room_name: e.auditorium_name || e.auditorium_code, date: agendaDate, range: 'week' } : null;
                const ext = c.ext_day && c.ext_pair ? { day: +c.ext_day, pair: +c.ext_pair } : null;
                const placed = effPlace(c);
                const extText = ext ? (boardDayNames()[ext.day - 1] || (ext.day + '-kun')) + ', ' + slotParaLabel(ext.pair) + ' (' + slotRangeText(ext.pair, len) + ')' : '';
                const edit = weeklyCanEdit() && !TIMETABLE_READ_ONLY && TIMETABLE_ROLE !== 'oqituvchi';
                // Fan mas'uli — mas'ul fani amaliy darsi (ichki jadval, shu hafta): joylash funksiyalari (o'qituvchi biriktirish va "Vaqtincha
                // kafedra mudiriga yozish"siz). Yozish — responsible-move (darhol tuzatish yoki so'rov — server aniqlaydi), "Joylash uchun
                // tanlash" — fmPick (server kataklari), xonalar — room-options.
                const fmEdit = TIMETABLE_ROLE === 'fan_masuli' && typeof fmCanPlace === 'function' && fmCanPlace(c);
                // "Shu joyga joylash": admin, superadmin, registrator ofisi, kichik admin, kafedra mudiri — ichki jadvalda bir xil. Ko'rinmasa
                // (joylanmagan darsda) — sababi kichik matnda; joylangan (to'qnashuvdagi) darsda tugma yo'q (allaqachon joyida).
                // Ichki jadvalni tahrirlay oladimi (tashqi qatlam ochiq bo'lsa ham — sababi "Ichki'ga o'ting" ko'rinsin).
                const internalEditor = fmEdit || (weeklyLayer === 'internal' ? edit : !TIMETABLE_READ_ONLY && (WEEKLY_ADMIN || TIMETABLE_ROLE === 'kafedra_mudiri'));
                const canPlaceHere = !placed && (edit || fmEdit) && ext && W && weeklyLayer === 'internal';
                const placeWhy = placed || canPlaceHere || !internalEditor ? ''
                    : weeklyLayer !== 'internal' ? "Tashqi jadval tanlangan — Ichki'ga o'ting"
                    : !W ? 'Hafta tanlanmagan'
                    : !ext ? "Tashqi jadvalda joyi yo'q — 'Joylash uchun tanlash'dan foydalaning" : '';
                const pop = document.createElement('div');
                pop.id = 'pnCardPop';
                pop.setAttribute('role', 'dialog');
                // Balandligi ekrandan oshmaydi (ichida scroll), sarlavha (fan nomi, ×) yuqorida yopishib turadi.
                pop.style.cssText = 'position:fixed;z-index:75;background:#fff;border:1px solid #cbd5e1;border-radius:8px;box-shadow:0 10px 30px #0003;padding:0 10px 8px;font-size:12px;'
                    + 'width:min(340px,92vw);max-height:calc(100vh - 16px);overflow-y:auto;box-sizing:border-box';
                const row = (label, body) => '<div style="margin-top:4px"><span style="color:#64748b">' + label + ':</span> ' + body + '</div>';
                const link = (attr, text) => '<a href="#" class="tt-agenda-link" ' + attr + '>' + esc(text) + '</a>';
                pop.innerHTML = '<div class="pn-pop-head" style="position:sticky;top:0;z-index:1;background:#fff;display:flex;justify-content:space-between;gap:6px;padding-top:8px;padding-bottom:2px"><b>' + esc(c.subject_name) + '</b>' +
                    '<button type="button" data-pop-close aria-label="Yopish" style="font-size:16px;line-height:1">&times;</button></div>' +
                    '<div style="color:#64748b"' + (c.training_type === 'lecture' ? ' title="' + esc(lectureLabel(c.oqim_label, cardGroups(c)).title) + '"' : '') + '>'
                        + esc((c.training_type === 'lecture' ? lectureLabel(c.oqim_label, cardGroups(c)).text : 'Amaliy · ' + cardGroups(c).join(', ')) +
                        (len ? ' · ' + len + ' soat' : '')) + '</div>' +
                    row("O'qituvchi", tInfo ? link('data-pop-teacher title="' + esc((tName || '') + (teacherPhones[c.teacher_id] ? ' · ' + teacherPhones[c.teacher_id].text : '')) + '"',
                        tName || c.teacher_name || "O'qituvchi") + (teacherPhones[c.teacher_id]
                        ? ' <a href="tel:' + esc(teacherPhones[c.teacher_id].tel) + '" style="color:#475569">· ' + esc(teacherPhones[c.teacher_id].text) + '</a>' : '')
                        : '<i>biriktirilmagan</i>') +
                    row('Xona', rInfo ? link('data-pop-room', room) + (roomInactive(e.auditorium_code)
                        ? ' <span data-pop-room-off style="color:#b91c1c;font-weight:600">(nofaol) — ' + esc(ROOM_OFF_TEXT) + '</span>' : '') : '<i>biriktirilmagan</i>') +
                    (placed ? row('Joyi', '<b data-pop-placed>' + esc(placedSlotText(c)) + '</b> <span style="color:#b45309">· to\'qnashuv</span>') : '') +
                    row('Tashqi jadval', ext ? link('data-pop-ext', extText) : '<i>tashqi jadvalda yo\'q</i>') +
                    // Joylangan, to'qnashuvdagi dars — sabab turlarga ajratilgan bloklarda (ochilganda); rad etilgan joylash — data-pop-msg da.
                    '<div data-pop-cf style="margin-top:4px"></div>' +
                    '<div data-pop-msg style="margin-top:4px"></div>' +
                    '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:6px">' +
                    // Joylangan (to'qnashuvli) karta — "Jadvalda ko'rsatish"; joylanmagan — "Shu joyga joylash" (tashqi joyiga).
                    (placed ? '<button type="button" data-pop-show style="border:1px solid #0f766e;color:#115e59;background:#f0fdfa;border-radius:5px;padding:1px 8px">Jadvalda ko\'rsatish</button>' : '') +
                    (canPlaceHere ? '<button type="button" data-pop-place style="border:1px solid #16a34a;color:#166534;background:#f0fdf4;border-radius:5px;padding:1px 8px">Shu joyga joylash</button>' : '') +
                    (edit || fmEdit ? '<button type="button" data-pop-select style="border:1px solid #2563eb;color:#1d4ed8;background:#eff6ff;border-radius:5px;padding:1px 8px">Joylash uchun tanlash</button>' : '') +
                    (mudirPhAllowed() && !phOf(c) ? '<button type="button" data-pop-mudir disabled title="tekshirilmoqda…" style="border:1px solid #ca8a04;color:#854d0e;background:#fefce8;border-radius:5px;padding:1px 8px">Vaqtincha kafedra mudiriga yozish</button>' : '') +
                    '<div data-pop-mudir-why style="width:100%;color:#a16207;font-size:11px"></div>' +
                    (placeWhy ? '<div data-pop-place-why style="width:100%;color:#64748b;font-size:11px">' + esc(placeWhy) + '</div>' : '') +
                    (TIMETABLE_ROLE === 'oqituvchi' ? '<button type="button" data-pop-propose style="border:1px solid #7c3aed;color:#6d28d9;background:#f5f3ff;border-radius:5px;padding:1px 8px">Vaqtini o\'zgartirishni so\'rash</button>' : '') +
                    '</div>';
                document.body.appendChild(pop);
                // Joylashuv — har kontent o'zgarishida (kech kelgan "Band: …", yana N ta), oyna o'lchami va scroll'da qayta hisoblanadi.
                const reposition = () => panelPopPlace(pop, el);
                panelPopState = { pop, reposition, ro: null };
                if (typeof ResizeObserver === 'function') { panelPopState.ro = new ResizeObserver(reposition); panelPopState.ro.observe(pop); }
                window.addEventListener('resize', reposition);
                window.addEventListener('scroll', reposition, true);
                reposition();
                // To'qnashuv sababi bloklari (cbRender): yechimlar — boshqa xona (faqat xona band), vaqtincha kafedra mudiri (o'qituvchi band),
                // joylash uchun tanlash (har doim, tahrir huquqi bo'lsa).
                const ids = list.map(x => x.id);
                const cbCtx = (d, p, isPlaced, roomCard = list[0]) => ({ card: c, list, ids, day: d, pair: p, len, placed: isPlaced, close: closePanelCardPop, reposition,
                    solutions: {
                        // Boshqa xona: kun va para — bitta bo'lakdan (joylangan darsda — bosilgan kartaning o'z joyi). Bo'lingan (turli kunda / oraliq bilan)
                        // joylangan darsda yo'q: xona almashtirish butun birlikni qayta joylaydi — avval "Yaxlitlash".
                        room: edit && W && weeklyLayer === 'internal' && !(isPlaced && unitIsSplit(list)) ? () => {
                            closePanelCardPop();
                            const at = isPlaced ? effPlace(roomCard) : null;
                            openPlaceRoomPick(roomCard, at ? at.day : d, at ? at.pair : p);
                        } : null,
                        // "Boshqa xona tanlash" — "Xona band" blokida (boshqa sabablar bilan birga ham): xonalar ro'yxati (server), tanlangach qayta
                        // tekshiruv va joylash / shu hafta xonani almashtirish (placeCardWithRoom: birlik — unit-place, yakka — week-override).
                        roomPick: (edit || fmEdit) && W && weeklyLayer === 'internal' && !(isPlaced && unitIsSplit(list)) ? (() => {
                            const at = isPlaced ? effPlace(roomCard) : null;
                            const day = at ? at.day : d, pair = at ? at.pair : p;
                            // Xonalar ro'yxati — birlik boshidan (bosilgan bo'lak keyingisi bo'lsa ham): placeCardWithRoom (unitMovePlan) bilan bir xil.
                            const plan = unitMovePlan(roomCard, pair);
                            return { card: roomCard, day, pair: plan ? plan[0][1] : pair, placed: !!isPlaced, apply: async room => {
                                if (fmEdit) {
                                    // Fan mas'uli: responsible-move (joylanmagan / to'qnashuvdagi dars — darhol; aks holda server rad etadi).
                                    await api(BASE + '/cards/' + roomCard.id + '/responsible-move', 'POST',
                                        { week: curWeek, day, pair: plan ? plan[0][1] : pair, auditorium_code: room.code });
                                    closePanelCardPop();
                                    if (typeof fmGridCache !== 'undefined') fmGridCache.clear();
                                    await loadBoard(board.id);
                                    ttToast(esc((isPlaced ? 'Xona almashtirildi (shu hafta): ' : 'Joylandi: ') + (room.name || room.code)), 'ok');
                                    return;
                                }
                                const r = await placeCardWithRoom(roomCard, day, pair, room);
                                closePanelCardPop();
                                selected = null;
                                renderAll();
                                if (!(r && r.pending_approval)) ttToast(esc((isPlaced ? 'Xona almashtirildi (shu hafta): ' : 'Joylandi: ') + (room.name || room.code)), 'ok');
                            } };
                        })() : null,
                        // "Joylash uchun tanlash" va "Vaqtincha kafedra mudiriga yozish" — oynada bittadan (pastki qatorda); yechimlarda takrorlanmaydi.
                    } });
                if (placed && W && weeklyLayer === 'internal') {
                    // Joylangan, to'qnashuvdagi dars: sabablar — server yozuvlaridan (butun doska; belgi ham shulardan — ko'rish qamrovidan tashqaridagi
                    // dars bilan to'qnashuv ham ko'rinadi); yuklanmagan / bo'sh bo'lsa — front tekshiruvi (har bo'lak o'z joyida). Xona sig'imi — alohida.
                    const srv = weeklyConflictItems.__week === curWeek
                        ? list.flatMap(x => (((weeklyConflictItems[x.id] || {})[curWeek]) || []).map(i => cbItemFromServer(i, x)).filter(Boolean)) : [];
                    const front = list.flatMap(x => {
                        const at = effPlace(x);
                        return at ? conflictsAtDetail(x, at.day, at.pair, ids).map(k => cbItemFromDetail(k, x, at.day, at.pair)).filter(Boolean) : [];
                    });
                    const cfItems = (srv.length ? srv : front).concat([cbCapItem(c)].filter(Boolean));
                    const first = effPlace(list[0]) || placed;
                    cbRender(pop.querySelector('[data-pop-cf]'), cfItems, cbCtx(first.day, first.pair, true, c));
                    // To'qnashuv belgisidan ochilgan: bloklar [Ko'rsatish] bilan ochiq.
                    if (opts.cfOpen) pop.querySelectorAll('[data-pop-cf] [data-cb-show]').forEach(a => a.click());
                }
                // Rad etilgan joylash: sabab bloklari (front oldindan tekshiruvi yoki server conflict_items — bir xil shakl).
                const showBlocks = items => {
                    const m = pop.querySelector('[data-pop-msg]');
                    if (!m) return;
                    m.style.color = '';
                    cbRender(m, items, cbCtx(ext.day, ext.pair, false));
                };
                // Xabar: sarlavha va ro'yxat (takrorlar olib tashlanadi, hammasi ko'rinadi).
                const msg = (text, bad, items) => {
                    const m = pop.querySelector('[data-pop-msg]');
                    if (!m) return;
                    m.style.color = bad ? '#b91c1c' : '#166534';
                    m.innerHTML = panelPopMsgHtml(text, items || []);
                    const more = m.querySelector('[data-pop-more]');
                    if (more) more.onclick = ev => {
                        ev.preventDefault(); ev.stopPropagation();
                        const open = m.querySelector('[data-pop-rest]').hidden;
                        m.querySelector('[data-pop-rest]').hidden = !open;
                        more.textContent = open ? 'yig\'ish ▴' : more.dataset.label;
                        reposition();
                    };
                    reposition();
                };
                pop.addEventListener('click', async ev => {
                    const t = ev.target.closest ? ev.target.closest('[data-pop-close],[data-pop-teacher],[data-pop-room],[data-pop-ext],[data-pop-show],[data-pop-place],[data-pop-select],[data-pop-propose],[data-pop-mudir]') : null;
                    if (!t) return;
                    ev.preventDefault();
                    ev.stopPropagation();
                    if (t.hasAttribute('data-pop-close')) { closePanelCardPop(); return; }
                    if (t.hasAttribute('data-pop-teacher')) { closePanelCardPop(); ttAgendaOpen(tInfo); return; }
                    if (t.hasAttribute('data-pop-room')) { closePanelCardPop(); ttAgendaOpen(rInfo); return; }
                    if (t.hasAttribute('data-pop-ext')) { gotoGridSlot(c, ext.day, ext.pair); return; }
                    if (t.hasAttribute('data-pop-show')) { closePanelCardPop(); gotoGridSlot(c, placed.day, placed.pair); return; }
                    if (t.hasAttribute('data-pop-propose')) { closePanelCardPop(); openTeacherTimeProposal(c); return; }
                    if (t.hasAttribute('data-pop-mudir')) { if (!t.disabled) openMudirPhConfirm(c, mudirPhSlot(c)); return; }
                    if (t.hasAttribute('data-pop-select')) {
                        closePanelCardPop();
                        // Fan mas'uli — o'z "Joylash uchun tanlash" rejimi (guruh ustuni belgilanadi, jadval suriladi; kataklar serverdan).
                        if (fmEdit) { fmPickStart(c); return; }
                        selected = (selected && selected.id === c.id) ? null : c;
                        renderPanel(); renderGrid();
                        // Guruh ustuni belgilanadi (renderGrid → markPickColumns) va jadval shu ustunga suriladi.
                        if (selected) scrollToPickColumn(selected);
                        return;
                    }
                    // Shu joyga joylash: oldindan tekshiruv (birlik bilan), keyin server (unit-place) — band bo'lsa sababi turlarga ajratilgan
                    // bloklarda (xona sig'imi — ogohlantirish, joylashga to'sqinlik qilmaydi).
                    const pre = cbPlanItems(list, ext.day, ext.pair);
                    if (cbBlocking(cbBlocks(pre)).length) { showBlocks(pre); return; }
                    // Fan mas'uli: tasdiq oynasi (xona, darhol / so'rov — responsible-move check), shu joyga.
                    if (fmEdit) { closePanelCardPop(); openResponsibleMove(list[0], { pick: true, day: ext.day, pair: ext.pair, anchor: el }); return; }
                    t.disabled = true;
                    try {
                        await placeUnitAt(list[0], ext.day, ext.pair);
                        closePanelCardPop();
                        selected = null;
                        renderAll();
                        gotoGridSlot(c, ext.day, ext.pair);
                    } catch (err) {
                        const ci = err && err.data && err.data.conflict_items;
                        if (Array.isArray(ci) && ci.length) showBlocks(ci);
                        else { const pe = panelPopSplitError(err.message); msg(pe.title, true, pe.items); }
                        t.disabled = false;
                    }
                });
                // Tugma holati (kech keladi): mudir / xona topilmasa — o'chiq, sababi bilan; tashqi joyi yo'q — katak tanlanadi.
                if (pop.querySelector('[data-pop-mudir]')) {
                    mudirPhInfo(c, mudirPhSlot(c)).then(info => {
                        const btn = pop.querySelector('[data-pop-mudir]');
                        const why = pop.querySelector('[data-pop-mudir-why]');
                        if (!btn) return;
                        const usable = info.ok || (!info.slot && info.mudir && info.room);
                        btn.disabled = !usable;
                        btn.title = usable ? (info.mudir ? 'Kafedra mudiri: ' + info.mudir.name : '') : (info.why || '');
                        if (!usable && why) why.textContent = info.why || '';
                        if (usable && !info.slot && why) why.textContent = 'Tashqi jadvalda joyi yo\'q — tugmani bosib, jadvaldan katak tanlang.';
                        reposition();
                    }).catch(e => { const btn = pop.querySelector('[data-pop-mudir]'); if (btn) { btn.disabled = true; btn.title = e.message; } });
                }
                setTimeout(() => document.addEventListener('mousedown', panelPopOutside, true), 0);
                document.addEventListener('keydown', panelPopKey, true);
            }
            let panelPopState = null;   // { pop, reposition, ro } — ochiq oyna (yopilganda tinglovchilar olinadi)
            // Oyna joyi: kartaning o'ng tomoni (sig'masa — chap, yana sig'masa — ekran ichiga siqiladi); vertikal — karta tepasidan pastga,
            // pastda joy yetmasa — kartaning ustiga (pastki cheti karta pastida), so'ng ekran ichiga: clamp(8, top, innerHeight − h − 8).
            function panelPopPlace(pop, el) {
                if (!pop || !pop.style) return;
                const W = window.innerWidth || 1024, H = window.innerHeight || 768;
                const w = pop.offsetWidth || 340, h = Math.min(pop.offsetHeight || 220, H - 16);
                const r = el && el.getBoundingClientRect && el.isConnected !== false ? el.getBoundingClientRect() : panelPopPlace.last || { left: 8, right: 8, top: 8, bottom: 8 };
                panelPopPlace.last = r;
                const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
                let left = r.right + 8;
                if (left + w > W - 8) left = r.left - w - 8 >= 8 ? r.left - w - 8 : clamp(r.left, 8, W - w - 8);
                let top = r.top;
                if (top + h > H - 8) top = (r.bottom || r.top) - h;   // pastda joy yo'q — yuqoriga ochiladi
                pop.style.left = Math.round(clamp(left, 8, Math.max(8, W - w - 8))) + 'px';
                pop.style.top = Math.round(clamp(top, 8, Math.max(8, H - h - 8))) + 'px';
            }
            // Server xatosi ("4 soat sig'maydi: 13:30 dan keyin 2 soat bo'sh — A · B · …") → sarlavha va sabablar ro'yxati.
            function panelPopSplitError(text) {
                const parts = String(text || '').split(' · ');
                let title = 'Band:';
                const m = /^(.*?sig'maydi:[^—]*?) — (.*)$/.exec(parts[0]);
                if (m) { title = m[1]; parts[0] = m[2]; } else if (parts.length === 1 && !/band/i.test(parts[0])) return { title: parts[0], items: [] };
                return { title, items: parts };
            }
            // Sabablar — hammasi (takrorlarsiz), "yana N ta" ostiga yashirilmaydi.
            function panelPopMsgHtml(title, items) {
                const uniq = [...new Set((items || []).map(x => String(x).trim()).filter(Boolean))];
                return '<div>' + esc(title) + '</div>' + (uniq.length ? '<ul style="margin:2px 0 0;padding-left:16px">' + uniq.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>' : '');
            }
            // ===== To'qnashuv sababi: turlarga ajratilgan bloklar, "Ko'rsatish" (oynaning o'zida), yechimlar =====
            // Sabab yozuvi — front oldindan tekshiruvi (conflictsAtDetail) va server javobi (422 conflict_items) bir xil shaklda: {kind: room |
            // teacher | group | capacity | day_end, who, card_id (band qilgan dars), piece_id, groups, subject, training_type, teacher, teacher_id,
            // room_name, room_code, date, time, day, pair}. Matn parse qilinmaydi.
            const CB_ORDER = ['teacher', 'group', 'room', 'day_end', 'capacity'];
            const CB_HEAD = { teacher: "O'qituvchi band", group: 'Guruh band', room: 'Xona band', day_end: 'Kun oxiri', capacity: "Xona sig'maydi" };
            const CB_SHORT = { teacher: "o'qituvchi band", group: 'guruh band', room: 'xona band', day_end: 'kun oxirigacha joy yetmaydi' };
            function cbItemFromDetail(x, piece, d, at, W = curWeek) {
                const o = x && x.cardId ? cards.find(k => k.id === x.cardId) : null;
                if (!o) return null;
                const eo = effectiveCard(o), pl = effPlace(o);
                return { kind: x.kind, who: x.who != null ? String(x.who) : '', card_id: o.id, piece_id: piece.id, groups: cardGroups(o), subject: o.subject_name,
                    training_type: o.training_type, teacher: o.teacher_name || '', teacher_id: +o.teacher_id || null,
                    room_name: eo.auditorium_name || eo.auditorium_code || '', room_code: eo.auditorium_code || '', date: weekDayIso(W, d),
                    time: pl ? slotRangeText(pl.pair, cardLen(o)) : '', day: d, pair: pl ? pl.pair : at, piece_pair: at };
            }
            // Server to'qnashuv yozuvi (weeklyConflictItems — butun doska bo'yicha, ko'rish qamrovidan qat'i nazar) → sabab: band qilgan dars
            // ma'lumoti — barcha yuklangan kartalardan (allCards), topilmasa yozuvning o'zidan; fokus — yozuvning show'i.
            // Band qilgan darsning vaqti va xonasi — to'qnashuv sanasidagi o'z haftasi bo'yicha (with_week/with_day/with_pair/with_room: boshqa
            // kalendarli dasturda hafta raqami boshqa), tanlangan hafta (curWeek) bo'yicha emas.
            function cbItemFromServer(i, piece) {
                const kind = { teacher_busy: 'teacher', room_busy: 'room', group_busy: 'group' }[i && i.kind];
                if (!kind) return null;
                const o = (typeof allCards !== 'undefined' && allCards || []).find(x => +x.id === +i.with_card) || (cards || []).find(x => +x.id === +i.with_card) || null;
                const W = +i.with_week || curWeek, ov = o && W ? overrides[o.id + '|' + W] : null;
                const pl = +i.with_pair ? { day: +i.with_day, pair: +i.with_pair } : (o ? placeInWeek(o, W) : null);
                const ovRoom = ov && !ov.cancelled && ov.auditorium_code ? ov : null;
                const oRoomCode = i.with_room || (ovRoom ? ovRoom.auditorium_code : o ? o.auditorium_code || '' : '');
                const oRoomName = i.with_room_name || (ovRoom ? ovRoom.auditorium_name || ovRoom.auditorium_code : o ? o.auditorium_name || o.auditorium_code || '' : '');
                const date = i.date_from || ((i.show || {}).dates || [])[0] || '';
                const mineG = cardGroups(piece), overlap = (i.groups || []).filter(g => mineG.includes(g));
                return { kind, who: kind === 'teacher' ? (i.teacher_name || piece.teacher_name || '') : kind === 'room' ? (i.room_name || i.room || '')
                        : (overlap.length ? overlap : (i.groups || [])).join(','),
                    card_id: +i.with_card || null, piece_id: piece.id, groups: o ? cardGroups(o) : (i.groups || []), subject: o ? o.subject_name : '',
                    training_type: o ? o.training_type : '', teacher: o ? (o.teacher_name || '') : '', teacher_id: +(i.teacher_id || (o && o.teacher_id)) || null,
                    room_name: oRoomName || i.room_name || i.room || '', room_code: i.room || oRoomCode || '',
                    date, day: date ? ((new Date(date + 'T00:00:00').getDay() + 6) % 7) + 1 : 0, time: pl && o ? slotRangeText(pl.pair, cardLen(o)) : '',
                    pair: pl ? pl.pair : 0, piece_pair: +((i.show || {}).hour_from) || ((effPlace(piece) || {}).pair) || 0, show: i.show || null };
            }
            // Xona sig'imi (ogohlantirish, rad sababi emas): shu haftadagi xona sig'imi talabalar sonidan kam.
            function cbCapItem(c) {
                if (!c || isNonBlocking(c)) return null;
                const e = effectiveCard(c);
                const vol = +e.auditorium_volume || +((audCache || []).find(a => a.code === e.auditorium_code) || {}).volume || 0;
                const st = +c.students || 0;
                if (!vol || !st || st <= vol || isSharedRoomName(e.auditorium_name)) return null;
                return { kind: 'capacity', who: e.auditorium_name || e.auditorium_code || '', room_code: e.auditorium_code || '', volume: vol, students: st, over: st - vol, blocking: false };
            }
            // Birlikni (d, start) dan joylash sabablari: har bo'lak o'z joyida (birlikning o'z bo'laklari hisobga olinmaydi), kun oxiri, xona sig'imi.
            function cbPlanItems(list, d, start, W = curWeek) {
                const mine = list.map(x => x.id);
                const items = [];
                let at = start;
                list.forEach(x => {
                    conflictsAtDetail(x, d, at, mine).forEach(k => { const it = cbItemFromDetail(k, x, d, at, W); if (it) items.push(it); });
                    at += cardLen(x);
                });
                const maxRow = boardSchedule().filter(it => it.type === 'pair').length || 12;
                const len = unitLen(list);
                if (start < 1 || start + len - 1 > maxRow) items.push({ kind: 'day_end', who: '', hours: len, free: Math.max(0, maxRow - start + 1), from: slotStart(start) });
                const cap = cbCapItem(list[0]);
                if (cap) items.push(cap);
                return items;
            }
            // Bloklar: tur + kim + kun bo'yicha (bitta dars ikki turda band qilsa — har blokda o'z sababi bilan; bo'lingan darsda bir o'qituvchi /
            // xona bilan turli kunlardagi to'qnashuv — har kun alohida blok, "Ko'rsatish" o'sha kuniniki), tartib — CB_ORDER, keyin sana.
            function cbBlocks(items) {
                const m = new Map();
                (items || []).forEach(it => {
                    if (!it || !CB_HEAD[it.kind]) return;
                    const k = it.kind + '|' + (it.who || '') + '|' + (it.date || '');
                    if (!m.has(k)) m.set(k, { kind: it.kind, who: it.who || '', date: it.date || '', day: +it.day || 0, items: [] });
                    const b = m.get(k);
                    if (!b.items.some(x => x.card_id && x.card_id === it.card_id && x.piece_id === it.piece_id)) b.items.push(it);
                });
                return [...m.values()].sort((a, b) => CB_ORDER.indexOf(a.kind) - CB_ORDER.indexOf(b.kind) || String(a.date).localeCompare(String(b.date)));
            }
            const cbBlocking = blocks => blocks.filter(b => b.kind !== 'capacity');
            // "Joylab bo'lmadi — sabab: o'qituvchi band va xona band" (joylangan, to'qnashuvdagi dars — "To'qnashuv — sabab: …").
            function cbTitle(blocks, placed) {
                const kinds = [...new Set(cbBlocking(blocks).map(b => CB_SHORT[b.kind]).filter(Boolean))];
                const list = kinds.length > 1 ? kinds.slice(0, -1).join(', ') + ' va ' + kinds[kinds.length - 1] : (kinds[0] || '');
                return (placed ? "To'qnashuv" : "Joylab bo'lmadi") + (list ? ' — sabab: ' + list : '');
            }
            function cbBlockHead(b) {
                const it = b.items[0] || {};
                if (b.kind === 'day_end') return 'Kun oxiri: ' + it.hours + " soat sig'maydi" + (it.from ? ' (' + it.from + ' dan keyin ' + (it.free ? it.free + " soat bo'sh" : "bo'sh joy yo'q") + ')' : '');
                if (b.kind === 'capacity') return "Xona sig'maydi: " + (b.who ? b.who + ' — ' : '') + it.volume + " o'rin, " + it.students + ' talaba (+' + it.over + ')';
                return CB_HEAD[b.kind] + ': ' + b.who;
            }
            // Band qilgan dars: "10:00–11:20 · d1/d26-01a · Tibbiy biologiya (amaliy) · NUROVA Z. A. · 123-amaliyot xonasi".
            const cbTypeText = t => (t ? (t === 'lecture' || t === 'M' ? "ma'ruza" : 'amaliy') : '');
            const cbLineText = it => [it.time, (it.groups || []).join(', '), (it.subject || '') + (it.training_type ? ' (' + cbTypeText(it.training_type) + ')' : ''),
                it.teacher, it.room_name].filter(Boolean).join(' · ');
            const CB_SHOWABLE = ['room', 'teacher', 'group'];
            // Bloklar HTML: sarlavha, har blok — sarlavhasi, [Ko'rsatish], band qilgan darslar (hammasi, yashirilmaydi), "Ko'rsatish" joyi.
            function cbHtml(blocks, placed, opts = {}) {
                if (!blocks.length) return '';
                // To'qnashuvlar bir necha kunda (bo'lingan dars) — blok sarlavhasida kun va sana.
                const multiDay = new Set(blocks.map(b => b.date).filter(Boolean)).size > 1;
                const dayTag = b => (multiDay && b.date ? ' (' + (boardDayNames()[b.day - 1] || b.day + '-kun') + ', ' + cfDate(b.date) + ')' : '');
                const tone = { teacher: '#fee2e2', group: '#ffe4e6', room: '#fef9c3', day_end: '#fee2e2', capacity: '#fff7ed' };
                return '<div class="cb-title" data-cb-title style="font-weight:600;color:' + (cbBlocking(blocks).length ? '#991b1b' : '#9a3412') + '">' + esc(cbTitle(blocks, placed)) + '</div>' +
                    blocks.map((b, i) => '<div class="cb-block" data-cb-block="' + b.kind + '" style="margin-top:4px;padding:3px 6px;border-radius:6px;background:' + (tone[b.kind] || '#f1f5f9') + ';color:#1f2937">' +
                        '<div style="display:flex;justify-content:space-between;gap:6px;align-items:baseline"><b data-cb-head>' + esc(cbBlockHead(b) + dayTag(b)) + '</b>' +
                        (CB_SHOWABLE.includes(b.kind) && !opts.compact ? '<span style="white-space:nowrap">' +
                            // "Xona band" — har holatda (boshqa sabablar bilan birga ham) shu blokning o'zida "Boshqa xona tanlash".
                            (b.kind === 'room' && opts.roomPick ? '<a href="#" data-cb-room-pick="' + i + '" style="text-decoration:underline dotted;margin-right:8px">Boshqa xona tanlash</a>' : '') +
                            '<a href="#" data-cb-show="' + i + '" style="text-decoration:underline dotted">Ko\'rsatish</a></span>' : '') + '</div>' +
                        (CB_SHOWABLE.includes(b.kind) && b.items.some(it => it.subject) ? '<ul style="margin:1px 0 0;padding-left:16px">' +
                            b.items.map(it => '<li data-cb-line>' + esc(cbLineText(it)) + '</li>').join('') + '</ul>' : '') +
                        (b.kind === 'room' && opts.roomPick ? '<div data-cb-room="' + i + '" hidden style="margin-top:3px"></div>' : '') +
                        '<div data-cb-detail="' + i + '" hidden style="margin-top:3px"></div></div>').join('');
            }
            // "Boshqa xona tanlash": shu vaqt uchun xonalar (server room-options — fan mas'uli oynasidagi ro'yxat: yaqinlik tartibi, bo'sh tepada,
            // band — kulrang kim bilan, sig'maydi, biriktirilgan — kulrang; qidiruv faqat nom bo'yicha). Tanlansa — shu xona bilan qayta tekshiruv:
            // boshqa sabab qolmasa — "Shu xona bilan joylash" / joylangan-to'qnashuvdagi darsda "Xonani almashtirish (shu hafta)"; o'qituvchi /
            // guruh ham band bo'lsa — xona tanlanadi, qolgan sabab ko'rsatiladi (joylanmaydi). Xona faqat shu hafta uchun.
            async function cbRoomPick(el, blocks, ctx) {
                const rp = ctx.solutions && ctx.solutions.roomPick;
                if (!el || !rp) return;
                el.hidden = false;
                el.innerHTML = '<div data-cb-room-head style="color:#475569;font-size:11px;margin-bottom:2px"></div>' +
                    '<input type="search" data-cb-room-q placeholder="Xona yoki bino qidirish…" autocomplete="off" style="width:100%;font-size:12px;padding:1px 4px">' +
                    '<div data-cb-room-list style="max-height:180px;overflow:auto;margin-top:2px">Yuklanmoqda…</div><div data-cb-room-msg style="margin-top:3px"></div>';
                const list = el.querySelector('[data-cb-room-list]'), msg = el.querySelector('[data-cb-room-msg]'), q = el.querySelector('[data-cb-room-q]');
                let rooms = [];
                try {
                    const j = await api(BASE + '/cards/' + rp.card.id + '/room-options?' + new URLSearchParams({ week: curWeek, day: rp.day, pair: rp.pair }));
                    rooms = (j && j.rooms) || [];
                    el.querySelector('[data-cb-room-head]').textContent = roomListHeadText(j && j.when, rooms);
                } catch (e) { list.innerHTML = '<div style="color:#b91c1c">' + esc(e.message) + '</div>'; if (ctx.reposition) ctx.reposition(); return; }
                const note = r => r.kind === 'busy' ? (r.busy || 'band') : r.kind === 'capacity' ? "sig'maydi" + (r.cap ? ' (+' + r.cap.over + ')' : '')
                    : r.kind === 'assigned' ? (r.note || 'biriktirilgan') : (r.why || '');
                const render = () => {
                    // Qidiruv — xona nomi va bino nomi bo'yicha (kod emas).
                    const shown = rooms.filter(r => roomMatches(r, q.value || '', true));
                    list.innerHTML = roomListGrouped(shown, r => '<button type="button" data-cb-room-code="' + esc(r.code) + '"' + (r.free ? '' : ' disabled') +
                        (r.note_full ? ' title="' + esc(r.note_full) + '"' : '') + ' style="display:block;width:100%;text-align:left;border:0;border-bottom:1px solid #e2e8f0;background:' +
                        (r.free ? '#fff;color:#0f172a;cursor:pointer' : '#f8fafc;color:#94a3b8') + ';padding:1px 4px">' +
                        '<b>' + esc(r.name || r.code) + '</b>' + (r.current ? ' (hozirgi)' : '') + (+r.volume ? ' · ' + +r.volume + " o'rin" : '') +
                        (roomBuildingTag(r) ? ' <span data-cb-room-bld style="font-size:10px;color:#64748b;background:#f1f5f9;border-radius:4px;padding:0 4px">' + esc(roomBuildingTag(r)) + '</span>' : '') +
                        (note(r) ? ' · <span data-cb-room-note>' + esc(note(r)) + '</span>' : '') + '</button>',
                        g => '<div data-cb-room-group style="position:sticky;top:0;background:#e2e8f0;color:#334155;font-weight:600;font-size:11px;padding:1px 4px">' + esc(g) + '</div>')
                        || '<div style="color:#94a3b8">' + (rooms.length ? 'Qidiruv bo\'yicha xona topilmadi' : 'Xona topilmadi') + '</div>';
                    if (ctx.reposition) ctx.reposition();
                };
                render();
                q.oninput = render;
                list.onclick = ev => {
                    const row = ev.target.closest ? ev.target.closest('[data-cb-room-code]') : null;
                    if (!row || row.disabled) return;
                    ev.preventDefault(); ev.stopPropagation();
                    const room = rooms.find(r => r.code === row.dataset.cbRoomCode);
                    const rest = cbBlocking(blocks).filter(b => b.kind !== 'room' && b.kind !== 'capacity');
                    if (rest.length) {
                        msg.innerHTML = '<div data-cb-room-rest style="color:#991b1b">Xona tanlandi: <b>' + esc(room.name || room.code) + '</b>. Qolgan sabab: ' +
                            esc(rest.map(cbBlockHead).join('; ')) + ' — joylanmaydi.</div>';
                    } else {
                        msg.innerHTML = 'Xona: <b>' + esc(room.name || room.code) + '</b> ' +
                            '<button type="button" data-cb-room-apply style="border:1px solid #16a34a;color:#166534;background:#f0fdf4;border-radius:5px;padding:1px 8px">' +
                            (rp.placed ? 'Xonani almashtirish (shu hafta)' : 'Shu xona bilan joylash') + '</button>';
                        msg.querySelector('[data-cb-room-apply]').onclick = async e2 => {
                            e2.preventDefault(); e2.stopPropagation();
                            e2.target.disabled = true;
                            try { await rp.apply(room); }
                            catch (er) { e2.target.disabled = false; msg.insertAdjacentHTML('beforeend', '<div style="color:#b91c1c">' + esc(er.message) + '</div>'); }
                        };
                    }
                    if (ctx.reposition) ctx.reposition();
                };
                if (ctx.reposition) ctx.reposition();
            }
            // "Ko'rsatish" tafsiloti uchun fokus (jadvalda to'qnashuvni ko'rish rejimi): ikkala dars guruhlari, sana, vaqt.
            // Bo'lak — to'qnashuvga aynan tegishli bo'lagi (piece_id) va uning shu yozuvdagi joyi (piece_pair): bo'laklari turli kunda yoki oraliq
            // bilan turgan birlikda ham fokus vaqti va belgilanadigan kartalar shu bo'lakniki.
            function cbFocusShow(b, ctx) {
                const it = b.items[0] || {};
                const kind = b.kind === 'teacher' ? 'teacher_busy' : b.kind === 'room' ? 'room_busy' : 'group_busy';
                const other = cards.find(x => x.id === it.card_id);
                const piece = cards.find(x => x.id === +it.piece_id) || ctx.card;
                const from = +it.piece_pair || ctx.pair, len = piece === ctx.card && !it.piece_pair ? ctx.len : cardLen(piece);
                const fg = x => cardGroups(x).map(g => ({ group: g, faculty: x.faculty_name || '', specialty: x.specialty_name || '', course: +x.course }));
                return { kind, teacher_id: b.kind === 'teacher' ? (+piece.teacher_id || null) : null, teacher_name: b.kind === 'teacher' ? b.who : null,
                    room_code: b.kind === 'room' ? (it.room_code || null) : null, room_name: b.kind === 'room' ? b.who : null,
                    groups: fg(piece).concat(other ? fg(other) : []), subject: it.subject, dates: [it.date, it.date], hour_from: from, hour_to: from + len,
                    hour_unit: 'row', card_ids: [piece.id].concat(it.card_id ? [it.card_id] : []), view: 'week', week: curWeek };
            }
            // Kun ro'yxati qatorlari (agenda yozuvlari): vaqt, guruh(lar), fan (ma'ruza/amaliy), o'qituvchi (xona) yoki xona (o'qituvchi);
            // band qilgan dars — qizil, shu dars — belgilangan; joylanmagan dars — joylanmoqchi bo'lgan vaqtida qo'shimcha qator.
            function cbDayRows(entries, b, ctx) {
                const hit = new Set(b.items.map(it => +it.card_id).filter(Boolean));
                const mine = new Set(ctx.ids);
                // Sikl yozuvlari (kartasi ajratilmagan): shu dars — aynan shu birlik yozuvi (agenda kaliti "c|<birlik>|<sana>"; birlik kaliti
                // bo'lmasa — guruhi); to'qnashgan — shu dars vaqti bilan kesishgan boshqa yozuv: to'qnashgan birliklar kartasi yoki guruhi
                // (shu guruhning boshqa vaqtdagi darsi yoki boshqa fani "shu dars" / qizil bo'lmaydi).
                const hitG = new Set(b.items.flatMap(it => it.hit_groups || []));
                const mineG = new Set(ctx.mineGroups || []);
                const cycIds = new Set(b.items.flatMap(it => (it.hit_groups && it.show && it.show.card_ids) || []).map(Number));
                // Shu birlik ma'ruzasi (sikl ma'ruzasi to'qnashuvi): agenda kaliti "l|<dars>|…" — yozuvning lecture_id si bilan.
                const mineLec = new Set(b.items.map(it => (it.hit_groups ? +it.lecture_id : 0)).filter(Boolean));
                const lecOf = e => { const k = String(e.key || '').split('|'); return k[0] === 'l' ? +k[1] : 0; };
                const mineBy = e => (e.card_ids || []).some(id => mine.has(+id)) || (ctx.cycKey
                    ? String(e.key || '').startsWith('c|' + ctx.cycKey + '|') || mineLec.has(lecOf(e)) : (e.groups || []).some(g => mineG.has(g)));
                // To'qnashuv oralig'i (akademik soat): shu birlikning o'sha kungi yozuvlari; topilmasa — yozuvning show soatlari.
                const mineSpans = ctx.cycKey ? (entries || []).filter(e => !e.hidden && mineBy(e)).map(e => [+e.from, +e.to]) : [];
                const spans = mineSpans.length ? mineSpans : b.items.map(it => (it.hit_groups && it.show && it.show.hour_unit === 'hour' && +it.show.hour_from
                    ? [+it.show.hour_from, +it.show.hour_to] : null)).filter(Boolean);
                const inSpan = e => !spans.length || spans.some(([a, z]) => +e.from < z && a < +e.to);
                const hitBy = e => (e.card_ids || []).some(id => hit.has(+id)) || (!mineBy(e) && inSpan(e)
                    && ((e.card_ids || []).some(id => cycIds.has(+id)) || (e.groups || []).some(g => hitG.has(g) && !mineG.has(g))));
                // Qamrovdan tashqari dars (hidden) — vaqti band, tafsiloti yashirin: "band: boshqa fakultet".
                const rows = (entries || []).map(e => (e.hidden
                    ? { start: e.start, end: e.end, groups: [], subject: e.label || 'band: boshqa fakultet', type: null, who: '', hit: false, mine: false, hidden: true }
                    : { start: e.start, end: e.end, groups: e.groups || [], subject: e.subject, type: e.type,
                        who: b.kind === 'room' ? (e.teacher || '') : (e.room || ''), hit: hitBy(e), mine: mineBy(e) }));
                // Joylanmoqchi dars: bo'laklar o'z tartibida ketma-ket (ctx.pair dan); xona ro'yxatida — faqat shu xonadagi bo'laklar (bo'laklar
                // turli xonada bo'lishi mumkin), ketma-ketlari — bitta qator.
                if (!ctx.placed) {
                    const room = b.kind === 'room' ? (b.items[0] || {}).room_code || '' : null;
                    const segs = [];
                    let at = ctx.pair;
                    (ctx.list || [ctx.card]).forEach(x => {
                        const len = cardLen(x);
                        if (room === null || (effectiveCard(x).auditorium_code || '') === room) {
                            const l = segs[segs.length - 1];
                            if (l && l[1] === at) l[1] = at + len; else segs.push([at, at + len]);
                        }
                        at += len;
                    });
                    segs.forEach(([a, z]) => rows.push({ start: slotStart(a), end: slotEnd(z - 1), groups: cardGroups(ctx.card), subject: ctx.card.subject_name,
                        type: ctx.card.training_type === 'lecture' ? 'M' : 'A', who: b.kind === 'room' ? (ctx.card.teacher_name || '') : (b.who || ''), hit: false, mine: true, pending: true }));
                }
                rows.sort((x, y) => String(x.start).localeCompare(String(y.start)) || (x.pending ? 1 : 0) - (y.pending ? 1 : 0));
                return rows;
            }
            function cbDayRowHtml(r) {
                return '<li data-cb-row' + (r.hit ? ' data-cb-hit' : '') + (r.mine ? ' data-cb-mine' : '') + ' style="' + (r.hit ? 'color:#b91c1c;font-weight:600;' : '') +
                    (r.mine ? 'background:#e0f2fe;' : '') + (r.hidden ? 'color:#64748b;' : '') + '"' + (r.hidden ? ' data-cb-hidden' : '') + '>' +
                    esc([(r.start || '') + '–' + (r.end || ''), r.groups.join(', '), (r.subject || '') + (r.type ? ' (' + cbTypeText(r.type) + ')' : ''), r.who]
                        .filter(Boolean).join(' · ')) + (r.pending ? ' — <i>shu dars (joylanmoqchi)</i>' : r.mine ? ' — <i>shu dars</i>' : '') + '</li>';
            }
            // "Ko'rsatish": xona / o'qituvchi — shu kunning barcha darslari (server: teacher-agenda, sikl darslari bilan); guruh — shu vaqtdagi darsi.
            async function cbShowDetail(el, b, ctx) {
                const it = b.items[0] || {};
                const day = +it.day || ctx.day;   // to'qnashuv kuni (bo'laklari turli kunda bo'lsa — shu yozuv kuni)
                const dow = (boardDayNames()[day - 1] || day + '-kun') + ', ' + cfDate(it.date || weekDayIso(curWeek, day));
                const links = info => '<div style="margin-top:3px;display:flex;gap:8px;flex-wrap:wrap"><a href="#" data-cb-focus style="text-decoration:underline dotted">Jadvalda ko\'rsatish</a>' +
                    (info ? '<a href="#" data-cb-agenda style="text-decoration:underline dotted">' + esc(info.label) + '</a>' : '') + '</div>';
                const bind = info => {
                    const f = el.querySelector('[data-cb-focus]');
                    if (f) f.onclick = ev => { ev.preventDefault(); ev.stopPropagation(); if (ctx.close) ctx.close(); ttFocusStart(it.show || cbFocusShow(b, ctx)); };
                    const a = el.querySelector('[data-cb-agenda]');
                    if (a && info) a.onclick = ev => { ev.preventDefault(); ev.stopPropagation(); if (ctx.close) ctx.close(); ttAgendaOpen(info.open); };
                };
                if (b.kind === 'group') {
                    el.innerHTML = '<div data-cb-detail-head style="font-weight:600">Guruh ' + esc(b.who) + ' · ' + esc(dow) + '</div><ul style="margin:1px 0 0;padding-left:16px">' +
                        b.items.map(x => '<li data-cb-row data-cb-hit style="color:#b91c1c">' + esc([x.time, (x.subject || '') + (x.training_type ? ' (' + cbTypeText(x.training_type) + ')' : ''), x.teacher, x.room_name].filter(Boolean).join(' · ')) + '</li>').join('') +
                        '</ul>' + links(null);
                    bind(null);
                    return;
                }
                const q = b.kind === 'room' ? { room_code: it.room_code || '' } : { teacher_id: +(it.teacher_id || ctx.card.teacher_id) || '' };
                const open = Object.assign({}, q, b.kind === 'room' ? { room_name: b.who } : { teacher_name: b.who }, { date: it.date, range: 'week' });
                const info = { label: b.kind === 'room' ? 'Xonaning haftalik jadvali' : 'O\'qituvchining haftalik jadvali', open };
                el.innerHTML = '<div style="color:#64748b">yuklanmoqda…</div>';
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/teacher-agenda?' + new URLSearchParams(Object.assign({}, q, { date: it.date, range: 'day', layer: 'internal' })).toString());
                    const head = b.kind === 'room' ? b.who + (j && j.room && +j.room.volume ? ' · ' + j.room.volume + " o'rin" : '') + ' · ' + dow : b.who + ' · ' + dow;
                    el.innerHTML = '<div data-cb-detail-head style="font-weight:600">' + esc(head) + '</div><ul style="margin:1px 0 0;padding-left:16px">' +
                        cbDayRows(j && j.entries, b, ctx).map(cbDayRowHtml).join('') + '</ul>' + links(info);
                } catch (e) {
                    el.innerHTML = '<div style="color:#b91c1c">' + esc(e.message) + '</div>' + links(info);
                }
                bind(info);
            }
            // Bloklarni joyiga chizadi va "Ko'rsatish" / yechim tugmalarini bog'laydi. ctx: {card, ids (birlik), day, pair, len, placed, close,
            // reposition, solutions: {room: fn, roomPick: {...}}} ("Joylash uchun tanlash", "Vaqtincha kafedra mudiriga yozish" — oynaning pastki qatorida).
            function cbRender(host, items, ctx) {
                const blocks = cbBlocks(items);
                if (!host) return blocks;
                const kinds = new Set(cbBlocking(blocks).map(b => b.kind));
                // Yechimlar: faqat xona band — "Boshqa xona bilan joylash" (roomPick bo'lmasa). "Joylash uchun tanlash" va "Vaqtincha kafedra
                // mudiriga yozish" — oynaning pastki qatorida (bittadan, takrorlanmaydi).
                const sol = ctx.solutions || {};
                const btn = (attr, text, color) => '<button type="button" ' + attr + ' style="border:1px solid ' + color + ';color:' + color + ';background:#fff;border-radius:5px;padding:1px 8px">' + text + '</button>';
                const sols = [
                    // Xona tanlash — "Xona band" blokining o'zida (roomPick); u yo'q joyda — eski "Boshqa xona bilan joylash" (faqat xona band).
                    !sol.roomPick && kinds.has('room') && !kinds.has('teacher') && !kinds.has('group') && !kinds.has('day_end') && sol.room ? btn('data-cb-sol="room"', 'Boshqa xona bilan joylash', '#a16207') : '',
                ].filter(Boolean);
                host.innerHTML = cbHtml(blocks, ctx.placed, { roomPick: !!sol.roomPick }) + (blocks.length && sols.length ? '<div data-cb-sols style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px">' + sols.join('') + '</div>' : '');
                host.querySelectorAll('[data-cb-show]').forEach(a => a.onclick = ev => {
                    ev.preventDefault(); ev.stopPropagation();
                    const i = +a.dataset.cbShow, el = host.querySelector('[data-cb-detail="' + i + '"]');
                    if (!el) return;
                    el.hidden = !el.hidden;
                    if (!el.hidden && !el.dataset.loaded) { el.dataset.loaded = '1'; cbShowDetail(el, blocks[i], ctx).then(() => ctx.reposition && ctx.reposition()); }
                    if (ctx.reposition) ctx.reposition();
                });
                host.querySelectorAll('[data-cb-room-pick]').forEach(a => a.onclick = ev => {
                    ev.preventDefault(); ev.stopPropagation();
                    const el = host.querySelector('[data-cb-room="' + a.dataset.cbRoomPick + '"]');
                    if (!el) return;
                    if (el.dataset.loaded) { el.hidden = !el.hidden; if (ctx.reposition) ctx.reposition(); return; }
                    el.dataset.loaded = '1';
                    cbRoomPick(el, blocks, ctx);
                });
                host.querySelectorAll('[data-cb-sol]').forEach(x => x.onclick = ev => { ev.preventDefault(); ev.stopPropagation(); const f = sol[x.dataset.cbSol]; if (f) f(); });
                if (ctx.reposition) ctx.reposition();
                return blocks;
            }
            function panelPopOutside(ev) {
                const pop = document.getElementById('pnCardPop');
                if (pop && !pop.contains(ev.target)) closePanelCardPop();
            }
            function panelPopKey(ev) { if (ev.key === 'Escape') closePanelCardPop(); }
            function closePanelCardPop() {
                const pop = document.getElementById('pnCardPop');
                if (pop) pop.remove();
                if (panelPopState) {
                    window.removeEventListener('resize', panelPopState.reposition);
                    window.removeEventListener('scroll', panelPopState.reposition, true);
                    if (panelPopState.ro) panelPopState.ro.disconnect();
                    panelPopState = null;
                }
                document.removeEventListener('mousedown', panelPopOutside, true);
                document.removeEventListener('keydown', panelPopKey, true);
            }
            // Ichki jadvalda kun/para katagiga o'tish: kartaning guruh ustunidagi katak (bo'lmasa shu vaqt qatori) — scroll va ajratish.
            function gotoGridSlot(c, d, p) {
                const grid = document.getElementById('grid');
                if (!grid) return null;
                const gks = cardGKeys(c);
                const all = [...grid.querySelectorAll('td[data-day="' + d + '"][data-pair="' + p + '"]')];
                const mine = all.filter(td => gks.includes(td.dataset.g));
                const targets = mine.length ? mine : all;
                grid.querySelectorAll('.tt-slot-flash').forEach(x => x.classList.remove('tt-slot-flash'));
                targets.forEach(td => td.classList.add('tt-slot-flash'));
                if (targets[0] && targets[0].scrollIntoView) targets[0].scrollIntoView({ block: 'center', inline: 'center' });
                setTimeout(() => targets.forEach(td => td.classList.remove('tt-slot-flash')), 3000);
                return targets;
            }
            function renderPanel() {
                // Hafta almashdi — shu haftaning to'qnashuvlar ro'yxati (qisqa belgi uchun).
                if (curWeek && weeklyConflictItems.__week !== curWeek) loadWeekConflictItems();
                $('pnFilters').classList.toggle('hidden', viewMode === 'cycle');
                if (viewMode === 'cycle') {
                    renderCycleCards(cyclePlanData);
                    return;
                }
                $('cycleGroupFilter').classList.add('hidden');
                $('subjectColorsBtn').classList.add('hidden');
                $('cardPanelTitle').textContent = 'Joylashmagan kartalar';
                $('cardPanelHint').classList.add('hidden');
                // Fan mas'uli: mas'ul fan kartalari tepada (so'ng fan nomi bo'yicha).
                const fmMine = c => TIMETABLE_ROLE === 'fan_masuli' && mySubjectCardIds.has(+c.id) ? 1 : 0;
                const bySubject = (a, b) => (fmMine(b) - fmMine(a)) || a.subject_name.localeCompare(b.subject_name, 'uz');
                // To'qnashuvli (joylashgan, lekin o'qituvchi/xona/guruh band) kartalar ham — sababi bilan.
                // Dars yaxlit (birlik): qisman joylangan birlikning qolgan bo'lagi panelda ko'rinmaydi (tepada "qisman joylangan: N ta"
                // va yaxlit joylash / bo'shatish); butunlay joylanmagan ko'p bo'lakli birlik — bitta karta (birinchi bo'lagi, jami soati
                // bilan): sudrash butun darsni joylaydi.
                const uIdx = buildUnitIndex();
                const partialUnits = new Map();
                // Qisman joylangan birlik — bitta karta (birinchi joylanmagan bo'lagi): o'z belgisi ("Qisman: 3 soatdan 2 soati …") va
                // shu birlik uchun "yaxlit joylash / yaxlit bo'shatish" tugmalari.
                const un = weekActiveCards().filter(c => {
                    if (effPlace(c)) return !!cardConflict(c);
                    if (c.training_type === 'lecture' || weeklyLayer === 'external') return true;
                    const st = unitState(c, curWeek, uIdx);
                    if (st.partial) {
                        if (st.list.find(x => !placeInWeek(x, curWeek)) !== c) return false;
                        partialUnits.set(unitKey(c), Object.assign({ card: c }, st));
                        return true;
                    }
                    return st.list[0] === c;
                }).sort(bySubject);
                // Bo'lingan birliklar (hamma bo'lak joylangan, lekin turli kunda yoki oraliq bilan) — panel tepasida "Bo'lingan: N ta",
                // har biriga alohida "Yaxlitlash" (ommaviy yaxlitlash yo'q).
                const splitUnits = curWeek && weeklyLayer === 'internal' ? weeklySplitUnits(uIdx) : new Map();
                // Eskirgan "yaxlit joylanmadi" izohlari (birlik endi qisman / bo'lingan emas) tozalanadi.
                Object.keys(unitFixErr).forEach(k => { if (!partialUnits.has(k) && !splitUnits.has(k)) { delete unitFixErr[k]; delete unitFixItems[k]; } });
                unitPanelLen = {};
                un.forEach(c => { if (c.training_type !== 'lecture' && !effPlace(c)) { const l = unitOf(c, curWeek, uIdx); if (l.length > 1) unitPanelLen[c.id] = l.map(cardLen); } });
                // Shu haftada o'tilmaydigan kartalar — odatda yashirin. Ular joylashgan,
                // shunchaki bu haftaga tegishli emas; qo'lda bekor qilinganini qaytarish
                // uchun "ko'rsatish" tugmasi orqali chiqariladi.
                const skipped = curWeek ? visibleSpecCards().filter(weekCancelled).sort(bySubject) : [];
                const skipBtn = $('skipToggle');
                skipBtn.classList.toggle('hidden', !skipped.length);
                skipBtn.textContent = (showSkipped ? 'Yashirish' : 'Ko\'rsatish') +
                    ': bu haftada o\'tilmaydi (' + skipped.length + ' ta)';

                // Filtr variantlari — paneldagi barcha kartalardan
                const pool = showSkipped ? un.concat(skipped) : un;
                const uzSort = (a, b) => a.localeCompare(b, 'uz', { numeric: true });
                fillPnSelect('pnSubject', 'Barcha fanlar', [...new Set(pool.map(c => c.subject_name))].sort(uzSort), 'subject');
                fillPnSelect('pnOqim', 'Barcha oqimlar', [...new Set(pool.map(c => c.oqim_label || '').filter(Boolean))].sort(uzSort), 'oqim');
                // Oqim tanlangan bo'lsa — guruh ro'yxatida faqat shu oqim guruhlari
                const groupPool = pnFilter.oqim ? pool.filter(c => (c.oqim_label || '') === pnFilter.oqim) : pool;
                fillPnGroups([...new Set(groupPool.flatMap(cardGroups))].sort(uzSort));
                $('pnType').value = pnFilter.type;
                const filtering = !!(pnFilter.subject || pnFilter.oqim || pnFilter.groups.size || pnFilter.type);
                const unShown = un.filter(pnMatch);
                const skippedShown = skipped.filter(pnMatch);
                $('pnReset').classList.toggle('hidden', !filtering);
                $('pnFilterCount').classList.toggle('hidden', !filtering);
                $('pnFilterCount').textContent = 'Filtrda: ' + unShown.length + ' / ' + un.length + ' ta';

                const panelCard = (c, skip, conflict = skip ? null : cardConflict(c)) =>
                    '<div class="pn-card ' + (c.training_type === 'lecture' ? 'lec' : 'prc') + infoOnlyClass(c) + (skip ? ' skip' : '') + (conflict ? ' conflict' : '') + ((selected && selected.id === c.id) || (fmPick && fmPick.card.id === c.id) ? ' sel' : '') +
                    ' lang-' + (c.lang || 'uz') + '" draggable="true" style="' + subjStyle(c) + 'border-left-width:3px;" data-id="' + c.id + '" title="' + esc(c.subject_name + (bolakPartsLabel(c) ? ' · qismlar: ' + (c.group_names || []).join(', ') + ' — bitta mashg\'ulot' : '') + (skip ? ' · bu haftada o\'tilmaydi' : '')) + '">' +
                    cardLabel(c, true) +
                    '<div class="text-[9px] text-gray-500">' +
                    (c.training_type === 'lecture'
                        ? esc(c.oqim_label || 'oqim') + ' · ' + (c.group_names || []).length + ' guruh · ' + c.students + ' t.'
                        : esc(bolakPartsLabel(c) || c.group_name || '') + ' · ' + c.students + ' t.') +
                    (c.teacher_name ? ' · <i class="bi bi-person-check" aria-hidden="true"></i>' : '') + (c.auditorium_name ? ' · <i class="bi bi-door-open" aria-hidden="true"></i>' : '') +
                    (unitPanelLen[c.id] && !partialUnits.has(unitKey(c)) ? '<div class="text-[9px] font-semibold text-indigo-700" title="Dars yaxlit joylanadi: barcha bo\'laklari ketma-ket">jami ' +
                        unitPanelLen[c.id].reduce((a, b) => a + b, 0) + ' soat (' + unitPanelLen[c.id].join(' + ') + ')</div>' : '') +
                    '</div>' +
                    // Joylangan, lekin to'qnashuvli — joylanmaganlar bilan aralashmasin: holat va joyi.
                    (!skip && effPlace(c) ? '<div class="pn-placed" data-pn-placed style="font-size:9px;font-weight:600;color:#0f766e">joylangan · to\'qnashuv — ' + esc(placedSlotText(c)) + '</div>' : '') +
                    parallelBadgeHtml(c) + (!skip && partialUnits.has(unitKey(c)) ? partialBadgeHtml(partialUnits.get(unitKey(c)), unitFixErr[unitKey(c)]) : '') + (conflict ? '<div class="pn-conflict" role="button" tabindex="0" data-wcf="' + c.id + '" title="Bosing — tafsilot">⚠ ' + esc(cfBadgeText(curWeek && weeklyConflictItems[c.id] ? weeklyConflictItems[c.id][curWeek] : null) || ('To\'qnashuv: ' + conflict)) + '</div>' : '') +
                    // Fan mas'uli: mas'ul fani kartasi — "Joylash" (jadval kataklari rang bilan; ma'ruza — ko'rish oynasi, sababi bilan).
                    (!skip && fmMine(c) && c.training_type !== 'lecture' ? '<button type="button" class="pn-fm-place" data-fm-place-btn="' + c.id + '" title="Jadvalda bo\'sh joyni tanlab joylash (faqat shu hafta)">Joylash</button>' : '') + '</div>';

                // Qisman joylangan birliklar (ichki jadval, tanlangan hafta): ro'yxat (nomi bosilsa — shu kartaga) va hammasi uchun tugmalar.
                const partialHead = partialUnits.size && curWeek && weeklyLayer === 'internal'
                    ? '<div class="pn-partial" style="border:1px solid #fcd34d;background:#fffbeb;color:#92400e;border-radius:6px;padding:4px 6px;margin-bottom:6px;font-size:11px">' +
                        'Qisman joylangan <b>' + partialUnits.size + ' ta</b>: ' + [...partialUnits.values()].map(st =>
                            '<a href="#" class="pn-partial-go" data-pn-go="' + st.card.id + '" style="text-decoration:underline dotted">' +
                            esc(cardGroups(st.card).join(', ') + ' · ' + st.card.subject_name) + '</a>').join('; ') +
                        (unitEditable() ? '<div style="margin-top:3px"><button type="button" data-unit-fix="complete" style="border:1px solid #16a34a;color:#166534;background:#f0fdf4;border-radius:4px;padding:0 6px">hammasini yaxlit joylash</button>' +
                            ' <button type="button" data-unit-fix="clear" style="border:1px solid #d97706;color:#92400e;background:#fff;border-radius:4px;padding:0 6px">hammasini yaxlit bo\'shatish</button></div>' : '') + '</div>'
                    : '';
                $('cardPanel').innerHTML = mudirPhSectionHtml(weeklyPhCards()) + (curWeek && weeklyLayer === 'internal' ? unitClearedHtml() : '') + partialHead + splitHeadHtml(splitUnits) +
                    unShown.map(c => panelCard(c, false)).join('') +
                    (showSkipped ? skippedShown.map(c => panelCard(c, true)).join('') : '')
                    || (filtering && un.length
                        ? '<div class="text-xs text-gray-400 p-1">Filtrga mos karta yo\'q.</div>'
                        : '<div class="text-xs text-gray-400 p-1">Hammasi joylashgan 🎉</div>');

                document.querySelectorAll('.pn-card').forEach(el => {
                    // Bosish — kartaning ma'lumot va havolalar oynasi (o'qituvchi, xona, tashqi jadval; "Joylash uchun tanlash").
                    el.onclick = ev => {
                        if (ev.target.closest && ev.target.closest('[data-unit-fix],[data-wcf]')) return;
                        const c = cards.find(x => x.id === +el.dataset.id);
                        if (!c) return;
                        // Fan mas'uli: mas'ul fani kartasi (yoki uning "Joylash" tugmasi) — "Joylash uchun tanlash" rejimi.
                        // Fan mas'uli: mas'ul fani amaliy darsi — karta oynasi (sabab bloklari, "Shu joyga joylash", "Joylash uchun tanlash",
                        // "Boshqa xona tanlash", jadvallar); ma'ruza va boshqa holatlar — ko'rish oynasi (sababi bilan).
                        if (fmMine(c) && !fmCanPlace(c)) { fmPickStart(c); return; }
                        openPanelCardPop(c, el);
                    };
                    el.addEventListener('dragstart', ev => {
                        const c = cards.find(x => x.id === +el.dataset.id);
                        if (TIMETABLE_ROLE === 'fan_masuli') { fmDragStart(c, ev); return; }
                        startDrag(+el.dataset.id, ev);
                    });
                });
                document.querySelectorAll('#cardPanel [data-ph-revert]').forEach(b => b.onclick = ev => {
                    ev.stopPropagation();
                    const c = cards.find(x => x.id === +b.dataset.phRevert);
                    const sel = document.querySelector('#cardPanel [data-ph-weeks="' + b.dataset.phRevert + '"]');
                    if (c) mudirPhRevert(c, b, b.dataset.phMode || 'original', sel && sel.value ? +sel.value : null);
                });
                document.querySelectorAll('#cardPanel [data-pn-go]').forEach(a => a.onclick = ev => {
                    ev.preventDefault();
                    const el = document.querySelector('#cardPanel .pn-card[data-id="' + a.dataset.pnGo + '"]');
                    if (!el) return;
                    if (el.scrollIntoView) el.scrollIntoView({ block: 'center' });
                    el.classList.remove('pn-flash'); void el.offsetWidth; el.classList.add('pn-flash');
                    setTimeout(() => el.classList.remove('pn-flash'), 2400);
                });
                // Yaxlitlash — faqat shu bo'lingan birlik (card_ids).
                document.querySelectorAll('#cardPanel [data-unit-merge]').forEach(btn => btn.onclick = ev => {
                    ev.stopPropagation();
                    const st = splitUnits.get(btn.dataset.unitMerge);
                    if (st) runUnitFix(btn, 'merge', [st]);
                });
                // Joylanmaganlarga o'tkazilgan birlik — "Joylash uchun tanlang": karta tanlanadi, guruh ustuni belgilanadi va jadval unga suriladi.
                document.querySelectorAll('#cardPanel [data-cleared-select]').forEach(b => b.onclick = ev => {
                    ev.stopPropagation();
                    const c = cards.find(x => x.id === +b.dataset.clearedSelect);
                    if (!c) return;
                    const first = unitOf(c, curWeek)[0] || c;
                    // Fan mas'uli — o'z "Joylash" rejimi (server kataklari: bugun / o'tgan kun, xona ruxsati, so'rov yoki darhol).
                    if (fmUnitOk(first)) { fmPickStart(first); return; }
                    selected = first;
                    renderPanel(); renderGrid();
                    scrollToPickColumn(first);
                });
                // Bo'lingan birlik nomi — jadvaldagi birinchi bo'lagi katagiga.
                document.querySelectorAll('#cardPanel [data-split-go]').forEach(a => a.onclick = ev => {
                    ev.preventDefault();
                    const st = splitUnits.get(a.dataset.splitGo);
                    const at = st && placeInWeek(st.list[0], curWeek);
                    if (at) gotoGridSlot(st.list[0], at.day, at.pair);
                });
                // Yaxlit joylash / bo'shatish: kartadagi tugma — faqat shu birlik (card_ids), tepadagi — hammasi.
                document.querySelectorAll('#cardPanel [data-unit-fix]').forEach(btn => btn.onclick = ev => {
                    ev.stopPropagation();
                    const one = btn.dataset.unitCard ? partialUnits.get(unitKey(cards.find(x => x.id === +btn.dataset.unitCard) || {})) : null;
                    runUnitFix(btn, btn.dataset.unitFix, one ? [one] : [...partialUnits.values()]);
                });

                // Joylashgan kartani panelga sudrab tashlash — joyidan olib tashlanadi.
                // Paneldagi (joylashmagan) kartani yana panelga tashlash hech narsa qilmaydi.
                // Sikl rejimi panelga o'z hodisalarini qo'yadi; bu yerda ularni almashtiramiz.
                const panel = $('cardPanel');
                const placedDragged = () => (dragCardIds || [])
                    .map(id => cards.find(x => x.id === id))
                    .filter(c => c && effPlace(c));
                panel.ondragover = ev => {
                    if (!placedDragged().length) return;
                    ev.preventDefault();
                    ev.dataTransfer.dropEffect = 'move';
                    panel.classList.add('pn-drop');
                };
                panel.ondragleave = ev => {
                    if (!panel.contains(ev.relatedTarget)) panel.classList.remove('pn-drop');
                };
                panel.ondrop = async ev => {
                    ev.preventDefault();
                    panel.classList.remove('pn-drop');
                    const toUnplace = placedDragged();
                    dragCardIds = null;
                    if (!toUnplace.length) return;
                    try {
                        // Amaliy dars — birlik bilan (barcha bo'laklari birga olinadi).
                        const doneUnits = new Set();
                        for (const c of toUnplace) {
                            if (c.training_type === 'lecture') { await unplaceOneCard(c); continue; }
                            if (doneUnits.has(unitKey(c))) continue;
                            doneUnits.add(unitKey(c));
                            await placeUnitAt(c, null, null);
                        }
                    } catch (e) {
                        alert('Xatolik: ' + e.message);
                    }
                    selected = null;
                    renderAll();
                };
            }

            // Jadval kesimi (faqat ko'rish): o'qituvchi / auditoriya / fan ustunlari
            // ===== Haftalik kesimlarda (o'qituvchi / fan / xona) sikl darslari: tanlangan hafta, ichki jadval kun rejasidan =====
            // (ma'ruza va amaliy soatlari, para, guruhcha smenasi, xona, o'qituvchi). Faqat ko'rish: "sikl" belgisi, bosilsa — dars oynasi
            // ("Vaqtini o'zgartirishni so'rash" — ruxsat bo'lsa). Haftalik dars bilan ustma-ust — to'qnashuv (katak qizil hoshiyali).
            const CROSS_MODES = ['teacher', 'subject', 'room'];
            let cycleWeek = { sig: '', lessons: [], loading: '' };
            let cycleWeekGen = 0;   // doska / sikl rejasi qayta yuklansa — kesh eskiradi (yo'ldagi javob ham)
            function invalidateCycleWeek() { cycleWeekGen++; }
            let crossCycleShown = [];   // joriy panjaradagi sikl darslari (data-cyc indeksi)
            let teacherFullNames = {};  // teacher_id => to'liq F.I.Sh. (/data va cycle-week dan)
            let teacherPhones = {};     // teacher_id => {text: "+998 90 123 45 67", tel: "+998901234567"} (huquq bo'yicha, /data)
            // Nofaol xonalar (auditoriums.active = false) — kartalarda turganlari, kod => nomi (/data): tanlab bo'lmaydi, kartada ogohlantirish.
            let inactiveRooms = {};
            const ROOM_OFF_TEXT = 'Xona nofaol — almashtiring';
            function roomInactive(code) { return !!code && Object.prototype.hasOwnProperty.call(inactiveRooms, code); }
            // O'qituvchi kesimi ustuni — teacher_id bo'yicha (kartada qisqa yoki to'liq nom bo'lsa ham bitta ustun); id yo'q — nom.
            const teacherColKey = c => c.teacher_id ? 'T' + c.teacher_id : (c.teacher_name ? 'N:' + c.teacher_name : '— (biriktirilmagan)');
            function teacherColLabel(key, names) {
                if (key.startsWith('T')) return teacherFullNames[key.slice(1)] || (names || []).slice().sort((x, y) => y.length - x.length)[0] || key;
                return key.startsWith('N:') ? key.slice(2) : key;
            }
            // Bitta dars: ma'ruza oqimi (fan, o'qituvchi, xona va aniq vaqt bir xil — turli yo'nalish kartalari ham) — to'qnashuv emas.
            // Xonasiz ma'ruza — oqimligi tasdiqlanmaydi (serverdagi cycleConflicts kabi).
            const sameCrossLesson = (a, b) => {
                const x = a.c || a.l, y = b.c || b.l;
                const room = String(x.auditorium_code || x.auditorium_name || '');
                return isNonBlocking(x) === isNonBlocking(y) && isHemisExcluded(x) === isHemisExcluded(y) && x.training_type === 'lecture' && y.training_type === 'lecture' && a.fa === b.fa && a.fb === b.fb && room !== ''
                    && String(x.teacher_id || '') === String(y.teacher_id || '')
                    && String(x.subject_name || '').trim().toLowerCase() === String(y.subject_name || '').trim().toLowerCase()
                    && room === String(y.auditorium_code || y.auditorium_name || '');
            };
            // Katakdagi darslar → noyob darslar (sessiyalar). Bitta karta (sikl darsida — karta + sana) — bitta dars: bitta paraning
            // yarim soatlari (08:30 va 09:10), "A + B" umumiy karta guruhchalari; bitta ma'ruza oqimi (sameCrossLesson) — bitta dars.
            // To'qnashuv — ikki xil sessiya vaqti kesishsa (check); son — turli darslar: sessiya guruhchalari (karta + guruhcha + sana),
            // ma'ruza oqimi — bitta. Qaytaradi: { lessons: [{ items, groups, lecture }], clashing: [...], count }.
            function crossCellLessons(list, check) {
                const par = list.map((_, i) => i);
                const find = i => par[i] === i ? i : (par[i] = find(par[i]));
                const join = (a, b) => { a = find(a); b = find(b); if (a !== b) par[Math.max(a, b)] = Math.min(a, b); };
                const seen = {};
                list.forEach((it, i) => {
                    // Bitta dars: o'sha karta (sikl — karta + sana) yoki o'sha fan + tur + guruh(cha) (bitta katakda: darsning qismlari,
                    // har xil kartalar — bo'lingan amaliy, sikl kunlari yozuvlari).
                    [it.l ? 'C' + it.l.id + '|' + (it.l.date || '') : 'W' + it.c.id, crossLessonKey(it)].forEach(k => {
                        if (!k) return;
                        if (k in seen) join(seen[k], i); else seen[k] = i;
                    });
                });
                list.forEach((a, i) => list.forEach((b, j) => { if (j > i && sameCrossLesson(a, b)) join(i, j); }));
                const byRoot = {}, lessons = [];
                list.forEach((it, i) => {
                    const r = find(i);
                    if (!byRoot[r]) lessons.push(byRoot[r] = { items: [], groups: [], lecture: false });
                    const ls = byRoot[r], x = it.c || it.l;
                    ls.items.push(it);
                    ls.lecture = ls.lecture || x.training_type === 'lecture';
                    (it.l ? (it.l.group_names && it.l.group_names.length ? it.l.group_names : [it.l.group_name]) : cardGroups(x))
                        .forEach(g => String(g || '').split(/\s*\+\s*/).forEach(sg => { sg = sg.trim(); if (sg && !ls.groups.includes(sg)) ls.groups.push(sg); }));
                });
                const hit = new Set();
                if (check) lessons.forEach((a, x) => lessons.forEach((b, y) => {
                    if (y > x && a.items.some(p => b.items.some(q => !isNonBlocking(p.c || p.l) && !isNonBlocking(q.c || q.l) && p.fa < q.fb && q.fa < p.fb))) { hit.add(a); hit.add(b); }
                }));
                const clashing = lessons.filter(ls => hit.has(ls));
                return { lessons, clashing, count: clashing.reduce((n, ls) => n + (ls.lecture ? 1 : Math.max(1, ls.groups.length)), 0) };
            }
            // Dars kaliti: fakultet + yo'nalish + kurs (guruh nomlari ular orasida takrorlanadi — cycleConflicts kabi) + fan + tur +
            // guruh(cha)lar (qo'shimcha "(o'z)" va katta-kichik harfsiz); guruhi yo'q — null (birlashtirilmaydi).
            const crossGroupNorm = g => String(g || '').toLowerCase().replace(/\s*\([^)]*\)\s*/g, ' ').replace(/\s+/g, ' ').trim();
            function crossItemGroups(it) {
                const x = it.c || it.l;
                const raw = it.l ? (it.l.group_names && it.l.group_names.length ? it.l.group_names : [it.l.group_name]) : cardGroups(x);
                const out = [];
                raw.forEach(g => String(g || '').split(/\s*\+\s*/).forEach(sg => { sg = crossGroupNorm(sg); if (sg && !out.includes(sg)) out.push(sg); }));
                return out.sort();
            }
            function crossLessonKey(it) {
                const x = it.c || it.l, gs = crossItemGroups(it);
                const scope = [x.faculty_name, x.specialty_name, x.course].map(v => String(v == null ? '' : v).trim().toLowerCase()).join('|');
                return gs.length ? 'S' + scope + '|' + String(x.subject_name || '').trim().toLowerCase() + '|' + (x.training_type === 'lecture' ? 'L' : 'A')
                    + '|' + gs.join(',') : null;
            }
            // Sikl darsining zal to'qnashuvlari (birlashtirilgan chipda — barcha yozuvlardan).
            const cycRoomClashes = l => isNonBlocking(l) ? [] : (l && l.room_clashes) || (l && l.room_clash ? [l.room_clash] : []);
            // Bitta sikl darsining yozuvlari (karta + sana) — vaqti bo'yicha guruhlanadi: bir xil vaqt — guruhchalari qo'shiladi.
            function mergeCycParts(list) {
                const by = {}, out = [];
                list.forEach(p => {
                    const k = (+p.hour || 0) + '|' + (+p.hours || 0);
                    const gs = p.group_names && p.group_names.length ? p.group_names : [p.group_name];
                    if (!by[k]) { out.push(by[k] = { hour: p.hour, hours: p.hours, dp: p.dp, ask: p.ask, group_name: p.group_name, group_names: gs.slice() }); return; }
                    gs.forEach(g => { if (!by[k].group_names.includes(g)) by[k].group_names.push(g); });
                });
                return out.sort((a, b) => (+a.hour || 0) - (+b.hour || 0));
            }
            function cycleWeekSig() {
                if (!board || !curWeek || weeklyLayer !== 'internal' || !CROSS_MODES.includes(viewMode)) return '';
                return [board.id, curWeek, [...selectedFaculties].sort().join(','), [...selectedDirs].sort().join(','),
                    [...selectedCourses].sort((a, b) => a - b).join(','), cycleWeekGen].join('#');
            }
            async function loadCycleWeek() {
                const sig = cycleWeekSig();
                if (!sig || sig === cycleWeek.sig || sig === cycleWeek.loading) return;
                cycleWeek.loading = sig;
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/cycle-week', 'POST', Object.assign({ week: curWeek, layer: weeklyLayer }, scopeBody()));
                    if (cycleWeekSig() !== sig) return;   // eskirgan javob (hafta / qamrov o'zgardi)
                    cycleWeek = { sig: sig, lessons: Array.isArray(j.lessons) ? j.lessons : [], loading: '' };
                    cycleWeek.lessons.forEach(l => { if (l.teacher_id && l.teacher_full_name) teacherFullNames[l.teacher_id] = l.teacher_full_name; });
                    if (CROSS_MODES.includes(viewMode)) { renderGrid(); renderStats(); }
                } catch (e) {
                    console.warn('Sikl darslari olinmadi:', e);
                } finally {
                    if (cycleWeek.loading === sig) cycleWeek.loading = '';
                }
            }
            // Ko'rinadigan sikl darslari: qamrov (fakultet / yo'nalish / kurs), "Faqat meniki" / kafedra / mas'ul fanlar, mashg'ulot turi.
            function cycleWeekLessons() {
                if (!cycleWeek.sig || cycleWeek.sig !== cycleWeekSig()) return [];
                return scopeCards(cycleWeek.lessons.filter(l => selectedFaculties.has(l.faculty_name || '') && selectedDirs.has(l.specialty_name)
                    && selectedCourses.has(+l.course))).filter(typeVisible);
            }
            const cfGroupsText = list => (list || []).slice(0, 3).join(', ') + ((list || []).length > 3 ? ' +' + ((list || []).length - 3) + ' ta' : '');
            function cycChipHtml(l, i, mode) {
                const isLec = l.training_type === 'lecture';
                const st = isLec ? 'background:#fde68a;' : ('background-color:' + subjColor(l.subject_name).bg + ';');
                const dp = l.dp || {};
                const who = mode === 'teacher' ? (l.auditorium_name ? 'Xona: ' + l.auditorium_name : '')
                    : (l.teacher_name ? "O'qituvchi: " + l.teacher_name : '');
                return '<div class="tt-chip tt-cyc-chip ' + (isLec ? 'lec' : 'prc') + infoOnlyClass(l) + '" data-cyc="' + i + '" style="' + st + '" title="Sikl darsi (faqat ko\'rish) — bosing: tafsilot">' +
                    '<div class="tt-cross-fac"><span class="tt-cyc-badge">sikl</span> ' + esc(l.faculty_name || '—') + '</div>' +
                    '<div class="tt-cross-dir">' + esc((l.specialty_name || '—') + ' · ' + l.course + '-kurs') + '</div>' +
                    '<div class="tt-cross-subject">' + esc('[' + (isLec ? 'M' : 'A') + '] ' + l.subject_name) + infoOnlyBadgeHtml(l) + '</div>' +
                    '<div class="tt-cross-flow">' + esc(cfGroupsText(l.group_names && l.group_names.length ? l.group_names : [l.group_name])) + '</div>' +
                    '<div class="tt-cross-weeks">' + esc((who ? who + ' · ' : '') + (dp.k ? dp.k + '-kun' : '')) + '</div></div>';
            }
            function renderGridCross(mode) {
                const placed = visibleSpecCards().filter(c => effPlace(c)).map(effectiveCard);
                const cyc = CROSS_MODES.includes(mode) ? cycleWeekLessons() : [];
                if (CROSS_MODES.includes(mode)) loadCycleWeek();
                crossCycleShown = cyc.slice();   // + birlashtirilgan nusxalar (bitta darsning bir necha yozuvi — bitta chip)
                const keyOf = c => mode === 'teacher' ? teacherColKey(c)
                    : mode === 'room' ? (c.auditorium_name || '— (xona yo\'q)')
                    : c.subject_name;
                // Darslar (haftalik karta va sikl darsi) — ustun, kun va [boshlanish, tugash) qatorlari (chizish uchun); fa/fb — akademik
                // soatlardagi aniq oraliq (to'qnashuv uchun): to'liq parada 1 qator = rh soat, sikl darsi qatori yaxlitlangan bo'lishi mumkin.
                const rh = Math.max(1, +((cyc[0] || {}).row_hours) || 1);
                const items = focusCrossItems(mode, placed.map(c => {
                    const pl = effPlace(c), to = +pl.pair + cardLen(c);
                    return { col: keyOf(c), day: +pl.day, from: +pl.pair, to: to, fa: (+pl.pair - 1) * rh + 1, fb: (to - 1) * rh + 1, c: c };
                }).concat(cyc.map((l, i) => {
                    const from = +l.pair, to = from + Math.max(1, +l.len_half || 1), fa = +l.hour || (from - 1) * rh + 1;
                    return { col: keyOf(l), day: +l.day, from: from, to: to, fa: fa, fb: fa + (+l.hours || (to - from) * rh), l: l, i: i };
                })));
                const namesOf = {};
                if (mode === 'teacher') items.forEach(it => { const n = (it.c || it.l).teacher_name; if (n) (namesOf[it.col] = namesOf[it.col] || []).push(n); });
                const colLabel = col => mode === 'teacher' ? teacherColLabel(col, namesOf[col]) : col;
                const cols = [...new Set(items.map(it => it.col))].sort((a, b) => colLabel(a).localeCompare(colLabel(b), undefined, { numeric: true }));
                let D = board.days;
                Object.values(grids).forEach(gg => { D = Math.max(D, gg.days); });
                const sched = boardSchedule().filter(it => it.type === 'pair');
                const P = sched.length || board.pairs_per_day;
                const dayNames = boardDayNames();
                const pairTime = {};
                sched.forEach((it, i) => { pairTime[it.no || (i + 1)] = it; });

                // Bir ustun va kunda vaqti kesishgan darslar — bitta katak (birlashgan oraliq): ikkitasi bo'lsa — to'qnashuv.
                const startIdx = {}, consumed = {};
                const byColDay = {};
                items.forEach(it => { (byColDay[it.col + '|' + it.day] = byColDay[it.col + '|' + it.day] || []).push(it); });
                Object.keys(byColDay).forEach(k => {
                    let cur = null;
                    byColDay[k].sort((a, b) => a.from - b.from || b.to - a.to).forEach(it => {
                        if (cur && it.from < cur.to) { cur.items.push(it); cur.to = Math.max(cur.to, it.to); return; }
                        cur = { from: it.from, to: it.to, items: [it] };
                        startIdx[k + '|' + it.from] = cur;
                    });
                });

                if (!cols.length) {
                    $('grid').innerHTML = '<div class="p-4 text-sm text-gray-400">Bu kesimda joylashgan darslar yo\'q.</div>';
                    activeCell = null; return;
                }
                const rowEndCls = p => p === P ? ' tt-dayend' : (p % 2 === 0 ? ' tt-paraend' : '');
                let h = '<thead><tr><th class="tt-corner px-1 py-1">Kun</th><th class="tt-corner px-1 py-1" colspan="2" style="left:26px">Para</th>';
                const pGroups = paraGroups(P, pairTime);
                const roomMeta = {};
                 if (mode === 'room') items.forEach(it => {
                     const card = it.c || it.l;
                     const roomKey = it.col;
                     if (!roomMeta[roomKey]) roomMeta[roomKey] = {
                         code: card.auditorium_code || '',
                         name: card.auditorium_name || roomKey,
                         volume: card.auditorium_volume
                     };
                 });
                 cols.forEach(c => {
                     if (mode !== 'room') {
                         h += '<th class="tt-grp px-2 py-1">' + esc(colLabel(c)) + '</th>';
                         return;
                     }
                     const room = roomMeta[c] || { code: '', name: c, volume: null };
                     const roomNumber = String(room.name || room.code || c).replace(/^№\s*/u, '');
                     const capacity = room.volume !== null && room.volume !== undefined && room.volume !== ''
                         ? ' <span class="tt-room-vol">(' + esc(String(room.volume)) + ' ta)</span>' : '';
                     h += '<th class="tt-grp tt-room-head px-2 py-1">№ ' + esc(roomNumber) + capacity + '</th>';
                 });
                h += '</tr></thead><tbody>';
                // Kesimda to'qnashuv hisoblanmaydi: fan kesimi, biriktirilmagan / xonasiz ustun, "Kafedra mudiri xonasi" (vaqtincha ustma-ust mumkin).
                const noClash = col => mode === 'subject' || /^— \(/.test(col) || (mode === 'room' && /kafedra\s+mudiri/iu.test(col));
                for (let d = 1; d <= D; d++) {
                    for (let p = 1; p <= P; p++) {
                        h += '<tr>';
                        if (p === 1) h += '<td class="tt-day" rowspan="' + P + '">' + esc(dayNames[d - 1] || ('Kun ' + d)) + '</td>';
                        h += paraSideCells(p, P, pairTime, pGroups, rowEndCls);
                        cols.forEach(col => {
                            const key = col + '|' + d + '|' + p;
                            if (consumed[key]) return;
                            const cl = startIdx[key];
                            if (!cl) { h += '<td class="tt-cell' + rowEndCls(p) + '" data-day="' + d + '" data-pair="' + p + '"></td>'; return; }
                            const vs = Math.max(1, Math.min(cl.to, P + 1) - p);
                            for (let k = 1; k < vs; k++) consumed[col + '|' + d + '|' + (p + k)] = 1;
                            const rs = vs > 1 ? ' rowspan="' + vs + '"' : '';
                            // Noyob darslar: bitta darsning takror yozuvlari (yarim paralar, guruhchalar) — bitta chip (guruhlari qo'shiladi).
                            const cell = crossCellLessons(cl.items, !noClash(col));
                            const shown = [];
                            cell.lessons.forEach(ls => {
                                const chips = [];   // [{ keys: Set, idx }]
                                ls.items.forEach(it => {
                                    // Sikl yozuvlari — o'sha karta (+ sana) yoki o'sha dars kaliti (fan + tur + guruh) bo'lsa bitta chip (qismlari
                                    // parts'da), o'qituvchi va xonasi ham bir xil bo'lsa: chip bitta o'qituvchi/xonani ko'rsatadi — boshqasi
                                    // alohida chip (dars sanog'i o'zgarmaydi). Haftalik karta — o'z chipi.
                                    const lk = it.l ? crossLessonKey(it) : null;
                                    const asg = it.l ? '|T' + (it.l.teacher_id || it.l.teacher_name || '') + '|R' + (it.l.auditorium_code || it.l.auditorium_name || '') : '';
                                    const keys = it.l ? ['C' + it.l.id + '|' + (it.l.date || '') + asg].concat(lk ? [lk + '|' + (it.l.date || '') + asg] : []) : ['W' + it.c.id];
                                    const ch = chips.find(x => keys.some(k => x.keys.has(k)));
                                    if (!ch) { chips.push({ keys: new Set(keys), idx: shown.length }); shown.push(it); return; }
                                    keys.forEach(k => ch.keys.add(k));
                                    if (!it.l) return;
                                    const first = shown[ch.idx];
                                    const gs = [...new Set([].concat(first.l.group_names && first.l.group_names.length ? first.l.group_names : [first.l.group_name],
                                        it.l.group_names && it.l.group_names.length ? it.l.group_names : [it.l.group_name]))];
                                    // Vaqtlari har xil bo'lsa — umumiy oraliq, har guruhcha o'z vaqti, kun rejasi va so'rovi bilan (parts; oynada).
                                    const parts = mergeCycParts((first.l.parts || [first.l]).concat([it.l]));
                                    const lo = Math.min(...parts.map(p => +p.hour || 0)), hi = Math.max(...parts.map(p => (+p.hour || 0) + (+p.hours || 0)));
                                    // Zal to'qnashuvi — barcha yozuvlardan (keyingi yarmida bo'lsa ham yo'qolmasin).
                                    const clashes = [...new Set([].concat(cycRoomClashes(first.l), cycRoomClashes(it.l)))];
                                    const merged = Object.assign({}, first.l, { group_names: gs, hour: lo, hours: hi - lo,
                                        parts: parts.length > 1 ? parts : undefined, ask: parts.some(p => p.ask),
                                        room_clash: clashes[0], room_clashes: clashes.length ? clashes : undefined });
                                    crossCycleShown.push(merged);
                                    shown[ch.idx] = Object.assign({}, first, { l: merged, i: crossCycleShown.length - 1 });
                                });
                            });
                            const inner = shown.map(it => {
                                if (it.l) return cycChipHtml(it.l, it.i, mode);
                                const c = it.c;
                                const isLec = c.training_type === 'lecture';
                                const st = isLec ? 'background:#fde68a;' : ('background-color:' + subjColor(c.subject_name).bg + ';');
                                const detailLines = excelCardText(c).split('\n');
                                return '<div class="tt-chip ' + (isLec ? 'lec' : 'prc') + infoOnlyClass(c) + '" data-chip="' + c.id + '" style="' + st + '">' +
                                    '<div class="tt-cross-fac">' + esc(detailLines[0] || '') + '</div>' +
                                    '<div class="tt-cross-dir">' + esc(detailLines[1] || '') + '</div>' +
                                    '<div class="tt-cross-subject">' + esc(detailLines[2] || '') + '</div>' +
                                    '<div class="tt-cross-flow">' + esc(detailLines[3] || '') + '</div>' +
                                    '<div class="tt-cross-weeks">' + esc(detailLines[4] || '') + '</div>' +
                                    '</div>';
                            }).join('');
                            // Bir katakda vaqti kesishgan turli darslar (o'qituvchi/xona kesimida; haftalik ham, sikl ham) — to'qnashuv (kamida 2 ta
                            // turli dars); son va ro'yxat — noyob darslar bo'yicha (bitta darsning takror yozuvlari, ma'ruza oqimi — bitta).
                            const what = ls => { const it = ls.items[0], c = it.c || it.l;
                                return (it.l ? 'sikl: ' : '') + c.subject_name + ' (' + (ls.lecture ? 'M' : 'A') + ') ' + cfGroupsText(ls.groups); };
                            const clashOn = cell.clashing.length > 0;   // kamida ikki turli sessiya kesishgan
                            const why = clashOn ? 'To\'qnashuv — bir vaqtda ' + cell.count + ' ta dars: ' + cell.clashing.map(what).join('; ') : '';
                            // Sikl ma'ruzasi zalida shu vaqtda boshqa ma'ruza (butun doska bo'yicha, server: room_clash) — o'qituvchi kesimida ham.
                            const roomWhy = [...new Set([].concat(...shown.filter(it => it.l).map(it => cycRoomClashes(it.l))))];
                            const title = [why].concat(roomWhy).filter(Boolean).join(' · ');
                            const conflict = clashOn ? ' style="outline:2px solid #ef4444;outline-offset:-2px;background:#fef2f2" data-cross-clash="1" title="' + esc(title) + '"'
                                : roomWhy.length ? ' style="outline:2px solid #f59e0b;outline-offset:-2px;background:#fffbeb" data-room-clash="1" title="' + esc(title) + '"' : '';
                            const whyHtml = (clashOn ? '<div class="tt-clash-why">⚠ Bir vaqtda ' + cell.count + ' ta dars</div>'
                                + '<div class="tt-clash-list">' + cell.clashing.map(ls => '<div>' + esc(what(ls)) + '</div>').join('') + '</div>' : '')
                                + (roomWhy.length ? '<div class="tt-clash-why tt-room-why">⚠ Zalda bir vaqtda ikki ma\'ruza</div>'
                                    + '<div class="tt-clash-list">' + roomWhy.map(t => '<div>' + esc(t) + '</div>').join('') + '</div>' : '');
                            h += '<td class="tt-cell' + rowEndCls(p + vs - 1) + '"' + rs + ' data-day="' + d + '" data-pair="' + p + '"' + conflict + '>' + whyHtml + inner + '</td>';
                        });
                        h += '</tr>';
                    }
                }
                h += '</tbody>';
                $('grid').innerHTML = h;
                activeCell = null;
                focusHighlight();
            }
            // Sikl darsi oynasi (kesimlarda): sana, para, guruh(lar), o'qituvchi, xona, kun rejasi; ruxsat bo'lsa — vaqt so'rovi.
            function closeCrossCycPop() { const p = document.getElementById('crossCycPop'); if (p) p.remove(); }
            function openCrossCycPop(l, anchor) {
                closeCrossCycPop();
                const dp = l.dp || {};
                // Vaqt — asl akademik soatlardan (yarim para aniqligida); bo'lmasa panjara qatorlaridan.
                const hours = cycHourTimes(), h0 = +l.hour || 0, hn = +l.hours || 0;
                const sched = boardSchedule().filter(it => it.type === 'pair');
                const from = sched[+l.pair - 1], to = sched[+l.pair + (+l.len_half || 1) - 2];
                const time = h0 && hours[h0] && hours[h0 + hn - 1] ? hours[h0][0] + '–' + hours[h0 + hn - 1][1]
                    : from && to ? from.start + '–' + to.end : l.pair + '-qatordan';
                const iso = String(l.date || '');
                const d = iso.slice(8, 10) + '.' + iso.slice(5, 7) + '.' + iso.slice(0, 4);
                const isLec = l.training_type === 'lecture';
                // Ma'ruza so'rovi — butun oqim uchun (server ruxsati: l.ask); guruhcha qismlari bo'yicha so'rov — faqat amaliy.
                const canAsk = ['oqituvchi', 'fan_masuli'].includes(TIMETABLE_ROLE);
                // Birlashtirilgan chip (bitta darsning guruhchalari har xil vaqtda): har biri o'z vaqti va so'rovi bilan.
                const parts = Array.isArray(l.parts) && l.parts.length > 1 ? l.parts : null;
                const partTime = p => { const a = +p.hour || 0, n = +p.hours || 0; return a && hours[a] && hours[a + n - 1] ? hours[a][0] + '–' + hours[a + n - 1][1] : ''; };
                const partsHtml = parts ? '<div class="dp-sub"><b>Guruhchalar vaqti:</b></div>' + parts.map((p, k) => '<div class="dp-sub">'
                    + esc((p.group_names || [p.group_name]).join(', ')) + ': ' + esc(partTime(p)) + ' (' + (+p.hours || 1) + ' s)'
                    + (canAsk && !isLec && p.ask ? ' <button type="button" data-cyc-ask-part="' + k + '" class="dp-ask px-1 rounded bg-blue-600 text-white">Vaqtini o\'zgartirishni so\'rash</button>' : '')
                    + '</div>').join('') : '';
                const pop = document.createElement('div');
                pop.id = 'crossCycPop';
                pop.className = 'tt-cross-cyc-pop';
                pop.innerHTML = '<div class="dp-head"><div><div class="dp-title">' + esc(l.subject_name) + ' <span class="tt-cyc-badge">sikl</span></div>' +
                    '<div class="dp-sub">' + esc(d) + (dp.k ? ' · ' + dp.k + '-kun' : '') + ' · ' + esc(time) + '</div></div>' +
                    '<button type="button" class="dp-close" aria-label="Yopish">&times;</button></div>' +
                    '<div class="dp-row"><span class="dp-tag ' + (isLec ? 'l' : 'p') + '">' + (isLec ? 'M' : 'A') + '</span><div><b>' + (isLec ? 'Ma\'ruza' : 'Amaliy') + ' ' + (+l.hours || +l.len_half || 1) + ' s</b>' +
                    (isLec && dp.tl ? '<div class="dp-topic">' + esc(dp.tl) + '</div>' : '') + (!isLec && dp.tp ? '<div class="dp-topic">' + esc(dp.tp) + '</div>' : '') + '</div></div>' +
                    '<div class="dp-sub">' + esc((l.faculty_name || '—') + ' · ' + l.specialty_name + ' · ' + l.course + '-kurs') + '</div>' +
                    '<div class="dp-sub">Guruh: ' + esc((l.group_names && l.group_names.length ? l.group_names : [l.group_name]).join(', ')) + (l.flow ? ' · ' + esc(l.flow) : '') + '</div>' +
                    '<div class="dp-sub">O\'qituvchi: ' + esc(l.teacher_name || '—') + ' · Xona: ' + esc(l.auditorium_name || '—') + '</div>' +
                    partsHtml +
                    cycRoomClashes(l).map(t => '<div class="dp-note" style="color:#b45309">⚠ ' + esc(t) + '</div>').join('') +
                    '<div class="dp-note">Sikl jadvalidagi dars — bu yerda faqat ko\'rish; joyi "Sikl" kesimida.</div>' +
                    (!parts && l.ask && canAsk
                        ? '<div class="dp-actions"><button type="button" data-cyc-ask class="dp-ask px-2 py-1 rounded bg-blue-600 text-white">Vaqtini o\'zgartirishni so\'rash</button></div>' : '');
                document.body.appendChild(pop);
                const r = anchor.getBoundingClientRect();
                pop.style.left = Math.max(8, Math.min(window.innerWidth - pop.offsetWidth - 8, r.right + 8)) + 'px';
                pop.style.top = Math.min(window.innerHeight - pop.offsetHeight - 8, Math.max(8, r.top - 20)) + 'px';
                pop.querySelector('.dp-close').onclick = closeCrossCycPop;
                const ask = pop.querySelector('[data-cyc-ask]');
                if (ask) ask.onclick = () => {
                    closeCrossCycPop();
                    const kd = isLec ? 'lecture' : 'practice';
                    openCycleTimeProposal({ subject: l.subject_name, group: l.group_name, specialty: l.specialty_name, course: l.course, type: kd }, cycAskDp(dp, kd),
                        { iso: iso, d: d }, { kind: kd });
                };
                // Guruhcha bo'yicha so'rov (birlashtirilgan chip) — o'sha guruhcha va uning kun rejasi bilan.
                pop.onclick = ev => {
                    const b = ev && ev.target && ev.target.closest ? ev.target.closest('[data-cyc-ask-part]') : null;
                    const p = b && parts ? parts[+b.dataset.cycAskPart] : null;
                    if (!p) return;
                    closeCrossCycPop();
                    openCycleTimeProposal({ subject: l.subject_name, group: p.group_name, specialty: l.specialty_name, course: l.course }, p.dp || {}, { iso: iso, d: d });
                };
            }
            // Sikl darsi bosilganda — oyna (katakka joylash va boshqa ishlovchilarga o'tmaydi).
            $('grid').addEventListener('click', ev => {
                const chip = ev.target && ev.target.closest ? ev.target.closest('[data-cyc]') : null;
                if (!chip || !CROSS_MODES.includes(viewMode)) return;
                ev.preventDefault();
                ev.stopPropagation();
                const l = crossCycleShown[+chip.dataset.cyc];
                if (l) openCrossCycPop(l, chip);
            }, true);
            // Oynadan tashqariga bosilsa yoki Esc — yopiladi.
            document.addEventListener('mousedown', ev => {
                const pop = document.getElementById('crossCycPop');
                if (pop && !pop.contains(ev.target) && !(ev.target.closest && ev.target.closest('[data-cyc]'))) closeCrossCycPop();
            });
            document.addEventListener('keydown', ev => { if (ev.key === 'Escape') closeCrossCycPop(); });

            // Para ustuni (sikl ichki jadvali kabi): qo'ng'iroq jadvalida ketma-ket bir xil
            // qisqartmali yarim paralar ("I", "I") bitta para katagiga birlashadi — chapda
            // katta rim raqami + "para", o'ngda har yarim qatorning vaqti.
            // Bo'lak katagidagi yarim-slot chiziqlari: qatorlar balandligi har xil (mazmunli qator
            // baland), shuning uchun chiziqlar foiz emas — katak qamragan haqiqiy qatorlar bo'yicha.
            function alignBolakDrops() {
                document.querySelectorAll('#grid td.tt-bolak-cell').forEach(td => {
                    const zones = td.querySelectorAll('.tt-bolak-drop');
                    if (!zones.length) return;
                    const top0 = td.getBoundingClientRect().top;
                    let tr = td.parentElement;
                    const tops = [];
                    for (let r = 0; r <= zones.length && tr; r++, tr = tr.nextElementSibling) tops.push(tr.getBoundingClientRect().top - top0);
                    const h = td.getBoundingClientRect().height;
                    zones.forEach((z, r) => {
                        if (tops[r] == null) return;
                        const t = Math.max(0, tops[r]), b = tops[r + 1] != null ? tops[r + 1] : h;
                        z.style.top = t + 'px';
                        z.style.height = Math.max(0, b - t) + 'px';
                    });
                });
            }
            // Qotirilgan sarlavha: har bir sarlavha qatori o'zidan yuqoridagi qatorlar balandligicha pastda
            // qotadi (aks holda hammasi top:0 da ustma-ust tushib, pastga aylantirganda sarlavha aralashib ketadi).
            function stickGridHead() {
                const grid = document.getElementById('grid');
                const head = grid && grid.tHead;
                if (!head) return;
                let top = 0;
                [...head.rows].forEach(tr => {
                    [...tr.cells].forEach(th => { th.style.top = top + 'px'; });
                    top += tr.getBoundingClientRect().height;
                });
            }
            window.addEventListener('resize', () => { try { alignBolakDrops(); stickGridHead(); } catch (e) { /* panjara yo'q */ } });
            function paraGroups(P, pairTime) {
                const key = p => { const t = pairTime[p]; const a = t ? String(t.abbr || '').trim() : ''; return a && a !== '—' ? a : null; };
                const out = {};
                for (let p = 1; p <= P; p++) {
                    const k = key(p);
                    let n = 1;
                    while (k && p + n <= P && key(p + n) === k) n++;
                    out[p] = { span: n, label: k || (pairTime[p] ? (pairTime[p].name || p) : p) };
                    for (let q = 1; q < n; q++) out[p + q] = { span: 0 };
                    p += n - 1;
                }
                return out;
            }
            function paraSideCells(p, P, pairTime, groups, endCls) {
                const g = groups[p], pt = pairTime[p];
                let h = '';
                if (g && g.span) {
                    const last = p + g.span - 1;
                    h += '<td class="tt-para tt-para-roman' + endCls(last) + '"' + (g.span > 1 ? ' rowspan="' + g.span + '"' : '') +
                        ' title="' + esc(pt ? (String(pt.name || '').replace(/\s*\(\d\)\s*$/, '') + ' ' + (pt.start || '') + '–' + ((pairTime[last] || pt).end || '')) : '') + '">' +
                        '<b>' + esc(g.label) + '</b><i>para</i></td>';
                }
                h += '<td class="tt-ptime' + endCls(p) + '">' + (pt && (pt.start || pt.end) ? esc(pt.start) + '<br>' + esc(pt.end) : '') + '</td>';
                return h;
            }
            function renderGrid() {
                fmSync();
                fmRenderBar();
                $('grid').classList.toggle('tt-cross-details', viewMode !== 'group' && viewMode !== 'cycle');
                // Sikl ko'rinishi — alohida kalendar (sana × guruh)
                const cycleView = viewMode === 'cycle';
                $('gridWrap').classList.toggle('hidden', cycleView);
                $('cycleArea').classList.toggle('hidden', !cycleView);
                if (cycleView) { loadCyclePlan(); return; }
                if (viewMode !== 'group') { renderGridCross(viewMode); return; }
                // Bu tanlovda haftalik fan qolmagan bo'lsa-yu, sikl fanlari bo'lsa —
                // "fanlar yo'qolmadi", ular sikl kalendarida. Yo'naltiruvchi xabar.
                if (!groupRows.length) {
                    const hasCycleHere = cards.some(c => selectedFaculties.has(c.faculty_name || '') &&
                        selectedDirs.has(c.specialty_name) && selectedCourses.has(c.course) && isCycleCardAny(c));
                    if (hasCycleHere) {
                        $('grid').innerHTML = '<tbody><tr><td class="p-6 text-sm text-gray-600 text-center">' +
                            'Bu tanlovdagi fanlar <b>sikl (blok)</b> rejimida belgilangan — ular haftalik panjarada emas, ' +
                            '<b>sikl kalendarida</b> ketma-ket kunli blok bo\'lib turadi.<br>' +
                            'Yuqoridagi <b>Kesim</b> ro\'yxatidan <b>“Sikl (4-6 kurs)”</b> ni tanlang.' +
                            '</td></tr></tbody>';
                        activeCell = null;
                        return;
                    }
                }
                const g = curGrid();
                let D = g.days;
                // Yarim-slot (qator) soni — doska qo'ng'iroq jadvalidagi "pair" elementlar
                // soni (bir "pair" = bir yarim-slot). Yo'nalish bo'yicha faqat kun soni farq
                // qilishi mumkin, para soni butun doska uchun bir xil.
                let P = boardSchedule().filter(it => it.type === 'pair').length || g.pairs_per_day;
                // Ko'rinayotgan yo'nalish/kurslarning kun soni har xil bo'lishi mumkin;
                // eng kattasini olamiz (barcha kunlar sig'sin).
                [...new Set(specCards().map(c => c.specialty_name + '|' + c.course))].forEach(k => {
                    const gg = grids[k]; if (gg) { D = Math.max(D, gg.days); }
                });
                const dayNames = boardDayNames();

                // Ustunlar: guruhlar oqim bo'yicha guruhlangan (groupRows tartibida)
                const oqimCols = [];
                let curO = null;
                groupRows.forEach(gr => {
                    const lab = gr.oqim_label || '';
                    const fac = gr.faculty || '';
                    const spec = gr.specialty || '';
                    const crs = gr.course;
                    // Fakultet / yo'nalish / kurs o'zgarsa ham yangi oqim bloki (turli
                    // fakultet/yo'nalish/kursning bir xil nomli oqimlari birlashib ketmasin).
                    if (!curO || curO.label !== lab || curO.faculty !== fac || curO.specialty !== spec || curO.course !== crs) {
                        curO = { label: lab, faculty: fac, specialty: spec, course: crs, groups: [] }; oqimCols.push(curO);
                    }
                    // Ustunlar guruh KALITI bo'yicha (nom takrorlanishi mumkin)
                    curO.groups.push(gr.key);
                });
                // Kalit → ko'rinadigan guruh nomi (sarlavha va asos-guruh chegarasi uchun)
                const gName = {};
                groupRows.forEach(gr => { gName[gr.key] = gr.group; });

                // Para → nomi/qisqartma va boshlanish-tugash vaqti (sozlangan qo'ng'iroq jadvalidan).
                // Panjaradagi p-chi para = jadvaldagi p-chi "pair" element (tartib bo'yicha).
                const pairTime = {};
                boardSchedule().filter(it => it.type === 'pair').forEach((it, i) => {
                    pairTime[i + 1] = { name: it.name || '', abbr: it.abbr || '', start: it.start || '', end: it.end || '' };
                });

                // Joylashgan kartalar indeksi: group|day|pair → karta. `pair` — yarim-slot
                // indeksi; dars cardLen(c) ta yarim-slotni egallaydi, shuning uchun karta
                // qamragan HAR bir yarim-slotga yoziladi (band/konflikt/rowspan tekshiruvi uchun).
                const placedIdx = {};
                // Bir katakni bo'lishadigan darslar: hech qachon bir haftaga
                // tushmaydigan kartalar (toq/juft haftalardagi ma'ruzalar,
                // ma'ruza va uni almashtiruvchi amaliy) bitta slotda tura oladi.
                // placedIdx katakka bittasini saqlaydi — qolganlari yo'qolmasligi
                // uchun ular alohida ro'yxatda yig'iladi va shu katakda birga
                // chiziladi. Hafta ko'rinishida ro'yxatda faqat bittasi qoladi.
                const cellStack = {};
                visibleSpecCards().forEach(c => {
                    const pl = effPlace(c);
                    if (!pl) return;
                    const ec = effectiveCard(c);
                    const len = cardLen(ec);
                    cardGroups(ec).forEach(gg => {
                        const base = gkey(ec, gg) + '|' + pl.day;
                        (cellStack[base + '|' + pl.pair] = cellStack[base + '|' + pl.pair] || []).push(ec);
                        for (let k = 0; k < len; k++) { const key = base + '|' + (pl.pair + k); if (!placedIdx[key] || (!curWeek && ec.training_type === 'lecture')) placedIdx[key] = ec; }
                    });
                });
                // Shu katakda boshlanadigan, lekin asosiy chipda ko'rsatilmagan darslar
                const stackExtras = (grp, d, p, ids) => {
                    const list = cellStack[grp + '|' + d + '|' + p];
                    if (!list || list.length < 2) return [];
                    const shown = new Set(ids && ids.length ? ids : []);
                    return list.filter(x => !shown.has(x.id));
                };

                // Vertikal qamrov: karta o'zining cardLen(c) yarim-slotini to'ldiradi; qo'shimcha
                // ravishda ketma-ket bir xil fan kartalari (masalan "para qo'shish" bilan)
                // bitta katakka (rowspan) birlashtiriladi. vConsumed — yuqoridagi rowspan
                // qamragan (chiqarilmaydigan) kataklar. vChain — jami yarim-slot uzunligi
                // va tarkibidagi karta id'lari (badge uchun).
                const vConsumed = {};
                // Shablon ko'rinishida faqat bir xil haftalarda o'tiladigan kartalar birlashtiriladi:
                // har hafta o'tiladigan (15 hafta) va almashib keladigan (masalan 9 hafta) qism
                // alohida chiziladi — ikkinchisi yo'l-yo'l (⇄) bo'lib ajralib tursin.
                // Kalit — o'tiladigan haftalarning TO'LIQ ro'yxati (activeWeeksOf ko'rinish uchun 10 tadan keyin qisqartiradi:
                // 12 va 11 haftalik qismlar bir xil chiqib, birlashib ketardi).
                const weeksKey = x => {
                    if (curWeek) return '';
                    const out = [];
                    for (let w = 1, total = Math.max(1, +curGrid().weeks || 0); w <= total; w++) {
                        const ov = overrides[x.id + '|' + w];
                        if (!(ov && ov.cancelled)) out.push(w);
                    }
                    return out.join(',');
                };
                const vChain = (grp, d, p, c) => {
                    const ids = [];
                    let span = 0, cur = p;
                    const wk = weeksKey(c);
                    while (true) {
                        const n = placedIdx[grp + '|' + d + '|' + cur];
                        if (!n || n.training_type !== c.training_type || n.subject_name !== c.subject_name) break;
                        if (weeksKey(n) !== wk) break;
                        ids.push(n.id);
                        span += cardLen(n);
                        cur += cardLen(n);
                    }
                    return { span: span || cardLen(c), ids: ids.length ? ids : [c.id] };
                };

                // shade — bitta katakda bir necha almashinuvchi karta bo'lsa, ularni
                // biroz och/to'q qilib farqlash uchun (0 = ochroq, 1 = to'qroq).
                const chipHtml = (c, ids, shade) => {
                    const merged = ids && ids.length > 1;
                    const mids = merged ? ' data-merge-ids="' + ids.join(',') + '"' : '';
                    // Birlashgan blokning umumiy davomiyligi — kartalar soni emas, soat (yarim-slot = 1 soat):
                    // 2 soat + 1 soat = "3 soat", 2 + 2 = "4 soat".
                    const mergedHours = merged ? ids.reduce((sum, id) => {
                        const x = cards.find(k => k.id === id);
                        return sum + (x ? cardLen(x) : 0);
                    }, 0) : 0;
                    const badge = merged ? '<span class="tt-merge-badge" title="' + ids.length + ' ta karta">' + mergedHours + ' soat</span>' : '';
                    // Karta necha hafta o'tiladi: "(N hafta)". Semestrning HAR haftasida
                    // o'tiladigan dars uchun buni yozish shart emas — 1 soatmi, 3 soatmi,
                    // farqi yo'q. "Har hafta"ni karta haftalar sonidan emas, hafta
                    // istisnolaridan aniqlaymiz: bitta ham bekor qilingan hafta bo'lmasa,
                    // dars butun semestr davomida o'tiladi.
                    const fullWeeks = curGrid().weeks;
                    const skipsWeeks = (activeWeeksOf(c, fullWeeks).length > 0)
                        || (c.weeks && c.weeks < fullWeeks);
                    const showWks = !!(c.weeks && skipsWeeks);
                    // Qaysi haftalarda o'tilishi — hafta istisnolaridan (cancelled emas)
                    const wkList = showWks ? activeWeeksOf(c, fullWeeks) : [];
                    const wkNums = wkList.length ? ': ' + wkList.join(',') : '';
                    const wks = showWks
                        ? ' <span class="tt-weeks">(' + c.weeks + ' hafta' + wkNums + ')</span>' : '';
                    // Auditoriya raqami (kod) — sig'imi bilan; tooltipда to'liq nomi
                    const roomNo = String(c.auditorium_name || c.auditorium_code || '').replace(/^№\s*/u, '');
                    const capLine = weeklyCapLine(c);
                    const roomOff = roomInactive(c.auditorium_code);
                    const roomTxt = roomNo
                        ? '<div class="tt-room">№ ' + esc(roomNo) + (capLine ? ' <span class="tt-cap-warn" title="' + esc(capLine) + '">⚠ sig\'maydi</span>' : '')
                            + (roomOff ? ' <span class="tt-room-off" title="' + esc(ROOM_OFF_TEXT) + '">⚠ nofaol</span>' : '') + '</div>'
                        : '';
                    // Almashinuvchi karta — har hafta emas, faqat ayrim haftalarda o'tiladi
                    // (ma'ruza va uni almashtiruvchi amaliy). Shablon ("Barcha haftalar")
                    // ko'rinishida yo'l-yo'l fon + ⇄ belgisi bilan ajratib turadi, chunki
                    // u yerda barcha variantlar ustma-ust ko'rinadi.
                    const alt = !curWeek && showWks;
                    const altMark = alt ? '<span class="tt-alt-mark" title="Har hafta emas — almashib keladi">⇄</span>' : '';
                    const tri = shade === 0 ? ' tt-shade-a tt-tri-a' : shade === 1 ? ' tt-shade-b tt-tri-b' : '';
                    // Vaqtincha kafedra mudirida — kulrang-sariq ramka, yorliq va tooltip (asl o'qituvchi, sabab, kim/qachon).
                    const ph = phOf(c);
                    const phTip = ph ? '\nVaqtincha: kafedra mudiri' + (ph.mudir_name ? ' (' + ph.mudir_name + ')' : '') + ' · asl o\'qituvchi: ' + (ph.orig_teacher_name || 'biriktirilmagan')
                        + ', asl xona: ' + (ph.orig_room_name || c.auditorium_name || '—') + (ph.reason ? '\nSabab: ' + ph.reason : '')
                        + (ph.by_name ? '\nYozgan: ' + ph.by_name + (ph.at ? ', ' + ph.at : '') : '') : '';
                    const head = '<div class="tt-chip ' + (c.training_type === 'lecture' ? 'lec' : 'prc') + infoOnlyClass(c) +
                        (alt ? ' tt-alt' : '') + (ph ? ' tt-mudir-ph' : '') + tri +
                        (selected && selected.id === c.id ? ' sel' : '') + '" style="' + subjStyle(c) +
                        '" data-chip="' + c.id + '"' + mids + ' title="' +
                        esc(cardTooltip(c, (showWks ? 'Haftalar: ' + c.weeks + ' hafta' + wkNums : '')
                            + (alt ? ' · har hafta emas (almashib keladi)' : '') + (capLine ? '\n' + capLine : '') + phTip)) + '">';
                    const phTag = ph ? '<div class="tt-mudir-ph-tag">vaqtincha: kafedra mudiri</div>' : '';
                    // Uchburchakka bo'lingan katakda fan nomi, qaysi haftalarda
                    // o'tilishi va xona raqami ko'rinadi. O'qituvchi tooltipda
                    // qoladi — uchburchakka sig'may, yozuvni buzadi.
                    if (tri) {
                        return head + '<span class="tt-tri-name">' + cardLabel(c, true) + wks + roomTxt + phTag + '</span></div>';
                    }
                    // O'qituvchi «Faqat meniki» ko'rinishida — o'z darsi uchun vaqt o'zgarishi so'rovi (ichki jadval, aniq hafta).
                    const askTime = TIMETABLE_ROLE === 'oqituvchi' && scopeMode === 'mine' && +c.teacher_id === +TIMETABLE_TEACHER_ID
                        && weeklyLayer === 'internal' && curWeek
                        ? '<button type="button" class="tt-ask-time" data-ask-time="' + c.id + '">Vaqtini o\'zgartirishni so\'rash</button>' : '';
                    return head +
                        altMark + cardLabel(c, true) + wks + badge +
                        ((ph ? ph.teacher_name : c.teacher_name) ? '<div class="text-[9px] text-gray-600">' + esc(ph ? ph.teacher_name : c.teacher_name) + '</div>' : '') +
                        roomTxt + phTag + parallelBadgeHtml(c) + askTime +
                        '</div>';
                };

                // Asos guruh kaliti: til qo'shimchasi "(o'z)" va a/b pastki guruh harfini olib tashlab
                // (masalan "1K-01a (o'z)" → "1K-01"). Bir asos guruh = a va b pastki guruhlari.
                const baseKey = gn => String(gn).replace(/\s*\([^)]*\)\s*$/, '').replace(/[a-z]$/i, '');
                // Ustun chap chegara sinfi: oqim boshi (qo'sh chiziq) yoki asos guruh boshi (qalin chiziq)
                // groups — guruh KALITLARI; asos-guruh solishtiruvi ko'rinadigan nom bo'yicha
                const colBorder = (oqimIdx, gi, groups) => {
                    if (gi === 0) return oqimIdx > 0 ? ' sep-oqim' : '';
                    return baseKey(gName[groups[gi]] || '') !== baseKey(gName[groups[gi - 1]] || '') ? ' sep-base' : '';
                };

                // Fakultet sarlavhasi (Excel dars jadvali kabi): guruh → fakultet xaritasidan
                // qo'shni bir xil fakultet ustunlari bitta blokka birlashtiriladi.
                const facOf = {};
                groupRows.forEach(gr => { facOf[gr.key] = gr.faculty || ''; });
                const facRuns = [];
                oqimCols.forEach(o => o.groups.forEach(gr => {
                    const f = facOf[gr] || '';
                    const last = facRuns[facRuns.length - 1];
                    if (last && last.faculty === f) last.span++; else facRuns.push({ faculty: f, span: 1 });
                }));
                const showFac = facRuns.some(r => r.faculty);
                const corSpan = showFac ? 3 : 2;

                const courseCls = course => ' tt-course-' + (((+course || 1) - 1) % 6 + 1);

                // Sarlavha: Kun | Para | [fakultet] | oqim | guruhlar
                let h = '<thead><tr>' +
                    '<th class="tt-corner px-1 py-1" rowspan="' + corSpan + '" style="width:26px;min-width:26px;max-width:26px">Kun</th>' +
                    '<th class="tt-corner px-1 py-1" rowspan="' + corSpan + '" colspan="2" style="left:26px">Para</th>';
                if (showFac) {
                    facRuns.forEach((r, ri) => h += '<th class="tt-fac px-2 py-1' + (ri > 0 ? ' sep-oqim' : '') + '" colspan="' + r.span + '">' + esc(r.faculty || '—') + '</th>');
                    h += '</tr><tr>';
                }
                const multiCourse = selectedCourses.size > 1;
                const showSpec = multiSpec();
                const grpCount = (o, gr) => groupStudents[(o.faculty || '') + '|' + (gName[gr] || '')];
                oqimCols.forEach((o, oi) => {
                    const flowKey = (o.faculty || '') + '|' + (o.specialty || '') + '|' + o.course + '|' + (o.label || '');
                    const known = o.groups.map(gr => grpCount(o, gr)).filter(n => n != null);
                    // Faol talabalar (students) bo'yicha; ma'lumot bo'lmasa — kartalardagi son.
                    const studentCount = known.length ? known.reduce((a, b) => a + (+b || 0), 0) : flowStudents[flowKey];
                    const title = (showSpec && o.specialty ? o.specialty + ' · ' : '') +
                        (multiCourse ? o.course + '-kurs · ' : '') + (o.label || '—');
                    h += '<th class="tt-oqim px-2 py-1' + courseCls(o.course) + (oi > 0 ? ' sep-oqim' : '') + '" colspan="' + o.groups.length + '">' +
                        '<div>' + esc(title) + '</div>' +
                        (studentCount ? '<div class="tt-oqim-count">' + o.groups.length + ' guruh · ' + studentCount + ' talaba</div>' : '') +
                    '</th>';
                });
                h += '</tr><tr>';
                oqimCols.forEach((o, oi) => o.groups.forEach((gr, gi) => {
                    const n = grpCount(o, gr);
                    h += '<th class="tt-grp px-2 py-1' + courseCls(o.course) + colBorder(oi, gi, o.groups) + '" data-gh="' + esc(gr) + '">' + esc(gName[gr] || '') +
                        (n != null ? '<div class="tt-grp-count"><em class="tt-stu-count" title="' + n + ' ta faol talaba">' + n + '</em></div>' : '') + '</th>';
                }));
                h += '</tr></thead><tbody>';

                // Para ajratuvchi chiziq darajasi: shu qatorda TUGAYDIGAN katak uchun
                // (endP = boshlanish parasi + rowspan - 1). Kun oxiri (endP===P) — eng
                // qalin; juft endP — ikki butun para orasi (qalinroq); toq endP — bitta
                // butun paraning ikki yarmi orasi (sukut, yupqa — qo'shimcha sinf kerak emas).
                const rowEndCls = endP => endP === P ? ' tt-dayend' : (endP % 2 === 0 ? ' tt-paraend' : '');
                const pGroups = paraGroups(P, pairTime);
                // Bo'lakli fan amaliyoti ("Fan (a)/(b)/(c)") — bitta asos guruh (02a+02b) uchun bitta katak:
                // tepada fanning asosiy nomi, pastida bo'laklar ro'yxati (harf · guruhcha · talaba).
                // Har bo'lak alohida bosiladi/sudraladi; sarlavhani sudrasa — hamma bo'lak birga ko'chadi.
                const bolakBaseOf = x => { const m = BOLAK_RX.exec(String(x.subject_name || '').trim()); return m ? m[1].trim() : null; };
                const bolakLetterOf = x => { const m = BOLAK_RX.exec(String(x.subject_name || '').trim()); return m ? m[2] : ''; };
                const shortGroup = g => String(g).replace(/\s*\(.*\)\s*$/, '').split('-').pop();
                // Bo'lak kechroq boshlanishi mumkin (masalan (a) 12:40 da, (b)/(c) 12:00 da): katak
                // shu asos guruhdagi barcha bo'laklarni qamraydi (rowspan — eng oxirgi tugashgacha),
                // har bo'lak qatorida o'z vaqti yoziladi, katak ichida yarim-slot tushish chiziqlari bor.
                const bolakCell = (o, oi, gi, d, p) => {
                    const startList = (g, q) => (cellStack[g + '|' + d + '|' + q] || []).filter(x => x.training_type !== 'lecture');
                    const l0 = startList(o.groups[gi], p);
                    const B = l0.length ? bolakBaseOf(l0[0]) : null;
                    if (!B || !l0.every(x => bolakBaseOf(x) === B)) return null;
                    const isB = x => bolakBaseOf(x) === B;
                    const startOf = x => { const pl = effPlace(x); return pl ? +pl.pair : p; };
                    // Guruh ustunining [p, end) oralig'idagi bo'laklari; begona dars bo'lsa — null
                    const gather = (g, end, late) => {
                        const out = [];
                        for (let q = p; q < end; q++) {
                            if (q > p && vConsumed[g + '|' + d + '|' + q]) return null;
                            const l = startList(g, q);
                            const occ = placedIdx[g + '|' + d + '|' + q];
                            if (occ && occ.training_type !== 'lecture' && !isB(occ)) return null;
                            if (occ && occ.training_type === 'lecture') return null;
                            if (q > p && !late) { if (l.length) return null; continue; }
                            if (!l.every(isB)) return null;
                            out.push(...l);
                        }
                        return out;
                    };
                    const build = late => {
                        let end = p + Math.max(...l0.map(cardLen));
                        if (!late && !l0.every(x => cardLen(x) === end - p)) return null;
                        let span = 1, guard = 0;
                        while (guard++ < 8) {
                            let items = [];
                            for (let k = 0; k < span; k++) {
                                const l = gather(o.groups[gi + k], end, late);
                                if (!l) return null;
                                items.push(...l);
                            }
                            // Qo'shni ustunlar (shu asos guruh) — ularda ham shu fan bo'laklari bo'lsa
                            const bg = baseKey(gName[o.groups[gi]] || '');
                            while (gi + span < o.groups.length) {
                                const g2 = o.groups[gi + span];
                                if (baseKey(gName[g2] || '') !== bg || vConsumed[g2 + '|' + d + '|' + p]) break;
                                const l2 = gather(g2, end, late);
                                if (!l2 || !l2.length) break;
                                if (!late && !l2.every(x => startOf(x) === p && cardLen(x) === end - p)) break;
                                items.push(...l2);
                                span++;
                            }
                            const map = new Map(items.map(x => [x.id, x]));
                            items = [...map.values()];
                            let newEnd = Math.max(end, ...items.map(x => startOf(x) + cardLen(x)));
                            // Bo'lakning davomi (masalan 2 soat + 1 soat) aynan katak tugagan joydan boshlansa — qo'shamiz
                            if (late && newEnd === end) {
                                for (let k = 0; k < span; k++) {
                                    const nx = startList(o.groups[gi + k], end);
                                    if (nx.length && nx.every(y => isB(y) && items.some(x => x.subject_name === y.subject_name
                                        && cardGroups(x).join(',') === cardGroups(y).join(',') && startOf(x) + cardLen(x) === end))) {
                                        newEnd = Math.max(newEnd, ...nx.map(y => end + cardLen(y)));
                                    }
                                }
                            }
                            if (newEnd === end) return { span, end, items };
                            if (!late) return null;
                            end = newEnd;
                        }
                        return null;
                    };
                    const res = build(true) || build(false);
                    if (!res) return null;
                    const { span, end } = res;
                    const items = res.items.sort((a, b) => startOf(a) - startOf(b) || bolakLetterOf(a).localeCompare(bolakLetterOf(b)) || a.id - b.id);
                    const vs = end - p;
                    for (let r = 1; r < vs; r++) for (let k = 0; k < span; k++) vConsumed[o.groups[gi + k] + '|' + d + '|' + (p + r)] = 1;
                    const first = items[0];
                    const parts = B.split(/\.\s+/).filter(Boolean);
                    const shortB = parts.length > 1 ? parts[parts.length - 1] : B;
                    const ids = items.map(x => x.id).join(',');
                    const offs = items.map(x => startOf(x) - p).join(',');
                    const tStart = q => (pairTime[q] && pairTime[q].start) || '';
                    const tEnd = q => (pairTime[q] && pairTime[q].end) || '';
                    // Bitta bo'lakning ketma-ket qismlari (masalan 2 soat + 1 soat) — bitta qator:
                    // { x: birinchi karta, ids, s: boshlanish, e: tugash (yarim-slot, istisno) }
                    const chains = [];
                    items.forEach(x => {
                        const sx = startOf(x), gk = cardGroups(x).join(',');
                        // O'qituvchi/xona farq qilsa, ikkinchi qismning rekvizitlari yashirinmasin.
                        const prev = chains.find(ch => ch.x.subject_name === x.subject_name && ch.gk === gk && ch.e === sx
                            && (ch.x.teacher_id || null) === (x.teacher_id || null)
                            && (ch.x.auditorium_code || null) === (x.auditorium_code || null));
                        if (prev) { prev.ids.push(x.id); prev.e = sx + cardLen(x); }
                        else chains.push({ x, gk, ids: [x.id], s: sx, e: sx + cardLen(x) });
                    });
                    chains.sort((a, b) => a.s - b.s || bolakLetterOf(a.x).localeCompare(bolakLetterOf(b.x)) || a.x.id - b.x.id);
                    // Vaqt — bo'laklar boshlanishi/tugashi har xil bo'lsa har qatorda ko'rsatiladi
                    const varied = chains.some(ch => ch.s !== p || ch.e !== end);
                    // Katak paradan oshib ketsa (masalan 3 soat: II para + III ning yarmi) — umumiy vaqt sarlavhada
                    const paraOf = q => { let a = q; while (a > 1 && pGroups[a] && pGroups[a].span === 0) a--; return a; };
                    const headTime = !varied && paraOf(end - 1) !== paraOf(p) ? ' <span class="tt-bolak-time">' + esc(tStart(p) + '–' + tEnd(end - 1)) + '</span>' : '';
                    const head = '<div class="tt-bolak-head" data-chip="' + first.id + '" data-parallel-ids="' + ids + '" data-parallel-offs="' + offs + '" title="' +
                        esc(B + ' — amaliy, ' + items.length + " ta bo'lak parallel (sarlavhani sudrasangiz hammasi birga ko'chadi; bitta bo'lakni katak ichidagi chiziqqa sudrab boshlanish vaqtini o'zgartiring)") + '"><b>[A]</b> ' + esc(shortB) + headTime + infoOnlyBadgeHtml(first) + '</div>';
                    const rows = chains.map(ch => {
                        const x = ch.x, sx = ch.s, late = sx > p;
                        const tm = tStart(sx) + '–' + tEnd(ch.e - 1);
                        // Qismlar birga, o'z siljishi bilan ko'chadi (2 soat + 1 soat ketma-ket qoladi)
                        const mids = ch.ids.length > 1 ? ' data-parallel-ids="' + ch.ids.join(',') + '" data-parallel-offs="' +
                            ch.ids.map(id => startOf(items.find(y => y.id === id)) - ch.s).join(',') + '"' : '';
                        return '<div class="tt-bolak-item' + (late ? ' tt-bolak-late' : '') + (selected && ch.ids.includes(selected.id) ? ' sel' : '') + '" data-chip="' + x.id + '"' + mids + ' title="' + esc(cardTooltip(x, 'Vaqt: ' + tm + (ch.ids.length > 1 ? ' (' + ch.ids.length + ' qism)' : ''))) + '">' +
                            '<b class="tt-bolak-tag">' + esc(bolakLetterOf(x)) + '</b> ' + esc(cardGroups(x).map(shortGroup).join('+')) +
                            (varied ? '<span class="tt-bolak-time">' + (late ? '⏵ ' : '') + esc(tm) + '</span>' : '') +
                            '<span class="tt-bolak-n">' + (x.students || '') + '</span>' +
                            (x.teacher_name ? '<span class="tt-bolak-t">' + esc(String(x.teacher_name).split(' ')[0]) + '</span>' : '') + '</div>';
                    }).join('');
                    // Katak ichidagi yarim-slot tushish chiziqlari (12:00 / 12:40 ...)
                    let drops = '';
                    if (vs > 1) {
                        drops = '<div class="tt-bolak-drops">';
                        // Joyi render'dan keyin haqiqiy qator balandliklari bo'yicha qo'yiladi (alignBolakDrops)
                        for (let r = 0; r < vs; r++) drops += '<div class="tt-bolak-drop" data-drop-day="' + d + '" data-drop-pair="' + (p + r) + '" data-r="' + r + '" style="top:' + (r * 100 / vs) + '%;height:' + (100 / vs) + '%"><i>' + esc(tStart(p + r)) + '</i></div>';
                        drops += '</div>';
                    }
                    const cs = span > 1 ? ' colspan="' + span + '"' : '';
                    const rs = vs > 1 ? ' rowspan="' + vs + '"' : '';
                    return { span, html: '<td class="tt-cell tt-bolak-cell' + infoOnlyClass(first) + courseCls(o.course) + colBorder(oi, gi, o.groups) + rowEndCls(p + vs - 1) + '"' + cs + rs +
                        ' data-day="' + d + '" data-pair="' + p + '" style="' + subjStyle(first) + '">' + drops + head + '<div class="tt-bolak-list">' + rows + '</div></td>' };
                };

                for (let d = 1; d <= D; d++) {
                    for (let p = 1; p <= P; p++) {
                        h += '<tr>';
                        if (p === 1) h += '<td class="tt-day" rowspan="' + P + '">' + esc(dayNames[d - 1] || ('Kun ' + d)) + '</td>';
                        h += paraSideCells(p, P, pairTime, pGroups, rowEndCls);
                        oqimCols.forEach((o, oi) => {
                            // Har katakka kun/para — drag-and-drop tashlash nishoni uchun
                            const dp = ' data-day="' + d + '" data-pair="' + p + '"';
                            // Tanlangan ma'ruza — butun oqimga bitta birlashtirilgan nishon (colspan).
                            // Ko'p tanlovda faqat o'z fakulteti+yo'nalishi oqimi yonadi.
                            if (selected && selected.training_type === 'lecture' && (selected.oqim_label || '') === o.label
                                && (selected.faculty_name || '') === o.faculty && (selected.specialty_name || '') === o.specialty
                                && selected.course === o.course) {
                                const occupied = o.groups.some(gr => placedIdx[gr + '|' + d + '|' + p]);
                                if (!occupied) {
                                    // Band bo'lsa — turi rang bilan, sababi title da; faqat xona band (sariq) — bosilsa boshqa xona bilan joylash.
                                    const v = placeVerdict(conflictsAtDetail(selected, d, p));
                                    const bad = v.tone !== 'ok';
                                    h += '<td class="tt-cell' + (bad ? placeBadCls(v) : ' tt-ok') + courseCls(o.course) + colBorder(oi, 0, o.groups) + rowEndCls(p) + '" colspan="' + o.groups.length + '"' + dp +
                                        (bad ? ' title="' + esc(v.title) + '"' + placeCauseAttr(v) + (v.tone === 'room' ? ' data-room-place="' + d + '-' + p + '"' : '')
                                            : ' data-place="' + d + '-' + p + '"') + '></td>';
                                    return;
                                }
                            }
                            // Oddiy yurish: ma'ruzani oqim guruhlari bo'ylab birlashtirish, amaliy/bo'sh — alohida
                            let gi = 0;
                            while (gi < o.groups.length) {
                                const grp = o.groups[gi];
                                // Yuqoridagi vertikal birlashma (rowspan) qamragan bo'lsa — katak chiqarmaymiz
                                if (vConsumed[grp + '|' + d + '|' + p]) { gi++; continue; }
                                const bord = colBorder(oi, gi, o.groups);
                                let c = placedIdx[grp + '|' + d + '|' + p];
                                // placedIdx karta egallagan barcha yarim-slotlarni saqlaydi.
                                // Kartani faqat haqiqiy boshlanish qatorida chizamiz; aks holda
                                // bloklangan birinchi slot sabab ikkinchi slot yangi darsdek chiqadi.
                                if (c) {
                                    const cPlace = effPlace(c);
                                    if (!cPlace || +cPlace.pair !== p) c = null;
                                }
                                if (c && c.training_type !== 'lecture') {
                                    const bc = bolakCell(o, oi, gi, d, p);
                                    if (bc) { h += bc.html; gi += bc.span; continue; }
                                }
                                if (c && c.training_type === 'lecture') {
                                    // Gorizontal birlashma: bir xil karta yoki AYNAN SHU fanning
                                    // ma'ruzasi bo'lsa — bitta katak. Bir oqimdagi guruhlar
                                    // (fakultetlararo qo'shilganlari ham) alohida kartada
                                    // bo'lishi mumkin, lekin dars bitta — bo'linib ko'rinmasin.
                                    let span = 1;
                                    while (gi + span < o.groups.length) {
                                        const c2 = placedIdx[o.groups[gi + span] + '|' + d + '|' + p];
                                        const c2Place = c2 ? effPlace(c2) : null;
                                        if (c2 && c2Place && +c2Place.pair === p && (c2.id === c.id ||
                                            (c2.training_type === 'lecture' && c2.subject_name === c.subject_name))) span++;
                                        else break;
                                    }
                                    // Vertikal: karta o'z uzunligini (yarim-slotlar) egallaydi;
                                    // ketma-ket bir xil fan ma'ruzalari ham birlashtiriladi.
                                    const chain = vChain(o.groups[gi], d, p, c);
                                    const vs = chain.span, ids = chain.ids;
                                    for (let k = 1; k < vs; k++)
                                        for (let gg = gi; gg < gi + span; gg++)
                                            vConsumed[o.groups[gg] + '|' + d + '|' + (p + k)] = 1;
                                    const rs = vs > 1 ? ' rowspan="' + vs + '"' : '';
                                    // Ma'ruza katagi bir necha guruh ustunini qamrab oladi
                                    // (colspan), amaliy esa bitta guruhniki — shuning uchun
                                    // ma'ruza katagida faqat MA'RUZA kartalari chiziladi.
                                    const lecEx = stackExtras(o.groups[gi], d, p, ids)
                                        .filter(x => x.training_type === 'lecture');
                                    // Bir katakda bir necha almashinuvchi fan — diagonal ajratgich
                                    const lecSplit = lecEx.length ? ' tt-split' : '';
                                    const lecExtras = lecEx.map((x, xi) => chipHtml(x, [x.id], xi + 1)).join('');
                                    h += '<td class="tt-cell tt-lec' + lecSplit + courseCls(o.course) + bord + rowEndCls(p + vs - 1) + '" colspan="' + span + '"' + rs + dp + ' data-gs="' + esc(o.groups.slice(gi, gi + span).join('§')) + '" style="' + subjStyle(c) + '">' + infoOnlyGroupOverlapHtml([c, ...stackExtras(o.groups[gi], d, p, ids)]) + chipHtml(c, ids, lecEx.length ? 0 : undefined) + lecExtras + '</td>';
                                    gi += span;
                                } else if (c) {
                                    // Vertikal: karta o'z uzunligini (yarim-slotlar) egallaydi;
                                    // ketma-ket bir xil fan amaliyotlari ham bitta katakka birlashtiriladi.
                                    let span = 1;
                                    while (gi + span < o.groups.length) {
                                        const c2 = placedIdx[o.groups[gi + span] + '|' + d + '|' + p];
                                        const c2Place = c2 ? effPlace(c2) : null;
                                        if (c2 && c2Place && +c2Place.pair === p && c2.id === c.id) span++;
                                        else break;
                                    }
                                    const chain = vChain(grp, d, p, c);
                                    const vs = chain.span, ids = chain.ids;
                                    for (let k = 1; k < vs; k++)
                                        for (let gg = gi; gg < gi + span; gg++)
                                            vConsumed[o.groups[gg] + '|' + d + '|' + (p + k)] = 1;
                                    const rs = vs > 1 ? ' rowspan="' + vs + '"' : '';
                                    const prcEx = stackExtras(grp, d, p, ids)
                                        .filter(x => x.training_type !== 'lecture');
                                    const prcSplit = prcEx.length ? ' tt-split' : '';
                                    const prcExtras = prcEx.map((x, xi) => chipHtml(x, [x.id], xi + 1)).join('');
                                    const cs = span > 1 ? ' colspan="' + span + '"' : '';
                                    h += '<td class="tt-cell' + prcSplit + courseCls(o.course) + bord + rowEndCls(p + vs - 1) + '"' + cs + rs + dp + ' data-gs="' + esc(o.groups.slice(gi, gi + span).join('§')) + '" style="' + subjStyle(c) + '">' + infoOnlyGroupOverlapHtml([c, ...stackExtras(grp, d, p, ids)]) + chipHtml(c, ids, prcEx.length ? 0 : undefined) + prcExtras + '</td>';
                                    gi += span;
                                } else {
                                    // Bo'sh katak — tanlangan amaliy uchun nishon bo'lishi mumkin
                                    let cls = 'tt-cell' + courseCls(o.course) + bord + rowEndCls(p), clickable = '';
                                    if (mudirPick && cardGKeys(mudirPick).includes(grp)) {
                                        // "Vaqtincha kafedra mudiriga yozish": har qanday bo'sh katak (to'qnashuv tekshirilmaydi).
                                        cls += ' tt-ok'; clickable = ' data-mudir-place="' + d + '-' + p + '"';
                                    } else if (fmPick && cardGKeys(fmPick.card).includes(grp)) {
                                        // Fan mas'uli "Joylash": holat serverdan (responsible-move/grid) — kun × boshlanish qatori.
                                        const fc = fmCell(d, p);
                                        if (fc) { const t = fmCellAttrs(fc, d, p); cls += t.cls; clickable = t.attrs; }
                                    } else if (selected && selected.training_type === 'practice' && cardGKeys(selected).includes(grp)) {
                                        const v = placeVerdict(conflictsAtDetail(selected, d, p));
                                        if (v.tone !== 'ok') {
                                            cls += placeBadCls(v);
                                            clickable = ' title="' + esc(v.title) + '"' + placeCauseAttr(v) + (v.tone === 'room' ? ' data-room-place="' + d + '-' + p + '"' : '');
                                        } else { cls += ' tt-ok'; clickable = ' data-place="' + d + '-' + p + '"'; }
                                    }
                                    h += '<td class="' + cls + '"' + dp + ' data-g="' + esc(grp) + '"' + clickable + '></td>';
                                    gi++;
                                }
                            }
                        });
                        h += '</tr>';
                    }
                }
                h += '</tbody>';
                $('grid').innerHTML = h;
                alignBolakDrops();
                stickGridHead();
                activeCell = null;   // qayta render — eski faol katak eskirdi
                focusHighlight();
                markPickColumns();

                // Yashil katakni bosish — joylash (shablon yoki tanlangan hafta)
                document.querySelectorAll('[data-mudir-place]').forEach(td => td.onclick = () => {
                    if (!mudirPick) return;
                    const [d, p] = td.dataset.mudirPlace.split('-').map(Number);
                    openMudirPhConfirm(mudirPick, { day: d, pair: p });
                });
                document.querySelectorAll('[data-place]').forEach(td => td.onclick = () => {
                    if (!selected) return;
                    const [d, p] = td.dataset.place.split('-').map(Number);
                    placeCardAt(selected, d, p);
                });
                // Fan mas'uli: yashil / sariq katak — katak yonida tasdiq oynasi (sariqda xona tanlash majburiy).
                document.querySelectorAll('#grid [data-fm-place]').forEach(td => td.onclick = () => {
                    if (!fmPick) return;
                    const [d, p] = td.dataset.fmPlace.split('-').map(Number);
                    fmOpenConfirm(d, p, td);
                });
                // Sariq (faqat xona band) — boshqa (bo'sh, sig'adigan) xona tanlab joylash.
                document.querySelectorAll('[data-room-place]').forEach(td => td.onclick = () => {
                    if (!selected) return;
                    const [d, p] = td.dataset.roomPlace.split('-').map(Number);
                    openPlaceRoomPick(selected, d, p);
                });
                // Ranglar izohi — karta joylash uchun tanlanganda.
                const legend = document.getElementById('ttPlaceLegend');
                if (legend) legend.hidden = !(selected && !mudirPick && !TIMETABLE_READ_ONLY);

                document.querySelectorAll('[data-ask-time]').forEach(el => el.onclick = (ev) => {
                    ev.stopPropagation();
                    openTeacherTimeProposal(cards.find(x => x.id === +el.dataset.askTime));
                });
                // Joylashgan chipni bosish — tanlash + modal
                document.querySelectorAll('[data-chip]').forEach(el => el.onclick = (ev) => {
                    ev.stopPropagation();
                    const c = cards.find(x => x.id === +el.dataset.chip);
                    if (TIMETABLE_ROLE === 'oqituvchi') { openTeacherTimeProposal(c); return; }
                    selected = c;
                    openModal(c);
                    renderPanel(); renderGrid();
                });

                // ===== Drag-and-drop (aSc Timetables uslubida) =====
                // Joylashgan chiplar ham sudraladi. Birlashtirilgan (ketma-ket)
                // chip — butun blok bo'lib ko'chadi (data-merge-ids).
                document.querySelectorAll('#grid [data-chip]').forEach(el => {
                    el.setAttribute('draggable', 'true');
                    el.addEventListener('dragstart', ev => {
                        ev.stopPropagation();
                        // Fan mas'uli: mas'ul fani darsi — o'z "Joylash" rejimi bilan (tashlansa — tasdiq oynasi: to'qnashuvdagi — darhol, to'qnashuvsiz
                        // joylashgan — so'rov); boshqalari sudralmaydi.
                        if (TIMETABLE_ROLE === 'fan_masuli') { fmDragStart(cards.find(x => x.id === +el.dataset.chip), ev); return; }
                        // Bo'laklar sarlavhasi — hamma bo'lak bitta katakka birga ko'chadi (data-parallel-ids).
                        const parallel = !!el.dataset.parallelIds;
                        const list = parallel ? el.dataset.parallelIds : el.dataset.mergeIds;
                        const ids = list ? list.split(',').map(Number) : [+el.dataset.chip];
                        const offs = parallel && el.dataset.parallelOffs ? el.dataset.parallelOffs.split(',').map(Number) : null;
                        startDrag(ids, ev, parallel, offs);
                    });
                });
                // Kataklarni tashlash nishoni qilamiz
                document.querySelectorAll('#grid td[data-day]').forEach(td => {
                    td.addEventListener('dragover', ev => {
                        if (fmDragCard) { ev.preventDefault(); ev.dataTransfer.dropEffect = 'move'; fmDragPaint(td, ev); return; }
                        if (!dragCardIds) return;
                        ev.preventDefault();
                        ev.dataTransfer.dropEffect = 'move';
                        // Yarim para qadami: bir necha qatorli katakda sichqoncha turgan yarim-slot; bandlik — shu yarim-slot bo'yicha.
                        const d = +td.dataset.day, p = dropSlotAt(td, ev);
                        const plan = dragPlan(dragCardIds, d, p, dragParallel);
                        dragPaint(td, plan ? plan.items : []);
                        dragTip(ev, plan);
                    });
                    td.addEventListener('dragleave', () => { td.classList.remove(...DRAG_TONES); dragTip(null, null); });
                    td.addEventListener('drop', ev => {
                        ev.preventDefault();
                        td.classList.remove(...DRAG_TONES);
                        dragTip(null, null);
                        if (fmDragCard) { fmDrop(td, ev); return; }
                        if (!dragCardIds) return;
                        const ids = dragCardIds, parallel = dragParallel, offs = dragOffsets;
                        const d = +td.dataset.day, p = dropSlotAt(td, ev);
                        dragCardIds = null;
                        dragParallel = false;
                        dragOffsets = null;
                        placeBlockAt(ids, d, p, parallel, offs);
                    });
                });
                // Bo'lak katagi ichidagi yarim-slot chiziqlari: bitta bo'lakni 12:40 ga sudrash va h.k.
                document.querySelectorAll('#grid .tt-bolak-drop').forEach(z => {
                    z.addEventListener('dragover', ev => {
                        if (!dragCardIds) return;
                        ev.preventDefault(); ev.stopPropagation();
                        ev.dataTransfer.dropEffect = 'move';
                        const card = cards.find(x => x.id === dragCardIds[0]);
                        const d = +z.dataset.dropDay, p = +z.dataset.dropPair;
                        dragPaint(z, card ? conflictsAtDetail(card, d, p, dragCardIds) : []);
                    });
                    z.addEventListener('dragleave', () => z.classList.remove(...DRAG_TONES));
                    z.addEventListener('drop', ev => {
                        ev.preventDefault(); ev.stopPropagation();
                        z.classList.remove(...DRAG_TONES);
                        if (!dragCardIds) return;
                        const ids = dragCardIds, parallel = dragParallel, offs = dragOffsets;
                        dragCardIds = null; dragParallel = false; dragOffsets = null;
                        placeBlockAt(ids, +z.dataset.dropDay, +z.dataset.dropPair, parallel, offs);
                    });
                });
            }

            // Teachers propose a time; neither the card nor the local grid is moved before approval.
            function openTeacherTimeProposal(c) {
                if (!c || +c.teacher_id !== +TIMETABLE_TEACHER_ID) {
                    alert("Faqat o'zingizga biriktirilgan dars vaqtini taklif qila olasiz."); return;
                }
                if (weeklyLayer !== 'internal' || !curWeek) {
                    alert("Taklif berish uchun ichki jadval va haftani tanlang."); return;
                }
                const prior = document.getElementById('teacherTimeProposal');
                if (prior) prior.remove();
                const m = document.createElement('div');
                m.id = 'teacherTimeProposal'; m.className = 'cr-proposal-overlay';
                const days = boardDayNames().slice(0, +board.days || 6);
                const slots = boardSchedule().filter(x => x.type !== 'break');
                const pl = effPlace(c);
                m.innerHTML = '<form class="cr-proposal-form"><h3 class="font-bold text-lg">Vaqtini o‘zgartirishni so‘rash</h3>' +
                    '<p>' + esc(c.subject_name) + ' · ' + curWeek + '-hafta</p>' +
                    '<p class="text-sm">Amaldagi vaqt: ' + esc(pl ? (days[pl.day - 1] + ' · ' + (slots[pl.pair - 1]?.start || pl.pair + '-katak')) : 'Joylashmagan') + '</p>' +
                    '<p class="text-sm">Avval kafedra mudiri, keyin registrator ofisi yoki o‘quv bo‘limi tasdiqlaydi. Shu vaqtgacha jadval o‘zgarmaydi. Faqat ertangi va keyingi kunlardagi darslar; guruh, fan, xona va o‘qituvchi o‘zgarmaydi.</p>' +
                    '<label>Yangi kun<select name="day" required>' + days.map((d, i) => '<option value="' + (i + 1) + '"' + (pl?.day === i + 1 ? ' selected' : '') + '>' + esc(d) + '</option>').join('') + '</select></label>' +
                    '<label>Yangi boshlanish vaqti<select name="pair" required>' + slots.map((s, i) => '<option value="' + (i + 1) + '"' + (pl?.pair === i + 1 ? ' selected' : '') + '>' + esc(s.start || (i + 1) + '-katak') + '</option>').join('') + '</select></label>' +
                    '<label>O‘zgarish sababi<textarea name="reason" required maxlength="1000" rows="3"></textarea></label>' +
                    '<p role="alert" class="text-red-600"></p><button type="button" data-recheck>Vaqtni qayta tekshirish</button><div class="flex justify-end gap-3"><button type="button" data-close>Bekor</button>' +
                    '<button type="submit" class="px-3 py-2 bg-blue-600 text-white rounded">Taklif yuborish</button></div></form>';
                document.body.appendChild(m);
                m.querySelector('[data-close]').onclick = () => m.remove();
                m.onclick = ev => { if (ev.target === m) m.remove(); };
                const proposalWeek = curWeek;
                const proposalForm = m.querySelector('form');
                let checkSequence = 0;
                const checkTime = async () => {
                    const sequence = ++checkSequence, button = proposalForm.querySelector('[type="submit"]');
                    const status = proposalForm.querySelector('[role="alert"]');
                    button.disabled = true; status.textContent = 'Vaqt va bronlar tekshirilmoqda…';
                    try {
                        const result = await api(BASE + '/cards/' + c.id + '/time-proposal/check', 'POST', {
                            week: proposalWeek, day: proposalForm.elements.day.value, pair: proposalForm.elements.pair.value,
                        });
                        if (sequence !== checkSequence || !m.isConnected) return;
                        status.className = 'text-green-700'; status.textContent = result.message;
                        button.disabled = false;
                    } catch (e) {
                        if (sequence !== checkSequence || !m.isConnected) return;
                        status.className = 'text-red-600'; status.textContent = e.message;
                    }
                };
                m.querySelector('[data-recheck]').onclick = checkTime;
                proposalForm.elements.day.onchange = checkTime;
                proposalForm.elements.pair.onchange = checkTime;
                checkTime();
                m.querySelector('form').onsubmit = async ev => {
                    ev.preventDefault();
                    const form = ev.currentTarget, button = form.querySelector('[type="submit"]');
                    button.disabled = true;
                    try {
                        const sent = await api(BASE + '/cards/' + c.id + '/time-proposal', 'POST', {
                            week: proposalWeek, day: form.elements.day.value, pair: form.elements.pair.value,
                            reason: form.elements.reason.value,
                        });
                        m.remove();
                        if (sent && sent.message) ttToast(sent.message, 'ok');
                        await loadChangeRequests();
                    } catch (e) { form.querySelector('[role="alert"]').className = 'text-red-600'; form.querySelector('[role="alert"]').textContent = e.message; button.disabled = false; }
                };
            }

            // ===== Fan mas'uli: "Joylash uchun tanlash" — mas'ul fani kartasini 2–3 bosishda joylash (faqat shu hafta, ichki jadval) =====
            // Kartani (yoki "Joylash"ni) bosish / paneldan sudrash → kataklar rangi serverdan BITTA so'rov bilan (responsible-move/grid: har kun ×
            // boshlanish qatori — ok / teacher / group / room / closed, sabab va eng yaqin bo'sh xona; "karta|hafta" bo'yicha keshlanadi). Yashil
            // (yoki sariq — xona tanlash majburiy) katak bosilsa / unga tashlansa — katak yonida tasdiq oynasi (openResponsibleMove, pick rejimi):
            // vaqt, xona (best_room, "o'zgartirish ▾" — qidiruvli ro'yxat), "Joylash" → responsible-move (rejimni server aniqlaydi). Esc — bekor.
            const fmCanPlace = c => TIMETABLE_ROLE === 'fan_masuli' && !!c && mySubjectCardIds.has(+c.id) && c.training_type !== 'lecture'
                && weeklyLayer === 'internal' && !!curWeek;
            const fmCell = (d, p) => (fmPick && fmPick.data && fmPick.data.cells && fmPick.data.cells[d + '-' + p]) || null;
            // Katak sinfi va atributlari: yashil (bosiladi), sariq (bosiladi — xona tanlab), qizil turlari (sabab + sabab bo'lgan dars ramkasi), kulrang.
            function fmCellAttrs(fc, d, p) {
                const at = d + '-' + p;
                if (fc.state === 'ok') {
                    const r = fc.best_room;
                    return { cls: ' tt-ok tt-fm-ok', attrs: ' data-fm-place="' + at + '" title="' + esc('Joylash mumkin' + (r ? ' · xona: ' + r.name + (r.why ? ' (' + r.why + ')' : '') : '')) + '"' };
                }
                if (fc.state === 'closed') return { cls: ' tt-closed', attrs: ' title="' + esc(fc.reason || '') + '"' };
                const causes = Object.entries(fc.causes || {}).map(([id, k]) => id + ':' + k).join(',');
                return { cls: ' tt-bad tt-bad-' + fc.state,
                    attrs: ' title="' + esc((fc.reason || '') + (fc.state === 'room' ? '\nBosing: xona tanlab joylash' : '')) + '"'
                        + (causes ? ' data-bad-ids="' + causes + '" data-bad-tone="' + fc.state + '"' : '') + (fc.state === 'room' ? ' data-fm-place="' + at + '"' : '') };
            }
            // ── Tanlangan kartaning guruh ustuni ("Joylash uchun tanlash" va fan mas'uli joylash rejimi — umumiy) ──
            // Ustun kataklari: bo'sh katak (data-g) va dars katagi (data-gs — qamragan guruh ustunlari, "§" bilan); sarlavha — th[data-gh].
            function pickColumnTargets(c) {
                const grid = document.getElementById('grid');
                if (!grid || !c) return { cells: [], heads: [] };
                const keys = cardGKeys(c);
                const has = el => (el.dataset.g && keys.includes(el.dataset.g)) || (el.dataset.gs && el.dataset.gs.split('§').some(k => keys.includes(k)));
                return { cells: [...grid.querySelectorAll('td[data-g],td[data-gs]')].filter(has),
                    heads: [...grid.querySelectorAll('th[data-gh]')].filter(th => keys.includes(th.dataset.gh)) };
            }
            const pickColumnCard = () => (typeof fmPick !== 'undefined' && fmPick && fmPick.card) || (viewMode === 'group' && selected) || null;
            // Belgi — tanlov bekor bo'lguncha (har render). Guruh ustuni filtrda yo'q — "Guruhni ko'rsatish" (filtrga qo'shib qayta chizish).
            function markPickColumns() {
                const grid = document.getElementById('grid');
                if (!grid) return;
                grid.querySelectorAll('.tt-pick-col,.tt-pick-colh').forEach(x => x.classList.remove('tt-pick-col', 'tt-pick-colh'));
                const c = pickColumnCard();
                const t = c ? pickColumnTargets(c) : { cells: [], heads: [] };
                t.cells.forEach(td => td.classList.add('tt-pick-col'));
                t.heads.forEach(th => th.classList.add('tt-pick-colh'));
                pickColumnMsg(c && !t.heads.length ? c : null);
            }
            function pickColumnMsg(c) {
                let m = document.getElementById('ttPickColMsg');
                if (!c) { if (m) m.remove(); return; }
                const wrap = document.getElementById('gridWrap');
                if (!wrap) return;
                if (!m) { m = document.createElement('div'); m.id = 'ttPickColMsg'; wrap.insertBefore(m, wrap.firstChild); }
                m.innerHTML = 'Bu guruh hozirgi filtrda ko\'rinmaydi — <button type="button" data-pick-show>Guruhni ko\'rsatish</button>';
                m.querySelector('[data-pick-show]').onclick = () => {
                    const moved = fmEnsureColumn(c);
                    if (moved) renderAll(); else { buildGroupRows(); renderPanel(); renderGrid(); }
                    scrollToPickColumn(c);
                };
            }
            // Jadval ustunga suriladi (gorizontal + vertikal, markazga): birinchi yashil (tt-ok) katak, bo'lmasa ustunning birinchi qatori.
            function scrollToPickColumn(c) {
                const t = pickColumnTargets(c);
                const target = t.cells.find(td => td.classList.contains('tt-ok')) || t.cells[0] || t.heads[0];
                if (target && target.scrollIntoView) target.scrollIntoView({ block: 'center', inline: 'center' });
                return !!target;
            }
            // Kesim guruh bo'lmasa — guruh kesimiga o'tiladi va kartaning yo'nalishi/kursi tanlanadi (uning guruh ustuni ko'rinsin).
            function fmEnsureColumn(c) {
                let moved = false;
                if (viewMode !== 'group') { viewMode = 'group'; if ($('viewMode')) $('viewMode').value = 'group'; moved = true; }
                if (!selectedFaculties.has(c.faculty_name || '')) { selectedFaculties.add(c.faculty_name || ''); moved = true; }
                if (!selectedDirs.has(c.specialty_name)) { selectedDirs.add(c.specialty_name); moved = true; }
                if (!selectedCourses.has(+c.course)) { selectedCourses.add(+c.course); moved = true; }
                if (moved) { try { reconcileSelection(false); fillSelectors(); fillGridInputs(); } catch (e) { console.warn(e); } }
                return moved;
            }
            // opts.drag — sudrash boshlandi: panel qayta chizilmaydi (sudralayotgan element o'chsa, brauzer sudrashni to'xtatadi).
            function fmPickStart(c, opts) {
                const drag = !!(opts && opts.drag);
                if (!fmCanPlace(c)) { if (!drag) openResponsibleMove(c); return; }   // ko'rish oynasi — sababi bilan (ma'ruza, hafta tanlanmagan…)
                const first = unitOf(c)[0] || c;
                if (fmPick && +fmPick.card.id === +first.id && fmPick.week === curWeek) { if (!drag) fmPickStop(); return; }
                fmPick = { card: first, week: curWeek, data: fmGridCache.get(first.id + '|' + curWeek) || null, error: null, scrolled: false };
                const moved = fmEnsureColumn(first);
                if (drag) { buildGroupRows(); renderGrid(); }
                else if (moved) renderAll(); else { buildGroupRows(); renderPanel(); renderGrid(); }
                if (!fmPick.data) fmPickLoad(); else if (!drag) fmScrollToTarget();
            }
            function fmPickStop() {
                if (!fmPick) return;
                fmPick = null;
                buildGroupRows(); renderPanel(); renderGrid();
            }
            // Grid kelgach — jadval kartaning guruh ustunidagi birinchi yashil katakka (yashil yo'q bo'lsa — ustunning birinchi bo'sh qatoriga)
            // suriladi (markazga). Har hafta / har yoqilishda bir marta.
            function fmScrollToTarget() {
                if (!fmPick || fmPick.scrolled) return;
                fmPick.scrolled = true;
                scrollToPickColumn(fmPick.card);
            }
            // Keyingi haftaga o'tish (bo'sh joy yo'q holatidagi havola) — rejim davom etadi (fmSync shu hafta grid'ini so'raydi).
            function fmGoWeek(w) {
                const sel = $('weekSel');
                if (!fmPick || !sel) return;
                sel.value = String(w);
                if (sel.value !== String(w)) return;
                sel.onchange.call(sel);
            }
            async function fmPickLoad() {
                const pick = fmPick;
                if (!pick || !pick.week) return;
                const key = pick.card.id + '|' + pick.week;
                try {
                    const j = await api(BASE + '/cards/' + pick.card.id + '/responsible-move/grid?week=' + pick.week);
                    fmGridCache.set(key, j);
                    if (fmPick !== pick || pick.week + '' !== key.split('|')[1]) return;
                    pick.data = j;
                } catch (e) {
                    if (fmPick !== pick) return;
                    pick.error = (e.data && (e.data.message || e.data.error)) || e.message;
                }
                renderGrid();
                if (fmPick === pick && pick.data) fmScrollToTarget();
            }
            // Hafta / qatlam / kesim almashdi: shu hafta uchun qayta (keshdan yoki serverdan); ichki jadval va guruh kesimidan chiqilsa — rejim tugaydi.
            function fmSync() {
                if (!fmPick) return;
                if (weeklyLayer !== 'internal' || !curWeek || viewMode !== 'group') { fmPick = null; buildGroupRows(); return; }
                if (fmPick.week !== curWeek) {
                    Object.assign(fmPick, { week: curWeek, data: fmGridCache.get(fmPick.card.id + '|' + curWeek) || null, error: null, scrolled: false });
                    if (!fmPick.data) fmPickLoad(); else setTimeout(fmScrollToTarget, 0);
                }
            }
            // Panel ostidagi holat qatori: nima joylanmoqda, yuklanish / sabab, ranglar izohi, "Eng yaxshi joylar" va "Bekor".
            function fmRenderBar() {
                const bar = $('ttFmPick');
                if (!bar) return;
                if (!fmPick) { bar.hidden = true; bar.innerHTML = ''; return; }
                const c = fmPick.card, unit = unitOf(c), len = unitLen(unit), j = fmPick.data;
                const okN = j ? Object.values(j.cells || {}).filter(x => x.state === 'ok').length : 0;
                const best = (j && j.best) || [];
                // Bo'sh joy yo'q — keyingi haftalar (server: ahead — faqat bo'sh joylar soni), bosilsa shu haftaga o'tiladi (rejim davom etadi).
                const ahead = ((j && j.ahead) || []).filter(a => +a.ok > 0);
                const aheadHtml = !j || okN ? '' : ahead.length
                    ? ' — keyingi haftalar: ' + ahead.map(a => '<a href="#" data-fm-week="' + a.week + '" style="text-decoration:underline">' + a.week + '-hafta (' + a.ok + ' joy)</a>').join(', ')
                    : ((j.ahead || []).length ? ' — keyingi ' + j.ahead.length + ' haftada ham bo‘sh joy yo‘q' : '');
                const status = fmPick.error ? '<span class="text-red-600" data-fm-status>' + esc(fmPick.error) + '</span>'
                    : !j ? '<span class="text-slate-500" data-fm-status>Joylar hisoblanmoqda…</span>'
                    : okN ? '<span data-fm-status>yashil kataklardan birini bosing yoki kartani unga sudrang — <b>' + okN + '</b> ta joy</span>'
                    : '<span class="' + (j.closed ? 'text-red-600' : 'text-amber-700') + '" data-fm-status>' + esc(j.closed || 'Bu haftada bo‘sh joy yo‘q') + aheadHtml + '</span>';
                bar.hidden = false;
                bar.innerHTML = '<b>Joylash:</b> <span>' + esc(c.subject_name + ' · ' + (c.group_name || '') + ' · ' + len + ' soat'
                        + (unit.length > 1 ? ' (' + unit.map(cardLen).join(' + ') + ')' : '') + ' · ' + curWeek + '-hafta') + '</span> — ' + status
                    + '<span><i style="background:#86efac;box-shadow:inset 0 0 0 2px #16a34a"></i>yashil — butun dars sig‘adi, bo‘sh xona bor</span>'
                    + '<span><i style="background:#f87171"></i>to‘q qizil — o‘qituvchi band</span>'
                    + '<span><i style="background:#fecaca"></i>och qizil — guruh band</span>'
                    + '<span><i style="background:#fde68a"></i>sariq — vaqt bo‘sh, mos bo‘sh xona yo‘q (xona tanlab)</span>'
                    + '<span><i style="background:#e5e7eb"></i>kulrang — bugun / o‘tgan kun yoki sig‘maydi</span>'
                    + '<label title="Faqat shu kartaning fakulteti, yo‘nalishi va kursi ustunlari"><input type="checkbox" data-fm-own' + (fmOwnOnly ? ' checked' : '') + '> Faqat shu guruh</label>'
                    + '<button type="button" class="fm-btn" data-fm-best-toggle aria-expanded="false"' + (best.length ? '' : ' disabled') + '>Eng yaxshi joylar ▾</button>'
                    + '<button type="button" class="fm-btn" data-fm-cancel>Bekor (Esc)</button>'
                    + '<div class="fm-best" data-fm-best hidden role="menu">' + best.map((b, i) => '<button type="button" role="menuitem" data-fm-best-go="' + i + '"><b>'
                        + esc(b.label) + '</b> · xona: ' + esc(b.room ? b.room.name : '—') + '<small>' + esc(b.why || '') + '</small></button>').join('') + '</div>';
                bar.querySelector('[data-fm-cancel]').onclick = fmPickStop;
                bar.querySelector('[data-fm-own]').onchange = ev => { fmOwnOnly = ev.target.checked; buildGroupRows(); renderGrid(); };
                bar.querySelectorAll('[data-fm-week]').forEach(a => a.onclick = ev => { ev.preventDefault(); fmGoWeek(+a.dataset.fmWeek); });
                const list = bar.querySelector('[data-fm-best]'), toggle = bar.querySelector('[data-fm-best-toggle]');
                toggle.onclick = () => { list.hidden = !list.hidden; toggle.setAttribute('aria-expanded', String(!list.hidden)); };
                list.querySelectorAll('[data-fm-best-go]').forEach(b => b.onclick = () => { list.hidden = true; fmGoBest(best[+b.dataset.fmBestGo]); });
            }
            // Kartaning guruh ustunidagi (d, p) katagi — tasdiq oynasi uning yonida.
            function fmCellEl(d, p) {
                const keys = fmPick ? cardGKeys(fmPick.card) : [];
                const all = [...document.querySelectorAll('#grid td[data-fm-place="' + d + '-' + p + '"]')];
                return all.find(td => keys.includes(td.dataset.g)) || all[0] || null;
            }
            function fmGoBest(b) {
                if (!b || !fmPick) return;
                const td = fmCellEl(b.day, b.pair);
                if (td && td.scrollIntoView) td.scrollIntoView({ block: 'center', inline: 'center' });
                openResponsibleMove(fmPick.card, { pick: true, day: b.day, pair: b.pair, room: b.room || null, requireRoom: false, anchor: td });
            }
            function fmOpenConfirm(d, p, td) {
                const fc = fmCell(d, p);
                if (!fmPick || !fc || !['ok', 'room'].includes(fc.state)) return;
                openResponsibleMove(fmPick.card, { pick: true, day: d, pair: p, room: fc.best_room || null, requireRoom: fc.state === 'room', anchor: td });
            }
            // Paneldan sudrash (fan mas'uli): faqat mas'ul fan amaliy kartasi; kataklar shu kartaning grid'i bo'yicha bo'yaladi.
            function fmDragStart(c, ev) {
                if (!fmCanPlace(c)) { if (ev) ev.preventDefault(); return; }
                fmDragCard = c;
                if (ev && ev.dataTransfer) {
                    ev.dataTransfer.effectAllowed = 'move';
                    try { ev.dataTransfer.setData('text/plain', String(c.id)); } catch (e) { /* ba'zi brauzerlar */ }
                }
                const first = unitOf(c)[0] || c;
                if (!fmPick || +fmPick.card.id !== +first.id || fmPick.week !== curWeek) fmPickStart(c, { drag: true });
            }
            // Sudralgan bo'lakning birlikdagi siljishi: tashlangan qator — shu bo'lak joyi, birlik boshi undan oldingi bo'laklar uzunligicha yuqorida.
            const fmDragStartRow = (td, ev) => {
                const part = fmPick && fmPick.data ? (fmPick.data.parts || []).find(x => +x.card_id === +fmDragCard.id) : null;
                return dropSlotAt(td, ev) - (part ? +part.offset : 0);
            };
            function fmDragPaint(td, ev) {
                td.classList.remove(...DRAG_TONES);
                const d = +td.dataset.day, p = fmDragStartRow(td, ev), fc = fmCell(d, p);
                if (!fc) { dragTip(null, null); return; }
                if (fc.state === 'ok') td.classList.add('drag-ok'); else td.classList.add('drag-bad', 'drag-bad-' + fc.state);
                dragTip(ev, { start: p, len: fmPick.data.len || 1, errs: fc.state === 'ok' ? [] : [fc.reason || ''] });
            }
            function fmDrop(td, ev) {
                const d = +td.dataset.day, p = fmDragStartRow(td, ev);
                fmDragCard = null;
                if (!fmPick || !fmPick.data) { ttToast('Joylar hali hisoblanmoqda — birozdan so‘ng qayta urinib ko‘ring.', 'warn'); return; }
                const fc = fmCell(d, p);
                if (!fc) return;
                if (fc.state === 'ok' || fc.state === 'room') { fmOpenConfirm(d, p, fmCellEl(d, p) || td); return; }
                ttToast(esc(fc.reason || 'Bu joyga joylab bo‘lmaydi.'), 'warn');
            }
            document.addEventListener('dragend', () => { fmDragCard = null; });
            document.addEventListener('keydown', ev => {
                if (ev.key === 'Escape' && fmPick && !document.getElementById('respMove')) fmPickStop();
            });

            // ===== Fan mas'uli: mas'ul fani darsining vaqti va xonasi (faqat shu hafta, ichki jadval) =====
            // Rejim serverda: to'qnashuvdagi (yoki joylanmagan) dars toza joyga — darhol ("Qo'llash"); to'qnashuvsiz dars — so'rov (kafedra
            // mudiri → registrator ofisi, sabab majburiy); band joy — qizil sabab. Har o'zgarishda check; xonalar ro'yxati — check javobida
            // (bo'shlari tepada, bandlari sababi bilan, tanlab bo'lmaydi). Mas'ul fanida bo'lmagan dars va ma'ruza — faqat ko'rish.
            // opts.pick — "Joylash uchun tanlash"dan (fmOpenConfirm): kun va boshlanish tanlangan (day, pair), xona — opts.room (best_room), katak yonida
            // (opts.anchor) ixcham oyna, tugma — "Joylash"; opts.requireRoom (sariq katak) — xona tanlanmaguncha joylab bo'lmaydi.
            function openResponsibleMove(c, opts) {
                opts = opts || {};
                const pickMode = !!opts.pick;
                const prior = document.getElementById('respMove');
                if (prior) prior.remove();
                const m = document.createElement('div');
                m.id = 'respMove';
                m.className = 'cr-proposal-overlay';
                const days = boardDayNames().slice(0, +board.days || 6);
                const lecture = c.training_type === 'lecture';
                const unit = lecture ? [c] : unitOf(c);
                const len = unitLen(unit);
                const rows = boardSchedule().filter(it => it.type === 'pair').length || +board.pairs_per_day || 12;
                const pl = effPlace(unit[0]);
                // Kun / boshlanish tanlovining sukuti: pick rejimida — bosilgan katak, aks holda — amaldagi joy.
                const at = pickMode ? { day: +opts.day, pair: +opts.pair } : pl;
                const room = (c.auditorium_name || c.auditorium_code || '');
                const head = pickMode ? '<h3 class="font-bold">Joylash</h3><p class="text-sm">' + esc(c.subject_name) + ' · ' + esc(c.group_name || '')
                        + ' · ' + len + ' soat' + (unit.length > 1 ? ' (' + unit.map(cardLen).join(' + ') + ')' : '') + '</p>'
                        + '<p class="text-sm font-semibold" data-rmv-when>' + esc((days[at.day - 1] || at.day + '-kun') + ' ' + slotRangeText(at.pair, len)) + '</p>'
                    : '<h3 class="font-bold text-lg">Vaqt va xonani o‘zgartirish</h3>'
                    + '<p>' + esc(c.subject_name) + ' · ' + esc(lecture ? (c.oqim_label || '') : (c.group_name || '')) + (curWeek ? ' · ' + curWeek + '-hafta' : '') + '</p>'
                    // Amaldagi — butun dars: ko'p bo'lakli darsda birinchi bo'lak boshidan oxirgisi oxirigacha ("Shanba 10:00–13:20"); turli kunlarda —
                    // har kun alohida va "(bo'lingan)".
                    + '<p class="text-sm" data-rmv-now>Amaldagi: ' + esc(pl ? (unit.length > 1 ? unitDaysText(unit) + (unitIsSplit(unit) ? ' (bo‘lingan)' : '')
                        : (days[pl.day - 1] || pl.day + '-kun') + ' ' + slotRangeText(+pl.pair, len)) : 'joylanmagan')
                    + (room ? ', xona ' + esc(room) : '') + (unit.length > 1 ? ' · ' + unit.map(cardLen).join(' + ') + ' soatlik bo‘laklar' : '') + '</p>';
                const why = !mySubjectCardIds.has(+c.id) ? "Bu fan sizning mas'ul fanlaringizda emas — faqat ko'rish."
                    : lecture ? "Ma'ruzani surish — faqat kafedra mudiri va adminlar."
                    : (weeklyLayer !== 'internal' || !curWeek) ? "Vaqt va xonani o'zgartirish uchun ichki jadval va haftani tanlang (faqat shu hafta o'zgaradi)." : null;
                if (why) {
                    m.innerHTML = '<div class="cr-proposal-form">' + head + '<p class="text-sm text-slate-600" data-rm-why>' + esc(why) + '</p>'
                        + '<div class="flex justify-end"><button type="button" data-close>Yopish</button></div></div>';
                    document.body.appendChild(m);
                    m.querySelector('[data-close]').onclick = () => m.remove();
                    m.onclick = ev => { if (ev.target === m) m.remove(); };
                    return;
                }
                const starts = [];
                for (let q = 1; q + len - 1 <= rows; q++) starts.push(q);
                // Pick rejimida kun / boshlanish ko'rinmaydi (katak tanlangan) — qiymatlari saqlanadi.
                const hideSel = pickMode ? ' style="display:none"' : '';
                m.innerHTML = '<form class="cr-proposal-form">' + head
                    + '<p class="text-sm">' + (pickMode ? 'Faqat shu hafta (shablon va kartaning xonasi o‘zgarmaydi).'
                        : 'Faqat shu hafta o‘zgaradi (shablon va kartaning xonasi o‘zgarmaydi). Bugungi va o‘tgan kunlar — yopiq.') + '</p>'
                    + '<label' + hideSel + '>Kun<select name="day" required>' + days.map((d, i) => '<option value="' + (i + 1) + '"' + (at && +at.day === i + 1 ? ' selected' : '') + '>' + esc(d) + '</option>').join('') + '</select></label>'
                    + '<label' + hideSel + '>Boshlanish vaqti<select name="pair" required>' + starts.map(q => '<option value="' + q + '"' + (at && +at.pair === q ? ' selected' : '') + '>'
                        + esc(slotRangeText(q, len) || (q + '-katak')) + '</option>').join('') + '</select></label>'
                    + '<div class="rmv-room"><span>Xona</span><input type="hidden" name="room" value="">'
                    + '<button type="button" class="rmv-pick" data-rmv-pick aria-haspopup="listbox" aria-expanded="false"></button>'
                    + '<div class="rmv-panel" data-rmv-panel hidden><div class="rmv-tools">'
                    + '<input type="search" data-rmv-q placeholder="Xona qidirish…" aria-label="Xona qidirish" autocomplete="off">'
                    + '<label><input type="checkbox" data-rmv-free> Faqat bo‘shlar</label></div>'
                    + '<div class="rmv-head" data-rmv-head></div>'
                    + '<div class="rm-list" role="listbox" aria-label="Xonalar" data-rmv-list></div></div></div>'
                    + '<label data-rmv-reason' + hideSel + '>Sabab (so‘rov uchun majburiy)<textarea name="reason" maxlength="1000" rows="2"></textarea></label>'
                    + '<p role="alert" class="text-sm"></p>'
                    + '<div class="flex justify-end gap-3"><button type="button" data-close>Bekor</button>'
                    + '<button type="submit" class="px-3 py-2 bg-blue-600 text-white rounded" disabled>Tekshirilmoqda…</button></div></form>';
                document.body.appendChild(m);
                m.querySelector('[data-close]').onclick = () => m.remove();
                m.onclick = ev => { if (ev.target === m) m.remove(); };
                // Katak yonida (o'ngda, sig'masa — chapda; ekran ichida); telefonda — pastdan (CSS).
                const placePop = () => {
                    const f = m.querySelector('.cr-proposal-form');
                    if (!f || !opts.anchor || !opts.anchor.isConnected || !opts.anchor.getBoundingClientRect) return;
                    const r = opts.anchor.getBoundingClientRect(), w = f.offsetWidth || 360, h = f.offsetHeight || 320;
                    let left = r.right + 8;
                    if (left + w > window.innerWidth - 8) left = Math.max(8, r.left - w - 8);
                    f.style.left = left + 'px';
                    f.style.top = Math.min(Math.max(8, r.top), Math.max(8, window.innerHeight - h - 8)) + 'px';
                };
                if (pickMode && opts.anchor) { m.classList.add('rm-pop'); placePop(); }
                const form = m.querySelector('form'), btn = form.querySelector('[type="submit"]'), status = form.querySelector('[role="alert"]');
                const week = curWeek;
                let seq = 0, mode = null;
                const body = () => ({ week: week, day: +form.elements.day.value, pair: +form.elements.pair.value,
                    auditorium_code: form.elements.room.value || undefined });
                // Xonalar (check javobidan, tanlangan vaqt uchun — hammasi): qidiruvli ro'yxat. Birinchi qator — "hozirgi xona" (holati bilan),
                // so'ng bo'shlari (yaqinlik sababi bilan), so'ng band / sig'maydiganlari kulrang — tanlab bo'lmaydi (aria-disabled). Avval 50 ta,
                // "Ko'proq ko'rsatish"; qidiruv — hammasidan, faqat xona nomi bo'yicha (kod / bino emas; harf va tutuq belgisi farqsiz).
                // Biriktirilgan xona — "Biriktirilgan: OSTANAQULOV SH. F.", to'liq F.I.Sh. — title'da. Klaviatura: ↑/↓, Enter, Esc.
                const roomInput = form.elements.room, pick = m.querySelector('[data-rmv-pick]'), panel = m.querySelector('[data-rmv-panel]');
                const qEl = m.querySelector('[data-rmv-q]'), freeEl = m.querySelector('[data-rmv-free]'), listEl = m.querySelector('[data-rmv-list]');
                const ROOM_PAGE = 50;
                let roomsAll = [], partRooms = [], roomShown = ROOM_PAGE, roomActive = -1;
                // Bo'laklar har xil xonada (server: part_rooms) — birinchi qator "har bo'lak o'z xonasida", har bo'lak xonasi ro'yxatda oddiy qator;
                // biror bo'lak xonasi yaroqsiz bo'lsa — shu qatorda qizil izoh va bu tanlovda tugma o'chiq.
                const mixedRooms = () => partRooms.length > 1;
                const curText0 = '— hozirgi xona' + (room ? ' (' + room + ')' : '') + ' —';
                const keepText = () => mixedRooms() ? '— har bo‘lak o‘z xonasida (' + partRooms.map(p => p.name).join(', ') + ') —' : curText0;
                const keepProblem = () => mixedRooms() ? partRooms.filter(p => p.problem).map(p => p.name + ' — ' + p.problem + ', xona tanlang').join('; ') : '';
                const busyLine = it => 'Band: ' + [it.teacher, (it.groups || []).join(', '), it.subject, it.time].filter(Boolean).join(' · ');
                const busyTitle = it => [it.teacher_full || it.teacher, (it.groups || []).join(', '), it.subject,
                    (it.dates || []).filter((d, i, a) => a.indexOf(d) === i).map(d => String(d).slice(8, 10) + '.' + String(d).slice(5, 7)).join('–'), it.time].filter(Boolean).join(' · ');
                const capLine = r => r.cap ? 'Xona sig‘maydi: ' + cfCapText(r.cap) : '';
                const roomState = r => {
                    if (!r || r.free) return '';
                    const items = r.busy_items || [];
                    return r.kind === 'assigned' ? '<span class="rm-busy">' + esc(r.note || 'Boshqa o‘qituvchiga biriktirilgan') + '</span>'
                        : r.kind === 'busy'
                        ? '<span class="rm-busy">' + esc(items.length ? busyLine(items[0]) + (items.length > 1 ? ' +' + (items.length - 1) : '') : (r.busy || 'Band')) + '</span>'
                            + (r.cap ? '<span class="rm-cap">' + esc(capLine(r)) + '</span>' : '')
                        : '<span class="rm-cap">' + esc(capLine(r) || r.busy || "Xona sig'maydi") + '</span>';
                };
                const roomTitle = r => r && !r.free ? [r.kind === 'assigned' ? r.note_full : '', ...(r.busy_items || []).map(busyTitle), capLine(r)]
                    .filter(Boolean).join('\n') : '';
                const roomRow = (r, code, label) => {
                    const off = r && !r.free && code !== '';
                    return '<div role="option" class="rm-row' + (code === '' ? ' is-current' : '') + '" data-code="' + esc(code) + '"'
                        + ' aria-selected="' + (roomInput.value === code) + '"' + (off ? ' aria-disabled="true" style="opacity:.55"' : '')
                        + (roomTitle(r) ? ' title="' + esc(roomTitle(r)) + '"' : '') + '>'
                        + '<b>' + esc(label) + '</b>'
                        + (code !== '' && roomBuildingTag(r) ? '<span class="rm-bld" data-rmv-bld>' + esc(roomBuildingTag(r)) + '</span>' : '')
                        + (r && r.free && r.why ? '<span class="rm-why">' + esc(r.why) + '</span>' : '')
                        + (r && code !== '' ? '<span class="rm-vol">' + (r.volume ? r.volume + ' o‘rin' : 'sig‘imi kiritilmagan') + '</span>' : '')
                        + roomState(r) + (code === '' && keepProblem() ? '<span class="rm-err">' + esc(keepProblem()) + '</span>' : '') + '</div>';
                };
                const roomRows = () => Array.from(listEl.querySelectorAll('.rm-row'));
                const renderRooms = () => {
                    const q = qEl.value, cur = roomsAll.find(r => r.current);
                    const rest = roomsAll.filter(r => !r.current && (!freeEl.checked || r.free) && roomMatches(r, q, true));
                    listEl.innerHTML = roomRow(cur, '', keepText())
                        + roomListGrouped(rest.slice(0, roomShown), r => roomRow(r, r.code, r.name), g => '<div class="rm-group" data-rmv-group>' + esc(g) + '</div>')
                        + (rest.length > roomShown ? '<button type="button" class="rmv-more" data-rmv-more>Ko‘proq ko‘rsatish (yana ' + (rest.length - roomShown) + ' ta)</button>' : '')
                        + (!rest.length && (q || freeEl.checked) ? '<div class="p-3 text-sm text-slate-400">Xona topilmadi</div>' : '');
                    roomActive = -1;
                };
                const pickLabel = () => {
                    // Pick rejimi: ro'yxat kelguncha — taklif qilingan xona (best_room).
                    const r = roomsAll.find(x => x.code === roomInput.value)
                        || (pickMode && opts.room && String(opts.room.code) === roomInput.value ? opts.room : null);
                    pick.textContent = (r ? r.name + (r.volume ? ' (' + r.volume + ' o‘rin)' : '') + (r.why ? ' — ' + r.why : '') : keepText())
                        + (pickMode ? ' · o‘zgartirish ▾' : '');
                };
                if (pickMode && opts.room && opts.room.code) roomInput.value = String(opts.room.code);
                const openRooms = open => {
                    panel.hidden = !open;
                    pick.setAttribute('aria-expanded', String(open));
                    if (open) { roomShown = ROOM_PAGE; renderRooms(); qEl.focus(); }
                };
                const chooseRoom = row => {
                    if (!row || row.getAttribute('aria-disabled') === 'true') return;
                    roomInput.value = row.dataset.code;
                    pickLabel();
                    openRooms(false);
                    pick.focus();
                    check();
                };
                const moveActive = step => {
                    const rows = roomRows(), ok = rows.map((r, i) => r.getAttribute('aria-disabled') === 'true' ? -1 : i).filter(i => i >= 0);
                    if (!ok.length) return;
                    const at = ok.indexOf(roomActive);
                    roomActive = ok[at < 0 ? (step > 0 ? 0 : ok.length - 1) : Math.min(ok.length - 1, Math.max(0, at + step))];
                    rows.forEach((r, i) => r.classList.toggle('is-active', i === roomActive));
                    rows[roomActive].scrollIntoView({ block: 'nearest' });
                };
                pick.onclick = () => openRooms(panel.hidden);
                qEl.oninput = () => { roomShown = ROOM_PAGE; renderRooms(); };
                freeEl.onchange = () => { roomShown = ROOM_PAGE; renderRooms(); };
                qEl.onkeydown = ev => {
                    if (ev.key === 'ArrowDown' || ev.key === 'ArrowUp') { ev.preventDefault(); moveActive(ev.key === 'ArrowDown' ? 1 : -1); }
                    else if (ev.key === 'Enter') { ev.preventDefault(); chooseRoom(roomRows()[roomActive]); }
                    else if (ev.key === 'Escape') { ev.preventDefault(); ev.stopPropagation(); openRooms(false); pick.focus(); }
                };
                listEl.onclick = ev => {
                    if (ev.target.closest('[data-rmv-more]')) { roomShown += ROOM_PAGE; renderRooms(); qEl.focus(); return; }
                    chooseRoom(ev.target.closest('.rm-row'));
                };
                // Tanlov saqlanadi; tanlangan xona yangi vaqtda bo'sh bo'lmasa — "hozirgi xona"ga qaytadi.
                const fillRooms = (list, parts, when) => {
                    roomsAll = list || [];
                    partRooms = parts || [];
                    const h = m.querySelector('[data-rmv-head]');
                    if (h) h.textContent = roomsAll.length ? roomListHeadText(when, roomsAll) : '';
                    if (roomInput.value && !roomsAll.some(r => r.code === roomInput.value && r.free)) roomInput.value = '';
                    pickLabel();
                    if (!panel.hidden) renderRooms();
                };
                pickLabel();
                const check = async () => {
                    const my = ++seq;
                    mode = null;
                    btn.disabled = true;
                    btn.classList.remove('rmv-off');
                    btn.textContent = 'Tekshirilmoqda…';
                    status.className = 'text-sm text-slate-500';
                    status.textContent = 'Vaqt, xona va bronlar tekshirilmoqda…';
                    let j, ok = true;
                    try { j = await api(BASE + '/cards/' + c.id + '/responsible-move/check', 'POST', body()); }
                    catch (e) { j = e.data || { message: e.message }; ok = false; }
                    if (my !== seq || !m.isConnected) return;
                    if (j.rooms) fillRooms(j.rooms, j.part_rooms, j.when);
                    mode = ok ? j.mode : null;
                    // "Har bo'lak o'z xonasida" tanlangan, biror bo'lak xonasi yaroqsiz — qo'llab bo'lmaydi (xona tanlash kerak).
                    // Pick rejimida sariq katak (mos bo'sh xona yo'q) — xona tanlanmaguncha joylab bo'lmaydi.
                    const blocked = (!roomInput.value && keepProblem())
                        || (pickMode && opts.requireRoom && !roomInput.value ? 'Bu vaqtda mos bo‘sh xona yo‘q — «o‘zgartirish ▾» orqali xona tanlang.' : '');
                    if (blocked) mode = null;
                    const msg = blocked || j.message || j.error || 'Tekshirib bo‘lmadi.';
                    status.className = 'text-sm ' + (mode === 'fix' ? 'text-emerald-700' : mode === 'request' ? 'text-amber-700' : 'text-red-600');
                    status.textContent = (mode && !pickMode ? (j.new ? j.new + ' — ' : '') : '') + msg;
                    if (pickMode && j.new && m.querySelector('[data-rmv-when]')) m.querySelector('[data-rmv-when]').textContent = j.new;
                    // So'rov rejimi (to'qnashuvsiz joylashgan dars) — sabab maydoni pick rejimida ham ochiladi.
                    if (pickMode) m.querySelector('[data-rmv-reason]').style.display = mode === 'request' ? '' : 'none';
                    // Joylab bo'lmaydi — tugma o'chiq, kulrang: "Qo'llab bo'lmaydi" (sababi — yuqoridagi qizil matnda).
                    btn.textContent = mode === 'fix' ? (pickMode ? 'Joylash' : 'Qo‘llash') : mode === 'request' ? 'So‘rov yuborish' : (pickMode ? 'Joylab bo‘lmaydi' : 'Qo‘llab bo‘lmaydi');
                    btn.disabled = !mode;
                    btn.classList.toggle('rmv-off', !mode);
                    if (pickMode) placePop();
                };
                form.elements.day.onchange = check;
                form.elements.pair.onchange = check;
                check();
                form.onsubmit = async ev => {
                    ev.preventDefault();
                    if (!mode) return;
                    if (mode === 'request' && !form.elements.reason.value.trim()) {
                        status.className = 'text-sm text-red-600';
                        status.textContent = "So'rov sababini kiriting.";
                        form.elements.reason.focus();
                        return;
                    }
                    btn.disabled = true;
                    try {
                        const sent = await api(BASE + '/cards/' + c.id + '/responsible-move', 'POST', Object.assign(body(), { reason: form.elements.reason.value }));
                        m.remove();
                        // Joylash rejimi tugaydi (so'rov bo'lsa ham): kataklar keshi eskirdi; fmPickStop — "Faqat shu guruh" ustunlari tiklanadi,
                        // panel va jadval qayta chiziladi (darhol joylanganda — doska ham qayta yuklanadi).
                        if (pickMode) { fmGridCache.clear(); fmPickStop(); }
                        if (sent && sent.mode === 'fix') {
                            ttToast('<b>' + esc(pickMode ? 'Joylandi (faqat shu hafta)' : (sent.message || 'Joylandi.')) + '</b>', 'ok');
                            await loadBoard(board.id);
                        } else {
                            // So'rov: api() "Tasdiqqa yuborildi" xabarini ko'rsatadi va so'rovlar ro'yxatini yangilaydi.
                            await loadChangeRequests();
                        }
                    } catch (e) {
                        status.className = 'text-sm text-red-600';
                        status.textContent = (e.data && (e.data.message || e.data.error)) || e.message;
                        btn.disabled = false;
                    }
                };
            }

            // ===== Kartochka modali (o'qituvchi/auditoriya) =====
            async function openModal(c) {
                if (TIMETABLE_ROLE === 'oqituvchi') { openTeacherTimeProposal(c); return; }
                // Fan mas'uli: kafedra mudiri oynasi emas (o'qituvchi/xona ro'yxatlari unga yopiq) — vaqt va xona oynasi (mas'ul fanida — o'zgartirish).
                if (TIMETABLE_ROLE === 'fan_masuli') { openResponsibleMove(c); return; }
                modalCard = c;
                $('cmTitle').textContent = c.subject_name;
                const cmLec = c.training_type === 'lecture' ? lectureLabel(c.oqim_label, cardGroups(c)) : null;
                $('cmSub').title = cmLec ? cmLec.title : '';
                $('cmSub').textContent = (cmLec ? cmLec.text : 'Amaliy · ' + (c.group_name || '')) +
                    ' · ' + c.students + ' talaba' + (c.kafedra_name ? ' · ' + c.kafedra_name : '') +
                    (curWeek ? ' · ' + curWeek + '-hafta' + (hasWeekOverride(c) ? ' (individual)' : '') : '');
                $('cmCap').textContent = '(kamida ' + c.students + ' o\'rin)';
                // Hafta rejimida: "olib tashlash" shu haftada bekor qilish; override bo'lsa shablonga qaytarish
                $('cmUnplace').textContent = curWeek ? '✖ Shu haftada bekor qilish' : '↩ Jadvaldan olish';
                $('cmResetWeek').classList.toggle('hidden', !(curWeek && hasWeekOverride(c)));
                // Dars uzunligi: ko'p bo'lakli dars (birlik, masalan 2 + 1 soat) — to'liq uzunligi (bo'lak uzunligi tanlanmaydi).
                const unitList = c.training_type === 'lecture' ? [c] : unitOf(c);
                modalUnit = unitList.length > 1 ? unitList : null;
                $('cmUnitLen').classList.toggle('hidden', !modalUnit);
                $('cmLen').classList.toggle('hidden', !!modalUnit);
                $('cmUnitLen').textContent = modalUnit ? unitLen(modalUnit) + ' soat (' + modalUnit.map(cardLen).join(' + ') + ' soatlik bo\'laklar)' : '';
                // Dars uzunligi va boshlanish yarmi
                $('cmLen').value = String(c.len_half || 2);
                $('cmStartHalf').value = String(c.start_half || 0);
                $('cmStartHalf').disabled = !(c.day && c.pair);
                fillCmStartSlot(c);
                updateCmTimeHint();
                $('cmMsg').classList.add('hidden');
                $('cardModal').classList.remove('hidden');
                await Promise.all([loadTeachers(''), loadAuds()]);
            }
            let modalUnit = null;   // ochiq oynadagi darsning bo'laklari (ko'p bo'lakli bo'lsa)
            // Ochiq oynadagi dars boshi: ko'p bo'lakli darsda — birinchi bo'lagi joyi.
            const modalStartPlace = c => effPlace(modalUnit ? modalUnit[0] : c);
            // Modal: boshlanish vaqti — kunning har yarim-slotidan (yarim para qadami: 08:30, 09:10, 10:00 …), dars to'liq sig'adigan
            // joygacha. Ko'p bo'lakli dars — butun dars (barcha bo'laklari) shu vaqtdan ketma-ket suriladi.
            function fillCmStartSlot(c) {
                const sel = $('cmStartSlot');
                const pl = modalStartPlace(c);
                if (!pl) { sel.innerHTML = '<option value="">— joylashtirilmagan —</option>'; sel.disabled = true; return; }
                if (modalUnit) {
                    const sched = boardSchedule().filter(it => it.type === 'pair');
                    const len = unitLen(modalUnit);
                    let o = '';
                    for (let q = 1; q + len - 1 <= sched.length; q++) {
                        o += '<option value="' + q + '"' + (q === +pl.pair ? ' selected' : '') + '>' + esc(slotRangeText(q, len) || ('slot ' + q)) + '</option>';
                    }
                    sel.innerHTML = o;
                    sel.disabled = false;
                    return;
                }
                const sched = boardSchedule().filter(it => it.type === 'pair');
                const pt = {};
                sched.forEach((it, i) => { pt[i + 1] = { name: it.name || '', abbr: it.abbr || '', start: it.start || '', end: it.end || '' }; });
                const P = sched.length || board.pairs_per_day || 12;
                const groups = paraGroups(P, pt);
                let a = +pl.pair;
                while (a > 1 && groups[a] && groups[a].span === 0) a--;
                const n = (groups[a] && groups[a].span) || 1;
                let o = '';
                for (let q = a; q < a + n; q++) {
                    o += '<option value="' + q + '"' + (q === +pl.pair ? ' selected' : '') + '>' +
                        esc((pt[q] && pt[q].start) || ('slot ' + q)) + (q === a ? ' — para boshi' : ' — para ichidan') + '</option>';
                }
                sel.innerHTML = o;
                sel.disabled = n < 2;
            }
            // Modal: tanlangan uzunlik/boshlanish bo'yicha dars vaqti oralig'ini ko'rsatish
            function updateCmTimeHint() {
                const el = $('cmTimeHint');
                if (!modalCard || !effPlace(modalCard)) { el.textContent = 'Joylashtirilmagan — uzunlik saqlanadi.'; return; }
                const sched = boardSchedule().filter(it => it.type === 'pair');
                const len = modalUnit ? unitLen(modalUnit) : +$('cmLen').value;
                // Bu modelda `pair` — yarim-slot indeksi; har qo'ng'iroq elementi bitta
                // yarim-slot (o'z start/end vaqti bilan). Dars pair'dan boshlab len ta
                // yarim-slotni egallaydi.
                const pl = modalStartPlace(modalCard) || modalCard;
                const sp = +$('cmStartSlot').value || +pl.pair;
                const startEntry = sched[sp - 1];
                const endEntry = sched[sp - 1 + len - 1] || startEntry;
                const startT = startEntry ? (startEntry.start || '') : '';
                const endT = endEntry ? (endEntry.end || '') : '';
                const label = modalUnit ? len + ' soat' : ({ 1: '0.5 para', 2: '1 para', 3: '1.5 para', 4: '2 para' }[len] || len);
                el.textContent = '⏱ ' + label + (startT && endT ? ' · ' + startT + '–' + endT : '');
            }
            // Ikki vaqt oralig'ining o'rtasi (HH:MM)
            function midTime(s, e) {
                const toMin = t => { const [h, m] = String(t).split(':').map(Number); return (h || 0) * 60 + (m || 0); };
                if (!s || !e) return '';
                const m = Math.round((toMin(s) + toMin(e)) / 2);
                return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
            }
            $('cmLen').onchange = $('cmStartHalf').onchange = $('cmStartSlot').onchange = updateCmTimeHint;
            async function loadTeachers(search) {
                const p = new URLSearchParams();
                if (modalCard.kafedra_name && !search) p.set('kafedra', modalCard.kafedra_name.split(' ')[0]);
                if (search) p.set('search', search);
                const list = await api(TEACHERS_URL + '?' + p);
                $('cmTeacher').innerHTML = '<option value="">— biriktirilmagan —</option>' + list.map(t =>
                    '<option value="' + t.id + '"' + (modalCard.teacher_id === t.id ? ' selected' : '') + '>' +
                    esc(t.full_name) + (t.lavozim ? ' · ' + esc(t.lavozim) : '') + '</option>').join('');
            }
            async function loadAuds() {
                if (!audCache) audCache = await api(AUDS_URL);
                // Faqat faol xonalar; kartadagi hozirgi xona nofaol bo'lsa — "(nofaol)" belgisi bilan ko'rinadi, lekin tanlab bo'lmaydi.
                const cur = modalCard.auditorium_code ? audCache.find(a => a.code === modalCard.auditorium_code) : null;
                const curOff = !!modalCard.auditorium_code && ((cur && cur.active === false) || roomInactive(modalCard.auditorium_code));
                $('cmAud').innerHTML = '<option value="">— tanlanmagan —</option>' + (curOff
                    ? '<option value="' + esc(modalCard.auditorium_code) + '" disabled selected data-room-off="1" style="color:#b91c1c">' +
                        esc((cur && cur.name) || modalCard.auditorium_name || modalCard.auditorium_code) + ' (nofaol)</option>' : '') +
                    audCache.filter(a => a.active !== false).map(a =>
                    '<option value="' + esc(a.code) + '"' + (modalCard.auditorium_code === a.code ? ' selected' : '') +
                    ((!isNonBlocking(modalCard) && a.volume && a.volume < modalCard.students) ? ' style="color:#dc2626"' : '') + '>' +
                    esc(a.name) + (a.volume ? ' (' + a.volume + ')' : '') + (a.building_name ? ' · ' + esc(a.building_name) : '') + '</option>').join('');
            }
            let tSearchTimer = null;
            $('cmTeacherSearch').oninput = function () {
                clearTimeout(tSearchTimer);
                tSearchTimer = setTimeout(() => loadTeachers(this.value.trim()), 300);
            };
            $('cmClose').onclick = $('cmCancel').onclick = () => { $('cardModal').classList.add('hidden'); modalCard = null; selected = null; renderPanel(); renderGrid(); };
            $('cmSave').onclick = () => cmSaveRun(false);
            const cmAsgKey = () => ($('cmTeacher').value || '') + '|' + ($('cmAud').value || '');
            async function cmSaveRun(force) {
                if (!modalCard) return;
                const btn = $('cmSave');
                btn.disabled = true;
                try {
                    const j = await api(BASE + '/cards/' + modalCard.id + '/update', 'POST', {
                        teacher_id: $('cmTeacher').value || '',
                        // Hozirgi nofaol xona (o'zgartirilmagan) — yuborilmaydi: qayta saqlanmaydi, karta xonasi o'zgarmaydi.
                        ...(($('cmAud').selectedOptions[0] || {}).dataset && $('cmAud').selectedOptions[0].dataset.roomOff ? {} : { auditorium_code: $('cmAud').value || '' }),
                        len_half: $('cmLen').value,
                        start_half: $('cmStartHalf').value,
                        // Xona boshqa o'qituvchiga biriktirilgan — "Baribir biriktirish" dan keyin.
                        force: force ? 1 : undefined,
                    });
                    modalCard.teacher_id = $('cmTeacher').value ? +$('cmTeacher').value : null;
                    modalCard.teacher_name = j.teacher_name;
                    modalCard.auditorium_code = j.auditorium_code;
                    modalCard.auditorium_name = j.auditorium_name;
                    modalCard.len_half = +$('cmLen').value;
                    if (modalCard.day && modalCard.pair) modalCard.start_half = +$('cmStartHalf').value;
                    // Boshlanish vaqti o'zgargan bo'lsa — shu kunda yangi yarim-slotga ko'chirish
                    const pl = modalStartPlace(modalCard);
                    const slot = +$('cmStartSlot').value;
                    if (pl && slot && slot !== +pl.pair) {
                        if (modalCard.training_type !== 'lecture') {
                            // Amaliy — birlik bilan: barcha bo'laklari ketma-ket, o'z bo'laklari bilan "to'qnashuv" yo'q (server tekshiradi).
                            await placeUnitAt(modalUnit ? modalUnit[0] : modalCard, +pl.day, slot);
                        } else {
                            const errs = conflictsAt(modalCard, +pl.day, slot);
                            if (errs.length) throw new Error('Konflikt: ' + errs.join('; '));
                            await placeOneCard(modalCard, +pl.day, slot);
                        }
                    }
                    $('cardModal').classList.add('hidden'); modalCard = null; selected = null;
                    renderAll();
                } catch (e) {
                    const m = $('cmMsg');
                    if (e.data && e.data.needs_confirm && !force) {
                        // Xona boshqa o'qituvchiga biriktirilgan — ogohlantirish, "Baribir biriktirish" bilan saqlanadi. Tasdiq shu
                        // tanlov (o'qituvchi + xona) uchun: keyin o'zgartirilgan bo'lsa — force'siz qayta tekshiriladi (o'z ogohlantirishi).
                        const warned = cmAsgKey();
                        m.className = 'text-sm rounded px-3 py-2 bg-amber-50';
                        showBusyConfirm(m, e.message, () => cmSaveRun(cmAsgKey() === warned), e.data.conflict_items);
                    } else {
                        m.className = 'text-sm rounded px-3 py-2 bg-red-50 text-red-700';
                        m.textContent = e.message; m.classList.remove('hidden');
                    }
                }
                btn.disabled = false;
            }
            $('cmUnplace').onclick = async () => {
                if (!modalCard) return;
                try {
                    // Amaliy — butun dars (barcha bo'laklari) olinadi.
                    if (modalCard.training_type !== 'lecture') await placeUnitAt(modalCard, null, null);
                    else await unplaceOneCard(modalCard);
                } catch (e) { alert('Xatolik: ' + e.message); return; }
                $('cardModal').classList.add('hidden'); modalCard = null; selected = null;
                renderAll();
            };
            $('cmResetWeek').onclick = async () => {
                if (!modalCard || !curWeek) return;
                try {
                    await api(BASE + '/cards/' + modalCard.id + '/week-override', 'POST', { week: curWeek, action: 'reset' });
                    delete overrides[modalCard.id + '|' + curWeek];
                } catch (e) { alert('Xatolik: ' + e.message); return; }
                $('cardModal').classList.add('hidden'); modalCard = null; selected = null;
                renderAll();
            };

            // ══════════════════════════════════════════════════════════════
            //  aSc uslubidagi boshqaruv dialoglari
            // ══════════════════════════════════════════════════════════════
            const PAIR_TIMES = ['08:30-09:50','10:00-11:20','12:00-13:20','13:30-14:50','15:00-16:20','16:30-17:50','17:00-18:20'];
            const ROMAN = ['I','II','III','IV','V','VI','VII','VIII','IX','X'];
            const LANG_LABEL = { uz: "o'zbek", rus: 'rus', ru: 'rus', ing: 'ingliz', en: 'ingliz' };
            const ICON_BASE = @json(asset('image'));
            const iconImage = file => '<img class="tt-custom-icon" src="' + ICON_BASE + '/' + file + '" alt="" aria-hidden="true">';
            const managerIcons = {
                subjects: iconImage('06_subjects_book.png'),
                groups: iconImage('07_classes.png'),
                auditoriums: iconImage('08_classrooms.png'),
                teachers: iconImage('09_teachers_cap.png'),
            };

            let ascType = null;       // joriy dialog turi
            let ascData = [];         // dialog ma'lumotlari (xom)
            let ascSelId = null;      // tanlangan qator id/kalit
            let ascColumnFilters = {};
            const ascCache = {};      // tablar orasida qaytishda jadvalni qayta yuklamaslik uchun

            const dialogMeta = {
                subjects:    { icon: managerIcons.subjects, title: 'Darslar',      listLabel: 'Darslar ro\'yxati:', filter: 'spec' },
                groups:      { icon: managerIcons.groups, title: 'Guruhlar',     listLabel: 'Guruhlar ro\'yxati:', filter: 'spec' },
                auditoriums: { icon: managerIcons.auditoriums, title: 'Auditoriyalar', listLabel: 'Auditoriyalar:',     filter: null   },
                teachers:    { icon: managerIcons.teachers, title: "O'qituvchilar", listLabel: 'O\'qituvchilar:',   filter: null   },
            };

            document.querySelectorAll('.asc-tool[data-dialog]').forEach(btn =>
                btn.onclick = () => openDialog(btn.dataset.dialog));
            document.querySelectorAll('.asc-nav-btn').forEach(btn =>
                btn.onclick = () => openDialog(btn.dataset.ascType));

            function updateAscNav(type) {
                document.querySelectorAll('.asc-nav-btn').forEach(btn => {
                    const active = btn.dataset.ascType === type;
                    btn.classList.toggle('active', active);
                    btn.setAttribute('aria-selected', active ? 'true' : 'false');
                });
            }

            async function openDialog(type) {
                if (!board) return;
                if (TIMETABLE_CAN_USE_MANAGER && type !== 'subjects') return;

                const modalIsOpen = !$('ascModal').classList.contains('hidden');
                if (modalIsOpen && ascType === type) return;

                ascType = type;
                ascSelId = null;
                ascColumnFilters = {};
                updateAscNav(type);

                const m = dialogMeta[type];
                $('ascIcon').innerHTML = m.icon;
                $('ascTitle').textContent = m.title;
                $('ascListLabel').textContent = m.listLabel;
                $('ascSearch').value = '';
                $('ascFilter').value = '';
                $('ascFootMsg').textContent = '';

                if (!modalIsOpen) {
                    $('ascModal').classList.remove('hidden');
                    $('ascTable').innerHTML = '<tbody><tr><td class="p-5 text-slate-400">Yuklanmoqda...</td></tr></tbody>';
                }
                renderAscButtons();

                if (ascCache[type]) {
                    ascData = ascCache[type].data;
                    $('ascFootMsg').textContent = ascCache[type].foot || '';
                    buildAscFilter();
                    renderAscTable();
                    animateAscPanel();
                    return;
                }

                $('ascFootMsg').textContent = 'Yuklanmoqda...';
                try {
                    if (type === 'subjects') {
                        const j = await api(BASE + '/boards/' + board.id + '/subjects');
                        ascData = j.subjects || [];
                        $('ascFootMsg').textContent = 'Manba: ishchi o\'quv rejalar · hafta soni: ' + j.weeks;
                    } else if (type === 'groups') {
                        const j = await api(BASE + '/boards/' + board.id + '/groups');
                        ascData = j.groups || [];
                    } else if (type === 'auditoriums') {
                        ascData = await api(AUDS_URL);
                    } else if (type === 'teachers') {
                        ascData = await api(TEACHERS_URL);
                    }
                    if (ascType !== type) return;
                    ascCache[type] = { data: ascData, foot: $('ascFootMsg').textContent };
                } catch (e) {
                    if (ascType !== type) return;
                    ascData = [];
                    $('ascFootMsg').textContent = 'Xatolik: ' + e.message;
                }
                buildAscFilter();
                renderAscTable();
                animateAscPanel();
            }

            function animateAscPanel() {
                const panel = $('ascPanel');
                if (!panel) return;
                panel.classList.remove('asc-panel-enter');
                void panel.offsetWidth;
                panel.classList.add('asc-panel-enter');
            }

            function buildAscFilter() {
                const f = $('ascFilter');
                const meta = dialogMeta[ascType];
                if (meta.filter === 'spec') {
                    const specs = [...new Set(ascData.map(r => r.specialty_name + ' · ' + r.course + '-kurs'))].sort();
                    f.innerHTML = '<option value="">— barcha yo\'nalishlar —</option>' +
                        specs.map(s => '<option value="' + esc(s) + '">' + esc(s) + '</option>').join('');
                    f.classList.remove('hidden');
                } else { f.classList.add('hidden'); }
            }

            function filteredAsc() {
                const q = ($('ascSearch').value || '').toLowerCase().trim();
                const fv = $('ascFilter').value;
                return ascData.filter(r => {
                    if (fv && (r.specialty_name + ' · ' + r.course + '-kurs') !== fv) return false;
                    const haystack = ascType === 'subjects'
                        ? JSON.stringify({
                            ...r,
                            semester_display: subjectSeasonSemesterLabel(r, subjectSeasonOf(r)),
                            season_display: subjectSeasonLabel(subjectSeasonOf(r)),
                        }).toLowerCase()
                        : JSON.stringify(r).toLowerCase();
                    if (q && !haystack.includes(q)) return false;
                    if (ascType !== 'subjects') return true;

                    const f = ascColumnFilters;
                    const mode = (subjectSettings[subjModeKey(r.specialty_name, r.course, r.subject_name)] || { mode: 'normal' }).mode || 'normal';
                    const values = {
                        subject: r.subject_name,
                        course: r.specialty_name + ' · ' + r.course + '-kurs',
                        semester: subjectSeasonSemesterLabel(r, subjectSeasonOf(r)),
                        department: r.kafedra_name || '',
                        lecture: r.lecture,
                        practice: (+r.practice || 0) + (+r.laboratory || 0) + (+r.seminar || 0),
                        week_load: (r.week_plan ? r.week_plan.per_week_hours : ''),
                        mode: SUBJ_MODE_LABELS[mode] || mode,
                    };
                    return Object.entries(f).every(([key, value]) => {
                        if (!value) return true;
                        return String(values[key] ?? '').toLowerCase().includes(String(value).toLowerCase());
                    });
                });
            }

            // Soatni chiroyli ko'rsatish: 6 → "6", 4.5 → "4,5"
            const hrs = v => {
                const n = +v || 0;
                return (Number.isInteger(n) ? String(n) : n.toFixed(1).replace('.', ',')).replace(/,0$/, '');
            };
            // "Hafta yuki" ustuni — jami soat / semestr haftalari
            function weekLoadHtml(r) {
                const w = r.week_plan;
                if (!w || !w.total_hours) return '<span class="text-slate-400">—</span>';
                if ((subjectSettingOf(r).mode || 'normal') === 'cycle') {
                    return '<b>6</b> s<div class="text-[10px] text-slate-400">' + hrs(w.total_hours) + ' s jami</div>';
                }
                return '<b>' + hrs(w.per_week_hours) + '</b> s'
                    + '<div class="text-[10px] text-slate-400">' + hrs(w.total_hours) + ' s jami</div>';
            }
            // "Haftalik taqsimot" ustuni — ma'ruzali / ma'ruzasiz haftalar
            function weekSplitHtml(r) {
                const w = r.week_plan;
                if (!w || !w.total_hours) return '<span class="text-slate-400">—</span>';
                if ((subjectSettingOf(r).mode || 'normal') === 'cycle') {
                    return '';
                }
                const parts = [];
                if (w.lecture_weeks > 0) {
                    parts.push('<div><b>' + w.lecture_weeks + '</b> hafta: 2 s ma\'ruza'
                        + (w.practice_in_lecture_week > 0 ? ' + ' + hrs(w.practice_in_lecture_week) + ' s amaliy' : '') + '</div>');
                }
                if (w.plain_weeks > 0 && w.practice_in_plain_week > 0) {
                    parts.push('<div><b>' + w.plain_weeks + '</b> hafta: ' + hrs(w.practice_in_plain_week) + ' s amaliy</div>');
                }
                if (w.extra_weeks > 0) {
                    parts.push('<div class="text-slate-500">+1 s qo\'shimcha: <b>' + w.extra_weeks + '</b> hafta</div>');
                }
                let warn = w.exact ? ''
                    : '<div class="text-[10px] text-amber-600" title="Reja soati bu hafta soniga aniq sig\'madi">⚠ reja soatiga sig\'madi</div>';
                // Haftalik chegarani buzmaslik uchun joylanmay qolgan amaliy soat
                if (w.practice_shortfall > 0) {
                    warn += '<div class="text-[10px] text-amber-600" title="Haftalik yuk chegarasidan oshmaslik uchun bu soat kartochkaga joylanmadi. Hafta sonini yoki reja soatini ko\'rib chiqing.">'
                        + '⚠ ' + hrs(w.practice_shortfall) + ' s amaliy joylanmadi</div>';
                }
                return '<div class="text-[11px] leading-tight">' + (parts.join('') || '—') + warn + '</div>';
            }

            function subjectFilterControl(key, placeholder, type = 'text') {
                const value = ascColumnFilters[key] || '';
                if (type === 'select') {
                    const optionValues = key === 'mode'
                        ? Object.entries(SUBJ_MODE_LABELS).map(([mode, label]) => [mode, label])
                        : [...new Set(ascData.map(r => r.course))]
                            .sort((a, b) => (+a || 0) - (+b || 0))
                            .map(course => [course, course + '-kurs']);
                    const options = optionValues
                        .map(([optionValue, label]) => '<option value="' + esc(optionValue) + '"' + (String(value) === String(optionValue) ? ' selected' : '') + '>' + esc(label) + '</option>').join('');
                    return '<select class="asc-column-filter" data-filter-key="' + key + '"><option value="">Barchasi</option>' + options + '</select>';
                }
                return '<input class="asc-column-filter" data-filter-key="' + key + '" type="' + type + '" value="' + esc(value) + '" placeholder="' + placeholder + '">';
            }

            function renderAscTable() {
                $('ascTable').classList.toggle('asc-auditorium-table', ascType === 'auditoriums');
                $('ascTable').classList.toggle('asc-subject-table', ascType === 'subjects');
                const rows = filteredAsc();
                $('ascCount').textContent = rows.length + ' ta';
                let h = '';
                if (ascType === 'subjects') {
                    h = '<thead><tr><th>Fan</th><th>Fakultet · yo\'nalish · kurs</th><th>Semestr</th><th>Kafedra</th><th>Ma\'ruza s.</th><th>Amaliy s.</th>' +
                        '<th title="Jami soat / semestr haftalari — haftada shundan oshmasligi kerak">Hafta yuki</th>' +
                        '<th title="Ma\'ruza 2 soatdan. Ma\'ruzali haftada amaliy shunga kamayadi, ma\'ruzasiz haftada to\'liq yuk amaliyga beriladi.">Haftalik taqsimot</th>' +
                        '<th>Fan rejimi</th></tr>' +
                        '<tr class="asc-column-filter-row">' +
                        '<th>' + subjectFilterControl('subject', 'Fan...') + '</th>' +
                        '<th>' + subjectFilterControl('course', 'Kurs', 'select') + '</th>' +
                        '<th>' + subjectFilterControl('semester', 'Semestr...') + '</th>' +
                        '<th>' + subjectFilterControl('department', 'Kafedra...') + '</th>' +
                        '<th>' + subjectFilterControl('lecture', 'Soat', 'number') + '</th>' +
                        '<th>' + subjectFilterControl('practice', 'Soat', 'number') + '</th>' +
                        '<th>' + subjectFilterControl('week_load', 'Soat', 'number') + '</th>' +
                        '<th></th>' +
                        '<th>' + subjectFilterControl('mode', 'Rejim...', 'select') + '</th>' +
                        '</tr></thead><tbody>';
                    let lastSpec = null;
                    rows.forEach((r, i) => {
                        const faculty = r.faculty_name || 'Fakultet ko\'rsatilmagan';
                        const sk = (r.faculty_name || '') + '·' + r.specialty_name + '·' + r.course;
                        if (sk !== lastSpec) {
                            h += '<tr class="asc-row-head"><td colspan="9"><div class="asc-subject-faculty">' + esc(faculty) + '</div><div class="asc-subject-specialty">' + esc(r.specialty_name) + ' · ' + r.course + '-kurs</div></td></tr>';
                            lastSpec = sk;
                        }
                        const setting = { mode: 'normal', ...subjectSettingOf(r), season: subjectSeasonOf(r) };
                        const modeOptions = Object.entries(SUBJ_MODE_LABELS).map(([value, label]) =>
                            '<option value="' + value + '"' + (setting.mode === value ? ' selected' : '') + '>' + label + '</option>').join('');
                        h += rowTag(i) + '<td>' + esc(r.subject_name) + '</td><td class="asc-subject-path"><div class="asc-subject-faculty">' + esc(faculty) + '</div><div class="asc-subject-specialty">' + esc(r.specialty_name) + ' · ' + r.course + '-kurs</div></td>' +
                            '<td><span class="asc-semester-pill asc-semester-' + esc(r.season || '') + '">' + esc(r.semester_label || (r.semester ? r.semester + '-semestr' : '—')) + '</span></td>' +
                            '<td>' + esc(r.kafedra_name || '—') + '</td><td>' + fmt(r.lecture) + '</td><td>' + fmt(r.practice + r.laboratory + r.seminar) +
                            '</td><td>' + weekLoadHtml(r) + '</td><td>' + weekSplitHtml(r) + '</td>' +
                            '<td class="asc-subj-mode-cell"><select class="asc-subj-mode">' + modeOptions + '</select><div class="asc-subj-params">' +
                            subjectModeParamsHtml(setting) + '</div><span class="asc-subj-status" aria-live="polite"></span></td></tr>';
                    });
                } else if (ascType === 'groups') {
                    h = '<thead><tr><th>Guruh</th><th>Yo\'nalish · kurs</th><th>Oqim</th><th>Til</th><th>Talaba</th></tr></thead><tbody>';
                    rows.forEach((r, i) => {
                        h += rowTag(i) + '<td class="font-semibold">' + esc(r.group_name) + '</td><td>' + esc(r.specialty_name) + ' · ' + r.course + '-kurs</td>' +
                            '<td>' + esc(r.oqim_label || '—') + '</td><td>' + esc(LANG_LABEL[r.lang] || r.lang || '—') + '</td><td>' + r.students + '</td></tr>';
                    });
                } else if (ascType === 'auditoriums') {
                    h = '<colgroup><col class="tt-aud-code"><col class="tt-aud-name"><col class="tt-aud-volume"><col class="tt-aud-building"><col class="tt-aud-type"><col class="tt-aud-status"></colgroup><thead><tr><th>Kod</th><th>Nomi</th><th>Sig\'im</th><th>Bino</th><th>Turi</th><th>Holat</th></tr></thead><tbody>';
                    rows.forEach((r, i) => {
                        h += rowTag(i, r.id) + '<td class="font-semibold">' + esc(r.code) + '</td><td>' + esc(r.name) + '</td>' +
                            '<td>' + audVolumeHtml(r.volume) + '</td><td>' + esc(r.building_name || '—') + '</td><td>' + esc(r.auditorium_type_name || '—') + '</td>' +
                            '<td>' + (r.active ? '<span class="text-green-600">faol</span>' : '<span class="text-gray-400">nofaol</span>') + '</td></tr>';
                    });
                } else if (ascType === 'teachers') {
                    h = '<thead><tr><th>F.I.O.</th><th>Qisqa</th><th>Kafedra</th><th>Lavozim</th></tr></thead><tbody>';
                    rows.forEach((r, i) => {
                        h += rowTag(i, r.id) + '<td>' + esc(r.full_name) + '</td><td>' + esc(r.short_name || '—') + '</td>' +
                            '<td>' + esc(r.department || '—') + '</td><td>' + esc(r.lavozim || '—') + '</td></tr>';
                    });
                }
                h += '</tbody>';
                $('ascTable').innerHTML = h;
                const applyColumnFilter = ev => {
                    if (!ev.target.classList.contains('asc-column-filter')) return;
                    const key = ev.target.dataset.filterKey;
                    const cursor = typeof ev.target.selectionStart === 'number' ? ev.target.selectionStart : null;
                    ascColumnFilters[key] = ev.target.value;
                    renderAscTable();
                    const next = $('ascTable').querySelector('[data-filter-key="' + key + '"]');
                    if (next) {
                        next.focus();
                        if (cursor !== null && typeof next.setSelectionRange === 'function') {
                            next.setSelectionRange(cursor, cursor);
                        }
                    }
                };
                $('ascTable').oninput = applyColumnFilter;
                $('ascTable').onchange = applyColumnFilter;
                document.querySelectorAll('#ascTable tbody tr[data-idx]').forEach(tr => {
                    if (ascType === 'subjects') {
                        const row = rows[+tr.dataset.idx];
                        const semesterCell = tr.querySelector('.asc-semester-pill')?.parentElement || null;
                        if (semesterCell && !tr.querySelector('.asc-subj-season')) {
                            semesterCell.classList.add('asc-subj-season-cell');
                            semesterCell.innerHTML = '<select class="asc-subj-season"></select>';
                            repaintSubjectSeason(tr, row, subjectSeasonOf(row));
                        }
                        const modeSelect = tr.querySelector('.asc-subj-mode');
                        const seasonSelect = tr.querySelector('.asc-subj-season');
                        const refreshParams = () => {
                            const current = subjectSettings[subjModeKey(row.specialty_name, row.course, row.subject_name)] || {};
                            tr.querySelector('.asc-subj-params').innerHTML = subjectModeParamsHtml({ ...current, mode: modeSelect.value });
                        };
                        modeSelect.onchange = async () => {
                            refreshParams();
                            await saveSubjectModeRow(tr, row);
                        };
                        if (seasonSelect) {
                            seasonSelect.onchange = () => saveSubjectModeRow(tr, row);
                            repaintSubjectSeason(tr, row, subjectSeasonOf(row));
                        }
                        tr.addEventListener('change', ev => {
                            if (ev.target.classList.contains('asc-subj-group') ||
                                ev.target.classList.contains('asc-subj-occ') ||
                                ev.target.classList.contains('asc-subj-cycle')) {
                                saveSubjectModeRow(tr, row);
                            }
                            // "Ma'ruza alohida": belgi qo'yilsa — soatlar kiritilgach saqlanadi; olinsa — darhol.
                            if (ev.target.classList.contains('asc-subj-lecon') || ev.target.classList.contains('asc-subj-lechours')) {
                                const lecOn = tr.querySelector('.asc-subj-lecon'), lecHours = tr.querySelector('.asc-subj-lechours');
                                lecHours.hidden = !lecOn.checked;
                                if (lecOn.checked && !lecHours.value.trim()) { lecHours.focus(); return; }
                                saveSubjectModeRow(tr, row);
                            }
                        });
                        // "Fakultet / o'quv reja bo'yicha alohida": oyna; saqlangach qatordagi soni va (sikl ko'rinishida) jadval yangilanadi.
                        tr.addEventListener('click', ev => {
                            if (!ev.target.closest || !ev.target.closest('.asc-subj-scope')) return;
                            ev.stopPropagation();
                            openSubjScopeDlg(row, async () => {
                                const j = await api(BASE + '/boards/' + board.id + '/subject-setting/scopes?' + new URLSearchParams({
                                    specialty_name: row.specialty_name, course: row.course, subject_name: row.subject_name }));
                                const key = subjModeKey(row.specialty_name, row.course, row.subject_name);
                                const scoped = [];
                                (j.faculties || []).forEach(f => {
                                    if (f.days != null || f.lecture) scoped.push({ faculty_name: f.name, curriculum_hemis_id: 0, cycle_days: f.days, lecture: f.lecture || null });
                                    (f.curricula || []).forEach(c => { if (c.days != null || c.lecture) scoped.push({ faculty_name: f.name, curriculum_hemis_id: c.id, cycle_days: c.days, lecture: c.lecture || null }); });
                                });
                                subjectSettings[key] = Object.assign({}, subjectSettingOf(row), { scoped });
                                refreshParams();
                                if (typeof viewMode !== 'undefined' && viewMode === 'cycle' && typeof loadCyclePlan === 'function') loadCyclePlan();
                            });
                        });
                    }
                    tr.onclick = () => {
                        ascSelId = tr.dataset.id || tr.dataset.idx;
                        document.querySelectorAll('#ascTable tbody tr').forEach(x => x.classList.remove('sel'));
                        tr.classList.add('sel');
                        renderAscButtons();
                    };
                    tr.ondblclick = () => {
                        if (ascType !== 'auditoriums') return;
                        const row = ascData.find(x => String(x.id) === String(tr.dataset.id));
                        if (row) openAudEdit(row);
                    };
                });
                if (ascType === 'subjects') renderAscButtons();
            }
            const rowTag = (i, id) => '<tr data-idx="' + i + '"' + (id != null ? ' data-id="' + id + '"' : '') + '>';
            const fmt = v => { v = +v || 0; return Number.isInteger(v) ? v : v.toFixed(1); };

            const actionIcons = {
                plus: '01_new_document.png',
                edit: 'tahrirlash.png',
                trash: '11_delete.png',
                import: '02_open_folder.png',
                template: '05_print_preview.png',
                export: '04_print.png',
            };
            const actionIcon = name => '<span class="asc-action-icon" aria-hidden="true"><img class="tt-custom-icon" src="' + ICON_BASE + '/' + actionIcons[name] + '" alt="" aria-hidden="true"></span>';

            function renderAscButtons() {
                const b = $('ascButtons');
                if (ascType === 'subjects' && ascData.length) syncAutoCycleState();
                if (ascType === 'subjects' && ascData.length &&
                    autoCycleCandidates().some(item => (subjectSettingOf(item.row).mode || 'normal') === 'cycle')) {
                    autoCycleApplied = true;
                }
                const hasSel = ascSelId !== null;
                if (ascType === 'auditoriums') {
                    b.innerHTML =
                        '<button class="asc-btn primary asc-action-btn" id="aBtnNew">' + actionIcon('plus') + 'Yangi</button>' +
                        '<button class="asc-btn asc-action-btn" id="aBtnEdit"' + (hasSel ? '' : ' disabled') + '>' + actionIcon('edit') + 'Tahrirlash</button>' +
                        '<button class="asc-btn danger asc-action-btn" id="aBtnDel"' + (hasSel ? '' : ' disabled') + '>' + actionIcon('trash') + 'O\'chirish</button>' +
                        '<div class="my-1 border-t border-gray-300"></div>' +
                        '<button class="asc-btn asc-action-btn" id="aBtnImport">' + actionIcon('import') + 'Import (Excel)</button>' +
                        '<button class="asc-btn asc-action-btn" id="aBtnTemplate">' + actionIcon('template') + 'Namuna shabloni</button>';
                    $('aBtnNew').onclick = () => openAudEdit(null);
                    $('aBtnEdit').onclick = () => hasSel && openAudEdit(ascData.find(x => String(x.id) === String(ascSelId)));
                    $('aBtnDel').onclick = () => hasSel && deleteAud();
                    $('aBtnImport').onclick = () => $('audImportFile').click();
                    $('aBtnTemplate').onclick = downloadAudTemplate;
                } else if (ascType === 'subjects') {
                    // Fan rejimlari manba jadvalini o'zgartirmaydi, faqat doska
                    // uchun saqlanadigan Sikl sozlamalarini yaratadi.
                    b.innerHTML =
                        '<button class="asc-btn primary asc-action-btn" id="aBtnAutoCycle" title="4-6 kurs fanlarini jami soat / 6 bo‘yicha Sikl qilish">' +
                        '<i class="bi ' + (autoCycleApplied ? 'bi-arrow-counterclockwise' : 'bi-magic') + '" aria-hidden="true"></i> ' +
                        (autoCycleApplied ? 'Avvalgi holatiga qaytarish' : '4-6 kursni avtomatik Sikl') + '</button>' +
                        '<button class="asc-btn asc-action-btn" id="aBtnCsv" title="CSV ga eksport">' + actionIcon('export') + 'CSV ga eksport</button>';
                    $('aBtnAutoCycle').onclick = toggleAutoCycleSubjects;
                    $('aBtnCsv').onclick = exportAscCsv;
                } else {
                    // Faqat o'qish (manba HEMIS/o'quv reja) — eksport imkoniyati
                    b.innerHTML =
                        '<button class="asc-btn asc-action-btn" id="aBtnCsv" title="CSV ga eksport">' + actionIcon('export') + 'CSV ga eksport</button>';
                    $('aBtnCsv').onclick = exportAscCsv;
                }
            }

            $('ascSearch').oninput = () => renderAscTable();
            $('ascFilter').onchange = () => { ascSelId = null; renderAscTable(); renderAscButtons(); };
            $('ascClose').onclick = $('ascCloseBtn').onclick = () => $('ascModal').classList.add('hidden');

            // ── CSV eksport (faqat o'qiladigan dialoglar) ──
            function exportAscCsv() {
                const rows = filteredAsc();
                if (!rows.length) return;
                // Ichma-ich obyektlarni (mas. week_plan) alohida ustunlarga yoyamiz —
                // aks holda CSV da "[object Object]" bo'lib chiqadi.
                const flat = r => {
                    const o = {};
                    Object.entries(r).forEach(([k, v]) => {
                        if (v && typeof v === 'object' && !Array.isArray(v)) {
                            Object.entries(v).forEach(([k2, v2]) => { o[k + '_' + k2] = v2; });
                        } else { o[k] = v; }
                    });
                    return o;
                };
                const flatRows = rows.map(flat);
                const cols = [...new Set(flatRows.flatMap(r => Object.keys(r)))];
                const csv = [cols.join(',')].concat(flatRows.map(r =>
                    cols.map(c => '"' + String(r[c] ?? '').replace(/"/g, '""') + '"').join(','))).join('\n');
                dl('﻿' + csv, ascType + '.csv', 'text/csv');
            }
            function downloadAudTemplate() {
                dl('﻿kod,nomi,sigim,bino,turi\n101,"1-bino №101",30,"1-bino","Amaliy xona"\n', 'auditoriya-namuna.csv', 'text/csv');
            }
            function dl(content, name, type) {
                const a = document.createElement('a');
                a.href = URL.createObjectURL(new Blob([content], { type }));
                a.download = name; a.click(); URL.revokeObjectURL(a.href);
            }

            // ── Auditoriya CRUD ──
            let audEditId = null;
            function openAudEdit(a) {
                audEditId = a ? a.id : null;
                $('aeTitle').textContent = a ? 'Auditoriyani tahrirlash' : 'Yangi auditoriya';
                $('aeCode').value = a ? a.code : '';
                $('aeName').value = a ? a.name : '';
                $('aeVolume').value = a ? (a.volume || 0) : 30;
                $('aeBuilding').value = a ? (a.building_name || '') : '';
                $('aeType').value = a ? (a.auditorium_type_name || '') : '';
                $('aeActive').checked = a ? !!a.active : true;
                $('aeMsg').classList.add('hidden');
                $('audEditModal').classList.remove('hidden');
            }
            $('aeClose').onclick = $('aeCancel').onclick = () => $('audEditModal').classList.add('hidden');
            $('aeSave').onclick = async function () {
                this.disabled = true;
                const body = {
                    code: $('aeCode').value.trim(), name: $('aeName').value.trim(),
                    volume: $('aeVolume').value || 0, building_name: $('aeBuilding').value.trim(),
                    auditorium_type_name: $('aeType').value.trim(), active: $('aeActive').checked ? 1 : 0,
                };
                const url = BASE + '/auditoriums' + (audEditId ? '/' + audEditId : '');
                try {
                    await api(url, 'POST', body);
                    $('audEditModal').classList.add('hidden');
                    audCache = null;                       // rekvizit modalidagi kesh eskirdi
                    ascCache.auditoriums = null;
                    ascData = await api(AUDS_URL); ascSelId = null;
                    renderAscTable(); renderAscButtons();
                } catch (e) {
                    const m = $('aeMsg'); m.className = 'col-span-2 text-sm rounded px-3 py-2 bg-red-50 text-red-700';
                    m.textContent = e.message; m.classList.remove('hidden');
                }
                this.disabled = false;
            };
            async function deleteAud() {
                const a = ascData.find(x => String(x.id) === String(ascSelId));
                if (!a || !confirm('«' + a.name + '» auditoriyasi o\'chirilsinmi?')) return;
                try {
                    const f = new FormData(); f.append('_token', CSRF); f.append('_method', 'DELETE');
                    const r = await fetch(BASE + '/auditoriums/' + a.id, { method: 'POST', headers: { 'Accept': 'application/json' }, body: f });
                    const j = await r.json();
                    $('ascFootMsg').textContent = j.deactivated
                        ? 'Auditoriya jadvalda ishlatilgani uchun nofaol qilindi.' : 'O\'chirildi.';
                    audCache = null;
                    ascCache.auditoriums = null;
                    ascData = await api(AUDS_URL); ascSelId = null;
                    renderAscTable(); renderAscButtons();
                } catch (e) { alert('Xatolik: ' + e.message); }
            }
            $('audImportFile').onchange = async function () {
                if (!this.files.length) return;
                const f = new FormData(); f.append('_token', CSRF); f.append('file', this.files[0]);
                $('ascFootMsg').textContent = 'Import qilinmoqda...';
                try {
                    const r = await fetch(BASE + '/auditoriums/import', { method: 'POST', headers: { 'Accept': 'application/json' }, body: f });
                    const j = await r.json();
                    if (!r.ok) throw new Error(j.error || j.message || 'Xatolik');
                    $('ascFootMsg').textContent = 'Import: ' + j.imported + ' qo\'shildi, ' + j.updated + ' yangilandi' +
                        (j.errors && j.errors.length ? ' · ' + j.errors.length + ' xato' : '');
                    audCache = null;
                    ascData = await api(AUDS_URL); ascSelId = null;
                    renderAscTable(); renderAscButtons();
                } catch (e) { $('ascFootMsg').textContent = 'Xatolik: ' + e.message; }
                this.value = '';
            };

            // ══════════════════════════════════════════════════════════════
            //  Excel ko'rinishidagi jadval (kunlar/paralar qatorda, guruhlar ustunda)
            // ══════════════════════════════════════════════════════════════
            let excelMode = 'group';   // group | teacher | room
            // "Excelga yuklash" — ekrandagi HAQIQIY panjarani (chiziqlar, ranglar,
            // birlashgan kataklar bilan) aynan o'zini Excel'ga chiqaradi.
            $('excelViewBtn').onclick = () => downloadExcelXls();
            $('excelClose').onclick = () => $('excelModal').classList.add('hidden');
            $('excelPrint').onclick = () => window.print();
            $('excelDownload').onclick = () => downloadExcelXls();

            // ── Rang yordamchisi (Excel eksporti uchun) ──
            const rgbToHex = c => {
                const m = String(c).match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
                if (!m) return null;
                return '#' + [1, 2, 3].map(i => (+m[i]).toString(16).padStart(2, '0')).join('');
            };
            // ── Panjarani ixcham katak ma'lumoti sifatida yig'ish ──────────────
            // Ilgari butun jadval inline-uslubli HTML bo'lib yuborilar, server esa
            // uni PhpSpreadsheet ning HTML o'quvchisi orqali o'qirdi. Katta doskada
            // (o'n minglab katak) bu juda sekin — so'rov timeout bo'lib, brauzer
            // jimgina HTML ni ".xls" nomi bilan saqlab qo'yardi. Excel esa aynan
            // shu sababli "fayl formati kengaytmaga mos emas" deb ogohlantirardi.
            // Endi faqat matn + rang + birlashtirish ma'lumoti yuboriladi va server
            // xlsx ni to'g'ridan-to'g'ri yozadi.
            function excelCardText(card) {
                if (!card) return '';

                const cardGrid = gridForCard(card);
                const totalWeeks = Math.max(1, +cardGrid.weeks || +(board && board.weeks) || +card.weeks || 15);
                const activeWeeks = [];
                let hasWeekExceptions = false;

                for (let week = 1; week <= totalWeeks; week++) {
                    const override = overrides[card.id + '|' + week];
                    if (override && override.cancelled) {
                        hasWeekExceptions = true;
                    } else {
                        activeWeeks.push(week);
                    }
                }

                let weeksText;
                if (hasWeekExceptions) {
                    weeksText = activeWeeks.length ? activeWeeks.join(', ') : '—';
                } else if (+card.weeks > 0 && +card.weeks < totalWeeks) {
                    weeksText = card.weeks + ' hafta';
                } else {
                    weeksText = '1–' + totalWeeks;
                }

                const lessonType = card.training_type === 'lecture' ? 'M' : 'A';
                const flow = card.oqim_label || card.group_name || '—';
                const ec = typeof effectiveCard === 'function' ? effectiveCard(card) : card;
                const room = String(ec.auditorium_name || ec.auditorium_code || '').trim();

                return [
                    card.faculty_name || '—',
                    (card.specialty_name || '—') + (card.course ? ' · ' + card.course + '-kurs' : ''),
                    '[' + lessonType + '] ' + (card.subject_name || '—'),
                    'Oqim: ' + flow,
                    card.teacher_name ? "O'qituvchi: " + card.teacher_name : null,
                    room ? 'Xona: ' + room : null,
                    '(Haftalar: ' + weeksText + ')',
                ].filter(Boolean).join('\n');
            }

            function gridExportCells() {
                const grid = document.getElementById('grid');
                if (!grid || !grid.querySelector('tbody tr')) return null;
                const rows = [];
                grid.querySelectorAll('tr').forEach(tr => {
                    const cells = [];
                    [...tr.children].forEach(el => {
                        if (el.tagName !== 'TD' && el.tagName !== 'TH') return;
                        // Chip (kartochka) bo'lsa rangni undan olamiz — katak oq bo'lsa ham
                        // Excelda dars rangi ekrandagidek chiqsin.
                        const chip = el.querySelector('.tt-chip');
                        const cs = getComputedStyle(chip || el);
                        const bgRaw = cs.backgroundColor;
                        const transparent = !bgRaw || bgRaw === 'transparent' || bgRaw === 'rgba(0, 0, 0, 0)';
                        const subjectChips = [...el.children]
                            .filter(child => child.classList && child.classList.contains('tt-chip'));
                        const subjectTexts = subjectChips.map(child => {
                            const card = cards.find(item => item.id === +child.dataset.chip);
                            return card ? excelCardText(card) : (child.innerText || '').replace(/\s+/g, ' ').trim();
                        }).filter(Boolean);
                        // Bo'lak katagi: sarlavha (fan) + har bo'lak qatori (harf, guruh, talaba, o'qituvchi, vaqt)
                        const bolakText = el.classList.contains('tt-bolak-cell')
                            ? [el.querySelector('.tt-bolak-head'), ...el.querySelectorAll('.tt-bolak-item')]
                                .filter(Boolean).map(x => {
                                    const card = x.classList.contains('tt-bolak-item') ? cards.find(item => item.id === +x.dataset.chip) : null;
                                    const base = (x.innerText || '').replace(/\s+/g, ' ').trim();
                                    const ec = card && typeof effectiveCard === 'function' ? effectiveCard(card) : card;
                                    const room = ec ? String(ec.auditorium_name || ec.auditorium_code || '').trim() : '';
                                    return (x.classList.contains('tt-bolak-item') ? '• ' : '') + base
                                        + (card && card.teacher_name && !base.includes(card.teacher_name) ? ' · ' + card.teacher_name : '')
                                        + (room ? ' · №' + room.replace(/^№\s*/u, '') : '');
                                }).join('\n')
                            : '';
                        const exportedText = bolakText || (subjectTexts.length
                            ? subjectTexts.join('\n────────────\n')
                            : (el.innerText || '').replace(/\s+/g, ' ').trim());
                        const cell = { t: exportedText };
                        if (el.colSpan > 1) cell.cs = el.colSpan;
                        if (el.rowSpan > 1) cell.rs = el.rowSpan;
                        if (!transparent) { const hex = rgbToHex(bgRaw); if (hex) cell.bg = hex; }
                        if (parseInt(cs.fontWeight, 10) >= 600) cell.b = 1;
                        cells.push(cell);
                    });
                    rows.push(cells);
                });
                // Chapda 3 ustun qotiriladi: kun, para (rim raqami), yarim para vaqti.
                return { rows, freeze_rows: grid.querySelectorAll('thead tr').length, freeze_cols: 3, col_widths: [null, null, 9] };
            }

            // Jadvalni HAQIQIY .xlsx fayl sifatida yuklab olish (serverda PhpSpreadsheet
            // orqali) — Excel "format kengaytmага mos emas" ogohlantirishi chiqmaydi.
            async function downloadExcelXls() {
                const cellData = gridExportCells();
                if (!cellData) { alert('Yuklab olish uchun panjara yo\'q.'); return; }
                const title = (board.institution_name ? board.institution_name + ' — ' : '') + (board.name || 'Dars jadvali') +
                    (curWeek ? ' · ' + curWeek + '-hafta' : '');
                const base = (board.name || 'dars-jadvali').replace(/[^\w\-]+/g, '_') +
                    (curWeek ? '_' + curWeek + '-hafta' : '');
                await sendExcelExport(cellData, title, base, $('excelViewBtn'));
            }
            // Katak ma'lumotini serverga yuborib, tayyor .xlsx ni yuklab oladi.
            async function sendExcelExport(cellData, title, base, btn) {
                const btnHtml = btn ? btn.innerHTML : null;
                if (btn) { btn.disabled = true; btn.textContent = 'Tayyorlanmoqda…'; }
                try {
                    const fd = new FormData();
                    fd.append('_token', CSRF);
                    fd.append('payload', JSON.stringify(cellData));
                    fd.append('title', title);
                    fd.append('filename', base);
                    const r = await fetch(BASE + '/boards/' + board.id + '/excel-export', {
                        method: 'POST', headers: { 'Accept': 'application/json' }, body: fd
                    });
                    if (!r.ok) {
                        let msg = 'HTTP ' + r.status;
                        try { const j = await r.json(); if (j && j.error) msg = j.error; } catch (_) { }
                        throw new Error(msg);
                    }
                    const blob = await r.blob();
                    const url = URL.createObjectURL(blob);
                    const a = document.createElement('a');
                    a.href = url; a.download = base + '.xlsx';
                    document.body.appendChild(a); a.click(); a.remove();
                    setTimeout(() => URL.revokeObjectURL(url), 5000);
                } catch (e) {
                    // Jimgina ".xls" (aslida HTML) saqlamaymiz — Excel uni "format
                    // kengaytmaga mos emas" deb ogohlantiradi va sabab ko'rinmay qoladi.
                    alert('Excel faylini yaratib bo\'lmadi: ' + e.message +
                        '\n\nQamrovni kichraytirib (fakultet/kurs tanlab) qayta urinib ko\'ring.');
                } finally {
                    if (btn && btnHtml !== null) { btn.disabled = false; btn.innerHTML = btnHtml; }
                }
            }
            // ── Sikl jadvalini Excelga yuklash (tashqi yoki ichki — ekranda qaysi bo'lsa) ──
            // Bloklar ekranda ustma-ust (overlay) chizilgani uchun DOM emas,
            // yuklangan reja (cyclePlanData) dan katak ma'lumoti tuziladi.
            function cycleExportPayload(j) {
                const dates = j.dates || [];
                // Ekrandagi qatorlar bilan bir xil (guruhcha tanlansa — uning bo'lak qatorlari ham).
                const rows = cycleVisibleRows(j.rows || []);
                if (!rows.length || !dates.length) return null;
                const WD = ['', 'Du', 'Se', 'Ch', 'Pa', 'Ju', 'Sh', 'Ya'];
                const OFF_BG = '#e2e8f0', HOL_BG = '#fecaca';
                const offBg = d => d && d.holiday ? HOL_BG : (d && d.off ? OFF_BG : null);
                const vis = [];
                dates.forEach((d, i) => { if (!cycleColHidden(i)) vis.push(i); });
                const visCount = (a, b) => vis.filter(i => i >= a && i <= b).length;
                const blockText = (b, extra) => {
                    const parts = [b.subject + ' (' + b.days + ' kun)'];
                    if (extra) parts.push(...extra.filter(Boolean));
                    return parts.join('\n');
                };
                const groupLabel = row => (j.view || cycleViewMode) === 'group' || !(row.subgroups || []).length
                    ? row.group
                    : row.group + '\n' + row.subgroups.join(', ');
                const isGroupView = (j.view || cycleViewMode) === 'group';
                const out = [], heights = {};
                const push = (cells, h) => { if (h) heights[out.length] = h; out.push(cells); };

                if (j.mark_mode) {
                    // ── Ichki: har guruhcha — fan qatori + kunlik yarim-para qatorlari ──
                    const dayHours = Math.max(1, +j.day_hours || 6);
                    const bell = boardSchedule().filter(it => it.type === 'pair');
                    const tm = t => { const m = /^(\d{1,2}):(\d{2})$/.exec(t || ''); return m ? (+m[1]) * 60 + (+m[2]) : null; };
                    const hm = v => String(Math.floor(v / 60)).padStart(2, '0') + ':' + String(v % 60).padStart(2, '0');
                    // Para necha soatligi ekrandagidek — barcha paralar o'rtacha davomiyligidan
                    // (birinchi para 0.5-para bo'lishi mumkin, faqat unga qarash noto'g'ri).
                    const durs = bell.map(it => { const a = tm(it.start), e = tm(it.end); return a != null && e != null && e > a ? e - a : null; }).filter(v => v != null);
                    const hpp = (durs.length ? durs.reduce((x, y) => x + y, 0) / durs.length : 80) >= 60 ? 2 : 1;
                    push([{ t: isGroupView ? 'Guruh' : 'Oqim', b: 1, bg: '#dbe4f0' }, { t: 'Para', b: 1, bg: '#dbe4f0' }, { t: 'Vaqt', b: 1, bg: '#dbe4f0' }]
                        .concat(vis.map(i => ({ t: dates[i].d + '\n' + (WD[dates[i].dow] || ''), b: 1, bg: offBg(dates[i]) || '#dbe4f0' }))), 26);
                    rows.forEach(row => {
                        // Ustma-ust tushgan blok chizilmaydi (ekrandagidek).
                        const owner = new Array(dates.length).fill(null);
                        (row.blocks || []).forEach(b => {
                            if (b.from == null || b.to == null) return;
                            for (let c = b.from; c <= b.to && c < dates.length; c++) if (owner[c]) return;
                            for (let c = b.from; c <= b.to && c < dates.length; c++) owner[c] = b;
                        });
                        // Guruhcha bo'lak qatori orqali o'qiydigan sikl — ekrandagidek ishora (sanalar bo'sh bo'lsa).
                        cycleVariantRowsOf(j.rows || [], row).forEach(v => (v.blocks || []).forEach(b => {
                            if (b.from == null || b.to == null) return;
                            for (let c = b.from; c <= b.to && c < dates.length; c++) if (owner[c]) return;
                            const ghost = { ...b, ghost: true, ghost_letter: (/\((\p{L})\)\s*$/u.exec(v.variant || '') || [])[1] || '' };
                            for (let c = b.from; c <= b.to && c < dates.length; c++) owner[c] = ghost;
                        }));
                        // Fan qatori
                        const head = [{ t: groupLabel(row), rs: dayHours + 1, b: 1, al: 'l' }, { t: 'Fan', cs: 2, b: 1, bg: '#f1f5f9' }];
                        for (let v = 0; v < vis.length; v++) {
                            const b = owner[vis[v]];
                            if (!b) { head.push({ t: '', bg: offBg(dates[vis[v]]) }); continue; }
                            let n = 1;
                            while (v + n < vis.length && owner[vis[v + n]] === b) n++;
                            if (b.ghost) {
                                head.push({ t: String(b.subject).replace(/\s*\(\p{L}\)\s*$/u, '') + '\n(' + b.ghost_letter + ") bo'lakda · " + b.days + ' kun',
                                    cs: n, b: 1, bg: '#ede9fe', fc: '#6d28d9' });
                                v += n - 1;
                                continue;
                            }
                            const plan = Object.values(b.day_plan || {});
                            const sl = plan.reduce((a, d) => a + (+d.lec || 0), 0), sp = plan.reduce((a, d) => a + (+d.prc || 0), 0);
                            const req = [b.teacher_name, b.auditorium_name || b.auditorium_code].filter(Boolean).join(' · ');
                            head.push({
                                t: blockText(b, [req, 'M ' + sl + (b.lecture_hours != null ? '/' + b.lecture_hours : '') + ' · A ' + sp + (b.practice_hours != null ? '/' + b.practice_hours : '') + ' soat']),
                                cs: n, b: 1, bg: subjColor(b.subject).bg,
                            });
                            v += n - 1;
                        }
                        push(head, 40);
                        // Soat (yarim para) qatorlari
                        for (let hour = 1; hour <= dayHours; hour++) {
                            const pt = bell[Math.ceil(hour / hpp) - 1];
                            const part = (hour - 1) % hpp;
                            const cells = [];
                            if (part === 0) {
                                const abbr = pt ? (pt.abbr && pt.abbr !== '—' ? pt.abbr : (pt.name || Math.ceil(hour / hpp))) : Math.ceil(hour / hpp);
                                cells.push({ t: abbr + '\npara', rs: Math.min(hpp, dayHours - hour + 1), b: 1, bg: '#e8eef6' });
                            }
                            const a = pt ? tm(pt.start) : null, e = pt ? tm(pt.end) : null;
                            cells.push({ t: a != null && e != null ? hm(Math.round(a + (e - a) / hpp * part)) + '–' + hm(Math.round(a + (e - a) / hpp * (part + 1))) : '' });
                            vis.forEach(i => {
                                const d = dates[i], b = owner[i];
                                if (d.off) { cells.push({ t: '', bg: offBg(d) }); return; }
                                if (!b) { cells.push({ t: '' }); return; }
                                if (b.ghost) { cells.push({ t: '', bg: '#f5f3ff' }); return; }   // dars bo'lak qatorida
                                const dp = (b.day_plan || {})[i - b.from];
                                const st = dp ? (+dp.start || 1) : 0, l = dp ? (+dp.lec || 0) : 0, p = dp ? (+dp.prc || 0) : 0;
                                const ps = dp && dp.ps != null ? +dp.ps : st + l;
                                if (dp && hour >= st && hour < st + l) cells.push({ t: 'M', b: 1, bg: '#facc15', fc: '#713f12' });
                                else if (dp && hour >= ps && hour < ps + p) cells.push({ t: 'A', b: 1, bg: '#c9e8e5', fc: '#0f766e' });
                                else cells.push({ t: '', bg: subjColor(b.subject).bg });
                            });
                            push(cells, 13);
                        }
                    });
                    return {
                        rows: out, row_heights: heights, freeze_rows: 1, freeze_cols: 3, font_size: 8, landscape: 1,
                        sheet_title: 'Ichki jadval', col_widths: [22, 6, 10].concat(vis.map(() => 4.6)),
                    };
                }

                // ── Tashqi: har qator — oqim/guruh, bloklar sanalar bo'ylab birlashgan ──
                push([{ t: isGroupView ? 'Guruh' : 'Oqim', b: 1, bg: '#dbe4f0' }]
                    .concat(vis.map(i => ({ t: dates[i].d + '\n' + (WD[dates[i].dow] || ''), b: 1, bg: offBg(dates[i]) || '#dbe4f0' }))), 26);
                rows.forEach(row => {
                    // Kesishgan bloklar alohida qatorchaga (lane) tushadi — hech biri yo'qolmaydi.
                    const lanes = [];
                    // "Fan (a)/(b)/(c)" — bitta sikl bo'laklari: bir xil sanalarda bitta blok.
                    const vBase = n => String(n || '').replace(/\s*\(\p{L}\)\s*$/u, '').trim().toLowerCase();
                    const seenVar = new Set();
                    [...(row.blocks || [])].filter(b => b.from != null && b.to != null)
                        .filter(b => { const k = vBase(b.subject) + '|' + b.from + '|' + b.to; if (seenVar.has(k)) return false; seenVar.add(k); return true; })
                        .sort((x, y) => x.from - y.from || (+x.pair || 1) - (+y.pair || 1))
                        .forEach(b => {
                            const to = Math.min(b.to, dates.length - 1);
                            if (visCount(b.from, to) < 1) return;
                            let lane = lanes.find(l => l.every(o => o.to < b.from || o.from > to));
                            if (!lane) { lane = []; lanes.push(lane); }
                            lane.push({ from: b.from, to: to, b: b });
                        });
                    if (!lanes.length) lanes.push([]);
                    const labelLines = (groupLabel(row).match(/\n/g) || []).length + 1 + Math.floor(groupLabel(row).length / 40);
                    const laneH = Math.max(36, Math.ceil(labelLines * 11 / lanes.length) + 4);
                    lanes.forEach((lane, li) => {
                        const cells = li === 0 ? [{ t: groupLabel(row), rs: lanes.length, b: 1, al: 'l' }] : [];
                        const at = {};
                        lane.forEach(o => { at[vis.find(i => i >= o.from && i <= o.to)] = o; });
                        for (let v = 0; v < vis.length; v++) {
                            const o = at[vis[v]];
                            if (!o) { cells.push({ t: '', bg: offBg(dates[vis[v]]) }); continue; }
                            const n = visCount(o.from, o.to);
                            const b = o.b;
                            cells.push({
                                t: (j.simple ? '' : (b.type === 'lecture' ? '[M] ' : '[A] ')) + blockText(b, [b.hours ? b.hours + ' soat' : '']),
                                cs: n, b: 1, bg: subjColor(b.subject).bg,
                            });
                            v += n - 1;
                        }
                        push(cells, laneH);
                    });
                });
                return {
                    rows: out, row_heights: heights, freeze_rows: 1, freeze_cols: 1, font_size: 8, landscape: 1,
                    sheet_title: 'Tashqi jadval', col_widths: [26].concat(vis.map(() => 6.5)),
                };
            }
            async function downloadCycleExcel() {
                const j = cyclePlanData;
                const payload = j ? cycleExportPayload(j) : null;
                if (!payload) { alert('Yuklab olish uchun sikl jadvali yo\'q.'); return; }
                const internal = Boolean(j.mark_mode);
                const label = internal ? 'Ichki' : 'Tashqi';
                const start = j.start_date ? j.start_date.split('-').reverse().join('.') : '';
                const filterLabel = cycleRowFilters.length ? cycleRowFilterText(j.rows || [], (j.view || cycleViewMode) === 'group' ? 'Guruh' : 'Oqim') : '';
                const title = (board.institution_name ? board.institution_name + ' — ' : '') + (board.name || 'Dars jadvali') +
                    ' · Sikl jadvali (' + label.toLowerCase() + ')' + (filterLabel ? ' · ' + filterLabel : '') +
                    (start ? ' · semestr boshi ' + start : '');
                const base = ((board.name || 'dars-jadvali') + '_sikl_' + label.toLowerCase() + (filterLabel ? '_' + filterLabel : ''))
                    .replace(/[^\w\-]+/g, '_');
                await sendExcelExport(payload, title, base, $('cycleExcel'));
            }
            if ($('cycleExcel')) $('cycleExcel').onclick = () => downloadCycleExcel();
            // Haftalik jadval (1–3 kurs): ekrandagi panjara — tanlangan hafta/shablon, tashqi/ichki qatlam
            // va ko'rinish qamrovi (Butun doska / Kafedraniki / Mas'ul fanlarim / Faqat meniki) bilan.
            async function downloadWeeklyExcel() {
                const cellData = gridExportCells();
                if (!cellData) { alert('Yuklab olish uchun panjara yo\'q.'); return; }
                const layer = weeklyLayer === 'external' ? 'tashqi' : 'ichki';
                const wk = curWeek ? curWeek + '-hafta' : 'barcha haftalar (shablon)';
                const scope = scopeMode !== 'all' ? ' · ' + scopeModeLabel() : '';
                // Uzun doska nomida ham hafta, qatlam va ko'rinish sarlavhada saqlansin.
                const title = 'Haftalik jadval (' + layer + ') · ' + wk + scope + (curSpec ? ' · ' + scopeLabelText() : '') +
                    ' · ' + (board.institution_name ? board.institution_name + ' — ' : '') + (board.name || 'Dars jadvali');
                const base = ((board.name || 'dars-jadvali').slice(0, 80) + '_haftalik_' + layer + '_' + (curWeek ? curWeek + '-hafta' : 'shablon') +
                    (scopeMode !== 'all' ? '_' + scopeModeLabel() : '')).replace(/[^\w\-]+/g, '_');
                cellData.sheet_title = 'Haftalik ' + layer;
                cellData.landscape = 1;
                await sendExcelExport(cellData, Array.from(title).slice(0, 255).join(''), base.slice(0, 150), $('weeklyExcel'));
            }
            if ($('weeklyExcel')) $('weeklyExcel').onclick = () => downloadWeeklyExcel();
            document.querySelectorAll('.ex-mode').forEach(b => b.onclick = () => {
                excelMode = b.dataset.mode;
                document.querySelectorAll('.ex-mode').forEach(x => x.classList.toggle('active', x === b));
                buildExcelView();
            });

            // Doska sozlamalari yordamchilari (default fallback bilan)
            function boardSchedule() {
                if (board && board.bell_schedule && board.bell_schedule.length) return board.bell_schedule;
                return PAIR_TIMES.slice(0, board ? board.pairs_per_day : 6).map((t, i) => {
                    const [start, end] = t.split('-');
                    return { type: 'pair', no: i + 1, name: (ROMAN[i] || (i + 1)) + '-para', abbr: ROMAN[i] || String(i + 1), start, end, print: true };
                });
            }
            function boardDayNames() {
                return (board && board.day_names && board.day_names.length) ? board.day_names : DAY_NAMES;
            }

            function buildExcelView() {
                // Ekranда ko'rinaётган qamrov (tanlangan fakultet × yo'nalish × kurs)
                // o'zini yuklaymiz.
                const src = specCards();
                // Dars turi filtri + tanlangan hafta Excel ko'rinishga ham qo'llanadi
                const placed = src.filter(c => effPlace(c) && typeVisible(c)).map(effectiveCard);
                // Ustun tuzilishi rejimga qarab: guruh / o'qituvchi / auditoriya.
                // headGroups: [{title, span, cols:[{key,label}]}]; idx: "colKey|day|pair" → karta(lar)
                let headGroups = [], idx = {};
                const push = (key, d, p, c) => { const k = key + '|' + d + '|' + p; (idx[k] = idx[k] || []).push(c); };

                if (excelMode === 'group') {
                    const specMap = {};
                    src.forEach(c => {
                        // Fakultet ham kalitga kiradi — bir xil yo'nalish+kurs turli
                        // fakultetlarda bo'lsa, guruhlari aralashib ketmasin.
                        const sk = (c.faculty_name || '') + '|' + c.specialty_name + '|' + c.course;
                        (specMap[sk] = specMap[sk] || { name: c.specialty_name, course: c.course, faculty: c.faculty_name || '', groups: new Map() });
                        cardGroups(c).forEach(g => specMap[sk].groups.set(gkey(c, g), g));
                    });
                    // Ustunlar fakultet bo'yicha guruhlanadi — bir fakultet
                    // ustunlari ketma-ket (davomida) kelib, tepasida fakultet
                    // super-sarlavhasi ustma-ust turadi.
                    Object.values(specMap)
                        .map(s => ({ ...s, groups: [...s.groups.entries()].sort((a, b) => a[1].localeCompare(b[1], undefined, { numeric: true })) }))
                        .sort((a, b) => (a.faculty + '|' + a.name + a.course).localeCompare(b.faculty + '|' + b.name + b.course, 'uz'))
                        .forEach(s => headGroups.push({ title: s.name + ' · ' + s.course + '-kurs', cols: s.groups.map(([k, g]) => ({ key: k, label: g })) }));
                    placed.forEach(c => { const pl = effPlace(c); cardGroups(c).forEach(g => push(gkey(c, g), pl.day, pl.pair, c)); });
                } else if (excelMode === 'teacher') {
                    const names = [...new Set(placed.filter(c => c.teacher_name).map(c => c.teacher_name))]
                        .sort((a, b) => a.localeCompare(b));
                    headGroups.push({ title: "O'qituvchilar", cols: names.map(n => ({ key: n, label: n })) });
                    placed.forEach(c => { if (c.teacher_name) { const pl = effPlace(c); push(c.teacher_name, pl.day, pl.pair, c); } });
                } else { // room
                    const names = [...new Set(placed.filter(c => c.auditorium_name).map(c => c.auditorium_name))]
                        .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
                    headGroups.push({ title: 'Auditoriyalar', cols: names.map(n => ({ key: n, label: n })) });
                    placed.forEach(c => { if (c.auditorium_name) { const pl = effPlace(c); push(c.auditorium_name, pl.day, pl.pair, c); } });
                }

                const cols = headGroups.flatMap(hg => hg.cols);
                if (!cols.length) {
                    $('excelBody').innerHTML = '<div class="p-4 text-gray-500">' +
                        (excelMode === 'group' ? 'Joylashgan darslar yo\'q.' :
                         excelMode === 'teacher' ? 'Biriktirilgan va joylashgan darslar yo\'q.' :
                         'Auditoriya biriktirilgan darslar yo\'q.') + '</div>';
                    return;
                }

                // Fakultet super-sarlavhasi (faqat guruh rejimida): guruh → fakultet
                let facHead = null;
                if (excelMode === 'group') {
                    const gFac = {};
                    cards.forEach(c => cardGroups(c).forEach(g => { const k = gkey(c, g); if (!(k in gFac)) gFac[k] = c.faculty_name || ''; }));
                    if (cols.some(col => gFac[col.key])) {
                        facHead = [];
                        cols.forEach(col => {
                            const f = gFac[col.key] || '';
                            const last = facHead[facHead.length - 1];
                            if (last && last.faculty === f) last.span++; else facHead.push({ faculty: f, span: 1 });
                        });
                    }
                }

                // Kunlar soni — faqat ko'rsatilaётган yo'nalishlar grid'idan (eng kattasi)
                let D = board.days;
                [...new Set(src.map(c => c.specialty_name + '|' + c.course))].forEach(k => {
                    const g = grids[k]; if (g) D = Math.max(D, g.days);
                });
                const dayNames = boardDayNames();
                const sched = boardSchedule().filter(it => it.print !== false || it.type === 'pair');

                // Katak matni rejimga qarab. span — ma'ruzani oqim ustunlari
                // bo'ylab birlashtirish (colspan) uchun.
                const cellHtml = (c, span) => {
                    const isLec = c.training_type === 'lecture';
                    const cls = isLec ? 'ex-lec' : 'ex-prc';
                    let extra;
                    if (excelMode === 'group') extra = [c.teacher_name, c.auditorium_name];
                    else if (excelMode === 'teacher') extra = [c.group_name || (c.oqim_label ? c.oqim_label : ''), c.auditorium_name];
                    else extra = [c.group_name || c.oqim_label, c.teacher_name];
                    const sub = extra.filter(Boolean).join(' · ');
                    // Ma'ruza — bir xil sariq; amaliy — har fan o'z rangida (nuqtali chegara).
                    // Ranglar inline (hex) — Excelга eksport qilinganда ham saqlanadi.
                    const s = subjColor(c.subject_name);
                    const st = isLec ? 'background-color:#fde68a;'
                        : 'background-color:' + s.bg + ';border-left:3px dotted ' + s.border + ';';
                    const cs = (span && span > 1) ? ' colspan="' + span + '"' : '';
                    const tag = '[' + (isLec ? 'M' : 'A') + '] ';
                    return '<td class="ex-cell ' + cls + '"' + cs + ' style="' + st + '">' +
                        '<div><b>' + tag + '</b>' + esc(c.subject_name) + '</div>' +
                        (sub ? '<div style="color:#64748b;font-size:9px">' + esc(sub) + '</div>' : '') + '</td>';
                };

                const modeLabel = { group: 'guruh', teacher: "o'qituvchi", room: 'auditoriya' }[excelMode];
                const title = (board.institution_name ? board.institution_name + ' — ' : '') + (board.name || 'Dars jadvali') + ' (' + modeLabel + ' kesimida)';
                let h = '<table><thead>';
                h += '<tr><td class="ex-title" colspan="' + (cols.length + 3) + '">' + esc(title) + '</td></tr>';
                const kpSpan = facHead ? 3 : 2;
                h += '<tr><th rowspan="' + kpSpan + '" class="ex-para">Kun</th><th rowspan="' + kpSpan + '" class="ex-para">Para</th><th rowspan="' + kpSpan + '" class="ex-para">Soati</th>';
                if (facHead) {
                    facHead.forEach(r => h += '<th class="ex-fac" colspan="' + r.span + '">' + esc(r.faculty || '—') + '</th>');
                    h += '</tr><tr>';
                }
                headGroups.forEach(hg => h += '<th class="ex-spec" colspan="' + hg.cols.length + '">' + esc(hg.title) + '</th>');
                h += '</tr><tr>';
                cols.forEach(col => h += '<th class="ex-grp">' + esc(col.label) + '</th>');
                h += '</tr></thead><tbody>';

                for (let d = 1; d <= D; d++) {
                    sched.forEach((it, si) => {
                        h += '<tr>';
                        if (si === 0) h += '<td class="ex-day" rowspan="' + sched.length + '">' + esc(dayNames[d - 1] || ('Kun ' + d)) + '</td>';
                        const timeStr = (it.start || '') + (it.end ? '-' + it.end : '');
                        if (it.type === 'break') {
                            h += '<td class="ex-para" colspan="2">' + esc(it.name || 'Tanaffus') + '</td>';
                            h += '<td class="ex-time" colspan="' + cols.length + '" style="text-align:center;color:#15803d;background:#f0fdf4">' + esc(timeStr) + '</td></tr>';
                            return;
                        }
                        h += '<td class="ex-para">' + esc(it.abbr || it.no) + '</td><td class="ex-time">' + esc(timeStr) + '</td>';
                        const cellAt = ci => idx[cols[ci].key + '|' + d + '|' + it.no] || [];
                        let ci = 0;
                        while (ci < cols.length) {
                            const list = cellAt(ci);
                            if (!list.length) { h += '<td class="ex-cell"></td>'; ci++; continue; }
                            if (list.length === 1) {
                                const c = list[0];
                                // Ma'ruza — bir xil karta ketma-ket ustunlarda kelsa
                                // (oqim guruhlari) bitta birlashtirilgan katakka jamlanadi.
                                let span = 1;
                                if (c.training_type === 'lecture') {
                                    while (ci + span < cols.length) {
                                        const nx = cellAt(ci + span);
                                        if (nx.length === 1 && nx[0].id === c.id) span++; else break;
                                    }
                                }
                                h += cellHtml(c, span);
                                ci += span;
                                continue;
                            }
                            // Bir katakda bir nechta (konflikt) — qizil ramka bilan
                            h += '<td class="ex-cell" style="outline:2px solid #ef4444;outline-offset:-2px">' +
                                list.map(c => '<div><b>[' + (c.training_type === 'lecture' ? 'M' : 'A') + ']</b> ' +
                                    esc(c.subject_name) + '<span style="color:#64748b;font-size:9px"> · ' +
                                    esc(excelMode === 'teacher' ? (c.group_name || c.oqim_label || '') : (c.teacher_name || '')) + '</span></div>').join('') + '</td>';
                            ci++;
                        }
                        h += '</tr>';
                    });
                }
                h += '</tbody></table>';
                $('excelBody').innerHTML = h;
            }

            // ══════════════════════════════════════════════════════════════
            //  Umumiy sozlamalar dialogi (qo'ng'iroqlar / juftliklar vaqti)
            // ══════════════════════════════════════════════════════════════
            let bellDraft = [];       // tahrirlanayotgan qo'ng'iroq jadvali
            let dayDraft = [];        // tahrirlanayotgan kun nomlari
            let gridSettingRows = []; // modalda ko'rsatiladigan fakultet/yo'nalish/kurs qatorlari
            let bellEditIdx = null;
            let bellSel = null;       // belgilangan (highlight) qator indeksi — ▲/▼ bilan ko'chirish uchun

            const SETTINGS_URL = id => BASE + '/boards/' + id + '/settings';

            let infoSubjectDraft = [];
            function renderInfoSubjectTags() {
                $('stInfoSubjectTags').innerHTML = infoSubjectDraft.map((name, i) =>
                    '<span class="rounded bg-gray-100 px-2 py-1 text-sm">' + esc(name)
                    + ' <button type="button" data-info-subject-remove="' + i + '" aria-label="' + esc(name + 'ni olib tashlash') + '">×</button></span>').join('');
            }
            function addInfoSubjectTag() {
                const input = $('stInfoSubjectInput'), name = input.value.trim();
                if (!name) return;
                if (infoSubjectDraft.length >= 50) { $('setMsg').textContent = 'Ko‘pi bilan 50 ta nom kiritish mumkin.'; return; }
                if (!infoSubjectDraft.some(n => normalizeInfoSubject(n) === normalizeInfoSubject(name))) infoSubjectDraft.push(name);
                input.value = '';
                renderInfoSubjectTags();
            }
            function appendInfoSubjectSettings(fd) {
                // Include the last typed tag even when the user clicks Save directly.
                addInfoSubjectTag();
                fd.append('info_only_subjects_present', 1);
                infoSubjectDraft.forEach((name, i) => fd.append('settings[info_only_subjects][' + i + ']', name));
            }
            $('stInfoSubjectAdd').onclick = addInfoSubjectTag;
            $('stInfoSubjectInput').onkeydown = e => { if (e.key === 'Enter') { e.preventDefault(); addInfoSubjectTag(); } };
            $('stInfoSubjectTags').onclick = e => {
                const button = e.target.closest('[data-info-subject-remove]');
                if (!button) return;
                infoSubjectDraft.splice(+button.dataset.infoSubjectRemove, 1);
                renderInfoSubjectTags();
            };

            $('settingsBtn').onclick = async () => {
                if (!board) return;
                $('setMsg').textContent = '';
                setTab('basic');
                $('setModal').classList.remove('hidden');
                try {
                    const s = await api(SETTINGS_URL(board.id));
                    $('stInst').value = s.institution_name || '';
                    $('stYear').value = s.academic_year || '';
                    $('stDays').value = s.days;
                    $('stPairs').value = s.pairs_per_day;
                    renderGridSettings();
                    const set = s.settings || {};
                    $('stDayOff').value = (set.days_off || []).join(', ');
                    $('stAllowZero').checked = !!set.allow_zero;
                    $('stShowNum').checked = !!set.show_day_number;
                    document.querySelectorAll('[data-info-only-course]').forEach(el => {
                        el.checked = (Array.isArray(set.info_only_courses) ? set.info_only_courses : [6]).map(Number).includes(+el.dataset.infoOnlyCourse);
                    });
                    infoSubjectDraft = (Array.isArray(set.info_only_subjects) ? set.info_only_subjects : ["O'quv amaliyoti"]).slice();
                    $('stInfoSubjectInput').value = '';
                    renderInfoSubjectTags();
                    $('stHemisMudir').checked = !!+(set.hemis_mudir_fallback || 0);
                    // Shaxsiy (brauzerda): sikl katagini sudrashda "hammasi birga" tugmasi — doska sozlamasi emas, darhol saqlanadi.
                    if ($('stCycBothKey')) { $('stCycBothKey').value = cycBothKey(); $('stCycBothKey').onchange = ev => setCycBothKey(ev.target.value); }
                    const br = (set.weekly_breaks || [])[0] || {};
                    $('stBreakFrom').value = br.from || '';
                    $('stBreakTo').value = br.to || '';
                    bellDraft = (s.bell_schedule || []).map(x => ({ ...x }));
                    dayDraft = (s.day_names || []).slice();
                    renderBellTable(); renderDayNames();
                } catch (e) { $('setMsg').textContent = 'Xatolik: ' + e.message; }
            };

            document.querySelectorAll('.set-tab').forEach(t => t.onclick = () => setTab(t.dataset.tab));
            function setTab(name) {
                document.querySelectorAll('.set-tab').forEach(t => t.classList.toggle('active', t.dataset.tab === name));
                $('setBasic').classList.toggle('hidden', name !== 'basic');
                $('setBells').classList.toggle('hidden', name !== 'bells');
                $('setDays').classList.toggle('hidden', name !== 'days');
                $('setGrid').classList.toggle('hidden', name !== 'grid');
                $('setSave').classList.toggle('hidden', name === 'grid');
            }
            let gridFacultyFilter = '';
            let gridSpecialtyFilter = '';

            function renderGridSettings() {
                const seen = new Map();
                (cards || []).forEach(card => {
                    const row = {
                        faculty: card.faculty_name || '',
                        specialty: card.specialty_name || '',
                        course: +card.course || 0,
                        curriculum_hemis_id: +card.curriculum_hemis_id || 0,
                        program_name: card.program_name || 'Umumiy sozlama',
                        education_form_name: card.education_form_name || '',
                    };
                    const key = gridKey(row.faculty, row.specialty, row.course, row.curriculum_hemis_id);
                    if (!seen.has(key)) seen.set(key, row);
                });
                gridSettingRows = [...seen.values()].sort((a, b) =>
                    (a.faculty + '|' + a.specialty + '|' + a.course)
                        .localeCompare(b.faculty + '|' + b.specialty + '|' + b.course, 'uz')
                );

                const facultyValues = [...new Set(gridSettingRows.map(row => row.faculty))].sort((a, b) => a.localeCompare(b, 'uz'));
                const specialtyValues = [...new Set(gridSettingRows
                    .filter(row => !gridFacultyFilter || row.faculty === gridFacultyFilter)
                    .map(row => row.specialty))].sort((a, b) => a.localeCompare(b, 'uz'));

                $('stGridFacultyFilter').innerHTML =
                    '<option value="">Barcha fakultetlar</option>' +
                    facultyValues.map(value => '<option value="' + esc(value) + '">' + esc(value || 'Fakultet ko\'rsatilmagan') + '</option>').join('');
                $('stGridSpecialtyFilter').innerHTML =
                    '<option value="">Barcha yo\'nalishlar</option>' +
                    specialtyValues.map(value => '<option value="' + esc(value) + '">' + esc(value) + '</option>').join('');
                if (facultyValues.includes(gridFacultyFilter)) $('stGridFacultyFilter').value = gridFacultyFilter;
                else gridFacultyFilter = '', $('stGridFacultyFilter').value = '';
                if (specialtyValues.includes(gridSpecialtyFilter)) $('stGridSpecialtyFilter').value = gridSpecialtyFilter;
                else gridSpecialtyFilter = '', $('stGridSpecialtyFilter').value = '';

                const filtered = gridSettingRows.filter(row =>
                    (!gridFacultyFilter || row.faculty === gridFacultyFilter) &&
                    (!gridSpecialtyFilter || row.specialty === gridSpecialtyFilter)
                );
                const groups = new Map();
                filtered.forEach((row, index) => {
                    const key = row.faculty + '|' + row.specialty + '|' + row.curriculum_hemis_id;
                    if (!groups.has(key)) groups.set(key, { faculty: row.faculty, specialty: row.specialty, program: row.program_name, form: row.education_form_name, curriculum: row.curriculum_hemis_id, courses: new Map() });
                    const originalIndex = gridSettingRows.findIndex(item =>
                        gridKey(item.faculty, item.specialty, item.course, item.curriculum_hemis_id) === gridKey(row.faculty, row.specialty, row.course, row.curriculum_hemis_id)
                    );
                    groups.get(key).courses.set(row.course, { row, index: originalIndex });
                });

                if (!groups.size) {
                    $('stGridRows').innerHTML = '<div class="rounded-lg border border-dashed border-slate-300 p-6 text-center text-sm text-slate-400">Mos keladigan yo\'nalish topilmadi.</div>';
                    return;
                }

                let html = '<div class="grid-setting-table-wrap"><table class="grid-setting-table"><thead><tr>' +
                    '<th>Fakultet</th><th>Ta’lim dasturi / o‘quv reja</th><th>Yo\'nalish</th>';
                for (let course = 1; course <= 6; course++) html += '<th>' + course + '-kurs</th>';
                html += '</tr></thead><tbody>';

                groups.forEach(group => {
                    html += '<tr><td class="grid-setting-name"><b>' + esc(group.faculty || 'Fakultet ko\'rsatilmagan') + '</b></td>' +
                        '<td class="grid-setting-name"><b>' + esc(group.program) + '</b><div>' + esc(group.form) + '</div></td>' +
                        '<td class="grid-setting-name"><span>' + esc(group.specialty) + '</span></td>';
                    for (let course = 1; course <= 6; course++) {
                        const item = group.courses.get(course);
                        if (!item) {
                            html += '<td class="grid-setting-empty">—</td>';
                            continue;
                        }
                        const row = item.row;
                        const g = gridForCard(row);
                        html += '<td><div class="grid-setting-cell" data-grid-row="' + item.index + '">' +
                            '<div class="grid-setting-values">' +
                                '<label title="Kunlar soni">K<input data-grid-field="days" type="number" min="1" max="7" value="' + (+g.days || board.days) + '"></label>' +
                                '<label title="Kuniga paralar soni">P<input data-grid-field="pairs_per_day" type="number" min="1" max="24" value="' + (+g.pairs_per_day || board.pairs_per_day) + '"></label>' +
                                '<label title="Hafta soni">H<input data-grid-field="weeks" type="number" min="1" max="30" value="' + (+g.weeks || board.weeks) + '"></label>' +
                                '<label title="Semestr boshlanishi (bo\'sh — doska semestr boshi)">B<input data-grid-field="start_date" type="date" value="' + esc(String(g.start_date || '').slice(0, 10)) + '" style="width:118px"></label>' +
                            '</div>' +
                            '<label title="Bo‘sh qoldirilsa doska ta’tili ishlaydi"><input data-grid-field="inherit_breaks" type="checkbox"' + (g.weekly_breaks == null ? ' checked' : '') + '> Umumiy ta’til</label>' +
                            '<label>Ta’til boshi<input data-grid-field="break_from" type="date" value="' + esc(g.weekly_breaks?.[0]?.from || '') + '"></label>' +
                            '<label>Ta’til oxiri<input data-grid-field="break_to" type="date" value="' + esc(g.weekly_breaks?.[0]?.to || '') + '"></label>' +
                            '<button type="button" class="grid-setting-save" data-grid-save="' + item.index + '" title="Saqlash"><img src="' + ICON_BASE + '/saqlash.png" alt="" aria-hidden="true"></button>' +
                            '<span class="grid-setting-status"></span>' +
                        '</div></td>';
                    }
                    html += '</tr>';
                });
                html += '</tbody></table></div>';
                $('stGridRows').innerHTML = html;
                $('stGridRows').querySelectorAll('[data-grid-save]').forEach(btn => {
                    btn.onclick = () => saveGridSettingRow(+btn.dataset.gridSave, btn);
                });
            }

            $('stGridFacultyFilter').onchange = function () {
                gridFacultyFilter = this.value;
                gridSpecialtyFilter = '';
                renderGridSettings();
            };
            $('stGridSpecialtyFilter').onchange = function () {
                gridSpecialtyFilter = this.value;
                renderGridSettings();
            };

            async function saveGridSettingRow(index, btn) {
                const row = gridSettingRows[index];
                const wrap = btn.closest('[data-grid-row]');
                if (!row || !wrap || !board) return;
                const value = name => wrap.querySelector('[data-grid-field="' + name + '"]').value;
                const status = wrap.querySelector('.grid-setting-status');
                const inheritBreaks = wrap.querySelector('[data-grid-field="inherit_breaks"]').checked;
                const from = value('break_from'), to = value('break_to');
                if (!inheritBreaks && ((from && !to) || (!from && to) || (from && to < from))) {
                    status.textContent = 'Ta’til sanalarini to‘liq va to‘g‘ri kiriting.';
                    return;
                }
                btn.disabled = true;
                status.textContent = 'Saqlanmoqda...';
                try {
                    await api(BASE + '/boards/' + board.id + '/grid', 'POST', {
                        faculty_name: row.faculty,
                        curriculum_hemis_id: row.curriculum_hemis_id,
                        weekly_breaks: inheritBreaks ? null : (from ? [{ from, to }] : []),
                        specialty_name: row.specialty,
                        course: row.course,
                        days: value('days'),
                        pairs_per_day: value('pairs_per_day'),
                        weeks: value('weeks'),
                        start_date: value('start_date') || '',
                        regenerate: 0,
                    });
                    await loadBoard(board.id);
                    renderGridSettings();
                    $('setMsg').textContent = 'Panjara sozlamasi saqlandi.';
                } catch (e) {
                    status.textContent = 'Xatolik: ' + e.message;
                    btn.disabled = false;
                }
            }

            $('setClose').onclick = $('setCancel').onclick = () => $('setModal').classList.add('hidden');

            // Kun soni o'zgarsa — kun nomlari maydonini moslash
            $('stDays').onchange = function () {
                const n = +this.value;
                while (dayDraft.length < n) dayDraft.push(DAY_NAMES[dayDraft.length] || ('Kun ' + (dayDraft.length + 1)));
                dayDraft = dayDraft.slice(0, n);
                renderDayNames();
            };

            function renderBellTable() {
                let pn = 0;
                let h = '<thead><tr><th>#</th><th>Nomi</th><th>Qisqartma</th><th>Boshi</th><th>Oxiri</th><th>Chop</th><th></th></tr></thead><tbody>';
                bellDraft.forEach((it, i) => {
                    const isBreak = it.type === 'break';
                    const label = isBreak ? '<span class="text-green-600">tanaffus</span>' : (++pn);
                    const selCls = (i === bellSel) ? ' bell-sel' : '';
                    h += '<tr class="' + (isBreak ? 'is-break' : '') + selCls + '" data-row="' + i + '">' +
                        '<td class="text-center">' + label + '</td>' +
                        '<td>' + esc(it.name || '') + '</td><td>' + esc(it.abbr || '') + '</td>' +
                        '<td>' + esc(it.start || '') + '</td><td>' + esc(it.end || '') + '</td>' +
                        '<td class="text-center">' + (it.print === false ? '—' : 'Ha') + '</td>' +
                        '<td class="whitespace-nowrap text-right">' +
                            '<button class="asc-mini" data-edit="' + i + '" title="Tahrirlash"><img src="{{ asset('image/tahrirlash.png') }}" alt="" aria-hidden="true"></button>' +
                            '<button class="asc-mini" data-del="' + i + '" title="O\'chirish"><img src="{{ asset('image/11_delete.png') }}" alt="" aria-hidden="true"></button>' +
                        '</td></tr>';
                });
                h += '</tbody>';
                $('stBellTable').innerHTML = h;
                const T = $('stBellTable');
                // Qatorni bosib belgilash — umumiy ▲/▼ tugmalari shu belgilangan qatorni ko'chiradi
                T.querySelectorAll('tr[data-row]').forEach(tr => tr.onclick = ev => {
                    if (ev.target.closest('button')) return;   // tugma bosilsa — belgilamaymiz
                    bellSel = (bellSel === +tr.dataset.row) ? null : +tr.dataset.row;
                    renderBellTable();
                });
                T.querySelectorAll('[data-edit]').forEach(b => b.onclick = () => openBellEdit(+b.dataset.edit));
                T.querySelectorAll('[data-del]').forEach(b => b.onclick = () => {
                    const d = +b.dataset.del;
                    bellDraft.splice(d, 1);
                    if (bellSel === d) bellSel = null; else if (bellSel > d) bellSel--;
                    renderBellTable();
                });
                // Belgilangan qatorni ko'rinishga suramiz
                const selTr = T.querySelector('tr.bell-sel');
                if (selTr) selTr.scrollIntoView({ block: 'nearest' });
                $('stMoveUp').disabled = !(bellSel !== null && bellSel > 0);
                $('stMoveDown').disabled = !(bellSel !== null && bellSel < bellDraft.length - 1);
            }
            // Umumiy ▲/▼ tugmalari — belgilangan qatorni ko'chiradi va belgini
            // shu qatorda saqlab qoladi, shunda qayta-qayta bosib yuqoriga/pastga
            // chiqarib borish mumkin.
            function moveBell(dir) {
                if (bellSel === null) return;
                const i = bellSel, j = i + dir;
                if (j < 0 || j >= bellDraft.length) return;
                [bellDraft[i], bellDraft[j]] = [bellDraft[j], bellDraft[i]];
                bellSel = j;
                renderBellTable();
            }
            $('stMoveUp').onclick = () => moveBell(-1);
            $('stMoveDown').onclick = () => moveBell(1);
            $('stAddPair').onclick = () => {
                const pairs = bellDraft.filter(x => x.type === 'pair').length;
                bellDraft.push({ type: 'pair', name: (pairs + 1) + '-para', abbr: ROMAN[pairs] || String(pairs + 1),
                    start: '', end: '', print: true });
                renderBellTable();
            };
            $('stAddBreak').onclick = () => {
                bellDraft.push({ type: 'break', name: 'Tanaffus', abbr: '—', start: '', end: '', print: false });
                renderBellTable();
            };
            $('stResetBells').onclick = () => {
                if (!confirm('Qo\'ng\'iroqlar jadvali standart holatga qaytarilsinmi?')) return;
                const n = +$('stPairs').value || 6;
                bellDraft = [];
                for (let i = 0; i < n; i++) {
                    const [s, e] = (PAIR_TIMES[i] || '-').split('-');
                    bellDraft.push({ type: 'pair', name: (ROMAN[i] || (i + 1)) + '-para', abbr: ROMAN[i] || String(i + 1), start: s, end: e, print: true });
                    if (i < n - 1) bellDraft.push({ type: 'break', name: 'Tanaffus', abbr: '—', start: e, end: (PAIR_TIMES[i + 1] || '').split('-')[0] || '', print: false });
                }
                renderBellTable();
            };

            // Qo'ng'iroq qatorini tahrirlash
            function openBellEdit(i) {
                bellEditIdx = i; const it = bellDraft[i];
                $('beTitle').textContent = it.type === 'break' ? 'Tanaffus' : 'Para (juftlik)';
                $('beName').value = it.name || ''; $('beAbbr').value = it.abbr || '';
                $('beStart').value = it.start || ''; $('beEnd').value = it.end || '';
                $('bePrint').value = it.print === false ? '0' : '1';
                $('bellEditModal').classList.remove('hidden');
            }
            $('beClose').onclick = $('beCancel').onclick = () => $('bellEditModal').classList.add('hidden');
            $('beSave').onclick = () => {
                const it = bellDraft[bellEditIdx]; if (!it) return;
                it.name = $('beName').value.trim(); it.abbr = $('beAbbr').value.trim();
                it.start = $('beStart').value.trim(); it.end = $('beEnd').value.trim();
                it.print = $('bePrint').value === '1';
                $('bellEditModal').classList.add('hidden');
                renderBellTable();
            };

            function renderDayNames() {
                $('stDayNames').innerHTML = dayDraft.map((d, i) =>
                    '<div class="flex items-center gap-2"><span class="text-xs text-gray-400 w-4">' + (i + 1) + '</span>' +
                    '<input class="flex-1 rounded-md border-gray-300 text-sm dn-inp" data-i="' + i + '" value="' + esc(d) + '"></div>').join('');
                $('stDayNames').querySelectorAll('.dn-inp').forEach(inp =>
                    inp.oninput = () => { dayDraft[+inp.dataset.i] = inp.value; });
            }

            $('setSave').onclick = async function () {
                if (!board) return;
                const pairs = bellDraft.filter(x => x.type === 'pair').length;
                if (!pairs) { $('setMsg').textContent = 'Kamida bitta para bo\'lishi kerak.'; return; }
                this.disabled = true; $('setMsg').textContent = 'Saqlanmoqda...';
                const dayOff = $('stDayOff').value.split(',').map(s => s.trim()).filter(Boolean);
                const body = {
                    institution_name: $('stInst').value.trim(),
                    days: $('stDays').value,
                };
                // Massivlarni FormData ga qo'lda joylash uchun maxsus yuborish
                const fd = new FormData();
                fd.append('_token', CSRF);
                fd.append('institution_name', body.institution_name);
                fd.append('days', body.days);
                dayDraft.slice(0, +body.days).forEach((d, i) => fd.append('day_names[' + i + ']', d || ''));
                bellDraft.forEach((it, i) => {
                    fd.append('bell_schedule[' + i + '][type]', it.type);
                    fd.append('bell_schedule[' + i + '][name]', it.name || '');
                    fd.append('bell_schedule[' + i + '][abbr]', it.abbr || '');
                    fd.append('bell_schedule[' + i + '][start]', it.start || '');
                    fd.append('bell_schedule[' + i + '][end]', it.end || '');
                    fd.append('bell_schedule[' + i + '][print]', it.print === false ? 0 : 1);
                });
                dayOff.forEach((d, i) => fd.append('settings[days_off][' + i + ']', d));
                fd.append('settings[allow_zero]', $('stAllowZero').checked ? 1 : 0);
                fd.append('settings[show_day_number]', $('stShowNum').checked ? 1 : 0);
                appendInfoSubjectSettings(fd);
                fd.append('info_only_courses_present', 1);
                document.querySelectorAll('[data-info-only-course]:checked').forEach((el, i) =>
                    fd.append('settings[info_only_courses][' + i + ']', el.dataset.infoOnlyCourse));
                fd.append('settings[hemis_mudir_fallback]', $('stHemisMudir').checked ? 1 : 0);
                if ($('stBreakFrom').value && $('stBreakTo').value) {
                    fd.append('settings[weekly_breaks][0][from]', $('stBreakFrom').value);
                    fd.append('settings[weekly_breaks][0][to]', $('stBreakTo').value);
                } else {
                    fd.append('settings[weekly_breaks]', '');
                }
                try {
                    const r = await fetch(SETTINGS_URL(board.id), { method: 'POST', headers: { 'Accept': 'application/json' }, body: fd });
                    const j = await r.json();
                    if (!r.ok) throw new Error(j.error || j.message || 'Xatolik');
                    $('setModal').classList.add('hidden');
                    await loadBoard(board.id);   // yangi o'lcham/vaqtlar bilan qayta yuklash
                } catch (e) { $('setMsg').textContent = 'Xatolik: ' + e.message; }
                this.disabled = false;
            };

            // ══════════════════════════════════════════════════════════════
            //  O'qituvchi biriktirish matritsasi
            // ══════════════════════════════════════════════════════════════
            let asgUnits = [];        // dars birliklari
            let asgSel = null;        // tanlangan birlik
            let asgTeacherTimer = null;
            // Tanlangan birlik darslari vaqtida boshqa guruhcha bilan band o'qituvchilar/xonalar — ro'yxatda kulrang; rank — xonalar
            // reytingi (server: odat, o'qituvchi, kafedra, shu bino, sig'im) — { order: [kod, ...], why: { kod: sabab } }.
            let asgBusy = { teachers: {}, rooms: {}, rank: null };
            const asgUnitParams = u => ({ faculty_name: u.faculty_name || '', specialty_name: u.specialty_name, course: u.course,
                subject_name: u.subject_name, training_type: u.training_type, oqim_label: u.oqim_label || '', group_name: u.group_name || '' });
            // Bandlik va xonalar reytingi: birlik tanlanganda va shu birlikka o'qituvchi/xona biriktirilgach (reyting o'qituvchi va hozirgi
            // xonaga bog'liq) qayta yuklanadi. Boshqa birlikka o'tilsa — darhol tozalanadi; o'sha birlik qayta yuklanayotganda eski ma'lumot
            // javob kelguncha qoladi. Faqat eng oxirgi so'rov javobi olinadi (kech kelgan eskisi yangisini bosmaydi). Xona oynasi ochiq
            // bo'lsa — yangi reyting/bandlik bilan qayta chiziladi.
            let asgBusyFor = null, asgBusySeq = 0;
            async function loadAsgBusy(u) {
                if (asgBusyFor !== u) { asgBusy = { teachers: {}, rooms: {}, rank: null, caps: {} }; asgBusyFor = u; }
                const seq = ++asgBusySeq;
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/unit-busy?' + new URLSearchParams(asgUnitParams(u)));
                    if (asgSel === u && seq === asgBusySeq) {
                        asgBusy = { teachers: j.teachers || {}, rooms: j.rooms || {}, rank: j.room_rank || null, items: j.busy_items || null,
                            caps: j.room_caps || {} };
                        if (!$('asgRoomModal').classList.contains('hidden')) renderAsgRooms();
                    }
                } catch (e) { console.warn('Bandlik olinmadi:', e); }
            }
            function markAsgBusy() {
                [...$('asgTeacher').options].forEach(o => {
                    const busy = asgBusy.teachers[o.value];
                    o.style.color = busy ? '#9ca3af' : '';
                    o.title = busy ? 'Band: ' + busy : '';
                    o.dataset.busy = busy ? '1' : '';
                });
            }
            // Band o'qituvchi/xona ogohlantirishi (kim bilan, qachon) — "Baribir biriktirish" bosilsa force bilan qayta yuboriladi.
            function showBusyConfirm(el, message, onForce, items) {
                el.innerHTML = '<div style="color:#b45309">⚠ ' + esc(message) + focusLinksHtml(items) + agendaLinksHtml(items, null) + '</div>' +
                    '<button type="button" class="busy-force" style="margin-top:4px;padding:2px 8px;border:1px solid #b45309;border-radius:6px;color:#b45309;background:#fff">Baribir biriktirish</button>';
                el.classList.remove('hidden');
                el.querySelector('.busy-force').onclick = onForce;
            }
            const ASG_HEADER_KEYS = ['subject', 'type', 'scope', 'department', 'cards', 'teacher'];
            let asgAudRooms = [];
            let asgAudSel = null;
            let asgAudTeacherTimer = null;
            let asgAudDepartmentsLoaded = false;
            // Band o'qituvchi tanlansa — kim bilan, qachon va "Ko'rsatish" (tuzilgan ro'yxat: unit-busy busy_items).
            $('asgTeacher').addEventListener('change', () => {
                const id = $('asgTeacher').value, busy = id ? asgBusy.teachers[id] : null, el = $('asgMsg');
                if (busy) {
                    el.innerHTML = '<span class="asg-busy-note" style="color:#b45309">⚠ Band: ' + esc(busy) +
                        focusLinksHtml(((asgBusy.items || {}).teachers || {})[id]) + agendaLinksHtml(((asgBusy.items || {}).teachers || {})[id], null) + '</span>';
                } else if (el.querySelector('.asg-busy-note')) {
                    el.innerHTML = '';
                }
            });

            function newAsgHeaderFilters() {
                return { subject: '', type: '', scope: '', department: '', cards: '', teacher: '' };
            }

            let asgHeaderFilters = newAsgHeaderFilters();

            // Ustun filtrlari (jadval sarlavhasi ostidagi qator): matn bo'yicha qidiruv, tur — tanlov
            const asgColFilters = { subject: '', spec: '', type: '', scope: '', kaf: '', teacher: '', room: '' };
            const asgNormText = v => String(v || '').toLowerCase().replace(/[‘’ʻʼ`´]/g, "'");
            function asgColMatch(u) {
                const has = (val, q) => !q || asgNormText(val).includes(asgNormText(q));
                return has(u.subject_name, asgColFilters.subject)
                    && has(asgSpecLabel(u), asgColFilters.spec)
                    && (!asgColFilters.type || u.training_type === asgColFilters.type)
                    && has(asgScopeLabel(u) + ' ' + (u.group_names || []).join(' '), asgColFilters.scope)
                    && has(u.kafedra_name, asgColFilters.kaf)
                    && has(asgTeacherText(u), asgColFilters.teacher)
                    && has(u.room_mixed ? 'turlicha' : (u.auditorium_name || ''), asgColFilters.room);
            }
            let asgColTimer = null;
            function ensureAsgHead() {
                const table = $('asgTable');
                if (table.tHead && table.tHead.dataset.f) return;
                const inp = (key, ph) => '<th><input type="search" data-asg-col="' + key + '" placeholder="' + ph + '" aria-label="' + ph + '"></th>';
                table.innerHTML = '<thead data-f="1"><tr><th>Fan</th><th>Fakultet / yo\'nalish</th><th>Tur</th><th>Oqim/Guruh</th><th>Kafedra</th><th>Karta</th><th>O\'qituvchi</th><th>Xona</th></tr>' +
                    '<tr class="asg-frow">' + inp('subject', 'Fan...') + inp('spec', 'Fakultet / yo\'nalish...') +
                    '<th><select data-asg-col="type" aria-label="Tur"><option value="">Hammasi</option><option value="lecture">Ma\'ruza</option><option value="practice">Amaliy</option></select></th>' +
                    inp('scope', 'Oqim / guruh...') + inp('kaf', 'Kafedra...') + '<th></th>' +
                    inp('teacher', "O'qituvchi...") + inp('room', 'Xona...') + '</tr></thead><tbody></tbody>';
                table.tHead.querySelectorAll('[data-asg-col]').forEach(el => {
                    el.value = asgColFilters[el.dataset.asgCol] || '';
                    const apply = () => {
                        asgColFilters[el.dataset.asgCol] = el.value.trim();
                        el.classList.toggle('is-active', !!el.value.trim());
                        clearTimeout(asgColTimer);
                        asgColTimer = setTimeout(renderAsgTable, el.tagName === 'SELECT' ? 0 : 200);
                    };
                    el.addEventListener(el.tagName === 'SELECT' ? 'change' : 'input', apply);
                });
            }

            function resetAsgHeaderFilters() {
                asgHeaderFilters = newAsgHeaderFilters();
            }

            function asgTypeLabel(unit) {
                return unit.training_type === 'lecture' ? "Ma'ruza" : 'Amaliy';
            }

            function asgScopeLabel(unit) {
                return unit.training_type === 'lecture' ? (unit.oqim_label || 'oqim') : (unit.group_name || '');
            }

            function asgSpecLabel(unit) {
                return (unit.faculty_name ? unit.faculty_name + ' / ' : '') + unit.specialty_name + ' · ' + unit.course + '-kurs';
            }

            function asgSpecHtml(unit) {
                const faculty = unit.faculty_name ? '<b>' + esc(unit.faculty_name) + '</b><br>' : '';
                return faculty + '<span class="text-slate-500">' + esc(unit.specialty_name + ' · ' + unit.course + '-kurs') + '</span>';
            }

            function asgTeacherText(unit) {
                if (unit.teacher_mixed) return 'turlicha';
                return unit.teacher_name || 'biriktirilmagan';
            }

            function asgHeaderValue(unit, key) {
                switch (key) {
                    case 'type': return asgTypeLabel(unit);
                    case 'scope': return asgScopeLabel(unit) || '-';
                    case 'department': return unit.kafedra_name || '-';
                    case 'cards': return String(unit.cards || 0);
                    case 'teacher': return asgTeacherText(unit);
                    case 'subject':
                    default: return unit.subject_name || '-';
                }
            }

            function asgCompareText(a, b) {
                return String(a || '').localeCompare(String(b || ''), 'uz', {
                    numeric: true,
                    sensitivity: 'base'
                });
            }

            function asgMatchesHeaderFilters(unit, exceptKey = null) {
                for (const key of ASG_HEADER_KEYS) {
                    if (key === exceptKey) continue;
                    const active = asgHeaderFilters[key];
                    if (active && asgHeaderValue(unit, key) !== active) return false;
                }
                return true;
            }

            function asgHeaderOptions(key, baseRows) {
                const values = [...new Set((baseRows || [])
                    .filter(unit => asgMatchesHeaderFilters(unit, key))
                    .map(unit => asgHeaderValue(unit, key))
                    .filter(Boolean))];

                if (key === 'cards') {
                    values.sort((a, b) => (+a || 0) - (+b || 0));
                } else {
                    values.sort(asgCompareText);
                }

                return values;
            }

            function asgNormalizeHeaderFilters(baseRows) {
                ASG_HEADER_KEYS.forEach(key => {
                    const active = asgHeaderFilters[key];
                    if (!active) return;
                    if (!asgHeaderOptions(key, baseRows).includes(active)) {
                        asgHeaderFilters[key] = '';
                    }
                });
            }

            function asgHeaderIndicator(key) {
                const active = asgHeaderFilters[key];
                return active ? '<span class="asg-sort-indicator">' + esc(active) + '</span>' : '';
            }

            function asgHeaderCell(label, key, center = false) {
                return '<th>' +
                    '<button type="button" class="asg-sort-btn' + (center ? ' asg-sort-btn-center' : '') + (asgHeaderFilters[key] ? ' is-active' : '') + '" data-asg-filter="' + key + '" title="Bosib filtrni almashtiring">' +
                    '<span>' + label + '</span>' +
                    asgHeaderIndicator(key) +
                    '</button>' +
                    '</th>';
            }

            function asgToggleHeaderFilter(key) {
                const baseRows = asgFiltered();
                const options = asgHeaderOptions(key, baseRows);

                if (!options.length) {
                    asgHeaderFilters[key] = '';
                    renderAsgTable();
                    return;
                }

                const current = asgHeaderFilters[key] || '';
                const currentIndex = options.indexOf(current);
                asgHeaderFilters[key] = currentIndex === -1
                    ? options[0]
                    : (currentIndex === options.length - 1 ? '' : options[currentIndex + 1]);

                renderAsgTable();
            }

             function setAsgTab(tab) {
                 document.querySelectorAll('[data-asg-tab]').forEach(btn => {
                     btn.classList.toggle('active', btn.dataset.asgTab === tab);
                 });
                 document.querySelectorAll('[data-asg-panel]').forEach(panel => {
                     const active = panel.dataset.asgPanel === tab;
                     panel.classList.toggle('hidden', !active);
                     if (panel.dataset.asgPanel === 'auditoriums') panel.classList.toggle('flex', active);
                 });
             }
             document.querySelectorAll('[data-asg-tab]').forEach(btn => {
                 btn.onclick = () => {
                     const tab = btn.dataset.asgTab;
                     setAsgTab(tab);
                     if (tab === 'auditoriums') loadAsgAuditoriums();
                 };
             });

            $('assignBtn').onclick = async () => {
                if (!board) return;
                asgSel = null; setAsgTeacherPanel(null); resetAsgHeaderFilters(); $('asgTypeFilter').value = '';
                setAsgTab(TIMETABLE_AUDITORIUM_ASSIGNMENT_ONLY ? 'auditoriums' : 'teachers');
                $('assignModal').classList.remove('hidden');
                $('asgMsg').textContent = '';

                if (TIMETABLE_AUDITORIUM_ASSIGNMENT_ONLY) {
                    await loadAsgAuditoriums();
                    return;
                }

                $('asgTable').innerHTML = '<tbody><tr><td class="p-3 text-gray-400">Yuklanmoqda...</td></tr></tbody>';
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/teacher-units');
                    asgUnits = j.units || [];
                } catch (e) { asgUnits = []; $('asgMsg').textContent = 'Xatolik: ' + e.message; }
                const specs = [...new Set(asgUnits.map(u => u.specialty_name + ' · ' + u.course + '-kurs'))].sort();
                $('asgFilter').innerHTML = '<option value="">— barcha yo\'nalishlar —</option>' +
                    specs.map(s => '<option value="' + esc(s) + '">' + esc(s) + '</option>').join('');
                const scopedSpecs = [...new Set(asgUnits.map(u => asgSpecLabel(u)))].sort();
                $('asgFilter').innerHTML = '<option value="">-- barcha yo\'nalishlar --</option>' +
                    scopedSpecs.map(s => '<option value="' + esc(s) + '">' + esc(s) + '</option>').join('');
                renderAsgTable();
            };
            // Excel hisobot: kafedralar kesimida biriktirish holati (faqat admin)
            if ($('asgReportBtn')) {
                $('asgReportBtn').onclick = () => {
                    if (board) window.location.href = BASE + '/boards/' + board.id + '/assignment-report';
                };
            }
            $('asgClose').onclick = $('asgCloseBtn').onclick = () => {
                $('assignModal').classList.add('hidden');
                renderAll();   // grid/panel o'qituvchi o'zgarishlarini aks ettirsin
            };
            $('asgFilter').onchange = $('asgSearch').oninput = $('asgOnlyEmpty').onchange = $('asgTypeFilter').onchange = () => renderAsgTable();

            // Qidiruv: fan nomi, kafedra yoki guruh/guruhcha nomi ("02b" — shu guruhchani qamragan ma'ruzalar ham chiqadi).
            function asgUnitSearchMatch(u, q) {
                return String(u.subject_name || '').toLowerCase().includes(q) || (u.kafedra_name || '').toLowerCase().includes(q)
                    || (u.group_name || '').toLowerCase().includes(q) || (u.group_names || []).some(g => String(g).toLowerCase().includes(q));
            }

            function asgFiltered() {
                const q = ($('asgSearch').value || '').toLowerCase().trim();
                const fv = $('asgFilter').value;
                const tv = $('asgTypeFilter').value;
                const onlyEmpty = $('asgOnlyEmpty').checked;
                return asgUnits.filter(u => {
                    if (fv && (u.specialty_name + ' · ' + u.course + '-kurs') !== fv) return false;
                    if (tv && asgTypeLabel(u) !== tv) return false;
                    if (onlyEmpty && u.teacher_id) return false;
                    if (q && !asgUnitSearchMatch(u, q)) return false;
                    return true;
                });
            }

            function asgFilteredScoped() {
                const q = ($('asgSearch').value || '').toLowerCase().trim();
                const fv = $('asgFilter').value;
                const tv = $('asgTypeFilter').value;
                const onlyEmpty = $('asgOnlyEmpty').checked;
                return asgUnits.filter(u => {
                    if (fv && asgSpecLabel(u) !== fv) return false;
                    if (tv && asgTypeLabel(u) !== tv) return false;
                    if (onlyEmpty && u.teacher_id) return false;
                    if (q && !asgUnitSearchMatch(u, q)) return false;
                    return true;
                });
            }

            function renderAsgTable() {
                const baseRows = asgFilteredScoped();
                asgNormalizeHeaderFilters(baseRows);
                const rows = baseRows.filter(unit => asgMatchesHeaderFilters(unit) && asgColMatch(unit));
                if (asgSel && !rows.includes(asgSel)) {
                    asgSel = null;
                    setAsgTeacherPanel(null);
                }
                $('asgCount').textContent = rows.length + ' ta';
                ensureAsgHead();
                let h = '';
                if (!rows.length) h += '<tr><td colspan="8" class="p-3 text-gray-400">Ma\'lumot topilmadi</td></tr>';
                rows.forEach((u, i) => {
                    const scopeLabel = asgScopeLabel(u);
                    const ttLabel = u.training_type === 'lecture'
                        ? '<span class="text-blue-600 font-semibold">Ma\'ruza</span>'
                        : '<span class="text-purple-600 font-semibold">Amaliy</span>';
                    const teacherLabel = u.teacher_mixed
                        ? '<span class="text-amber-600">⚠ turlicha</span>'
                        : (u.teacher_name ? esc(u.teacher_name) : '<span class="text-gray-400">— biriktirilmagan —</span>');
                    h += '<tr data-i="' + i + '"' + (asgSel === rows[i] ? ' class="sel"' : '') + '>' +
                        '<td>' + esc(u.subject_name) + '</td><td>' + asgSpecHtml(u) + '</td><td class="text-center">' + ttLabel + '</td>' +
                        (u.training_type === 'lecture' && (u.group_names || []).length
                            ? '<td title="' + esc(lectureLabel(u.oqim_label, u.group_names).title) + '">' + esc(lectureLabel(u.oqim_label, u.group_names).text.replace(/^Ma'ruza · /, '')) + '</td>'
                            : '<td>' + esc(scopeLabel) + '</td>') + '<td class="asg-kaf" title="' + esc(u.kafedra_name || '') + '">' + esc(u.kafedra_name || '—') + '</td>' +
                        '<td class="text-center">' + u.cards + (u.placed ? ' <span class="text-green-600">(' + u.placed + '✓)</span>' : '') + '</td>' +
                        '<td>' + teacherLabel + '</td>' +
                        '<td>' + (u.room_mixed ? '<span class="text-amber-600">⚠ turlicha</span>'
                            : (u.auditorium_name ? esc(u.auditorium_name) : '<span class="text-gray-400">—</span>')) + '</td></tr>';
                    return;
                    const sk = u.specialty_name + '·' + u.course;
                    if (sk !== lastSpec) {
                        h += '<tr class="asc-row-head"><td colspan="6">' + esc(u.specialty_name) + ' · ' + u.course + '-kurs</td></tr>';
                        lastSpec = sk;
                    }
                    const scope = u.training_type === 'lecture' ? (u.oqim_label || 'oqim') : (u.group_name || '');
                    const tt = u.training_type === 'lecture'
                        ? '<span class="text-blue-600 font-semibold">M</span>' : '<span class="text-purple-600 font-semibold">A</span>';
                    const teacher = u.teacher_mixed
                        ? '<span class="text-amber-600">⚠ turlicha</span>'
                        : (u.teacher_name ? esc(u.teacher_name) : '<span class="text-gray-400">— biriktirilmagan —</span>');
                    h += '<tr data-i="' + i + '"' + (asgSel === rows[i] ? ' class="sel"' : '') + '>' +
                        '<td>' + esc(u.subject_name) + '</td><td class="text-center">' + tt + '</td>' +
                        '<td>' + esc(scope) + '</td><td>' + esc(u.kafedra_name || '—') + '</td>' +
                        '<td class="text-center">' + u.cards + (u.placed ? ' <span class="text-green-600">(' + u.placed + '⚑)</span>' : '') + '</td>' +
                        '<td>' + teacher + '</td></tr>';
                });
                $('asgTable').tBodies[0].innerHTML = h;
                // Filtr qatori birinchi sarlavha ostida yopishib tursin
                const head = $('asgTable').tHead;
                const firstRowH = head.rows[0].offsetHeight;
                if (firstRowH) head.rows[1].querySelectorAll('th').forEach(th => th.style.top = firstRowH + 'px');
                const rowsRef = rows;
                $('asgTable').querySelectorAll('tbody tr[data-i]').forEach(tr => tr.onclick = () => {
                    asgSel = rowsRef[+tr.dataset.i];
                    $('asgTable').querySelectorAll('tbody tr').forEach(x => x.classList.remove('sel'));
                    tr.classList.add('sel');
                    selectAsgUnit();
                });
            }

            async function selectAsgUnit() {
                const u = asgSel;
                setAsgTeacherPanel(u);
                $('asgUnitInfo').innerHTML = '<b>' + esc(u.subject_name) + '</b><br>' +
                    '<span class="text-slate-600">' + asgSpecHtml(u) + '</span><br>' +
                    (u.training_type === 'lecture' ? '<span title="' + esc(lectureLabel(u.oqim_label, u.group_names).title) + '">'
                        + esc(lectureLabel(u.oqim_label, u.group_names).text) + '</span>' : 'Amaliy · ' + esc(u.group_name || '')) +
                    ' · ' + u.cards + ' karta' + (u.kafedra_name ? '<br><span class="text-gray-400">' + esc(u.kafedra_name) + '</span>' : '');
                renderAsgRoomCurrent();
                await Promise.all([loadAsgTeachers(''), loadAsgBusy(u)]);
                markAsgBusy();
            }

            // ----- Xona (auditoriya): ro'yxat alohida oynada, bir marta yuklanadi -----
            let asgRoomsList = null;
            function renderAsgRoomCurrent() {
                if (!asgSel) { $('asgRoomCurrent').textContent = '—'; return; }
                $('asgRoomCurrent').innerHTML = asgSel.room_mixed
                    ? '<span class="text-amber-600">⚠ kartalarda turlicha</span>'
                    : (asgSel.auditorium_name ? '<b class="text-slate-700">' + esc(asgSel.auditorium_name) + '</b>' + (roomInactive(asgSel.auditorium_code)
                        ? ' <span class="text-red-600 font-semibold" data-asg-room-off>(nofaol) — ' + esc(ROOM_OFF_TEXT) + '</span>' : '') : '<span class="text-slate-400">biriktirilmagan</span>');
            }
            async function openAsgRoomModal() {
                if (!asgSel) return;
                const forLec = asgSel.training_type === 'lecture' ? lectureLabel(asgSel.oqim_label, asgSel.group_names) : null;
                $('asgRoomFor').title = forLec ? forLec.title : '';
                $('asgRoomFor').textContent = asgSel.subject_name + ' · ' + (forLec ? forLec.text : 'Amaliy · ' + (asgSel.group_name || ''));
                $('asgRoomSearch').value = '';
                $('asgRoomList').innerHTML = '<div class="p-3 text-sm text-slate-400">Yuklanmoqda...</div>';
                $('asgRoomModal').classList.remove('hidden');
                if (!asgRoomsList) {
                    try {
                        asgRoomsList = (await api(AUDS_URL) || [])
                            .filter(room => room.active !== false)
                            .sort((a, b) => String(a.name || a.code || '').localeCompare(String(b.name || b.code || ''), undefined, { numeric: true }));
                    } catch (e) {
                        $('asgRoomList').innerHTML = '<div class="p-3 text-sm text-red-500">' + esc(e.message) + '</div>';
                        return;
                    }
                }
                renderAsgRooms();
                $('asgRoomSearch').focus();
            }
            function closeAsgRoomModal() { $('asgRoomModal').classList.add('hidden'); }
            // Xonalar: bo'shlari yaqinlik bo'yicha (server reytingi — odatdagi, o'qituvchiniki, kafedraniki, shu bino, sig'imi yaqin),
            // band xonalar oxirida (kulrang); reyting kelmagan bo'lsa — alifbo tartibi saqlanadi. Sabab — yashil yorliq.
            function asgRoomsSorted(list) {
                const order = (asgBusy.rank && asgBusy.rank.order) || [];
                const pos = {};
                order.forEach((code, i) => { pos[code] = i; });
                const at = (room, i) => (room.code in pos ? pos[room.code] : order.length + i);
                return list.map((room, i) => ({ room, i })).sort((a, b) =>
                    (asgBusy.rooms[a.room.code] ? 1 : 0) - (asgBusy.rooms[b.room.code] ? 1 : 0) || at(a.room, a.i) - at(b.room, b.i)).map(x => x.room);
            }
            function renderAsgRooms() {
                if (!asgSel || !asgRoomsList) return;
                const q = $('asgRoomSearch').value || '';
                const why = (asgBusy.rank && asgBusy.rank.why) || {};
                const list = asgRoomsSorted(asgRoomsList.filter(room => roomMatches(room, q)));
                // Sig'imdan oshadigan xona — aniq raqamlar (1.4, to'qnashuvlar oynasi bilan bitta formatlovchi — cfCapText): server matni
                // "Xona sig'maydi: 215 — 65 o'rin, 98 talaba (+33) — …"; sig'imi kiritilmagan — to'qnashuv emas.
                const caps = asgBusy.caps || {};
                $('asgRoomList').innerHTML = list.map(room =>
                    '<button type="button" class="rm-row' + (asgSel.auditorium_code === room.code ? ' is-current' : '') + '" data-code="' + esc(room.code) + '"' +
                    (asgBusy.rooms[room.code] ? ' style="opacity:.55" title="' + (String(asgBusy.rooms[room.code]).startsWith("Xona sig'maydi: ") ? '' : 'Band: ')
                        + esc(asgBusy.rooms[room.code]) + '"' : '') + '>' +
                    '<b>' + esc(room.name || room.code) + '</b>' +
                    '<span>' + esc([room.building_name, room.auditorium_type_name].filter(Boolean).join(' · ')) + '</span>' +
                    (why[room.code] && !asgBusy.rooms[room.code] ? '<span class="rm-why">' + esc(why[room.code]) + '</span>' : '') +
                    (caps[room.code] && asgBusy.rooms[room.code] ? '<span class="rm-cap">Xona sig\'maydi: ' + esc(cfCapText(caps[room.code])) + '</span>' : '') +
                    '<span class="rm-vol">' + (room.volume ? room.volume + ' o\'rin' : 'sig\'imi kiritilmagan') + '</span></button>').join('')
                    || '<div class="p-3 text-sm text-slate-400">Xona topilmadi</div>';
            }
            $('asgRoomOpen').onclick = () => openAsgRoomModal();
            $('asgRoomClear').onclick = () => applyAsgRoom(null);
            $('asgRoomSearch').oninput = () => renderAsgRooms();
            $('asgRoomModalClose').onclick = $('asgRoomCancel').onclick = () => closeAsgRoomModal();
            $('asgRoomModal').addEventListener('click', (ev) => {
                if (ev.target === ev.currentTarget || ev.target.classList.contains('tt-modal-body')) { closeAsgRoomModal(); return; }
                const row = ev.target.closest('.rm-row');
                if (row) applyAsgRoom(row.dataset.code);
            });

            async function applyAsgRoom(code, force) {
                if (!asgSel) return;
                $('asgRoomOpen').disabled = $('asgRoomClear').disabled = true;
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/assign-room', 'POST', Object.assign(asgUnitParams(asgSel), {
                        auditorium_code: code || '', force: force ? 1 : undefined,
                    }));
                    asgSel.auditorium_code = j.auditorium_code || null;
                    asgSel.auditorium_name = j.auditorium_name || null;
                    asgSel.room_mixed = false;
                    cards.forEach(c => {
                        const sameScope = asgSel.training_type === 'lecture'
                            ? (c.oqim_label === asgSel.oqim_label) : (c.group_name === asgSel.group_name);
                        if ((c.faculty_name || '') === (asgSel.faculty_name || '') && c.specialty_name === asgSel.specialty_name && c.course === asgSel.course &&
                            c.subject_name === asgSel.subject_name && c.training_type === asgSel.training_type && sameScope) {
                            c.auditorium_code = asgSel.auditorium_code; c.auditorium_name = asgSel.auditorium_name;
                        }
                    });
                    // Darsning o'z to'qnashuvlari (o'qituvchi / guruh band) xona biriktirishni to'smaydi — sariq ogohlantirish.
                    $('asgMsg').innerHTML = esc((j.auditorium_name ? '«' + j.auditorium_name + '» xonasi biriktirildi' : 'Xona olib tashlandi') +
                        ' · ' + j.affected + ' karta') + ((j.warnings || []).length ? '<div class="asg-room-warn" style="color:#b45309">⚠ Darsning o\u2018z to\u2018qnashuvi (hal qilish kerak): '
                        + (j.warnings || []).map(esc).join(' · ') + '</div>' : '');
                    renderAsgTable();
                    renderAsgRoomCurrent();
                    closeAsgRoomModal();
                    loadAsgBusy(asgSel).then(markAsgBusy);   // hozirgi xona o'zgardi — reyting (shu bino, odat) yangilanadi
                } catch (e) {
                    if (e.data && e.data.needs_confirm) {
                        // Xona band / sig'maydi / boshqa o'qituvchiniki — "Baribir biriktirish" (force); "Xona tanlash" oynasi ochiq bo'lsa —
                        // o'sha yerda ham. Tasdiq shu dars birligi uchun: boshqa birlik tanlangan bo'lsa — force'siz qayta tekshiriladi.
                        const unit = asgSel;
                        const force = () => applyAsgRoom(code, asgSel === unit);
                        showBusyConfirm($('asgMsg'), e.message, force, e.data.conflict_items);
                        if (!$('asgRoomModal').classList.contains('hidden')) showBusyConfirm($('asgRoomFor'), e.message, force, e.data.conflict_items);
                        $('asgRoomOpen').disabled = $('asgRoomClear').disabled = false;
                        return;
                    }
                    $('asgMsg').textContent = 'Xatolik: ' + e.message;
                    // Oyna ochiq bo'lsa xatoni shu yerda ham ko'rsatamiz
                    if (!$('asgRoomModal').classList.contains('hidden')) {
                        $('asgRoomFor').innerHTML = '<span class="text-red-600">Xatolik: ' + esc(e.message) + '</span>';
                    }
                }
                $('asgRoomOpen').disabled = $('asgRoomClear').disabled = false;
            }

            function setAsgTeacherPanel(u) {
                const on = !!u;
                ['asgTeacherSearch', 'asgTeacher', 'asgApply', 'asgClear', 'asgKafedraOnly',
                    'asgRoomOpen', 'asgRoomClear'].forEach(id => $(id).disabled = !on);
                if (!on) {
                    $('asgUnitInfo').textContent = '← Chapdan dars birligini tanlang';
                    $('asgTeacher').innerHTML = ''; $('asgTeacherSearch').value = '';
                    $('asgRoomCurrent').textContent = '—';
                }
            }

            async function loadAsgTeachers(search) {
                if (!asgSel) return;
                const p = new URLSearchParams();
                if ($('asgKafedraOnly').checked && asgSel.kafedra_name && !search) p.set('kafedra', asgSel.kafedra_name.split(' ')[0]);
                if (search) p.set('search', search);
                try {
                    const list = await api(TEACHERS_URL + '?' + p);
                    $('asgTeacher').innerHTML = list.map(t =>
                        '<option value="' + t.id + '"' + (asgSel.teacher_id === t.id ? ' selected' : '') + '>' +
                        esc(t.short_name || t.full_name) + (t.lavozim ? ' · ' + esc(t.lavozim) : '') + '</option>').join('')
                        || '<option disabled>topilmadi</option>';
                    markAsgBusy();
                } catch (e) { $('asgTeacher').innerHTML = '<option disabled>xato</option>'; }
            }
            $('asgTeacherSearch').oninput = function () {
                clearTimeout(asgTeacherTimer);
                asgTeacherTimer = setTimeout(() => loadAsgTeachers(this.value.trim()), 300);
            };
            $('asgKafedraOnly').onchange = () => loadAsgTeachers($('asgTeacherSearch').value.trim());

            $('asgApply').onclick = () => applyAsg($('asgTeacher').value || null);
            $('asgClear').onclick = () => applyAsg(null);

            async function applyAsg(teacherId, force) {
                if (!asgSel) return;
                $('asgApply').disabled = $('asgClear').disabled = true;
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/assign-teacher', 'POST', Object.assign(asgUnitParams(asgSel), {
                        teacher_id: teacherId || '', force: force ? 1 : undefined,
                    }));
                    // Mahalliy holatni yangilaymiz (birlik + tegishli kartalar)
                    asgSel.teacher_id = teacherId ? +teacherId : null;
                    asgSel.teacher_name = j.teacher_name;
                    asgSel.teacher_mixed = false;
                    cards.forEach(c => {
                        const sameScope = asgSel.training_type === 'lecture'
                            ? (c.oqim_label === asgSel.oqim_label) : (c.group_name === asgSel.group_name);
                        if ((c.faculty_name || '') === (asgSel.faculty_name || '') && c.specialty_name === asgSel.specialty_name && c.course === asgSel.course &&
                            c.subject_name === asgSel.subject_name && c.training_type === asgSel.training_type && sameScope) {
                            c.teacher_id = asgSel.teacher_id; c.teacher_name = j.teacher_name;
                        }
                    });
                    $('asgMsg').textContent = (j.teacher_name ? '«' + j.teacher_name + '» biriktirildi' : 'Biriktirish olib tashlandi') +
                        ' · ' + j.affected + ' karta';
                    renderAsgTable();
                    loadAsgBusy(asgSel).then(markAsgBusy);   // o'qituvchi o'zgardi — unga biriktirilgan xonalar reytingi yangilanadi
                } catch (e) {
                    // Tasdiq shu dars birligi uchun: boshqa birlik tanlangan bo'lsa — force'siz qayta tekshiriladi.
                    if (e.data && e.data.needs_confirm) {
                        const unit = asgSel;
                        showBusyConfirm($('asgMsg'), e.message, () => applyAsg(teacherId, asgSel === unit), e.data.conflict_items);
                    }
                    else $('asgMsg').textContent = 'Xatolik: ' + e.message;
                }
                $('asgApply').disabled = $('asgClear').disabled = false;
            }

            async function loadAsgAuditoriums() {
                if (!board) return;
                $('asgAudTable').innerHTML = '<tbody><tr><td class="p-3 text-gray-400">Yuklanmoqda...</td></tr></tbody>';
                try {
                    // Xonalar ma'lumotlar modalidagi Auditoriyalar tabida
                    // ishlatiladigan ayni endpointdan olinadi; assignmentlar ustiga birlashtiriladi.
                    const [rooms, assignments] = await Promise.all([
                        api(AUDS_URL),
                        api(BASE + '/boards/' + board.id + '/auditorium-teachers'),
                    ]);
                    const assignmentById = Object.fromEntries(
                        (assignments.auditoriums || []).map(room => [String(room.id), room])
                    );
                    asgAudRooms = (rooms || [])
                        .filter(room => room.active !== false)
                        .map(room => ({ ...room, ...(assignmentById[String(room.id)] || {}) }));
                    if (!asgAudDepartmentsLoaded) {
                        const departments = await api(TEACHER_DEPARTMENTS_URL);
                        const departmentOptions = departments
                            .map(d => '<option value="' + esc(d) + '">' + esc(d) + '</option>')
                            .join('');
                        $('asgAudDepartment').innerHTML = TIMETABLE_DEPARTMENT_HEAD
                            ? departmentOptions
                            : '<option value="">— barcha kafedralar —</option>' + departmentOptions;
                        if (TIMETABLE_DEPARTMENT_HEAD && departments.length) {
                            $('asgAudDepartment').value = departments[0];
                        }
                        asgAudDepartmentsLoaded = true;
                    }
                    renderAsgAudTable();
                    if (asgAudSel) selectAsgAudRoom(asgAudSel.id);
                } catch (e) {
                    asgAudRooms = [];
                    $('asgAudTable').innerHTML = '<tbody><tr><td class="p-3 text-red-500">' + esc(e.message) + '</td></tr></tbody>';
                }
            }

            function filteredAsgAudRooms() {
                const q = $('asgAudSearch').value || '';
                return asgAudRooms.filter(room => roomMatches(room, q));
            }

            function renderAsgAudTable() {
                const rows = filteredAsgAudRooms();
                $('asgAudCount').textContent = rows.length + ' ta';

                let h = '<colgroup><col style="width:16%"><col style="width:24%"><col style="width:9%">' +
                    '<col style="width:15%"><col style="width:16%"><col style="width:20%"></colgroup>';

                h += '<thead><tr><th>Xona</th><th>Bino</th><th class="text-center">Sig\'im</th>' +
                    '<th>Turi</th><th>Holat</th><th>O\'qituvchi</th></tr></thead><tbody>';

                rows.forEach((room, i) => {
                    const general = !!room.is_general;
                    const hasTeacher = !!room.teacher_id;
                    const capacity = room.volume ?? room.capacity ?? 0;
                    const unassignButton = room.assignment_id
                        ? '<button type="button" data-asg-aud-unassign="' + room.id + '" class="inline-flex items-center justify-center text-red-500 hover:text-red-700" title="Biriktirishni bekor qilish"><i class="bi bi-trash3" aria-hidden="true"></i></button>'
                        : '';
                    const status = room.active === false
                        ? '<span class="text-red-600 font-semibold">Faol emas</span>'
                        : (general
                            ? '<span class="inline-flex items-center gap-1">' + unassignButton + '<span class="aud-general">Umumiy</span></span>'
                            : (hasTeacher
                                ? '<span class="inline-flex items-center gap-1">' + unassignButton + '<span class="text-amber-600 font-semibold">Biriktirilgan</span></span>'
                                : '<span class="text-slate-400">Biriktirilmagan</span>'));
                    const teacher = general
                        ? '<span class="text-slate-400">Barcha o\'qituvchilar</span>'
                        : (hasTeacher ? '<span class="aud-teacher">' + esc(room.teacher_name || '—') + '</span>' : '<span class="text-slate-400">Tanlanmagan</span>');
                    h += '<tr data-i="' + i + '"' + (asgAudSel && asgAudSel.id === room.id ? ' class="sel"' : '') + '>' +
                        '<td class="font-semibold">' + esc(room.name || room.code) + '</td>' +
                        '<td>' + esc(room.building_name || '—') + '</td>' +
                        '<td class="text-center text-emerald-600 font-semibold">' + esc(String(capacity)) + '</td>' +
                        '<td>' + esc(room.auditorium_type_name || '—') + '</td>' +
                        '<td>' + status + '</td><td>' + teacher + '</td></tr>';
                });

                $('asgAudTable').innerHTML = h + '</tbody>';
                const rowsRef = rows;
                $('asgAudTable').querySelectorAll('tbody tr[data-i]').forEach(tr => tr.onclick = () => {
                    asgAudSel = rowsRef[+tr.dataset.i];
                    $('asgAudTable').querySelectorAll('tbody tr').forEach(row => row.classList.remove('sel'));
                    tr.classList.add('sel');
                    selectAsgAudRoom(asgAudSel.id);
                });
                $('asgAudTable').querySelectorAll('[data-asg-aud-unassign]').forEach(button => {
                    button.onclick = async event => {
                        event.preventDefault();
                        event.stopPropagation();

                        const room = asgAudRooms.find(item => +item.id === +button.dataset.asgAudUnassign);
                        if (!room || !confirm('«' + (room.name || room.code) + '» auditoriyasidagi biriktirishni bekor qilasizmi?')) return;

                        button.disabled = true;
                        try {
                            const result = await api(BASE + '/boards/' + board.id + '/auditorium-teachers/' + room.id, 'DELETE', {});
                            room.assignment_id = null;
                            room.teacher_id = null;
                            room.teacher_name = null;
                            room.is_general = false;
                            if (asgAudSel && +asgAudSel.id === +room.id) {
                                $('asgAudGeneral').checked = false;
                                $('asgAudTeacher').value = '';
                                applyAsgAudGeneralState();
                            }
                            $('asgMsg').textContent = result.message || 'Biriktirish bekor qilindi';
                            renderAsgAudTable();
                        } catch (e) {
                            $('asgMsg').textContent = 'Xatolik: ' + e.message;
                            button.disabled = false;
                        }
                    };
                });
            }

            function setAsgAudControls(on) {
                ['asgAudDepartment', 'asgAudTeacherSearch', 'asgAudTeacher', 'asgAudGeneral', 'asgAudApply', 'asgAudClear'].forEach(id => $(id).disabled = !on);
                if (!on) {
                    $('asgAudInfo').textContent = 'Chapdan auditoriyani tanlang';
                    $('asgAudTeacher').innerHTML = '';
                    $('asgAudTeacherSearch').value = '';
                    $('asgAudGeneral').checked = false;
                }
            }

            function applyAsgAudGeneralState() {
                const general = $('asgAudGeneral').checked;
                $('asgAudTeacher').disabled = !asgAudSel || general;
                $('asgAudTeacherSearch').disabled = !asgAudSel || general;
                $('asgAudDepartment').disabled = !asgAudSel || general || TIMETABLE_DEPARTMENT_HEAD;
            }

            async function selectAsgAudRoom(roomId) {
                asgAudSel = asgAudRooms.find(room => +room.id === +roomId) || null;
                setAsgAudControls(!!asgAudSel);
                if (!asgAudSel) return;
                $('asgAudInfo').innerHTML = '<b>' + esc(asgAudSel.name || asgAudSel.code) + '</b><br>' + esc(asgAudSel.building_name || 'Bino ko\'rsatilmagan') + ' · ' + (asgAudSel.volume || 0) + ' o\'rin';
                $('asgAudGeneral').checked = !!asgAudSel.is_general;
                applyAsgAudGeneralState();
                await loadAsgAudTeachers('');
                if (asgAudSel.teacher_id) $('asgAudTeacher').value = String(asgAudSel.teacher_id);
            }

            async function loadAsgAudTeachers(search) {
                if (!asgAudSel || $('asgAudGeneral').checked) return;
                const p = new URLSearchParams();
                if ($('asgAudDepartment').value) p.set('kafedra', $('asgAudDepartment').value);
                if (search) p.set('search', search);
                try {
                    const list = await api(TEACHERS_URL + '?' + p);
                    $('asgAudTeacher').innerHTML = list.map(t => '<option value="' + t.id + '">' + esc(t.short_name || t.full_name) + (t.lavozim ? ' · ' + esc(t.lavozim) : '') + '</option>').join('') || '<option disabled>topilmadi</option>';
                    if (asgAudSel?.teacher_id) $('asgAudTeacher').value = String(asgAudSel.teacher_id);
                } catch (e) { $('asgAudTeacher').innerHTML = '<option disabled>xato</option>'; }
            }

            $('asgAudSearch').oninput = () => renderAsgAudTable();
            $('asgAudDepartment').onchange = () => loadAsgAudTeachers($('asgAudTeacherSearch').value.trim());
            $('asgAudTeacherSearch').oninput = function () {
                clearTimeout(asgAudTeacherTimer);
                asgAudTeacherTimer = setTimeout(() => loadAsgAudTeachers(this.value.trim()), 300);
            };
            $('asgAudGeneral').onchange = () => {
                applyAsgAudGeneralState();
                if (!$('asgAudGeneral').checked) loadAsgAudTeachers('');
            };
            $('asgAudApply').onclick = () => saveAsgAudRoom(false);
            $('asgAudClear').onclick = () => saveAsgAudRoom(true);

            async function saveAsgAudRoom(forceGeneral) {
                if (!asgAudSel) return;
                const isGeneral = forceGeneral || $('asgAudGeneral').checked;
                const teacherId = isGeneral ? null : ($('asgAudTeacher').value || null);
                if (!isGeneral && !teacherId) {
                    $('asgMsg').textContent = 'Umumiy bo\'lmagan xona uchun o\'qituvchi tanlang';
                    return;
                }
                $('asgAudApply').disabled = $('asgAudClear').disabled = true;
                try {
                    const j = await api(BASE + '/boards/' + board.id + '/assign-auditorium-teacher', 'POST', {
                        auditorium_id: asgAudSel.id, teacher_id: teacherId || '', is_general: isGeneral ? 1 : 0,
                    });
                    asgAudSel.assignment_id = j.assignment_id;
                    asgAudSel.teacher_id = j.teacher_id;
                    asgAudSel.teacher_name = j.teacher_name;
                    asgAudSel.is_general = !!j.is_general;
                    $('asgAudGeneral').checked = asgAudSel.is_general;
                    applyAsgAudGeneralState();
                    renderAsgAudTable();
                    $('asgMsg').textContent = asgAudSel.is_general ? '«' + asgAudSel.name + '» umumiy xona qilindi' : '«' + asgAudSel.name + '» uchun o\'qituvchi biriktirildi';
                } catch (e) { $('asgMsg').textContent = 'Xatolik: ' + e.message; }
                $('asgAudApply').disabled = $('asgAudClear').disabled = false;
            }

            // ══════════════════════════════════════════════════════════════
            //  Tekshiruv (konflikt / oyna) hisoboti — client-side
            // ══════════════════════════════════════════════════════════════
            function computeDiagnostics() {
                const placed = cards.filter(c => c.day && c.pair);
                const dayName = i => (boardDayNames()[i - 1] || ('Kun ' + i));

                // 1) Joylashmagan kartalar — yo'nalish bo'yicha
                const unplacedBySpec = {};
                cards.filter(c => !c.day).forEach(c => {
                    const k = c.specialty_name + ' · ' + c.course + '-kurs';
                    unplacedBySpec[k] = (unplacedBySpec[k] || 0) + 1;
                });

                // 2/3) O'qituvchi va auditoriya konfliktlari (day|pair bo'yicha)
                const bySlot = {};
                placed.forEach(c => { (bySlot[c.day + '|' + c.pair] = bySlot[c.day + '|' + c.pair] || []).push(c); });
                const teacherConf = [], roomConf = [];
                Object.entries(bySlot).forEach(([slot, list]) => {
                    const [d, p] = slot.split('|').map(Number);
                    const byT = {}, byR = {};
                    list.forEach(c => {
                        if (c.teacher_id) (byT[c.teacher_id] = byT[c.teacher_id] || []).push(c);
                        if (c.auditorium_code) (byR[c.auditorium_code] = byR[c.auditorium_code] || []).push(c);
                    });
                    Object.values(byT).forEach(g => { if (g.length > 1) teacherConf.push({ d, p, name: g[0].teacher_name, subs: g.map(x => x.subject_name) }); });
                    Object.values(byR).forEach(g => { if (g.length > 1) roomConf.push({ d, p, name: g[0].auditorium_name, subs: g.map(x => x.subject_name) }); });
                });

                // 4) Guruh oynalari (oyna): guruh × kun ichida bo'sh paralar
                const gday = {};   // group|day => Set(pairs)
                placed.forEach(c => cardGroups(c).forEach(g => {
                    // Guruh kaliti bo'yicha — turli fakultetdagi bir xil nomli
                    // guruhlar bitta qatorga qo'shilib, soxta "oyna" bermasin.
                    const k = gkey(c, g) + '||' + c.day; (gday[k] = gday[k] || new Set()).add(c.pair);
                }));
                const gaps = [];
                Object.entries(gday).forEach(([k, set]) => {
                    const [gk, d] = k.split('||');
                    const g = gk.split('¦').pop();          // ko'rinadigan guruh nomi
                    const arr = [...set].sort((a, b) => a - b);
                    const hole = (arr[arr.length - 1] - arr[0] + 1) - arr.length;
                    if (hole > 0) gaps.push({ group: g, day: +d, holes: hole, pairs: arr });
                });
                gaps.sort((a, b) => b.holes - a.holes);

                // 5) O'qituvchisiz dars birliklari
                const unitTeacher = {};
                cards.forEach(c => {
                    const scope = c.training_type === 'lecture' ? ('L|' + c.oqim_label) : ('P|' + c.group_name);
                    const k = [c.specialty_name, c.course, c.subject_name, c.training_type, scope].join('¦');
                    if (!(k in unitTeacher)) unitTeacher[k] = { has: false, sub: c.subject_name, spec: c.specialty_name, course: c.course };
                    if (c.teacher_id) unitTeacher[k].has = true;
                });
                const noTeacher = Object.values(unitTeacher).filter(u => !u.has);

                const totalUnplaced = Object.values(unplacedBySpec).reduce((a, b) => a + b, 0);
                const issues = teacherConf.length + roomConf.length + gaps.length + missingGroups.length;
                return { unplacedBySpec, totalUnplaced, teacherConf, roomConf, gaps, noTeacher, missingGroups, issues, dayName };
            }

            function updateCheckBadge() {
                if (!board || !cards.length) { $('checkBadge').classList.add('hidden'); return; }
                const d = computeDiagnostics();
                const n = d.issues;
                if (n > 0) { $('checkBadge').textContent = n; $('checkBadge').classList.remove('hidden'); }
                else { $('checkBadge').classList.add('hidden'); }
            }

            $('checkBtn').onclick = () => { renderCheck(); $('checkModal').classList.remove('hidden'); };
            $('chkClose').onclick = () => $('checkModal').classList.add('hidden');

            function renderCheck() {
                const d = computeDiagnostics();
                const sec = (icon, title, count, ok, body) =>
                    '<section class="check-section ' + (count ? 'is-danger' : 'is-ok') + '">' +
                    '<div class="check-section-head">' +
                    '<span class="check-section-icon" aria-hidden="true">' + icon + '</span>' +
                    '<span class="check-section-title">' + title + '</span>' +
                    '<span class="check-section-count">' + (count ? count + ' ta' : '✓ ' + ok) + '</span>' +
                    '</div>' +
                    (count ? '<div class="check-section-body">' + body + '</div>' : '<div class="check-section-empty">' + ok + '</div>') +
                    '</section>';

                let h = '';
                // Rejada fani bor, lekin guruh proyeksiyasi yo'q — doskada umuman chiqmaydi
                if (d.missingGroups.length) {
                    h += sec('<i class="bi bi-people-fill"></i>', "Guruh proyeksiyasi topilmagan (rejada bor, doskada yo'q)", d.missingGroups.length, '',
                        '<div class="mb-1 text-gray-500">Bu yo\'nalish+kurslarda ishchi rejada fan bor, lekin tasdiqlangan guruh (oqim) proyeksiyasi yo\'q — shuning uchun kartochkalar yaratilmaydi va KURS ro\'yxatida ko\'rinmaydi. Yechim: shu yo\'nalish+kurs uchun guruh proyeksiyasini yaratib tasdiqlang, so\'ng doskani qayta yarating.</div>' +
                        d.missingGroups.map(m => '<div>• <b>' + esc(m.specialty_name) + '</b> · ' + m.course + '-kurs</div>').join(''));
                }
                // Joylashmagan
                h += sec('<i class="bi bi-pin-angle-fill"></i>', 'Joylashmagan darslar', d.totalUnplaced, 'hammasi joyida',
                    Object.entries(d.unplacedBySpec).map(([k, v]) => '<div>' + esc(k) + ' — <b>' + v + '</b> karta</div>').join(''));
                // O'qituvchi konflikti
                h += sec('<i class="bi bi-person-workspace"></i>', "O'qituvchi to'qnashuvlari", d.teacherConf.length, 'to\'qnashuv yo\'q',
                    d.teacherConf.map(c => '<div>' + esc(d.dayName(c.d)) + ', ' + c.p + '-para — <b>' + esc(c.name || '') + '</b>: ' + esc(c.subs.join(' / ')) + '</div>').join(''));
                // Auditoriya konflikti
                h += sec('<i class="bi bi-door-open"></i>', 'Auditoriya to\'qnashuvlari', d.roomConf.length, 'to\'qnashuv yo\'q',
                    d.roomConf.map(c => '<div>' + esc(d.dayName(c.d)) + ', ' + c.p + '-para — <b>' + esc(c.name || '') + '</b>: ' + esc(c.subs.join(' / ')) + '</div>').join(''));
                // Oynalar
                h += sec('<i class="bi bi-layout-three-columns"></i>', 'Guruh oynalari (bo\'sh para)', d.gaps.length, 'oyna yo\'q',
                    d.gaps.slice(0, 40).map(g => '<div>' + esc(g.group) + ' · ' + esc(d.dayName(g.day)) + ' — <b>' + g.holes + '</b> oyna (paralar: ' + g.pairs.join(',') + ')</div>').join('') +
                    (d.gaps.length > 40 ? '<div class="text-gray-400">... yana ' + (d.gaps.length - 40) + '</div>' : ''));
                // O'qituvchisiz
                h += sec('<i class="bi bi-person-question"></i>', 'O\'qituvchisi biriktirilmagan birliklar', d.noTeacher.length, 'hammasiga biriktirilgan',
                    d.noTeacher.slice(0, 40).map(u => '<div>' + esc(u.spec) + ' · ' + u.course + '-kurs — ' + esc(u.sub) + '</div>').join('') +
                    (d.noTeacher.length > 40 ? '<div class="text-gray-400">... yana ' + (d.noTeacher.length - 40) + '</div>' : ''));

                const okAll = !d.totalUnplaced && !d.issues && !d.noTeacher.length;
                $('chkBody').innerHTML = (okAll
                    ? '<div class="mb-3 p-3 rounded bg-green-50 text-green-700 text-sm font-semibold">✓ Jadval to\'liq va konfliktsiz.</div>' : '') + h;
            }

            // ===== Dars turi filtri (Hammasi / Ma'ruza / Amaliy) =====
            document.querySelectorAll('.tt-type').forEach(b => b.onclick = () => {
                setTypeFilter(b.dataset.type);
                if (selected && !typeVisible(selected)) selected = null;   // filtrga mos kelmasa tanlovni bekor qilamiz
                renderAll();
            });

            // URLdan doska ochish (F5 / havola) — tanlovlar ham URLdan tiklanadi (applyPendingView)
            // URLda doska bo'lmasa — o'qituvchi / fan mas'uli / kafedra mudiriga yagona yoki joriy Real doska (TIMETABLE_AUTO_BOARD_ID).
            // Avtomatik (URLsiz) ochilishda: oxirgi ochilgan doska (shu foydalanuvchi va rol, ro'yxatda bo'lsa), bo'lmasa server tanlagani;
            // hafta — joriy hafta.
            const explicitBoard = new URLSearchParams(location.search).get('board');
            let lastBoard = null;
            try { lastBoard = localStorage.getItem(LAST_BOARD_KEY); } catch (e) { }
            const lastBoardOk = lastBoard && [...$('boardSel').options].some(o => o.value === String(lastBoard));
            const autoBoard = !explicitBoard && TIMETABLE_AUTO_BOARD_ID ? (lastBoardOk ? String(lastBoard) : String(TIMETABLE_AUTO_BOARD_ID)) : null;
            const urlBoard = explicitBoard || autoBoard;
            const notificationRequest = new URLSearchParams(location.search).get('change_request');
            if (urlBoard) loadBoard(urlBoard).then(() => {
                if (autoBoard && !curWeek && board) {
                    curWeek = currentWeekNo(+curGrid().weeks || +board.weeks || 15);
                    fillWeekSel();
                    renderAll();
                }
                if (notificationRequest) openChangeReqModal();
            }).catch(e => {
                hideBoard();
                $('boardMsg').textContent = 'Doska ochilmadi: ' + e.message;
            });

        })();

        // Menyu va joylashmagan kartalar panelining balandligini sichqoncha bilan o'zgartirish:
        // ular kichraysa asosiy jadval (flex) shu hisobiga kengayadi. O'lcham shu brauzerda eslab qolinadi.
        (function () {
            const store = {
                get(k) { try { return JSON.parse(localStorage.getItem('tt-size-' + k)); } catch (e) { return null; } },
                set(k, v) { try { if (v === null) localStorage.removeItem('tt-size-' + k); else localStorage.setItem('tt-size-' + k, JSON.stringify(v)); } catch (e) { } },
            };
            const top = document.getElementById('ttTopArea');
            const panel = document.getElementById('cardPanel');
            const applyTop = h => {
                if (!top) return;
                if (h === null) { top.style.height = ''; top.style.overflow = ''; return; }
                top.style.height = h + 'px';
                top.style.overflow = 'auto';
            };
            const applyPanel = h => {
                if (!panel) return;
                if (h === null) { panel.style.maxHeight = '120px'; panel.style.height = ''; return; }
                panel.style.maxHeight = h + 'px';
                panel.style.height = h + 'px';
            };
            applyTop(store.get('top'));
            applyPanel(store.get('panel'));
            const drag = (handle, start, move, key) => {
                if (!handle) return;
                handle.addEventListener('pointerdown', ev => {
                    if (ev.button !== 0) return;
                    ev.preventDefault();
                    const y0 = ev.clientY, h0 = start();
                    let last = h0, moved = false;
                    handle.classList.add('dragging');
                    document.body.classList.add('tt-resizing');
                    handle.setPointerCapture(ev.pointerId);
                    // Oddiy bosish (yoki 1-2px titrash) o'lchamni qotirib qo'ymaydi — faqat haqiqiy surish eslab qolinadi.
                    const onMove = e => {
                        if (!moved && Math.abs(e.clientY - y0) < 3) return;
                        moved = true;
                        last = move(h0, e.clientY - y0);
                    };
                    const onUp = () => {
                        handle.classList.remove('dragging');
                        document.body.classList.remove('tt-resizing');
                        handle.removeEventListener('pointermove', onMove);
                        handle.removeEventListener('pointerup', onUp);
                        handle.removeEventListener('pointercancel', onUp);
                        if (moved) store.set(key, last === null ? null : Math.round(last));
                    };
                    handle.addEventListener('pointermove', onMove);
                    handle.addEventListener('pointerup', onUp);
                    handle.addEventListener('pointercancel', onUp);
                });
            };
            // Yuqori menyu: pastga sursangiz kattalashadi (tabiiy balandligidan oshmaydi), tepaga — kichrayadi.
            drag(document.getElementById('ttResizeTop'),
                () => top.getBoundingClientRect().height,
                (h0, dy) => {
                    const natural = top.scrollHeight;
                    const h = Math.max(0, Math.min(natural, h0 + dy));
                    // To'liq balandlik px bilan saqlanmaydi: menyu keyin kattalashsa ham skroll bilan kesilib qolmasin.
                    if (h >= natural - 1) { applyTop(null); return null; }
                    applyTop(h);
                    return h;
                }, 'top');
            // Joylashmagan kartalar: tepaga sursangiz kattalashadi, pastga — kichrayadi.
            drag(document.getElementById('ttResizeBottom'),
                () => panel.getBoundingClientRect().height,
                (h0, dy) => {
                    const h = Math.max(0, Math.min(window.innerHeight * 0.7, h0 - dy));
                    applyPanel(h);
                    return h;
                }, 'panel');
            const reset = (id, key, fn) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener('dblclick', () => { fn(null); store.set(key, null); });
            };
            reset('ttResizeTop', 'top', applyTop);
            reset('ttResizeBottom', 'panel', applyPanel);
        })();
    </script>
</x-app-layout>
